local ADDON, ns = ...

function ns.GetAddonVersion()
	local v = (C_AddOns and C_AddOns.GetAddOnMetadata and C_AddOns.GetAddOnMetadata(ADDON, "Version"))
		or (GetAddOnMetadata and GetAddOnMetadata(ADDON, "Version"))
	if type(v) ~= "string" then return "dev" end
	v = v:match("^%s*(.-)%s*$") or ""
	if v == "" or v == "@project-version@" or v:find("@project-version@", 1, true) then
		return "dev"
	end
	v = v:gsub("^[vV]", "")
	return v ~= "" and v or "dev"
end

