function app.invalidateRecipeStats(reason, itemIDs)
	if reason == "sellers" then return end
	if reason == "ownership" then
		app.ownershipRev = (app.ownershipRev or 0) + 1
		app._ownedCountsEpoch = (app._ownedCountsEpoch or 0) + 1
		app._shoppingSyncSig = nil
	end
	if reason ~= "ownership" then app.profSolveRev = (app.profSolveRev or 0) + 1 end
	if app.uiPriceBank and (reason == "skills" or reason == "professions" or reason == "known" or reason == "rep") then
		app.uiPriceBank.candidates = {}
		if reason ~= "rep" then app.uiPriceBank.craftOpt, app.uiPriceBank.smartCraft = {}, {} end
	end
	if reason == "items" then
		ns.InvalidateEvalCrafts(app.uiPriceBank)
		for key, value in pairs(itemIDs or {}) do
			local id = type(value) == "number" and value or (value and key)
			if type(id) == "number" and id > 0 then
				ns.InvalidateEvalItem(app.uiPriceBank, id)
				if ns._evalCache and ns._evalCache ~= app.uiPriceBank then
					ns.InvalidateEvalItem(ns._evalCache, id)
				end
			end
		end
		if ns._evalCache and ns._evalCache ~= app.uiPriceBank then
			ns.InvalidateEvalCrafts(ns._evalCache)
		end
		app._detachedCraftShopSig = nil
	end
	if (reason == "skills" or reason == "professions" or reason == "known" or reason == "rep" or reason == "items") and ns.InvalidateCrateTooltipCache then
		ns.InvalidateCrateTooltipCache()
	end
	if ns.RecipeStats then ns.RecipeStats.Invalidate(reason, itemIDs)
	else
		app.recipeStatsRevision = (app.recipeStatsRevision or 0) + 1
		if app.vendorCrafterProvider and app.vendorCrafterProvider.Invalidate then
			app.vendorCrafterProvider.Invalidate(reason, itemIDs)
		end
		if app.disenchantCrafterProvider and app.disenchantCrafterProvider.Invalidate then
			app.disenchantCrafterProvider.Invalidate(reason, itemIDs)
		end
		if app.allItemsProvider and app.allItemsProvider.Invalidate then
			app.allItemsProvider.Invalidate(reason, itemIDs)
		end
		if app.watchlistProvider and app.watchlistProvider.Invalidate then
			app.watchlistProvider.Invalidate(reason, itemIDs)
		end
	end
end

function app.bindRecipeStatsInvalidation()
	if app.recipeInvalidationBound or not ns.RecipeStats then return end
	app.recipeInvalidationBound = true
	local invalidate = ns.RecipeStats.Invalidate
	ns.RecipeStats.Invalidate = function(reason, itemIDs)
		invalidate(reason, itemIDs)
		if app.superListProvider and app.superListProvider.Invalidate then app.superListProvider.Invalidate(reason, itemIDs) end
		if app.vendorCrafterProvider and app.vendorCrafterProvider.Invalidate then app.vendorCrafterProvider.Invalidate(reason, itemIDs) end
		if app.disenchantCrafterProvider and app.disenchantCrafterProvider.Invalidate then app.disenchantCrafterProvider.Invalidate(reason, itemIDs) end
		if app.allItemsProvider and app.allItemsProvider.Invalidate then app.allItemsProvider.Invalidate(reason, itemIDs) end
		if app.watchlistProvider and app.watchlistProvider.Invalidate then app.watchlistProvider.Invalidate(reason, itemIDs) end
		local wantsRefresh = (app.activeTab == "recipes" or app.activeTab == "vendor_crafter" or app.activeTab == "disenchant_crafter" or app.activeTab == "watchlist")
			or (app.activeTab == "all_items" and (reason == nil or reason == "ownership" or reason == "prices" or reason == "items" or reason == "snapshot"))
		if wantsRefresh and app.scheduleRecipeRefresh then app.scheduleRecipeRefresh(reason) end
	end
end

