local function isAutoOpenAtAHDisabled()
	if not MerchantMasterDB then return false end
	if MerchantMasterDB.autoOpenAtAH == false then return true end
	return MerchantMasterDB.hideWithAH == true
end

local function setAutoOpenAtAHDisabled(disabled)
	if not MerchantMasterDB then return end
	local off = disabled and true or false
	MerchantMasterDB.hideWithAH = off
	MerchantMasterDB.autoOpenAtAH = not off
	if app.ui and app.ui.hideWithAH then app.ui.hideWithAH:SetChecked(off) end
	if app.ui and app.ui.dashOnboardNoAutoOpenCheck then app.ui.dashOnboardNoAutoOpenCheck:SetChecked(off) end
	if app.consoleProvider and app.consoleProvider.SyncSettings then app.consoleProvider.SyncSettings() end
end

local function getActiveLiveScanTs(db)
	if not db then return nil end
	local econInfo = ns.CurrentEconomyInfo and ns.CurrentEconomyInfo() or nil
	local econKey = econInfo and econInfo.effectiveKey
	local ahPool = db.ahPrices and econKey and db.ahPrices[econKey]
	local ts = (type(ahPool) == "table" and type(ahPool._scannedAt) == "number" and ahPool._scannedAt > 0) and ahPool._scannedAt or nil
	if (not ts) and econInfo and econInfo.isActive and type(db.lastRefreshAt) == "number" and db.lastRefreshAt > 0 then
		ts = db.lastRefreshAt
	end
	return ts
end

function app.shouldShowOnboarding()
	local db = MerchantMasterDB
	if db and db.onboardingDismissed == true then return false end
	if ns.HasSnapshots and ns.HasSnapshots() then return false end
	if getActiveLiveScanTs(db) ~= nil then return false end
	return true
end

local function learnCrateIcon(icon)
	if not icon or not MerchantMasterDB or MerchantMasterDB.crateIcon == icon then return end
	MerchantMasterDB.crateIcon = icon
end

local cachedFavorMarkup = nil
local function favorIconMarkup(knownIconID)
	if cachedFavorMarkup then return cachedFavorMarkup end
	if knownIconID then
		cachedFavorMarkup = "|T" .. knownIconID .. ":12:12:1:0|t"
		return cachedFavorMarkup
	end
	if C_CurrencyInfo and C_CurrencyInfo.GetCurrencyInfo then
		local ok, info = pcall(C_CurrencyInfo.GetCurrencyInfo, ns.FAVOR_CURRENCY_ID)
		if ok and info and info.iconFileID then
			cachedFavorMarkup = "|T" .. info.iconFileID .. ":12:12:1:0|t"
			return cachedFavorMarkup
		end
	end
	return ""
end

local function atAH()
	return (AuctionHouseFrame and AuctionHouseFrame:IsShown()) or (AuctionFrame and AuctionFrame:IsShown()) or false
end

