-- Bags, Bank, Mail & Alt Inventory Counting + TradeSkill Recipe Scanner

function app.getBagContainers()
	local bags, seen = {}, {}
	local function add(id)
		if type(id) == "number" and not seen[id] then
			seen[id] = true
			bags[#bags + 1] = id
		end
	end
	local numBags = tonumber(_G.NUM_BAG_SLOTS) or 4
	local numTotal = tonumber(_G.NUM_TOTAL_EQUIPPED_BAG_SLOTS) or 0
	local enumIdx = _G.Enum and _G.Enum.BagIndex
	local reagentBag = enumIdx and tonumber(enumIdx.ReagentBag) or nil
	local enumBankBag1 = enumIdx and tonumber(enumIdx.BankBag_1) or nil
	local hasCharTabs = enumIdx and tonumber(enumIdx.CharacterBankTab_1) ~= nil
	for bag = 0, numBags do add(bag) end
	if reagentBag ~= nil and reagentBag > numBags and (enumBankBag1 == nil or reagentBag ~= enumBankBag1) then
		local slots = (C_Container and C_Container.GetContainerNumSlots and C_Container.GetContainerNumSlots(reagentBag))
			or (GetContainerNumSlots and GetContainerNumSlots(reagentBag)) or 0
		if numTotal > numBags or hasCharTabs or slots > 0 then
			add(reagentBag)
		end
	end
	return bags
end

function app.getBankContainers()
	local bank, seen = {}, {}
	local function add(id)
		if type(id) == "number" and not seen[id] then
			seen[id] = true
			bank[#bank + 1] = id
		end
	end
	local numBags = tonumber(_G.NUM_BAG_SLOTS) or 4
	local numTotal = tonumber(_G.NUM_TOTAL_EQUIPPED_BAG_SLOTS) or 0
	local enumIdx = _G.Enum and _G.Enum.BagIndex
	local reagentBag = enumIdx and tonumber(enumIdx.ReagentBag) or nil
	local enumBankBag1 = enumIdx and tonumber(enumIdx.BankBag_1) or nil
	local hasCharTabs = enumIdx and tonumber(enumIdx.CharacterBankTab_1) ~= nil
	local hasReagentBag = reagentBag ~= nil and reagentBag > numBags and (enumBankBag1 == nil or reagentBag ~= enumBankBag1)
		and (numTotal > numBags or hasCharTabs)
	if hasCharTabs then
		if enumIdx and tonumber(enumIdx.Bank) and tonumber(enumIdx.Bank) ~= reagentBag then
			add(tonumber(enumIdx.Bank))
		end
		for ti = 1, 9 do
			local tabId = enumIdx and tonumber(enumIdx["CharacterBankTab_" .. ti]) or nil
			if tabId and tabId ~= reagentBag then add(tabId) end
		end
		return bank
	end
	add(-1)
	if enumIdx and tonumber(enumIdx.Bank) then add(tonumber(enumIdx.Bank)) end
	local reagentBankID = (enumIdx and tonumber(enumIdx.Reagentbank)) or -3
	local reagentUnlocked = true
	if type(_G.IsReagentBankUnlocked) == "function" then
		local ok, unlocked = pcall(_G.IsReagentBankUnlocked)
		reagentUnlocked = ok and unlocked == true
	end
	if reagentUnlocked then add(reagentBankID) end
	local firstBankBag = enumBankBag1 or (hasReagentBag and (reagentBag + 1) or (numBags + 1))
	local bankSlots = tonumber(_G.NUM_BANKBAGSLOTS) or 7
	for bag = firstBankBag, firstBankBag + bankSlots - 1 do
		if not (hasReagentBag and bag == reagentBag) then
			add(bag)
		end
	end
	return bank
end

local BAGS, BANK = app.getBagContainers(), app.getBankContainers()

local function forEachBagItem(fn, containers)
	for _, bag in ipairs(containers or app.getBagContainers()) do
		local slots = C_Container and C_Container.GetContainerNumSlots and C_Container.GetContainerNumSlots(bag)
			or (GetContainerNumSlots and GetContainerNumSlots(bag)) or 0
		for slot = 1, slots do
			local link, stack, icon, isBound, itemID
			if C_Container and C_Container.GetContainerItemInfo then
				local info = C_Container.GetContainerItemInfo(bag, slot)
				if info then link, stack, icon, isBound, itemID = info.hyperlink, info.stackCount, info.iconFileID, info.isBound == true, tonumber(info.itemID) end
			elseif GetContainerItemInfo then
				local tex, count, _, _, _, _, l, _, _, id, bound = GetContainerItemInfo(bag, slot)
				link, stack, icon, isBound, itemID = l, count, tex, bound == true, tonumber(id)
			end
			if link or (itemID and itemID > 0) then fn(bag, slot, link, stack or 1, icon, isBound, itemID) end
		end
	end
end

local function learnID(name, link)
	local id = link and tonumber(link:match("item:(%d+)"))
	if name and id then
		app.itemIDs[name] = id
		ns.ITEM_IDS_BY_NAME[name] = id
	end
end

local function lookupID(name)
	if not name then return nil end
	if app.itemIDs[name] then return app.itemIDs[name] end
	if ns.ITEM_IDS_BY_NAME[name] then
		app.itemIDs[name] = ns.ITEM_IDS_BY_NAME[name]
		return app.itemIDs[name]
	end
	local id = C_Item and C_Item.GetItemInfoInstant and C_Item.GetItemInfoInstant(name)
		or (GetItemInfoInstant and GetItemInfoInstant(name))
	if id then app.itemIDs[name] = id end
	return id
end

app.bagsDirty = true
app.bagCountsDirty = true
app.cachedBagCounts = nil
app.cachedBoundBags = nil
app.cachedBagCrates = nil

local function copyCountsTable(src)
	local out = {}
	if src then
		for k, v in pairs(src) do out[k] = v end
	end
	return out
end

local function bagCounts(containers)
	if containers == nil and not app.bagCountsDirty and app.cachedBagCounts then
		if app.char and app.cachedBoundBags then
			app.char.boundBags = copyCountsTable(app.cachedBoundBags)
		end
		return copyCountsTable(app.cachedBagCounts)
	end
	local counts, boundCounts, countsByID = {}, {}, {}
	forEachBagItem(function(_, _, link, stack, _, isBound, itemID)
		local name = link and link:match("%[(.-)%]")
		local id = (itemID and itemID > 0 and itemID) or (link and tonumber(link:match("item:(%d+)")))
		if not name and id and id > 0 and ns.ItemName then
			name = ns.ItemName(id)
		end
		if name then
			counts[name] = (counts[name] or 0) + stack
			if isBound then
				boundCounts[name] = (boundCounts[name] or 0) + stack
			end
			if link then learnID(name, link) end
		end
		if (not id or id <= 0) and name then id = lookupID(name) end
		if id and id > 0 then
			countsByID[id] = (countsByID[id] or 0) + stack
		end
	end, containers)
	if containers == nil then
		app.cachedBagCounts = counts
		app.cachedBagCountsByID = countsByID
		app.cachedBoundBags = boundCounts
		app.bagCountsDirty = false
		if app.char then
			app.char.boundBags = copyCountsTable(boundCounts)
		end
		return copyCountsTable(counts)
	end
	return counts, boundCounts
end

local function getForeverPlayerName()
	if ns.GetPlayerFullName then
		return ns.GetPlayerFullName()
	end
	local first = (UnitName and UnitName("player")) or "Player"
	if type(first) ~= "string" or first == "" then first = "Player" end
	local splitFirst = first:match("^([^%s]+)%s+")
	return first, (type(splitFirst) == "string" and splitFirst ~= "") and splitFirst or first
end
app.getForeverPlayerName = getForeverPlayerName

local function markSeenChar(seen, c)
	if type(c) ~= "table" or type(c.name) ~= "string" then return end
	local normRealm = (_G.GetNormalizedRealmName and _G.GetNormalizedRealmName()) or nil
	local function addVariant(nm)
		if type(nm) ~= "string" or nm == "" then return end
		seen[nm:lower()] = true
		if type(c.realm) == "string" and c.realm ~= "" then
			seen[(nm .. "-" .. c.realm):lower()] = true
		end
		if type(normRealm) == "string" and normRealm ~= "" then
			seen[(nm .. "-" .. normRealm):lower()] = true
		end
	end
	addVariant(c.name)
	if c == app.char then
		if type(c.firstName) == "string" and c.firstName ~= "" then
			addVariant(c.firstName)
		end
		local firstWord = c.name:match("^([^%s]+)%s+")
		if type(firstWord) == "string" and firstWord ~= "" then
			addVariant(firstWord)
		end
	end
end

local function alts()
	local list = {}
	if not (MerchantMasterDB and MerchantMasterDB.chars) then return list end
	local cur = app.char
	local curGuid = cur and cur.guid or nil
	local curFirst = nil
	if cur then
		if type(cur.firstName) == "string" and cur.firstName ~= "" and cur.name ~= cur.firstName then
			curFirst = cur.firstName
		elseif type(cur.name) == "string" then
			curFirst = cur.name:match("^([^%s]+)%s+")
		end
	end
	local curFirstLow = (type(curFirst) == "string" and curFirst ~= "") and curFirst:lower() or nil
	for key, c in pairs(MerchantMasterDB.chars) do
		if key ~= app.charKey and type(c) == "table" then
			local isSelfGuid = (curGuid ~= nil and c.guid ~= nil and c.guid == curGuid)
			local sameScope = (c.economy == cur.economy) or (c.realm == cur.realm and c.faction == cur.faction)
			local isStaleSelfFirst = (curFirstLow ~= nil and type(c.name) == "string" and c.name:lower() == curFirstLow
				and sameScope and (c.guid == nil or curGuid == nil or c.guid == curGuid))
			if not isSelfGuid and not isStaleSelfFirst then
				if c.economy == cur.economy then
					list[#list + 1] = c
				elseif not c.economy and c.realm == cur.realm and c.faction == cur.faction then
					list[#list + 1] = c
				end
			end
		end
	end
	return list
end
app.getAlts = alts

local function mailCount(name)
	return (app.char.mail and app.char.mail[name]) or 0
end

local function bankCount(name)
	return (app.char.bank and app.char.bank[name]) or 0
end

local function altCount(name)
	local n = 0
	for _, c in ipairs(alts()) do
		n = n + ((c.bags or {})[name] or 0)
		if MerchantMasterDB and MerchantMasterDB.includeMail then
			n = n + ((c.mail or {})[name] or 0)
		end
		if MerchantMasterDB and MerchantMasterDB.includeBank then
			n = n + ((c.bank or {})[name] or 0)
		end
	end
	return n
end

local function ownedCounts()
	local rev = app.ownershipRev or 0
	if app._cachedOwnedCounts and app._cachedOwnedCountsRev == rev then return app._cachedOwnedCounts end
	local counts = {}
	for name, qty in pairs(bagCounts()) do counts[name] = qty end
	local function add(from)
		for name, n in pairs(from or {}) do
			if (n or 0) > 0 then
				counts[name] = (counts[name] or 0) + n
			end
		end
	end
	local function addChar(c, withBags)
		if withBags then add(c.bags) end
		if MerchantMasterDB and MerchantMasterDB.includeMail then
			add(c.mail)
		end
		if MerchantMasterDB and MerchantMasterDB.includeBank then
			add(c.bank)
		end
	end
	addChar(app.char, false)
	if MerchantMasterDB and MerchantMasterDB.includeAlts then
		for _, c in ipairs(alts()) do addChar(c, true) end
	end
	app._cachedOwnedCounts, app._cachedOwnedCountsRev = counts, rev
	return counts
end

local function ownedCountsByID()
	local rev = app.ownershipRev or 0
	if app._cachedOwnedCountsByID and app._cachedOwnedCountsByIDRev == rev then
		return app._cachedOwnedCountsByID
	end
	local byID = {}
	local bags = bagCounts()
	if app.cachedBagCountsByID then
		for id, qty in pairs(app.cachedBagCountsByID) do
			if id > 0 and qty > 0 then byID[id] = (byID[id] or 0) + qty end
		end
	else
		for name, qty in pairs(bags) do
			local id = lookupID(name)
			if id and id > 0 and qty > 0 then byID[id] = (byID[id] or 0) + qty end
		end
	end
	local function addByName(from)
		for name, n in pairs(from or {}) do
			local id = lookupID(name)
			if id and id > 0 then
				local qty = tonumber(n) or 0
				if qty > 0 then
					byID[id] = (byID[id] or 0) + qty
				end
			end
		end
	end
	local function addCharByID(c, withBags)
		if not c then return end
		if withBags then addByName(c.bags) end
		if MerchantMasterDB and MerchantMasterDB.includeMail then
			addByName(c.mail)
		end
		if MerchantMasterDB and MerchantMasterDB.includeBank then
			addByName(c.bank)
		end
	end
	addCharByID(app.char, false)
	if MerchantMasterDB and MerchantMasterDB.includeAlts then
		for _, c in ipairs(alts()) do addCharByID(c, true) end
	end
	app._cachedOwnedCountsByID, app._cachedOwnedCountsByIDRev = byID, rev
	return byID
end

function app.getBagCountByID(itemID)
	local id = tonumber(itemID)
	if not id or id <= 0 then return 0 end
	if app.bagCountsDirty or not app.cachedBagCountsByID then
		bagCounts()
	end
	return (app.cachedBagCountsByID and app.cachedBagCountsByID[id]) or 0
end

function app.getItemOwnershipBreakdown(itemID, name)
	local id = tonumber(itemID)
	local itemName = (type(name) == "string" and name ~= "") and name or (id and ns.ItemName and ns.ItemName(id)) or nil
	if (not id or id <= 0) and itemName then
		id = lookupID(itemName)
	end
	local bags = 0
	if id and id > 0 then
		bags = app.getBagCountByID(id)
	elseif itemName then
		local bc = bagCounts()
		bags = (bc and bc[itemName]) or 0
	end
	local db = MerchantMasterDB
	local bank, mail = 0, 0
	if not db or db.includeBank ~= false then
		if itemName then
			bank = bankCount(itemName)
		end
	end
	if not db or db.includeMail ~= false then
		if itemName then
			mail = mailCount(itemName)
		end
	end
	local altEntries = {}
	if db and db.includeAlts then
		local seen = {}
		markSeenChar(seen, app.char)
		for _, c in ipairs(alts()) do
			markSeenChar(seen, c)
			if itemName then
				local bq = (c.bags and c.bags[itemName]) or 0
				if bq > 0 then altEntries[#altEntries + 1] = { name = c.name or "Alt", location = "Bags", qty = bq } end
				if db.includeBank ~= false then
					local bkq = (c.bank and c.bank[itemName]) or 0
					if bkq > 0 then altEntries[#altEntries + 1] = { name = c.name or "Alt", location = "Bank", qty = bkq } end
				end
				if db.includeMail ~= false then
					local mq = (c.mail and c.mail[itemName]) or 0
					if mq > 0 then altEntries[#altEntries + 1] = { name = c.name or "Alt", location = "Mail", qty = mq } end
				end
			end
		end
	end
	return { bags = math.max(0, bags), bank = math.max(0, bank), mail = math.max(0, mail), alts = altEntries }
end

local function sameCounts(a,b)
    for key,value in pairs(a or {}) do if value~=((b or {})[key] or 0) then return false end end
    for key,value in pairs(b or {}) do if value~=((a or {})[key] or 0) then return false end end
    return true
end
local function sameProfKeys(a,b)
    for key in pairs(a or {}) do if not (b and b[key]) then return false end end
    for key in pairs(b or {}) do if not (a and a[key]) then return false end end
    return true
end
function app.CommitMailboxSnapshot(snapshot)
    if not snapshot or not snapshot.names or not app.char then return false end
    local prior=app.char.mail or {}
    local priorItems=app.mailboxItems
    if not priorItems then
        priorItems={}
        for name,qty in pairs(prior) do local id=app.itemIDs[name]; if id then priorItems[id]=(priorItems[id] or 0)+qty end end
    end
    local changed=not sameCounts(prior,snapshot.names) or not sameCounts(priorItems,snapshot.items)
    app.mailboxItems=snapshot.items
    app.char.mail=snapshot.names; app.char.bought={}
    for name,id in pairs(snapshot.itemIDs or {}) do app.itemIDs[name]=id end
    local analytics=ns.Analytics
    if analytics and analytics.Inventory then
        local _,arrived=analytics.Inventory.AcceptMailboxSnapshot(snapshot)
        analytics.Inventory.ReceiveTransitMail(app.charKey,arrived)
    end
    if changed then
        app.invalidateRecipeStats("ownership")
        if ns.MapPins and ns.MapPins.InvalidateOwnership then ns.MapPins.InvalidateOwnership() end
        if app.scheduleRecipeRefresh then app.scheduleRecipeRefresh() end
    end
    if analytics and analytics.Capture and analytics.Capture.MailboxSnapshotCommitted then analytics.Capture.MailboxSnapshotCommitted() end
    return changed
end
local function readMailboxOwnership(allowEmpty)
    if not _G.GetInboxNumItems or not _G.GetInboxHeaderInfo or not _G.GetInboxItem then return end
    local count,total=_G.GetInboxNumItems()
    local function secret(v)
        return (_G.issecretvalue and _G.issecretvalue(v)) or (type(v)=="table" and _G.issecrettable and _G.issecrettable(v))
    end
    if secret(count) or secret(total) or count==nil then return end
    count=tonumber(count)
    if not count or count<0 or count%1~=0 or (count==0 and (not allowEmpty or (tonumber(total) or 0)>0)) then return end
    local snapshot={names={},items={},itemIDs={}}
    local maxAtt=tonumber(_G.ATTACHMENTS_MAX_RECEIVE) or 12
    for index=1,count do
        local _,_,_,subject,_,_,_,hasItem=_G.GetInboxHeaderInfo(index)
        if secret(subject) or secret(hasItem) or subject==nil or subject==_G.RETRIEVING_DATA then return end
        local declared=tonumber(hasItem)
        local loaded=0
        for slot=1,maxAtt do
            local name,id,_,qty=_G.GetInboxItem(index,slot)
            local link=_G.GetInboxItemLink and _G.GetInboxItemLink(index,slot)
            if secret(name) or secret(id) or secret(qty) or secret(link) then return end
            id=tonumber(id) or (type(link)=="string" and tonumber(link:match("item:(%d+)")))
            if name or (id and (hasItem==true or (tonumber(hasItem) or 0)>0)) then
                if not id or not name or name==_G.RETRIEVING_DATA then return end
                loaded=loaded+1
                qty=tonumber(qty) or 1
                snapshot.items[id]=(snapshot.items[id] or 0)+qty
                snapshot.names[name]=(snapshot.names[name] or 0)+qty
                snapshot.itemIDs[name]=id
            end
        end
        if (declared and loaded~=declared) or (hasItem==true and loaded==0) then return end
    end
    return snapshot
end
function app.QueueMailboxScan(reason)
    if not app.atMailbox or (reason~="open" and reason~="take") then return end
    if ns.MailHelper and ns.MailHelper.IsActive and ns.MailHelper.IsActive() then return end
    local request=app.mailboxScanPending
    if request then
        if reason=="take" then
            request.actionPending=true; request.inboxReady=false; request.attempt=0; request.schedule()
        end
        return
    end
    local token=app.mailboxSession
    request={attempt=0,actionPending=reason=="take",inboxReady=false}; app.mailboxScanPending=request
    local function schedule()
        request.generation=(request.generation or 0)+1
        local generation=request.generation
        C_Timer.After(1,function()
            if app.mailboxSession~=token or not app.atMailbox or app.mailboxScanPending~=request or request.generation~=generation then return end
            if ns.MailHelper and ns.MailHelper.IsActive and ns.MailHelper.IsActive() then app.mailboxScanPending=nil; return end
            request.attempt=request.attempt+1
            local capture=ns.Analytics and ns.Analytics.Capture
            local snapshot=capture and capture.ScanMailboxSnapshot and capture.ScanMailboxSnapshot(request.inboxReady or reason=="take")
            if type(snapshot)~="table" then
                snapshot=readMailboxOwnership(request.inboxReady or reason=="take" or not (app.char and next(app.char.mail or {})))
            end
            if snapshot and (not request.actionPending or request.inboxReady) then
                app.mailboxScanPending=nil; app.CommitMailboxSnapshot(snapshot)
            elseif request.attempt<3 then
                schedule()
            elseif not request.actionPending then
                app.mailboxScanPending=nil
            end
        end)
    end
    request.schedule=schedule
    schedule()
end
local function hookMailboxTake(name)
    if type(_G[name])~="function" then return end
    if hooksecurefunc then
        hooksecurefunc(name,function()
            if app.atMailbox then app.QueueMailboxScan("take") end
        end)
    else
        local original=_G[name]
        _G[name]=function(...)
            if app.atMailbox then app.QueueMailboxScan("take") end
            return original(...)
        end
    end
end
for _,name in ipairs({"TakeInboxMoney","AutoLootMailItem","TakeInboxItem"}) do hookMailboxTake(name) end

local function scanBank()
	local counts, boundCounts = bagCounts(app.getBankContainers())
	local changed = not sameCounts(app.char.bank, counts)
	if changed then app.ownershipRev = (app.ownershipRev or 0) + 1 end
	app.char.bank = counts
	app.char.boundBank = boundCounts
	return changed
end

local function scanGear()
	if not GetInventoryItemLink then return end
	local gear = {}
	for slot = 1, 19 do
		local ok, link = pcall(GetInventoryItemLink, "player", slot)
		if ok and type(link) == "string" then
			local name = link:match("%[(.-)%]")
			if name then
				gear[name] = (gear[name] or 0) + 1
				learnID(name, link)
			end
		end
	end
	if app.char then
		app.char.gear = gear
		app.ownershipRev = (app.ownershipRev or 0) + 1
	end
	return gear
end
app.scanGear = scanGear

local function matchProfKeyByName(profName)
	if type(profName) ~= "string" or profName == "" then return nil end
	local low = profName:lower()
	for _, p in ipairs(ns.PROFESSIONS) do
		if p.full and p.full:lower() == low then return p.key end
	end
	return nil
end

local function getCatalogSpellMap()
	if ns._catalogBySpell then return ns._catalogBySpell end
	local map = {}
	local function addEntry(spellID, prof, skill, outID, name, reqName)
		if not spellID or spellID <= 0 then return end
		local entry = map[spellID]
		if not entry then
			entry = { prof = prof, skill = skill, outIDs = {}, names = {} }
			map[spellID] = entry
		else
			if not entry.prof and prof then entry.prof = prof end
			if not entry.skill and skill then entry.skill = skill end
		end
		if outID and outID > 0 then entry.outIDs[outID] = true end
		if type(name) == "string" and name ~= "" then entry.names[name:lower()] = true end
		if type(reqName) == "string" and reqName ~= "" then entry.names[reqName:lower()] = true end
	end
	for _, r in ipairs(ns.RECIPES or {}) do
		addEntry(r.spellID, r.prof, r.skill, r.outputItemID, r.name, nil)
	end
	for _, w in ipairs(ns.WRITS or {}) do
		addEntry(w.spellID, w.prof, w.skill, w.requiredItemID, w.name, w.requiredItemName)
	end
	if ns.MP and ns.MP.RECIPES then
		for pk, list in pairs(ns.MP.RECIPES) do
			for _, m in ipairs(list) do
				local estSkill = (m.y and m.y > 50) and (m.y - 50) or nil
				addEntry(m.s, pk, estSkill, m.i, m.n, nil)
			end
		end
	end
	ns._catalogBySpell = map
	return map
end

local function rebuildKnownDerivedFromSpells(ch)
	if not ch then return end
	ch.knownOutputs = ch.knownOutputs or {}
	ch.knownNames = ch.knownNames or {}
	wipe(ch.knownOutputs)
	wipe(ch.knownNames)
	local catMap = getCatalogSpellMap()
	for spID, flag in pairs(ch.knownSpells or {}) do
		if flag == true then
			local entry = catMap[spID]
			if entry then
				for oid in pairs(entry.outIDs) do ch.knownOutputs[oid] = true end
				for nm in pairs(entry.names) do ch.knownNames[nm] = true end
			end
		end
	end
end

local function syncActiveCharProfs()
	local ch = app.char
	if type(ch) ~= "table" then return end
	local liveMap = ns.GetLivePlayerProfessions and ns.GetLivePlayerProfessions()
		or (ns.GetPlayerProfessions and ns.GetPlayerProfessions()) or {}
	if next(liveMap) == nil then return end
	ch.profs = ch.profs or {}
	for k in pairs(ch.profs) do
		if not liveMap[k] then ch.profs[k] = nil end
	end
	for k, v in pairs(liveMap) do
		ch.profs[k] = v
	end
end

local function sanitizeKnownRecipes(ch)
	if not ch or not MerchantMasterDB then return false end
	ch.knownSpells = ch.knownSpells or {}
	ch.knownOutputs = ch.knownOutputs or {}
	ch.knownNames = ch.knownNames or {}
	ch.scannedProfs = ch.scannedProfs or {}

	local catMap = getCatalogSpellMap()
	local profMap = (ns.GetLivePlayerProfessions and ns.GetLivePlayerProfessions()) or (ns.GetPlayerProfessions and ns.GetPlayerProfessions()) or {}
	local hasAnyProf = next(profMap) ~= nil
	local mpDB = ns.GetProfessorDB and ns.GetProfessorDB() or _G.MerchantProfessorDB
	local mpCharKey = (ns.MP and ns.MP.GetCharKey) and ns.MP.GetCharKey() or nil
	local mpCharSpells = (mpDB and mpDB.knownSpells and mpCharKey) and mpDB.knownSpells[mpCharKey] or nil
	local changed = false

	if ch.knownScanVersion ~= 2 then
		for spID in pairs(ch.knownSpells) do
			local ent = catMap[spID]
			if ent and hasAnyProf and ent.prof and ns.PROF_BY_KEY[ent.prof] then
				local rank = profMap[ent.prof]
				if not rank or (ent.skill and ent.skill > (rank + 15)) then
					ch.knownSpells[spID] = nil
				end
			end
		end
		if mpCharSpells then
			for spID in pairs(mpCharSpells) do
				local ent = catMap[spID]
				if ent and hasAnyProf and ent.prof and ns.PROF_BY_KEY[ent.prof] then
					local rank = profMap[ent.prof]
					if not rank or (ent.skill and ent.skill > (rank + 15)) then
						mpCharSpells[spID] = nil
					end
				end
			end
		end
		for pk in pairs(ch.scannedProfs) do
			if hasAnyProf and ns.PROF_BY_KEY[pk] and not profMap[pk] then
				ch.scannedProfs[pk] = nil
			end
		end
		rebuildKnownDerivedFromSpells(ch)
		ch.knownScanVersion = 2
		changed = true
	end

	if hasAnyProf then
		local pruned = false
		for spID in pairs(ch.knownSpells) do
			local ent = catMap[spID]
			if ent and ent.prof and ns.PROF_BY_KEY[ent.prof] and not profMap[ent.prof] then
				ch.knownSpells[spID] = nil
				pruned = true
			end
		end
		if mpCharSpells then
			for spID in pairs(mpCharSpells) do
				local ent = catMap[spID]
				if ent and ent.prof and ns.PROF_BY_KEY[ent.prof] and not profMap[ent.prof] then
					mpCharSpells[spID] = nil
					pruned = true
				end
			end
		end
		for pk in pairs(ch.scannedProfs) do
			if ns.PROF_BY_KEY[pk] and not profMap[pk] then
				ch.scannedProfs[pk] = nil
				pruned = true
			end
		end
		if pruned then
			rebuildKnownDerivedFromSpells(ch)
			changed = true
		end
	end

	if changed then
		if ns.ResetEval then ns.ResetEval() end
		app.invalidateRecipeStats("known")
	end
	return changed
end

local function scanTradeSkillWindow()
	if not MerchantMasterDB then return false end
	if ns.IsForeignTradeSkill and ns.IsForeignTradeSkill() then return false end
	MerchantMasterDB.knownSpells = MerchantMasterDB.knownSpells or {}
	local knownChanged, skillsChanged = false, false
	local function readable(v)
		return not ((_G.issecretvalue and _G.issecretvalue(v)) or (type(v) == "table" and _G.issecrettable and _G.issecrettable(v)))
	end
	local function mark(map, key, skill)
		if map and readable(key) and key ~= nil and not map[key] then
			map[key] = true
			if skill then skillsChanged = true else knownChanged = true end
		end
	end
	local function unmark(map, key)
		if map and readable(key) and key ~= nil and map[key] ~= nil then
			map[key] = nil
			knownChanged = true
			return true
		end
		return false
	end
	local ch = app.char
	if ch then
		ch.knownSpells = ch.knownSpells or {}
		ch.knownOutputs = ch.knownOutputs or {}
		ch.knownNames = ch.knownNames or {}
		ch.scannedProfs = ch.scannedProfs or {}
	end
	local profMap = (ns.GetLivePlayerProfessions and ns.GetLivePlayerProfessions()) or (ns.GetPlayerProfessions and ns.GetPlayerProfessions()) or {}
	local hasAnyProf = next(profMap) ~= nil
	local mpDB = ns.GetProfessorDB and ns.GetProfessorDB() or _G.MerchantProfessorDB
	local mpCharKey = (ns.MP and ns.MP.GetCharKey) and ns.MP.GetCharKey() or nil
	local mpCharSpells = (mpDB and mpDB.knownSpells and mpCharKey) and mpDB.knownSpells[mpCharKey] or nil

	-- 1. Retail / Forever 16001 C_TradeSkillUI
	local usedModernAPI, removedSpell = false, false
	if C_TradeSkillUI and C_TradeSkillUI.GetAllRecipeIDs and C_TradeSkillUI.GetRecipeInfo then
		local openPkey, winRank = nil, nil
		if C_TradeSkillUI.GetBaseProfessionInfo then
			local pok, pinfo = pcall(C_TradeSkillUI.GetBaseProfessionInfo)
			if pok and readable(pinfo) and type(pinfo) == "table" then
				openPkey = (readable(pinfo.professionID) and pinfo.professionID and ns.PROF_BY_SKILLLINE[pinfo.professionID])
					or (readable(pinfo.professionName) and matchProfKeyByName(pinfo.professionName))
				winRank = (readable(pinfo.skillLevel) and type(pinfo.skillLevel) == "number" and pinfo.skillLevel > 0) and pinfo.skillLevel or nil
			end
		end
		if openPkey and hasAnyProf and (not profMap[openPkey] or (winRank and winRank > profMap[openPkey] + 15)) then
			return false
		end
		local ok, ids = pcall(C_TradeSkillUI.GetAllRecipeIDs)
		if ok and readable(ids) and type(ids) == "table" and #ids > 0 then
			local infos, anyLearnedFlag = {}, false
			for _, id in ipairs(ids) do
				if readable(id) then
					local iok, info = pcall(C_TradeSkillUI.GetRecipeInfo, id)
					if iok and readable(info) and type(info) == "table" then
						infos[id] = info
						if readable(info.learned) and info.learned ~= nil then
							anyLearnedFlag = true
						end
					end
				end
			end
			if anyLearnedFlag then
				usedModernAPI = true
				if ch and openPkey then mark(ch.scannedProfs, openPkey, true) end
				for _, id in ipairs(ids) do
					local info = infos[id]
					if info and readable(info.learned) then
						if info.learned == true then
							if ch then
								mark(ch.knownSpells, id)
								if readable(info.name) and type(info.name) == "string" and info.name ~= "" then
									mark(ch.knownNames, info.name:lower())
								end
								if C_TradeSkillUI.GetRecipeOutputItemData then
									local ook, odata = pcall(C_TradeSkillUI.GetRecipeOutputItemData, id)
									if ook and readable(odata) and type(odata) == "table" and readable(odata.itemID) and odata.itemID then
										mark(ch.knownOutputs, odata.itemID)
									end
								end
								if ns.RecordRecipeYieldRange and C_TradeSkillUI.GetRecipeSchematic then
									local sok, sch = pcall(C_TradeSkillUI.GetRecipeSchematic, id, false)
									if sok and readable(sch) and type(sch) == "table" and readable(sch.quantityMin) and readable(sch.quantityMax) then
										local qMin = tonumber(sch.quantityMin)
										local qMax = tonumber(sch.quantityMax or qMin)
										if qMin and qMin > 0 and qMax and qMax >= qMin and ns.RecordRecipeYieldRange(id, qMin, qMax) then
											knownChanged = true
										end
									end
								end
							end
						elseif info.learned == false then
							if unmark(ch and ch.knownSpells, id) then removedSpell = true end
							unmark(MerchantMasterDB.knownSpells, id)
							unmark(mpCharSpells, id)
						end
					end
				end
				if removedSpell and ch then
					rebuildKnownDerivedFromSpells(ch)
				end
			end
		end
	end

	-- 2. Classic TradeSkillFrame API (only when C_TradeSkillUI did not provide learned flags)
	if not usedModernAPI and GetNumTradeSkills and GetTradeSkillInfo then
		local pkey, winRank = nil, nil
		if GetTradeSkillLine then
			local lok, lineName, lineRank = pcall(GetTradeSkillLine)
			pkey = lok and readable(lineName) and matchProfKeyByName(lineName) or nil
			winRank = (lok and readable(lineRank) and type(lineRank) == "number" and lineRank > 0) and lineRank or nil
		end
		local allowClassic = not hasAnyProf or (pkey ~= nil and profMap[pkey] ~= nil and (not winRank or winRank <= profMap[pkey] + 15))
		if allowClassic then
			local ok, num = pcall(GetNumTradeSkills)
			if ok and readable(num) and type(num) == "number" and num > 0 then
				if ch and pkey then mark(ch.scannedProfs, pkey, true) end
				local seenActiveGroup = {}
				for i = 1, num do
					local iok, skillName, skillType = pcall(GetTradeSkillInfo, i)
					if iok and readable(skillName) and readable(skillType) and type(skillName) == "string" and skillType ~= "header" and skillType ~= "subheader" then
						if ch then
							mark(ch.knownNames, skillName:lower())
							if GetTradeSkillItemLink then
								local _, ilink = pcall(GetTradeSkillItemLink, i)
								local outID = readable(ilink) and type(ilink) == "string" and tonumber(ilink:match("item:(%d+)")) or nil
								if outID then mark(ch.knownOutputs, outID) end
							end
							if GetTradeSkillRecipeLink then
								local _, rlink = pcall(GetTradeSkillRecipeLink, i)
								local spID = readable(rlink) and type(rlink) == "string" and tonumber(rlink:match("enchant:(%d+)") or rlink:match("spell:(%d+)")) or nil
								if spID then
									mark(ch.knownSpells, spID)
									if ns.RecordRecipeYieldRange and GetTradeSkillNumMade then
										local mok, minM, maxM = pcall(GetTradeSkillNumMade, i)
										if mok and readable(minM) and readable(maxM) then
											local nMin = tonumber(minM)
											local nMax = tonumber(maxM or minM)
											if nMin and nMin > 0 and ns.RecordRecipeYieldRange(spID, nMin, nMax or nMin) then
												knownChanged = true
											end
										end
									end
									if ns.SyncLiveRecipeReagents and GetTradeSkillNumReagents and GetTradeSkillReagentItemLink and GetTradeSkillReagentInfo then
										local rok, nRg = pcall(GetTradeSkillNumReagents, i)
										if rok and readable(nRg) and type(nRg) == "number" and nRg > 0 then
											local liveRg = {}
											local allOk = true
											for rIdx = 1, nRg do
												local lok, rgLink = pcall(GetTradeSkillReagentItemLink, i, rIdx)
												local qok, _, _, rgQty = pcall(GetTradeSkillReagentInfo, i, rIdx)
												local rgID = lok and readable(rgLink) and type(rgLink) == "string" and tonumber(rgLink:match("item:(%d+)")) or nil
												local qtyNum = qok and readable(rgQty) and tonumber(rgQty) or nil
												if rgID and rgID > 0 and qtyNum and qtyNum > 0 then
													liveRg[#liveRg + 1] = { rgID, qtyNum }
												else
													allOk = false
													break
												end
											end
											if allOk and #liveRg > 0 and ns.SyncLiveRecipeReagents(spID, liveRg, app.uiPriceBank) then
												knownChanged = true
											end
										end
									end
									if GetTradeSkillCooldown then
										local cok, cdRem = pcall(GetTradeSkillCooldown, i)
										if cok and readable(cdRem) and type(cdRem) == "number" then
											local grp = ns.GetRecipeCooldownGroup and ns.GetRecipeCooldownGroup(
												(ns.MP and ns.MP.RECIPES_BY_SPELL and ns.MP.RECIPES_BY_SPELL[spID]) or { spellID = spID }
											)
											ch.cooldowns = ch.cooldowns or {}
											if grp then ch.cooldownGroups = ch.cooldownGroups or {} end
											if cdRem > 1.5 then
												local exp = time() + math.ceil(cdRem)
												ch.cooldowns[spID] = exp
												if grp then
													seenActiveGroup[grp] = true
													if grp == "alchemy_transmute" and ns.RebuildSharedTransmuteCooldownGroup then
														ns.RebuildSharedTransmuteCooldownGroup(ch, time())
													else
														ch.cooldownGroups[grp] = math.max(tonumber(ch.cooldownGroups[grp]) or 0, exp)
													end
												end
											else
												if ch.cooldowns[spID] then ch.cooldowns[spID] = nil end
												if grp == "alchemy_transmute" and ns.RebuildSharedTransmuteCooldownGroup then
													ns.RebuildSharedTransmuteCooldownGroup(ch, time())
												elseif grp and ch.cooldownGroups and ch.cooldownGroups[grp] and not seenActiveGroup[grp] then
													local activeSibling = false
													for activeID, expiration in pairs(ch.cooldowns) do
														local activeRecipe = (ns.MP and ns.MP.RECIPES_BY_SPELL and ns.MP.RECIPES_BY_SPELL[tonumber(activeID)]) or { spellID = tonumber(activeID) }
														if readable(expiration) and (tonumber(expiration) or 0) > time() and ns.GetRecipeCooldownGroup(activeRecipe) == grp then
															activeSibling = true
															break
														end
													end
													if not activeSibling then ch.cooldownGroups[grp] = nil end
												end
											end
										end
									end
								end
							end
						end
					end
				end
			end
		end
	end

	-- 3. Classic Enchanting CraftFrame API
	if not usedModernAPI and GetNumCrafts and GetCraftInfo and (not hasAnyProf or profMap.enchanting) then
		local ok, num = pcall(GetNumCrafts)
		if ok and readable(num) and type(num) == "number" and num > 0 then
			if ch then mark(ch.scannedProfs, "enchanting", true) end
			for i = 1, num do
				local iok, craftName, _, craftType = pcall(GetCraftInfo, i)
				if iok and readable(craftName) and readable(craftType) and type(craftName) == "string" and craftType ~= "header" then
					if ch then
						mark(ch.knownNames, craftName:lower())
						if GetCraftItemLink then
							local _, clink = pcall(GetCraftItemLink, i)
							local spID = readable(clink) and type(clink) == "string" and tonumber(clink:match("enchant:(%d+)") or clink:match("spell:(%d+)")) or nil
							if spID then
								mark(ch.knownSpells, spID)
							end
						end
					end
				end
			end
		end
	end
	if not sameCounts(app._lastPlayerProfMap, profMap) then skillsChanged = true end
	app._lastPlayerProfMap = profMap
	syncActiveCharProfs()
	if skillsChanged or knownChanged then
		if ns.ResetEval then ns.ResetEval() end
	end
	if skillsChanged then app.invalidateRecipeStats("skills") end
	if knownChanged then app.invalidateRecipeStats("known") end
	return skillsChanged or knownChanged
end

if C_AuctionHouse and C_AuctionHouse.ConfirmCommoditiesPurchase and hooksecurefunc then
	hooksecurefunc(C_AuctionHouse, "ConfirmCommoditiesPurchase", function(itemID, quantity)
		local name = ns.ItemName(itemID)
		if name then
			app.purchase = { name = name, quantity = quantity, before = bagCounts()[name] or 0 }
		end
		if app.cartBuyer and app.cartBuyer.OnCommodityPurchaseConfirmed then
			app.cartBuyer.OnCommodityPurchaseConfirmed(itemID, quantity)
		end
	end)
end

