-- Waylaid Crates in Player's Bags + Tooltip Enhancer

local BUNDLE_LINE = "^%s*%-%s*(%d+)%s*[xX]?%s+(.-)%s*$"
local function parseBundles(text, out)
	for line in (text .. "\n"):gmatch("(.-)\r?\n") do
		line = line:gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", "")
		local n, name = line:match(BUNDLE_LINE)
		if n then out[#out + 1] = { count = tonumber(n), name = name } end
	end
	return out
end

local bagScanner = CreateFrame("GameTooltip", ADDON .. "Scanner", UIParent, "GameTooltipTemplate")
bagScanner:SetOwner(UIParent, "ANCHOR_NONE")

local function tooltipBundles(tooltip)
	local bundles = {}
	local gname = tooltip:GetName()
	if not gname then return bundles end
	local prefix = gname .. "TextLeft"
	for i = 1, tooltip:NumLines() do
		local fs = _G[prefix .. i]
		local text = fs and fs:GetText()
		if text then parseBundles(text, bundles) end
	end
	return bundles
end

local function bagCrates()
	if not app.bagsDirty and app.cachedBagCrates then
		return app.cachedBagCrates
	end
	-- Refresh bag counts alongside crates when counts were marked dirty so both caches stay synchronized
	if app.bagCountsDirty then
		bagCounts()
	end
	local crates, seen = {}, {}
	forEachBagItem(function(bag, slot, link, _, icon)
		local itemID = tonumber(link:match("item:(%d+)"))
		local isCandidate = (itemID and ns.CRATE_BY_ID and ns.CRATE_BY_ID[itemID] ~= nil)
			or (link:find("Waylaid", 1, true) ~= nil)
		if isCandidate then
			local name = link:match("%[(.-)%]")
			if name and not seen[name] then
				bagScanner:SetOwner(UIParent, "ANCHOR_NONE")
				bagScanner:ClearLines()
				bagScanner:SetBagItem(bag, slot)
				local bundles = tooltipBundles(bagScanner)
				if #bundles > 0 then
					seen[name] = true
					crates[#crates + 1] = { name = name, link = link, icon = icon, bundles = bundles }
					learnCrateIcon(icon)
				end
			end
		end
	end)
	table.sort(crates, function(a, b) return a.name < b.name end)
	app.cachedBagCrates = crates
	app.bagsDirty = false
	return crates
end

local function lotsPrice(lots, whole, qty)
	local remaining, cost = qty, 0
	for _, lot in ipairs(lots) do
		if remaining <= 0 then break end
		if whole then
			cost = cost + lot.price
			remaining = remaining - lot.n
		else
			local take = math.min(remaining, lot.n)
			cost = cost + take * lot.price
			remaining = remaining - take
		end
	end
	return remaining < qty and cost or nil, remaining > 0 and remaining or nil
end

local function lotsFor(lots, qty)
	local kept, n = {}, 0
	for _, lot in ipairs(lots) do
		if n >= qty then break end
		kept[#kept + 1] = lot
		n = n + lot.n
	end
	return kept
end

local function rankBundles(bundles, counts, crateName)
	local ranked = {}
	local scanned = crateName and app.costs[crateName]
	for _, b in ipairs(bundles) do
		local have = counts[b.name] or 0
		local missing = math.max(0, b.count - have)
		local price = scanned and scanned[b.name]
		if price and price.qty ~= missing then
			if price.lots and missing > 0 and (missing < price.qty or price.short) then
				local cost, short = lotsPrice(price.lots, price.whole, missing)
				price = { qty = missing, cost = cost, short = short, at = price.at }
			else
				price = nil
			end
		end
		ranked[#ranked + 1] = { name = b.name, count = b.count, have = have, missing = missing, price = price }
	end
	local function tier(b)
		if b.missing == 0 then return 0 end
		if b.price and b.price.cost and not b.price.short then return 1 end
		return 2
	end
	table.sort(ranked, function(a, b)
		if scanned then
			local ta, tb = tier(a), tier(b)
			if ta ~= tb then return ta < tb end
			if ta == 1 and a.price.cost ~= b.price.cost then return a.price.cost < b.price.cost end
		end
		local ra, rb = a.missing / a.count, b.missing / b.count
		if ra ~= rb then return ra < rb end
		return a.name < b.name
	end)
	return ranked
end

local function missingFor(name)
	local counts, total = ownedCounts(), 0
	for _, crate in ipairs(bagCrates()) do
		local best = rankBundles(crate.bundles, counts, crate.name)[1]
		if best and best.name == name then total = total + best.missing end
	end
	return total
end

local function bundleText(b)
	local text = string.format("%d/%d %s", math.min(b.have, b.count), b.count, b.name)
	local where = {}
	local mail = MerchantMasterDB and MerchantMasterDB.includeMail and mailCount(b.name) or 0
	local bank = MerchantMasterDB and MerchantMasterDB.includeBank and bankCount(b.name) or 0
	if mail > 0 then where[#where + 1] = string.format("%d in mail", mail) end
	if bank > 0 then where[#where + 1] = string.format("%d in bank", bank) end
	local onAlts = MerchantMasterDB and MerchantMasterDB.includeAlts and altCount(b.name) or 0
	if onAlts > 0 then where[#where + 1] = string.format("%d on alts", onAlts) end
	if #where > 0 then
		text = text .. " |cff9d9d9d(" .. table.concat(where, ", ") .. ")|r"
	end
	return text
end

