local seenCrateTooltip = setmetatable({}, { __mode = "k" })
local clearHookedCrateTooltip = setmetatable({}, { __mode = "k" })
local seenEconTooltip = setmetatable({}, { __mode = "k" })
local clearHookedEconTooltip = setmetatable({}, { __mode = "k" })
local suppressCratePostCall = false

