local function formatComma(n)
	local num = math.floor((tonumber(n) or 0) + 0.5)
	local s = tostring(num)
	while true do
		local nextStr, k = s:gsub("^(-?%d+)(%d%d%d)", "%1,%2")
		s = nextStr
		if k == 0 then break end
	end
	return s
end

local function applySafeFont(fs, size, weight)
	if not fs then return end
	if ns.Theme and ns.Theme.ApplyFont then
		ns.Theme.ApplyFont(fs, size, weight)
	elseif ns.Theme and ns.Theme.SetFont then
		ns.Theme.SetFont(fs, size, "")
	end
end

local function getPal()
	local active = ns.Theme and ns.Theme.GetActivePalette and ns.Theme.GetActivePalette()
	if active then return active end
	if ns.Theme and ns.Theme.PALETTES and ns.Theme.GetMode then
		local p = ns.Theme.PALETTES[ns.Theme.GetMode()]
		if p then return p end
	end
	return (ns.Theme and (ns.Theme.PALETTE or ns.Theme.COLORS)) or {}
end

local function palHex(key, fb)
	local p = getPal()
	return "|cff" .. tostring((p and p[key]) or fb or "ffffff")
end

local function formatRepColumnCell(data)
	if (tonumber(data and data.reqRep) or 0) > 0 then
		local color = data.repMet == false and "hexDanger" or "hexPositive"
		return palHex(color, data.repMet == false and "ff453a" or "30d158") .. tostring(data.repLabel or "Rep") .. "|r"
	end
	return palHex("hexMuted", "98989d") .. "-|r"
end

local function addRecipeRepTooltipLine(row)
	if (tonumber(row and row.reqRep) or 0) > 0 then
		local met = row.repMet ~= false
		local faction = row.repFactionName and (tostring(row.repFactionName) .. " - ") or ""
		GameTooltip:AddDoubleLine("Reputation Required:", faction .. tostring(row.repLabel or "") .. (met and " (Met)" or " (Required)"), 0.85, 0.85, 0.85, met and 0.25 or 1.0, met and 0.95 or 0.35, met and 0.45 or 0.35)
	else
		GameTooltip:AddDoubleLine("Reputation Required:", "None", 0.85, 0.85, 0.85, 0.65, 0.65, 0.65)
	end
end

-- Every legacy hardcoded |cff hex (and the other appearance's palette) -> active palette ink.
