	return ns.Theme.ThemeText(str)
end

-- Themed zero-money literals ("0g" / "0c") with the metallic unit colour of the active appearance
local function zeroMoney(unit)
	if ns.Theme and ns.Theme.GetPriceDisplayMode and ns.Theme.GetPriceDisplayMode() ~= "compact" then
		return ns.FormatMoneyCompact(0)
	end
	local unitKey = (unit == "g" and "hexGold") or (unit == "s" and "hexSilver") or "hexCopper"
	return palHex("hexText") .. "0|r" .. palHex(unitKey) .. (unit or "c") .. "|r"
end

