-- UI Theme (skin) switcher: Modern Glass + 5 Warcraft skins. Gear popover button, Blizzard
-- Options button, /mm theme and MerchantMasterAPI.SetSkin all funnel through app.applyUiSkin.
local function uiSkinShortLabel()
	local T = ns.Theme
	local info = T and T.GetSkinInfo and T.GetSkinInfo(T.GetSkin and T.GetSkin() or "goblin")
	return (info and info.short) or "Goblin"
end

local function updateUiSkinButton(button)
	if button then button:SetText("UI Theme: " .. uiSkinShortLabel()) end
end

-- Pushes the active skin into every control that mirrors it (idempotent, no Theme.SetSkin call).
function app.syncUiSkinWidgets()
	updateUiSkinButton(app.ui.uiSkinBtn)
	updateUiSkinButton(app.ui.optUiSkinBtn)
	if app.ui.optSlashFs and app.buildSlashHelp then app.ui.optSlashFs:SetText(app.buildSlashHelp()) end
	if app.refreshSkinLayout then app.refreshSkinLayout() end
	if app.consoleProvider and app.consoleProvider.SyncSettings then app.consoleProvider.SyncSettings() end
end

function app.applyUiSkin(skinKey)
	local T = ns.Theme
	if not (T and T.SetSkin) then return "goblin" end
	if not (T.IsValidSkin and T.IsValidSkin(skinKey)) then skinKey = "goblin" end
	if MerchantMasterDB then MerchantMasterDB.uiSkin = skinKey end
	app._skinSwitching = true
	local ok, err = pcall(T.SetSkin, skinKey)
	app._skinSwitching = nil
	if not ok and geterrorhandler then geterrorhandler()(err) end
	if MerchantMasterDB then MerchantMasterDB.uiSkin = T.GetSkin() end
	return T.GetSkin()
end

if ns.Theme and ns.Theme.OnSkinChanged then
	ns.Theme.OnSkinChanged(function(skinKey, _, changed)
		if MerchantMasterDB then MerchantMasterDB.uiSkin = skinKey end
		app.syncUiSkinWidgets()
		if not changed then return end
		if panel:IsShown() and app.refresh then
			app.refresh()
		elseif app.ui.appearanceSwitch and app.ui.appearanceSwitch.UpdateTheme then
			app.ui.appearanceSwitch:UpdateTheme()
		end
	end)
end

