function app.applyTableStyle(styleKey)
	local T = ns.Theme
	if not (T and T.SetTableStyle) then return "t5_ruled" end
	if not (T.IsValidTableStyle and T.IsValidTableStyle(styleKey)) then styleKey = "t5_ruled" end
	if MerchantMasterDB then MerchantMasterDB.tableStyle = styleKey end
	local ok, err = pcall(T.SetTableStyle, styleKey)
	if not ok and geterrorhandler then geterrorhandler()(err) end
	if MerchantMasterDB then MerchantMasterDB.tableStyle = T.GetTableStyle() end
	app.syncTableStyleWidgets()
	return T.GetTableStyle()
end

