	ns.Theme.OnTableStyleChanged(function(styleKey, _, changed)
		if MerchantMasterDB then MerchantMasterDB.tableStyle = styleKey end
		app.syncTableStyleWidgets()
		if changed and panel:IsShown() and app.refresh then
			app.refresh()
		end
	end)
end

-- Theme-aware row tints: the legacy white zebra vanishes and the brown/amber washes turn muddy on light cards.
local function setRowStripe(r, kind, rowIndex)
	local stripe = r and r.stripe
	if not stripe then return end
	local light = (getPal().mode == "light")
	if kind == "monopoly" then
		if light then stripe:SetColorTexture(0.88, 0.42, 0.00, 0.085) else stripe:SetColorTexture(1.00, 0.57, 0.19, 0.14) end
	elseif kind == "hot" then
		if light then stripe:SetColorTexture(0.84, 0.14, 0.16, 0.065) else stripe:SetColorTexture(1.00, 0.26, 0.27, 0.12) end
	elseif kind == "zebra" and (rowIndex or 0) % 2 == 0 then
		if light then stripe:SetColorTexture(0, 0, 0, 0.025) else stripe:SetColorTexture(1, 1, 1, 0.03) end
	else
		stripe:SetColorTexture(0, 0, 0, 0)
	end
	if r and r.sep and ns.Theme and ns.Theme.IsCustomSkin and ns.Theme.IsCustomSkin() then
		local tStyle = ns.Theme.GetTableStyle and ns.Theme.GetTableStyle() or "t5_ruled"
		local pal = getPal()
		local fb = pal.frameBorder or { 0.75, 0.56, 0.18, 1 }
		if tStyle == "t5_well" then
			r.sep:SetColorTexture(0, 0, 0, 0)
		elseif tStyle == "t5_ruled" then
			local a = ((rowIndex or 0) > 0 and (rowIndex % 4 == 0)) and 0.30 or 0.13
			r.sep:SetColorTexture(fb[1], fb[2], fb[3], a)
		elseif tStyle == "t3_strips" then
			r.sep:SetColorTexture(0.02, 0.06, 0.04, 0.85)
		end
	end
end

-- Hairline separator that follows pal.separator on Dark <-> Light
local function themeSeparator(tex)
	local function paint()
		local sep = getPal().separator or getPal().glassSep or { 1, 1, 1, 0.12 }
		tex:SetColorTexture(sep[1], sep[2], sep[3], sep[4] or 0.12)
	end
	paint()
	ns.Theme.RegisterWidget(tex, paint)
	return tex
end

-- Free-standing label: Apple font (no yellow GameFontNormal + drop shadow), palette ink, legacy
-- colour codes translated on every SetText, repainted live on Dark <-> Light.
local function themeLabel(fs, size, weight, colorKey)
	if not fs then return fs end
	applySafeFont(fs, size or 11, weight or "regular")
	ns.Theme.AutoThemeText(fs)
	local function paint()
		local pal = getPal()
		local c = pal[colorKey or "text"] or pal.text
		if c and fs.SetTextColor then fs:SetTextColor(c[1], c[2], c[3], c[4] or 1) end
	end
	paint()
	ns.Theme.RegisterWidget(fs, function()
		paint()
		local txt = fs.GetText and fs:GetText()
		if txt and txt ~= "" then fs:SetText(txt) end
	end)
	return fs
end

local sidebar = CreateFrame("Frame", nil, panel)
