	layer = "BACKGROUND",
	sub = -3,
})

-- Liquid Glass frost: WoW cannot blur the game UI behind a frame, so the sidebar is a near-opaque
-- baked substrate (diffused light pools + silica grain) under an optical lensing rim. Both maps are
-- 256x512 vertical 3-slices (32px caps, stretched middle) whose baked r=22 outer-left corners sit
-- inside sidebar.surface at any window height.
do
	local GLASS_ROOT = ns.Theme.ASSET_ROOT or "Interface\\AddOns\\MerchantMaster\\Assets\\"
	local CAP, CAP_V = 32, 32 / 512

	local function glassSlices(layer, sub)
		local set = { pieces = {} }
		local top = sidebar:CreateTexture(nil, layer, nil, sub)
		top:SetPoint("TOPLEFT", sidebar, "TOPLEFT", 0, 0)
		top:SetPoint("TOPRIGHT", sidebar, "TOPRIGHT", 0, 0)
		top:SetHeight(CAP)
		top:SetTexCoord(0, 1, 0, CAP_V)
		local bottom = sidebar:CreateTexture(nil, layer, nil, sub)
		bottom:SetPoint("BOTTOMLEFT", sidebar, "BOTTOMLEFT", 0, 0)
		bottom:SetPoint("BOTTOMRIGHT", sidebar, "BOTTOMRIGHT", 0, 0)
		bottom:SetHeight(CAP)
		bottom:SetTexCoord(0, 1, 1 - CAP_V, 1)
		local mid = sidebar:CreateTexture(nil, layer, nil, sub)
		mid:SetPoint("TOPLEFT", top, "BOTTOMLEFT", 0, 0)
		mid:SetPoint("BOTTOMRIGHT", bottom, "TOPRIGHT", 0, 0)
		mid:SetTexCoord(0, 1, CAP_V, 1 - CAP_V)
		set.pieces[1], set.pieces[2], set.pieces[3] = top, mid, bottom
		function set:Apply(texName, alpha)
			self.texture, self.alpha = texName, alpha
			for _, piece in ipairs(self.pieces) do
				piece:SetTexture(GLASS_ROOT .. texName)
				piece:SetVertexColor(1, 1, 1, alpha)
			end
		end
		return set
	end

	sidebar.refractWash = glassSlices("BACKGROUND", -1)
	sidebar.refractLens = glassSlices("BORDER", -1)
	-- Top specular caustic shimmer riding the upper lip of the pane
	sidebar.refractGlow = sidebar:CreateTexture(nil, "BORDER", nil, 0)
	sidebar.refractGlow:SetPoint("TOPLEFT", sidebar, "TOPLEFT", 22, -1)
	sidebar.refractGlow:SetPoint("TOPRIGHT", sidebar, "TOPRIGHT", 0, -1)
	sidebar.refractGlow:SetHeight(16)
	sidebar.refractGlow:SetTexture(GLASS_ROOT .. "glow_line")

	function sidebar.applyGlass()
		local light = (getPal().mode == "light")
		sidebar.refractWash:Apply(light and "header_wash" or "shade_v", 0.92)
		sidebar.refractLens:Apply("fade_lr", light and 0.70 or 0.55)
		sidebar.refractGlow:SetVertexColor(1, 1, 1, light and 0.16 or 0.07)
	end
	sidebar.applyGlass()
end
