local function moneyText(copper, signed, opts)
	if _G.issecretvalue and _G.issecretvalue(copper) then return "--" end
	if copper == nil then return "--" end
	if ns.Theme and ns.Theme.FormatMoneyFable then
		return ns.Theme.FormatMoneyFable(copper, signed, opts)
	elseif ns.Theme and ns.Theme.FormatMoneyParts then
		return ns.Theme.FormatMoneyParts(copper, signed).text
	end
	return ns.FormatMoneyCompact(copper, signed)
end

