function app.invalidateCraftableScope()
	if ns.InvalidatePriceCache then ns.InvalidatePriceCache() end
	if app.invalidateRecipeStats then
		app.invalidateRecipeStats("known")
		app.invalidateRecipeStats("skills")
		app.invalidateRecipeStats("cooldown")
	end
end

function app.canFitToolbarCharScope()
	if ns.Theme.IsCustomSkin and ns.Theme.IsCustomSkin() then return false end
	local tw = (app.ui.toolbar and app.ui.toolbar.GetWidth and app.ui.toolbar:GetWidth()) or 0
	if tw <= 200 then
		local cartW = (app.ui.topCartBtn and app.ui.topCartBtn.GetWidth and app.ui.topCartBtn:GetWidth()) or 184
		local pw = (panel and panel.GetWidth and panel:GetWidth()) or 1840
		tw = pw - 216 - 12 - (12 + 48 + 6 + 48 + 6 + cartW + 8 + 84 + 8)
	end
	return tw >= 910
end

function app.setCraftableAllChars(on)
	if not MerchantMasterDB then return end
	MerchantMasterDB.craftableAllChars = (on == true)
	app.invalidateCraftableScope()
	if app.syncToolbarCharScope then app.syncToolbarCharScope(true) end
	if app.ui.knownAllCharsCheck then app.ui.knownAllCharsCheck:SetChecked(MerchantMasterDB.craftableAllChars) end
	if app.ui.optAllCharsCheck then app.ui.optAllCharsCheck:SetChecked(MerchantMasterDB.craftableAllChars) end
	if app.consoleProvider and app.consoleProvider.SyncSettings then app.consoleProvider.SyncSettings() end
	if app.refresh then app.refresh() end
end

