function app.syncToolbarCharScope(skipScanChrome)
	local db = MerchantMasterDB or {}
	local knownOnly = (db.knownRecipesOnly == true) or (db.unlockFilter == "known")
	local showSeg = knownOnly and app.canFitToolbarCharScope()
	charScopeSeg:SetActive(db.craftableAllChars and "all_chars" or "current", true)
	local changed = (charScopeSeg.frame:IsShown() ~= showSeg)
	charScopeSeg.frame:SetShown(showSeg)
	local kBtn = scopeSeg.buttons and scopeSeg.buttons.known
	if kBtn and kBtn._label and kBtn._label.SetText then
		kBtn._label:SetText((knownOnly and not showSeg and db.craftableAllChars) and "Craftable (All)" or "Craftable Now")
	end
	if changed and not skipScanChrome and app.updateScanChrome then
		app.updateScanChrome()
	end
end

