-- Tooltip / API wording for a live browse scan (nil while idle)
function app.formatScanStatus(state)
	if not (state and state.active) then return nil end
	if (state.page or 0) <= 0 then return "Scanning AH…" end
	return string.format("Scanning page %d · %d items matched", state.page, state.matchedCount or 0)
end

-- Live scan feedback: MarketScan calls app.onScanProgress on start, every browse page, every
-- order-book job and on finish / cancel. Idle restores the normal freshness dot + source label.
-- `marketState` is optional: callers that already read MarketScan.GetState() pass it through.
do
	local function syncLabelWidth(str)
		statusSyncFs:SetText(str)
		local w = (statusSyncFs.GetUnboundedStringWidth and statusSyncFs:GetUnboundedStringWidth())
			or (statusSyncFs.GetStringWidth and statusSyncFs:GetStringWidth())
			or 0
		if w < 16 then w = 7.2 * #str end
		return w
	end

	function app.updateScanChrome(marketState)
		local ui = app.ui
		if not (ui.statusEconFs and ui.statusSyncFs) then return end
		local pal = getPal()
		if type(marketState) ~= "table" then
			marketState = (ns.MarketScan and ns.MarketScan.GetState and ns.MarketScan.GetState()) or {}
		end
		local refresh = winChrome and winChrome.ahRefresh
		if refresh then refresh:Update(marketState.active == true, app.formatScanStatus(marketState)) end
		local econStr = ui._statusEconStr or ui.statusEconFs:GetText() or ""
		local syncStr = ui._statusSyncStr or "AH Ready"
		local blue = pal.accentBlue or { 0, 0.569, 1, 1 }
		local lots = app.lotScanTotal or 0
		local dotCol, syncCol, frac
		-- One width lock per scan (browse = -1, deep lot scan = its lot total)
		local lockKey = (marketState.active and -1) or (lots > 0 and lots) or nil
		if lockKey ~= ui._scanLockKey then
			ui._scanLockKey, ui._scanSyncMinW, ui._scanCapsuleW = lockKey, nil, nil
		end
		if marketState.active then
			local page = tonumber(marketState.page) or 0
			dotCol = blue
			syncStr = page > 0 and string.format("Scanning p.%d · %d items", page, marketState.matchedCount or 0) or "Scanning AH…"
			syncCol = pal.text or blue
			-- Reserve the widest label this scan will plausibly show, once, so the right-anchored
			-- capsule keeps its left edge still while pages arrive.
			ui._scanSyncMinW = ui._scanSyncMinW
				or math.max(syncLabelWidth("Scanning AH…"), syncLabelWidth("Scanning p.999 · 999 items"))
		elseif lots > 0 then
			dotCol = blue
			syncStr = string.format("Deep Scan %d/%d", app.lotScanDone or 0, lots)
			syncCol = pal.text or blue
			frac = math.max(0.08, math.min(1, (app.lotScanDone or 0) / lots))
			ui._scanSyncMinW = ui._scanSyncMinW or syncLabelWidth(string.format("Deep Scan %d/%d", lots, lots))
		else
			if ui._statusUsingTSM then
				dotCol = pal.accentGreen or { 0.19, 0.82, 0.35, 1 }
				syncCol = pal.textTertiary or pal.textSecondary
			elseif ui._statusNoScanYet then
				local amber = pal.accentOrange or { 1.0, 0.62, 0.04, 1 }
				dotCol = amber
				syncCol = amber
			else
				local status = refresh and refresh.state and refresh.state.status
				dotCol = (status == "red" and pal.accentRed) or (status == "orange" and pal.accentOrange) or pal.accentGreen
					or { 0.19, 0.82, 0.35, 1 }
				syncCol = pal.textTertiary or pal.textSecondary
			end
		end
		ui.statusSyncFs:SetText(syncStr)
		if ui.statusServerFs then
			ui.statusServerFs:SetText(string.format("%s  |  %s", econStr, syncStr))
		end
		if syncCol then ui.statusSyncFs:SetTextColor(syncCol[1], syncCol[2], syncCol[3], syncCol[4] or 1) end
		if ui.statusDot then ui.statusDot:SetVertexColor(dotCol[1], dotCol[2], dotCol[3], 1) end
		ui.statusScanning = lockKey ~= nil
		-- While scanning the capsule may grow (p.1000+) but never shrinks
		local capsuleW = updateStatusCapsuleWidth(econStr, syncStr, ui._scanSyncMinW, ui._scanCapsuleW)
		if lockKey then ui._scanCapsuleW = capsuleW end
		local bar = ui.statusScanBar
		if bar then
			if lockKey then
				bar.track:SetVertexColor(blue[1], blue[2], blue[3], 0.24)
				bar.fill:SetVertexColor(blue[1], blue[2], blue[3], 1)
				bar.indeterminate = (frac == nil)
				bar.fraction = frac
				if bar.indeterminate then
					bar.shuttlePos = bar.shuttlePos or 0
				else
					bar.shuttlePhase, bar.shuttlePos = nil, nil
				end
				bar:LayoutFill()
				bar:Show()
			else
				bar.indeterminate, bar.fraction, bar.shuttlePhase, bar.shuttlePos = false, nil, nil, nil
				bar:Hide()
			end
		end
	end
end
app.onScanProgress = app.updateScanChrome

-- Real glyph widths only exist once the toolbar has rendered: one-shot re-measure right after its first show.
toolbar:HookScript("OnShow", function(self)
	if self._mmStatusMeasured then return end
	self._mmStatusMeasured = true
	if C_Timer and C_Timer.After then
		C_Timer.After(0, function()
			if app.updateScanChrome then app.updateScanChrome() end
		end)
	end
end)


