-- Cycle & Dropdown helpers
local function cycleListOption(list, currentKey, reverse)
	local idx = 1
	for i, item in ipairs(list) do
		if item.key == currentKey then idx = i; break end
	end
	if reverse then
		idx = ((idx - 2) % #list) + 1
	else
		idx = (idx % #list) + 1
	end
	return list[idx]
end

local function toggleSubCraftOverride(overrideKey, currentlyCraft, mouseBtn, rawItemID)
	if not (MerchantMasterDB and (overrideKey or rawItemID)) then return end
	local key = overrideKey or rawItemID
	MerchantMasterDB.subCraftOverrides = MerchantMasterDB.subCraftOverrides or {}
	if mouseBtn == "RightButton" then
		MerchantMasterDB.subCraftOverrides[key] = nil
		if rawItemID and key ~= rawItemID then
			MerchantMasterDB.subCraftOverrides[rawItemID] = nil
		end
	else
		MerchantMasterDB.subCraftOverrides[key] = currentlyCraft and "buy" or "craft"
	end
	app._subCraftOverrideEpoch = (app._subCraftOverrideEpoch or 0) + 1
	app._shoppingSyncSig = nil
	if ns.InvalidateCraftDecisionCache then
		ns.InvalidateCraftDecisionCache(app.uiPriceBank)
	elseif ns.InvalidatePriceCache then
		ns.InvalidatePriceCache()
	end
	local shopShown = app.ui and app.ui.shopModal and app.ui.shopModal:IsShown()
	if shopShown and app.refreshUnifiedShoppingDisplay then
		app.refreshUnifiedShoppingDisplay()
		if app.panel and app.panel:IsShown() then
			if app.scheduleRefresh then
				app.scheduleRefresh("subcraft_override")
			elseif app.refresh then
				app.refresh()
			end
		end
	elseif app.refresh then
		app.refresh()
	end
end

local function buildEconomyMenuOptions()
	local activeEcon = ns.DetectActiveEconomy()
	local opts = {}
	for _, e in ipairs(ns.ECONOMIES) do
		local lbl = e.label
		if e.key == "auto" then
			lbl = "Auto (" .. activeEcon .. ")"
		end
		opts[#opts + 1] = { key = e.key, label = lbl }
	end
	return opts
end

function app.cycleEconomy(button, ownerBtn)
	if not MerchantMasterDB then return end
	if button == "RightButton" then
		MerchantMasterDB.economy = "auto"
	elseif ownerBtn and not (IsShiftKeyDown and IsShiftKeyDown()) then
		local curSel = (ns.CurrentEconomyInfo and ns.CurrentEconomyInfo().selectedKey) or MerchantMasterDB.economy or "auto"
		ns.Theme.OpenDropDown(ownerBtn, buildEconomyMenuOptions(), curSel, function(pickedKey)
			MerchantMasterDB.economy = pickedKey
			if ns.InvalidatePriceCache then ns.InvalidatePriceCache() end
			if app.ui.optEconBtn then
				app.ui.optEconBtn:SetText("Economy: " .. ns.CurrentEconomyInfo().buttonLabel)
			end
			if ns.MapPins and ns.MapPins.OnEvent then ns.MapPins.OnEvent("HOST_CONTEXT_CHANGED") end
			if app.consoleProvider and app.consoleProvider.SyncSettings then app.consoleProvider.SyncSettings() end
			if app.refresh then app.refresh() end
		end, 224)
		return
	else
		local curSel = (ns.CurrentEconomyInfo and ns.CurrentEconomyInfo().selectedKey) or MerchantMasterDB.economy or "auto"
		local nxt = cycleListOption(buildEconomyMenuOptions(), curSel, IsShiftKeyDown and IsShiftKeyDown())
		MerchantMasterDB.economy = nxt.key
	end
	if ns.InvalidatePriceCache then ns.InvalidatePriceCache() end
	if app.ui.optEconBtn then
		app.ui.optEconBtn:SetText("Economy: " .. ns.CurrentEconomyInfo().buttonLabel)
	end
	if ns.MapPins and ns.MapPins.OnEvent then ns.MapPins.OnEvent("HOST_CONTEXT_CHANGED") end
	if app.consoleProvider and app.consoleProvider.SyncSettings then app.consoleProvider.SyncSettings() end
	if app.refresh then app.refresh() end
end

function app.showEconomyTooltip(owner)
	GameTooltip:SetOwner(owner, "ANCHOR_RIGHT")
	local econ = ns.CurrentEconomyInfo()
	local activeEcon, activeRegion = ns.DetectActiveEconomy()
	GameTooltip:AddLine("Auction House Economy Filter", 1, 0.82, 0)
	GameTooltip:AddDoubleLine("Selected Economy:", econ.buttonLabel, 0.85, 0.85, 0.85, 0.2, 1, 0.2)
	GameTooltip:AddDoubleLine("Character Active Economy:", activeEcon .. " (" .. activeRegion .. ")", 0.85, 0.85, 0.85, 1, 1, 1)
	local snapMeta = (ns.HasSnapshots and ns.HasSnapshots())
		and ns.Pricing and type(ns.Pricing.GetSnapshotMeta) == "function"
		and ns.Pricing.GetSnapshotMeta(econ.effectiveKey) or nil
	if type(snapMeta) == "table" then
		local srcLabel = "Blizzard API"
		local now = type(_G.time) == "function" and _G.time() or nil
		local upd = tonumber(snapMeta.updatedAt) or 0
		local ageText = "loaded"
		local ar, ag, ab = 0.65, 0.95, 0.65
		if upd > 0 and now and now >= upd then
			local ageSec = now - upd
			if ageSec > 10800 then
				ageText = tostring(math.floor(ageSec / 3600)) .. "h ago"
				ar, ag, ab = 1.0, 0.42, 0.42
			else
				ageText = tostring(math.floor(ageSec / 60)) .. "m ago"
				if ageSec >= 4500 then
					ar, ag, ab = 1.0, 0.72, 0.28
				end
			end
		end
		local itemsN = tonumber(snapMeta.itemCount) or 0
		local heatN = tonumber(snapMeta.heatmapCount) or 0
		local winDays = tonumber(snapMeta.windowDays) or 30
		GameTooltip:AddLine(" ")
		GameTooltip:AddLine("Local Snapshot:", 1, 0.82, 0)
		GameTooltip:AddDoubleLine("  " .. (econ.effectiveKey or "Active") .. " (" .. srcLabel .. ")", ageText, 0.9, 0.9, 0.9, ar, ag, ab)
		GameTooltip:AddDoubleLine("  Coverage:", string.format("%s items  ·  %s heatmaps  ·  %dd", formatComma(itemsN), formatComma(heatN), winDays), 0.85, 0.85, 0.85, 0.75, 0.88, 1)
	end
	if MerchantMasterDB and MerchantMasterDB.ahPrices then
		local hasAH = false
		for k, tbl in pairs(MerchantMasterDB.ahPrices) do
			if type(tbl) == "table" and tbl._scannedAt then
				if not hasAH then
					GameTooltip:AddLine(" ")
					GameTooltip:AddLine("Saved Live AH Scans:", 1, 0.82, 0)
					hasAH = true
				end
				local age = SecondsToTime and (SecondsToTime(math.max(0, time() - tbl._scannedAt)) .. " ago") or "saved"
				GameTooltip:AddDoubleLine("  " .. k, age, 0.9, 0.9, 0.9, 0.65, 0.85, 1)
			end
		end
	end
	GameTooltip:AddLine(" ")
	GameTooltip:AddLine("WoW: Forever splits AH economies by Ruleset x Faction (Normal, PvP, Roleplay, Roleplay PvP, Hardcore x Horde/Alliance).", 0.75, 0.75, 0.75, true)
	GameTooltip:AddLine("Left-Click: open dropdown menu  ·  Shift-Click: cycle  ·  Right-Click: Auto", 0.65, 0.85, 1)
	GameTooltip:Show()
end

-- Fable 5.2 Design 1 Sidebar (Search Capsule, 4 Grouped Nav Sections, Pinned Rep & Wallet Card)
-- + Floating Filters & Tools Popover (`sidebarOptionsHost`) hosting all legacy/advanced panel controls
do
	local SB_SIDEBAR_W = 192
	local searchWrap = CreateFrame("Frame", nil, sidebar)
	searchWrap:SetPoint("TOPLEFT", sidebar, "TOPLEFT", 12, -74)
	searchWrap:SetPoint("TOPRIGHT", sidebar, "TOPRIGHT", -12, -74)
	searchWrap:SetHeight(30)
