		cornerSize = 15,
		noSpecular = true,
	})
	app.ui.searchWrap = searchWrap

	local searchIcon = ns.Theme.AppleIcon(searchWrap, "search", 13, getPal().textTertiary or getPal().textMuted)
	searchIcon:SetPoint("LEFT", searchWrap, "LEFT", 10, 0)
	app.ui.searchIcon = searchIcon

	local searchBox = CreateFrame("EditBox", nil, searchWrap, "InputBoxTemplate")
	searchBox:SetHeight(24)
	searchBox:SetPoint("LEFT", searchIcon, "RIGHT", 6, 0)
	searchBox:SetPoint("RIGHT", searchWrap, "RIGHT", -24, 0)
	searchBox:SetAutoFocus(false)
	for _, k in ipairs({ "Left", "Middle", "Right" }) do
		if searchBox[k] and searchBox[k].Hide then searchBox[k]:Hide() end
	end
	if searchBox.SetTextInsets then searchBox:SetTextInsets(0, 0, 0, 0) end
	applySafeFont(searchBox, 12, "regular")
	if searchBox.SetTextColor and getPal().text then
		local t = getPal().text
		searchBox:SetTextColor(t[1], t[2], t[3], 1)
	end
	searchBox.placeholder = searchBox:CreateFontString(nil, "ARTWORK", "GameFontDisableSmall")
	searchBox.placeholder:SetPoint("LEFT", searchBox, "LEFT", 1, 0)
	searchBox.placeholder:SetText("Search")
	applySafeFont(searchBox.placeholder, 12, "regular")
	do
		local pc = getPal().textTertiary or getPal().textMuted
		if pc then searchBox.placeholder:SetTextColor(pc[1], pc[2], pc[3], pc[4] or 1) end
	end

	local clearSearchBtn = CreateFrame("Button", nil, searchWrap)
	clearSearchBtn:SetSize(18, 18)
	clearSearchBtn:SetPoint("RIGHT", searchWrap, "RIGHT", -6, 0)
	local clearIcon = ns.Theme.AppleIcon(clearSearchBtn, "close", 11, ns.Theme.COLORS.textMuted)
	clearIcon:SetPoint("CENTER")
	clearSearchBtn.icon = clearIcon
	clearSearchBtn:SetScript("OnClick", function()
		searchBox:SetText("")
		searchBox:ClearFocus()
	end)
	clearSearchBtn:Hide()
	searchBox._mmClearBtn = clearSearchBtn

	searchBox:SetScript("OnEscapePressed", function(self)
		if self:GetText() ~= "" then self:SetText("") end
		self:ClearFocus()
	end)
	searchBox:SetScript("OnEnterPressed", function(self) self:ClearFocus() end)
	function app.onOverviewSearchChanged(self, userInput)
		local txt = self:GetText() or ""
		local empty = (txt == "")
		self.placeholder:SetShown(empty)
		if self._mmClearBtn then self._mmClearBtn:SetShown(not empty) end
		if txt == self._lastSearchText then return end
		self._lastSearchText = txt
		self._searchSeq = (self._searchSeq or 0) + 1
		if not panel:IsShown() then return end
		if userInput and C_Timer and C_Timer.After then
			local seq = self._searchSeq
			C_Timer.After(0.15, function()
				if self._searchSeq == seq and panel:IsShown() and app.refresh then
					app.refresh()
				end
			end)
		elseif app.refresh then
			app.refresh()
		end
	end
	searchBox._lastSearchText = ""
	searchBox:SetScript("OnTextChanged", app.onOverviewSearchChanged)
	app.ui.searchBox = searchBox
	-- Item links enter the same text-change path as a typed search.
	function ns.AllowItemInsert(link)
		if (_G.issecretvalue and _G.issecretvalue(link)) or type(link) ~= "string" then return false end
		if not panel:IsShown() or not searchBox.HasFocus or not searchBox:HasFocus() then return false end
		if _G.IsShiftKeyDown and not _G.IsShiftKeyDown() then return false end
		local id = link:match("item:(%d+)")
		if not id then return false end
		local name = link:match("|h%[(.-)%]|h")
		if not name and _G.GetItemInfo then
			local ok, value = pcall(_G.GetItemInfo, tonumber(id))
			if ok and not (_G.issecretvalue and _G.issecretvalue(value)) then name = value end
		end
		if type(name) ~= "string" or name == "" then return false end
		searchBox:SetText(name)
		return true
	end
