				if sc then sfs:SetTextColor(sc[1], sc[2], sc[3], 1.0) end
				if sfs.SetShadowOffset then sfs:SetShadowOffset(1, -1) end
				if sfs.SetShadowColor then sfs:SetShadowColor(0, 0, 0, 0.90) end
			else
				local tm = pal.textTertiary or pal.textMuted
				if tm then sfs:SetTextColor(tm[1], tm[2], tm[3], tm[4] or 1) end
				if sfs.SetShadowOffset then sfs:SetShadowOffset(0, 0) end
			end
