	local function createProfCard(p, px, py, pw)
		local btn = CreateFrame("Button", nil, sidebarOptionsHost)
		btn:SetSize(pw, 18)
		btn:SetPoint("TOPLEFT", px, py)
		btn._gridX = px
		btn._gridRelY = py - profGridToolsY
		btn.card = ns.Theme.NineApple(btn, "glass_r8", ns.Theme.COLORS.inputBg, ns.Theme.COLORS.border, { noSpecular = true })
		btn.hl = btn:CreateTexture(nil, "HIGHLIGHT")
		btn.hl:SetAllPoints()
		local hc = ns.Theme.COLORS.glassHover or { 1, 1, 1, 0.08 }
		btn.hl:SetColorTexture(hc[1], hc[2], hc[3], hc[4] or 0.08)
		btn.fs = btn:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
		btn.fs:SetAllPoints()
		btn.fs:SetJustifyH("CENTER")
		btn.fs:SetText(p.label)
		local pkey = p.key
		btn:SetScript("OnClick", function(_, mouseBtn)
			if not MerchantMasterDB then return end
			local isProfMenu = (type(app.activeTab) == "string" and app.activeTab:sub(1, 5) == "prof_")
			if isProfMenu and ns.MP and ns.MP.PROFESSIONS and ns.MP.PROFESSIONS[pkey] then
				local pdb = ns.GetProfessorDB and ns.GetProfessorDB()
				if pdb then pdb.selectedProf = pkey end
				MerchantMasterDB.profFilter = (mouseBtn == "RightButton") and "all" or pkey
				if app.professorProvider and app.professorProvider.onProfSelected then
					pcall(app.professorProvider.onProfSelected, pkey)
				end
				app.refresh()
				return
			end
			if mouseBtn == "RightButton" or (MerchantMasterDB.profFilter == pkey and pkey ~= "all") then
				MerchantMasterDB.profFilter = "all"
			else
				MerchantMasterDB.profFilter = pkey
				if ns.MP and ns.MP.PROFESSIONS and ns.MP.PROFESSIONS[pkey] and ns.GetProfessorDB then
					ns.GetProfessorDB().selectedProf = pkey
				end
			end
			app.refresh()
		end)
		btn:RegisterForClicks("LeftButtonUp", "RightButtonUp")
		app.ui.profBtns[pkey] = btn
	end

	createProfCard(ns.PROF_BY_KEY.all, 12, y, 52)
