	local function makeSidebarDrop(listGetter, getKeyFn, setKeyFn, resetFn, tipTitle, tipBody)
		local b = CreateFrame("Button", nil, sidebarOptionsHost, "UIPanelButtonTemplate")
		b:SetSize(SB_W, 21)
		b:RegisterForClicks("LeftButtonUp", "RightButtonUp")
		ns.Theme.SkinButton(b, { dropdown = true })
		b._isCheck = false
		b:SetScript("OnClick", function(self, mouseBtn)
			if not MerchantMasterDB then return end
			if mouseBtn == "RightButton" then
				if resetFn then resetFn() end
				app.refresh()
			else
				local menu = type(listGetter) == "function" and listGetter() or listGetter
				ns.Theme.OpenDropDown(self, menu, getKeyFn(), function(picked)
					setKeyFn(picked)
					app.refresh()
				end, 206)
			end
		end)
		if tipTitle then
			b:SetScript("OnEnter", function(self)
				GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
				GameTooltip:AddLine(tipTitle, 1, 0.82, 0)
				if tipBody then GameTooltip:AddLine(tipBody, 1, 1, 1, true) end
				GameTooltip:Show()
			end)
			b:SetScript("OnLeave", GameTooltip_Hide)
		end
		b:Hide()
		return b
	end

