		if tipTitle then
			chk:SetScript("OnEnter", function(self)
				GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
				GameTooltip:AddLine(tipTitle, 1, 0.82, 0)
				if tipBody then GameTooltip:AddLine(tipBody, 1, 1, 1, true) end
				GameTooltip:Show()
			end)
			chk:SetScript("OnLeave", GameTooltip_Hide)
		end
		chk:Hide()
		return chk
	end

