		if MerchantMasterDB then MerchantMasterDB.calcRespectStock = self:GetChecked() and true or false end
		app.refresh()
	end, "Stock-Aware Combo Switching", "Switches automatically to the next cheapest combo when AH stock runs out or hits a price jump.")

	app.ui.deepScanBtn = makeSidebarBtn("Deep Scan AH Lots", false, function()
		if app.runCalculatorDeepScan then app.runCalculatorDeepScan() end
	end, "Deep Scan Multi-Price AH Lots", "Scans exact multi-price order-book ladders at the Auction House.")

	app.ui.writZoneBtn = makeSidebarDrop(function()
		return ns.GetWritZones and ns.GetWritZones() or { { key = "all", label = "Area: All Zones" } }
	end,
		function() return MerchantMasterDB and MerchantMasterDB.writZoneFilter or "all" end,
		function(k) if MerchantMasterDB then MerchantMasterDB.writZoneFilter = k end end,
		function() if MerchantMasterDB then MerchantMasterDB.writZoneFilter = "all" end end,
		"Turn-In Area / Zone Filter",
		"Filter Craftsman's Writs by turn-in zone (Orgrimmar, Stormwind, Hillsbrad, Tanaris, Winterspring, etc.) so you can buy & complete multiple Writs in one trip! Right-click to reset.")

	app.ui.writPouchCheck = makeSidebarCheck("Include Coin Pouch", function(self)
		if MerchantMasterDB then MerchantMasterDB.includeWritPouch = (self:GetChecked() and true or false) end
		app.refresh()
	end, "Craftsman's Writ Coin Pouch (Tiered Cashback)", "Turning in a Craftsman's Writ rewards a tiered Coin Pouch: Journeyman (+75 Rep, item 284584) = 35s 36c, Expert (+125 Rep, item 284585) = 74s 80c, Artisan (+200 Rep, item 284586) = 74s 80c. Deducting the Coin Pouch makes many Writs near-zero or net-profitable Reputation!")

	app.ui.clearWritRouteBtn = makeSidebarBtn("Clear Shopping List", false, function()
		if app.clearUnifiedShoppingList then app.clearUnifiedShoppingList() end
	end, "Clear Shopping List", "Clears all queued and added items from the unified Shopping List across every screen.")

	for _, reset in ipairs({
		{ "dashResetFiltersBtn", "resetDashboardFilters" },
		{ "spreadResetFiltersBtn", "resetSpreadFilters" },
		{ "outliersResetFiltersBtn", "resetOutliersFilters" },
		{ "cratesResetFiltersBtn", "resetCratesFilters" },
		{ "writsResetFiltersBtn", "resetWritsFilters" },
		{ "forgedResetFiltersBtn", "resetForgedFilters" },
		{ "repResetFiltersBtn", "resetRepViewFilters" },
		{ "favorResetFiltersBtn", "resetFavorCalcFilters" },
		{ "repCalcResetFiltersBtn", "resetRepCalcFilters" },
	}) do
		local method = reset[2]
		app.ui[reset[1]] = makeSidebarBtn("Reset Filters", false, function() app[method]() end)
	end

	app.allDynamicSidebarControls = {
		app.ui.dashResetFiltersBtn, app.ui.spreadResetFiltersBtn, app.ui.outliersResetFiltersBtn,
		app.ui.cratesResetFiltersBtn, app.ui.writsResetFiltersBtn, app.ui.forgedResetFiltersBtn, app.ui.repResetFiltersBtn,
		app.ui.favorResetFiltersBtn, app.ui.repCalcResetFiltersBtn,
		app.ui.dashScopeBtn, app.ui.spreadCountBtn, app.ui.diversifyCheck, app.ui.clearSpreadQueueBtn,
		app.ui.outlierScopeBtn, app.ui.outlierQualityBtn, app.ui.resetOutlierPricesBtn,
		app.ui.crateModeBtn, app.ui.bestOnlyCheck, app.ui.crateTooltipCheck, app.ui.quickCalcBtn,
		app.ui.writModeBtn, app.ui.writZoneBtn, app.ui.writPouchCheck, app.ui.clearWritRouteBtn,
		app.ui.subCraftBtn, app.ui.sellBtn, app.ui.originBtn,
		app.ui.merchantOnlyCheck, app.ui.recipeSourcesBtn, app.ui.recCraftFilterBtn, app.ui.recDemandFilterBtn,
		app.ui.simStartBtn, app.ui.shippingCheck,
		app.ui.calcModeBtn, app.ui.respectStockCheck, app.ui.deepScanBtn,
	}

	local function isResetControl(w)
		if not w then return false end
		local txt = w.GetText and w:GetText()
		return txt == "Reset Filters"
	end

	local function tabUsesGlobalProfFilters(tab)
		if type(tab) ~= "string" then return true end
		if tab:sub(1, 5) == "prof_" or tab:sub(1, 3) == "an_" or tab == "bags" or tab == "all_items" then
			return false
		end
		return true
	end

	function app.layoutSidebarOptions(list)
		sidebarOptionsHost._lastList = list or {}
		for _, w in ipairs(app.allDynamicSidebarControls) do
			w:Hide()
		end
		if app.professorProvider and app.professorProvider.controls then
			for _, w in ipairs(app.professorProvider.controls) do w:Hide() end
		end
		if app.analyticsProvider and app.analyticsProvider.controls then
			for _, w in ipairs(app.analyticsProvider.controls) do w:Hide() end
		end
		local isFiltersOnly = (sidebarOptionsHost._mode == "filters")
		local showProfs = isFiltersOnly and tabUsesGlobalProfFilters(app.activeTab)
		local profTopY = isFiltersOnly and -34 or sidebarOptionsHost._profGridToolsY
		for _, pBtn in pairs(app.ui.profBtns or {}) do
			pBtn:ClearAllPoints()
			pBtn:SetPoint("TOPLEFT", pBtn._gridX or 12, profTopY + (pBtn._gridRelY or 0))
			pBtn:SetShown(showProfs)
		end
		if app.ui.unlockBtn then
			app.ui.unlockBtn:ClearAllPoints()
			app.ui.unlockBtn:SetPoint("TOPLEFT", 12, profTopY - (sidebarOptionsHost._profGridHeight or 104))
			app.ui.unlockBtn:SetShown(showProfs)
		end
		for _, tc in ipairs(sidebarOptionsHost._toolsOnlyControls or {}) do
			tc:SetShown(not isFiltersOnly)
		end
		if app.ui.sidebarPopHdr then
			app.ui.sidebarPopHdr:SetText(isFiltersOnly and "FILTERS" or "SETTINGS & TOOLS")
		end

		if isFiltersOnly then
			local cy = showProfs and (profTopY - (sidebarOptionsHost._profGridHeight or 104) - 26) or -34
			local defaultStep = (#(list or {}) >= 7) and 22 or 23
			for _, w in ipairs(list or {}) do
				if w.GetParent and w:GetParent() == sidebar and w.SetParent then
					w:SetParent(sidebarOptionsHost)
				end
				if isResetControl(w) then
					w:Hide()
				else
					w:ClearAllPoints()
					w:SetPoint("TOPLEFT", sidebarOptionsHost, "TOPLEFT", 12, cy)
					w:Show()
					cy = cy - (w._sidebarHeight or (w._isCheck and 21 or defaultStep))
				end
			end
			sidebarOptionsHost:SetSize(224, math.max(96, math.abs(cy) + 12))
		else
			sidebarOptionsHost:SetSize(224, 292)
		end
	end

	function app.openSidebarPopover(mode, anchorBtn, alignLeft)
		sidebarOptionsHost._mode = (mode == "filters") and "filters" or "tools"
		sidebarOptionsHost._anchorBtn = anchorBtn
		sidebarOptionsHost:ClearAllPoints()
		if anchorBtn then
			if alignLeft then
				sidebarOptionsHost:SetPoint("TOPLEFT", anchorBtn, "BOTTOMLEFT", 0, -6)
			else
				sidebarOptionsHost:SetPoint("TOPRIGHT", anchorBtn, "BOTTOMRIGHT", 0, -6)
			end
		elseif toolsBtn then
			sidebarOptionsHost:SetPoint("TOPRIGHT", toolsBtn, "BOTTOMRIGHT", 0, -8)
		else
			sidebarOptionsHost:SetPoint("TOPRIGHT", panel, "TOPRIGHT", -12, -68)
		end
		app.layoutSidebarOptions(sidebarOptionsHost._lastList or {})
		sidebarOptionsHost:Show()
		if sidebarOptionsHost.Raise then sidebarOptionsHost:Raise() end
	end

	function app.toggleScreenFilters(anchorBtn, alignLeft)
		if sidebarOptionsHost:IsShown() and sidebarOptionsHost._mode == "filters" and sidebarOptionsHost._anchorBtn == anchorBtn then
			sidebarOptionsHost:Hide()
			return false
		end
		app.openSidebarPopover("filters", anchorBtn, alignLeft)
		return true
	end

	sidebarOptionsHost:HookScript("OnHide", function()
		if sidebarOptionsHost._mode == "filters" then
			sidebarOptionsHost._mode = "tools"
			sidebarOptionsHost._anchorBtn = nil
			app.layoutSidebarOptions(sidebarOptionsHost._lastList or {})
		end
	end)

	-- Hidden compat FontString for legacy sidebarShopFs callers (basket card removed from Filters & Tools)
	local shopCardFs = sidebarOptionsHost:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
	shopCardFs:Hide()
	shopCardFs:SetText("Basket: 0 items")
	app.ui.sidebarShopFs = shopCardFs
	app.ui.makeSidebarDrop = makeSidebarDrop
	app.ui.makeSidebarCheck = makeSidebarCheck
	app.ui.makeSidebarBtn = makeSidebarBtn
end

local function setCellBold(fs, isBold)
	if not fs or not fs.GetFont or not fs.SetFont then return end
	if not fs._mmBaseFont then
		local fp, fsz = fs:GetFont()
		if fp and fsz then
			fs._mmBaseFont = fp
			fs._mmBaseSize = fsz
		end
	end
	local want = isBold and true or false
	if fs._mmIsBold == want then return end
	fs._mmIsBold = want
	applySafeFont(fs, fs._mmBaseSize or 11, want and "semibold" or "regular")
end

-- Reusable Sortable Table Factory (Apple HIG 26px Uppercase Header, Hairline Separators & 4px Slim Scrollbar)
local function createSortableTable(parent, topOffset, tabKey, columns, initRowFn, bottomOffset, opts)
	columns = ns.Window.CopyColumns(columns)
	for _, col in ipairs(columns) do col.minWidth = col.minWidth or math.floor(col.width * 0.70) end
	app.ui.resizeTables = app.ui.resizeTables or {}
	local tbl = { columns = columns, colX = {}, headerBtns = {}, tabKey = tabKey, proportional = true }
	tbl.resizeParent = parent
	app.ui.resizeTables[#app.ui.resizeTables + 1] = tbl
	local x = 4
	for i, col in ipairs(columns) do
		tbl.colX[i] = x
		x = x + col.width + COL_GAP
	end

	local cardMode = (opts and opts.cardMode == true)
	local rowH = (opts and opts.rowHeight) or ROW_H
	local headerGap = cardMode and 0 or 27
	tbl.rowHeight = rowH
	tbl.cardMode = cardMode

	local headerBar = CreateFrame("Frame", nil, parent)
	headerBar:SetPoint("TOPLEFT", 6, topOffset)
	headerBar:SetPoint("TOPRIGHT", -18, topOffset)
	headerBar:SetHeight(cardMode and 1 or 26)
	if cardMode and headerBar.SetAlpha then headerBar:SetAlpha(0) end
	local hUnderline = headerBar:CreateTexture(nil, "BORDER")
	hUnderline:SetPoint("BOTTOMLEFT", 0, 0)
	hUnderline:SetPoint("BOTTOMRIGHT", 0, 0)
	hUnderline:SetHeight(1)
	local initSep = (ns.Theme.PALETTE and (ns.Theme.PALETTE.glassSep or ns.Theme.PALETTE.separator)) or { 1, 1, 1, 0.08 }
	hUnderline:SetColorTexture(initSep[1], initSep[2], initSep[3], cardMode and 0 or (initSep[4] or 0.08))
	tbl.headerBar = headerBar

	local function activeTableStyle()
		local T = ns.Theme
		if not (T and T.IsCustomSkin and T.IsCustomSkin()) then return "standard" end
		return (T.GetTableStyle and T.GetTableStyle()) or "t5_ruled"
	end

	local function isRuledGroupCol(idx, total)
		if total >= 11 then
			return idx == 4 or idx == 7 or idx == 11 or idx == 13
		end
		return idx > 1 and ((idx - 1) % 3 == 0)
	end

	local function paintTableChrome()
		if cardMode then
			if tbl.headerSkinBg then tbl.headerSkinBg:Hide() end
			if tbl.headerSkinSep then tbl.headerSkinSep:Hide() end
			if tbl.wellBgTex then tbl.wellBgTex:Hide() end
			if tbl.insetSkinEdges then for _, e in pairs(tbl.insetSkinEdges) do e:Hide() end end
			if tbl.insetMiniCorners then for _, c in pairs(tbl.insetMiniCorners) do c:Hide() end end
			if tbl.ruledVLines then for _, ln in pairs(tbl.ruledVLines) do ln:Hide() end end
			return
		end
		local style = activeTableStyle()
		local T = ns.Theme
		local pal = (T and (T.PALETTE or T.COLORS)) or {}
		local styled = (style == "t5_ruled" or style == "t5_well" or style == "t3_strips")
		local skinKey = T and T.GetSkin and T.GetSkin() or "standard"
		local fb = pal.frameBorder or { 0.75, 0.56, 0.18, 1 }
		if tbl.headerSkinBg then
			if styled and T and T.GetSkinAsset then
				local assetName = (style == "t3_strips") and "panel_hdr" or "header_bg"
				tbl.headerSkinBg:SetTexture(T.GetSkinAsset(skinKey, assetName))
				tbl.headerSkinBg:SetVertexColor(1, 1, 1, 0.98)
				tbl.headerSkinBg:Show()
				if tbl.headerSkinSep then
					tbl.headerSkinSep:SetColorTexture(fb[1], fb[2], fb[3], 0.80)
					tbl.headerSkinSep:Show()
				end
			else
				tbl.headerSkinBg:Hide()
				if tbl.headerSkinSep then tbl.headerSkinSep:Hide() end
			end
		end
		if tbl.wellBgTex then
			if styled then
				local ca = pal.cardAlt or pal.windowBg or { 0.035, 0.11, 0.075, 1 }
				tbl.wellBgTex:SetColorTexture(ca[1] * 0.62, ca[2] * 0.62, ca[3] * 0.62, 0.96)
				tbl.wellBgTex:Show()
				if tbl.inset and tbl.inset._mmCard and tbl.inset._mmCard.fill and tbl.inset._mmCard.fill.SetAlpha then
					tbl.inset._mmCard.fill:SetAlpha(0)
				end
			else
				tbl.wellBgTex:Hide()
				if tbl.inset and tbl.inset._mmCard and tbl.inset._mmCard.fill and tbl.inset._mmCard.fill.SetAlpha then
					tbl.inset._mmCard.fill:SetAlpha(1)
				end
			end
		end
		if tbl.inset then
			if tbl.insetSkinEdges then
				for _, e in pairs(tbl.insetSkinEdges) do
					if styled then
						e:SetColorTexture(fb[1], fb[2], fb[3], 0.88)
						e:Show()
					else
						e:Hide()
					end
				end
			end
			if tbl.insetMiniCorners then
				local showCorners = (style == "t5_ruled" or style == "t5_well") and T and T.GetSkinAsset
				local cPath = showCorners and T.GetSkinAsset(skinKey, "corner") or nil
				for _, c in pairs(tbl.insetMiniCorners) do
					if showCorners and cPath then
						c:SetTexture(cPath)
						c:SetVertexColor(1, 1, 1, 0.96)
						c:Show()
					else
						c:Hide()
					end
				end
			end
			if tbl.ruledVLines then
				local showV = (style == "t5_ruled")
				for i, ln in pairs(tbl.ruledVLines) do
					if showV and tbl.colX[i] then
						ln:ClearAllPoints()
						ln:SetPoint("TOPLEFT", tbl.inset, "TOPLEFT", tbl.colX[i] + 3, 0)
						ln:SetPoint("BOTTOMLEFT", tbl.inset, "BOTTOMLEFT", tbl.colX[i] + 3, 2)
						ln:SetColorTexture(fb[1], fb[2], fb[3], 0.18)
						ln:Show()
					else
						ln:Hide()
					end
				end
			end
		end
	end
	tbl.paintTableChrome = paintTableChrome

	function tbl.updateHeaders()
		local st = tabKey and app.sortState[tabKey] or nil
		local style = activeTableStyle()
		local styled = (style == "t5_ruled" or style == "t5_well" or style == "t3_strips")
		local pal = ns.Theme.PALETTE or ns.Theme.COLORS
		local activeCol = (pal and pal.text) or { 0.96, 0.96, 0.97, 1 }
		local mutedCol = styled and (pal and (pal.gold or pal.text)) or (pal and (pal.textTertiary or pal.textMuted)) or { 0.58, 0.58, 0.62, 1 }
		local blueCol = (pal and pal.accentBlue) or { 0.04, 0.52, 1.0, 1 }
		local fb = (pal and pal.frameBorder) or { 0.75, 0.56, 0.18, 1 }
		local chevronPath = (ns.Theme.ASSETS and ns.Theme.ASSETS.icon_chevron_down) or "Interface\\AddOns\\MerchantMaster\\Assets\\apple\\icon_chevron_down"
		for i, col in ipairs(columns) do
			local btn = tbl.headerBtns[i]
			local lbl = col.label or ""
			local dispLbl = styled and string.upper(lbl) or lbl
			if st and col.key == st.col then
				local r255 = math.floor((blueCol[1] or 0.04) * 255 + 0.5)
				local g255 = math.floor((blueCol[2] or 0.52) * 255 + 0.5)
				local b255 = math.floor((blueCol[3] or 1.0) * 255 + 0.5)
				local arrow = st.asc
					and string.format(" |T%s:9:9:0:0:32:32:0:32:32:0:%d:%d:%d|t", chevronPath, r255, g255, b255)
					or  string.format(" |T%s:9:9:0:0:32:32:0:32:0:32:%d:%d:%d|t", chevronPath, r255, g255, b255)
				btn.fs:SetText(dispLbl .. arrow)
				btn.fs:SetTextColor(activeCol[1], activeCol[2], activeCol[3], 1)
				btn.bg:SetColorTexture(blueCol[1], blueCol[2], blueCol[3], (style == "t3_strips") and 0.14 or 0.08)
			else
				btn.fs:SetText(dispLbl)
				btn.fs:SetTextColor(mutedCol[1], mutedCol[2], mutedCol[3], mutedCol[4] or 1)
				btn.bg:SetColorTexture(0, 0, 0, 0)
			end
			if btn.sep and pal then
				if style == "t5_ruled" and isRuledGroupCol(i, #columns) then
					btn.sep:SetColorTexture(fb[1], fb[2], fb[3], 0.42)
				else
					local sepC = pal.glassSep or pal.separator or { 1, 1, 1, 0.08 }
					btn.sep:SetColorTexture(sepC[1], sepC[2], sepC[3], (sepC[4] or 0.08) * 0.75)
				end
			end
		end
		if pal then
			if styled then
				hUnderline:SetColorTexture(0, 0, 0, 0)
			else
				local sepC = pal.glassSep or pal.separator or { 1, 1, 1, 0.08 }
				hUnderline:SetColorTexture(sepC[1], sepC[2], sepC[3], sepC[4] or 0.08)
			end
		end
		paintTableChrome()
	end

	for i, col in ipairs(columns) do
		local btn = CreateFrame("Button", nil, headerBar)
		btn:SetSize(col.width, 24)
		btn:SetPoint("LEFT", headerBar, "LEFT", tbl.colX[i], 1)
		local bg = btn:CreateTexture(nil, "BACKGROUND")
		bg:SetAllPoints()
		bg:SetColorTexture(0, 0, 0, 0)
		btn.bg = bg
		if i > 1 then
			local sep = btn:CreateTexture(nil, "BORDER")
			sep:SetSize(1, 12)
			sep:SetPoint("LEFT", btn, "LEFT", -math.ceil(COL_GAP * 0.5), 0)
			sep:SetColorTexture(initSep[1], initSep[2], initSep[3], (initSep[4] or 0.08) * 0.75)
			btn.sep = sep
		end
		local hl = btn:CreateTexture(nil, "HIGHLIGHT")
		hl:SetAllPoints()
		local hc = (ns.Theme.PALETTE and ns.Theme.PALETTE.glassHover) or { 1, 1, 1, 0.06 }
		hl:SetColorTexture(hc[1], hc[2], hc[3], hc[4] or 0.06)
		btn.fs = btn:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
		btn.fs:SetPoint("LEFT", 3, 0)
		btn.fs:SetPoint("RIGHT", -3, 0)
		btn.fs:SetJustifyH(col.align)
		btn.fs:SetWordWrap(false)
		applySafeFont(btn.fs, 11, "regular")
		if tabKey and col.key then
			btn:SetScript("OnClick", function()
				local st = app.sortState[tabKey]
				if not st then return end
				if st.col == col.key then
					st.asc = not st.asc
				else
					st.col = col.key
					st.asc = (col.defaultAsc ~= false)
				end
				if MerchantMasterDB and MerchantMasterDB.sort then
					MerchantMasterDB.sort[tabKey] = { col = st.col, asc = st.asc }
				end
				tbl.updateHeaders()
				if tabKey == "shopping_list" and app.refreshUnifiedShoppingDisplay then
					app.refreshUnifiedShoppingDisplay()
				else
					app.refresh()
				end
			end)
		end
		if col.hint then
			btn:SetScript("OnEnter", function(self)
				GameTooltip:SetOwner(self, "ANCHOR_TOP")
				GameTooltip:AddLine(col.label, 1, 0.82, 0)
				GameTooltip:AddLine(col.hint, 1, 1, 1, true)
				GameTooltip:Show()
			end)
			btn:SetScript("OnLeave", GameTooltip_Hide)
		end
		tbl.headerBtns[i] = btn
	end

	if ns.Theme and ns.Theme.RegisterWidget then
		ns.Theme.RegisterWidget(headerBar, function()
			tbl.updateHeaders()
		end)
	end

	local padBottom = (opts and opts.bottomPad) or bottomOffset or 0
	local inset
	if opts and opts.transparentInset then
		inset = CreateFrame("Frame", nil, parent)
		inset:SetPoint("TOPLEFT", 0, topOffset - headerGap)
		inset:SetPoint("BOTTOMRIGHT", 0, padBottom)
	else
		inset = CreateFrame("Frame", nil, parent, "InsetFrameTemplate")
		inset:SetPoint("TOPLEFT", 0, topOffset - headerGap)
		inset:SetPoint("BOTTOMRIGHT", 0, padBottom)
		applyListBackground(inset)
	end
	tbl.inset = inset
	do
		-- Dedicated underlay frame for full-width header art + recessed well backdrop (immune to inset region clears)
		local baseLvl = (inset.GetFrameLevel and inset:GetFrameLevel()) or 1
		local wellBgFrame = CreateFrame("Frame", nil, parent)
		wellBgFrame:SetPoint("TOPLEFT", inset, "TOPLEFT", 0, 27)
		wellBgFrame:SetPoint("BOTTOMRIGHT", inset, "BOTTOMRIGHT", 0, 0)
		if wellBgFrame.SetFrameLevel then wellBgFrame:SetFrameLevel(baseLvl + 1) end
		if headerBar.SetFrameLevel then headerBar:SetFrameLevel(baseLvl + 2) end
		if wellBgFrame.EnableMouse then wellBgFrame:EnableMouse(false) end

		local hSkinBg = wellBgFrame:CreateTexture(nil, "BACKGROUND", nil, 0)
		hSkinBg:SetPoint("TOPLEFT", wellBgFrame, "TOPLEFT", 0, 0)
		hSkinBg:SetPoint("TOPRIGHT", wellBgFrame, "TOPRIGHT", 0, 0)
		hSkinBg:SetHeight(27)
		hSkinBg:Hide()
		tbl.headerSkinBg = hSkinBg

		local hSkinSep = wellBgFrame:CreateTexture(nil, "BORDER", nil, 1)
		hSkinSep:SetPoint("TOPLEFT", wellBgFrame, "TOPLEFT", 0, -27)
		hSkinSep:SetPoint("TOPRIGHT", wellBgFrame, "TOPRIGHT", 0, -27)
		hSkinSep:SetHeight(1)
		hSkinSep:Hide()
		tbl.headerSkinSep = hSkinSep

		local wellBgTex = wellBgFrame:CreateTexture(nil, "BACKGROUND", nil, -1)
		wellBgTex:SetPoint("TOPLEFT", wellBgFrame, "TOPLEFT", 0, -27)
		wellBgTex:SetPoint("BOTTOMRIGHT", wellBgFrame, "BOTTOMRIGHT", 0, 0)
		wellBgTex:Hide()
		tbl.wellBgTex = wellBgTex
		tbl.wellBgFrame = wellBgFrame

		-- Dedicated overlay frame wrapping BOTH headerBar + inset with 1px brass border, 4 mini-corners & vertical rules
		local skinFrame = CreateFrame("Frame", nil, parent)
		skinFrame:SetPoint("TOPLEFT", inset, "TOPLEFT", 0, 27)
		skinFrame:SetPoint("BOTTOMRIGHT", inset, "BOTTOMRIGHT", 0, 0)
		if inset.GetFrameLevel and skinFrame.SetFrameLevel then
			skinFrame:SetFrameLevel(inset:GetFrameLevel() + 6)
		end
		if skinFrame.EnableMouse then skinFrame:EnableMouse(false) end
		tbl.skinFrame = skinFrame

		local edges = {}
		local specs = {
			top    = { "TOPLEFT", "TOPRIGHT", 1, true },
			bottom = { "BOTTOMLEFT", "BOTTOMRIGHT", 1, true },
			left   = { "TOPLEFT", "BOTTOMLEFT", 1, false },
			right  = { "TOPRIGHT", "BOTTOMRIGHT", 1, false },
		}
		for k, sp in pairs(specs) do
			local e = skinFrame:CreateTexture(nil, "OVERLAY", nil, 2)
			e:SetPoint(sp[1], skinFrame, sp[1], 0, 0)
			e:SetPoint(sp[2], skinFrame, sp[2], 0, 0)
			if sp[4] then e:SetHeight(sp[3]) else e:SetWidth(sp[3]) end
			e:Hide()
			edges[k] = e
		end
		tbl.insetSkinEdges = edges

		local corners = {}
		local cSpecs = {
			TL = { "TOPLEFT",     -2,  2, 0, 1, 0, 1 },
			TR = { "TOPRIGHT",     2,  2, 1, 0, 0, 1 },
			BL = { "BOTTOMLEFT",  -2, -2, 0, 1, 1, 0 },
			BR = { "BOTTOMRIGHT",  2, -2, 1, 0, 1, 0 },
		}
		for k, cs in pairs(cSpecs) do
			local c = skinFrame:CreateTexture(nil, "OVERLAY", nil, 4)
			c:SetSize(24, 24)
			c:SetPoint(cs[1], skinFrame, cs[1], cs[2], cs[3])
			c:SetTexCoord(cs[4], cs[5], cs[6], cs[7])
			c:Hide()
			corners[k] = c
		end
		tbl.insetMiniCorners = corners

		local vlines = {}
		for i = 2, #columns do
			if isRuledGroupCol(i, #columns) then
				local ln = skinFrame:CreateTexture(nil, "ARTWORK", nil, 1)
				ln:SetWidth(1)
				ln:Hide()
				vlines[i] = ln
			end
		end
		tbl.ruledVLines = vlines
		if ns.Theme and ns.Theme.RegisterWidget then
			ns.Theme.RegisterWidget(skinFrame, paintTableChrome)
		end
		paintTableChrome()
	end

	local scrollBox = CreateFrame("Frame", nil, inset, "WowScrollBoxList")
	if inset.GetFrameLevel and scrollBox.SetFrameLevel then scrollBox:SetFrameLevel(inset:GetFrameLevel() + 2) end
	scrollBox:SetPoint("TOPLEFT", 6, -5)
	scrollBox:SetPoint("BOTTOMRIGHT", -16, 5)
	local scrollBar = CreateFrame("EventFrame", nil, inset, "MinimalScrollBar")
	scrollBar:SetPoint("TOPLEFT", scrollBox, "TOPRIGHT", 5, -2)
	scrollBar:SetPoint("BOTTOMLEFT", scrollBox, "BOTTOMRIGHT", 5, 2)
	ns.Theme.SlimScrollBar(scrollBar)
	tbl.scrollBox = scrollBox

	local linearView = CreateScrollBoxListLinearView()
	if opts and opts.extentCalculator and linearView.SetElementExtentCalculator then
		linearView:SetElementExtentCalculator(opts.extentCalculator)
	else
		linearView:SetElementExtent(rowH)
	end
	linearView:SetElementInitializer("Button", function(r, data)
		local firstInit = (r.cells == nil)
		initRowFn(r, data, tbl)
		if firstInit and r.cells and not (opts and opts.preparedCells) then
			for _, cell in ipairs(r.cells) do
				local fs = (type(cell) == "table" and cell.fs) or cell
				if fs and fs.SetFont then
					applySafeFont(fs, opts and opts.cellFontSize or 11, fs._mmIsBold and "semibold" or "regular")
				end
			end
			-- Cell text is theme-translated at render time; data-model strings keep their raw codes.
			ns.Theme.AutoThemeCells(r)
		end
		if r.cells and not (opts and opts.preserveCellColors) then
			local tc = getPal().text
			if tc then
				for _, cell in ipairs(r.cells) do
					local fs = (type(cell) == "table" and cell.fs) or cell
					if fs and fs.SetTextColor then fs:SetTextColor(tc[1], tc[2], tc[3], 1) end
				end
			end
		end
		if tbl.layoutRow and r._layoutEpoch ~= tbl._layoutEpoch then tbl.layoutRow(r) end
	end)
	ScrollUtil.InitScrollBoxListWithScrollBar(scrollBox, scrollBar, linearView)

	function tbl.setRows(rows)
		for idx, r in ipairs(rows) do r.rowIndex = idx end
		scrollBox:SetDataProvider(CreateDataProvider(rows), ScrollBoxConstants and ScrollBoxConstants.RetainScrollPosition or true)
	end

	return tbl
end
