-- Reusable Online Shopping Sales Cart Panel (Option A V2: Baron Two-Column E-Commerce Cards)
local function createShoppingListPanel(parent, height, fillParent, topOffset, modal)
	local wrap = CreateFrame("Frame", nil, parent)
	if fillParent then
		wrap:SetPoint("TOPLEFT", 0, topOffset or 0)
		wrap:SetPoint("BOTTOMRIGHT", 0, 0)
	else
		wrap:SetPoint("BOTTOMLEFT", 0, 0)
		wrap:SetPoint("BOTTOMRIGHT", 0, 0)
		wrap:SetHeight(height)
	end

	local RAIL_W = 318
	local RAIL_GAP = 14
	local hdrHost = (modal and modal.header) or wrap

	-- Lush Header Pills mounted inside shopModal.header (ZERO extra stacked bars!)
	local sortScopeBtn = CreateFrame("Button", nil, hdrHost)
	sortScopeBtn:SetSize(124, 26)
	if modal and modal.closeBtn then
		sortScopeBtn:SetPoint("RIGHT", modal.closeBtn, "LEFT", -8, 0)
	else
		sortScopeBtn:SetPoint("TOPRIGHT", -2, 0)
	end
	sortScopeBtn.plate = ns.Theme.NineApple(sortScopeBtn, "glass_r8", "cardAltBg", "frameBorder", { cornerSize = 8, noSpecular = true })
	sortScopeBtn.fs = sortScopeBtn:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
	sortScopeBtn.fs:SetAllPoints(sortScopeBtn)
	sortScopeBtn.fs:SetJustifyH("CENTER")
	sortScopeBtn.fs:SetWordWrap(false)
	applySafeFont(sortScopeBtn.fs, 11, "semibold")
	function sortScopeBtn:SetText(txt) self.fs:SetText(txt or "") end
	function sortScopeBtn:GetText() return self.fs:GetText() or "" end
	sortScopeBtn:SetText("Sort: Main Items")
	sortScopeBtn:SetScript("OnClick", function()
		if not MerchantMasterDB then return end
		local cur = (MerchantMasterDB.shoppingSortScope == "sub") and "sub" or "main"
		MerchantMasterDB.shoppingSortScope = (cur == "main") and "sub" or "main"
		if app.refreshUnifiedShoppingDisplay then
			app.refreshUnifiedShoppingDisplay()
		elseif app.refresh then
			app.refresh()
		end
	end)
	sortScopeBtn:SetScript("OnEnter", function(self)
		GameTooltip:SetOwner(self, "ANCHOR_TOP")
		GameTooltip:AddLine("Shopping Cart Sort Mode", 1, 0.82, 0)
		GameTooltip:AddLine("Main Items: keeps Main Orders, their Sub-Crafts, and raw materials grouped together while sorting Main Orders.\nSub-Items: sorts all Direct Sub-Items globally while keeping crafted sub-breakdowns attached underneath.", 1, 1, 1, true)
		GameTooltip:Show()
	end)
	sortScopeBtn:SetScript("OnLeave", GameTooltip_Hide)
	wrap.sortScopeBtn = sortScopeBtn

	local useOwnedBtn = CreateFrame("Button", nil, hdrHost)
	useOwnedBtn:SetSize(124, 26)
	useOwnedBtn:SetPoint("RIGHT", sortScopeBtn, "LEFT", -6, 0)
	useOwnedBtn.plate = ns.Theme.NineApple(useOwnedBtn, "glass_r8", "pillBuyBg", "pillBuyBorder", { cornerSize = 8, noSpecular = true })
	useOwnedBtn.dot = useOwnedBtn:CreateTexture(nil, "ARTWORK")
	useOwnedBtn.dot:SetSize(7, 7)
	useOwnedBtn.dot:SetPoint("LEFT", 10, 0)
	useOwnedBtn.dot:SetTexture(ns.Theme.ASSETS.circle_fill)
	useOwnedBtn.fs = useOwnedBtn:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
	useOwnedBtn.fs:SetPoint("LEFT", useOwnedBtn.dot, "RIGHT", 6, 0)
	useOwnedBtn.fs:SetPoint("RIGHT", -8, 0)
	useOwnedBtn.fs:SetJustifyH("LEFT")
	useOwnedBtn.fs:SetWordWrap(false)
	applySafeFont(useOwnedBtn.fs, 11, "semibold")
	function useOwnedBtn:SetText(txt) self.fs:SetText(txt or "") end
	function useOwnedBtn:GetText() return self.fs:GetText() or "" end
	useOwnedBtn:SetText("Use Owned: On")
	useOwnedBtn:SetScript("OnClick", function()
		MerchantMasterDB = MerchantMasterDB or {}
		MerchantMasterDB.craftOrderDeductOwned = not (MerchantMasterDB.craftOrderDeductOwned == true)
		MerchantMasterDB.migratedShoppingUseOwned = true
		if app.refreshUnifiedShoppingDisplay then
			app.refreshUnifiedShoppingDisplay()
		elseif app.refresh then
			app.refresh()
		end
	end)
