	local function syncRailHdrTile(isCustom, skinKey)
		if isCustom == nil then
			isCustom = ns.Theme.IsCustomSkin and ns.Theme.IsCustomSkin()
		end
		if not skinKey then
			skinKey = isCustom and ns.Theme.GetSkin and ns.Theme.GetSkin() or "standard"
		end
		if isCustom and ns.Theme.GetSkinAsset then
			local tileTex = ns.Theme.GetSkinAsset(skinKey, "header_tile")
			if tileTex then
				railHdrTile:SetTexture(tileTex, "REPEAT", "REPEAT")
				if railHdrTile.SetHorizTile then railHdrTile:SetHorizTile(false) end
				if railHdrTile.SetVertTile then railHdrTile:SetVertTile(false) end
				local rw = (railHdr.GetWidth and railHdr:GetWidth()) or 0
				local rh = (railHdr.GetHeight and railHdr:GetHeight()) or 0
				if rw <= 0 then rw = RAIL_W - 4 end
				if rh <= 0 then rh = 34 end
				railHdrTile:SetTexCoord(0, math.max(0.25, rw / 210), 0, math.max(0.10, rh / 210))
				railHdrTile:SetVertexColor(1, 1, 1, 1)
				railHdrTile:Show()
			else
				railHdrTile:Hide()
			end
		else
			railHdrTile:Hide()
		end
	end

