	local function makeSummaryBucket(parentFrame, topY, h, leftOff, rightOff, opts)
		opts = opts or {}
		local card = CreateFrame("Frame", nil, parentFrame)
		card:SetPoint("TOPLEFT", parentFrame, "TOPLEFT", leftOff or 12, topY)
		card:SetPoint("TOPRIGHT", parentFrame, "TOPRIGHT", rightOff or -12, topY)
		card:SetHeight(h)
		card.plate = ns.Theme.NineApple(card, opts.kind or "glass_r10", "cardBg", "border", { cornerSize = opts.corner or 10, noSpecular = true })
		if opts.useGradient then
			card.gradTex = card:CreateTexture(nil, "BACKGROUND", nil, 1)
			card.gradTex:SetPoint("TOPLEFT", card, "TOPLEFT", 2, -2)
			card.gradTex:SetPoint("BOTTOMRIGHT", card, "BOTTOMRIGHT", -2, 2)
		end
		card.bar = card:CreateTexture(nil, "ARTWORK")
		card.bar:SetPoint("TOPLEFT", 2, -4)
		card.bar:SetPoint("BOTTOMLEFT", 2, 4)
		card.bar:SetWidth(3)
		if opts.hideBar then card.bar:Hide() end

		local labelLeft = 12
		if opts.icon then
			card.icon = card:CreateTexture(nil, "ARTWORK")
			card.icon:SetSize(13, 13)
			card.icon:SetPoint("TOPLEFT", 11, -8)
			card.icon:SetTexture(opts.icon)
			labelLeft = 28
		end

		card.labelFs = card:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
		card.labelFs:SetPoint("TOPLEFT", labelLeft, -8)
		card.labelFs:SetJustifyH("LEFT")
		card.labelFs:SetWordWrap(false)
