		card.valFs = card:CreateFontString(nil, "OVERLAY", "GameFontNormal")
		card.valFs:SetPoint("TOPRIGHT", -10, -7)
		card.valFs:SetJustifyH("RIGHT")
		card.valFs:SetWordWrap(false)
