		card.subFs = card:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
		card.subFs:SetPoint("BOTTOMLEFT", 12, 8)
		card.subFs:SetJustifyH("LEFT")
		card.subFs:SetWordWrap(false)
