		else
			card.tagFs = card:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
			card.tagFs:SetPoint("BOTTOMRIGHT", -10, 7)
			card.tagFs:SetWidth(rightOff and 68 or 118)
			card.tagFs:SetJustifyH("RIGHT")
			card.tagFs:SetWordWrap(false)
			applySafeFont(card.tagFs, 10, "semibold")
		end
		return card
	end

	local ahCard = makeSummaryBucket(summaryRail, -46, 56, 12, -12, { kind = "glass_r10", icon = ns.Theme.ASSETS.icon_basket, valSize = 13, useGradient = true })
	local craftCard = makeSummaryBucket(summaryRail, -110, 60, 12, -12, { kind = "glass_r10", icon = ns.Theme.ASSETS.icon_flask, tagPill = true, valSize = 12, useGradient = true })
