	-- HERO 54px "Send to Auction House" CTA Button (vertical emerald gradient + skin send_btn icon + specular sheen)
	local buyAllBtn = CreateFrame("Button", nil, summaryRail)
	buyAllBtn:SetPoint("TOPLEFT", 12, -304)
	buyAllBtn:SetPoint("TOPRIGHT", -12, -304)
	buyAllBtn:SetHeight(54)
