	}

	local function showShoppingRowTooltip(owner, row)
		GameTooltip:SetOwner(owner, "ANCHOR_RIGHT")
		suppressCratePostCall = true
		if row.itemID and GameTooltip.SetItemByID then
			GameTooltip:SetItemByID(row.itemID)
		elseif row.itemID then
			GameTooltip:SetHyperlink("item:" .. row.itemID)
		else
			GameTooltip:AddLine(row.name, 1, 1, 1)
		end
		suppressCratePostCall = false
		if row.itemID and ns.AppendCrateTooltip then
			ns.AppendCrateTooltip(GameTooltip, row.itemID)
		end
		if row.isMainRow then
			GameTooltip:AddLine(" ")
			GameTooltip:AddDoubleLine("Main Order Category:", string.format("%dx (%s)", row.qty or 1, tostring(row.sourceLabel or "Order")), 1, 0.82, 0, 1, 1, 1)
			GameTooltip:AddDoubleLine("Total Order Cost:", ns.FormatMoneyCompact(row.groupTotalCost), 0.85, 0.85, 0.85, 0.4, 1, 0.6)
			if row.canRemoveMain then
				GameTooltip:AddLine("Use [- / +] to adjust order count, or click × to remove this Main Order.", 1, 0.65, 0.65, true)
			end
			if ns.Theme and ns.Theme.LiftTooltip then ns.Theme.LiftTooltip(GameTooltip) end
			GameTooltip:Show()
			return
		end
		GameTooltip:AddLine(" ")
		GameTooltip:AddLine("Shopping Cart Pricing (" .. tostring(row.qty) .. "x needed)", 1, 0.82, 0)
		if row.categoryName then
			GameTooltip:AddDoubleLine("Main Order:", tostring(row.categoryName), 0.85, 0.85, 0.85, 1, 0.88, 0.48)
		end
		if row.parentSubName then
			GameTooltip:AddDoubleLine("Crafted Sub-Item:", tostring(row.parentSubName), 0.85, 0.85, 0.85, 0.53, 0.87, 1)
		end
		local ahTag = row.isVendor and "NPC Vendor" or (row.ahSource or "AH")
		GameTooltip:AddDoubleLine("Buy Option (" .. ahTag .. "):",
			row.ahTotalPrice and (ns.FormatMoneyCompact(row.ahUnitPrice) .. " ea  ->  " .. ns.FormatMoneyCompact(row.ahTotalPrice)) or "Unlisted",
			0.85, 0.85, 0.85, 1, 1, 1)
		if row.craftUnitPrice then
			local hasCraftCD = (row.craftCD or 0) >= 60
			local cdPerStr = row.craftCDLabel or "CD"
			GameTooltip:AddDoubleLine("Craft Option (" .. (row.craftProfLabel or "Recipe") .. (hasCraftCD and (", " .. cdPerStr .. " CD") or "") .. "):",
				ns.FormatMoneyCompact(row.craftUnitPrice) .. " ea  ->  " .. ns.FormatMoneyCompact(row.craftTotalPrice),
				0.85, 0.85, 0.85, 0.78, 0.62, 1)
			if row.ahTotalPrice ~= nil and row.craftTotalPrice ~= nil and row.qty and row.qty > 0 then
				local diff = row.ahTotalPrice - row.craftTotalPrice
				if diff > 0 then
					GameTooltip:AddDoubleLine("Best Price Option:", "Craft saves " .. ns.FormatMoneyCompact(diff), 0.85, 0.85, 0.85, 0.3, 1, 0.45)
				elseif diff < 0 then
					GameTooltip:AddDoubleLine("Best Price Option:", "Buy AH saves " .. ns.FormatMoneyCompact(-diff), 0.85, 0.85, 0.85, 1, 0.82, 0.3)
				end
			end
		end
		if not row.isVendor then
			local salesHdr = (ns.HasSnapshots and ns.HasSnapshots()) and "AH Stock / Snapshot Sales:" or "AH Stock / Est. Daily Sales:"
			GameTooltip:AddDoubleLine(salesHdr,
				string.format("%s listed  ·  %s / day", row.listed ~= nil and tostring(row.listed) or "—", row.dailySold ~= nil and string.format("%.2f", row.dailySold) or "—"),
				0.85, 0.85, 0.85, 0.5, 0.9, 1)
		end
		GameTooltip:AddLine(" ")
		GameTooltip:AddLine("Click Row: search " .. tostring(row.qty) .. "x on Auction House", 0.65, 0.85, 1)
		if row.canToggleCraft then
			GameTooltip:AddLine("Click pill: toggle Craft Yourself vs Buy AH  ·  Right-Click: Auto", 0.75, 0.65, 1)
		end
		if ns.Theme and ns.Theme.LiftTooltip then ns.Theme.LiftTooltip(GameTooltip) end
		GameTooltip:Show()
	end

	local function searchShoppingRow(row)
		local name = not row.itemID and row.name or nil
		app.searchAH(name, row.isMainRow and 1 or row.qty, row.itemID)
	end

	local function shortProfTag(profLabel)
		local p = tostring(profLabel or ""):lower()
		if p:find("alch", 1, true) then return "ALCH"
		elseif p:find("black", 1, true) then return "BS"
		elseif p:find("ench", 1, true) then return "ENCH"
		elseif p:find("eng", 1, true) then return "ENG"
		elseif p:find("leath", 1, true) then return "LW"
		elseif p:find("tail", 1, true) then return "TAIL"
		elseif p:find("cook", 1, true) then return "COOK"
		elseif p:find("first", 1, true) then return "FA"
		elseif p:find("mine", 1, true) or p:find("smelt", 1, true) then return "SMELT"
		elseif p ~= "" then return string.upper(p:sub(1, 4)) end
		return nil
	end

	local function shopRowExtent(_, data)
		if not data then return 30 end
		local baseH
		if data.isMainRow then
			baseH = 48
		elseif data.makeMyself or data.canToggleCraft then
			baseH = 34
		else
			baseH = 30
		end
		return baseH + (data._isGroupLast and 8 or 0)
	end

