					toggleSubCraftOverride(d.overrideKey or d.itemID, d.makeMyself, mouseBtn, d.itemID)
				elseif not d.isMainRow and not d.isVendor then
					searchShoppingRow(d)
				end
			end)

			-- Stacked Cost Column (r.cells[9]): optional micro-label "ORDER COST" on Main Orders + bold right-aligned gold total
			local costLblFs = card:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
			costLblFs:SetWidth(84)
			costLblFs:SetJustifyH("RIGHT")
			costLblFs:SetWordWrap(false)
			applySafeFont(costLblFs, 9, "semibold")
			costLblFs:SetText("ORDER COST")
			r.costLblFs = costLblFs

			local costFs = card:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
			costFs:SetWidth(84)
			costFs:SetJustifyH("RIGHT")
			costFs:SetWordWrap(false)
			applySafeFont(costFs, 12, "semibold")

			-- Optically Centered [-  qty  +] Stepper Pill with clickable inline numeric EditBox (r.cells[3])
			local qWrap = CreateFrame("Frame", nil, card)
			qWrap:SetSize(90, 26)
			qWrap.plate = ns.Theme.NineApple(qWrap, "glass_r8", "cardAltBg", "cartMainAccent", { cornerSize = 6, noSpecular = true })
			local minusBtn = CreateFrame("Button", nil, qWrap)
			minusBtn:SetSize(24, 22)
			minusBtn:SetPoint("LEFT", qWrap, "LEFT", 2, 0)
			minusBtn.bg = minusBtn:CreateTexture(nil, "BACKGROUND")
			minusBtn.bg:SetAllPoints()
			minusBtn.div = qWrap:CreateTexture(nil, "BORDER")
			minusBtn.div:SetSize(1, 20); minusBtn.div:SetPoint("LEFT", minusBtn, "RIGHT", 0, 0)
			minusBtn.fs = minusBtn:CreateFontString(nil, "OVERLAY", "GameFontNormal")
			minusBtn.fs:SetAllPoints()
			minusBtn.fs:SetJustifyH("CENTER")
			minusBtn.fs:SetJustifyV("MIDDLE")
			applySafeFont(minusBtn.fs, 13, "semibold")
			minusBtn.fs:SetText("-")
			minusBtn:SetScript("OnClick", function()
				local d = r.data
				if d and d.isMainRow and d.removeRef and app.adjustShoppingMainQty then
					app.adjustShoppingMainQty(d.removeRef, -1)
				end
			end)

			local plusBtn = CreateFrame("Button", nil, qWrap)
			plusBtn:SetSize(24, 22)
			plusBtn:SetPoint("RIGHT", qWrap, "RIGHT", -2, 0)
			plusBtn.bg = plusBtn:CreateTexture(nil, "BACKGROUND")
			plusBtn.bg:SetAllPoints()
			plusBtn.div = qWrap:CreateTexture(nil, "BORDER")
			plusBtn.div:SetSize(1, 20); plusBtn.div:SetPoint("RIGHT", plusBtn, "LEFT", 0, 0)
			plusBtn.fs = plusBtn:CreateFontString(nil, "OVERLAY", "GameFontNormal")
			plusBtn.fs:SetAllPoints()
			plusBtn.fs:SetJustifyH("CENTER")
			plusBtn.fs:SetJustifyV("MIDDLE")
			applySafeFont(plusBtn.fs, 13, "semibold")
			plusBtn.fs:SetText("+")
			plusBtn:SetScript("OnClick", function()
				local d = r.data
				if d and d.isMainRow and d.removeRef and app.adjustShoppingMainQty then
					app.adjustShoppingMainQty(d.removeRef, 1)
				end
			end)

			local qFs = qWrap:CreateFontString(nil, "OVERLAY", "GameFontNormal")
			qFs:SetPoint("TOPLEFT", minusBtn, "TOPRIGHT", 1, 0)
			qFs:SetPoint("BOTTOMRIGHT", plusBtn, "BOTTOMLEFT", -1, 0)
			qFs:SetJustifyH("CENTER")
			qFs:SetJustifyV("MIDDLE")
			qFs:SetWordWrap(false)
			applySafeFont(qFs, 12, "semibold")

			-- Clickable center number slot + inline numeric EditBox (Enter applies, Esc cancels without closing shopModal)
			local qtyBtn = CreateFrame("Button", nil, qWrap)
			qtyBtn:SetPoint("TOPLEFT", minusBtn, "TOPRIGHT", 1, 0)
			qtyBtn:SetPoint("BOTTOMRIGHT", plusBtn, "BOTTOMLEFT", -1, 0)
			qtyBtn.hl = qtyBtn:CreateTexture(nil, "HIGHLIGHT")
			qtyBtn.hl:SetAllPoints(qtyBtn)
			qtyBtn.hl:SetColorTexture(1, 0.92, 0.62, 0.16)

			local qtyEdit = CreateFrame("EditBox", nil, qWrap)
			qtyEdit:SetPoint("TOPLEFT", minusBtn, "TOPRIGHT", 1, 0)
			qtyEdit:SetPoint("BOTTOMRIGHT", plusBtn, "BOTTOMLEFT", -1, 0)
			if qtyEdit.SetFontObject then qtyEdit:SetFontObject("GameFontNormal") end
			applySafeFont(qtyEdit, 12, "semibold")
			qtyEdit:SetAutoFocus(false)
			qtyEdit:SetNumeric(true)
			qtyEdit:SetMaxLetters(4)
			qtyEdit:SetJustifyH("CENTER")
			if qtyEdit.SetTextInsets then qtyEdit:SetTextInsets(2, 2, 0, 0) end
			qtyEdit.bg = qtyEdit:CreateTexture(nil, "BACKGROUND")
			qtyEdit.bg:SetAllPoints(qtyEdit)
			qtyEdit.bg:SetColorTexture(0.03, 0.09, 0.06, 0.98)
			qtyEdit.bdTop = qtyEdit:CreateTexture(nil, "BORDER"); qtyEdit.bdTop:SetHeight(1); qtyEdit.bdTop:SetPoint("TOPLEFT", 0, 0); qtyEdit.bdTop:SetPoint("TOPRIGHT", 0, 0)
			qtyEdit.bdBot = qtyEdit:CreateTexture(nil, "BORDER"); qtyEdit.bdBot:SetHeight(1); qtyEdit.bdBot:SetPoint("BOTTOMLEFT", 0, 0); qtyEdit.bdBot:SetPoint("BOTTOMRIGHT", 0, 0)
			qtyEdit.bdL = qtyEdit:CreateTexture(nil, "BORDER"); qtyEdit.bdL:SetWidth(1); qtyEdit.bdL:SetPoint("TOPLEFT", 0, 0); qtyEdit.bdL:SetPoint("BOTTOMLEFT", 0, 0)
			qtyEdit.bdR = qtyEdit:CreateTexture(nil, "BORDER"); qtyEdit.bdR:SetWidth(1); qtyEdit.bdR:SetPoint("TOPRIGHT", 0, 0); qtyEdit.bdR:SetPoint("BOTTOMRIGHT", 0, 0)
			qtyEdit:Hide()

			local function closeQtyEdit(restoreBtn)
				qtyEdit:Hide()
				qFs:Show()
				if restoreBtn then
					local d = r.data
					qtyBtn:SetShown(d ~= nil and d.isMainRow == true and d.removeRef ~= nil)
				end
			end

			qtyBtn:SetScript("OnEnter", function(self)
				if GameTooltip then
					GameTooltip:SetOwner(self, "ANCHOR_TOP")
					GameTooltip:SetText("Click to enter an exact quantity (Enter to apply, Esc to cancel)", 1, 1, 1, 1, true)
					GameTooltip:Show()
				end
			end)
			qtyBtn:SetScript("OnLeave", GameTooltip_Hide)
			qtyBtn:SetScript("OnClick", function()
				local d = r.data
				if not (d and d.isMainRow and d.removeRef) then return end
				local cur = math.max(1, math.floor((tonumber(d.qty) or 1) + 0.5))
				qtyEdit._cancelled = nil
				qtyEdit._committing = nil
				qtyEdit._startQty = cur
				qtyEdit:SetText(tostring(cur))
				qFs:Hide()
				qtyBtn:Hide()
				qtyEdit:Show()
				if qtyEdit.SetFocus then qtyEdit:SetFocus() end
				if qtyEdit.HighlightText then qtyEdit:HighlightText() end
			end)

			qtyEdit:SetScript("OnEnterPressed", function(self)
				local d = r.data
				local raw = self:GetText()
				self._committing = true
				self._cancelled = nil
				closeQtyEdit(true)
				if self.ClearFocus then self:ClearFocus() end
				local n = tonumber(raw)
				if d and d.isMainRow and d.removeRef and n and app.setShoppingMainQty then
					app.setShoppingMainQty(d.removeRef, n)
				end
				self._committing = nil
			end)
			qtyEdit:SetScript("OnEscapePressed", function(self)
				self._cancelled = true
				self._committing = nil
				closeQtyEdit(true)
				if self.ClearFocus then self:ClearFocus() end
			end)
			qtyEdit:SetScript("OnEditFocusLost", function(self)
				if self._cancelled or self._committing then
					self._cancelled = nil
					closeQtyEdit(true)
					return
				end
				local d = r.data
				local raw = self:GetText()
				local startQty = self._startQty
				self._committing = true
				closeQtyEdit(true)
				local n = tonumber(raw)
				if d and d.isMainRow and d.removeRef and n and math.floor(n) ~= startQty and app.setShoppingMainQty then
					app.setShoppingMainQty(d.removeRef, n)
				end
				self._committing = nil
			end)

			qWrap.minusBtn, qWrap.plusBtn, qWrap.fs = minusBtn, plusBtn, qFs
			qWrap.qtyBtn, qWrap.qtyEdit = qtyBtn, qtyEdit
			function qWrap:GetText() return qFs:GetText() end
			r.qtyMinusBtn, r.qtyPlusBtn, r.qtyBtn, r.qtyEdit = minusBtn, plusBtn, qtyBtn, qtyEdit

			-- Title & 2nd-line Metadata Button (r.cells[1]: full untruncated name + crisp subtitle!)
			local nameBtn = CreateFrame("Button", nil, card)
			nameBtn:SetPoint("TOPLEFT", sock, "TOPRIGHT", 8, 2)
			nameBtn:SetPoint("BOTTOMRIGHT", card, "BOTTOMRIGHT", -210, 2)
			nameBtn.icon = sock.icon
			nameBtn.fs = nameBtn:CreateFontString(nil, "OVERLAY", "GameFontNormal")
			nameBtn.fs:SetJustifyH("LEFT")
			nameBtn.fs:SetWordWrap(false)
			applySafeFont(nameBtn.fs, 12, "semibold")

			nameBtn.subFs = nameBtn:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
			nameBtn.subFs:SetJustifyH("LEFT")
			nameBtn.subFs:SetWordWrap(false)
			applySafeFont(nameBtn.subFs, 10, "regular")
			r.subLineFs = nameBtn.subFs

			nameBtn:SetScript("OnEnter", function(self) if r.data then showShoppingRowTooltip(self, r.data) end end)
			nameBtn:SetScript("OnLeave", GameTooltip_Hide)
			nameBtn:SetScript("OnClick", function()
				local d = r.data
				if d and not d.isVendor and not d.isBundle and d.itemID then
					searchShoppingRow(d)
				end
			end)

			-- Programmatic hidden data-backing cells (keeps r.cells[1..9] contract 100% intact for tests without cluttering UI!)
			local function makeBackingFs()
				local fs = r:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
				fs:SetSize(1, 1); fs:SetPoint("TOPLEFT", 0, 0); fs:Hide()
				applySafeFont(fs, 12, "regular")
				return fs
			end
			r.cells = {
				[1] = nameBtn,
				[2] = makeBackingFs(),
				[3] = qWrap,
				[4] = makeBackingFs(),
				[5] = makeBackingFs(),
				[6] = makeBackingFs(),
				[7] = makeBackingFs(),
				[8] = actBtn,
				[9] = costFs,
			}

			r:SetScript("OnClick", function(self)
				if self.data and not self.data.isVendor and not self.data.isBundle and self.data.itemID then
					searchShoppingRow(self.data)
				end
			end)
		end

		r.data = data
		local pal = getPal()
		local isCustom = ns.Theme.IsCustomSkin and ns.Theme.IsCustomSkin()
		local skinKey = isCustom and ns.Theme.GetSkin and ns.Theme.GetSkin() or "standard"
		local isLight = (pal.mode == "light")
		local sortScope = (MerchantMasterDB and MerchantMasterDB.shoppingSortScope == "sub") and "sub" or "main"

		local hText, hSec, hMuted = palHex("hexText"), palHex("hexSecondary", "ebebf5"), palHex("hexMuted", "98989d")
		local hPos, hBlue = palHex("hexPositive", "30d158"), palHex("hexBlue", "5ac8fa")
		local hWarn, hDanger = palHex("hexWarning", "ff9230"), palHex("hexDanger", "ff4245")
		local hSub = palHex("hexCartSub", isLight and "6b24a8" or "d4b3ff")
		local hTeal = palHex("hexCartTeal", isLight and "0a6b82" or "56d4e8")
		local hGold = palHex("hexGold", isLight and "8a5a00" or "f7d57c")

		local isSubCraftHeader = (not data.isMainRow) and (data.makeMyself or data.canToggleCraft)
		local isNestedLeaf = (not data.isMainRow) and (not isSubCraftHeader) and (data.isSubRow == true or (tonumber(data.indent) or 0) >= 2)
		local isOwnedCovered = (not data.isMainRow) and (((data.ownedUsed or 0) > 0 or (data.surplusUsed or 0) > 0) and (data.qty or 0) == 0)

		-- Keep row height synchronized with variable extentCalculator (48px Main / 34px Sub / 30px Leaf + 8px valley on _isGroupLast)
		local targetRowH = shopRowExtent(nil, data)
		if r.SetHeight and ((not r.GetHeight) or r:GetHeight() ~= targetRowH) then
			r:SetHeight(targetRowH)
		end

		-- Unified Main-Order Outer Gold Frame + Active Sub-Craft Cyan/Violet Block + Balanced V7 Indentation
		local card = r.card
		local inMainGroup = (data._inMainGroup == true)
		local isGrpFirst = (data._isGroupFirst == true)
		local isGrpLast = (data._isGroupLast == true)
		local inSubBlock = (data._inSubBlock == true)
		local isSubFirst = (data._isSubFirst == true)
		local isSubLast = (data._isSubLast == true)
		local grpGold = isLight and { 0.72, 0.50, 0.08, 0.42 } or { 0.831, 0.635, 0.243, 0.48 }
		local grpBarGold = pal.cartMainAccent or (isLight and { 0.72, 0.50, 0.08, 1 } or { 0.831, 0.635, 0.243, 1.0 })
		local grpBottomPad = isGrpLast and 8 or 0

		if inMainGroup then
			local grpInterior = isLight and { 0.98, 0.98, 0.99, 0.98 }
				or (skinKey == "goblin" and { 0.043, 0.125, 0.082, 0.96 }
				or { pal.cardAltBg[1], pal.cardAltBg[2], pal.cardAltBg[3], 0.96 })
			r.grpBg:ClearAllPoints()
			r.grpBg:SetPoint("TOPLEFT", r, "TOPLEFT", 2, isGrpFirst and -2 or 0)
			r.grpBg:SetPoint("BOTTOMRIGHT", r, "BOTTOMRIGHT", -2, grpBottomPad)
			r.grpBg:SetColorTexture(grpInterior[1], grpInterior[2], grpInterior[3], grpInterior[4])
			r.grpBg:Show()

			r.grpLeft:ClearAllPoints()
			r.grpLeft:SetPoint("TOPLEFT", r.grpBg, "TOPLEFT", 0, 0)
			r.grpLeft:SetPoint("BOTTOMLEFT", r.grpBg, "BOTTOMLEFT", 0, 0)
			r.grpLeft:SetColorTexture(grpGold[1], grpGold[2], grpGold[3], grpGold[4])
			r.grpLeft:Show()

			r.grpRight:ClearAllPoints()
			r.grpRight:SetPoint("TOPRIGHT", r.grpBg, "TOPRIGHT", 0, 0)
			r.grpRight:SetPoint("BOTTOMRIGHT", r.grpBg, "BOTTOMRIGHT", 0, 0)
			r.grpRight:SetColorTexture(grpGold[1], grpGold[2], grpGold[3], grpGold[4])
			r.grpRight:Show()

			if isGrpFirst then
				r.grpTop:ClearAllPoints()
				r.grpTop:SetPoint("TOPLEFT", r.grpBg, "TOPLEFT", 0, 0)
				r.grpTop:SetPoint("TOPRIGHT", r.grpBg, "TOPRIGHT", 0, 0)
				r.grpTop:SetColorTexture(grpGold[1], grpGold[2], grpGold[3], grpGold[4])
				r.grpTop:Show()
			else
				r.grpTop:Hide()
			end
			if isGrpLast then
				r.grpBot:ClearAllPoints()
				r.grpBot:SetPoint("BOTTOMLEFT", r.grpBg, "BOTTOMLEFT", 0, 0)
				r.grpBot:SetPoint("BOTTOMRIGHT", r.grpBg, "BOTTOMRIGHT", 0, 0)
				r.grpBot:SetColorTexture(grpGold[1], grpGold[2], grpGold[3], grpGold[4])
				r.grpBot:Show()
			else
				r.grpBot:Hide()
			end
			if isGrpFirst and not isGrpLast then
				r.grpHdrSep:ClearAllPoints()
				r.grpHdrSep:SetPoint("BOTTOMLEFT", r.grpBg, "BOTTOMLEFT", 5, 0)
				r.grpHdrSep:SetPoint("BOTTOMRIGHT", r.grpBg, "BOTTOMRIGHT", -1, 0)
				r.grpHdrSep:SetColorTexture(grpGold[1], grpGold[2], grpGold[3], isLight and 0.24 or 0.28)
				r.grpHdrSep:Show()
			else
				r.grpHdrSep:Hide()
			end
			r.grpAccent:ClearAllPoints()
			r.grpAccent:SetPoint("TOPLEFT", r.grpBg, "TOPLEFT", 1, isGrpFirst and -1 or 0)
			r.grpAccent:SetPoint("BOTTOMLEFT", r.grpBg, "BOTTOMLEFT", 1, isGrpLast and 1 or 0)
			r.grpAccent:SetWidth(4)
			r.grpAccent:SetColorTexture(grpBarGold[1], grpBarGold[2], grpBarGold[3], 1)
			r.grpAccent:Show()
		else
			r.grpBg:Hide()
			r.grpTop:Hide()
			r.grpBot:Hide()
			r.grpLeft:Hide()
			r.grpRight:Hide()
			r.grpHdrSep:Hide()
			r.grpAccent:Hide()
		end

		if inSubBlock then
			local sbTop = isSubFirst and -2 or 0
			local sbBot = isSubLast and (grpBottomPad + 3) or 0
			local sbFill = isSubFirst
				and (isLight and { 0.94, 0.91, 0.99, 1 } or { 0.14, 0.08, 0.24, 0.92 })
				or  (isLight and { 0.97, 0.96, 1.0, 1 } or { 0.04, 0.10, 0.11, 0.90 })
			local sbStroke = isLight and { 0.48, 0.22, 0.76, 0.36 } or { 0.659, 0.459, 0.969, 0.44 }
			local sbCyan = pal.cartSubAccent or { 0.34, 0.83, 0.91, 1.0 }
			r.subBg:ClearAllPoints()
			r.subBg:SetPoint("TOPLEFT", r, "TOPLEFT", 10, sbTop)
			r.subBg:SetPoint("BOTTOMRIGHT", r, "BOTTOMRIGHT", -10, sbBot)
			r.subBg:SetColorTexture(sbFill[1], sbFill[2], sbFill[3], sbFill[4])
			r.subBg:Show()

			r.subAccent:ClearAllPoints()
			r.subAccent:SetPoint("TOPLEFT", r.subBg, "TOPLEFT", 0, 0)
			r.subAccent:SetPoint("BOTTOMLEFT", r.subBg, "BOTTOMLEFT", 0, 0)
			r.subAccent:SetColorTexture(sbCyan[1], sbCyan[2], sbCyan[3], 1)
			r.subAccent:Show()

			r.subRight:ClearAllPoints()
			r.subRight:SetPoint("TOPRIGHT", r.subBg, "TOPRIGHT", 0, 0)
			r.subRight:SetPoint("BOTTOMRIGHT", r.subBg, "BOTTOMRIGHT", 0, 0)
			r.subRight:SetColorTexture(sbStroke[1], sbStroke[2], sbStroke[3], sbStroke[4])
			r.subRight:Show()

			if isSubFirst then
				r.subTop:ClearAllPoints()
				r.subTop:SetPoint("TOPLEFT", r.subBg, "TOPLEFT", 3, 0)
				r.subTop:SetPoint("TOPRIGHT", r.subBg, "TOPRIGHT", 0, 0)
				r.subTop:SetColorTexture(sbStroke[1], sbStroke[2], sbStroke[3], sbStroke[4])
				r.subTop:Show()
			else
				r.subTop:Hide()
			end
			if isSubLast then
				r.subBot:ClearAllPoints()
				r.subBot:SetPoint("BOTTOMLEFT", r.subBg, "BOTTOMLEFT", 3, 0)
				r.subBot:SetPoint("BOTTOMRIGHT", r.subBg, "BOTTOMRIGHT", 0, 0)
				r.subBot:SetColorTexture(sbStroke[1], sbStroke[2], sbStroke[3], sbStroke[4])
				r.subBot:Show()
			else
				r.subBot:Hide()
			end
			if isSubFirst and not isSubLast then
				r.subHdrSep:ClearAllPoints()
				r.subHdrSep:SetPoint("BOTTOMLEFT", r.subBg, "BOTTOMLEFT", 3, 0)
				r.subHdrSep:SetPoint("BOTTOMRIGHT", r.subBg, "BOTTOMRIGHT", -1, 0)
				r.subHdrSep:SetColorTexture(sbStroke[1], sbStroke[2], sbStroke[3], 0.24)
				r.subHdrSep:Show()
			else
				r.subHdrSep:Hide()
			end
		else
			r.subBg:Hide()
			r.subAccent:Hide()
			r.subTop:Hide()
			r.subBot:Hide()
			r.subRight:Hide()
			r.subHdrSep:Hide()
		end

		local leftIndent, rightInset, topInset, botInset = 2, -2, -2, 2
		if inMainGroup then
			if data.isMainRow then
				leftIndent, rightInset, topInset, botInset = 6, -3, -3, isGrpLast and 9 or 1
			elseif inSubBlock then
				if isSubFirst then
					leftIndent, rightInset, topInset, botInset = 13, -11, -3, isSubLast and (grpBottomPad + 4) or 1
				else
					leftIndent, rightInset, topInset, botInset = 36, -16, -2, isSubLast and (grpBottomPad + 5) or 2
				end
			elseif isSubCraftHeader then
				leftIndent, rightInset, topInset, botInset = 10, -10, -2, isGrpLast and 10 or 2
			else
				leftIndent, rightInset, topInset, botInset = 20, -10, -2, isGrpLast and 10 or 2
			end
		else
			if not data.isMainRow then
				leftIndent = isNestedLeaf and 24 or 4
			end
		end
		card:ClearAllPoints()
		card:SetPoint("TOPLEFT", r, "TOPLEFT", leftIndent, topInset)
		card:SetPoint("BOTTOMRIGHT", r, "BOTTOMRIGHT", rightInset, botInset)

		if (not data.isMainRow) and (not isSubCraftHeader) and leftIndent >= 18 then
			local connCol = inSubBlock
				and (pal.cartSubAccent or { 0.34, 0.83, 0.91, 0.58 })
				or (pal.frameBorder or { 0.831, 0.635, 0.243, 0.45 })
			local cx = inSubBlock and 24 or 12
			r.connV:ClearAllPoints()
			r.connV:SetPoint("TOPLEFT", r, "TOPLEFT", cx, 0)
			r.connV:SetHeight(15)
			r.connV:SetColorTexture(connCol[1], connCol[2], connCol[3], inSubBlock and 0.55 or 0.45)
			r.connV:Show()
			r.connH:ClearAllPoints()
			r.connH:SetPoint("TOPLEFT", r, "TOPLEFT", cx, -14)
			r.connH:SetWidth(math.max(6, leftIndent - cx - 2))
			r.connH:SetColorTexture(connCol[1], connCol[2], connCol[3], inSubBlock and 0.55 or 0.45)
			r.connH:Show()
		else
			r.connV:Hide()
			r.connH:Hide()
		end

		-- Color-Coded Item Icon Frame (replaces dull metallic socket.blp on Shopping Cart rows!)
		local sock = r.iconSocket
		local sockSize = data.isMainRow and 30 or (isSubCraftHeader and 22 or 20)
		sock:SetSize(sockSize, sockSize)
		sock:ClearAllPoints()
		if data.isMainRow then
			r.chevron:Show()
			local chevC = pal.cartMainAccent or pal.gold or { 0.97, 0.84, 0.49, 1 }
			r.chevron:SetVertexColor(chevC[1], chevC[2], chevC[3], 0.92)
			sock:SetPoint("LEFT", card, "LEFT", 24, 0)
		else
			r.chevron:Hide()
			sock:SetPoint("LEFT", card, "LEFT", 8, 0)
		end
		sock.icon:SetTexture(data.icon)
		sock.skinTex:Hide()
		local iconBorder, iconBg
		if data.isMainRow then
			iconBorder = isLight and { 0.74, 0.52, 0.08, 0.95 } or { 0.969, 0.835, 0.486, 0.98 }
			iconBg = isLight and { 0.95, 0.90, 0.78, 1 } or { 0.35, 0.24, 0.06, 1 }
		elseif isSubCraftHeader and data.makeMyself == true then
			iconBorder = isLight and { 0.46, 0.18, 0.74, 0.92 } or { 0.659, 0.459, 0.969, 0.98 }
			iconBg = isLight and { 0.92, 0.88, 0.98, 1 } or { 0.18, 0.09, 0.30, 1 }
		elseif isOwnedCovered then
			iconBorder = isLight and { 0.00, 0.52, 0.26, 0.85 } or { 0.373, 0.976, 0.678, 0.85 }
			iconBg = isLight and { 0.90, 0.97, 0.93, 1 } or { 0.06, 0.18, 0.12, 1 }
		elseif data.isVendor then
			iconBorder = isLight and { 0.74, 0.44, 0.04, 0.90 } or { 0.961, 0.702, 0.259, 0.92 }
			iconBg = isLight and { 0.98, 0.93, 0.84, 1 } or { 0.24, 0.15, 0.04, 1 }
		else
			iconBorder = isLight and { 0.00, 0.52, 0.24, 0.90 } or { 0.180, 0.949, 0.561, 0.92 }
			iconBg = isLight and { 0.90, 0.97, 0.93, 1 } or { 0.05, 0.20, 0.12, 1 }
		end
		sock.colorFrame:SetFill(iconBg[1], iconBg[2], iconBg[3], iconBg[4])
		sock.colorFrame:SetStroke(iconBorder[1], iconBorder[2], iconBorder[3], iconBorder[4])
		sock.colorFrame:SetShown(true)

		local nameBtn = r.cells[1]
		local qWrap = r.cells[3]
		local actBtn = r.cells[8]
		local costFs = r.cells[9]

		-- Populate hidden backing cells for test_unified_shopping_list.lua & test_crafting_order.lua parity
		if data.isMainRow then
			r.cells[2]:SetText(hBlue .. "Main: " .. tostring(data.sourceLabel or "Order") .. "|r")
		elseif data.isSubRow then
			r.cells[2]:SetText(hSub .. tostring(data.parentSubName or data.categoryName or "Sub-Mat") .. "|r")
		else
			r.cells[2]:SetText(hSec .. tostring(data.categoryName or data.role or "") .. "|r")
		end
		r.cells[4]:SetText(data.isVendor and (hWarn .. "Vendor|r") or (data.listed ~= nil and (hText .. tostring(data.listed) .. "|r") or (hMuted .. "—|r")))
		r.cells[5]:SetText(data.isVendor and (hWarn .. "Unl.|r") or ns.Theme.FormatSalesPerDay(data.dailySold))
		r.cells[6]:SetText(data.ahUnitPrice and ns.FormatMoneyCompact(data.ahUnitPrice) or (hMuted .. "—|r"))
		if data.isMainRow then
			r.cells[7]:SetText(data.groupTotalCost and (hPos .. "Sum: |r" .. ns.FormatMoneyCompact(data.groupTotalCost)) or (hMuted .. "—|r"))
		elseif data.craftUnitPrice ~= nil and data.craftTotalPrice ~= nil then
			local canTag = ""
			if (data.craftCD or 0) >= 60 then
				canTag = " " .. hWarn .. "[" .. tostring(data.craftCDLabel or "CD") .. " CD]|r"
			elseif data.craftProfLabel ~= nil then
				canTag = data.craftCanDo and (" " .. hSub .. "[You]|r") or (" " .. hWarn .. "[Need]|r")
			end
			r.cells[7]:SetText(ns.FormatMoneyCompact(data.craftUnitPrice) .. canTag)
		else
			r.cells[7]:SetText(hMuted .. "—|r")
		end

		local function applyDimensionalPill(topC, botC, outlineC, sheenAlpha)
			local midC = { (topC[1] + botC[1]) * 0.5, (topC[2] + botC[2]) * 0.5, (topC[3] + botC[3]) * 0.5, (topC[4] + botC[4]) * 0.5 }
			actBtn.plate:SetFill(midC[1], midC[2], midC[3], midC[4])
			actBtn.plate:SetStroke(outlineC[1], outlineC[2], outlineC[3], outlineC[4])
			if ns.Theme.SetGradientFill then
				ns.Theme.SetGradientFill(actBtn.gradTex, "VERTICAL", topC, botC)
			else
				actBtn.gradTex:SetColorTexture(midC[1], midC[2], midC[3], midC[4])
			end
			actBtn.gradTex:Show()
			actBtn.topSheen:SetVertexColor(1, 1, 1, sheenAlpha or (isLight and 0.10 or 0.24))
			actBtn.topSheen:Show()
		end

		-- Card gradient fill, smooth border, square tier badges, steppers, uniform dimensional pills & layout by tier
		if data.isMainRow then
			local cStroke = pal.cartMainAccent or (isLight and { 0.72, 0.50, 0.08, 0.75 } or { 0.831, 0.635, 0.243, 0.85 })
			card.plate:SetShown(true)
			card.plate:SetFill(0, 0, 0, 0)
			card.plate:SetStroke(cStroke[1], cStroke[2], cStroke[3], inMainGroup and 0 or (isLight and 0.42 or 0.48))
			if ns.Theme.SetGradientFill then
				ns.Theme.SetGradientFill(r.rowGrad, "HORIZONTAL",
					isLight and { 0.99, 0.96, 0.86, 1 } or { 0.24, 0.17, 0.08, 0.92 },
					isLight and { 0.99, 0.98, 0.94, 1 } or { 0.047, 0.125, 0.086, 0.92 })
			end
			r.rowGrad:Show()
			r.accentBar:ClearAllPoints()
			if inMainGroup then
				r.accentBar:SetPoint("TOPLEFT", r.grpBg, "TOPLEFT", 1, -1)
				r.accentBar:SetPoint("BOTTOMLEFT", r.grpBg, "BOTTOMLEFT", 1, isGrpLast and 1 or 0)
			else
				r.accentBar:SetPoint("TOPLEFT", card, "TOPLEFT", 1, -2)
				r.accentBar:SetPoint("BOTTOMLEFT", card, "BOTTOMLEFT", 1, 2)
			end
			r.accentBar:SetColorTexture(cStroke[1], cStroke[2], cStroke[3], 1)
			r.accentBar:SetWidth(4)
			r.accentBar:Show()
			r.qtyBadge:Hide()
			r.inlineMetaFs:Hide()

			-- Square slightly-rounded MAIN ORDER badge (glass_r4, 66x16)
			local bFill = isLight and { 0.84, 0.62, 0.12, 0.16 } or { 0.62, 0.44, 0.10, 0.44 }
			local bStroke = isLight and { 0.72, 0.50, 0.08, 0.65 } or { 0.97, 0.84, 0.49, 0.72 }
			r.tierBadge:SetSize(66, 16)
			r.tierBadge:ClearAllPoints()
			r.tierBadge:SetPoint("TOPLEFT", sock, "TOPRIGHT", 8, 0)
			r.tierBadge.plate:SetFill(bFill[1], bFill[2], bFill[3], bFill[4])
			r.tierBadge.plate:SetStroke(bStroke[1], bStroke[2], bStroke[3], bStroke[4])
			r.tierBadge.fs:SetText(hGold .. "MAIN ORDER|r")
			r.tierBadge:Show()

			-- Far-right Framed 24x24 Crimson X Remove Button (r.cells[8], dead-centered X)
			actBtn:SetSize(24, 24)
			actBtn:ClearAllPoints()
			actBtn:SetPoint("RIGHT", card, "RIGHT", -10, 0)
			actBtn.plate:SetShown(false)
			actBtn.gradTex:Hide()
			actBtn.topSheen:Hide()
			actBtn.swapIcon:Hide()
			if data.canRemoveMain then
				local rFill = isLight and { 0.84, 0.14, 0.16, 0.12 } or { 0.42, 0.07, 0.13, 0.92 }
				local rStroke = isLight and { 0.72, 0.08, 0.10, 0.65 } or { 0.88, 0.31, 0.37, 0.82 }
				actBtn.sqPlate:SetFill(rFill[1], rFill[2], rFill[3], rFill[4])
				actBtn.sqPlate:SetStroke(rStroke[1], rStroke[2], rStroke[3], rStroke[4])
				actBtn.sqPlate:SetShown(true)
				actBtn.icon:ClearAllPoints()
				actBtn.icon:SetPoint("CENTER", actBtn, "CENTER", 0, 0)
				actBtn.icon:SetSize(10, 10)
				actBtn.icon:SetTexture(ns.Theme.ASSETS.icon_close)
				local xCol = isLight and { 0.72, 0.08, 0.10, 1 } or { 1.0, 0.72, 0.76, 1 }
				actBtn.icon:SetVertexColor(xCol[1], xCol[2], xCol[3], 1)
				actBtn.icon:Show()
				actBtn.fs:SetText("")
