				actBtn:Show()
			else
				actBtn.sqPlate:SetShown(false)
				actBtn.icon:Hide()
				actBtn.fs:SetText("")
				actBtn._actionTag = "Main"
				actBtn:Hide()
			end

			-- Stacked ORDER COST + Gold Money Total (r.cells[9], compact 84px width)
			r.costLblFs:ClearAllPoints()
			r.costLblFs:SetPoint("TOPRIGHT", actBtn, "TOPLEFT", -8, 2)
			local mutC = pal.textMuted or { 0.65, 0.72, 0.68, 1 }
			r.costLblFs:SetTextColor(mutC[1], mutC[2], mutC[3], 1)
			r.costLblFs:Show()
			costFs:ClearAllPoints()
			costFs:SetPoint("TOPRIGHT", r.costLblFs, "BOTTOMRIGHT", 0, -1)
			costFs:SetText(data.groupTotalCost ~= nil and ns.FormatMoneyCompact(data.groupTotalCost) or (hMuted .. "—|r"))

			-- Optically Centered [-  qty  +] Stepper Pill anchored directly to card vertical centerline (r.cells[3])
			local canStep = (data.removeRef ~= nil)
			qWrap:SetSize(90, 26)
			qWrap:ClearAllPoints()
			qWrap:SetPoint("RIGHT", card, "RIGHT", -136, 0)
			local sWell = isLight and { 0.94, 0.94, 0.96, 1 } or { 0.024, 0.075, 0.047, 0.98 }
			local sBtnBg = isLight and { 0.87, 0.88, 0.91, 1 } or { 0.07, 0.17, 0.12, 0.96 }
			local sInk = isLight and (pal.text or { 0, 0, 0, 1 }) or (pal.cartMainAccent or { 0.97, 0.84, 0.49, 1 })
			local eText = pal.text or (isLight and { 0.1, 0.1, 0.12, 1 } or { 1.0, 1.0, 1.0, 1 })
			qWrap.plate:SetFill(sWell[1], sWell[2], sWell[3], sWell[4])
			qWrap.plate:SetStroke(cStroke[1], cStroke[2], cStroke[3], isLight and 0.62 or 0.82)
