				qWrap.qtyEdit.bdBot:SetColorTexture(fbd[1], fbd[2], fbd[3], 0.95)
				qWrap.qtyEdit.bdL:SetColorTexture(fbd[1], fbd[2], fbd[3], 0.95)
				qWrap.qtyEdit.bdR:SetColorTexture(fbd[1], fbd[2], fbd[3], 0.95)
