				qWrap.plusBtn.bg:SetColorTexture(sBtnBg[1], sBtnBg[2], sBtnBg[3], sBtnBg[4])
				qWrap.minusBtn.div:SetColorTexture(cStroke[1], cStroke[2], cStroke[3], 0.42)
				qWrap.plusBtn.div:SetColorTexture(cStroke[1], cStroke[2], cStroke[3], 0.42)
				qWrap.minusBtn.fs:SetTextColor(sInk[1], sInk[2], sInk[3], 1)
				qWrap.plusBtn.fs:SetTextColor(sInk[1], sInk[2], sInk[3], 1)
			end
			qWrap.fs:ClearAllPoints()
			if canStep then
				qWrap.fs:SetPoint("TOPLEFT", qWrap.minusBtn, "TOPRIGHT", 1, 0)
				qWrap.fs:SetPoint("BOTTOMRIGHT", qWrap.plusBtn, "BOTTOMLEFT", -1, 0)
			else
				qWrap.fs:SetAllPoints(qWrap)
			end
			qWrap.fs:Show()
			qWrap.fs:SetText(hText .. tostring(data.qty or 1) .. "|r")
			qWrap:Show()

			-- Full Untruncated Main Order Name + Source & Breakdown Count Subtitle (2 lines)
			nameBtn:ClearAllPoints()
			nameBtn:SetPoint("TOP", card, "TOP", 0, -2)
			nameBtn:SetPoint("BOTTOM", card, "BOTTOM", 0, 2)
			nameBtn:SetPoint("LEFT", sock, "RIGHT", 8, 0)
			nameBtn:SetPoint("RIGHT", qWrap, "LEFT", -8, 0)
			nameBtn.fs:ClearAllPoints()
			nameBtn.fs:SetWidth(0)
			nameBtn.fs:SetPoint("LEFT", r.tierBadge, "RIGHT", 7, 0)
			nameBtn.fs:SetPoint("RIGHT", nameBtn, "RIGHT", 0, 0)
			applySafeFont(nameBtn.fs, 12, "semibold")
			nameBtn.fs:SetText(hText .. tostring(data.name or "") .. "|r")
			nameBtn.subFs:ClearAllPoints()
			nameBtn.subFs:SetPoint("TOPLEFT", r.tierBadge, "BOTTOMLEFT", 1, -3)
			nameBtn.subFs:SetPoint("RIGHT", nameBtn, "RIGHT", 0, 0)
			local subMeta = {}
			if (data._subCraftCount or 0) > 0 then
				subMeta[#subMeta + 1] = string.format("%d sub-craft%s", data._subCraftCount, data._subCraftCount == 1 and "" or "s")
			end
			if (data._directMatCount or 0) > 0 then
				subMeta[#subMeta + 1] = string.format("%d direct mat%s", data._directMatCount, data._directMatCount == 1 and "" or "s")
			end
			local srcStr = tostring(data.sourceLabel or "Crafting Order")
			if #subMeta > 0 then
				nameBtn.subFs:SetText(hSec .. srcStr .. "|r " .. hMuted .. "· " .. table.concat(subMeta, ", ") .. "|r")
			else
				nameBtn.subFs:SetText(hSec .. srcStr .. "|r")
			end
			nameBtn.subFs:Show()

		elseif isSubCraftHeader then
