			if inSubBlock then
				card.plate:SetShown(false)
				r.accentBar:Hide()
			else
				local cStroke = isCraft
					and (isLight and { 0.48, 0.22, 0.76, 0.45 } or { 0.659, 0.459, 0.969, 0.44 })
					or  (isLight and { 0.00, 0.50, 0.22, 0.42 } or { 0.18, 0.95, 0.56, 0.38 })
				card.plate:SetShown(true)
				card.plate:SetFill(0, 0, 0, 0)
				card.plate:SetStroke(cStroke[1], cStroke[2], cStroke[3], cStroke[4])
				local barCol = isCraft and (pal.cartSubAccent or { 0.34, 0.83, 0.91, 1 }) or (pal.accentGreen or { 0.18, 0.95, 0.56, 1 })
				r.accentBar:ClearAllPoints()
				r.accentBar:SetPoint("TOPLEFT", card, "TOPLEFT", 1, -2)
				r.accentBar:SetPoint("BOTTOMLEFT", card, "BOTTOMLEFT", 1, 2)
				r.accentBar:SetColorTexture(barCol[1], barCol[2], barCol[3], 1)
				r.accentBar:SetWidth(3)
				r.accentBar:Show()
			end
			if ns.Theme.SetGradientFill then
				if isCraft then
					ns.Theme.SetGradientFill(r.rowGrad, "HORIZONTAL",
						isLight and { 0.94, 0.90, 0.99, 1 } or { 0.24, 0.12, 0.42, 0.92 },
						isLight and { 0.93, 0.97, 0.98, 1 } or { 0.055, 0.14, 0.16, 0.92 })
				else
					ns.Theme.SetGradientFill(r.rowGrad, "HORIZONTAL",
						isLight and { 0.90, 0.97, 0.93, 1 } or { 0.07, 0.24, 0.16, 0.92 },
						isLight and { 0.96, 0.99, 0.97, 1 } or { 0.035, 0.11, 0.078, 0.92 })
				end
			end
			r.rowGrad:Show()

