			local tbFill = isLight and { 0.44, 0.16, 0.70, 0.16 } or { 0.45, 0.20, 0.82, 0.88 }
			local tbStroke = isLight and { 0.44, 0.16, 0.70, 0.72 } or { 0.80, 0.64, 1.0, 0.88 }
			r.tierBadge:SetSize(66, 15)
			r.tierBadge:ClearAllPoints()
			r.tierBadge:SetPoint("LEFT", sock, "RIGHT", 7, 0)
			r.tierBadge.plate:SetFill(tbFill[1], tbFill[2], tbFill[3], tbFill[4])
			r.tierBadge.plate:SetStroke(tbStroke[1], tbStroke[2], tbStroke[3], tbStroke[4])
			local badgeWord = isCraft and "SUB-CRAFT" or "CRAFTABLE"
			r.tierBadge.fs:SetText(isLight and (hSub .. badgeWord .. "|r") or ("|cffffffff" .. badgeWord .. "|r"))
			r.tierBadge:Show()

			-- Far-right Cost (r.cells[9], fixed 84px)
			r.costLblFs:Hide()
			costFs:ClearAllPoints()
			costFs:SetPoint("RIGHT", card, "RIGHT", -10, 0)
