			else
				costFs:SetText(ns.FormatMoneyCompact(data.ahTotalPrice or data.lineCost or 0))
			end

			-- Uniform Dimensional Toggle Pill: 122x22 CRAFT · PROF [swap] OR 96x22 BUY AH [swap] (right-aligned to exact same edge!)
			local showSwap = (data.canToggleCraft == true)
			actBtn:SetSize(isCraft and 122 or 96, 22)
