					applyDimensionalPill({ 0.94, 0.89, 0.99, 1 }, { 0.88, 0.81, 0.97, 1 }, { 0.44, 0.16, 0.70, 0.82 }, 0.12)
				else
					applyDimensionalPill({ 0.52, 0.25, 0.88, 0.96 }, { 0.29, 0.12, 0.57, 0.98 }, { 0.91, 0.835, 1.0, 0.98 }, 0.24)
