			-- SINGLE-LINE Sub-Craft / Craftable Layout: [Badge] Name [ ×N ] Saves X · Not sent to AH
			nameBtn:ClearAllPoints()
			nameBtn:SetPoint("TOP", card, "TOP", 0, -1)
			nameBtn:SetPoint("BOTTOM", card, "BOTTOM", 0, 1)
			nameBtn:SetPoint("LEFT", sock, "RIGHT", 7, 0)
