			applySafeFont(nameBtn.fs, 12, "semibold")
			nameBtn.fs:SetText((isCraft and hSub or hText) .. subNamePlain .. "|r")
			local rawSubW = (nameBtn.fs.GetStringWidth and nameBtn.fs:GetStringWidth()) or (#subNamePlain * 6.8)
			if rawSubW <= 4 then rawSubW = #subNamePlain * 6.8 end
			nameBtn.fs:SetWidth(math.min(185, math.ceil(rawSubW) + 2))

			-- Inline gray rounded-square quantity badge [ ×N ]
			local qPlain = "×" .. tostring(data.qty or 0)
			local qbFill = isLight and { 0.88, 0.90, 0.93, 1 } or { 0.18, 0.24, 0.21, 0.90 }
			local qbStroke = isLight and { 0, 0, 0, 0.12 } or { 1, 1, 1, 0.14 }
			r.qtyBadge.plate:SetFill(qbFill[1], qbFill[2], qbFill[3], qbFill[4])
			r.qtyBadge.plate:SetStroke(qbStroke[1], qbStroke[2], qbStroke[3], qbStroke[4])
			r.qtyBadge.fs:SetText(isLight and (hText .. qPlain .. "|r") or ("|cffffffff" .. qPlain .. "|r"))
			local rawQBW = (r.qtyBadge.fs.GetStringWidth and r.qtyBadge.fs:GetStringWidth()) or (#qPlain * 6.4)
			if rawQBW <= 4 then rawQBW = #qPlain * 6.4 end
			r.qtyBadge:SetSize(math.max(28, math.ceil(rawQBW) + 12), 18)
			r.qtyBadge:ClearAllPoints()
			r.qtyBadge:SetPoint("LEFT", nameBtn.fs, "RIGHT", 6, 0)
			r.qtyBadge:Show()

			local subTxt
			if isCraft then
				local diff = (data.ahTotalPrice and data.craftTotalPrice) and (data.ahTotalPrice - data.craftTotalPrice) or 0
				if diff > 0 then
					subTxt = hTeal .. "Saves |r" .. ns.FormatMoneyCompact(diff) .. hTeal .. " · Not sent to AH|r"
				else
					subTxt = hTeal .. "Crafted locally · Not sent to AH|r"
				end
			else
				local listTxt = data.listed and (tostring(data.listed) .. " listed") or "AH"
				subTxt = hPos .. "Cheaper on AH|r " .. hMuted .. "· " .. listTxt .. "|r"
			end
			r.inlineMetaFs:ClearAllPoints()
			r.inlineMetaFs:SetPoint("LEFT", r.qtyBadge, "RIGHT", 7, 0)
			r.inlineMetaFs:SetPoint("RIGHT", actBtn, "LEFT", -8, 0)
			r.inlineMetaFs:SetText(subTxt)
			r.inlineMetaFs:Show()

		else
			-- SINGLE-LINE Leaf Material Row (30px compact card, horizontal gradient, hairline border, inline [ Nx ] badge!)
			local cStroke = isOwnedCovered
				and (isLight and { 0.00, 0.50, 0.22, 0.24 } or { 0.373, 0.976, 0.678, 0.18 })
				or  (inSubBlock and (isLight and { 0.48, 0.22, 0.76, 0.16 } or { 0.34, 0.83, 0.91, 0.18 })
				or  (isLight and { 0, 0, 0, 0.10 } or { 0.831, 0.635, 0.243, 0.16 }))
			card.plate:SetShown(true)
			card.plate:SetFill(0, 0, 0, 0)
			card.plate:SetStroke(cStroke[1], cStroke[2], cStroke[3], cStroke[4])
			if ns.Theme.SetGradientFill then
				local gL, gR
				if isLight then
					gL = isOwnedCovered and { 0.92, 0.97, 0.94, 1 } or { 0.97, 0.98, 0.99, 1 }
					gR = { 0.99, 0.99, 1.0, 1 }
				else
					gL = isOwnedCovered and { 0.05, 0.14, 0.095, 0.84 }
						or (inSubBlock and { 0.035, 0.10, 0.105, 0.88 } or { 0.035, 0.11, 0.072, 0.90 })
					gR = { 0.022, 0.075, 0.048, 0.92 }
				end
				ns.Theme.SetGradientFill(r.rowGrad, "HORIZONTAL", gL, gR)
			end
			r.rowGrad:Show()

			local tickCol = inSubBlock
				and { 0.34, 0.83, 0.91, 0.42 }
				or (isOwnedCovered and { 0.373, 0.976, 0.678, 0.42 }
				or (data.isVendor and { 0.961, 0.702, 0.259, 0.42 } or { 0.831, 0.635, 0.243, 0.32 }))
			r.accentBar:ClearAllPoints()
			r.accentBar:SetPoint("TOPLEFT", card, "TOPLEFT", 1, -2)
			r.accentBar:SetPoint("BOTTOMLEFT", card, "BOTTOMLEFT", 1, 2)
			r.accentBar:SetColorTexture(tickCol[1], tickCol[2], tickCol[3], tickCol[4])
			r.accentBar:SetWidth(2)
			r.accentBar:Show()
			r.tierBadge:Hide()

			-- Far-right Cost (r.cells[9], fixed 84px)
			r.costLblFs:Hide()
			costFs:ClearAllPoints()
			costFs:SetPoint("RIGHT", card, "RIGHT", -10, 0)
			if isOwnedCovered then
				costFs:SetText(hMuted .. "0c|r")
