				costFs:SetText(hSub .. "(|r" .. ns.FormatMoneyCompact(data.lineCost or 0) .. hSub .. ")|r")
			else
				costFs:SetText((data.lineFavor and data.lineFavor > 0) and (hText .. tostring(data.lineFavor) .. " Favor|r") or ns.FormatMoneyCompact(data.lineCost or 0))
			end

			-- Uniform Fixed 96x22 Dimensional Semantic Pill (BUY AH / VENDOR / OWNED — razor-straight right column!)
			actBtn:SetSize(96, 22)
			if actBtn.plate.SetCapWidth then actBtn.plate:SetCapWidth(11) end
			actBtn:ClearAllPoints()
			actBtn:SetPoint("RIGHT", costFs, "LEFT", -10, 0)
			actBtn.sqPlate:SetShown(false)
			actBtn.plate:SetShown(true)
			actBtn.swapIcon:Hide()
			actBtn:Show()
			if isOwnedCovered then
				if isLight then
					applyDimensionalPill({ 0.91, 0.97, 0.93, 1 }, { 0.84, 0.94, 0.88, 1 }, { 0.00, 0.50, 0.24, 0.75 }, 0.08)
				else
					applyDimensionalPill({ 0.14, 0.36, 0.24, 0.86 }, { 0.08, 0.22, 0.14, 0.92 }, { 0.541, 0.961, 0.753, 0.84 }, 0.20)
				end
				actBtn.icon:ClearAllPoints()
				actBtn.icon:SetPoint("LEFT", 9, 0)
				actBtn.icon:SetSize(10, 10)
