				local ic = isLight and { 0.00, 0.48, 0.20, 1 } or { 0.541, 0.961, 0.753, 1 }
				actBtn.icon:SetVertexColor(ic[1], ic[2], ic[3], 1)
				actBtn.icon:Show()
				actBtn.fs:ClearAllPoints()
				actBtn.fs:SetPoint("LEFT", actBtn.icon, "RIGHT", 3, 0)
				actBtn.fs:SetPoint("RIGHT", -6, 0)
				actBtn.fs:SetJustifyH("CENTER")
				if (data.ownedUsed or 0) > 0 and (data.surplusUsed or 0) > 0 then
					actBtn.fs:SetText(hPos .. "OWN + SURP|r")
				elseif (data.ownedUsed or 0) > 0 then
					actBtn.fs:SetText(hPos .. "OWNED|r")
				else
					actBtn.fs:SetText(hPos .. tostring(data.action or ("Surplus (" .. tostring(data.rawQty or data.surplusUsed) .. "x)")) .. "|r")
				end
				actBtn._actionTag = "Own"
			elseif data.isVendor then
				if isLight then
					applyDimensionalPill({ 0.99, 0.95, 0.86, 1 }, { 0.96, 0.89, 0.74, 1 }, { 0.74, 0.44, 0.04, 0.82 }, 0.10)
				else
					applyDimensionalPill({ 0.64, 0.40, 0.09, 0.92 }, { 0.36, 0.21, 0.04, 0.96 }, { 1.0, 0.886, 0.620, 0.94 }, 0.24)
				end
				actBtn.icon:Hide()
				actBtn.fs:ClearAllPoints(); actBtn.fs:SetAllPoints(actBtn); actBtn.fs:SetJustifyH("CENTER")
				actBtn.fs:SetText(isLight and (hWarn .. "VENDOR|r") or "|cffffffffVENDOR|r")
				actBtn._actionTag = "Vendor"
			else
				if isLight then
					applyDimensionalPill({ 0.90, 0.97, 0.93, 1 }, { 0.82, 0.94, 0.87, 1 }, { 0.00, 0.50, 0.22, 0.82 }, 0.10)
				else
					applyDimensionalPill({ 0.10, 0.50, 0.29, 0.94 }, { 0.043, 0.25, 0.145, 0.98 }, { 0.478, 1.0, 0.745, 0.95 }, 0.24)
				end
				actBtn.icon:Hide()
				actBtn.fs:ClearAllPoints(); actBtn.fs:SetAllPoints(actBtn); actBtn.fs:SetJustifyH("CENTER")
				actBtn.fs:SetText(isLight and (hPos .. "BUY AH|r") or "|cffffffffBUY AH|r")
				actBtn._actionTag = "Buy"
			end

			-- Keep hidden qty cell synced for test_crafting_order.lua (0/1 check!)
			local qtyDisplay, qtyPlain
			if ((data.ownedUsed or 0) + (data.surplusUsed or 0)) > 0 and data.rawQty and data.rawQty ~= data.qty then
				local qCol = (data.qty == 0) and hPos or hText
				qtyDisplay = qCol .. tostring(data.qty or 0) .. "|r" .. hMuted .. "/" .. tostring(data.rawQty) .. "|r"
				qtyPlain = tostring(data.qty or 0) .. "/" .. tostring(data.rawQty)
			else
				qtyDisplay = ((data.qty or 0) == 0 and hPos or hText) .. tostring(data.qty or 0) .. "x|r"
				qtyPlain = tostring(data.qty or 0) .. "x"
			end
			if qWrap.qtyEdit then qWrap.qtyEdit._cancelled = true; qWrap.qtyEdit:Hide(); qWrap.qtyEdit._cancelled = nil end
			if qWrap.qtyBtn then qWrap.qtyBtn:Hide() end
			qWrap:Hide()
			qWrap.fs:SetText(qtyDisplay)

			-- SINGLE-LINE Leaf Layout: [Icon] Name [ Nx ] 12048 listed · 20c ea
			nameBtn:ClearAllPoints()
			nameBtn:SetPoint("TOP", card, "TOP", 0, -1)
			nameBtn:SetPoint("BOTTOM", card, "BOTTOM", 0, 1)
			nameBtn:SetPoint("LEFT", sock, "RIGHT", 8, 0)
			nameBtn:SetPoint("RIGHT", actBtn, "LEFT", -8, 0)
			nameBtn.subFs:Hide()

			local leafNamePlain = tostring(data.name or "")
			nameBtn.fs:ClearAllPoints()
			nameBtn.fs:SetWidth(0)
			nameBtn.fs:SetPoint("LEFT", nameBtn, "LEFT", 0, 0)
			applySafeFont(nameBtn.fs, 12, "semibold")
			nameBtn.fs:SetText(hText .. leafNamePlain .. "|r")
			local rawLeafW = (nameBtn.fs.GetStringWidth and nameBtn.fs:GetStringWidth()) or (#leafNamePlain * 6.8)
			if rawLeafW <= 4 then rawLeafW = #leafNamePlain * 6.8 end
			nameBtn.fs:SetWidth(math.min(220, math.ceil(rawLeafW) + 2))

			-- Inline gray rounded-square quantity badge ([ 22x ] or emerald-tinted [ 0/5 ])
			local qbFill, qbStroke, qbTxt
			if isOwnedCovered then
				qbFill = isLight and { 0.88, 0.96, 0.91, 1 } or { 0.08, 0.28, 0.18, 0.88 }
				qbStroke = isLight and { 0.00, 0.48, 0.22, 0.30 } or { 0.373, 0.976, 0.678, 0.42 }
				qbTxt = hPos .. qtyPlain .. "|r"
			else
				qbFill = isLight and { 0.88, 0.90, 0.93, 1 } or { 0.18, 0.24, 0.21, 0.90 }
				qbStroke = isLight and { 0, 0, 0, 0.12 } or { 1, 1, 1, 0.14 }
				qbTxt = isLight and (hText .. qtyPlain .. "|r") or ("|cffffffff" .. qtyPlain .. "|r")
			end
			r.qtyBadge.plate:SetFill(qbFill[1], qbFill[2], qbFill[3], qbFill[4])
			r.qtyBadge.plate:SetStroke(qbStroke[1], qbStroke[2], qbStroke[3], qbStroke[4])
			r.qtyBadge.fs:SetText(qbTxt)
			local rawLQW = (r.qtyBadge.fs.GetStringWidth and r.qtyBadge.fs:GetStringWidth()) or (#qtyPlain * 6.4)
			if rawLQW <= 4 then rawLQW = #qtyPlain * 6.4 end
			r.qtyBadge:SetSize(math.max(28, math.ceil(rawLQW) + 12), 18)
			r.qtyBadge:ClearAllPoints()
			r.qtyBadge:SetPoint("LEFT", nameBtn.fs, "RIGHT", 6, 0)
			r.qtyBadge:Show()

			local mktLine
			if data.isVendor then
				local vParts = { "NPC Vendor", "Unl." }
				if data.ahUnitPrice then vParts[#vParts + 1] = ns.FormatMoneyCompact(data.ahUnitPrice) .. " ea" end
				if data.owned and data.owned > 0 and not isOwnedCovered then
					vParts[#vParts + 1] = string.format("%d own", data.owned)
				end
				mktLine = hMuted .. table.concat(vParts, " · ") .. "|r"
			else
				local mktParts = {}
				if data.listed ~= nil then
					mktParts[#mktParts + 1] = tostring(data.listed) .. " listed"
				else
					mktParts[#mktParts + 1] = "AH"
				end
				if data.dailySold ~= nil then
					mktParts[#mktParts + 1] = string.format("%.1f/d", data.dailySold)
				end
				if data.ahUnitPrice ~= nil then
					mktParts[#mktParts + 1] = ns.FormatMoneyCompact(data.ahUnitPrice) .. " ea"
				end
				if data.owned and data.owned > 0 and not isOwnedCovered then
					mktParts[#mktParts + 1] = string.format("%d own", data.owned)
				end
				mktLine = hMuted .. table.concat(mktParts, " · ") .. "|r"
			end
			r.inlineMetaFs:ClearAllPoints()
			r.inlineMetaFs:SetPoint("LEFT", r.qtyBadge, "RIGHT", 7, 0)
			r.inlineMetaFs:SetPoint("RIGHT", actBtn, "LEFT", -8, 0)
			r.inlineMetaFs:SetText(mktLine)
			r.inlineMetaFs:Show()
		end
	end, nil, { cellFontSize = 12, rowHeight = 48, extentCalculator = shopRowExtent, cardMode = true, transparentInset = true, preparedCells = true })
	wrap.table.updateHeaders()

	-- Empty Cart State Overlay inside Left Pane (52x52 V3 Socketed Medallion across ALL 6 themes!)
	local emptyState = CreateFrame("Frame", nil, leftPane)
	emptyState:SetPoint("TOPLEFT", leftPane, "TOPLEFT", 2, -28)
	emptyState:SetPoint("BOTTOMRIGHT", leftPane, "BOTTOMRIGHT", -2, 2)
