	local function formatCTAMoneyPlain(copper)
		local c = math.floor((tonumber(copper) or 0) + 0.5)
		if c < 0 then c = 0 end
		local g = math.floor(c / 10000)
		local s = math.floor((c % 10000) / 100)
		local rem = c % 100
		if g > 0 then
			return s > 0 and string.format("%dg %02ds", g, s) or string.format("%dg", g)
		elseif s > 0 then
			return rem > 0 and string.format("%ds %02dc", s, rem) or string.format("%ds", s)
		end
		return string.format("%dc", rem)
	end

	function wrap.updateSummaryRail()
		local pal = getPal()
		local isCustom = ns.Theme.IsCustomSkin and ns.Theme.IsCustomSkin()
		local skinKey = isCustom and ns.Theme.GetSkin and ns.Theme.GetSkin() or "standard"
		local isLight = (pal.mode == "light")
		local hSub = palHex("hexCartSub", isLight and "6b24a8" or "d4b3ff")
		local hMuted = palHex("hexMuted", isLight and "5e626a" or "98989d")

		local posCol = pal.accentGreen or { 0.19, 0.82, 0.35, 1 }
		local subCol = pal.cartSubInk or pal.accentPurple or { 0.83, 0.70, 1, 1 }
		local tealCol = pal.cartSubAccent or { 0.34, 0.83, 0.91, 1 }
		local warnCol = pal.accentOrange or { 0.96, 0.70, 0.26, 1 }
		local goldCol = pal.cartMainAccent or pal.gold or { 0.97, 0.84, 0.49, 1 }
		local secCol = pal.textSecondary or { 0.8, 0.8, 0.85, 1 }
		local mutCol = pal.textMuted or { 0.6, 0.6, 0.65, 1 }
		local txtCol = pal.text or { 1, 1, 1, 1 }
		local fbCol = (isCustom and pal.frameBorder) or pal.borderStrong or { 0.75, 0.56, 0.18, 0.75 }
		local tc = (isCustom and pal.headGold) or pal.text

		-- Paint Header Pills (Legend + Use Owned + Sort)
		local lpFill = isLight and { 0.94, 0.95, 0.97, 0.96 } or { 0.03, 0.10, 0.07, 0.88 }
		legendPill.plate:SetFill(lpFill[1], lpFill[2], lpFill[3], lpFill[4])
		legendPill.plate:SetStroke(fbCol[1], fbCol[2], fbCol[3], isLight and 0.45 or 0.55)
		sw1:SetColorTexture(goldCol[1], goldCol[2], goldCol[3], 1)
		sw2:SetColorTexture(subCol[1], subCol[2], subCol[3], 1)
		sw3:SetColorTexture(posCol[1], posCol[2], posCol[3], 1)
		sw1Fs:SetTextColor(txtCol[1], txtCol[2], txtCol[3], 1)
		sw2Fs:SetTextColor(txtCol[1], txtCol[2], txtCol[3], 1)
		sw3Fs:SetTextColor(txtCol[1], txtCol[2], txtCol[3], 1)

		local useOwnedOn = MerchantMasterDB and MerchantMasterDB.craftOrderDeductOwned == true
		if useOwnedOn then
			local ob = pal.pillBuyBg or { 0.07, 0.36, 0.21, 0.90 }
			useOwnedBtn.plate:SetFill(ob[1], ob[2], ob[3], isLight and 0.16 or 0.60)
			useOwnedBtn.plate:SetStroke(posCol[1], posCol[2], posCol[3], 0.88)
			useOwnedBtn.dot:SetVertexColor(posCol[1], posCol[2], posCol[3], 1)
			useOwnedBtn.fs:SetTextColor(posCol[1], posCol[2], posCol[3], 1)
		else
			useOwnedBtn.plate:SetFill(lpFill[1], lpFill[2], lpFill[3], lpFill[4])
			useOwnedBtn.plate:SetStroke(fbCol[1], fbCol[2], fbCol[3], 0.65)
			useOwnedBtn.dot:SetVertexColor(mutCol[1], mutCol[2], mutCol[3], 0.85)
			useOwnedBtn.fs:SetTextColor(txtCol[1], txtCol[2], txtCol[3], 1)
		end
		sortScopeBtn.plate:SetFill(lpFill[1], lpFill[2], lpFill[3], lpFill[4])
		sortScopeBtn.plate:SetStroke(fbCol[1], fbCol[2], fbCol[3], 0.72)
		sortScopeBtn.fs:SetTextColor(txtCol[1], txtCol[2], txtCol[3], 1)
		subHintFs:SetTextColor(mutCol[1], mutCol[2], mutCol[3], 1)

		local rows = wrap.rawRows or wrap.currentRows or {}
		local b = (wrap.lastMeta and wrap.lastMeta.buckets)
			or (ns.ComputeShoppingBuckets and ns.ComputeShoppingBuckets(rows))
			or { ahCount = 0, ahUnits = 0, ahCost = 0, craftCount = 0, craftUnits = 0, craftSavings = 0, vendorCount = 0, vendorCost = 0, ownedCount = 0 }

		local mainOrders = 0
		for _, r in ipairs(rows) do
			if r.isMainRow then mainOrders = mainOrders + 1 end
		end
		if mainOrders == 0 and #rows > 0 then mainOrders = #rows end

		-- Clean Left Subheader: CART ORDERS & BREAKDOWN + [N Main Orders] pill + non-overlapping right hint
		titleFs:SetText("CART ORDERS & BREAKDOWN")
		titleFs:SetTextColor(tc[1], tc[2], tc[3], 1)
		local titleW = (titleFs.GetStringWidth and titleFs:GetStringWidth()) or 0
		titleFs:SetWidth(math.max(176, math.ceil(titleW) + 4))
		local countTxt = string.format("%d Main Order%s", mainOrders, mainOrders == 1 and "" or "s")
		orderCountPill.fs:SetText(countTxt)
		local oFill = isLight and { 0.84, 0.62, 0.12, 0.14 } or { 0.83, 0.64, 0.24, 0.18 }
		local oStroke = isLight and { 0.72, 0.50, 0.08, 0.65 } or { 0.83, 0.64, 0.24, 0.72 }
		local oInk = isLight and { 0.54, 0.34, 0.0, 1 } or goldCol
		orderCountPill.plate:SetFill(oFill[1], oFill[2], oFill[3], oFill[4])
		orderCountPill.plate:SetStroke(oStroke[1], oStroke[2], oStroke[3], oStroke[4])
		if orderCountPill.plate.SetCapWidth then orderCountPill.plate:SetCapWidth(10) end
		orderCountPill.fs:SetTextColor(oInk[1], oInk[2], oInk[3], 1)
		local tw = (orderCountPill.fs.GetStringWidth and orderCountPill.fs:GetStringWidth()) or 0
		orderCountPill:SetWidth(math.max(88, math.ceil((tw > 10 and tw or (#countTxt * 6.5))) + 18))
		orderCountPill:ClearAllPoints()
		orderCountPill:SetPoint("LEFT", titleFs, "RIGHT", 8, 0)
		subHintFs:ClearAllPoints()
		subHintFs:SetPoint("LEFT", orderCountPill, "RIGHT", 12, 0)
		subHintFs:SetPoint("RIGHT", subHdr, "RIGHT", -2, 0)

		if modal and modal.hdrSubFs then
			if #rows == 0 then
				modal.hdrSubFs:SetText("0 QUEUED ORDERS · CART EMPTY")
			else
				modal.hdrSubFs:SetText(string.format("%d QUEUED ORDER%s · %d AH · %d SUB-CRAFT%s",
					mainOrders, mainOrders == 1 and "" or "S", b.ahCount or 0, b.craftCount or 0, (b.craftCount == 1) and "" or "S"))
			end
		end

		-- Outer Order Summary Rail chrome: lush #0c2216 Baron emerald fill + unbroken burnished gold #c0902e border!
		local railBg = isLight and { 0.96, 0.96, 0.98, 1 }
			or (skinKey == "goblin" and { 0.047, 0.133, 0.086, 0.96 }
			or { pal.cardAltBg[1], pal.cardAltBg[2], pal.cardAltBg[3], 0.98 })
		local goldRailEdge = (skinKey == "goblin") and { 0.753, 0.565, 0.180, 1.0 } or fbCol
		summaryRail.plate:SetFill(railBg[1], railBg[2], railBg[3], railBg[4])
		summaryRail.plate:SetStroke(goldRailEdge[1], goldRailEdge[2], goldRailEdge[3], isLight and 0.45 or 1.0)
		for _, edge in pairs(summaryRail.goldEdges) do
			if isCustom then
				edge:SetColorTexture(goldRailEdge[1], goldRailEdge[2], goldRailEdge[3], 0.96)
				edge:Show()
			else
				edge:Hide()
			end
		end

		-- Repeating quilted crimson velvet cushion header (header_tile.blp beneath panel_hdr at alpha 0.68)
		syncRailHdrTile(isCustom, skinKey)
		if isCustom and ns.Theme.GetSkinAsset then
			railHdrSkinBg:SetTexture(ns.Theme.GetSkinAsset(skinKey, "panel_hdr"))
			railHdrSkinBg:SetVertexColor(1, 1, 1, 0.68)
			railHdrSkinBg:Show()
		else
			railHdrSkinBg:Hide()
		end
		railHdrSep:SetColorTexture(goldRailEdge[1], goldRailEdge[2], goldRailEdge[3], isCustom and 0.94 or 0.25)
		railTitleFs:SetTextColor(tc[1], tc[2], tc[3], 1)

		local rbFill = isLight and { 0.00, 0.48, 0.18, 0.12 } or { 0.04, 0.14, 0.09, 0.92 }
		railBadgeWrap.plate:SetFill(rbFill[1], rbFill[2], rbFill[3], rbFill[4])
		railBadgeWrap.plate:SetStroke(posCol[1], posCol[2], posCol[3], 0.78)
		if railBadgeWrap.plate.SetCapWidth then railBadgeWrap.plate:SetCapWidth(10) end
		railBadgeFs:SetTextColor(posCol[1], posCol[2], posCol[3], 1)
		railBadgeFs:SetText(string.format("%d AH · %d Craft", b.ahCount or 0, b.craftCount or 0))

		-- 1. BUY ON AUCTION HOUSE (Horizontal Emerald Gradient Card + Basket Icon)
		local ahFill = isLight and { 0.92, 0.98, 0.94, 1 } or { 0.058, 0.235, 0.146, 0.94 }
		ahCard.plate:SetFill(ahFill[1], ahFill[2], ahFill[3], ahFill[4])
		ahCard.plate:SetStroke(posCol[1], posCol[2], posCol[3], isLight and 0.55 or 0.78)
		if ahCard.gradTex and ns.Theme.SetGradientFill then
			ns.Theme.SetGradientFill(ahCard.gradTex, "HORIZONTAL",
				isLight and { 0.89, 0.97, 0.92, 1 } or { 0.08, 0.34, 0.21, 0.92 },
				isLight and { 0.95, 0.99, 0.96, 1 } or { 0.035, 0.13, 0.082, 0.95 })
			ahCard.gradTex:Show()
		end
		ahCard.bar:SetColorTexture(posCol[1], posCol[2], posCol[3], 1)
		if ahCard.icon then ahCard.icon:SetVertexColor(posCol[1], posCol[2], posCol[3], 1) end
		ahCard.labelFs:SetTextColor(posCol[1], posCol[2], posCol[3], 1)
		ahCard.labelFs:SetText("BUY ON AUCTION HOUSE")
		ahCard.valFs:SetText(ns.FormatMoneyCompact(b.ahCost or 0))
		ahCard.subFs:SetTextColor(secCol[1], secCol[2], secCol[3], 1)
		ahCard.subFs:SetText(string.format("%d item%s · %d units", b.ahCount or 0, (b.ahCount == 1) and "" or "s", b.ahUnits or 0))
		ahCard.tagFs:SetTextColor(posCol[1], posCol[2], posCol[3], 1)
		ahCard.tagFs:SetText("Sent to AH")

		-- 2. CRAFT YOURSELF (Horizontal Arcane Violet -> Cool Teal Gradient Card + Cyan Accent + "Not sent to AH" Pill)
		local crFill = isLight and { 0.95, 0.92, 0.99, 1 } or { 0.18, 0.15, 0.36, 0.94 }
		local crBorder = isLight and { 0.44, 0.16, 0.70, 0.55 } or { 0.66, 0.46, 0.97, 0.82 }
