		-- 6. HERO "Send to Auction House" CTA (vertical emerald gradient + skin send_btn icon at 34x34 + #84 4-stage subtext)
		local hasAH = (b.ahCount or 0) > 0
		local flowCraftCount = 0
		for _, r in ipairs(rows) do
			if r.isMainRow then
				if r.spellID or r.sourceKind == "craft_order" or r.sourceKind == "writ_craft"
					or r.sourceKind == "spread" or r.sourceKind == "leveling" or r.asCraft == true then
					flowCraftCount = flowCraftCount + 1
				end
			elseif r.makeMyself == true and (tonumber(r.qty) or 0) > 0 then
				flowCraftCount = flowCraftCount + 1
			end
		end
		local hasFlowWork = (#rows > 0) and (hasAH or (b.vendorCount or 0) > 0 or (b.ownedCount or 0) > 0 or flowCraftCount > 0)
		local canRunCTA = hasFlowWork
		buyAllBtn:SetText("Send to Auction House")
		buyAllBtn:SetEnabled(canRunCTA)
		if canRunCTA then
			local ctaTop = isLight and { 0.07, 0.52, 0.28, 1 } or { 0.153, 0.725, 0.435, 1 }
			local ctaBot = isLight and { 0.03, 0.36, 0.19, 1 } or { 0.047, 0.302, 0.176, 1 }
