			buyAllBtn.spec:SetVertexColor(1, 1, 1, 0.28)
			if isCustom and ns.Theme.GetSkinAsset then
				buyAllBtn.gemWrap:SetSize(34, 34)
				buyAllBtn.skinGem:SetTexture(ns.Theme.GetSkinAsset(skinKey, "send_btn"))
				buyAllBtn.skinGem:SetVertexColor(1, 1, 1, 1)
				buyAllBtn.skinGem:Show()
				buyAllBtn.gemBg:Hide(); buyAllBtn.gemRing:Hide(); buyAllBtn.gemIcon:Hide()
			else
				buyAllBtn.gemWrap:SetSize(30, 30)
				buyAllBtn.skinGem:Hide()
				buyAllBtn.gemBg:SetVertexColor(0.18, 0.95, 0.56, 1); buyAllBtn.gemBg:Show()
				buyAllBtn.gemRing:SetVertexColor(1.0, 0.95, 0.77, 0.92); buyAllBtn.gemRing:Show()
				buyAllBtn.gemIcon:SetVertexColor(0.03, 0.18, 0.10, 1); buyAllBtn.gemIcon:Show()
			end
			buyAllBtn.fs:SetTextColor(1, 1, 1, 1)
			buyAllBtn.subFs:SetTextColor(0.85, 1.0, 0.93, 1)
			buyAllBtn.arrowFs:SetTextColor(goldCol[1], goldCol[2], goldCol[3], 1)
			local parts = {}
			if hasAH then parts[#parts + 1] = string.format("%d AH", b.ahCount) end
			if (b.vendorCount or 0) > 0 then parts[#parts + 1] = string.format("%d Vendor", b.vendorCount) end
			if (not hasAH) and (b.ownedCount or 0) > 0 then parts[#parts + 1] = string.format("%d Owned", b.ownedCount) end
			if flowCraftCount > 0 then parts[#parts + 1] = string.format("%d Craft%s", flowCraftCount, flowCraftCount == 1 and "" or "s") end
			local outlayCopper = (b.ahCost or 0) + (b.vendorCost or 0)
			if #parts <= 2 and outlayCopper > 0 then
				parts[#parts + 1] = formatCTAMoneyPlain(outlayCopper)
			end
			buyAllBtn.subFs:SetText(#parts > 0 and table.concat(parts, " - ") or "Open 4-Stage Order Strip")
		else
			local disTop = isLight and { 0.91, 0.93, 0.95, 1 } or { 0.055, 0.13, 0.09, 0.96 }
			local disBot = isLight and { 0.86, 0.88, 0.91, 1 } or { 0.03, 0.08, 0.055, 0.98 }
			local disFill = isLight and { 0.89, 0.91, 0.93, 1 } or { 0.04, 0.10, 0.07, 0.96 }
			local disStroke = isLight and { 0.68, 0.71, 0.76, 1 } or { 0.24, 0.38, 0.30, 0.80 }
			local disInk = isLight and { 0.26, 0.28, 0.32, 1 } or { 0.72, 0.80, 0.76, 1 }
			buyAllBtn.plate:SetFill(disFill[1], disFill[2], disFill[3], disFill[4])
			buyAllBtn.plate:SetStroke(disStroke[1], disStroke[2], disStroke[3], disStroke[4])
			if buyAllBtn.gradTex and ns.Theme.SetGradientFill then
				ns.Theme.SetGradientFill(buyAllBtn.gradTex, "VERTICAL", disTop, disBot)
				buyAllBtn.gradTex:Show()
			end
			buyAllBtn.spec:SetVertexColor(1, 1, 1, 0.04)
			buyAllBtn.gemWrap:SetSize(30, 30)
			buyAllBtn.skinGem:Hide()
			buyAllBtn.gemBg:SetVertexColor(disStroke[1], disStroke[2], disStroke[3], 0.65); buyAllBtn.gemBg:Show()
			buyAllBtn.gemRing:Hide()
			buyAllBtn.gemIcon:SetVertexColor(disInk[1], disInk[2], disInk[3], 1); buyAllBtn.gemIcon:Show()
			buyAllBtn.fs:SetTextColor(disInk[1], disInk[2], disInk[3], 1)
			buyAllBtn.subFs:SetTextColor(disInk[1], disInk[2], disInk[3], 1)
			buyAllBtn.arrowFs:SetTextColor(disInk[1], disInk[2], disInk[3], 1)
			buyAllBtn.subFs:SetText("Add items to cart to start AH buying")
		end

		-- 8. HERO 38px Rich Ruby-Crimson Velvet "Empty Cart" Button (vertical crimson gradient + bold pure white text)
		local hasRows = #rows > 0
		clearShopBtn:SetText(mainOrders > 0 and string.format("Empty Cart (%d Order%s)", mainOrders, mainOrders == 1 and "" or "s") or "Empty Cart")
		clearShopBtn:SetEnabled(hasRows)
		local dBd = isLight and { 0.72, 0.12, 0.16, 0.72 } or { 0.88, 0.31, 0.37, 0.96 }
		if hasRows then
			local dTop = isLight and { 0.99, 0.92, 0.93, 1 } or { 0.545, 0.090, 0.161, 1 }
			local dBot = isLight and { 0.95, 0.85, 0.87, 1 } or { 0.322, 0.039, 0.086, 1 }
			local dBg = { (dTop[1] + dBot[1]) * 0.5, (dTop[2] + dBot[2]) * 0.5, (dTop[3] + dBot[3]) * 0.5, 1 }
			local dInk = isLight and { 0.68, 0.06, 0.10, 1 } or { 1.0, 1.0, 1.0, 1 }
			clearShopBtn.plate:SetFill(dBg[1], dBg[2], dBg[3], dBg[4])
			clearShopBtn.plate:SetStroke(dBd[1], dBd[2], dBd[3], dBd[4])
			if clearShopBtn.gradTex and ns.Theme.SetGradientFill then
				ns.Theme.SetGradientFill(clearShopBtn.gradTex, "VERTICAL", dTop, dBot)
				clearShopBtn.gradTex:Show()
			end
			if not isLight then
				clearShopBtn.skinSheen:SetVertexColor(1, 1, 1, 0.18)
				clearShopBtn.skinSheen:Show()
			else
				clearShopBtn.skinSheen:Hide()
			end
			clearShopBtn.icon:SetVertexColor(dInk[1], dInk[2], dInk[3], 1)
			clearShopBtn.fs:SetTextColor(dInk[1], dInk[2], dInk[3], 1)
		else
			local disBg = isLight and { 0.92, 0.90, 0.91, 1 } or { 0.13, 0.04, 0.06, 0.96 }
			local disInk = isLight and { 0.32, 0.30, 0.32, 1 } or { 0.76, 0.70, 0.72, 1 }
			clearShopBtn.plate:SetFill(disBg[1], disBg[2], disBg[3], disBg[4])
			clearShopBtn.plate:SetStroke(dBd[1], dBd[2], dBd[3], 0.42)
			if clearShopBtn.gradTex then clearShopBtn.gradTex:Hide() end
			clearShopBtn.skinSheen:Hide()
			clearShopBtn.icon:SetVertexColor(disInk[1], disInk[2], disInk[3], 1)
			clearShopBtn.fs:SetTextColor(disInk[1], disInk[2], disInk[3], 1)
		end
		dangerSep:SetColorTexture(dBd[1], dBd[2], dBd[3], isLight and 0.24 or 0.32)
		dangerNoteFs:SetTextColor(mutCol[1], mutCol[2], mutCol[3], 1)
		dangerNoteFs:SetText(hasRows and string.format("Safely clears all %d queued order%s & materials", mainOrders, mainOrders == 1 and "" or "s") or "No queued orders in cart")

		-- 9. Empty Cart State V3 Socketed Medallion + Lush Emerald Fill across ALL 6 themes!
		local empFill = isLight and { 0.97, 0.97, 0.98, 1 } or { 0.047, 0.133, 0.086, 0.94 }
		emptyState.plate:SetFill(empFill[1], empFill[2], empFill[3], empFill[4])
		emptyState.plate:SetStroke(goldRailEdge[1], goldRailEdge[2], goldRailEdge[3], isLight and 0.35 or 0.65)
		emptyMedWrap.sock:Hide()
		local medTex = (ns.Theme.GetCartMedallionAsset and ns.Theme.GetCartMedallionAsset(skinKey))
			or (isCustom and ns.Theme.GetSkinAsset and ns.Theme.GetSkinAsset(skinKey, "portrait"))
			or ns.ADDON_ICON_SMALL or ns.ADDON_ICON or ns.CRATE_ICON
		emptyMedWrap.icon:SetTexture(medTex)
		emptyTitleFs:SetTextColor(tc[1], tc[2], tc[3], 1)
		emptyHintFs:SetTextColor(secCol[1], secCol[2], secCol[3], 1)
		emptyState:SetShown(#rows == 0)
	end

	-- Responsive Vertical Layout for Order Summary Rail: mathematically guaranteed ZERO bottom overflow & ZERO overlap at ANY height!
	function wrap.layoutSummaryRail()
		local availH = (summaryRail.GetHeight and summaryRail:GetHeight()) or 0
		if availH <= 0 then
			local mh = (modal and modal.GetHeight and modal:GetHeight()) or 720
			local isCustom = ns.Theme and ns.Theme.IsCustomSkin and ns.Theme.IsCustomSkin()
			availH = math.max(320, mh - (isCustom and 112 or 68))
		end

		local hdrH, ahCardH, craftCardH, smallCardH, outlayH, ctaH, emptyH, noteH
		local gap, ctaGap, bottomPad, noteGap, minFreeGap

		if availH >= 570 then
			hdrH, gap, ctaGap = 34, 9, 14
			ahCardH, craftCardH, smallCardH, outlayH = 56, 60, 48, 48
			ctaH = 54
			emptyH, noteH, bottomPad, noteGap, minFreeGap = 38, 14, 6, 4, 8
		elseif availH >= 520 then
			hdrH, gap, ctaGap = 32, 8, 12
			ahCardH, craftCardH, smallCardH, outlayH = 52, 58, 46, 46
			ctaH = 52
			emptyH, noteH, bottomPad, noteGap, minFreeGap = 36, 14, 6, 4, 8
		else
			hdrH, gap, ctaGap = 30, 6, 10
			ahCardH, craftCardH, smallCardH, outlayH = 48, 54, 42, 42
			ctaH = 48
			emptyH, noteH, bottomPad, noteGap, minFreeGap = 34, 13, 5, 3, 6
		end

		local bottomReserve = bottomPad + noteH + noteGap + emptyH + minFreeGap
		local topBudget = availH - bottomReserve - 2

		local function calcTopUsed()
			return hdrH + gap + ahCardH + gap + craftCardH + gap + smallCardH + gap
				+ outlayH + ctaGap + ctaH
		end

		local topUsed = calcTopUsed()
		if topUsed > topBudget then
			gap = math.max(3, gap - 2)
			ctaGap = math.max(6, ctaGap - 4)
			bottomPad = math.max(4, bottomPad - 1)
			noteGap = math.max(2, noteGap - 1)
			minFreeGap = math.max(4, minFreeGap - 2)
			bottomReserve = bottomPad + noteH + noteGap + emptyH + minFreeGap
			topBudget = availH - bottomReserve - 2
			topUsed = calcTopUsed()
		end
		if topUsed > topBudget then
			local fixedGaps = (gap * 4) + ctaGap
			local blocksTotal = hdrH + ahCardH + craftCardH + smallCardH + outlayH + ctaH
			local availBlocks = math.max(160, topBudget - fixedGaps)
			local ratio = math.min(1, availBlocks / math.max(1, blocksTotal))
			hdrH       = math.max(22, math.floor(hdrH * ratio))
			ahCardH    = math.max(32, math.floor(ahCardH * ratio))
			craftCardH = math.max(36, math.floor(craftCardH * ratio))
			smallCardH = math.max(30, math.floor(smallCardH * ratio))
			outlayH    = math.max(30, math.floor(outlayH * ratio))
			ctaH       = math.max(34, math.floor(ctaH * ratio))
			topUsed = calcTopUsed()
			if topUsed > topBudget then
				emptyH = math.max(26, math.floor(emptyH * ratio))
				noteH = math.max(11, math.floor(noteH * ratio))
				bottomReserve = bottomPad + noteH + noteGap + emptyH + minFreeGap
				topBudget = availH - bottomReserve - 2
				local excess = topUsed - topBudget
				if excess > 0 then
					local trim = math.ceil(excess / 5)
					ahCardH    = math.max(28, ahCardH - trim)
					craftCardH = math.max(32, craftCardH - trim)
					smallCardH = math.max(26, smallCardH - trim)
					outlayH    = math.max(26, outlayH - trim)
					ctaH       = math.max(30, ctaH - trim)
				end
			end
		end

		railHdr:ClearAllPoints()
		railHdr:SetPoint("TOPLEFT", summaryRail, "TOPLEFT", 2, -2)
		railHdr:SetPoint("TOPRIGHT", summaryRail, "TOPRIGHT", -2, -2)
		railHdr:SetHeight(hdrH)
		syncRailHdrTile()

		local y = -(2 + hdrH + gap)
		ahCard:ClearAllPoints()
		ahCard:SetPoint("TOPLEFT", summaryRail, "TOPLEFT", 12, y)
		ahCard:SetPoint("TOPRIGHT", summaryRail, "TOPRIGHT", -12, y)
		ahCard:SetHeight(ahCardH)
		y = y - ahCardH - gap

		craftCard:ClearAllPoints()
		craftCard:SetPoint("TOPLEFT", summaryRail, "TOPLEFT", 12, y)
		craftCard:SetPoint("TOPRIGHT", summaryRail, "TOPRIGHT", -12, y)
		craftCard:SetHeight(craftCardH)
		y = y - craftCardH - gap

		local hw = math.floor(RAIL_W * 0.5)
		vendorCard:ClearAllPoints()
		vendorCard:SetPoint("TOPLEFT", summaryRail, "TOPLEFT", 12, y)
		vendorCard:SetPoint("TOPRIGHT", summaryRail, "TOPRIGHT", -(hw + 3), y)
		vendorCard:SetHeight(smallCardH)
		ownedCard:ClearAllPoints()
		ownedCard:SetPoint("TOPLEFT", summaryRail, "TOPLEFT", hw + 3, y)
		ownedCard:SetPoint("TOPRIGHT", summaryRail, "TOPRIGHT", -12, y)
		ownedCard:SetHeight(smallCardH)
		y = y - smallCardH - gap

		outlayCard:ClearAllPoints()
		outlayCard:SetPoint("TOPLEFT", summaryRail, "TOPLEFT", 12, y)
		outlayCard:SetPoint("TOPRIGHT", summaryRail, "TOPRIGHT", -12, y)
		outlayCard:SetHeight(outlayH)
		y = y - outlayH - ctaGap

		buyAllBtn:ClearAllPoints()
		buyAllBtn:SetPoint("TOPLEFT", summaryRail, "TOPLEFT", 12, y)
		buyAllBtn:SetPoint("TOPRIGHT", summaryRail, "TOPRIGHT", -12, y)
		buyAllBtn:SetHeight(ctaH)
		local ctaBottomOffset = (-y) + ctaH

		-- ALWAYS dock dangerNoteFs and clearShopBtn cleanly inside BOTTOM of summaryRail (can NEVER escape outside frame!)
		local clearBottomOff = bottomPad + noteH + noteGap
		dangerNoteFs:ClearAllPoints()
		dangerNoteFs:SetPoint("BOTTOMLEFT", summaryRail, "BOTTOMLEFT", 12, bottomPad)
		dangerNoteFs:SetPoint("BOTTOMRIGHT", summaryRail, "BOTTOMRIGHT", -12, bottomPad)
		clearShopBtn:ClearAllPoints()
		clearShopBtn:SetHeight(emptyH)
		clearShopBtn:SetPoint("BOTTOMLEFT", summaryRail, "BOTTOMLEFT", 12, clearBottomOff)
		clearShopBtn:SetPoint("BOTTOMRIGHT", summaryRail, "BOTTOMRIGHT", -12, clearBottomOff)
		dangerSep:ClearAllPoints()
		local sepOff = clearBottomOff + emptyH + 8
		dangerSep:SetPoint("BOTTOMLEFT", summaryRail, "BOTTOMLEFT", 12, sepOff)
		dangerSep:SetPoint("BOTTOMRIGHT", summaryRail, "BOTTOMRIGHT", -12, sepOff)
		dangerSep:SetShown((availH - sepOff - 4) > ctaBottomOffset)

		local emptyBottom = availH - clearBottomOff
		local emptyTop = emptyBottom - emptyH
		local craftValBottom = 7 + 12 -- TOPRIGHT -7 + 12pt font height
		local craftPillH = (craftCard.tagPillWrap and craftCard.tagPillWrap.GetHeight and craftCard.tagPillWrap:GetHeight()) or 18
		local craftPillTop = craftCardH - 6 - craftPillH
		wrap._railMetrics = {
			availH = availH,
			ctaTop = -y,
			ctaBottom = ctaBottomOffset,
			emptyTop = emptyTop,
			emptyBottom = emptyBottom,
			clearBottomOff = clearBottomOff,
			dangerBottomOff = bottomPad,
			craftCardH = craftCardH,
			craftValBottom = craftValBottom,
			craftPillTop = craftPillTop,
			craftGap = craftPillTop - craftValBottom,
		}
	end

	if summaryRail.HookScript then
		summaryRail:HookScript("OnSizeChanged", function()
			wrap.layoutSummaryRail()
		end)
	end

	function wrap.layoutColumns()
		wrap.layoutSummaryRail()
		if wrap.table and wrap.table.updateHeaders then
			wrap.table.updateHeaders()
		end
	end

	function wrap.bindShoppingRows()
		wrap.table.updateHeaders()
		wrap.table.setRows(wrap.currentRows)
		wrap.layoutSummaryRail()
		wrap.updateSummaryRail()
		wrap.shoppingBindPending = nil
	end

	function wrap.setShoppingData(rows, summaryStr, rawRows, deferBind, meta)
		wrap.rawRows = rawRows or rows or {}
		wrap.lastMeta = meta
		local sortScope = (MerchantMasterDB and MerchantMasterDB.shoppingSortScope == "sub") and "sub" or "main"
		sortScopeBtn:SetText(sortScope == "sub" and "Sort: Sub-Items" or "Sort: Main Items")
		if useOwnedBtn then
			local useOwnedOn = MerchantMasterDB and MerchantMasterDB.craftOrderDeductOwned == true
			useOwnedBtn:SetText(useOwnedOn and "Use Owned: On" or "Use Owned: Off")
		end
		local st = app.sortState.shopping_list or { col = "default", asc = true }
		local displayRows = (ns.SortHierarchicalShoppingRows and ns.SortHierarchicalShoppingRows(rows or {}, st.col, st.asc, sortScope)) or (rows or {})
		if sortScope == "main" then
			local curMain = nil
			for i = 1, #displayRows do
				local row = displayRows[i]
				if row.isMainRow then
					curMain = row
					curMain._subCraftCount = 0
					curMain._directMatCount = 0
				elseif curMain then
					local isSubHdr = (row.makeMyself or row.canToggleCraft) and true or false
					local isNest = (not isSubHdr) and (row.isSubRow == true or (tonumber(row.indent) or 0) >= 2)
					if isSubHdr then
						curMain._subCraftCount = curMain._subCraftCount + 1
					elseif not isNest then
						curMain._directMatCount = curMain._directMatCount + 1
					end
				end
			end
			local inGroup = false
			local inSub = false
			for i = 1, #displayRows do
				local row = displayRows[i]
				local nextR = displayRows[i + 1]
				if row.isMainRow then
					inGroup = true
					inSub = false
				end
				row._inMainGroup = inGroup
				row._isGroupFirst = (row.isMainRow == true)
				row._isGroupLast = inGroup and (nextR == nil or nextR.isMainRow == true)
				if inGroup and not row.isMainRow then
					local isSubHdr = (row.makeMyself or row.canToggleCraft) and true or false
					local isNest = (not isSubHdr) and (row.isSubRow == true or (tonumber(row.indent) or 0) >= 2)
					if isSubHdr and row.makeMyself == true then
						inSub = true
						row._inSubBlock = true
						row._isSubFirst = true
					elseif inSub and isNest then
						row._inSubBlock = true
						row._isSubFirst = false
					else
						inSub = false
						row._inSubBlock = false
						row._isSubFirst = false
					end
					if row._inSubBlock then
						local nextIsSubHdr = nextR and (not nextR.isMainRow) and ((nextR.makeMyself or nextR.canToggleCraft) and true or false)
						local nextIsNest = nextR and (not nextR.isMainRow) and (not nextIsSubHdr) and (nextR.isSubRow == true or (tonumber(nextR.indent) or 0) >= 2)
						row._isSubLast = not nextIsNest
					else
						row._isSubLast = false
					end
				else
					row._inSubBlock = false
					row._isSubFirst = false
					row._isSubLast = false
				end
			end
		else
			for i = 1, #displayRows do
				local row = displayRows[i]
				row._inMainGroup = false
				row._isGroupFirst = false
				row._isGroupLast = false
				row._inSubBlock = false
				row._isSubFirst = false
				row._isSubLast = false
			end
		end
		wrap.currentRows = displayRows
		wrap.summaryStr = summaryStr
		titleFs:SetText("CART ORDERS & BREAKDOWN")
		wrap.layoutSummaryRail()
		wrap.updateSummaryRail()
		if deferBind then
			wrap.shoppingBindPending = true
		else
			wrap.bindShoppingRows()
		end
		return displayRows
	end

	wrap.layoutSummaryRail()
	return wrap
end

-- Detachable Floating Shopping List Window + Unified Active Shopping List Controller
do
	local EMPTY_SHOPPING_SUMMARY = "|cffaaaaaaShopping List is empty. Click [+ Add to List] or [+ Queue] on any screen.|r"
	local SHOP_DEFAULT_W, SHOP_DEFAULT_H = 1160, 720
	local SHOP_MIN_W, SHOP_MIN_H = 960, 660
	local SHOP_MAX_W, SHOP_MAX_H = 1440, 920
	local shopModal, shopPanel

	local function saveShopWindowSize(w, h)
		if not (MerchantMasterDB and w and h) then return end
		local nw = math.floor(math.max(SHOP_MIN_W, math.min(SHOP_MAX_W, w)) + 0.5)
		local nh = math.floor(math.max(SHOP_MIN_H, math.min(SHOP_MAX_H, h)) + 0.5)
		local scale = (shopModal and shopModal.GetScale and shopModal:GetScale()) or 1
		local effScale = (shopModal and shopModal.GetEffectiveScale and shopModal:GetEffectiveScale()) or scale
		local uiW = (UIParent and UIParent.GetWidth and UIParent:GetWidth()) or 0
		local uiH = (UIParent and UIParent.GetHeight and UIParent:GetHeight()) or 0
		local railH = (shopPanel and shopPanel.summaryRail and shopPanel.summaryRail.GetHeight and shopPanel.summaryRail:GetHeight()) or 0
		MerchantMasterDB.shoppingWindowSize = {
			w = nw,
			h = nh,
			scale = math.floor(scale * 1000 + 0.5) / 1000,
			effScale = math.floor(effScale * 1000 + 0.5) / 1000,
			uiW = math.floor(uiW + 0.5),
			uiH = math.floor(uiH + 0.5),
			railH = math.floor(railH + 0.5),
			measuredAt = time and time() or 0,
		}
	end

	local function applyShopWindowGeometry()
		local sz = MerchantMasterDB and MerchantMasterDB.shoppingWindowSize
		local targetW, targetH = SHOP_DEFAULT_W, SHOP_DEFAULT_H
		if type(sz) == "table" and tonumber(sz.w) and tonumber(sz.h) then
			targetW = math.floor(math.max(SHOP_MIN_W, math.min(SHOP_MAX_W, tonumber(sz.w))) + 0.5)
			local rawH = tonumber(sz.h)
			-- Upgrade stale saved heights (< 660, including 470-580px) to the spacious 720px default once
			if rawH < SHOP_MIN_H then
				targetH = SHOP_DEFAULT_H
				sz.h = SHOP_DEFAULT_H
			else
				targetH = math.floor(math.min(SHOP_MAX_H, rawH) + 0.5)
			end
		end
		-- Prevent WoW's layout-local.txt from reverting named frame size back to legacy 1096x470 on /reload
		if shopModal.SetDontSavePosition then shopModal:SetDontSavePosition(true) end
		if shopModal.SetUserPlaced then shopModal:SetUserPlaced(false) end

		-- Viewport-fit scale (mirrors UI_Window.lua:63 so 1160x720 fits cleanly even on WoW's 768px virtual UI height)
		local sw = (UIParent and UIParent.GetWidth and UIParent:GetWidth()) or 1920
		local sh = (UIParent and UIParent.GetHeight and UIParent:GetHeight()) or 1080
		if sw <= 0 then sw = 1920 end
		if sh <= 0 then sh = 1080 end
		local prefScale = (MerchantMasterDB and MerchantMasterDB.window and tonumber(MerchantMasterDB.window.scale)) or 1
		prefScale = math.max(0.65, math.min(1.35, prefScale))
		local fitScale = math.max(0.55, math.min(prefScale, (sw - 24) / targetW, (sh - 24) / targetH))

		shopModal._mmApplyingSize = true
		if shopModal.SetScale then shopModal:SetScale(fitScale) end
		shopModal:SetSize(targetW, targetH)
		if not shopModal._mmUserPositioned then
			shopModal:ClearAllPoints()
			shopModal:SetPoint("CENTER", UIParent, "CENTER", 0, 0)
		end
		shopModal._mmApplyingSize = false
		if shopModal.warcraftChrome and ns.Theme and ns.Theme.IsCustomSkin and ns.Theme.IsCustomSkin() then
			shopModal.warcraftChrome:Layout()
		end
		return targetW, targetH, fitScale
	end

	shopModal = ns.Theme.CreateFloatingWindow(ADDON .. "ShoppingWindow", "Shopping List", SHOP_DEFAULT_W, SHOP_DEFAULT_H, {
		warcraftChrome = true,
		hideCrest = true,
		showPortrait = true,
		useCartMedallion = true,
		customTitleUpper = true,
		headerHeight = 52,
		titleMaxWidth = 340,
		centerY = 0,
		dontSaveLayout = true,
		resizable = true,
		resizeTitle = "Resize Shopping List",
		minW = SHOP_MIN_W,
		minH = SHOP_MIN_H,
		maxW = SHOP_MAX_W,
		maxH = SHOP_MAX_H,
		getResizeTooltipInfo = function()
			if app.getShoppingWindowDiagnostics then
				local d = app.getShoppingWindowDiagnostics()
				return string.format("Window: %d x %d · Rail: %d x %d · Screen: %d x %d · Scale: %.2f",
					d.winW, d.winH, d.railW, d.railH, d.uiW, d.uiH, d.scale)
			end
		end,
		onMove = function()
			shopModal._mmUserPositioned = true
		end,
		onResetSize = function(w, h)
			shopModal._mmUserPositioned = false
			saveShopWindowSize(w, h)
			applyShopWindowGeometry()
			if shopPanel and shopPanel.layoutColumns then shopPanel.layoutColumns() end
		end,
		onResize = function(w, h, isUser)
			if isUser and w and h and w >= SHOP_MIN_W and h >= SHOP_MIN_H then
				saveShopWindowSize(w, h)
			end
			if app.ui and app.ui.shopPanel and app.ui.shopPanel.layoutColumns then
				app.ui.shopPanel.layoutColumns()
			end
		end,
	})
	shopPanel = createShoppingListPanel(shopModal.body, 0, true, 0, shopModal)
	app.ui.shopModal = shopModal
	app.ui.shopPanel = shopPanel

	function app.getShoppingWindowDiagnostics()
		local winW = (shopModal.GetWidth and shopModal:GetWidth()) or 0
		local winH = (shopModal.GetHeight and shopModal:GetHeight()) or 0
		local scale = (shopModal.GetScale and shopModal:GetScale()) or 1
		local effScale = (shopModal.GetEffectiveScale and shopModal:GetEffectiveScale()) or scale
		local bodyW = (shopModal.body and shopModal.body.GetWidth and shopModal.body:GetWidth()) or 0
		local bodyH = (shopModal.body and shopModal.body.GetHeight and shopModal.body:GetHeight()) or 0
		local rail = shopPanel and shopPanel.summaryRail
		local railW = (rail and rail.GetWidth and rail:GetWidth()) or 0
		local railH = (rail and rail.GetHeight and rail:GetHeight()) or 0
		local uiW = (UIParent and UIParent.GetWidth and UIParent:GetWidth()) or 0
		local uiH = (UIParent and UIParent.GetHeight and UIParent:GetHeight()) or 0
		local sz = MerchantMasterDB and MerchantMasterDB.shoppingWindowSize
		local savedW = (type(sz) == "table" and tonumber(sz.w)) or nil
		local savedH = (type(sz) == "table" and tonumber(sz.h)) or nil
		local m = shopPanel and shopPanel._railMetrics or {}
		local emptyBtn = shopPanel and shopPanel.clearShopBtn
		local emptyBottomOffset
		if emptyBtn and emptyBtn.GetBottom and rail and rail.GetBottom then
			local eb, rb = emptyBtn:GetBottom(), rail:GetBottom()
			if eb and rb then
				emptyBottomOffset = math.floor((eb - rb) + 0.5)
			end
		end
		if emptyBottomOffset == nil and m.availH and m.emptyBottom then
			emptyBottomOffset = math.floor((m.availH - m.emptyBottom) + 0.5)
		end
		emptyBottomOffset = emptyBottomOffset or 0
		local userPlaced = (shopModal.IsUserPlaced and shopModal:IsUserPlaced()) and true or false
		local savedStr = (savedW and savedH) and string.format("%dx%d", math.floor(savedW + 0.5), math.floor(savedH + 0.5)) or "none"
		local summaryLine = string.format(
			"ShopWindow: %dx%d (scale %.2f, eff %.2f) | Body: %dx%d | Rail: %dx%d | EmptyBtnBottomOffset: %+dpx | UIParent: %dx%d | Saved: %s",
			math.floor(winW + 0.5), math.floor(winH + 0.5),
			scale, effScale,
			math.floor(bodyW + 0.5), math.floor(bodyH + 0.5),
			math.floor(railW + 0.5), math.floor(railH + 0.5),
			emptyBottomOffset,
			math.floor(uiW + 0.5), math.floor(uiH + 0.5),
			savedStr
		)
		return {
			winW = math.floor(winW + 0.5),
			winH = math.floor(winH + 0.5),
			scale = scale,
			effScale = effScale,
			bodyW = math.floor(bodyW + 0.5),
			bodyH = math.floor(bodyH + 0.5),
			railW = math.floor(railW + 0.5),
			railH = math.floor(railH + 0.5),
			emptyBottomOffset = emptyBottomOffset,
			emptyInsideRail = emptyBottomOffset >= 0,
			ctaBottom = m.ctaBottom,
			emptyTop = m.emptyTop,
			emptyBottom = m.emptyBottom,
			uiW = math.floor(uiW + 0.5),
			uiH = math.floor(uiH + 0.5),
			savedW = savedW,
			savedH = savedH,
			userPlaced = userPlaced,
			summaryLine = summaryLine,
		}
	end

	shopModal:HookScript("OnShow", function()
		-- Always enforce geometry (defeats WoW layout-local.txt shrinking MerchantMasterShoppingWindow when DB size is nil!)
		applyShopWindowGeometry()
		if app._singleCraftPreviewDirty and app.singleCraftShoppingPreview and not app.hasUnifiedShoppingItems() then
			app.refreshUnifiedShoppingDisplay()
		elseif shopPanel.shoppingBindPending then
			shopPanel.bindShoppingRows()
		else
			shopPanel.layoutSummaryRail()
			shopPanel.updateSummaryRail()
		end
		shopPanel.layoutColumns()
		if C_Timer and C_Timer.After then
			C_Timer.After(0, function()
				if shopModal:IsShown() then
					local cw = (shopModal.GetWidth and shopModal:GetWidth()) or 0
					local ch = (shopModal.GetHeight and shopModal:GetHeight()) or 0
					if cw < SHOP_MIN_W or ch < SHOP_MIN_H then
						applyShopWindowGeometry()
					end
					shopPanel.layoutSummaryRail()
					shopPanel.updateSummaryRail()
				end
			end)
		end
	end)
	-- Rows and Summary Rail bake palette ink into their text: re-render the open list the moment appearance/skin flips.
	ns.Theme.RegisterWidget(shopPanel, function()
		if shopModal:IsShown() then
			if app.refreshUnifiedShoppingDisplay then app.refreshUnifiedShoppingDisplay() end
			shopPanel.updateSummaryRail()
		end
	end)

	-- Built-in 4-Stage Order & Crafting Task Flow (Baron Trade Strip + Slide-Out Drawer)
	do local function initCartBuyerUI()
	local CB_COMPACT_W = 396
	local CB_EXTENDED_W = 706
	local CB_STRIP_W = 356
	local CB_WIN_H = 684
	local CB_STAGE_BAR_H = 32
	local CB_VISIBLE_ROWS = 8
	local CB_ROW_H = 39
	local CB_VISIBLE_DESTS = 5
	local CB_DEST_H = 45

	local cartBuyerModal = ns.Theme.CreateFloatingWindow(ADDON .. "CartBuyerWindow", "AH TRADE STRIP", CB_COMPACT_W, CB_WIN_H, {
		warcraftChrome = true,
		compactChrome = true,
		headerHeight = 46,
		showPortrait = true,
		titleMaxWidth = 144,
	})
	app.ui.cartBuyerModal = cartBuyerModal
	local cbHdr = cartBuyerModal.header
	local cbBody = cartBuyerModal.body
	local cbExtended = false
	local cbScrollOffset = 0
	local cbDestScrollOffset = 0
	local ui = {}

	-- Reusable visual primitives (real NineApple 9-slices, socket.blp gold sockets, rounded pills)
	local function makeFramedBtn(parent, w, h, label, fontSize, opts)
		opts = opts or {}
		local b = CreateFrame("Button", opts.name, parent)
		b:SetSize(w, h)
		b._enabled = true
		b._label = tostring(label or "")
		b.plate = ns.Theme.NineApple(b, "glass_r8",
			{ 0.08, 0.20, 0.14, 0.94 },
			{ 0.78, 0.56, 0.20, 0.85 },
			{ layer = "BACKGROUND", sub = 0, cornerSize = 8, noSpecular = true })
		if opts.useSkinArt then
			local sa = b:CreateTexture(nil, "ARTWORK", nil, 0)
			sa:SetPoint("TOPLEFT", 2, -2)
			sa:SetPoint("BOTTOMRIGHT", -2, 2)
			sa:Hide()
			b.skinArt = sa
		end
		local spec = b:CreateTexture(nil, "ARTWORK", nil, 1)
		spec:SetTexture(ns.Theme.ASSETS.specular_top)
		spec:SetPoint("TOPLEFT", 4, -1)
		spec:SetPoint("TOPRIGHT", -4, -1)
		spec:SetHeight(2)
		spec:SetVertexColor(1, 0.95, 0.80, 0.22)
		b.spec = spec
		local hov = b:CreateTexture(nil, "HIGHLIGHT")
		hov:SetTexture(ns.Theme.ASSETS.glass_r8_fill)
		hov:SetPoint("TOPLEFT", 1, -1)
		hov:SetPoint("BOTTOMRIGHT", -1, 1)
		hov:SetVertexColor(1, 0.96, 0.85, 0.12)
		b.hov = hov

		local fs = b:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
		fs:SetJustifyH("CENTER")
		fs:SetJustifyV("MIDDLE")
		fs:SetWordWrap(false)
		applySafeFont(fs, fontSize or 11, "semibold")
		if opts.withDot then
			local dot = b:CreateTexture(nil, "OVERLAY", nil, 2)
			dot:SetTexture(ns.Theme.ASSETS.circle)
			dot:SetSize(7, 7)
			dot:SetPoint("LEFT", b, "LEFT", 12, 0)
			dot:SetVertexColor(0.18, 0.95, 0.56, 1)
			b.dot = dot
			fs:SetPoint("LEFT", dot, "RIGHT", 5, 0)
			fs:SetPoint("RIGHT", b, "RIGHT", -8, 0)
		else
			fs:SetPoint("LEFT", b, "LEFT", 6, 0)
			fs:SetPoint("RIGHT", b, "RIGHT", -6, 0)
		end
		fs:SetText(b._label)
		b.fs = fs

		function b:SetText(txt)
			self._label = tostring(txt or "")
			self.fs:SetText(self._label)
		end
		function b:GetText()
			return self._label
		end
		local rawSetEnabled = b.SetEnabled
		function b:SetEnabled(en)
			self._enabled = (en ~= false)
			if rawSetEnabled then rawSetEnabled(self, self._enabled) end
			self:SetAlpha(self._enabled and 1.0 or 0.55)
		end
		function b:IsEnabled()
			return self._enabled ~= false
		end
		function b:PaintStyle(fill, stroke, textCol, specAlpha, skinTexPath, dotCol)
			self.plate:SetFill(fill[1], fill[2], fill[3], fill[4] or 0.95)
			self.plate:SetStroke(stroke[1], stroke[2], stroke[3], stroke[4] or 0.88)
			self.fs:SetTextColor(textCol[1], textCol[2], textCol[3], textCol[4] or 1)
			self.spec:SetVertexColor(1, 0.96, 0.84, specAlpha or 0.20)
			if self.skinArt then
				if skinTexPath then
					self.skinArt:SetTexture(skinTexPath)
					self.skinArt:SetVertexColor(1, 1, 1, 0.42)
					self.skinArt:Show()
				else
					self.skinArt:Hide()
				end
			end
			if self.dot and dotCol then
				self.dot:SetVertexColor(dotCol[1], dotCol[2], dotCol[3], dotCol[4] or 1)
			end
		end
		return b
	end

	local function makeSocket(parent, size)
		local f = CreateFrame("Frame", nil, parent)
		f:SetSize(size, size)
		local stdBg = ns.Theme.NineApple(f, "glass_r8",
			{ 0.14, 0.15, 0.18, 0.95 },
			{ 0.45, 0.48, 0.54, 0.65 },
			{ layer = "BACKGROUND", sub = 0, cornerSize = 6, noSpecular = true })
		local icon = f:CreateTexture(nil, "ARTWORK", nil, 0)
		local pad = (size >= 34) and 4 or 3
		icon:SetPoint("TOPLEFT", f, "TOPLEFT", pad, -pad)
		icon:SetPoint("BOTTOMRIGHT", f, "BOTTOMRIGHT", -pad, pad)
		if icon.SetTexCoord then icon:SetTexCoord(0.08, 0.92, 0.08, 0.92) end
		local frameTex = f:CreateTexture(nil, "OVERLAY", nil, 2)
		frameTex:SetAllPoints(f)
		frameTex:Hide()
		f.stdBg = stdBg
		f.icon = icon
		f.frameTex = frameTex
		function f:ApplyTheme(isCustom, skinKey, pal)
			if isCustom then
				self.stdBg:SetShown(false)
				self.frameTex:SetTexture(ns.Theme.GetSkinAsset(skinKey, "socket"))
				self.frameTex:SetVertexColor(1, 1, 1, 1)
				self.frameTex:Show()
			else
				self.frameTex:Hide()
				self.stdBg:SetShown(true)
				local isL = (pal and pal.mode == "light")
				local bg = isL and { 0.92, 0.93, 0.96, 1 } or { 0.12, 0.13, 0.16, 0.96 }
				local st = isL and { 0.00, 0.00, 0.00, 0.18 } or { 1.00, 1.00, 1.00, 0.22 }
				self.stdBg:SetFill(bg[1], bg[2], bg[3], bg[4])
				self.stdBg:SetStroke(st[1], st[2], st[3], st[4])
			end
		end
		return f
	end

	local function makePill(parent, w, h, fontSize)
		local f = CreateFrame("Frame", nil, parent)
		f:SetSize(w, h)
		f.plate = ns.Theme.NineApple(f, "pill",
			{ 0.08, 0.30, 0.18, 0.80 },
			{ 0.18, 0.95, 0.56, 0.85 },
			{ layer = "BACKGROUND", sub = 0, cornerSize = math.max(6, math.floor(h * 0.5)), noSpecular = true })
		local fs = f:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
		fs:SetPoint("LEFT", f, "LEFT", 5, 0)
		fs:SetPoint("RIGHT", f, "RIGHT", -5, 0)
		fs:SetJustifyH("CENTER")
		fs:SetJustifyV("MIDDLE")
		fs:SetWordWrap(false)
		applySafeFont(fs, fontSize or 9, "semibold")
		f.fs = fs
		function f:Paint(fill, stroke, textHex, label)
			self.plate:SetFill(fill[1], fill[2], fill[3], fill[4] or 0.85)
			self.plate:SetStroke(stroke[1], stroke[2], stroke[3], stroke[4] or 0.85)
			if label ~= nil then
				self.fs:SetText((textHex or "") .. tostring(label) .. (textHex and "|r" or ""))
			end
		end
		return f
	end

	local function resolveIconTex(itemID, spellID)
		if itemID and itemID > 0 then
			local tex = (C_Item and C_Item.GetItemIconByID and C_Item.GetItemIconByID(itemID))
				or (GetItemIcon and GetItemIcon(itemID))
			if tex then return tex end
		end
		if spellID and spellID > 0 then
			local stex = (C_Spell and C_Spell.GetSpellTexture and C_Spell.GetSpellTexture(spellID))
				or (GetSpellTexture and GetSpellTexture(spellID))
			if stex then return stex end
			return "Interface\\Icons\\INV_Enchant_FormulaGood_01"
		end
		return ns.QUESTION_ICON or "Interface\\Icons\\INV_Misc_QuestionMark"
	end

