	local function makeBaronScrollbar(parent, onStep)
		local track = CreateFrame("Frame", nil, parent)
		track:SetWidth(8)
		track:SetPoint("TOPRIGHT", parent, "TOPRIGHT", 0, -2)
		track:SetPoint("BOTTOMRIGHT", parent, "BOTTOMRIGHT", 0, 2)
		track.plate = ns.Theme.NineApple(track, "pill",
			{ 0.03, 0.08, 0.05, 0.85 },
			{ 0.83, 0.64, 0.24, 0.35 },
			{ layer = "BACKGROUND", sub = 0, cornerSize = 4, noSpecular = true })
		local thumb = CreateFrame("Button", nil, track)
		thumb:SetWidth(6)
		thumb:SetPoint("TOP", track, "TOP", 0, -1)
		thumb:SetHeight(32)
		thumb.plate = ns.Theme.NineApple(thumb, "pill",
			{ 0.18, 0.72, 0.44, 0.92 },
			{ 0.97, 0.84, 0.49, 0.88 },
			{ layer = "ARTWORK", sub = 1, cornerSize = 3, noSpecular = true })
		if track.EnableMouseWheel then track:EnableMouseWheel(true) end
		track:SetScript("OnMouseWheel", function(_, delta)
			if onStep then onStep(delta) end
		end)
		thumb:SetScript("OnClick", function()
			if onStep then onStep(-1) end
		end)
		track.thumb = thumb
		track:Hide()

		function track:Update(offset, visible, total, isLight, goldBorder, accentCol)
			if total <= visible or visible <= 0 then
				self:Hide()
				return false
			end
			self:Show()
			local tf = isLight and { 0.00, 0.00, 0.00, 0.08 } or { 0.03, 0.08, 0.05, 0.88 }
			local ts = isLight and { 0.00, 0.00, 0.00, 0.16 } or { goldBorder[1], goldBorder[2], goldBorder[3], 0.38 }
			self.plate:SetFill(tf[1], tf[2], tf[3], tf[4])
			self.plate:SetStroke(ts[1], ts[2], ts[3], ts[4])
			local thf = isLight and { 0.42, 0.46, 0.52, 0.85 } or { accentCol[1] * 0.75, accentCol[2] * 0.82, accentCol[3] * 0.78, 0.92 }
			local ths = isLight and { 0.28, 0.32, 0.38, 0.90 } or { goldBorder[1], goldBorder[2], goldBorder[3], 0.85 }
			self.thumb.plate:SetFill(thf[1], thf[2], thf[3], thf[4])
			self.thumb.plate:SetStroke(ths[1], ths[2], ths[3], ths[4])

			local trackH = (self.GetHeight and self:GetHeight()) or 0
			if trackH < 40 then trackH = visible * 40 end
			local usableH = math.max(24, trackH - 4)
			local thumbH = math.max(22, math.floor(usableH * (visible / total) + 0.5))
			local maxOff = math.max(1, total - visible)
			local frac = math.max(0, math.min(1, (offset or 0) / maxOff))
			local topY = -2 - math.floor((usableH - thumbH) * frac + 0.5)
			self.thumb:ClearAllPoints()
			self.thumb:SetPoint("TOP", self, "TOP", 0, topY)
			self.thumb:SetHeight(thumbH)
			return true
		end
		return track
	end

