	local function layoutStageBar(explicitW)
		local isCustom = ns.Theme and ns.Theme.IsCustomSkin and ns.Theme.IsCustomSkin()
		local bodyPadX = isCustom and 20 or 14
		if cbBody and cbBody.GetPoint then
			local _, _, _, px = cbBody:GetPoint(1)
			if type(px) == "number" and px > 0 and px < 64 then
				bodyPadX = px
			end
		end
		local targetModalW = cbExtended and CB_EXTENDED_W or CB_COMPACT_W
		local bw = explicitW or math.max(200, targetModalW - (bodyPadX * 2))
		local nStages = #STAGE_ORDER
		local gap = 4
		local pw = math.floor((bw - (gap * (nStages - 1))) / nStages)
		local lastW = bw - (pw * (nStages - 1)) - (gap * (nStages - 1))
		for idx, meta in ipairs(STAGE_ORDER) do
			local sb = cbStageBtns[meta.key]
			local x = (idx - 1) * (pw + gap)
			sb:ClearAllPoints()
			sb:SetPoint("TOPLEFT", cbStageBar, "TOPLEFT", x, -2)
			sb:SetSize(idx == nStages and lastW or pw, 28)
		end
	end
	layoutStageBar()

