		local cw = math.floor(mw / 3)
		local cwLast = mw - (cw * 2)
		ui.mColExp:ClearAllPoints();  ui.mColExp:SetPoint("TOPLEFT", cbMetricsBox, "TOPLEFT", 0, -2);        ui.mColExp:SetWidth(cw)
		ui.mColLive:ClearAllPoints(); ui.mColLive:SetPoint("TOPLEFT", cbMetricsBox, "TOPLEFT", cw, -2);      ui.mColLive:SetWidth(cw)
		ui.mColDiff:ClearAllPoints(); ui.mColDiff:SetPoint("TOPLEFT", cbMetricsBox, "TOPLEFT", cw * 2, -2);  ui.mColDiff:SetWidth(cwLast)
		ui.mDiv1:ClearAllPoints(); ui.mDiv1:SetPoint("TOPLEFT", cbMetricsBox, "TOPLEFT", cw, -8);     ui.mDiv1:SetPoint("BOTTOMLEFT", cbMetricsBox, "BOTTOMLEFT", cw, 8)
		ui.mDiv2:ClearAllPoints(); ui.mDiv2:SetPoint("TOPLEFT", cbMetricsBox, "TOPLEFT", cw * 2, -8); ui.mDiv2:SetPoint("BOTTOMLEFT", cbMetricsBox, "BOTTOMLEFT", cw * 2, 8)
		if layoutCapGauge then
			local st = app.cartBuyer and app.cartBuyer.GetState and app.cartBuyer.GetState()
			local curItem = (st and st.items and st.activeIndex) and st.items[st.activeIndex] or nil
