		local it = self._curItem
		if not (it and it.maxBuyUnit and it.maxBuyUnit > 0 and GameTooltip) then return end
		GameTooltip:SetOwner(self, "ANCHOR_TOP")
		GameTooltip:AddLine(tostring(it.name or "Material") .. " - Buy Cap", 1, 0.85, 0.25)
		GameTooltip:AddDoubleLine("Safe Max Buy:", ns.FormatMoneyCompact(it.maxBuyUnit), 0.85, 0.85, 0.85, 0.25, 0.95, 0.45)
		if it.breakEvenUnit and it.breakEvenUnit > 0 then
			GameTooltip:AddDoubleLine("Break-Even:", ns.FormatMoneyCompact(it.breakEvenUnit), 0.85, 0.85, 0.85, 1.0, 0.78, 0.22)
		end
		if it.liveUnit and it.liveUnit > 0 then
			local margin = (it.buyCapMarginCopper ~= nil) and it.buyCapMarginCopper or (it.maxBuyUnit - it.liveUnit)
			local isOver = (it.overBuyCap == true) or (margin < 0)
			GameTooltip:AddDoubleLine("Live AH:", ns.FormatMoneyCompact(it.liveUnit), 0.85, 0.85, 0.85, isOver and 1.0 or 1.0, isOver and 0.35 or 1.0, isOver and 0.35 or 1.0)
			local remQty = math.max(1, it.remaining or 1)
			if isOver then
				local overEA = -margin
				GameTooltip:AddDoubleLine("Headroom:", "STOP: +" .. ns.FormatMoneyCompact(overEA) .. " ea OVER CAP", 0.85, 0.85, 0.85, 1.0, 0.32, 0.30)
				GameTooltip:AddDoubleLine("Remaining Cost Impact:", "+" .. ns.FormatMoneyCompact(overEA * remQty) .. " over for " .. tostring(remQty) .. "x", 0.85, 0.85, 0.85, 1.0, 0.45, 0.42)
			else
				GameTooltip:AddDoubleLine("Headroom:", "+" .. ns.FormatMoneyCompact(margin) .. " ea left under cap", 0.85, 0.85, 0.85, 0.25, 0.95, 0.45)
				GameTooltip:AddDoubleLine("Remaining Cushion:", "+" .. ns.FormatMoneyCompact(margin * remQty) .. " across " .. tostring(remQty) .. "x", 0.85, 0.85, 0.85, 0.65, 0.90, 0.72)
			end
		else
			GameTooltip:AddLine("Open in AH to compare live listing against cap.", 0.75, 0.78, 0.82, true)
		end
		GameTooltip:Show()
	end)
	cbCapGauge:SetScript("OnLeave", function()
		if GameTooltip and GameTooltip.Hide then GameTooltip:Hide() end
	end)

	layoutCapGauge = function(cur)
		local tw = (cbCapTrack.GetWidth and cbCapTrack:GetWidth()) or 0
		if tw < 100 then tw = (cbMetricsBox.GetWidth and cbMetricsBox:GetWidth()) or 332 end
		if tw < 120 then tw = 332 end
		local leftW = math.floor(tw * 0.50)
		capLeftFs:SetWidth(leftW)
		capRightFs:SetWidth(math.max(40, tw - leftW - 4))
		local innerW = math.max(10, tw - 2)
		local wSafe = math.floor(innerW * 0.68)
		local wTight = math.floor(innerW * 0.14)
		local wOver = math.max(2, innerW - wSafe - wTight)
		ui.capZoneSafe:ClearAllPoints()
		ui.capZoneSafe:SetPoint("TOPLEFT", cbCapTrack, "TOPLEFT", 1, -1)
		ui.capZoneSafe:SetPoint("BOTTOMLEFT", cbCapTrack, "BOTTOMLEFT", 1, 1)
		ui.capZoneSafe:SetWidth(wSafe)
		ui.capZoneTight:ClearAllPoints()
		ui.capZoneTight:SetPoint("TOPLEFT", cbCapTrack, "TOPLEFT", 1 + wSafe, -1)
		ui.capZoneTight:SetPoint("BOTTOMLEFT", cbCapTrack, "BOTTOMLEFT", 1 + wSafe, 1)
		ui.capZoneTight:SetWidth(wTight)
		ui.capZoneOver:ClearAllPoints()
		ui.capZoneOver:SetPoint("TOPLEFT", cbCapTrack, "TOPLEFT", 1 + wSafe + wTight, -1)
		ui.capZoneOver:SetPoint("BOTTOMLEFT", cbCapTrack, "BOTTOMLEFT", 1 + wSafe + wTight, 1)
		ui.capZoneOver:SetWidth(wOver)
		ui.capTick:ClearAllPoints()
		ui.capTick:SetPoint("CENTER", cbCapTrack, "LEFT", math.floor(tw * 0.80), 0)
		if cur and cur.maxBuyUnit and cur.maxBuyUnit > 0 and cur.liveUnit and cur.liveUnit > 0 then
			local frac = math.max(0.03, math.min(0.97, (cur.liveUnit / cur.maxBuyUnit) * 0.80))
			local px = math.max(3, math.min(tw - 3, math.floor(tw * frac + 0.5)))
			ui.capLiveHalo:ClearAllPoints()
			ui.capLiveHalo:SetPoint("CENTER", cbCapTrack, "LEFT", px, 0)
			ui.capLiveHalo:Show()
			ui.capLivePin:ClearAllPoints()
			ui.capLivePin:SetPoint("CENTER", cbCapTrack, "LEFT", px, 0)
			ui.capLivePin:Show()
			cbCapGauge._liveFrac = frac
		else
			ui.capLiveHalo:Hide()
			ui.capLivePin:Hide()
			cbCapGauge._liveFrac = nil
		end
	end
	layoutMetricsCols()

	-- Stage-Adaptive Baron Action Buttons (Stage 1: Open in AH dead-centered with NO left dot shift!)
	local function getFlowStage()
		return (app.orderFlow and app.orderFlow.GetActiveStage and app.orderFlow.GetActiveStage()) or "ah"
	end

	-- Stage 4 Craft Batch Total-Time Loading Bar (shares exact slot with cbCapGauge)
	local function updateCraftTimerVisual(timing, pal, isLight, isCustom, goldBorder)
		local track = ui.timerTrack
		local fill = ui.craftTimerFill
		local fs = ui.craftTimerFs
		if not (track and fill and fs) then return end
		local themeKey = isLight and "L" or (isCustom and string.format("C:%.2f,%.2f,%.2f", goldBorder[1] or 0, goldBorder[2] or 0, goldBorder[3] or 0) or "D")
		if ui.timerTrackPlate and track._plateStyleKey ~= themeKey then
			local tFill = isLight and { 0.91, 0.92, 0.95, 1.00 }
				or (isCustom and { 0.02, 0.08, 0.05, 0.96 } or { 0.09, 0.10, 0.13, 0.96 })
			local tStroke = isLight and { 0.56, 0.54, 0.48, 0.68 }
				or (isCustom and { goldBorder[1], goldBorder[2], goldBorder[3], 0.62 } or { 0.42, 0.48, 0.56, 0.58 })
			ui.timerTrackPlate:SetFill(tFill[1], tFill[2], tFill[3], tFill[4])
			ui.timerTrackPlate:SetStroke(tStroke[1], tStroke[2], tStroke[3], tStroke[4])
			track._plateStyleKey = themeKey
		end
		local tw = (track.GetWidth and track:GetWidth()) or 0
		if tw < 120 then
			local sw = (cbSpotlight.GetWidth and cbSpotlight:GetWidth()) or 0
			tw = (sw >= 140) and (sw - 20) or 332
		end
		local innerW = math.max(12, tw - 4)
		local fmt = (app.orderFlow and app.orderFlow.FormatDuration) or function(s)
			return string.format("%ds", math.floor((tonumber(s) or 0) + 0.5))
		end
		local isCraftingThis = (timing and (timing.isSelectedTaskCrafting == true or timing.casting == true)) and true or false
		local frac = math.max(0, math.min(1, tonumber(timing and timing.taskFrac) or 0))
		local taskLeft = tonumber(timing and timing.taskLeftSec) or 0
		local taskTotal = tonumber(timing and timing.taskTotalSec) or 0
		local queueLeft = tonumber(timing and timing.queueLeftSec) or 0
		local comp = tonumber(timing and timing.completedCrafts) or 0
		local need = tonumber(timing and timing.neededCrafts) or 0
		local showFill = (isCraftingThis or frac > 0.001) and true or false
		if showFill then
			local barFrac = math.max(0.02, frac)
			local newW = math.max(4, math.floor(innerW * barFrac + 0.5))
			if fill._lastW ~= newW then
				fill:SetWidth(newW)
				fill._lastW = newW
			end
			if fill._fillStyleKey ~= themeKey then
				if isLight then
					fill:SetColorTexture(0.10, 0.62, 0.34, 0.30)
				elseif isCustom then
					fill:SetColorTexture(0.10, 0.48, 0.27, 0.88)
				else
					fill:SetColorTexture(0.10, 0.46, 0.28, 0.86)
				end
				fill._fillStyleKey = themeKey
			end
			if not fill:IsShown() then fill:Show() end
		else
			fill._lastW = nil
			if fill:IsShown() then fill:Hide() end
		end
		local txtMode, nextText
		if isCraftingThis then
			txtMode = "active"
			if queueLeft > taskLeft + 0.5 then
				nextText = string.format("Crafting %s left  |  Queue %s", fmt(taskLeft), fmt(queueLeft))
			else
				nextText = string.format("Crafting %s left  (%d/%d)", fmt(taskLeft), comp, need)
			end
		elseif timing and taskLeft > 0 and frac > 0.001 then
			txtMode = "active"
			if queueLeft > taskLeft + 0.5 then
				nextText = string.format("%s left (%d/%d)  |  Queue %s", fmt(taskLeft), comp, need, fmt(queueLeft))
			else
				nextText = string.format("%s left  (%d/%d)", fmt(taskLeft), comp, need)
			end
		elseif timing and (taskLeft > 0 or queueLeft > 0) then
			txtMode = "idle"
			if queueLeft > taskLeft + 0.5 then
				nextText = string.format("Est. %s  |  Queue %s", fmt(taskLeft), fmt(queueLeft))
			else
				nextText = string.format("Est. %s  (%dx)", fmt(taskTotal > 0 and taskTotal or taskLeft), need)
			end
		else
			txtMode = "empty"
			nextText = "Ready to craft"
		end
		local colKey = themeKey .. ":" .. txtMode
		if fs._txtColKey ~= colKey then
			if txtMode == "active" then
				if isLight then
					fs:SetTextColor(0.05, 0.24, 0.12, 1.0)
				elseif isCustom then
					fs:SetTextColor(1.00, 0.98, 0.90, 1.0)
				else
					fs:SetTextColor(0.98, 0.99, 1.00, 1.0)
				end
			elseif txtMode == "idle" then
				if isLight then
					fs:SetTextColor(0.14, 0.16, 0.20, 1.0)
				else
					fs:SetTextColor(0.92, 0.92, 0.88, 1.0)
				end
			else
				if isLight then
					fs:SetTextColor(0.32, 0.35, 0.40, 1.0)
				else
					fs:SetTextColor(0.70, 0.74, 0.70, 1.0)
				end
			end
			fs._txtColKey = colKey
		end
		if fs._lastText ~= nextText then
			fs:SetText(nextText)
			fs._lastText = nextText
		end
	end

	local function buildCraftTimerBarUI()
		local bar = CreateFrame("Frame", nil, cbSpotlight)
		bar:SetPoint("TOPLEFT", cbSpotlight, "TOPLEFT", 10, -110)
		bar:SetPoint("TOPRIGHT", cbSpotlight, "TOPRIGHT", -10, -110)
		bar:SetHeight(24)
		bar:Hide()

		local track = CreateFrame("Frame", nil, bar)
		track:SetPoint("TOPLEFT", bar, "TOPLEFT", 0, 0)
		track:SetPoint("TOPRIGHT", bar, "TOPRIGHT", 0, 0)
		track:SetHeight(24)
		ui.timerTrackPlate = ns.Theme.NineApple(track, "glass_r8",
			{ 0.02, 0.08, 0.05, 0.95 },
			{ 0.83, 0.64, 0.24, 0.62 },
			{ layer = "BACKGROUND", sub = 0, cornerSize = 6, noSpecular = true })

		local fill = track:CreateTexture(nil, "ARTWORK", nil, 0)
		fill:SetPoint("TOPLEFT", track, "TOPLEFT", 2, -2)
		fill:SetPoint("BOTTOMLEFT", track, "BOTTOMLEFT", 2, 2)
		fill:SetWidth(1)
		fill:Hide()

		local fs = track:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
		fs:SetPoint("LEFT", track, "LEFT", 6, 0)
		fs:SetPoint("RIGHT", track, "RIGHT", -6, 0)
		fs:SetJustifyH("CENTER")
		fs:SetJustifyV("MIDDLE")
		fs:SetWordWrap(false)
		applySafeFont(fs, 9.5, "semibold")

		local elapsedAcc = 0
		bar:SetScript("OnUpdate", function(_, elapsed)
			elapsedAcc = elapsedAcc + (elapsed or 0)
			if elapsedAcc < 0.08 then return end
			elapsedAcc = 0
			if not (cartBuyerModal:IsShown() and getFlowStage() == "craft") then return end
			if not (app.orderFlow and app.orderFlow.GetCraftTimingSummary) then return end
			if app.orderFlow.ExpireCraftingBatchIfNeeded and app.orderFlow.ExpireCraftingBatchIfNeeded() then
				return
			end
			local timing = app.orderFlow.GetCraftTimingSummary()
			if not (timing and (timing.isSelectedTaskCrafting or timing.casting)) then return end
			local pal = getPal()
			local isCustom = ns.Theme and ns.Theme.IsCustomSkin and ns.Theme.IsCustomSkin()
			local isLight = (pal.mode == "light")
			local goldBorder = isLight and { 0.68, 0.45, 0.02, 0.68 } or ((isCustom and pal.frameBorder) or pal.cartMainAccent or { 0.83, 0.64, 0.24, 0.82 })
			updateCraftTimerVisual(timing, pal, isLight, isCustom, goldBorder)
		end)

		bar.track = track
		bar.fill = fill
		bar.fs = fs
		ui.craftTimerBar = bar
		ui.timerTrack = track
		ui.craftTimerFill = fill
		ui.craftTimerFs = fs
		cartBuyerModal.craftTimerBar = bar
		cartBuyerModal.craftTimerTrack = track
		cartBuyerModal.craftTimerFill = fill
		cartBuyerModal.craftTimerFs = fs
	end
	buildCraftTimerBarUI()

	local function addSellTip(widget, title, bodyFnOrText)
		if not (widget and widget.SetScript) then return end
		if widget.SetMotionScriptsWhileDisabled then
			pcall(widget.SetMotionScriptsWhileDisabled, widget, true)
		end
		local fn = function(self)
			if not GameTooltip then return end
			local body = (type(bodyFnOrText) == "function") and bodyFnOrText(self) or bodyFnOrText
			if type(bodyFnOrText) == "function" and (type(body) ~= "string" or body == "") then return end
			GameTooltip:SetOwner(self, "ANCHOR_TOP")
			GameTooltip:AddLine(title, 1.0, 0.85, 0.35)
			if type(body) == "string" and body ~= "" then
				GameTooltip:AddLine(body, 0.90, 0.92, 0.94, true)
			end
			if ns.Theme and ns.Theme.LiftTooltip then ns.Theme.LiftTooltip(GameTooltip) end
			GameTooltip:Show()
		end
		local leaveFn = function()
			if GameTooltip and GameTooltip.Hide then GameTooltip:Hide() end
		end
		if widget.HookScript then
			widget:HookScript("OnEnter", fn)
			widget:HookScript("OnLeave", leaveFn)
		else
			widget:SetScript("OnEnter", fn)
			widget:SetScript("OnLeave", leaveFn)
		end
	end

