	cbOpenAHBtn:SetScript("OnClick", function()
		local sk = getFlowStage()
		if sk == "ah" then
			if app.cartBuyer then
				if app.cartBuyer.ExecutePrimaryAction then
					app.cartBuyer.ExecutePrimaryAction()
				else
					app.cartBuyer.OpenInAH()
				end
			end
		elseif sk == "vendor" then
			if app.orderFlow then app.orderFlow.BuyVendorItem() end
		elseif sk == "collect" then
			if app.orderFlow then
				local ofSt = app.orderFlow.GetState()
				local cSt = ofSt and ofSt.stages and ofSt.stages.collect
				local cur = cSt and cSt.items and cSt.items[cSt.activeIndex]
				if cur and cur.source == "bank" then
					app.orderFlow.WithdrawFromBank()
				elseif cur and cur.source == "mail" then
					app.orderFlow.CollectFromMail()
				end
			end
		elseif sk == "craft" then
			if app.orderFlow then
				app.orderFlow.CraftActiveTask()
			end
		end
	end)
	addSellTip(cbOpenAHBtn, "Primary Action", function()
		local sk = getFlowStage()
		if sk == "ah" then
			local act = (app.cartBuyer and app.cartBuyer.GetPrimaryAction) and app.cartBuyer.GetPrimaryAction() or nil
			local lbl = act and tostring(act.label or "") or ""
			if lbl:find("(!)", 1, true) then
				return "Smallest available auction stack exceeds remaining need (overbuy warning). Click to buy this stack anyway."
			elseif act and act.action == "confirm_buy" then
				return "Click to confirm this Auction House purchase."
			elseif act and act.action == "buy" then
				return "Buy the cheapest available listing for the selected item."
			end
			return "Search the Auction House for the selected item."
		elseif sk == "vendor" then
			return "Buy the remaining needed quantity of this item from the open Vendor."
		elseif sk == "collect" then
			local ofSt = app.orderFlow and app.orderFlow.GetState and app.orderFlow.GetState()
			local cSt = ofSt and ofSt.stages and ofSt.stages.collect
			local cur = cSt and cSt.items and cSt.items[cSt.activeIndex]
			if cur and cur.source == "bank" then
				return "Withdraw the needed quantity of this item from your open Bank."
			elseif cur and cur.source == "mail" then
