		ah      = { "Stage 1: Auction House", "Buy missing crafting materials from the Auction House with live price checks and max-buy caps." },
		collect = { "Stage 2: Collect Owned", "Withdraw materials you already own from your Bank or Mailbox into your bags." },
		vendor  = { "Stage 3: Vendor", "Buy vendor-sold materials from Trade Goods or profession NPCs." },
		craft   = { "Stage 4: Craft", "Craft sub-components first and then final orders with live reagent readiness." },
	}
	for _, meta in ipairs(STAGE_ORDER) do
		local tip = STAGE_PILL_TIPS[meta.key]
