	cbNextStageBtn:SetPoint("BOTTOMLEFT", cbSpotlight, "BOTTOMLEFT", 10, 10)
	cbNextStageBtn:SetPoint("BOTTOMRIGHT", cbSpotlight, "BOTTOMRIGHT", -10, 10)
	cbNextStageBtn:SetScript("OnClick", function()
		local ofSt = app.orderFlow and app.orderFlow.GetState and app.orderFlow.GetState()
		local prompt = ofSt and ofSt.stageCompletePrompt
		if prompt and prompt.action == "clear_queue" then
			cbScrollOffset = 0
			if app.clearUnifiedShoppingList then
				app.clearUnifiedShoppingList()
			elseif app.orderFlow and app.orderFlow.ClearSavedState then
				app.orderFlow.ClearSavedState()
			end
			if cartBuyerModal.Render then cartBuyerModal.Render() end
			return
		end
		if app.orderFlow and app.orderFlow.AdvanceToNextStage then
			cbScrollOffset = 0
			app.orderFlow.AdvanceToNextStage()
			if app.dockCartBuyerModal then app.dockCartBuyerModal() end
			if cartBuyerModal.Render then cartBuyerModal.Render() end
		end
	end)
