	-- 3. Scrollable 1-Line Buying List (36px crisp cards, 3px gap, NO "For ..." subtitle, visible Baron scrollbar!)
	local cbListFrame = CreateFrame("Frame", nil, cbStripPane)
	cbListFrame:SetPoint("TOPLEFT", cbStripPane, "TOPLEFT", 2, -164)
	cbListFrame:SetPoint("BOTTOMRIGHT", cbStripPane, "BOTTOMRIGHT", -2, 0)
	if cbListFrame.EnableMouseWheel then cbListFrame:EnableMouseWheel(true) end
	local function getActiveVisibleEntries()
		local sk = getFlowStage()
		if app.orderFlow and app.orderFlow.GetVisibleStageEntries then
			return app.orderFlow.GetVisibleStageEntries(sk)
		end
		return (app.cartBuyer and app.cartBuyer.GetVisibleItems) and app.cartBuyer.GetVisibleItems() or {}
	end

	local function getVisCap(hasFilterFlag, hasCapFlag, hasNoticeFlag)
		if hasNoticeFlag == nil then
			hasNoticeFlag = (cbNoticeBar and cbNoticeBar.IsShown and cbNoticeBar:IsShown()) and true or false
		end
		local noticeDeduct = (hasNoticeFlag == true) and 1 or 0
		if hasCapFlag == nil then
			local sk = getFlowStage()
			if sk == "ah" then
				local stCap = app.cartBuyer and app.cartBuyer.GetState and app.cartBuyer.GetState()
				local curCap = (stCap and stCap.items and stCap.activeIndex) and stCap.items[stCap.activeIndex] or nil
				hasCapFlag = (atAH() and curCap and curCap.maxBuyUnit and curCap.maxBuyUnit > 0) and true or false
			elseif sk == "craft" then
				hasCapFlag = (ui.craftTimerBar and ui.craftTimerBar.IsShown and ui.craftTimerBar:IsShown()) and true or false
			else
				hasCapFlag = false
			end
		end
		return math.max(1, CB_VISIBLE_ROWS - (hasFilterFlag and 1 or 0) - (hasCapFlag and 1 or 0) - noticeDeduct)
	end
	cartBuyerModal.getVisCap = getVisCap

	local function stepListScroll(delta)
		local vis = getActiveVisibleEntries()
		local hasFilter = (app.cartBuyer and app.cartBuyer.GetDestinationFilter and app.cartBuyer.GetDestinationFilter() ~= nil)
		local visCap = getVisCap(hasFilter)
		local maxOff = math.max(0, #vis - visCap)
		cbScrollOffset = math.max(0, math.min(maxOff, cbScrollOffset - (delta > 0 and 1 or -1)))
		if cartBuyerModal.Render then cartBuyerModal.Render() end
	end
	cbListFrame:SetScript("OnMouseWheel", function(_, delta)
		stepListScroll(delta)
	end)
	cartBuyerModal.listFrame = cbListFrame
	ui.listScroll = makeBaronScrollbar(cbListFrame, stepListScroll)
	cartBuyerModal.listScrollTrack = ui.listScroll
	cartBuyerModal.listScrollThumb = ui.listScroll.thumb

	function cartBuyerModal.GetListScrollOffset() return cbScrollOffset end
	function cartBuyerModal.SetListScrollOffset(off)
		local vis = getActiveVisibleEntries()
		local hasFilter = (app.cartBuyer and app.cartBuyer.GetDestinationFilter and app.cartBuyer.GetDestinationFilter() ~= nil)
		local visCap = getVisCap(hasFilter)
		local maxOff = math.max(0, #vis - visCap)
		cbScrollOffset = math.max(0, math.min(maxOff, math.floor(tonumber(off) or 0)))
		if cartBuyerModal.Render then cartBuyerModal.Render() end
		return cbScrollOffset
	end

