		hintFs:Hide()
		row.cells.hint = hintFs

		local cartFs = row:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
		cartFs:Hide()
		row.cells.cart = cartFs

		if row.RegisterForClicks then row:RegisterForClicks("LeftButtonUp", "RightButtonUp") end
		row:SetScript("OnClick", function(self, mouseBtn)
			if not self._itemIndex then return end
			local sk = getFlowStage()
			if sk == "ah" then
				if app.cartBuyer then app.cartBuyer.SelectItem(self._itemIndex) end
			elseif sk == "vendor" then
				if app.orderFlow then app.orderFlow.SelectVendorItem(self._itemIndex) end
			elseif sk == "collect" then
				if app.orderFlow then app.orderFlow.SelectCollectItem(self._itemIndex) end
			elseif sk == "craft" then
				if app.orderFlow then app.orderFlow.SelectCraftTask(self._itemIndex) end
			end
		end)
		row:SetScript("OnEnter", function(self)
			if not (GameTooltip and self._itemIndex) then return end
			local sk = getFlowStage()
			if sk == "ah" and app.cartBuyer then
				local st = app.cartBuyer.GetState and app.cartBuyer.GetState()
				local it = st and st.items and st.items[self._itemIndex]
				if not it then return end
				GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
				GameTooltip:AddLine(tostring(it.name or "Item"), 1.0, 0.85, 0.35)
				GameTooltip:AddLine(string.format("Bought: %d / %d (Remaining: %d)",
					tonumber(it.bought) or 0, tonumber(it.needed) or 0, tonumber(it.remaining) or 0), 0.90, 0.92, 0.94, true)
				if it.expectedUnit and it.expectedUnit > 0 then
					GameTooltip:AddLine("Expected: " .. ns.FormatMoneyCompact(it.expectedUnit), 0.82, 0.86, 0.90, true)
				end
				if it.liveUnit and it.liveUnit > 0 then
					GameTooltip:AddLine("Live AH: " .. ns.FormatMoneyCompact(it.liveUnit), 0.30, 0.92, 0.50, true)
				end
				if it.maxBuyUnit and it.maxBuyUnit > 0 then
					GameTooltip:AddLine("Max Buy Cap: " .. ns.FormatMoneyCompact(it.maxBuyUnit), 1.00, 0.84, 0.40, true)
				end
				GameTooltip:AddLine("Click: Select & search in Auction House", 0.55, 0.90, 1.00, true)
			elseif sk == "collect" and app.orderFlow then
				local cSt = app.orderFlow.GetState and app.orderFlow.GetState().stages.collect
				local it = cSt and cSt.items and cSt.items[self._itemIndex]
				if not it then return end
				GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
				GameTooltip:AddLine(tostring(it.name or "Item"), 1.0, 0.85, 0.35)
				GameTooltip:AddLine(string.format("Source: %s | Remaining: %d / %d",
					tostring(it.source or "bags"), tonumber(it.remaining) or 0, tonumber(it.needed) or 0), 0.90, 0.92, 0.94, true)
				GameTooltip:AddLine("Click: Select item to collect", 0.55, 0.90, 1.00, true)
			elseif sk == "vendor" and app.orderFlow then
				local vSt = app.orderFlow.GetState and app.orderFlow.GetState().stages.vendor
				local it = vSt and vSt.items and vSt.items[self._itemIndex]
				if not it then return end
				GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
				GameTooltip:AddLine(tostring(it.name or "Item"), 1.0, 0.85, 0.35)
				GameTooltip:AddLine(string.format("Vendor: %s | Remaining: %d / %d",
					tostring(it.vendorHint or "Trade Goods Vendor"), tonumber(it.remaining) or 0, tonumber(it.needed) or 0), 0.90, 0.92, 0.94, true)
				if it.inStockHere then
					GameTooltip:AddLine("In stock at current Vendor", 0.30, 0.92, 0.50, true)
				end
				GameTooltip:AddLine("Click: Select vendor item", 0.55, 0.90, 1.00, true)
			elseif sk == "craft" and app.orderFlow then
				local crSt = app.orderFlow.GetState and app.orderFlow.GetState().stages.craft
				local it = crSt and crSt.tasks and crSt.tasks[self._itemIndex]
				if not it then return end
				GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
				GameTooltip:AddLine(tostring(it.name or "Craft Task"), 1.0, 0.85, 0.35)
				GameTooltip:AddLine(string.format("Profession: %s | Crafted: %d / %d",
					tostring(it.profName or it.profBadge or "Craft"), tonumber(it.completedCrafts) or 0, tonumber(it.neededCrafts) or 0), 0.90, 0.92, 0.94, true)
				GameTooltip:AddLine("Click: Select craft task", 0.55, 0.90, 1.00, true)
			else
				return
			end
			if ns.Theme and ns.Theme.LiftTooltip then ns.Theme.LiftTooltip(GameTooltip) end
			GameTooltip:Show()
		end)
		row:SetScript("OnLeave", function()
			if GameTooltip and GameTooltip.Hide then GameTooltip:Hide() end
		end)
		cbRows[i] = row
	end
