		dr:SetScript("OnClick", function(self)
			if self._destKey and app.cartBuyer and app.cartBuyer.SetDestinationFilter then
				cbScrollOffset = 0
				app.cartBuyer.SetDestinationFilter(self._destKey)
			end
		end)

		dr:Hide()
		cbDestRows[i] = dr
	end
	cartBuyerModal.treeDestRows = cbDestRows

	local function applyCartBuyerLayout()
		local targetW = cbExtended and CB_EXTENDED_W or CB_COMPACT_W
		cartBuyerModal:SetSize(targetW, CB_WIN_H)
		cbStripPane:ClearAllPoints()
		cbStripPane:SetPoint("TOPLEFT", cbWorkspace, "TOPLEFT", 0, 0)
		if cbExtended then
			cbStripPane:SetPoint("BOTTOMLEFT", cbWorkspace, "BOTTOMLEFT", 0, 0)
			cbStripPane:SetWidth(CB_STRIP_W)
			cbTreePane:Show()
		else
			cbStripPane:SetPoint("BOTTOMRIGHT", cbWorkspace, "BOTTOMRIGHT", 0, 0)
			cbTreePane:Hide()
		end
		local sk = getFlowStage()
		if sk == "craft" then
			cbExtendBtn:SetText(cbExtended and "Reagents <" or "Reagents >")
		else
			cbExtendBtn:SetText(cbExtended and "Buying For <" or "Buying For >")
		end
		if cartBuyerModal.warcraftChrome and ns.Theme.IsCustomSkin and ns.Theme.IsCustomSkin() then
			cartBuyerModal.warcraftChrome:Layout()
		end
		layoutStageBar()
		layoutMetricsCols()
	end

	function cartBuyerModal.SetExtended(want, skipSave)
		cbExtended = (want == true)
		if not skipSave and MerchantMasterDB then
			MerchantMasterDB.ahBuyerExtended = cbExtended
		end
		applyCartBuyerLayout()
		if cartBuyerModal.Render then cartBuyerModal.Render() end
	end

	function cartBuyerModal.IsExtended()
		return cbExtended == true
	end

	cbExtendBtn:SetScript("OnClick", function()
		cartBuyerModal.SetExtended(not cbExtended)
	end)

	local function paintCartBuyerHeaderAnchors(inAH, stageKey, ofState)
		local pal = getPal()
		local isCustom = ns.Theme and ns.Theme.IsCustomSkin and ns.Theme.IsCustomSkin()
		local isLight = (pal.mode == "light")
		stageKey = stageKey or getFlowStage()
		if cartBuyerModal.hdrPortraitWrap and isCustom then
			cartBuyerModal.hdrPortraitWrap:SetSize(28, 28)
			cartBuyerModal.hdrPortraitWrap:ClearAllPoints()
			cartBuyerModal.hdrPortraitWrap:SetPoint("LEFT", cbHdr, "LEFT", 16, 0)
		end
		if cartBuyerModal.titleFs and cbRestoreBtn and cartBuyerModal.closeBtn then
			cbRestoreBtn:ClearAllPoints()
			cbRestoreBtn:SetPoint("RIGHT", cartBuyerModal.closeBtn, "LEFT", -6, 0)
			if cbClearBtn then
				cbClearBtn:ClearAllPoints()
				cbClearBtn:SetPoint("RIGHT", cbRestoreBtn, "LEFT", -4, 0)
			end
			local tLeft = isCustom and 50 or 14
			cartBuyerModal.titleFs:ClearAllPoints()
			cartBuyerModal.titleFs:SetPoint("TOPLEFT", cbHdr, "TOPLEFT", tLeft, -7)
			cartBuyerModal.titleFs:SetPoint("RIGHT", cbClearBtn or cbRestoreBtn, "LEFT", -6, 0)
			local env = ofState and ofState.env or {}
			local hdrTitle, hdrSub
			if stageKey == "vendor" then
				hdrTitle = "VENDOR ORDER STRIP"
				hdrSub = env.atVendor and ("DOCKED TO VENDOR" .. (env.vendorName and (" - " .. tostring(env.vendorName):upper()) or "")) or "WAITING FOR VENDOR"
			elseif stageKey == "collect" then
				hdrTitle = "COLLECT OWNED STRIP"
				hdrSub = env.atBank and "DOCKED TO BANK" or (env.atMail and "DOCKED TO MAILBOX" or "WAITING FOR BANK / MAIL")
			elseif stageKey == "craft" then
				hdrTitle = "CRAFTING TASK STRIP"
				local crSt = ofState and ofState.stages and ofState.stages.craft
				local curT = crSt and crSt.tasks and crSt.tasks[crSt.activeIndex]
				local needProf = (curT and curT.profName and tostring(curT.profName):upper()) or "PROFESSION"
				if env.openProfKey then
					local openDisp = (curT and curT.profKey == env.openProfKey and curT.profName) or tostring(env.openProfKey)
					hdrSub = "DOCKED TO " .. tostring(openDisp):upper()
				else
					hdrSub = "WAITING FOR " .. needProf
				end
			else
				hdrTitle = "AH TRADE STRIP"
				hdrSub = inAH and "MINIMIZED - DOCKED TO AH" or "MINIMIZED - WAITING FOR AH"
			end
			cartBuyerModal.titleFs:SetText(hdrTitle)
			if cartBuyerModal.hdrSubFs then
				cartBuyerModal.hdrSubFs:ClearAllPoints()
				cartBuyerModal.hdrSubFs:SetPoint("TOPLEFT", cartBuyerModal.titleFs, "BOTTOMLEFT", 0, -2)
				cartBuyerModal.hdrSubFs:SetPoint("RIGHT", cbRestoreBtn, "LEFT", -6, 0)
				cartBuyerModal.hdrSubFs:SetText(hdrSub)
			end
		end
		local rFill = isLight and { 0.94, 0.95, 0.97, 1 } or (isCustom and { 0.06, 0.17, 0.12, 0.95 } or { 0.16, 0.17, 0.20, 0.94 })
		local rStroke = isLight and { 0.68, 0.45, 0.02, 0.72 } or ((isCustom and pal.frameBorder) or pal.cartMainAccent or { 0.83, 0.64, 0.24, 0.88 })
		local rText = isLight and (pal.text or { 0, 0, 0, 1 }) or ((isCustom and pal.headGold) or pal.text or { 0.97, 0.84, 0.49, 1 })
		cbRestoreBtn:PaintStyle(rFill, rStroke, rText, isLight and 0.10 or 0.24)
	end

	local function renderStageBar(pal, isCustom, isLight, goldBorder, accentGreen)
		layoutStageBar()
		local summary = (app.orderFlow and app.orderFlow.GetPipelineSummary) and app.orderFlow.GetPipelineSummary() or {}
		local activeStage = getFlowStage()
		for _, meta in ipairs(STAGE_ORDER) do
			local sb = cbStageBtns[meta.key]
			local info = nil
			for _, s in ipairs(summary) do
				if s.key == meta.key then info = s; break end
			end
			local isAct = (meta.key == activeStage)
			local isDone = info and (info.empty or info.complete)
			local suffix
			local baseLbl = cbExtended and meta.label or (meta.compact or meta.label)
			if not info or info.empty or info.complete then
				suffix = cbExtended and " [OK]" or ""
			else
				suffix = string.format(" %d/%d", info.done or 0, info.total or 0)
			end
			sb:SetText(baseLbl .. suffix)
			if isAct then
				local af = isLight and { 0.04, 0.44, 0.22, 0.16 } or (isCustom and { 0.36, 0.08, 0.14, 0.96 } or { 0.14, 0.28, 0.20, 0.96 })
				local as = isLight and { 0.68, 0.45, 0.02, 0.90 } or { 0.97, 0.84, 0.49, 0.98 }
				local at = isLight and { 0.06, 0.28, 0.14, 1.0 } or { 1.00, 0.97, 0.88, 1.0 }
				sb:PaintStyle(af, as, at, isLight and 0.10 or 0.28)
				sb.activeBar:SetColorTexture(accentGreen[1], accentGreen[2], accentGreen[3], 1.0)
				sb.activeBar:Show()
			elseif isDone then
				local df = isLight and { 0.00, 0.48, 0.18, 0.09 } or (isCustom and { 0.04, 0.15, 0.09, 0.92 } or { 0.08, 0.16, 0.12, 0.92 })
				local ds = isLight and { 0.00, 0.48, 0.18, 0.55 } or { 0.18, 0.95, 0.56, 0.65 }
				local dt = isLight and { 0.00, 0.42, 0.16, 1.0 } or { 0.60, 0.96, 0.74, 1.0 }
				sb:PaintStyle(df, ds, dt, 0.10)
				sb.activeBar:Hide()
			else
				local pf = isLight and { 0.95, 0.96, 0.98, 1.0 } or (isCustom and { 0.03, 0.10, 0.07, 0.90 } or { 0.11, 0.12, 0.15, 0.92 })
				local ps = isLight and { 0.00, 0.00, 0.00, 0.16 } or { goldBorder[1], goldBorder[2], goldBorder[3], 0.40 }
				local pt = isLight and (pal.text or { 0.12, 0.12, 0.14, 1 }) or { 0.88, 0.86, 0.80, 1.0 }
				sb:PaintStyle(pf, ps, pt, 0.08)
				sb.activeBar:Hide()
			end
		end
	end

	local function layoutSpotlightActionRow(mode, isCustom, isLight, goldBorder, skinKey, pal)
		local secFill = isLight and { 0.94, 0.95, 0.97, 1.0 } or (isCustom and { 0.06, 0.16, 0.11, 0.96 } or { 0.17, 0.18, 0.21, 0.96 })
		local secText = isLight and (pal.text or { 0, 0, 0, 1 }) or { 0.94, 0.92, 0.86, 1.0 }
		if mode == "next_stage" then
			cbOpenAHBtn:Hide()
			cbMarkBtn:Hide()
			cbNextBtn:Hide()
			cbExtraBtn:Hide()
			cbNextStageBtn:Show()
			local nf = isLight and { 0.04, 0.48, 0.24, 1.0 } or { 0.09, 0.50, 0.29, 0.98 }
			local nsCol = isLight and { 0.02, 0.36, 0.18, 0.95 } or { 0.97, 0.84, 0.49, 0.96 }
			cbNextStageBtn:PaintStyle(nf, nsCol, { 1.0, 0.98, 0.92, 1.0 }, 0.28, nil)
			return
		end
		cbNextStageBtn:Hide()
		cbOpenAHBtn:Show()
		cbMarkBtn:Show()
		cbNextBtn:Show()
		local w1, w2, w3, w4 = 114, 108, 98, nil
		if mode == "ah_confirm" then
			w1, w2, w3, w4 = 148, 94, 78, nil
		elseif mode == "vendor" then
			w1, w2, w3, w4 = 116, 94, 58, 46
		elseif mode == "collect" then
			w1, w2, w3, w4 = 126, 74, 70, 44
		elseif mode == "craft" then
			w1, w2, w3, w4 = 118, 68, 66, 62
		end
		cbOpenAHBtn:ClearAllPoints()
		cbOpenAHBtn:SetPoint("BOTTOMLEFT", cbSpotlight, "BOTTOMLEFT", 10, 10)
		cbOpenAHBtn:SetSize(w1, 30)
		cbMarkBtn:ClearAllPoints()
		cbMarkBtn:SetPoint("LEFT", cbOpenAHBtn, "RIGHT", 6, 0)
		cbMarkBtn:SetSize(w2, 30)
		cbNextBtn:ClearAllPoints()
		cbNextBtn:SetPoint("LEFT", cbMarkBtn, "RIGHT", 6, 0)
		cbNextBtn:SetSize(w3, 30)
		if w4 then
			cbExtraBtn:ClearAllPoints()
			cbExtraBtn:SetPoint("LEFT", cbNextBtn, "RIGHT", 6, 0)
			cbExtraBtn:SetSize(w4, 30)
			cbExtraBtn:Show()
			cbExtraBtn:PaintStyle(secFill, goldBorder, secText, isLight and 0.08 or 0.18)
		else
			cbExtraBtn:Hide()
		end
		if isCustom then
			cbOpenAHBtn:PaintStyle(
				{ 0.44, 0.07, 0.14, 0.96 },
				{ 0.97, 0.84, 0.49, 0.95 },
				{ 1.00, 0.96, 0.85, 1.00 },
				0.30,
				ns.Theme.GetSkinAsset(skinKey, "cta_bg"))
		else
			cbOpenAHBtn:PaintStyle(
				{ 0.04, 0.36, 0.78, 1.00 },
				{ 0.25, 0.58, 0.98, 0.92 },
				{ 1.00, 1.00, 1.00, 1.00 },
				0.22,
				nil)
		end
		cbMarkBtn:PaintStyle(secFill, goldBorder, secText, isLight and 0.08 or 0.18)
		cbNextBtn:PaintStyle(secFill, goldBorder, secText, isLight and 0.08 or 0.18)
	end

	local function positionSpotlightTitle(hasSecondLine)
		cbActiveFs:ClearAllPoints()
		if hasSecondLine then
			cbActiveFs:SetPoint("TOPLEFT", ui.spotSocket, "TOPRIGHT", 9, -1)
			cbActiveFs:SetPoint("RIGHT", ui.spotQtyPill, "LEFT", -6, 0)
		else
			cbActiveFs:SetPoint("LEFT", ui.spotSocket, "RIGHT", 9, 0)
			cbActiveFs:SetPoint("RIGHT", ui.spotQtyPill, "LEFT", -6, 0)
		end
	end

	local function renderRightDrawer(stageKey, cur, ofState, ctx)
		local pal, isCustom, skinKey, isLight = ctx.pal, ctx.isCustom, ctx.skinKey, ctx.isLight
		local goldBorder, subtleBorder, cardFill, sepCol, accentGreen = ctx.goldBorder, ctx.subtleBorder, ctx.cardFill, ctx.sepCol, ctx.accentGreen
		local hasFilter, activeDestKey = ctx.hasFilter, ctx.activeDestKey

		local tFill = isLight and { 0.95, 0.96, 0.98, 0.98 } or (isCustom and { 0.04, 0.09, 0.07, 0.92 } or { 0.09, 0.10, 0.13, 0.94 })
		ui.treeBgPlate:SetFill(tFill[1], tFill[2], tFill[3], tFill[4])
		ui.treeBgPlate:SetStroke(subtleBorder[1], subtleBorder[2], subtleBorder[3], isLight and 0.24 or 0.38)
		ui.treeSep:SetColorTexture(sepCol[1], sepCol[2], sepCol[3], isCustom and 0.70 or 0.42)

		local headCol = isLight and (pal.cartMainAccent or pal.text) or ((isCustom and pal.headGold) or pal.cartMainAccent or pal.text)
		ui.treeHeadFs:SetTextColor(headCol[1], headCol[2], headCol[3], 1)
		ui.destHeadFs:SetTextColor(headCol[1], headCol[2], headCol[3], 1)

		local pTagFill = isLight and { 0.44, 0.16, 0.70, 0.13 } or { 0.30, 0.14, 0.52, 0.88 }
		local pTagStroke = isLight and { 0.44, 0.16, 0.70, 0.62 } or { 0.79, 0.63, 1.00, 0.78 }

		cbTreeChainBox:Show()
		ui.destHeadFs:Show()
		ui.destCountPill:Show()
		cbDestList:Show()

		ui.treeItemPill:Paint(pTagFill, pTagStroke, palHex("hexCartSub", "d4b3ff"), cur and tostring(cur.name or "None") or "None")

		local boxFill = isLight and { 1.0, 1.0, 1.0, 0.98 } or (isCustom and { 0.03, 0.09, 0.06, 0.95 } or { 0.12, 0.13, 0.16, 0.95 })
		ui.chainPlate:SetFill(boxFill[1], boxFill[2], boxFill[3], boxFill[4])
		ui.chainPlate:SetStroke(goldBorder[1], goldBorder[2], goldBorder[3], isLight and 0.42 or 0.58)
		local shCol = pal.textMuted or { 0.62, 0.71, 0.66, 1 }
		ui.chainSubHdr:SetTextColor(shCol[1], shCol[2], shCol[3], 1)

		local matBorder = isLight and { 0.00, 0.48, 0.18, 0.72 } or { 0.18, 0.95, 0.56, 0.85 }
		local matBg = isLight and { 0.00, 0.48, 0.18, 0.09 } or { 0.06, 0.18, 0.12, 0.94 }
		local subBorder = isLight and { 0.44, 0.16, 0.70, 0.75 } or { 0.79, 0.63, 1.00, 0.88 }
		local subBg = isLight and { 0.44, 0.16, 0.70, 0.10 } or { 0.22, 0.10, 0.38, 0.90 }
		local goalBorder = isLight and { 0.68, 0.45, 0.02, 0.78 } or { 0.97, 0.84, 0.49, 0.88 }
		local goalBg = isLight and { 0.78, 0.58, 0.08, 0.11 } or { 0.30, 0.07, 0.13, 0.88 }
		local warnBorder = isLight and { 0.76, 0.46, 0.00, 0.82 } or { 0.96, 0.72, 0.14, 0.90 }
		local warnBg = isLight and { 0.86, 0.56, 0.04, 0.10 } or { 0.24, 0.16, 0.04, 0.92 }
		local redBorder = isLight and { 0.78, 0.11, 0.15, 0.82 } or { 0.95, 0.30, 0.28, 0.90 }
		local redBg = isLight and { 0.82, 0.16, 0.18, 0.10 } or { 0.28, 0.06, 0.08, 0.92 }

		local nodeIdx, connIdx, yOff = 0, 0, -24
		local isCraftDrawer = (stageKey == "craft")
		local nodeH = isCraftDrawer and 32 or 36
		local nodeStep = isCraftDrawer and 35 or 40
		if ui.chainOverflowFs then ui.chainOverflowFs:Hide() end
		local function pushConn(indentPx, label)
			connIdx = connIdx + 1
			if connIdx > #cbChainConns then return end
			local c = cbChainConns[connIdx]
			c:ClearAllPoints()
			c:SetPoint("TOPLEFT", cbTreeChainBox, "TOPLEFT", 18 + indentPx, yOff)
			c:SetPoint("TOPRIGHT", cbTreeChainBox, "TOPRIGHT", -10, yOff)
			c:SetText(palHex("hexGold", "f7d57c") .. label .. "|r")
			c:Show()
			yOff = yOff - 14
		end
		local function pushNode(indentPx, borderCol, bgCol, itemID, titleStr, subStr, spellID)
			nodeIdx = nodeIdx + 1
			if nodeIdx > #cbChainNodes then return end
			local nd = cbChainNodes[nodeIdx]
			nd:ClearAllPoints()
			nd:SetHeight(nodeH)
			nd:SetPoint("TOPLEFT", cbTreeChainBox, "TOPLEFT", 8 + indentPx, yOff)
			nd:SetPoint("TOPRIGHT", cbTreeChainBox, "TOPRIGHT", -8, yOff)
			nd.plate:SetFill(bgCol[1], bgCol[2], bgCol[3], bgCol[4] or 0.92)
			nd.plate:SetStroke(borderCol[1], borderCol[2], borderCol[3], borderCol[4] or 0.85)
			nd.accent:SetColorTexture(borderCol[1], borderCol[2], borderCol[3], 1.0)
			nd.socket:ApplyTheme(isCustom, skinKey, pal)
			nd.socket.icon:SetTexture(resolveIconTex(itemID, spellID))
			nd.textFs:SetText(titleStr)
			nd.subFs:SetText(subStr)
			nd:Show()
			yOff = yOff - nodeStep
		end

		if stageKey == "craft" then
			ui.treeHeadFs:SetText("CRAFT TASK - REAGENTS")
			ui.chainSubHdr:SetText("CURRENT TASK REAGENTS")
			local rList = {}
			if cur and app.orderFlow and app.orderFlow.ComputeTaskReadiness then
				local rd = app.orderFlow.ComputeTaskReadiness(cur)
				rList = rd.reagentsWithStock or {}
				for idxR = 1, math.min(6, #rList) do
					local rg = rList[idxR]
					local bCol, fCol, statHex
					if (rg.have or 0) >= (rg.needTotal or 1) then
						bCol, fCol, statHex = matBorder, matBg, palHex("hexPositive", "30d158")
					elseif (rg.have or 0) >= (rg.needPerCraft or 1) then
						bCol, fCol, statHex = warnBorder, warnBg, palHex("hexWarning", "ffd60a")
					else
						bCol, fCol, statHex = redBorder, redBg, palHex("hexDanger", "ff453a")
					end
					pushNode(0, bCol, fCol, rg.itemID,
						palHex("hexText", "ffffff") .. tostring(rg.name or "Reagent") .. "|r",
						string.format("%sIn Bags: %d / %d|r %s(%d/craft)|r",
							statHex, rg.have or 0, rg.needTotal or 0,
							palHex("hexMuted", "98989d"), rg.needPerCraft or 1))
				end
			end
			local overflowCnt = math.max(0, #rList - 6)
			if overflowCnt > 0 and ui.chainOverflowFs then
				ui.chainOverflowFs:ClearAllPoints()
				ui.chainOverflowFs:SetPoint("TOPLEFT", cbTreeChainBox, "TOPLEFT", 10, yOff)
				ui.chainOverflowFs:SetPoint("TOPRIGHT", cbTreeChainBox, "TOPRIGHT", -10, yOff)
				ui.chainOverflowFs:SetText(palHex("hexGold", "f7d57c") .. string.format("+%d more reagent%s", overflowCnt, overflowCnt == 1 and "" or "s") .. "|r")
				ui.chainOverflowFs:Show()
				cbTreeChainBox:SetHeight(256)
			elseif #rList > 4 then
				cbTreeChainBox:SetHeight(240)
			else
				cbTreeChainBox:SetHeight(196)
			end
		else
			cbTreeChainBox:SetHeight(196)
			if stageKey == "vendor" then
				ui.treeHeadFs:SetText("VENDOR FOR - CRAFT TREE")
				ui.chainSubHdr:SetText("SELECTED VENDOR ITEM -> CRAFT CHAIN")
			elseif stageKey == "collect" then
				ui.treeHeadFs:SetText("COLLECT FOR - CRAFT TREE")
				ui.chainSubHdr:SetText("SELECTED OWNED ITEM -> CRAFT CHAIN")
			else
				ui.treeHeadFs:SetText("BUYING FOR - CRAFT TREE")
				ui.chainSubHdr:SetText("SELECTED AH MATERIAL -> CRAFT CHAIN")
			end
			local provList = (cur and type(cur.provenance) == "table" and #cur.provenance > 0) and cur.provenance or nil
			local srcSub
			if stageKey == "vendor" then
				local up = cur and ((cur.liveUnit and cur.liveUnit > 0) and cur.liveUnit or cur.unitPrice) or 0
				srcSub = "Buy at Vendor - " .. ((up > 0) and (ns.FormatMoneyCompact(up) .. " ea") or "-")
			elseif stageKey == "collect" then
				local srcLbl = (cur and cur.source == "bank" and "Withdraw from Bank")
					or (cur and cur.source == "mail" and "Collect from Mailbox")
					or (cur and cur.source == "alt" and (cur.altLabel or "On Alt"))
					or "Ready in Bags"
				srcSub = srcLbl
			else
				local up = cur and ((cur.liveUnit and cur.liveUnit > 0) and cur.liveUnit or cur.targetUnit) or 0
				srcSub = "Buy on AH - " .. ((up > 0) and (ns.FormatMoneyCompact(up) .. " ea") or "-")
			end
			if cur and provList then
				local firstP = provList[1]
				if #provList == 1 or (firstP.subCraftName and firstP.subCraftName ~= "") then
					pushNode(0, matBorder, matBg, cur.itemID,
						palHex("hexText", "ffffff") .. string.format("%dx %s|r", firstP.qty or cur.needed or 1, tostring(cur.name or "")),
						palHex("hexSecondary", "ebebf5") .. srcSub .. "|r")
					if firstP.subCraftName and firstP.subCraftName ~= "" then
						pushConn(0, "v feeds sub-craft")
						local profTxt = (firstP.subCraftProf and firstP.subCraftProf ~= "") and ("Sub-Craft - " .. tostring(firstP.subCraftProf)) or "Sub-Craft"
						pushNode(10, subBorder, subBg, firstP.subCraftItemID or cur.itemID,
							palHex("hexText", "ffffff") .. tostring(firstP.subCraftName) .. "|r",
							palHex("hexCartSub", "d4b3ff") .. profTxt .. "|r")
						pushConn(10, "v crafts goal")
						pushNode(20, goalBorder, goalBg, firstP.targetItemID or cur.itemID,
							palHex("hexText", "ffffff") .. tostring(firstP.targetName or "Shopping List") .. "|r",
							palHex("hexGold", "f7d57c") .. tostring(firstP.sourceLabel or "Crafting Order") .. "|r")
					else
						pushConn(0, "v crafts goal")
						pushNode(10, goalBorder, goalBg, firstP.targetItemID or cur.itemID,
							palHex("hexText", "ffffff") .. tostring(firstP.targetName or "Shopping List") .. "|r",
							palHex("hexGold", "f7d57c") .. tostring(firstP.sourceLabel or "Crafting Order") .. "|r")
					end
				else
					pushNode(0, matBorder, matBg, cur.itemID,
						palHex("hexText", "ffffff") .. string.format("%dx %s|r", cur.needed or 1, tostring(cur.name or "")),
						palHex("hexSecondary", "ebebf5") .. "Shared across " .. tostring(#provList) .. " goals|r")
					for pIdx = 1, math.min(2, #provList) do
						local p = provList[pIdx]
						pushConn(0, string.format("v %dx for goal", p.qty or 1))
						pushNode(10, goalBorder, goalBg, p.targetItemID or cur.itemID,
							palHex("hexText", "ffffff") .. tostring(p.targetName or "Order") .. "|r",
							palHex("hexGold", "f7d57c") .. tostring(p.sourceLabel or "Crafting Order") .. "|r")
					end
				end
			elseif cur then
				pushNode(0, matBorder, matBg, cur.itemID,
					palHex("hexText", "ffffff") .. string.format("%dx %s|r", cur.needed or 1, tostring(cur.name or "")),
					palHex("hexSecondary", "ebebf5") .. srcSub .. "|r")
			end
		end
		for i = nodeIdx + 1, #cbChainNodes do cbChainNodes[i]:Hide() end
		for i = connIdx + 1, #cbChainConns do cbChainConns[i]:Hide() end

		-- Scrollable & Selectable All Cart Destinations (cross-stage filter)
		local dests = (app.orderFlow and app.orderFlow.GetAllDestinations) and app.orderFlow.GetAllDestinations()
			or ((app.cartBuyer and app.cartBuyer.GetAllDestinations) and app.cartBuyer.GetAllDestinations() or {})
		ui.destCountPill:Paint(pTagFill, pTagStroke, palHex("hexCartSub", "d4b3ff"),
			string.format("%d %s", #dests, #dests == 1 and "Goal" or "Goals"))

		local maxDestOff = math.max(0, #dests - CB_VISIBLE_DESTS)
		if cbDestScrollOffset > maxDestOff then cbDestScrollOffset = maxDestOff end
		if cbDestScrollOffset < 0 then cbDestScrollOffset = 0 end

		local hasDestScroll = ui.destScroll:Update(cbDestScrollOffset, CB_VISIBLE_DESTS, #dests, isLight, goldBorder, accentGreen)
		local destRightPad = hasDestScroll and -11 or 0

		for i = 1, CB_VISIBLE_DESTS do
			local dr = cbDestRows[i]
			local d = dests[cbDestScrollOffset + i]
			if d then
				dr._destKey = d.key or d.targetName
				dr:ClearAllPoints()
				dr:SetPoint("TOPLEFT", cbDestList, "TOPLEFT", 0, -((i - 1) * CB_DEST_H))
				dr:SetPoint("TOPRIGHT", cbDestList, "TOPRIGHT", destRightPad, -((i - 1) * CB_DEST_H))

				local isSelectedDest = (hasFilter and dr._destKey == activeDestKey)
				local allDone = ((d.boughtItems or d.boughtMats or 0) >= (d.totalItems or d.totalMats or 0) and (d.totalItems or d.totalMats or 0) > 0)
				if isSelectedDest then
					local selBg = isLight and { 0.00, 0.48, 0.18, 0.12 } or (isCustom and { 0.10, 0.26, 0.17, 0.96 } or { 0.16, 0.26, 0.21, 0.96 })
					dr.plate:SetFill(selBg[1], selBg[2], selBg[3], selBg[4])
					dr.plate:SetStroke(matBorder[1], matBorder[2], matBorder[3], 0.95)
					dr.accent:SetColorTexture(matBorder[1], matBorder[2], matBorder[3], 1.0)
				else
					dr.plate:SetFill(cardFill[1], cardFill[2], cardFill[3], cardFill[4] or 0.94)
					dr.plate:SetStroke(allDone and matBorder[1] or subtleBorder[1], allDone and matBorder[2] or subtleBorder[2], allDone and matBorder[3] or subtleBorder[3], allDone and 0.72 or (subtleBorder[4] or 0.36))
					local dAcc = allDone and matBorder or goalBorder
					dr.accent:SetColorTexture(dAcc[1], dAcc[2], dAcc[3], 0.92)
				end

				dr.nameFs:SetText(palHex("hexGold", "f7d57c") .. tostring(d.targetName or "Order") .. "|r")
				local bCnt = d.boughtItems or d.boughtMats or 0
				local tCnt = d.totalItems or d.totalMats or 0
				local pHex = allDone and palHex("hexPositive", "30d158") or palHex("hexSecondary", "ebebf5")
				dr.progFs:SetText(pHex .. string.format("%d/%d|r", bCnt, tCnt))

				local parts = {}
				for _, m in ipairs(d.items or {}) do
					local prefix = (m.subCraftName and m.subCraftName ~= "") and ("Via " .. tostring(m.subCraftName) .. " <- ") or ""
					parts[#parts + 1] = string.format("%s%dx %s%s", prefix, m.qty or 1, tostring(m.name or ""), m.done and " [OK]" or "")
				end
				dr.matsFs:SetText(palHex("hexSecondary", "ebebf5") .. table.concat(parts, " + ") .. "|r")
				dr:Show()
			else
				dr._destKey = nil
				dr:Hide()
			end
		end
	end

	local function renderStageRows(stageKey, activeIdx, visItems, visCap, ofState, ctx)
		local pal, isCustom, skinKey, isLight = ctx.pal, ctx.isCustom, ctx.skinKey, ctx.isLight
		local goldBorder, subtleBorder, cardFill, accentGreen = ctx.goldBorder, ctx.subtleBorder, ctx.cardFill, ctx.accentGreen
		local inAH = ctx.inAH
		local env = ofState and ofState.env or {}

		local maxOff = math.max(0, #visItems - visCap)
		if cbScrollOffset > maxOff then cbScrollOffset = maxOff end
		if cbScrollOffset < 0 then cbScrollOffset = 0 end

		local hasListScroll = ui.listScroll:Update(cbScrollOffset, visCap, #visItems, isLight, goldBorder, accentGreen)
		local rowRightPad = hasListScroll and -11 or 0

		for i = 1, CB_VISIBLE_ROWS do
			local row = cbRows[i]
			local entry = (i <= visCap) and visItems[cbScrollOffset + i] or nil
			if entry and entry.item then
				local idx = entry.index
				local it = entry.item
				row._itemIndex = idx
				row:ClearAllPoints()
				row:SetPoint("TOPLEFT", cbListFrame, "TOPLEFT", 0, -((i - 1) * CB_ROW_H))
				row:SetPoint("TOPRIGHT", cbListFrame, "TOPRIGHT", rowRightPad, -((i - 1) * CB_ROW_H))
				row:Show()

				local craftingKey = (stageKey == "craft" and app.orderFlow and app.orderFlow.GetActiveCraftingTaskKey)
					and app.orderFlow.GetActiveCraftingTaskKey() or nil
				local isRowCrafting = (craftingKey ~= nil and it.taskKey == craftingKey)

				local isSel = (idx == activeIdx)
				local isDone, isOverRow = false, false
				if stageKey == "craft" then
					isDone = (it.status == "done" or it.status == "skipped" or (it.remainingCrafts or 0) <= 0)
				else
					isDone = (it.status == "done" or it.status == "skipped" or (it.remaining or 0) <= 0)
					isOverRow = (stageKey == "ah" and inAH and not isDone and it.overBuyCap == true)
				end

				local rFill, rStroke
				if isSel then
					rFill = isLight and { 0.00, 0.48, 0.18, 0.10 } or (isCustom and { 0.09, 0.24, 0.16, 0.95 } or { 0.14, 0.24, 0.20, 0.95 })
					rStroke = isLight and (pal.accentGreen or { 0.00, 0.48, 0.18, 0.80 }) or { 0.18, 0.95, 0.56, 0.92 }
				elseif isRowCrafting then
					rFill = isLight and { 0.04, 0.44, 0.56, 0.08 } or { 0.05, 0.20, 0.25, 0.94 }
					rStroke = isLight and { 0.04, 0.44, 0.56, 0.72 } or { 0.34, 0.88, 0.98, 0.88 }
				else
					rFill = cardFill
					rStroke = subtleBorder
				end
				row.plate:SetFill(rFill[1], rFill[2], rFill[3], isDone and 0.65 or (rFill[4] or 0.94))
				row.plate:SetStroke(rStroke[1], rStroke[2], rStroke[3], rStroke[4] or 0.45)

				local stripe
				if isDone then
					stripe = pal.textMuted or { 0.42, 0.52, 0.46, 0.8 }
				elseif isRowCrafting then
					stripe = { 0.34, 0.88, 0.98, 0.98 }
				elseif isOverRow then
					stripe = pal.danger or { 1.00, 0.32, 0.28, 1 }
				elseif isSel then
					stripe = accentGreen
				elseif stageKey == "craft" then
					stripe = it.isSubCraft and { 0.72, 0.50, 0.98, 0.92 } or { 0.97, 0.84, 0.49, 0.92 }
				elseif stageKey == "vendor" then
					stripe = { 0.96, 0.72, 0.18, 0.85 }
				elseif stageKey == "collect" then
					stripe = (it.source == "bank" and { 0.34, 0.83, 0.91, 0.90 })
						or (it.source == "mail" and { 0.97, 0.84, 0.49, 0.90 })
						or (it.source == "alt" and { 0.72, 0.50, 0.98, 0.90 })
						or accentGreen
				else
					stripe = pal.pillBuyBorder or { 0.18, 0.80, 0.48, 0.72 }
				end
				row.accent:SetColorTexture(stripe[1], stripe[2], stripe[3], (isSel or isOverRow) and 1.0 or 0.72)

				row.socket:ApplyTheme(isCustom, skinKey, pal)
				row.icon:SetTexture(resolveIconTex(it.itemID, it.spellID))
				row.icon:Show()

				local pFill, pStroke, statusHex, statusLbl
				local nameHex = isDone and palHex("hexMuted", "98989d") or palHex("hexText", "ffffff")
				if stageKey == "ah" then
					if isDone then
						pFill = isLight and { 0.00, 0.48, 0.18, 0.12 } or { 0.06, 0.28, 0.16, 0.82 }
						pStroke = isLight and { 0.00, 0.48, 0.18, 0.55 } or { 0.18, 0.95, 0.56, 0.68 }
						statusHex = palHex("hexPositive", "30d158"); statusLbl = "Bought"
					elseif not inAH then
						pFill = isLight and { 0.00, 0.00, 0.00, 0.06 } or { 0.04, 0.10, 0.07, 0.86 }
						pStroke = subtleBorder
						statusHex = palHex("hexSecondary", "ebebf5"); statusLbl = "Waiting"
					elseif it.overBuyCap == true then
						pFill = isLight and { 0.78, 0.11, 0.15, 0.14 } or { 0.52, 0.07, 0.10, 0.92 }
						pStroke = isLight and { 0.72, 0.08, 0.10, 0.75 } or { 1.00, 0.36, 0.32, 0.95 }
						statusHex = isLight and palHex("hexDanger", "b8141a") or "|cffffffff"; statusLbl = "OVER!"
					elseif it.priceAlert == "high" then
						pFill = isLight and { 0.78, 0.11, 0.15, 0.12 } or { 0.48, 0.07, 0.09, 0.88 }
						pStroke = isLight and { 0.72, 0.08, 0.10, 0.65 } or { 1.00, 0.38, 0.34, 0.88 }
						statusHex = palHex("hexDanger", "ff453a"); statusLbl = string.format("+%d%%!", it.priceDeltaPct or 0)
					elseif it.priceAlert == "up" then
						pFill = isLight and { 0.68, 0.34, 0.00, 0.12 } or { 0.42, 0.28, 0.04, 0.86 }
						pStroke = isLight and { 0.68, 0.34, 0.00, 0.65 } or { 1.00, 0.82, 0.36, 0.88 }
						statusHex = palHex("hexWarning", "ffd60a"); statusLbl = string.format("+%d%%", it.priceDeltaPct or 0)
					elseif it.status == "active" then
						pFill = isLight and { 0.00, 0.48, 0.18, 0.14 } or { 0.08, 0.44, 0.25, 0.88 }
						pStroke = isLight and { 0.00, 0.48, 0.18, 0.72 } or { 0.18, 0.95, 0.56, 0.95 }
						statusHex = isLight and palHex("hexPositive", "007a2b") or "|cffffffff"; statusLbl = "In AH"
					else
						pFill = isLight and { 0.00, 0.00, 0.00, 0.06 } or { 0.04, 0.10, 0.07, 0.86 }
						pStroke = subtleBorder
						statusHex = palHex("hexSecondary", "ebebf5"); statusLbl = "Queued"
					end
					row.cells.name:SetText(nameHex .. tostring(it.name or "?") .. "|r")
					row.cells.need:SetText(palHex("hexSecondary", "ebebf5") .. string.format("%d/%d", it.bought or 0, it.needed or 0) .. "|r")
					local cartPriceText = (it.targetUnit and it.targetUnit > 0) and ns.FormatMoneyCompact(it.targetUnit) or (palHex("hexMuted", "98989d") .. "-|r")
					row.cells.cart:SetText(cartPriceText)
					if inAH and it.liveUnit and it.liveUnit > 0 then
						row.cells.live:SetText(ns.FormatMoneyCompact(it.liveUnit))
					else
						row.cells.live:SetText(cartPriceText)
					end
				elseif stageKey == "vendor" then
					if it.status == "done" or (it.remaining or 0) <= 0 then
						pFill = isLight and { 0.00, 0.48, 0.18, 0.12 } or { 0.06, 0.28, 0.16, 0.82 }
						pStroke = isLight and { 0.00, 0.48, 0.18, 0.55 } or { 0.18, 0.95, 0.56, 0.68 }
						statusHex = palHex("hexPositive", "30d158"); statusLbl = "Bought"
					elseif it.status == "skipped" then
						pFill = isLight and { 0.00, 0.00, 0.00, 0.05 } or { 0.06, 0.08, 0.07, 0.80 }
						pStroke = subtleBorder
						statusHex = palHex("hexMuted", "98989d"); statusLbl = "Skipped"
					elseif not env.atVendor then
						pFill = isLight and { 0.00, 0.00, 0.00, 0.06 } or { 0.04, 0.10, 0.07, 0.86 }
						pStroke = subtleBorder
						statusHex = palHex("hexSecondary", "ebebf5"); statusLbl = "Waiting"
					elseif it.hasExtendedCost then
						pFill = isLight and { 0.68, 0.34, 0.00, 0.12 } or { 0.40, 0.24, 0.04, 0.86 }
						pStroke = isLight and { 0.68, 0.34, 0.00, 0.65 } or { 1.00, 0.82, 0.36, 0.88 }
						statusHex = palHex("hexWarning", "ffd60a"); statusLbl = "Token"
					elseif it.numAvailable == 0 then
						pFill = isLight and { 0.78, 0.11, 0.15, 0.12 } or { 0.48, 0.07, 0.09, 0.88 }
						pStroke = isLight and { 0.72, 0.08, 0.10, 0.65 } or { 1.00, 0.38, 0.34, 0.88 }
						statusHex = palHex("hexDanger", "ff453a"); statusLbl = "SoldOut"
					elseif it.inStockHere then
						pFill = isLight and { 0.00, 0.48, 0.18, 0.14 } or { 0.08, 0.44, 0.25, 0.88 }
						pStroke = isLight and { 0.00, 0.48, 0.18, 0.72 } or { 0.18, 0.95, 0.56, 0.95 }
						statusHex = isLight and palHex("hexPositive", "007a2b") or "|cffffffff"; statusLbl = "InStock"
					else
						pFill = isLight and { 0.00, 0.00, 0.00, 0.06 } or { 0.04, 0.10, 0.07, 0.86 }
						pStroke = subtleBorder
						statusHex = palHex("hexMuted", "98989d"); statusLbl = "Other"
					end
					row.cells.name:SetText(nameHex .. tostring(it.name or "?") .. "|r")
					row.cells.need:SetText(palHex("hexSecondary", "ebebf5") .. string.format("%d/%d", it.bought or 0, it.needed or 0) .. "|r")
					local uP = (it.liveUnit and it.liveUnit > 0) and it.liveUnit or (it.unitPrice or 0)
					row.cells.live:SetText((uP > 0) and ns.FormatMoneyCompact(uP) or (palHex("hexMuted", "98989d") .. "-|r"))
				elseif stageKey == "collect" then
					local srcTag
					if it.source == "bank" then srcTag = palHex("hexInfo", "56d4e8") .. "Bank|r"
					elseif it.source == "mail" then srcTag = palHex("hexGold", "f7d57c") .. "Mail|r"
					elseif it.source == "alt" then srcTag = palHex("hexCartSub", "d4b3ff") .. "Alt|r"
					else srcTag = palHex("hexPositive", "30d158") .. "Bags|r" end
					if it.status == "done" or it.source == "bags" or (it.remaining or 0) <= 0 then
						pFill = isLight and { 0.00, 0.48, 0.18, 0.12 } or { 0.06, 0.28, 0.16, 0.82 }
						pStroke = isLight and { 0.00, 0.48, 0.18, 0.55 } or { 0.18, 0.95, 0.56, 0.68 }
						statusHex = palHex("hexPositive", "30d158"); statusLbl = "[OK]"
					elseif it.status == "skipped" then
						pFill = isLight and { 0.00, 0.00, 0.00, 0.05 } or { 0.06, 0.08, 0.07, 0.80 }
						pStroke = subtleBorder
						statusHex = palHex("hexMuted", "98989d"); statusLbl = "Skipped"
					elseif it.source == "alt" or it.status == "alt_info" then
						pFill = isLight and { 0.44, 0.16, 0.70, 0.12 } or { 0.24, 0.10, 0.42, 0.86 }
						pStroke = isLight and { 0.44, 0.16, 0.70, 0.62 } or { 0.79, 0.63, 1.00, 0.80 }
						statusHex = palHex("hexCartSub", "d4b3ff"); statusLbl = "Alt"
					elseif it.status == "ready" then
						pFill = isLight and { 0.00, 0.48, 0.18, 0.14 } or { 0.08, 0.44, 0.25, 0.88 }
						pStroke = isLight and { 0.00, 0.48, 0.18, 0.72 } or { 0.18, 0.95, 0.56, 0.95 }
						statusHex = isLight and palHex("hexPositive", "007a2b") or "|cffffffff"; statusLbl = "Ready"
					else
						pFill = isLight and { 0.68, 0.34, 0.00, 0.10 } or { 0.22, 0.16, 0.04, 0.86 }
						pStroke = subtleBorder
						statusHex = palHex("hexGold", "f7d57c"); statusLbl = (it.source == "bank") and "Bank" or "Mail"
					end
					row.cells.name:SetText(nameHex .. tostring(it.name or "?") .. "|r")
					row.cells.need:SetText(palHex("hexSecondary", "ebebf5") .. string.format("%d/%d", it.collected or 0, it.needed or 0) .. "|r")
					row.cells.live:SetText(srcTag)
				elseif stageKey == "craft" then
					local rd = (app.orderFlow and app.orderFlow.ComputeTaskReadiness) and app.orderFlow.ComputeTaskReadiness(it) or { canCraftNow = 0 }
					if it.status == "done" or (it.remainingCrafts or 0) <= 0 then
						pFill = isLight and { 0.00, 0.48, 0.18, 0.12 } or { 0.06, 0.28, 0.16, 0.82 }
						pStroke = isLight and { 0.00, 0.48, 0.18, 0.55 } or { 0.18, 0.95, 0.56, 0.68 }
						statusHex = palHex("hexPositive", "30d158"); statusLbl = "[OK]"
					elseif it.status == "skipped" then
						pFill = isLight and { 0.00, 0.00, 0.00, 0.05 } or { 0.06, 0.08, 0.07, 0.80 }
						pStroke = subtleBorder
						statusHex = palHex("hexMuted", "98989d"); statusLbl = "Skipped"
					elseif isRowCrafting then
						pFill = isLight and { 0.04, 0.44, 0.56, 0.16 } or { 0.06, 0.36, 0.44, 0.96 }
						pStroke = isLight and { 0.04, 0.44, 0.56, 0.85 } or { 0.34, 0.88, 0.98, 0.98 }
						statusHex = isLight and palHex("hexInfo", "005570") or "|cffffffff"; statusLbl = "CRAFTING"
					elseif (rd.canCraftNow or 0) > 0 and env.openProfKey == it.profKey then
						pFill = isLight and { 0.00, 0.48, 0.18, 0.14 } or { 0.08, 0.44, 0.25, 0.88 }
						pStroke = isLight and { 0.00, 0.48, 0.18, 0.72 } or { 0.18, 0.95, 0.56, 0.95 }
						statusHex = isLight and palHex("hexPositive", "007a2b") or "|cffffffff"; statusLbl = "Ready"
					elseif (rd.canCraftNow or 0) > 0 then
						pFill = isLight and { 0.68, 0.34, 0.00, 0.10 } or { 0.24, 0.16, 0.04, 0.86 }
						pStroke = isLight and { 0.68, 0.34, 0.00, 0.65 } or { 0.97, 0.84, 0.49, 0.82 }
						statusHex = palHex("hexGold", "f7d57c"); statusLbl = tostring(it.profBadge or "Open")
					else
						pFill = isLight and { 0.78, 0.11, 0.15, 0.12 } or { 0.44, 0.07, 0.09, 0.86 }
						pStroke = isLight and { 0.72, 0.08, 0.10, 0.65 } or { 0.95, 0.34, 0.32, 0.85 }
						statusHex = palHex("hexDanger", "ff453a"); statusLbl = "No Mats"
					end
					local tierPref = it.isSubCraft and (palHex("hexCartSub", "d4b3ff") .. "[Sub] |r") or ""
					row.cells.name:SetText(tierPref .. nameHex .. tostring(it.name or "?") .. "|r")
					row.cells.need:SetText(palHex("hexSecondary", "ebebf5") .. string.format("%d/%d", it.completedCrafts or 0, it.neededCrafts or 0) .. "|r")
					row.cells.live:SetText((it.isSubCraft and palHex("hexCartSub", "d4b3ff") or palHex("hexGold", "f7d57c")) .. tostring(it.profBadge or "CRAFT") .. "|r")
				end
				row.statusPill:ClearAllPoints()
				row.statusPill:SetPoint("RIGHT", row, "RIGHT", -7, 0)
				row.statusPill:SetWidth(statusLbl == "CRAFTING" and 66 or 54)
				row.statusPill:Paint(pFill, pStroke, statusHex, statusLbl)
				row.cells.hint:Hide()
			else
				row._itemIndex = nil
				row:Hide()
			end
		end
	end

	local function renderCartBuyer()
		local st = app.cartBuyer and app.cartBuyer.GetState()
		if not st then return end
		if app.orderFlow and app.orderFlow.SyncLiveEnvironment then
			app.orderFlow.SyncLiveEnvironment()
		end
		local ofState = (app.orderFlow and app.orderFlow.GetState) and app.orderFlow.GetState() or nil
		local stageKey = getFlowStage()
		local pal = getPal()
		local isCustom = ns.Theme and ns.Theme.IsCustomSkin and ns.Theme.IsCustomSkin()
		local skinKey = isCustom and ns.Theme.GetSkin() or "standard"
		local isLight = (pal.mode == "light")
		local inAH = atAH()
		local env = ofState and ofState.env or { atAH = inAH }

		paintCartBuyerHeaderAnchors(inAH, stageKey, ofState)

		local goldBorder = isLight and { 0.68, 0.45, 0.02, 0.68 } or ((isCustom and pal.frameBorder) or pal.cartMainAccent or { 0.83, 0.64, 0.24, 0.82 })
		local subtleBorder = isLight and { 0.00, 0.00, 0.00, 0.14 } or { goldBorder[1], goldBorder[2], goldBorder[3], 0.34 }
		local cardFill = isLight and { 0.98, 0.98, 0.99, 1.0 } or (isCustom and { 0.04, 0.12, 0.08, 0.94 } or { 0.13, 0.14, 0.17, 0.94 })
		local sepCol = (isCustom and pal.frameBorder) or pal.separator or { 0.5, 0.5, 0.5, 0.35 }
		local accentGreen = pal.accentGreen or pal.positive or { 0.18, 0.92, 0.54, 1 }

		renderStageBar(pal, isCustom, isLight, goldBorder, accentGreen)

		-- Top Progress Ribbon
		cbExtendBtn:SetWidth(94)
		cbSummaryFs:SetPoint("RIGHT", cbExtendBtn, "LEFT", -6, 0)
		cbToBuyFs:SetPoint("RIGHT", cbExtendBtn, "LEFT", -6, 0)
		if stageKey == "craft" then
			cbExtendBtn:SetText(cbExtended and "Reagents <" or "Reagents >")
		else
			cbExtendBtn:SetText(cbExtended and "Buying For <" or "Buying For >")
		end

		local stats = (app.orderFlow and app.orderFlow.GetStageStats) and app.orderFlow.GetStageStats(stageKey) or nil
		local progFrac = 0
		if stageKey == "ah" then
			local ov = (app.cartBuyer and app.cartBuyer.GetOverviewStats) and app.cartBuyer.GetOverviewStats() or {
				totalItems = #st.items, boughtItems = 0, remainingItems = #st.items,
				totalUnits = 0, boughtUnits = 0, remainingUnits = 0,
				totalEstCopper = 0, spentCopper = 0, remainingEstCopper = 0,
			}
			local spentTxt = (ov.spentCopper > 0) and ns.FormatMoneyCompact(ov.spentCopper) or (palHex("hexMuted", "98989d") .. "0c|r")
			local remTxt = (ov.remainingEstCopper > 0) and ns.FormatMoneyCompact(ov.remainingEstCopper) or (palHex("hexMuted", "98989d") .. "0c|r")
			local totTxt = (ov.totalEstCopper > 0) and ns.FormatMoneyCompact(ov.totalEstCopper) or (palHex("hexMuted", "98989d") .. "0c|r")
			cbSummaryFs:SetText(string.format("%sBought:|r %s%d/%d (%d/%d qty)|r %s-|r %s",
				palHex("hexPositive", "30d158"),
