					ui.spotSubFs:Show()
					local isCurDone = (cur.status == "done" or cur.status == "skipped" or (cur.remaining or 0) <= 0)
					local uP = (cur.liveUnit and cur.liveUnit > 0) and cur.liveUnit or (cur.unitPrice or 0)
					ui.mColExp.valFs:SetText((uP > 0) and ns.FormatMoneyCompact(uP) or (palHex("hexMuted", "98989d") .. "-|r"))
					if not env.atVendor then
						ui.mColLive.valFs:SetText(palHex("hexMuted", "98989d") .. "Closed|r")
					elseif cur.hasExtendedCost then
						ui.mColLive.valFs:SetText(palHex("hexWarning", "ffd60a") .. "Token Cost|r")
					elseif cur.numAvailable == 0 then
						ui.mColLive.valFs:SetText(palHex("hexDanger", "ff453a") .. "Sold Out|r")
					elseif cur.inStockHere then
						ui.mColLive.valFs:SetText(palHex("hexPositive", "30d158") .. "In Stock|r")
					else
						ui.mColLive.valFs:SetText(palHex("hexWarning", "ffd60a") .. "Not Here|r")
					end
					local packSz = math.max(1, math.floor(tonumber(cur.stackCount or cur.stackSize) or 1))
					local remUnits = math.max(0, math.floor(tonumber(cur.remaining) or 0))
					local numPacks = (remUnits > 0) and math.ceil(remUnits / packSz) or 0
					local remTot = (cur.packPrice and cur.packPrice > 0) and (numPacks * cur.packPrice) or (uP * numPacks * packSz)
					ui.mColDiff.valFs:SetText((remTot > 0) and ns.FormatMoneyCompact(remTot) or (palHex("hexMuted", "98989d") .. "0c|r"))
					if isCurDone then
						cbActiveFs:SetText(palHex("hexPositive", "30d158") .. tostring(cur.name or "") .. " - Done!|r")
						ui.spotQtyPill:Show(); ui.spotQtyPill:Paint(qtyFill, qtyStroke, qtyHex, "Done")
						cbOpenAHBtn:SetEnabled(false); cbNextBtn:SetEnabled(false); cbExtraBtn:SetEnabled(false)
					else
						cbActiveFs:SetText(palHex("hexText", "ffffff") .. tostring(cur.name or "") .. "|r")
						ui.spotQtyPill:Show(); ui.spotQtyPill:Paint(qtyFill, qtyStroke, qtyHex, string.format("%dx", cur.remaining or 0))
						local canBuy = (env.atVendor and cur.inStockHere == true and not cur.hasExtendedCost and cur.numAvailable ~= 0 and cur.isPurchasable ~= false)
						cbOpenAHBtn:SetEnabled(canBuy)
						cbNextBtn:SetEnabled(true)
						cbExtraBtn:SetEnabled(true)
					end
					local hasStockedHere = false
					local vList = ofState and ofState.stages and ofState.stages.vendor and ofState.stages.vendor.items or {}
					for _, vit in ipairs(vList) do
						if (vit.remaining or 0) > 0 and vit.status ~= "done" and vit.status ~= "skipped"
							and vit.inStockHere == true and not vit.hasExtendedCost and vit.numAvailable ~= 0 and vit.isPurchasable ~= false then
							hasStockedHere = true
							break
						end
					end
					cbMarkBtn:SetEnabled(env.atVendor == true and hasStockedHere)
				end
				if stageDonePrompt then
					cbActiveFs:SetText(palHex("hexPositive", "30d158") .. "Vendor Complete!|r")
					cbNextStageBtn:SetText(stageDonePrompt.label or "Next Stage ->")
					layoutSpotlightActionRow("next_stage", isCustom, isLight, goldBorder, skinKey, pal)
				else
					layoutSpotlightActionRow("vendor", isCustom, isLight, goldBorder, skinKey, pal)
				end
			elseif stageKey == "collect" then
				ui.mColExp.lblFs:SetText("LOCATION")
				ui.mColLive.lblFs:SetText("AVAILABLE")
				ui.mColDiff.lblFs:SetText("REMAINING")
				local isCollectAll = (app.orderFlow and app.orderFlow.IsCollectAllActive and app.orderFlow.IsCollectAllActive()) and true or false
				local canCollectAll = isCollectAll or ((app.orderFlow and app.orderFlow.HasCollectableAtCurrentSource and app.orderFlow.HasCollectableAtCurrentSource()) and true or false)
				cbMarkBtn:SetText(isCollectAll and "Stop" or "Collect All")
				cbNextBtn:SetText("Mark Done")
				cbExtraBtn:SetText("Skip")
				if not cur then
					cbActiveFs:SetText(palHex("hexMuted", "98989d") .. "No Owned items to collect|r")
					ui.spotQtyPill:Hide()
					ui.mColExp.valFs:SetText(palHex("hexMuted", "98989d") .. "-|r")
					ui.mColLive.valFs:SetText(palHex("hexMuted", "98989d") .. "-|r")
					ui.mColDiff.valFs:SetText(palHex("hexMuted", "98989d") .. "-|r")
					cbOpenAHBtn:SetText("Withdraw from Bank")
					cbOpenAHBtn:SetEnabled(false); cbMarkBtn:SetEnabled(canCollectAll); cbNextBtn:SetEnabled(false); cbExtraBtn:SetEnabled(false)
				else
					positionSpotlightTitle(true)
					local srcBadge = (cur.source == "bank" and "BANK") or (cur.source == "mail" and "MAIL") or (cur.source == "alt" and "ALT") or "BAGS"
					local sFillP = (cur.source == "bank" and { 0.06, 0.24, 0.30, 0.92 })
						or (cur.source == "mail" and { 0.30, 0.22, 0.06, 0.92 })
						or (cur.source == "alt" and { 0.26, 0.11, 0.44, 0.92 })
						or { 0.08, 0.36, 0.20, 0.90 }
					local sStrokeP = (cur.source == "bank" and { 0.34, 0.83, 0.91, 0.90 })
						or (cur.source == "mail" and { 0.97, 0.84, 0.49, 0.90 })
						or (cur.source == "alt" and { 0.79, 0.63, 1.00, 0.90 })
						or { 0.18, 0.95, 0.56, 0.90 }
					ui.spotTierPill:SetSize(48, 16)
					ui.spotTierPill:Paint(sFillP, sStrokeP, "|cffffffff", srcBadge)
					ui.spotTierPill:Show()
					ui.spotSubFs:ClearAllPoints()
					ui.spotSubFs:SetPoint("LEFT", ui.spotTierPill, "RIGHT", 6, 0)
					ui.spotSubFs:SetPoint("RIGHT", cbSpotlight, "TOPRIGHT", -10, -32)
					local locDesc = (cur.source == "bank" and "Withdraw from Bank")
						or (cur.source == "mail" and "Take from Mailbox")
						or (cur.source == "alt" and (cur.altLabel or "On Alt"))
						or "Already in Bags"
					ui.spotSubFs:SetText(palHex("hexSecondary", "ebebf5") .. locDesc .. "|r")
					ui.spotSubFs:Show()

					local locVal = (cur.source == "bank" and (palHex("hexInfo", "56d4e8") .. "Bank|r"))
						or (cur.source == "mail" and (palHex("hexGold", "f7d57c") .. "Mailbox|r"))
						or (cur.source == "alt" and (palHex("hexCartSub", "d4b3ff") .. "Alt|r"))
						or (palHex("hexPositive", "30d158") .. "Bags|r")
					ui.mColExp.valFs:SetText(locVal)
					if cur.source == "bank" then
						local avB = cur.availableHere or 0
						local avBHex = (avB > 0) and palHex("hexPositive", "30d158") or palHex("hexWarning", "ffd60a")
						ui.mColLive.valFs:SetText(env.atBank and (avBHex .. tostring(avB) .. " in Bank|r") or (palHex("hexMuted", "98989d") .. "Bank Closed|r"))
						cbOpenAHBtn:SetText("Withdraw from Bank")
					elseif cur.source == "mail" then
						local avM = cur.availableHere or 0
						local avMHex = (avM > 0) and palHex("hexPositive", "30d158") or palHex("hexWarning", "ffd60a")
						ui.mColLive.valFs:SetText(env.atMail and (avMHex .. tostring(avM) .. " in Mail|r") or (palHex("hexMuted", "98989d") .. "Mail Closed|r"))
						cbOpenAHBtn:SetText("Collect from Mail")
					elseif cur.source == "alt" then
						ui.mColLive.valFs:SetText(palHex("hexCartSub", "d4b3ff") .. "On Alt|r")
						cbOpenAHBtn:SetText("On Alt")
					else
						ui.mColLive.valFs:SetText(palHex("hexPositive", "30d158") .. "In Bags|r")
						cbOpenAHBtn:SetText("Ready in Bags")
					end
					local isCurDone = (cur.status == "done" or cur.status == "skipped" or (cur.remaining or 0) <= 0)
					ui.mColDiff.valFs:SetText(isCurDone and (palHex("hexPositive", "30d158") .. "Done|r") or (palHex("hexText", "ffffff") .. string.format("%dx|r", cur.remaining or 0)))
					if isCurDone then
						cbActiveFs:SetText(palHex("hexPositive", "30d158") .. tostring(cur.name or "") .. " - Ready!|r")
						ui.spotQtyPill:Show(); ui.spotQtyPill:Paint(qtyFill, qtyStroke, qtyHex, "[OK]")
						cbOpenAHBtn:SetEnabled(false); cbMarkBtn:SetEnabled(canCollectAll); cbNextBtn:SetEnabled(false); cbExtraBtn:SetEnabled(false)
					else
						cbActiveFs:SetText(palHex("hexText", "ffffff") .. tostring(cur.name or "") .. "|r")
						ui.spotQtyPill:Show(); ui.spotQtyPill:Paint(qtyFill, qtyStroke, qtyHex, string.format("%dx", cur.remaining or 0))
						local canAct = (cur.source == "bank" and env.atBank and (cur.availableHere or 0) > 0)
							or (cur.source == "mail" and env.atMail and (cur.availableHere or 0) > 0)
						cbOpenAHBtn:SetEnabled(canAct)
						cbMarkBtn:SetEnabled(canCollectAll)
						cbNextBtn:SetEnabled(cur.source ~= "alt")
						cbExtraBtn:SetEnabled(true)
					end
				end
				if stageDonePrompt then
					cbActiveFs:SetText(palHex("hexPositive", "30d158") .. "Collect Complete!|r")
					cbNextStageBtn:SetText(stageDonePrompt.label or "Next Stage ->")
					layoutSpotlightActionRow("next_stage", isCustom, isLight, goldBorder, skinKey, pal)
				else
					layoutSpotlightActionRow("collect", isCustom, isLight, goldBorder, skinKey, pal)
				end
			elseif stageKey == "craft" then
				ui.mColExp.lblFs:SetText("TO CRAFT")
				ui.mColLive.lblFs:SetText("MATS READY")
				ui.mColDiff.lblFs:SetText("CAN CRAFT NOW")
				cbMarkBtn:SetText("Select")
				cbNextBtn:SetText("Done")
				cbExtraBtn:SetText("Skip")
				if not cur then
					cbActiveFs:SetText(palHex("hexMuted", "98989d") .. "No Crafting tasks in cart|r")
					ui.spotQtyPill:Hide()
					ui.mColExp.valFs:SetText(palHex("hexMuted", "98989d") .. "-|r")
					ui.mColLive.valFs:SetText(palHex("hexMuted", "98989d") .. "-|r")
					ui.mColDiff.valFs:SetText(palHex("hexMuted", "98989d") .. "-|r")
					cbOpenAHBtn:SetText("Craft")
					cbOpenAHBtn:SetEnabled(false); cbMarkBtn:SetEnabled(false); cbNextBtn:SetEnabled(false); cbExtraBtn:SetEnabled(false)
				else
					positionSpotlightTitle(true)
					local isSub = (cur.isSubCraft == true)
					ui.spotTierPill:SetSize(74, 16)
					if isSub then
						local sf = isLight and { 0.44, 0.16, 0.70, 0.14 } or { 0.34, 0.14, 0.58, 0.94 }
						local ss = isLight and { 0.44, 0.16, 0.70, 0.75 } or { 0.79, 0.63, 1.00, 0.92 }
						ui.spotTierPill:Paint(sf, ss, isLight and palHex("hexCartSub", "6b24a8") or "|cffffffff", "SUB-CRAFT")
					else
						local mf = isLight and { 0.76, 0.52, 0.06, 0.14 } or { 0.36, 0.24, 0.05, 0.94 }
						local ms = isLight and { 0.68, 0.45, 0.02, 0.78 } or { 0.97, 0.84, 0.49, 0.94 }
						ui.spotTierPill:Paint(mf, ms, isLight and palHex("hexGold", "8a5a00") or "|cffffffff", "MAIN ORDER")
					end
					ui.spotTierPill:Show()
					local pf = isLight and { 0.04, 0.46, 0.58, 0.14 } or { 0.06, 0.22, 0.28, 0.94 }
					local ps = isLight and { 0.04, 0.46, 0.58, 0.75 } or { 0.34, 0.83, 0.91, 0.92 }
					ui.spotProfPill:Paint(pf, ps, isLight and palHex("hexInfo", "086e8a") or "|cffffffff", tostring(cur.profBadge or "CRAFT"))
					ui.spotProfPill:Show()

					local rd = (app.orderFlow and app.orderFlow.ComputeTaskReadiness) and app.orderFlow.ComputeTaskReadiness(cur)
						or { matsReadyCount = 0, totalReagents = 0, canCraftNow = 0 }
					local isCurDone = (cur.status == "done" or cur.status == "skipped" or (cur.remainingCrafts or 0) <= 0)
					ui.mColExp.valFs:SetText(palHex("hexText", "ffffff") .. string.format("%d/%d|r", cur.completedCrafts or 0, cur.neededCrafts or 0))
					local mHex
					if rd.totalReagents == 0 or rd.matsReadyCount >= rd.totalReagents then
						mHex = palHex("hexPositive", "30d158")
					elseif rd.matsReadyCount > 0 then
						mHex = palHex("hexWarning", "ffd60a")
					else
						mHex = palHex("hexDanger", "ff453a")
					end
					ui.mColLive.valFs:SetText(mHex .. string.format("%d/%d|r", rd.matsReadyCount or 0, rd.totalReagents or 0))
					local canNow = rd.canCraftNow or 0
					local cHex = (canNow > 0) and palHex("hexPositive", "30d158") or palHex("hexDanger", "ff453a")
					ui.mColDiff.valFs:SetText(cHex .. string.format("%dx|r", canNow))

					if isCurDone then
						cbActiveFs:SetText(palHex("hexPositive", "30d158") .. tostring(cur.name or "") .. " - Crafted!|r")
						ui.spotQtyPill:Show(); ui.spotQtyPill:Paint(qtyFill, qtyStroke, qtyHex, "Done")
						cbOpenAHBtn:SetText((stats and stats.complete) and "All Crafted!" or "Craft")
						cbOpenAHBtn:SetEnabled(false); cbMarkBtn:SetEnabled(false); cbNextBtn:SetEnabled(false); cbExtraBtn:SetEnabled(false)
					else
						cbActiveFs:SetText(palHex("hexText", "ffffff") .. tostring(cur.name or "") .. "|r")
						ui.spotQtyPill:Show(); ui.spotQtyPill:Paint(qtyFill, qtyStroke, qtyHex, string.format("%dx", cur.remainingCrafts or 0))
						local profMatches = (env.openProfKey ~= nil and env.openProfKey == cur.profKey)
						local isClassicCraftFrame = (_G.CraftFrame and _G.CraftFrame.IsShown and _G.CraftFrame:IsShown())
							and not (_G.TradeSkillFrame and _G.TradeSkillFrame.IsShown and _G.TradeSkillFrame:IsShown())
							and not (C_TradeSkillUI and C_TradeSkillUI.CraftRecipe)
						local craftCountDisp = isClassicCraftFrame and 1 or canNow
						local craftLabel = (canNow > 0) and string.format("Craft %dx", craftCountDisp) or "Craft"
						cbOpenAHBtn:SetText(craftLabel)
						cbOpenAHBtn:SetEnabled(profMatches and canNow > 0)
						cbMarkBtn:SetEnabled(profMatches)
						cbNextBtn:SetEnabled(true)
						cbExtraBtn:SetEnabled(true)
					end
				end
				if stageDonePrompt then
					cbActiveFs:SetText(palHex("hexPositive", "30d158") .. "Crafting Complete!|r")
					cbNextStageBtn:SetText(stageDonePrompt.label or "Next Stage ->")
					layoutSpotlightActionRow("next_stage", isCustom, isLight, goldBorder, skinKey, pal)
				else
					layoutSpotlightActionRow("craft", isCustom, isLight, goldBorder, skinKey, pal)
				end
			end
		end

		-- Live Notice Pill Bar across all 4 stages (auto-hides when notice is nil/empty)
		local noticeTxt = (ofState and type(ofState.notice) == "string" and ofState.notice ~= "" and ofState.notice)
			or (st and type(st.notice) == "string" and st.notice ~= "" and st.notice)
			or nil
		local noticeKind = (ofState and type(ofState.notice) == "string" and ofState.notice ~= "" and ofState.noticeKind)
			or (st and st.noticeKind)
			or "info"
		local hasNotice = (noticeTxt ~= nil)
		if hasNotice then
			cbNoticeBar:ClearAllPoints()
			cbNoticeBar:SetPoint("TOPLEFT", cbStripPane, "TOPLEFT", 2, topBelowCard)
			cbNoticeBar:SetPoint("TOPRIGHT", cbStripPane, "TOPRIGHT", -2, topBelowCard)
			local nFill, nStroke, nHex
			if noticeKind == "danger" or noticeKind == "error" then
				nFill = isLight and { 0.82, 0.14, 0.18, 0.14 } or { 0.30, 0.06, 0.08, 0.94 }
				nStroke = isLight and { 0.78, 0.12, 0.16, 0.75 } or { 0.96, 0.32, 0.30, 0.88 }
				nHex = palHex("hexDanger", "ff453a")
			elseif noticeKind == "warning" then
				nFill = isLight and { 0.86, 0.56, 0.04, 0.14 } or { 0.26, 0.18, 0.04, 0.94 }
				nStroke = isLight and { 0.76, 0.46, 0.00, 0.78 } or { 0.96, 0.78, 0.20, 0.88 }
				nHex = palHex("hexWarning", "ffd60a")
			elseif noticeKind == "positive" or noticeKind == "success" then
				nFill = isLight and { 0.00, 0.48, 0.18, 0.13 } or { 0.06, 0.22, 0.14, 0.94 }
				nStroke = isLight and { 0.00, 0.48, 0.18, 0.72 } or { 0.18, 0.95, 0.56, 0.85 }
				nHex = palHex("hexPositive", "30d158")
			else
				nFill = isLight and { 0.04, 0.46, 0.58, 0.12 } or { 0.06, 0.16, 0.22, 0.94 }
				nStroke = isLight and { 0.04, 0.46, 0.58, 0.68 } or { 0.34, 0.83, 0.91, 0.80 }
				nHex = palHex("hexInfo", "56d4e8")
			end
			ui.noticePlate:SetFill(nFill[1], nFill[2], nFill[3], nFill[4])
			ui.noticePlate:SetStroke(nStroke[1], nStroke[2], nStroke[3], nStroke[4])
			cbNoticeFs:SetText(nHex .. tostring(noticeTxt) .. "|r")
			cbNoticeFs:Show()
			cbNoticeBar:Show()
			topBelowCard = topBelowCard - 24
		else
			cbNoticeFs:SetText("")
			cbNoticeFs:Hide()
			cbNoticeBar:Hide()
		end

		-- Active Destination Filter Bar
		if hasFilter then
			cbFilterBar:ClearAllPoints()
			cbFilterBar:SetPoint("TOPLEFT", cbStripPane, "TOPLEFT", 2, topBelowCard)
			cbFilterBar:SetPoint("TOPRIGHT", cbStripPane, "TOPRIGHT", -2, topBelowCard)
			local fBg = isLight and { 0.78, 0.58, 0.08, 0.14 } or (isCustom and { 0.10, 0.24, 0.16, 0.95 } or { 0.16, 0.20, 0.24, 0.95 })
			ui.filterPlate:SetFill(fBg[1], fBg[2], fBg[3], fBg[4])
			ui.filterPlate:SetStroke(goldBorder[1], goldBorder[2], goldBorder[3], 0.88)
			cbFilterFs:SetText(palHex("hexGold", "f7d57c") .. "Craft: |r" .. palHex("hexText", "ffffff") .. tostring(activeDestKey) .. "|r")
			local cfFill = isLight and { 0.96, 0.96, 0.98, 1 } or { 0.26, 0.06, 0.10, 0.94 }
			local cfTxt = isLight and (pal.text or { 0, 0, 0, 1 }) or { 1.0, 0.92, 0.78, 1 }
			cbFilterClearBtn:PaintStyle(cfFill, goldBorder, cfTxt, 0.12)
			cbFilterBar:Show()
			cbListFrame:SetPoint("TOPLEFT", cbStripPane, "TOPLEFT", 2, topBelowCard - 28)
		else
			cbFilterBar:Hide()
			cbListFrame:SetPoint("TOPLEFT", cbStripPane, "TOPLEFT", 2, topBelowCard - 2)
		end
		cbListFrame:SetPoint("BOTTOMRIGHT", cbStripPane, "BOTTOMRIGHT", -2, 0)

		local ctx = {
			pal = pal, isCustom = isCustom, skinKey = skinKey, isLight = isLight, inAH = inAH,
			goldBorder = goldBorder, subtleBorder = subtleBorder, cardFill = cardFill,
			sepCol = sepCol, accentGreen = accentGreen,
			hasFilter = hasFilter, activeDestKey = activeDestKey,
		}
		local visItems = getActiveVisibleEntries()
		local visCap = getVisCap(hasFilter, hasCap or hasCraftBar, hasNotice)
		renderStageRows(stageKey, activeIdx, visItems, visCap, ofState, ctx)

		if cbExtended then
			renderRightDrawer(stageKey, cur, ofState, ctx)
		end
	end
	cartBuyerModal.Render = renderCartBuyer

	local function onFlowStateUpdated()
		if app.ui._updateTopTaskListBadge then app.ui._updateTopTaskListBadge() end
		if cartBuyerModal:IsShown() then
			renderCartBuyer()
		end
	end
	if app.orderFlow and app.orderFlow.SetOnUpdate then
		app.orderFlow.SetOnUpdate(onFlowStateUpdated)
	end
	if app.cartBuyer and app.cartBuyer.SetOnUpdate then
		app.cartBuyer.SetOnUpdate(onFlowStateUpdated)
	end
	cartBuyerModal:HookScript("OnHide", function()
		app._ahBuyingMode = false
		if app.orderFlow and app.orderFlow.OnWindowHide then
			app.orderFlow.OnWindowHide()
		elseif app.cartBuyer then
			app.cartBuyer.OnWindowHide()
		end
	end)
	ns.Theme.RegisterWidget(cbWorkspace, function()
		local ofState = (app.orderFlow and app.orderFlow.GetState) and app.orderFlow.GetState() or nil
		paintCartBuyerHeaderAnchors(atAH(), getFlowStage(), ofState)
		if cartBuyerModal:IsShown() then renderCartBuyer() end
	end)

	local function getActiveDockAnchorFrame(stageKey)
		if stageKey == "ah" and AuctionHouseFrame and AuctionHouseFrame:IsShown() then
			return AuctionHouseFrame
		elseif stageKey == "vendor" and MerchantFrame and MerchantFrame:IsShown() then
			return MerchantFrame
		elseif stageKey == "collect" then
			if BankFrame and BankFrame:IsShown() then return BankFrame end
			if MailFrame and MailFrame:IsShown() then return MailFrame end
		elseif stageKey == "craft" then
			if ProfessionsFrame and ProfessionsFrame:IsShown() then return ProfessionsFrame end
			if TradeSkillFrame and TradeSkillFrame:IsShown() then return TradeSkillFrame end
			if CraftFrame and CraftFrame:IsShown() then return CraftFrame end
		end
		for _, f in ipairs({ AuctionHouseFrame, MerchantFrame, BankFrame, MailFrame, ProfessionsFrame, TradeSkillFrame, CraftFrame }) do
			if f and f:IsShown() then return f end
		end
		return nil
	end

	function app.dockCartBuyerModal()
		cartBuyerModal:ClearAllPoints()
		local stKey = getFlowStage()
		local anchorFrame = getActiveDockAnchorFrame(stKey)
		if anchorFrame then
			local modalW = (cartBuyerModal.GetWidth and cartBuyerModal:GetWidth()) or (cbExtended and CB_EXTENDED_W or CB_COMPACT_W)
			local screenW = (UIParent and UIParent.GetWidth and UIParent:GetWidth()) or 1920
			local anchorRight = (anchorFrame.GetRight and anchorFrame:GetRight()) or nil
			if anchorRight and (anchorRight + modalW + 12) > screenW then
				cartBuyerModal:SetPoint("TOPRIGHT", anchorFrame, "TOPLEFT", -12, 0)
			else
				cartBuyerModal:SetPoint("TOPLEFT", anchorFrame, "TOPRIGHT", 12, 0)
			end
		else
			cartBuyerModal:SetPoint("CENTER", UIParent, "CENTER", 0, 20)
		end
	end

	local hookedMerchantFrames = setmetatable({}, { __mode = "k" })
	function app.ensureMerchantFrameHooked()
		local mf = _G.MerchantFrame
		if mf and type(mf) == "table" and type(mf.HookScript) == "function" and not hookedMerchantFrames[mf] then
			hookedMerchantFrames[mf] = true
			mf:HookScript("OnShow", function()
				if app.orderFlow and app.orderFlow.OnMerchantShow then
					app.orderFlow.OnMerchantShow()
					if app.syncOrderFlowDockAndRender then app.syncOrderFlowDockAndRender() end
				end
			end)
			mf:HookScript("OnHide", function()
				if app.orderFlow and app.orderFlow.OnMerchantClosed then
					app.orderFlow.OnMerchantClosed()
					if app.syncOrderFlowDockAndRender then app.syncOrderFlowDockAndRender() end
				end
			end)
		end
	end

	function app.enterOrderFlowMode(initialStage)
		if initialStage == "sell" then
			if ns.AHSellTab and atAH() and ns.AHSellTab.SelectTab then
				return ns.AHSellTab.SelectTab()
			end
			initialStage = "ah"
		end
		if not app.orderFlow then return false end
		if app.ensureMerchantFrameHooked then app.ensureMerchantFrameHooked() end
		if app.orderFlow.SyncLiveEnvironment then
			app.orderFlow.SyncLiveEnvironment()
		end
		if initialStage and app.orderFlow.SetActiveStage then
			app.orderFlow.SetActiveStage(initialStage)
		end
		if not app._ahBuyingMode then
			app._preAHBuyState = {
				wasShown = panel and panel:IsShown() and true or false,
				wasMinimized = app._minimized == true,
				activeTab = app.activeTab,
			}
		end
		app._ahBuyingMode = true

		if shopModal and shopModal:IsShown() then shopModal:Hide() end
		if panel and panel:IsShown() then panel:Hide() end

		cbScrollOffset = 0
		cbDestScrollOffset = 0
		local savedExt = MerchantMasterDB and MerchantMasterDB.ahBuyerExtended == true
		cartBuyerModal.SetExtended(savedExt, true)
		app.dockCartBuyerModal()
		cartBuyerModal:Show()
		if cartBuyerModal.Raise then cartBuyerModal:Raise() end
		renderCartBuyer()

		local stKey = getFlowStage()
		if stKey == "ah" and atAH() and app.cartBuyer then
			local firstPending = 1
			local ahSt = app.cartBuyer.GetState and app.cartBuyer.GetState()
			if ahSt and ahSt.items then
				for i, it in ipairs(ahSt.items) do
					if (it.remaining or 0) > 0 and it.status ~= "done" and it.status ~= "skipped" then
						firstPending = i
						break
					end
				end
			end
			app.cartBuyer.OpenInAH(firstPending)
		elseif stKey == "vendor" and app.orderFlow.GetState then
			local env = app.orderFlow.GetState().env
			if ((MerchantFrame and MerchantFrame:IsShown()) or (env and env.atVendor)) and app.orderFlow.OnMerchantShow then
				app.orderFlow.OnMerchantShow()
				app.dockCartBuyerModal()
				renderCartBuyer()
			end
		elseif stKey == "collect" then
			if BankFrame and BankFrame:IsShown() and app.orderFlow.OnBankShow then
				app.orderFlow.OnBankShow()
				app.dockCartBuyerModal()
				renderCartBuyer()
			elseif MailFrame and MailFrame:IsShown() and app.orderFlow.OnMailShow then
				app.orderFlow.OnMailShow()
				app.dockCartBuyerModal()
				renderCartBuyer()
			end
		elseif stKey == "craft" and app.orderFlow.OnTradeSkillShow then
			local pk = app.orderFlow.GetOpenProfession and app.orderFlow.GetOpenProfession()
			if pk then app.orderFlow.OnTradeSkillShow() end
		end
		return true
	end

	function app.enterAHBuyingMode(terms, title)
		if not app.cartBuyer then return false end
		local count = app.cartBuyer.LoadTerms(terms, title)
		if count <= 0 then
			say("No Auction House items needed in this shopping list.")
			return false
		end
		return app.enterOrderFlowMode("ah")
	end

	function app.exitAHBuyingMode(restoreFull)
		local prev = app._preAHBuyState
		app._ahBuyingMode = false
		app._preAHBuyState = nil
		if cartBuyerModal and cartBuyerModal:IsShown() then
			cartBuyerModal:Hide()
		end
		if restoreFull == true and panel then
			if app._minimized and app.setMinimized and not (prev and prev.wasMinimized) then
				app.setMinimized(false, true)
			end
			panel:Show()
			if panel.Raise then panel:Raise() end
			if app.refresh then app.refresh() end
		end
	end

	function app.openCartBuyer(terms, title)
		return app.enterAHBuyingMode(terms, title)
	end
	end initCartBuyerUI() end

	local function cloneEntryShallow(d)
		local copy = {}
		for k, v in pairs(d) do copy[k] = v end
		return copy
	end

	local function forgedCrateID(rowOrID)
		if type(rowOrID) == "table" then
			rowOrID = rowOrID.crateID or rowOrID.itemID or rowOrID.rowKey
		end
		return tonumber(rowOrID) or (type(rowOrID) == "string" and tonumber(rowOrID:match("^forged:(%d+)$")))
	end

	local function readForgedQueueEntry(key, value)
		if type(value) == "table" then
			local id = forgedCrateID(value) or forgedCrateID(value.row) or forgedCrateID(key)
			return id, math.floor(tonumber(value.count) or 0)
		end
		return forgedCrateID(key), math.floor(tonumber(value) or 0)
	end

	-- Compact legacy maps and sparse arrays so the saved queue can be read with ipairs.
	local function splitForgedQueue(queue, crateID)
		local kept, count, previous = {}, 0, nil
		for key, value in pairs(type(queue) == "table" and queue or {}) do
			local id, qty = readForgedQueueEntry(key, value)
			if id and qty > 0 then
				local entry = type(value) == "table" and value or {}
				if id == crateID then
					count = count + qty
					previous = previous or entry
				else
					if entry.row ~= nil or entry.crateID ~= id or entry.count ~= qty or not entry.rowKey then
						entry = cloneEntryShallow(entry)
						entry.row = nil
						entry.crateID, entry.count = id, qty
						entry.rowKey = entry.rowKey or ("forged:" .. id)
					end
					kept[#kept + 1] = entry
				end
			end
		end
		return kept, count, previous
	end

	function app.isForgedHuman()
		local db = MerchantMasterDB or {}
		if db.forgedHumanDiplomacy ~= nil then return db.forgedHumanDiplomacy == true end
		return ((ns.GetRacialRepMultiplier and ns.GetRacialRepMultiplier()) or 1) > 1
	end

	function app.getForgedQueuedCount(rowOrCrateID)
		local queue = MerchantMasterDB and MerchantMasterDB.forgedTurnInQueue
		if type(queue) ~= "table" then return 0 end
		local id = forgedCrateID(rowOrCrateID)
		local count = 0
		for key, value in pairs(queue) do
			local crateID, qty = readForgedQueueEntry(key, value)
			if crateID and (rowOrCrateID == nil or id == crateID) and qty > 0 then
				count = count + qty
			end
		end
		return count
	end

	function app.adjustForgedTurnInQueue(row, delta)
		local db = MerchantMasterDB
		local crateID = type(row) == "table" and forgedCrateID(row)
		delta = math.floor(tonumber(delta) or 0)
		if not db or not crateID or delta == 0 then return false end
		local queue, count, previous = splitForgedQueue(db.forgedTurnInQueue, crateID)
		if count == 0 and delta < 0 then return false end
		local nextCount = count + delta
		if nextCount > 0 then
			local entry = {
				crateID = crateID,
				rowKey = (previous and previous.rowKey) or row.rowKey or ("forged:" .. crateID),
				count = nextCount,
				forgedMode = (previous and previous.forgedMode) or row.forgedMode or db.forgedMode or "self_funded",
				humanDiplomacy = (previous and previous.humanDiplomacy ~= nil) and previous.humanDiplomacy or app.isForgedHuman(),
			}
			queue[#queue + 1] = entry
		end
		db.forgedTurnInQueue = queue
		if not panel:IsShown() or app.activeTab ~= "forged" then app.syncUnifiedShoppingList() end
		app.refresh()
		return true
	end

	function app.hasUnifiedShoppingItems()
		local db = MerchantMasterDB
		if not db then return false end
		if type(db.craftOrderQueue) == "table" and #db.craftOrderQueue > 0 then return true end
		if type(db.shoppingList) == "table" and #db.shoppingList > 0 then return true end
		if app.getForgedQueuedCount() > 0 then return true end
		for _, mapTbl in ipairs({ db.writCraftQueue, db.spreadQueue, db.writTurnInQueue }) do
			if type(mapTbl) == "table" then
				for _, v in pairs(mapTbl) do
					if (tonumber(v) or 0) > 0 then return true end
				end
			end
		end
		return false
	end

	function app.clearUnifiedShoppingList()
		local db = MerchantMasterDB
		if not db then return end
		if type(db.craftOrderQueue) == "table" then wipe(db.craftOrderQueue) end
		if type(db.writCraftQueue) == "table" then wipe(db.writCraftQueue) end
		if type(db.spreadQueue) == "table" then wipe(db.spreadQueue) end
		if type(db.writTurnInQueue) == "table" then wipe(db.writTurnInQueue) end
		if type(db.forgedTurnInQueue) == "table" then wipe(db.forgedTurnInQueue) end
		if type(db.crateTurnInQueue) == "table" then wipe(db.crateTurnInQueue) end
		if type(db.shoppingList) == "table" then wipe(db.shoppingList) end

		app._profPreviewCleared = true

		if app.orderFlow and app.orderFlow.ClearSavedState then
			app.orderFlow.ClearSavedState()
		end
		if app.ui and app.ui._updateTopTaskListBadge then
			app.ui._updateTopTaskListBadge()
		end
		if app.setActiveShoppingList then
			app.setActiveShoppingList({}, themeText(EMPTY_SHOPPING_SUMMARY), "Shopping List", app.activeTab)
		end
		if app.superListProvider and app.superListProvider.RepaintVisible then
			app.superListProvider.RepaintVisible()
		end
		if app.vendorCrafterProvider and app.vendorCrafterProvider.RepaintVisible then
			app.vendorCrafterProvider.RepaintVisible()
		end
		if app.disenchantCrafterProvider and app.disenchantCrafterProvider.RepaintVisible then
			app.disenchantCrafterProvider.RepaintVisible()
		end
		if app.allItemsProvider and app.allItemsProvider.RepaintVisible then
			app.allItemsProvider.RepaintVisible()
		end
		if app.refresh then app.refresh() end
	end

	local function matchesCraftRemoveRef(e, ref)
		if type(e) ~= "table" then return false end
		local eSpell, rSpell = tonumber(e.spellID) or 0, tonumber(ref.spellID) or 0
		if eSpell > 0 or rSpell > 0 then
			return eSpell > 0 and eSpell == rSpell and (not e.prof or not ref.prof or e.prof == ref.prof)
		end
		if ref.idx and e.idx then
			return e.idx == ref.idx and (not ref.outputItemID or e.outputItemID == ref.outputItemID)
		end
		return (tonumber(ref.outputItemID) or 0) > 0
			and e.outputItemID == ref.outputItemID
			and (not e.prof or not ref.prof or e.prof == ref.prof)
	end

	function app.removeShoppingMainItem(ref)
		local db = MerchantMasterDB
		if not (db and type(ref) == "table") then return false end
		local removed = false
		if ref.sourceKind == "craft_order" and type(db.craftOrderQueue) == "table" then
			local targetIdx = tonumber(ref.queueIndex)
			if targetIdx and db.craftOrderQueue[targetIdx] and matchesCraftRemoveRef(db.craftOrderQueue[targetIdx], ref) then
				table.remove(db.craftOrderQueue, targetIdx)
				removed = true
			else
				for i = #db.craftOrderQueue, 1, -1 do
					if matchesCraftRemoveRef(db.craftOrderQueue[i], ref) then
						table.remove(db.craftOrderQueue, i)
						removed = true
						break
					end
				end
			end
		elseif ref.sourceKind == "writ_craft" and type(db.writCraftQueue) == "table" and ref.itemID ~= nil then
			if db.writCraftQueue[ref.itemID] ~= nil then
				db.writCraftQueue[ref.itemID] = nil
				removed = true
			end
		elseif ref.sourceKind == "spread" and type(db.spreadQueue) == "table" then
			local key = ref.queueKey or ref.itemID
			if key and db.spreadQueue[key] ~= nil then
				db.spreadQueue[key] = nil
				removed = true
			end
		elseif ref.sourceKind == "writ_turnin" and type(db.writTurnInQueue) == "table" and ref.writID ~= nil then
			if db.writTurnInQueue[ref.writID] ~= nil then
				db.writTurnInQueue[ref.writID] = nil
				removed = true
			end
		elseif ref.sourceKind == "forged_turnin" and type(db.forgedTurnInQueue) == "table" then
			local key = ref.queueKey or tonumber(ref.index or ref.queueIndex)
			local value = db.forgedTurnInQueue[key]
			local crateID = forgedCrateID(ref) or (value and readForgedQueueEntry(key, value))
			if crateID then
				local queue, count = splitForgedQueue(db.forgedTurnInQueue, crateID)
				if count > 0 then
					db.forgedTurnInQueue = queue
					removed = true
				end
			end
		elseif ref.sourceKind == "shopping" and type(db.shoppingList) == "table" then
			local idx = tonumber(ref.index)
			if idx and db.shoppingList[idx] and (not ref.key or db.shoppingList[idx].key == ref.key) then
				table.remove(db.shoppingList, idx)
				removed = true
			elseif ref.key then
				for i = #db.shoppingList, 1, -1 do
					local e = db.shoppingList[i]
					if e and e.key == ref.key then
						table.remove(db.shoppingList, i)
						removed = true
						break
					end
				end
			elseif idx and db.shoppingList[idx] then
				table.remove(db.shoppingList, idx)
				removed = true
			end
		end
		if removed then
			if not app.hasUnifiedShoppingItems() then

				app._profPreviewCleared = true

				if app.setActiveShoppingList then
					app.setActiveShoppingList({}, EMPTY_SHOPPING_SUMMARY, "Shopping List", app.activeTab)
				end
			elseif app.syncUnifiedShoppingList then
				app.syncUnifiedShoppingList()
			end
			if app.superListProvider and app.superListProvider.RepaintVisible then
				app.superListProvider.RepaintVisible()
			end
			if app.vendorCrafterProvider and app.vendorCrafterProvider.RepaintVisible then
				app.vendorCrafterProvider.RepaintVisible()
			end
			if app.disenchantCrafterProvider and app.disenchantCrafterProvider.RepaintVisible then
				app.disenchantCrafterProvider.RepaintVisible()
			end
			if app.allItemsProvider and app.allItemsProvider.RepaintVisible then
				app.allItemsProvider.RepaintVisible()
			end
			if app.refresh then app.refresh() end
		end
		return removed
	end

	function app.adjustShoppingMainQty(ref, delta)
		local db = MerchantMasterDB
		local numDelta = tonumber(delta) or 0
		local d = numDelta >= 0 and math.floor(numDelta + 0.5) or -math.floor(-numDelta + 0.5)
		if not (db and type(ref) == "table") or d == 0 then return false end
		local changed = false
		if ref.sourceKind == "craft_order" and type(db.craftOrderQueue) == "table" then
			local idx = tonumber(ref.queueIndex)
			if not (idx and db.craftOrderQueue[idx] and matchesCraftRemoveRef(db.craftOrderQueue[idx], ref)) then
				idx = nil
				for i = 1, #db.craftOrderQueue do
					if matchesCraftRemoveRef(db.craftOrderQueue[i], ref) then
						idx = i
						break
					end
				end
			end
			local e = idx and db.craftOrderQueue[idx]
			if e then
				local nextQty = math.floor((tonumber(e.qty) or 1) + 0.5) + d
				if nextQty <= 0 then
					table.remove(db.craftOrderQueue, idx)
				else
					e.qty = nextQty
					if e.reusedQty and e.reusedQty > nextQty then e.reusedQty = nextQty end
				end
				changed = true
			end
		elseif ref.sourceKind == "writ_craft" and type(db.writCraftQueue) == "table" and ref.itemID ~= nil then
			local cur = math.floor((tonumber(db.writCraftQueue[ref.itemID]) or 0) + 0.5)
			if cur > 0 or d > 0 then
				local nextQty = cur + d
				db.writCraftQueue[ref.itemID] = nextQty > 0 and nextQty or nil
				changed = true
			end
		elseif ref.sourceKind == "spread" and type(db.spreadQueue) == "table" then
			local key = ref.queueKey or ref.itemID
			if key ~= nil then
				local cur = math.floor((tonumber(db.spreadQueue[key]) or 0) + 0.5)
				if cur > 0 or d > 0 then
					local nextQty = cur + d
					db.spreadQueue[key] = nextQty > 0 and nextQty or nil
					changed = true
				end
			end
		elseif ref.sourceKind == "writ_turnin" and type(db.writTurnInQueue) == "table" and ref.writID ~= nil then
			local cur = math.floor((tonumber(db.writTurnInQueue[ref.writID]) or 0) + 0.5)
			if cur > 0 or d > 0 then
				local nextQty = cur + d
				db.writTurnInQueue[ref.writID] = nextQty > 0 and nextQty or nil
				changed = true
			end
		elseif ref.sourceKind == "forged_turnin" then
			return app.adjustForgedTurnInQueue(ref, d)
		elseif ref.sourceKind == "shopping" and type(db.shoppingList) == "table" then
			local idx = tonumber(ref.index)
			if not (idx and db.shoppingList[idx] and (not ref.key or db.shoppingList[idx].key == ref.key)) then
				idx = nil
				if ref.key then
					for i = 1, #db.shoppingList do
						if db.shoppingList[i] and db.shoppingList[i].key == ref.key then
							idx = i
							break
						end
					end
				end
			end
			local e = idx and db.shoppingList[idx]
			if e then
				local prevQty = math.max(1, math.floor((tonumber(e.qty) or 1) + 0.5))
				local nextQty = prevQty + d
				if nextQty <= 0 then
					table.remove(db.shoppingList, idx)
				else
					e.qty = nextQty
					if e.numMade and e.numMade > 0 then
						e.batches = math.ceil(nextQty / math.max(1, e.numMade))
					end
					if type(e.demandList) == "table" then
						local ratio = nextQty / prevQty
						for _, item in ipairs(e.demandList) do
							if type(item) == "table" and tonumber(item.qty) then
								item.qty = math.max(1, math.floor((tonumber(item.qty) * ratio) + 0.5))
							end
						end
					end
				end
				changed = true
			end
		end
		if changed then
			if not app.hasUnifiedShoppingItems() then
				app._profPreviewCleared = true
				if app.setActiveShoppingList then
					app.setActiveShoppingList({}, themeText(EMPTY_SHOPPING_SUMMARY), "Shopping List", app.activeTab)
				end
			elseif app.syncUnifiedShoppingList then
				app.syncUnifiedShoppingList()
			end
			if app.superListProvider and app.superListProvider.RepaintVisible then
				app.superListProvider.RepaintVisible()
			end
			if app.vendorCrafterProvider and app.vendorCrafterProvider.RepaintVisible then
				app.vendorCrafterProvider.RepaintVisible()
			end
			if app.disenchantCrafterProvider and app.disenchantCrafterProvider.RepaintVisible then
				app.disenchantCrafterProvider.RepaintVisible()
			end
			if app.allItemsProvider and app.allItemsProvider.RepaintVisible then
				app.allItemsProvider.RepaintVisible()
			end
			if app.refresh then app.refresh() end
		end
		return changed
	end

	function app.setShoppingMainQty(ref, targetQty)
		local db = MerchantMasterDB
		local rawNum = tonumber(targetQty)
		if not (db and type(ref) == "table" and rawNum) then return false end
		local qty = math.floor(rawNum)
		if qty < 0 then return false end
		if qty == 0 then
			return app.removeShoppingMainItem(ref) == true
		end
		local changed = false
		if ref.sourceKind == "craft_order" and type(db.craftOrderQueue) == "table" then
			local idx = tonumber(ref.queueIndex)
			if not (idx and db.craftOrderQueue[idx] and matchesCraftRemoveRef(db.craftOrderQueue[idx], ref)) then
				idx = nil
				for i = 1, #db.craftOrderQueue do
					if matchesCraftRemoveRef(db.craftOrderQueue[i], ref) then
						idx = i
						break
					end
				end
			end
			local e = idx and db.craftOrderQueue[idx]
			if e then
				e.qty = qty
				if e.reusedQty and e.reusedQty > qty then e.reusedQty = qty end
				changed = true
			end
		elseif ref.sourceKind == "writ_craft" and type(db.writCraftQueue) == "table" and ref.itemID ~= nil then
			db.writCraftQueue[ref.itemID] = qty
			changed = true
		elseif ref.sourceKind == "spread" and type(db.spreadQueue) == "table" then
			local key = ref.queueKey or ref.itemID
			if key ~= nil then
				db.spreadQueue[key] = qty
				changed = true
			end
		elseif ref.sourceKind == "writ_turnin" and type(db.writTurnInQueue) == "table" and ref.writID ~= nil then
			db.writTurnInQueue[ref.writID] = qty
			changed = true
		elseif ref.sourceKind == "forged_turnin" then
			local curCount = (app.getForgedQueuedCount and app.getForgedQueuedCount(ref.crateID)) or 0
			local delta = qty - curCount
			if delta == 0 then return true end
			return app.adjustForgedTurnInQueue(ref, delta)
		elseif ref.sourceKind == "shopping" and type(db.shoppingList) == "table" then
			local idx = tonumber(ref.index)
			if not (idx and db.shoppingList[idx] and (not ref.key or db.shoppingList[idx].key == ref.key)) then
				idx = nil
				if ref.key then
					for i = 1, #db.shoppingList do
						if db.shoppingList[i] and db.shoppingList[i].key == ref.key then
							idx = i
							break
						end
					end
				end
			end
			local e = idx and db.shoppingList[idx]
			if e then
				local prevQty = math.max(1, math.floor((tonumber(e.qty) or 1) + 0.5))
				e.qty = qty
				if e.numMade and e.numMade > 0 then
					e.batches = math.ceil(qty / math.max(1, e.numMade))
				end
				if type(e.demandList) == "table" then
					local ratio = qty / prevQty
					for _, item in ipairs(e.demandList) do
						if type(item) == "table" and tonumber(item.qty) then
							item.qty = math.max(1, math.floor((tonumber(item.qty) * ratio) + 0.5))
						end
					end
				end
				changed = true
			end
		end
		if changed then
			if not app.hasUnifiedShoppingItems() then
				app._profPreviewCleared = true
				if app.setActiveShoppingList then
					app.setActiveShoppingList({}, themeText(EMPTY_SHOPPING_SUMMARY), "Shopping List", app.activeTab)
				end
			elseif app.syncUnifiedShoppingList then
				app.syncUnifiedShoppingList()
			end
			if app.superListProvider and app.superListProvider.RepaintVisible then
				app.superListProvider.RepaintVisible()
			end
			if app.vendorCrafterProvider and app.vendorCrafterProvider.RepaintVisible then
				app.vendorCrafterProvider.RepaintVisible()
			end
			if app.disenchantCrafterProvider and app.disenchantCrafterProvider.RepaintVisible then
				app.disenchantCrafterProvider.RepaintVisible()
			end
			if app.allItemsProvider and app.allItemsProvider.RepaintVisible then
				app.allItemsProvider.RepaintVisible()
			end
			if app.refresh then app.refresh() end
		end
		return changed
	end

	local function cloneDemandList(src)
		if type(src) ~= "table" then return nil end
		local out = {}
		for i, d in ipairs(src) do
			if type(d) == "table" then
				out[i] = cloneEntryShallow(d)
			else
				out[i] = d
			end
		end
		return out
	end

	function app.addUnifiedShoppingItem(entry, suppressRefresh)
		if not (MerchantMasterDB and type(entry) == "table") then return false end
		MerchantMasterDB.shoppingList = MerchantMasterDB.shoppingList or {}
		local list = MerchantMasterDB.shoppingList
		local qty = math.max(1, math.floor((tonumber(entry.qty) or 1) + 0.5))
		local matched = nil
		if entry.key then
			for _, cur in ipairs(list) do
				if cur.key == entry.key then
					matched = cur
					break
				end
			end
		end
		if matched then
			matched.qty = (tonumber(matched.qty) or 0) + qty
			if type(entry.demandList) == "table" and #entry.demandList > 0 then
				matched.demandList = matched.demandList or {}
				for _, d in ipairs(entry.demandList) do
					local did = tonumber(d and d.itemID) or 0
					local dqty = tonumber(d and d.qty) or 0
					if did > 0 and dqty > 0 then
						local dProf = d.parentProf or ""
						local existing = nil
						for _, curD in ipairs(matched.demandList) do
							if curD and tonumber(curD.itemID) == did and (curD.parentProf or "") == dProf then
								existing = curD
								break
							end
						end
						if existing then
							existing.qty = (tonumber(existing.qty) or 0) + dqty
						else
							matched.demandList[#matched.demandList + 1] = cloneEntryShallow(d)
						end
					end
				end
			elseif entry.reagents then
				matched.reagents = entry.reagents
			end
			if matched.numMade and matched.numMade > 0 then
				matched.batches = math.ceil(matched.qty / math.max(1, matched.numMade))
			end
		else
			local made = math.max(1, tonumber(entry.numMade) or 1)
			local copy = {
				key = entry.key,
				name = entry.name,
				itemID = entry.itemID,
				spellID = entry.spellID,
				prof = entry.prof,
				qty = qty,
				numMade = made,
				batches = entry.batches or math.ceil(qty / made),
				isBundle = entry.isBundle == true,
				asCraft = entry.asCraft == true,
				sourceLabel = entry.sourceLabel or "Shopping",
				reagents = entry.reagents,
				demandList = cloneDemandList(entry.demandList),
			}
			list[#list + 1] = copy
		end
		if not suppressRefresh then
			if app.syncUnifiedShoppingList then app.syncUnifiedShoppingList() end
			if app.refresh then app.refresh() end
		end
		return true
	end

	function app.setActiveShoppingList(rows, summaryStr, contextLabel, sourceTabOverride, meta)
		rows = rows or {}
		app.singleCraftShoppingPreview = nil
		app._singleCraftPreviewDirty = nil
		app.rawUnifiedShoppingRows = rows
		app.activeShoppingSummary = summaryStr or "Shopping List"
		app.activeShoppingLabel = "Shopping List"
		app.activeShoppingSourceTab = sourceTabOverride or app.activeTab

		local displayed = shopPanel.setShoppingData(rows, app.activeShoppingSummary, rows, not shopModal:IsShown(), meta)
		app.activeShoppingRows = displayed or rows
		if shopModal.SetWindowTitle then
			shopModal:SetWindowTitle("Shopping List")
		else
			shopModal.titleFs:SetText((ns.Theme.IsCustomSkin and ns.Theme.IsCustomSkin()) and "SHOPPING LIST" or "Shopping List")
		end

		local hasMainRows = false
		for _, r in ipairs(rows) do
			if r.isMainRow then
				hasMainRows = true
				break
			end
		end
		local topLineCount, totalSpend, unpricedCount = 0, 0, 0
		for _, r in ipairs(rows) do
			if hasMainRows then
				if r.isMainRow then
					topLineCount = topLineCount + 1
					if r.groupTotalCost ~= nil then
						totalSpend = totalSpend + (tonumber(r.groupTotalCost) or 0)
					end
					unpricedCount = unpricedCount + (tonumber(r.groupMissingCount) or 0)
				end
			elseif not r.isSubRow then
				topLineCount = topLineCount + 1
				if r.lineCost ~= nil then
					totalSpend = totalSpend + (tonumber(r.lineCost) or 0)
				else
					unpricedCount = unpricedCount + 1
				end
			end
		end
		local dispCount = topLineCount > 0 and topLineCount or #rows
		app.ui._basketSummary = { count = dispCount, spend = totalSpend, unpriced = unpricedCount }
		if app.ui._updateTopCartButton then app.ui._updateTopCartButton() end
		if app.ui.openShopBtn then
			app.ui.openShopBtn:SetText(string.format("Shopping List (%d)", dispCount))
		end
		if app.ui.navBasketCount and app.ui.navBasketCount.SetVariant then
			app.ui.navBasketCount:SetVariant("neutral", tostring(dispCount))
			if app.ui.navBasketCount.frame then app.ui.navBasketCount.frame:SetShown(dispCount > 0) end
		end
		if app.ui.sidebarShopFs then
			if dispCount > 0 then
				local spendLbl = (unpricedCount > 0)
					and string.format("%s (+%d unpriced)", ns.FormatMoneyCompact(totalSpend), unpricedCount)
					or ns.FormatMoneyCompact(totalSpend)
				app.ui.sidebarShopFs:SetText(string.format("Basket: %d item%s · %s",
					dispCount, dispCount == 1 and "" or "s", spendLbl))
			else
				app.ui.sidebarShopFs:SetText("Basket: 0 items")
			end
		end
		if app.syncDashboardBasketCard then
			app.syncDashboardBasketCard()
		end
	end

	local function buildQueueSignatureParts(db, includeVolatile)
		db = db or MerchantMasterDB or {}
		local parts = {
			tostring(db.subCraftMode or "smart"),
			tostring(db.craftOrderDeductOwned == true),
			tostring(db.forgedHumanDiplomacy == true),
			tostring(db.crateMode or "cheapest"),
			tostring(db.writMode or "cheapest"),
			tostring(db.includeWritPouch == true),
		}
		if includeVolatile then
			parts[#parts + 1] = tostring(db.priceSource or "auto")
			parts[#parts + 1] = tostring(db.lastRefreshAt or 0)
			parts[#parts + 1] = tostring(ns.GetEffectivePriceVersion and ns.GetEffectivePriceVersion() or ns.priceCacheEpoch or 1)
			parts[#parts + 1] = tostring(app._subCraftOverrideEpoch or 0)
			parts[#parts + 1] = tostring(app._ownedCountsEpoch or 0)
			parts[#parts + 1] = tostring(ns.Theme and ns.Theme.GetMode and ns.Theme.GetMode() or "")
		end
		local function addQueueMap(tag, tbl)
			if type(tbl) ~= "table" then return end
			local ks = {}
			for k, v in pairs(tbl) do
				if (tonumber(v) or 0) > 0 then ks[#ks + 1] = tostring(k) .. "=" .. tostring(v) end
			end
			if #ks > 0 then
				table.sort(ks)
				parts[#parts + 1] = tag .. ":" .. table.concat(ks, ",")
			end
		end
		if type(db.craftOrderQueue) == "table" and #db.craftOrderQueue > 0 then
			local cq = {}
			for i, q in ipairs(db.craftOrderQueue) do
				cq[i] = tostring(q.idx or q.spellID or q.outputItemID or i) .. ":" .. tostring(q.qty or 0)
			end
			parts[#parts + 1] = "cq:" .. table.concat(cq, ",")
		end
		addQueueMap("wc", db.writCraftQueue)
		addQueueMap("sp", db.spreadQueue)
		addQueueMap("wt", db.writTurnInQueue)
		addQueueMap("ft", db.forgedTurnInQueue)
		addQueueMap("ct", db.crateTurnInQueue)
		if type(db.shoppingList) == "table" and #db.shoppingList > 0 then
			local sl = {}
			for i, e in ipairs(db.shoppingList) do
				sl[i] = tostring(e.key or e.itemID or e.spellID or i) .. ":" .. tostring(e.qty or 1)
			end
			parts[#parts + 1] = "sl:" .. table.concat(sl, ",")
		end
		if type(db.subCraftOverrides) == "table" and next(db.subCraftOverrides) ~= nil then
			local ov = {}
			for k, v in pairs(db.subCraftOverrides) do
				ov[#ov + 1] = tostring(k) .. "=" .. tostring(v)
			end
			table.sort(ov)
			parts[#parts + 1] = "ov:" .. table.concat(ov, ",")
		end
		return table.concat(parts, "|")
	end

	local function computeShoppingSyncSig(db)
		return buildQueueSignatureParts(db, true)
	end

	function app.getOrderFlowCartSignature()
		if not (app.hasUnifiedShoppingItems and app.hasUnifiedShoppingItems()) then
			return nil
		end
		return buildQueueSignatureParts(MerchantMasterDB, false)
	end

	function app.syncUnifiedShoppingList(cachedOpts)
		local db = MerchantMasterDB or {}
		local hasItems = app.hasUnifiedShoppingItems()
		if not hasItems then
			app._shoppingSyncSig = nil
			local meta = { mainCount = 0, groups = {} }
			if app.activeTab ~= "professor" then
				app.setActiveShoppingList({}, themeText(EMPTY_SHOPPING_SUMMARY), "Shopping List", app.activeTab)
			end
			return {}, 0, 0, meta, ""
		end
		local opts = cachedOpts or {}
		local rawRows, totalCost, missingCount, meta = ns.BuildUnifiedShoppingList(db, {
			profMap = opts.profMap or ns.GetPlayerProfessions(),
			repState = opts.repState or ns.GetMerchantReputation(),
			subCraftMode = db.subCraftMode or "smart",
			subCraftOverrides = db.subCraftOverrides,
			ownedCounts = opts.ownedCounts or ownedCounts(),
			deductOwned = (db.craftOrderDeductOwned == true),
			writRowsByID = opts.writRowsByID,
			forgedRowsByID = opts.forgedRowsByID,
			humanDiplomacy = db.forgedHumanDiplomacy,
			spreadRowsByID = opts.spreadRowsByID,
			writProfitRowsByItemID = opts.writProfitRowsByItemID,
			priceBank = app.getUIPriceBank and app.getUIPriceBank() or nil,
		})
		local mc = (meta and meta.mainCount) or 0
		-- Heading stays in primary ink (the title label is semibold); only the caption and warning are tinted.
		local sumStr = themeText(string.format(
			"Shopping List (%d Main Item%s):  %sEst. Spend:|r %s%s",
			mc, mc == 1 and "" or "s", palHex("hexSecondary", "ebebf5"),
			ns.FormatMoneyCompact(totalCost or 0),
			(missingCount and missingCount > 0) and string.format(" |cffff6644(+%d unpriced)|r", missingCount) or ""))
		app.setActiveShoppingList(rawRows, sumStr, "Shopping List", app.activeTab, meta)
		app._shoppingSyncSig = computeShoppingSyncSig(db)
		return app.activeShoppingRows, totalCost, missingCount, meta, sumStr
	end

	function app.refreshUnifiedShoppingDisplay()
		if app.hasUnifiedShoppingItems() then
			app.syncUnifiedShoppingList()
		else
			local preview = app.singleCraftShoppingPreview
			if preview then
				app.showSingleCraftShoppingPreview(preview.row, preview.units, preview.counts, preview.profMap,
					preview.subCraftMode, preview.subCraftOverrides, preview.sourceTab)
			elseif app.activeShoppingRows then
				app.setActiveShoppingList(app.rawUnifiedShoppingRows or app.activeShoppingRows, app.activeShoppingSummary, "Shopping List", app.activeShoppingSourceTab)
			end
		end
	end

	local function ensureShoppingListSyncedForOpen(cachedOpts)
		if app.hasUnifiedShoppingItems and app.hasUnifiedShoppingItems() then
			local sig = computeShoppingSyncSig(MerchantMasterDB)
			if not app.rawUnifiedShoppingRows or app._shoppingSyncSig ~= sig then
				app.syncUnifiedShoppingList(cachedOpts)
			end
		end
	end
	app.ensureShoppingListSynced = ensureShoppingListSyncedForOpen

	function app.toggleShoppingWindow(forceShow)
		if forceShow == true then
			ensureShoppingListSyncedForOpen()
			shopModal:Show()
			if shopModal.Raise then shopModal:Raise() end
			return
		elseif forceShow == false then
			shopModal:Hide()
			return
		end
		if shopModal:IsShown() then
			shopModal:Hide()
		else
			ensureShoppingListSyncedForOpen()
			shopModal:Show()
			if shopModal.Raise then shopModal:Raise() end
		end
	end

	function app.buildSingleCraftShoppingRows(row, targetUnits, counts, profMap, subCraftMode, subCraftOverrides)
		if not row or not row.craftBreakdown or #row.craftBreakdown == 0 then return {}, 0 end
		local qty = math.max(1, tonumber(targetUnits) or 1)
		local batches = math.ceil(qty / math.max(1, row.numMade or 1))
		local demand = {}
		for _, rg in ipairs(row.craftBreakdown) do
			demand[#demand + 1] = {
				itemID = rg.itemID,
				qty = rg.qty * batches,
				role = "Reagent",
				parentProf = row.prof,
			}
		end
		local ok, rows, spend, missing = pcall(function()
			ns.BeginEval(app.getUIPriceBank and app.getUIPriceBank() or nil)
			local preview, total, unpriced = ns.BuildShoppingListRows(demand, {
				profMap = profMap,
				subCraftMode = subCraftMode,
				subCraftOverrides = subCraftOverrides,
				ownedCounts = counts,
			})
			ns.EndEval()
			return preview, total, unpriced
		end)
		if not ok then
			if ns.ResetEval then ns.ResetEval() end
			error(rows, 0)
		end
		return rows, spend, missing
	end

	function app.showSingleCraftShoppingPreview(row, units, counts, profMap, subCraftMode, subCraftOverrides, sourceTab)
		local rows, spend = app.buildSingleCraftShoppingRows(row, units, counts, profMap, subCraftMode, subCraftOverrides)
		local summary = "Shopping List - " .. tostring(row.name or "") .. ": " .. ns.FormatMoneyCompact(spend)
		app.setActiveShoppingList(rows, summary, "Shopping List", sourceTab)
		app.singleCraftShoppingPreview = {
			row = row, units = units, counts = counts, profMap = profMap, subCraftMode = subCraftMode,
			subCraftOverrides = subCraftOverrides, sourceTab = app.activeShoppingSourceTab,
		}
	end
end

-- Wowhead Forever Recipe Source Popup + Reusable Clickable [WH] Able/How Cell Helper
local createAbleCell, bindAbleCell
do
	local wowheadModal = ns.Theme.CreateFloatingWindow(ADDON .. "WowheadWindow", "Wowhead Forever — Where to Get Recipe", 520, 178)
	wowheadModal:SetFrameStrata("FULLSCREEN_DIALOG")
	app.ui.wowheadModal = wowheadModal

	local body = wowheadModal.body
	local iconTex = body:CreateTexture(nil, "ARTWORK")
	iconTex:SetSize(28, 28)
	iconTex:SetPoint("TOPLEFT", 2, -2)
	iconTex:SetTexture(ns.QUESTION_ICON)
	wowheadModal.iconTex = iconTex

	local recipeTitleFs = body:CreateFontString(nil, "OVERLAY", "GameFontNormal")
	recipeTitleFs:SetPoint("TOPLEFT", 38, -2)
	recipeTitleFs:SetPoint("RIGHT", -4, 0)
	recipeTitleFs:SetJustifyH("LEFT")
	recipeTitleFs:SetWordWrap(false)
	themeLabel(recipeTitleFs, 13, "semibold")
	wowheadModal.recipeTitleFs = recipeTitleFs

	local sourceDetailFs = body:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
	sourceDetailFs:SetPoint("TOPLEFT", 38, -19)
	sourceDetailFs:SetPoint("RIGHT", -4, 0)
	sourceDetailFs:SetJustifyH("LEFT")
	sourceDetailFs:SetWordWrap(false)
	themeLabel(sourceDetailFs, 11, "regular", "textSecondary")
	wowheadModal.sourceDetailFs = sourceDetailFs

	local urlBox = CreateFrame("EditBox", nil, body, "InputBoxTemplate")
	urlBox:SetPoint("TOPLEFT", 4, -44)
	urlBox:SetPoint("TOPRIGHT", -4, -44)
	urlBox:SetHeight(24)
	urlBox:SetAutoFocus(false)
	ns.Theme.StyleEditBox(urlBox)
	wowheadModal.urlBox = urlBox
	app.ui.wowheadUrlBox = urlBox

	urlBox:SetScript("OnEscapePressed", function() wowheadModal:Hide() end)
	urlBox:SetScript("OnEnterPressed", function() wowheadModal:Hide() end)
	urlBox:SetScript("OnEditFocusGained", function(self)
		if self.HighlightText then self:HighlightText() end
	end)
	urlBox:SetScript("OnTextChanged", function(self, userInput)
		if userInput and wowheadModal.currentURL and self:GetText() ~= wowheadModal.currentURL then
			self:SetText(wowheadModal.currentURL)
			if self.HighlightText then self:HighlightText() end
		end
	end)

	local hintFs = body:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
	hintFs:SetPoint("TOPLEFT", 4, -74)
	hintFs:SetPoint("RIGHT", -4, 0)
	hintFs:SetJustifyH("LEFT")
	hintFs:SetWordWrap(false)
	hintFs:SetText("URL highlighted — press Ctrl+C to copy, then open in browser (Enter / Esc closes)")
	themeLabel(hintFs, 11, "regular", "accentGreen")

	local ahRecipeBtn = ns.Theme.CreatePlateButton(body, "Search Recipe on AH", 156, 24, { variant = "secondary", pill = true, fontSize = 11 })
	ahRecipeBtn:SetPoint("BOTTOMLEFT", 2, 2)
	ahRecipeBtn:SetScript("OnClick", function()
		local ca = wowheadModal.currentCA
		if ca and ca.recipeItemID and ca.acqType ~= "camp" then
			local rName = ns.ItemName(ca.recipeItemID, ca.recipeName)
			if rName and rName ~= "" then
				app.searchAH(rName, 1, ca.recipeItemID)
			end
		end
	end)
	wowheadModal.ahRecipeBtn = ahRecipeBtn

	local reselectBtn = ns.Theme.CreatePlateButton(body, "Highlight URL", 112, 24, { variant = "primary", pill = true, fontSize = 11 })
	reselectBtn:SetPoint("BOTTOMRIGHT", -84, 2)
	reselectBtn:SetScript("OnClick", function()
		if urlBox.SetFocus then urlBox:SetFocus() end
		if urlBox.HighlightText then urlBox:HighlightText() end
	end)

	local closeWhBtn = ns.Theme.CreatePlateButton(body, "Close", 76, 24, { variant = "secondary", pill = true, fontSize = 11 })
	closeWhBtn:SetPoint("BOTTOMRIGHT", -2, 2)
	closeWhBtn:SetScript("OnClick", function() wowheadModal:Hide() end)

	function app.openWowheadPopup(ca, fallbackName, fallbackIcon)
		if not ca or not ca.wowheadURL then return false end
		wowheadModal.currentCA = ca
		wowheadModal.currentURL = ca.wowheadURL
		local dispIcon = (ca.recipeItemID and ns.ItemIcon(ca.recipeItemID, fallbackIcon)) or fallbackIcon or ns.QUESTION_ICON
		iconTex:SetTexture(dispIcon)
		local rTitle = ca.wowheadLabel or ca.recipeName or fallbackName or "Recipe"
		local kindBadge = (ca.wowheadKind == "spell") and "[Spell]" or "[Recipe Item]"
		recipeTitleFs:SetText(string.format("%s  %s", rTitle, kindBadge))
		sourceDetailFs:SetText("Where to get: " .. tostring(ca.howDetail or ca.howShort or "Trainer / Vendor / AH"))
		ahRecipeBtn:SetShown(ca.recipeItemID ~= nil and ca.acqType ~= "camp")
		urlBox:SetText(ca.wowheadURL)
		wowheadModal:Show()
		if wowheadModal.Raise then wowheadModal:Raise() end
		if urlBox.SetFocus then urlBox:SetFocus() end
		if urlBox.HighlightText then urlBox:HighlightText() end
		return true
	end

	createAbleCell = function(r, width, xOffset, showRowTooltipFn, onFallbackClickFn)
		local cBtn = CreateFrame("Button", nil, r)
		cBtn:SetSize(width, ROW_H)
		cBtn:SetPoint("LEFT", r, "LEFT", xOffset, 0)
		cBtn.fs = cBtn:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
		cBtn.fs:SetPoint("LEFT", cBtn, "LEFT", 0, 0)
		cBtn.fs:SetPoint("RIGHT", cBtn, "RIGHT", 0, 0)
		cBtn.fs:SetJustifyH("LEFT")
		cBtn.fs:SetWordWrap(false)

		local whBtn = CreateFrame("Button", nil, cBtn)
		whBtn:SetSize(28, 16)
		whBtn:SetPoint("RIGHT", cBtn, "RIGHT", -1, 0)
		whBtn.surface = ns.Theme.NineApple(whBtn, "pill", getPal().glassFill, false, { cornerSize = 8, noSpecular = true })
		whBtn.hl = whBtn:CreateTexture(nil, "HIGHLIGHT")
		whBtn.hl:SetAllPoints()
		local whc = getPal().glassHover or { 1, 1, 1, 0.08 }
		whBtn.hl:SetColorTexture(whc[1], whc[2], whc[3], whc[4] or 0.08)
		whBtn.fs = whBtn:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
		whBtn.fs:SetPoint("CENTER", 0, 0)
		applySafeFont(whBtn.fs, 10, "semibold")
		whBtn.fs:SetText("WH")
		do
			local wc = getPal().textSecondary
			if wc then whBtn.fs:SetTextColor(wc[1], wc[2], wc[3], wc[4] or 0.8) end
		end
		ns.Theme.RegisterWidget(whBtn, function()
			local pal = getPal()
			if whBtn.surface and whBtn.surface.UpdateTheme then whBtn.surface:UpdateTheme(pal.glassFill, false) end
			if whBtn.hl and pal.glassHover then whBtn.hl:SetColorTexture(pal.glassHover[1], pal.glassHover[2], pal.glassHover[3], pal.glassHover[4] or 0.08) end
			if whBtn.fs and pal.textSecondary then whBtn.fs:SetTextColor(pal.textSecondary[1], pal.textSecondary[2], pal.textSecondary[3], pal.textSecondary[4] or 0.8) end
		end)
		whBtn:Hide()

		whBtn:SetScript("OnEnter", function(self)
			local d = r.data
			local orig = (d and d._orig) or d
			local ca = (d and d.craftAbility) or (orig and orig.craftAbility)
			if not ca or not ca.wowheadURL then return end
			GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
			GameTooltip:AddLine("Wowhead Forever — Recipe Source", 1, 0.82, 0)
			GameTooltip:AddDoubleLine("Recipe / Spell:", ca.wowheadLabel or ca.recipeName or "Recipe", 0.85, 0.85, 0.85, 1, 1, 1)
			GameTooltip:AddDoubleLine("Where to Get:", ca.howDetail or ca.howShort or "—", 0.85, 0.85, 0.85, 0.55, 0.9, 1)
			GameTooltip:AddDoubleLine("Wowhead URL:", ca.wowheadURL, 0.85, 0.85, 0.85, 0.45, 1, 0.65)
			GameTooltip:AddLine(" ")
			GameTooltip:AddLine("Click: open Wowhead Forever link to copy (Ctrl+C)", 1, 0.82, 0.35)
			GameTooltip:Show()
		end)
		whBtn:SetScript("OnLeave", GameTooltip_Hide)
		whBtn:SetScript("OnClick", function()
			local d = r.data
			local orig = (d and d._orig) or d
			local ca = (d and d.craftAbility) or (orig and orig.craftAbility)
			if ca and ca.wowheadURL then
				app.openWowheadPopup(ca, (orig and orig.name) or (d and d.sortName), (orig and orig.icon) or (d and d.icon))
			end
		end)
		cBtn.whBtn = whBtn

		if showRowTooltipFn then
			cBtn:SetScript("OnEnter", function(self)
				if r.data then showRowTooltipFn(self, r.data) end
			end)
			cBtn:SetScript("OnLeave", GameTooltip_Hide)
		end
		cBtn:SetScript("OnClick", function(_, mouseBtn)
			local d = r.data
			if not d then return end
			local orig = d._orig or d
			local ca = d.craftAbility or (orig and orig.craftAbility)
			if ca and not ca.ableToCraft then
				if atAH() and ca.recipeItemID and ca.acqType ~= "camp" and not (IsShiftKeyDown and IsShiftKeyDown()) then
					local rName = ns.ItemName(ca.recipeItemID, ca.recipeName)
					if rName and rName ~= "" then
						app.searchAH(rName, 1, ca.recipeItemID)
						return
					end
				end
				if ca.wowheadURL and app.openWowheadPopup(ca, (orig and orig.name) or d.sortName, (orig and orig.icon) or d.icon) then
					return
				end
			end
			if onFallbackClickFn then onFallbackClickFn(d, mouseBtn, r) end
		end)
		return cBtn
	end

	bindAbleCell = function(cBtn, ca, fallbackText)
		local showWH = (ca ~= nil and not ca.ableToCraft and ca.wowheadURL ~= nil)
		cBtn.whBtn:SetShown(showWH)
		cBtn.fs:ClearAllPoints()
		cBtn.fs:SetPoint("LEFT", cBtn, "LEFT", 0, 0)
		cBtn.fs:SetPoint("RIGHT", cBtn, "RIGHT", showWH and -32 or 0, 0)
		cBtn.fs:SetText(themeText(fallbackText or (ca and ca.cellText) or (palHex("hexMuted", "98989d") .. "—|r")))
	end
end

function app.clickRecipeQuickLook(self, mouseBtn)
	local d = self.data
	if not d or (mouseBtn and mouseBtn ~= "LeftButton") then return end
	if IsShiftKeyDown and IsShiftKeyDown() then
		if d.itemID then app.searchAH(d.name, 1, d.itemID) end
		return
	end
	local quickLookRow = app.buildRecipeQuickLookRow(d)
	if quickLookRow and app.openQuickLook("recipe", quickLookRow, { owner = self }) and atAH() then
		app.searchAH(quickLookRow.name, 1, quickLookRow.outputItemID, { silentNoAH = true, coalesce = true })
	end
end

