function app.createResetFiltersButton(parent, key, method)
	local button = ns.Theme.CreatePlateButton(parent, "Reset Filters", 106, 24, { variant = "secondary", pill = true, fontSize = 11 })
	button:SetScript("OnClick", function() app[method]() end)
	app.ui[key] = button
	return button
end

function app.createFiltersButton(parent, key, anchorBtn, alignLeft)
	local button = ns.Theme.CreatePlateButton(parent, "Filters", 78, 24, {
		variant = "secondary",
		pill = true,
		fontSize = 11,
		icon = ns.Theme.ASSETS and ns.Theme.ASSETS.icon_bars,
		iconSize = 11,
	})
	if anchorBtn then
		if alignLeft then
			button:SetPoint("LEFT", anchorBtn, "RIGHT", 6, 0)
		else
			button:SetPoint("RIGHT", anchorBtn, "LEFT", -6, 0)
		end
	end
	button:SetScript("OnClick", function(self)
		if app.toggleScreenFilters then app.toggleScreenFilters(self, alignLeft) end
	end)
	button:SetScript("OnEnter", function(self)
		GameTooltip:SetOwner(self, "ANCHOR_TOP")
		GameTooltip:AddLine("Filters", 1, 0.82, 0)
		GameTooltip:AddLine("Open the filters that apply to this screen (Professions, Show, Sources, Craft, Demand, Sub-Mats & screen options).", 1, 1, 1, true)
		GameTooltip:Show()
	end)
	button:SetScript("OnLeave", GameTooltip_Hide)
	if key then app.ui[key] = button end
	return button
end

