	-- Warcraft skins (custom skins only; Standard keeps every extra texture hidden): painted bento
	-- header plate + metallic perimeter, framed real item icons in the glyph-badge slot, CTA plate.
	local dashSkin = {}
	local DASH_ICON_FALLBACK = "Interface\\Icons\\INV_Misc_QuestionMark"
	function dashSkin.active()
		return ns.Theme.IsCustomSkin and ns.Theme.IsCustomSkin() and getPal().frameBorder ~= nil
	end
	function dashSkin.asset(name)
		return ns.Theme.GetSkinAsset(ns.Theme.GetSkin(), name)
	end
	-- Adds `row.icon` (28px, created when missing) centred inside a `socket` frame texture
	-- (row.iconSocket) at the slot of the row's glyph badge (16px from the left edge).
	function dashSkin.attachIcon(row, glyphSize, group, index)
		row._dashGroup, row._dashIndex = group, index
		row._dashStandardHeight = row:GetHeight()
		row._dashStandardPoints = {}
		for i = 1, row:GetNumPoints() do row._dashStandardPoints[i] = { row:GetPoint(i) } end
		row._dashStandardSep = row.sep and row.sep:IsShown()
		row.skinFill = row:CreateTexture(nil, "BACKGROUND", nil, 2)
		row.skinFill:SetAllPoints(row)
		row.skinFill:Hide()
		row.skinEdges = {}
		for _, side in ipairs({ "top", "bottom", "left", "right" }) do
			local edge = row:CreateTexture(nil, "BORDER")
			if side == "top" or side == "bottom" then
				local anchor = side == "top" and "TOP" or "BOTTOM"
				edge:SetPoint(anchor .. "LEFT", row, anchor .. "LEFT", 0, 0)
				edge:SetPoint(anchor .. "RIGHT", row, anchor .. "RIGHT", 0, 0)
				edge:SetHeight(1)
			else
				local anchor = side == "left" and "LEFT" or "RIGHT"
				edge:SetPoint("TOP" .. anchor, row, "TOP" .. anchor, 0, 0)
				edge:SetPoint("BOTTOM" .. anchor, row, "BOTTOM" .. anchor, 0, 0)
				edge:SetWidth(1)
			end
			edge:Hide()
			row.skinEdges[#row.skinEdges + 1] = edge
		end
		local sockSize = 30
		local sock = row:CreateTexture(nil, "ARTWORK", nil, 2)
		sock:SetSize(sockSize, sockSize)
		sock:SetPoint("LEFT", row, "LEFT", 16 + math.floor((glyphSize - sockSize) / 2), 0)
		sock:Hide()
		row.iconSocket = sock
		if not row.icon then
			row.icon = row:CreateTexture(nil, "ARTWORK")
		end
		row.icon:ClearAllPoints()
		row.icon:SetSize(sockSize - 2, sockSize - 2)
		row.icon:SetPoint("CENTER", sock, "CENTER", 0, 0)
		row.icon:Hide()
	end
	-- Swaps icon+socket (custom skin) against the glyph badge (Standard) on one row.
	function dashSkin.applyRow(row)
		if not row or not row.icon or not row.iconSocket then return end
		local on = dashSkin.active() and true or false
		if on then
			local pal = getPal()
			local fill, border = pal.cardAltBg, pal.cardBorder
			row.skinFill:SetColorTexture(fill[1], fill[2], fill[3], fill[4] or 1)
			for _, edge in ipairs(row.skinEdges) do edge:SetColorTexture(border[1], border[2], border[3], border[4] or 1) end
			row.icon:SetTexture(row._dashIconPath or DASH_ICON_FALLBACK)
			row.icon:SetTexCoord(0.07, 0.93, 0.07, 0.93)
			row.iconSocket:SetTexture(dashSkin.asset("socket"))
		end
		row.skinFill:SetShown(on)
		for _, edge in ipairs(row.skinEdges) do edge:SetShown(on) end
		if row.sep then row.sep:SetShown(not on and row._dashStandardSep) end
		row:ClearAllPoints()
		if on then
			local parent = row:GetParent()
			local basket = row._dashGroup == "basket"
			local count = (row._dashGroup == "crafts" or row._dashGroup == "outliers") and (parent:GetHeight() >= 280 and 5 or 4) or 4
			local headerHeight = parent.hdrBar:GetHeight()
			local available = math.max(0, parent:GetHeight() - headerHeight - 12 - (basket and 44 or 0))
			local rowHeight = math.min(39, (available - (count - 1) * 4) / count)
			local step = count > 1 and (available - rowHeight) / (count - 1) or 0
			local y = -headerHeight - 6 - (row._dashIndex - 1) * step
			row:SetPoint("TOPLEFT", parent, "TOPLEFT", 10, y)
			row:SetPoint("TOPRIGHT", parent, "TOPRIGHT", -10, y)
			row:SetHeight(math.max(28, rowHeight))
		else
			for _, point in ipairs(row._dashStandardPoints) do row:SetPoint(unpack(point)) end
			row:SetHeight(row._dashStandardHeight)
		end
		row.icon:SetShown(on)
		row.iconSocket:SetShown(on)
		if row.glyphBadge and row.glyphBadge.frame then
			row.glyphBadge.frame:SetShown(not on)
		end
	end
	function dashSkin.setIcon(row, path)
		if not row or not row.icon then return end
		row._dashIconPath = path or DASH_ICON_FALLBACK
		row.icon:SetTexture(row._dashIconPath)
		dashSkin.applyRow(row)
	end
	function dashSkin.rowIcon(row)
		local d = row.rowData or row.data or {}
		local id = row.itemID or d.outputItemID or d.itemID or d.crateID or d.writID
		local icon = d.icon or (id and ns.ItemIcon and ns.ItemIcon(id))
		if not icon and d.spellID and GetSpellTexture then icon = GetSpellTexture(d.spellID) end
		return icon
	end
	function app.refreshDashRowIcons()
		for _, rows in ipairs({ app.ui.dashCraftRows, app.ui.dashOutlierRows, app.ui.dashTurninRows, app.ui.dashBasketRows }) do
			for _, row in ipairs(rows or {}) do dashSkin.setIcon(row, dashSkin.rowIcon(row)) end
		end
	end
	app.setDashRowIcon = dashSkin.setIcon
	app.applyDashRowSkin = dashSkin.applyRow

	local function createBentoCard(titleText, seeAllTab, seeAllLabel)
		local card = CreateFrame("Frame", nil, dashClassicWrap)
