				t:SetPoint("TOPLEFT", card, "TOPLEFT", 0, 0); t:SetPoint("TOPRIGHT", card, "TOPRIGHT", 0, 0); t:SetHeight(1)
			elseif e == "bottom" then
				t:SetPoint("BOTTOMLEFT", card, "BOTTOMLEFT", 0, 0); t:SetPoint("BOTTOMRIGHT", card, "BOTTOMRIGHT", 0, 0); t:SetHeight(1)
			elseif e == "left" then
