				variant = "badge",
				pill = true,
				fontSize = 11,
				weight = "regular",
			})
			seeBtn:SetPoint("RIGHT", card.hdrBar, "RIGHT", -16, 0)
			seeBtn:SetScript("OnClick", function() app.setTab(seeAllTab) end)
			card.seeAllBtn = seeBtn
		end

		ns.Theme.RegisterWidget(card, function()
			local pal = getPal()
			if card.surface and card.surface.UpdateTheme then
				card.surface:UpdateTheme(pal.cardBg, false)
			end
			if card.hdrFs and pal.text then
				card.hdrFs:SetTextColor(pal.text[1], pal.text[2], pal.text[3], 1)
			end
			if card.subHdrSep then
				local sep = pal.glassSep or pal.separator or { 1, 1, 1, 0.08 }
				card.subHdrSep:SetColorTexture(sep[1], sep[2], sep[3], sep[4] or 0.08)
			end
			if card.subHdrTopSep then
				local sep = pal.glassSep or pal.separator or { 1, 1, 1, 0.08 }
