		topSep:SetPoint("TOPRIGHT", 0, 0)
		topSep:SetHeight(1)
		local sc = getPal().glassSep or getPal().separator or { 1, 1, 1, 0.08 }
		topSep:SetColorTexture(sc[1], sc[2], sc[3], sc[4] or 0.08)
		card.subHdrTopSep = topSep

		local sep = sub:CreateTexture(nil, "BORDER")
		sep:SetPoint("BOTTOMLEFT", 0, 0)
		sep:SetPoint("BOTTOMRIGHT", 0, 0)
		sep:SetHeight(1)
		sep:SetColorTexture(sc[1], sc[2], sc[3], sc[4] or 0.08)
		card.subHdrSep = sep

		local mc = getPal().textTertiary or getPal().textMuted
		local function mkCol(text, pt, relX, width, justify)
			local fs = sub:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
			fs:SetPoint(pt, sub, pt, relX, 0)
			if width then fs:SetWidth(width) end
			fs:SetJustifyH(justify or "RIGHT")
			fs:SetWordWrap(false)
			fs:SetText(text)
			applySafeFont(fs, 11, "regular")
			if mc then fs:SetTextColor(mc[1], mc[2], mc[3], mc[4] or 1) end
			card.colHeadLabels = card.colHeadLabels or {}
			card.colHeadLabels[#card.colHeadLabels + 1] = fs
			return fs
		end

		card.subHdrLeft = mkCol("Recipe", "LEFT", 16, 120, "LEFT")
		if showVel then
			mkCol("Demand", "RIGHT", -188, 76, "RIGHT")
			mkCol("Velocity", "RIGHT", -112, 68, "RIGHT")
