	local function createDashCardRow(parent, idx, isOutlier)
		local row = CreateFrame("Button", nil, parent)
		row:SetHeight(41)
		row:SetPoint("TOPLEFT", parent, "TOPLEFT", 0, -72 - (idx - 1) * 41)
		row:SetPoint("TOPRIGHT", parent, "TOPRIGHT", 0, -72 - (idx - 1) * 41)

		row.sep = row:CreateTexture(nil, "BORDER")
		row.sep:SetPoint("TOPLEFT", row, "TOPLEFT", 54, 0)
		row.sep:SetPoint("TOPRIGHT", row, "TOPRIGHT", 0, 0)
		row.sep:SetHeight(1)
		local sc = getPal().glassSep or getPal().separator or { 1, 1, 1, 0.08 }
		row.sep:SetColorTexture(sc[1], sc[2], sc[3], sc[4] or 0.08)
		row.sep:SetShown(idx > 1)

