		row.actBtn:SetPoint("BOTTOMRIGHT", row, "BOTTOMRIGHT", -2, 2)
		row.actBtn:SetAlpha(0)
		row.actBtn:SetScript("OnClick", function(self)
			local d = self:GetParent().data
			if not d then return end
			if isOutlier and not d.isBestKnownOption then
				app.selectedOutlierItemID = d.itemID
				if MerchantMasterDB then
					if type(d.listed) == "number" and d.listed > 2 and (MerchantMasterDB.outlierScope == nil or MerchantMasterDB.outlierScope == "monopoly" or MerchantMasterDB.outlierScope == "unlisted") then
						MerchantMasterDB.outlierScope = (d.listed <= 4) and "thin" or "all"
					end
					if d.isGoodProduct == false and (MerchantMasterDB.outlierQuality == nil or MerchantMasterDB.outlierQuality == "good") then
						MerchantMasterDB.outlierQuality = "all"
					end
				end
				app.setTab("outliers")
				if app.ui.outlierPriceInput and app.ui.outlierPriceInput.SetFocus then
					app.ui.outlierPriceInput:SetFocus()
				end
			else
				if app.addUnifiedShoppingItem then
					app.addUnifiedShoppingItem({
						key = "dash:" .. tostring(d.outputItemID or d.itemID or d.spellID or d.name or "craft"),
						name = d.name,
						itemID = d.outputItemID or d.itemID,
						spellID = d.spellID,
						prof = d.prof,
						qty = d.recDailyQty or 1,
						reagents = d.craftBreakdown,
						numMade = d.numMade or 1,
						sourceLabel = "Dashboard",
					})
				end
				if not app.sendShoppingRowsToBuyer(app.rawUnifiedShoppingRows or app.activeShoppingRows, "Shopping List") then
					app.toggleShoppingWindow(true)
				end
