			GameTooltip:AddDoubleLine("Recipe / Spell:", ca.wowheadLabel or ca.recipeName or d.name or "Recipe", 0.85, 0.85, 0.85, 1, 1, 1)
			GameTooltip:AddDoubleLine("Where to Get:", ca.howDetail or ca.howShort or "—", 0.85, 0.85, 0.85, 0.55, 0.9, 1)
