			if shown then
				row.metaFs:ClearAllPoints()
				row.metaFs:SetPoint("TOPLEFT", row, "TOPLEFT", 54, -22)
				if row.metaCheck then
					row.metaCheck:ClearAllPoints()
					row.metaCheck:SetPoint("LEFT", row.metaFs, "RIGHT", -2, 0)
					row.metaCheck:Show()
				end
				if row.metaRightFs then
					row.metaRightFs:ClearAllPoints()
					row.metaRightFs:SetPoint("LEFT", row.metaCheck, "RIGHT", 3, 0)
					row.metaRightFs:SetPoint("RIGHT", row, "RIGHT", textRight, 0)
					row.metaRightFs:Show()
				end
			else
				if row.metaCheck then row.metaCheck:Hide() end
				if row.metaRightFs then row.metaRightFs:Hide() end
				row.metaFs:ClearAllPoints()
				row.metaFs:SetPoint("TOPLEFT", row, "TOPLEFT", 54, -22)
				row.metaFs:SetPoint("RIGHT", row, "RIGHT", textRight, 0)
			end
		end

