			GameTooltip:AddLine(useOutlierTip and "Monopoly Opportunity" or (d.isBestKnownOption and "Best Known Option" or "Daily Velocity Craft"), 1, 0.82, 0)
			GameTooltip:AddDoubleLine("Profession / Skill:", d.profSkillLabel or d.profLabel or "—", 0.85, 0.85, 0.85, 1, 1, 1)
