				GameTooltip:AddDoubleLine("Demand:", d.demand.stateLabel or d.demand.heatBadge, 0.85, 0.85, 0.85, 1, 1, 1)
			end
			GameTooltip:AddDoubleLine("Current AH Qty · Sales/Day:", string.format("%s listed  ·  %s / day", d.listed ~= nil and tostring(d.listed) or "—", d.dailySold and string.format("%.1f", d.dailySold) or "—"), 0.85, 0.85, 0.85, 0.5, 0.9, 1)
			GameTooltip:AddDoubleLine("Unit Craft Cost:", ns.FormatMoneyCompact(d.craftCost), 0.85, 0.85, 0.85, 1, 1, 1)
