			GameTooltip:AddDoubleLine("Expected Profit / Day:", ns.FormatMoneyCompact(d.expectedDailyProfit, true), 1, 0.82, 0, 0.3, 1, 0.4)
			GameTooltip:AddLine("Left-click for Quick Look · Shift-click to search the AH", 0.65, 0.85, 1)
