	app.ui.dashWritPulseFs = h3Pulse2

	local turninColLabels = {}
	local turninSeps = {}
	local function mkTurninColHead(yOff, cols)
		local ch = CreateFrame("Frame", nil, turninCard)
		turninCard.columnHeaders = turninCard.columnHeaders or {}
		turninCard.columnHeaders[#turninCard.columnHeaders + 1] = ch
		ch:SetPoint("TOPLEFT", turninCard, "TOPLEFT", 0, yOff)
		ch:SetPoint("TOPRIGHT", turninCard, "TOPRIGHT", 0, yOff)
		ch:SetHeight(24)
		local sc = getPal().glassSep or getPal().separator or { 1, 1, 1, 0.08 }
		local tSep = ch:CreateTexture(nil, "BORDER")
		tSep:SetPoint("TOPLEFT", 0, 0)
		tSep:SetPoint("TOPRIGHT", 0, 0)
		tSep:SetHeight(1)
		tSep:SetColorTexture(sc[1], sc[2], sc[3], sc[4] or 0.08)
		turninSeps[#turninSeps + 1] = tSep

		local bSep = ch:CreateTexture(nil, "BORDER")
		bSep:SetPoint("BOTTOMLEFT", 0, 0)
		bSep:SetPoint("BOTTOMRIGHT", 0, 0)
		bSep:SetHeight(1)
		bSep:SetColorTexture(sc[1], sc[2], sc[3], sc[4] or 0.08)
		turninSeps[#turninSeps + 1] = bSep

		local mc = getPal().textTertiary or getPal().textMuted
		for _, c in ipairs(cols) do
			local fs = ch:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
			fs:SetPoint(c.pt, ch, c.pt, c.x, 0)
			if c.w then fs:SetWidth(c.w) end
			fs:SetJustifyH(c.just or "RIGHT")
			fs:SetWordWrap(false)
			fs:SetText(c.txt)
			applySafeFont(fs, 11, "regular")
			if mc then fs:SetTextColor(mc[1], mc[2], mc[3], mc[4] or 1) end
			turninColLabels[#turninColLabels + 1] = fs
		end
	end

