	function app.syncDashboardBasketCard()
		local sum = app.ui._basketSummary or { count = 0, spend = 0, unpriced = 0 }
		local cnt = tonumber(sum.count) or 0
		if basketCountPill and basketCountPill.SetVariant then
			basketCountPill:SetVariant("neutral", string.format("%d item%s", cnt, cnt == 1 and "" or "s"))
		end
		if basketTotalFs then
			if cnt > 0 then
				basketTotalFs:SetText(moneyText(sum.spend or 0))
			else
				basketTotalFs:SetText(zeroMoney("g"))
			end
		end
		local function rowIsVendor(sr)
			if not sr then return false end
			if sr.isVendor or sr.source == "vendor" or (type(sr.sourceLabel) == "string" and sr.sourceLabel:lower():find("vendor", 1, true)) then
				return true
			end
			if sr.itemID and ns.VENDOR_ITEMS and ns.VENDOR_ITEMS[sr.itemID] then return true end
			return false
		end
		local srcRows = app.rawUnifiedShoppingRows or app.activeShoppingRows or {}
		local seenKeys, preview = {}, {}
		for _, sr in ipairs(srcRows) do
			if not sr.isSubRow and not sr.isMainRow then
				local k = tostring(sr.itemID or sr.name or "")
				if k ~= "" then
					if seenKeys[k] then
						local ex = seenKeys[k]
						ex.qty = ex.qty + (tonumber(sr.qty or sr.rawQty or 0) or 0)
						ex.cost = (ex.cost or 0) + (tonumber(sr.groupTotalCost or sr.lineCost or 0) or 0)
					else
						local entry = {
							itemID = sr.itemID or lookupID(sr.name),
							name = sr.name or "Item",
							qty = tonumber(sr.qty or sr.rawQty or 1) or 1,
							cost = sr.groupTotalCost or sr.lineCost,
							isVendor = rowIsVendor(sr),
						}
						seenKeys[k] = entry
						preview[#preview + 1] = entry
					end
				end
			end
		end
		if #preview == 0 then
			for _, sr in ipairs(srcRows) do
				if not sr.isSubRow then
					local k = tostring(sr.itemID or sr.name or "")
					if k ~= "" and not seenKeys[k] then
						local entry = {
							itemID = sr.itemID or lookupID(sr.name),
							name = sr.name or "Item",
							qty = tonumber(sr.qty or sr.rawQty or 1) or 1,
							cost = sr.groupTotalCost or sr.lineCost,
							isVendor = rowIsVendor(sr),
						}
						seenKeys[k] = entry
						preview[#preview + 1] = entry
					end
				end
			end
		end
		for i = 1, 4 do
			local br = app.ui.dashBasketRows[i]
			local sr = preview[i]
			if sr then
				br.itemID = sr.itemID
				br.rowData = sr
				br:Show()
				if br.nameHover then br.nameHover:SetShown(sr.itemID ~= nil or sr.name ~= nil) end
				br.nameFs:SetText(sr.name)
				br.qtyFs:SetText(tostring(sr.qty) .. "x")
				br.costFs:SetText(moneyText(sr.cost))
				if br.sourcePill and br.sourcePill.SetVariant then
					br.sourcePill:SetVariant("neutral", sr.isVendor and "NPC Vendor" or "Buy AH")
				end
			else
				br.itemID = nil
				br.rowData = nil
				if br.nameHover then br.nameHover:Hide() end
				br:Hide()
			end
		end
		local customSkin = ns.Theme and ns.Theme.IsCustomSkin and ns.Theme.IsCustomSkin() or false
		if basketTotalBar then basketTotalBar:SetShown(not customSkin and #preview > 0) end
		if basketEmptyFs then basketEmptyFs:SetShown(#preview == 0) end
		if app.ui._syncSkinBasketCount then app.ui._syncSkinBasketCount() end
		if customSkin and app.refreshDashRowIcons then app.refreshDashRowIcons() end
	end

	function app.getDashboardMode()
		local db = MerchantMasterDB
		if type(db) == "table" and db.dashboardMode == "classic" then
			return "classic"
		end
		return "brief"
	end

	function app.ensureDashboardBrief()
		if app.ui.dashBriefView then return app.ui.dashBriefView end
		if not (ns.DashboardBrief and type(ns.DashboardBrief.Create) == "function") then return nil end
		local brief = ns.DashboardBrief.Create(dashboardView, {
			onModeChange = function(mode)
				if app.setDashboardMode then app.setDashboardMode(mode) end
			end,
			onOpenDeepAnalysis = function(spec, ret)
				if app.openDeepAnalysis then app.openDeepAnalysis(spec, ret) end
			end,
			onAddToCart = function(itemID, qty, name)
				if app.adjustItemShoppingQty then
					app.adjustItemShoppingQty({ itemID = itemID, name = name }, qty)
					return true
				end
				return false
			end,
			getPriceBank = function()
				return app.getUIPriceBank and app.getUIPriceBank() or nil
			end,
			getEconKey = function()
				local info = ns.CurrentEconomyInfo and ns.CurrentEconomyInfo()
				return (info and info.effectiveKey) or (ns.DetectActiveEconomy and ns.DetectActiveEconomy()) or "Normal-Horde"
			end,
		})
		app.ui.dashBriefView = brief
		return brief
	end

	function app.syncDashboardMode()
		local brief = app.ensureDashboardBrief()
		local mode = app.getDashboardMode()
		local showBrief = (mode == "brief" and brief ~= nil)
		if brief then
			brief:SetShown(showBrief)
			if brief.SetMode then brief:SetMode(mode, true) end
		end
		if app.ui.dashClassicWrap then
			app.ui.dashClassicWrap:SetShown(not showBrief)
		end
		return mode
	end

	function app.setDashboardMode(mode)
		local nextMode = (mode == "classic") and "classic" or "brief"
		if type(MerchantMasterDB) == "table" then
			MerchantMasterDB.dashboardMode = nextMode
		end
		app.syncDashboardMode()
		if panel:IsShown() and app.activeTab == "dashboard" then
			if app.layoutWindow then app.layoutWindow() end
			if app.refresh then app.refresh() end
		end
		return nextMode
	end

	ns.Theme.RegisterWidget(basketFooter, function()
		local pal = getPal()
		local sep = pal.glassSep or pal.separator or { 1, 1, 1, 0.08 }
		for _, s in ipairs(turninSeps) do
