			if tr.sep then tr.sep:SetColorTexture(sep[1], sep[2], sep[3], sep[4] or 0.08) end
			if tr.hl and pal.glassHover then tr.hl:SetColorTexture(pal.glassHover[1], pal.glassHover[2], pal.glassHover[3], pal.glassHover[4] or 0.05) end
			if tr.nameFs and pal.text then tr.nameFs:SetTextColor(pal.text[1], pal.text[2], pal.text[3], 1) end
			if tr.subFs then
				local sec = pal.textTertiary or pal.textSecondary
				if sec then tr.subFs:SetTextColor(sec[1], sec[2], sec[3], sec[4] or 1) end
			end
			if tr.pouchFs and pal.textSecondary then tr.pouchFs:SetTextColor(pal.textSecondary[1], pal.textSecondary[2], pal.textSecondary[3], 1) end
		end
		if basketTopRule then basketTopRule:SetColorTexture(sep[1], sep[2], sep[3], sep[4] or 0.08) end
		for _, br in ipairs(app.ui.dashBasketRows) do
			if br.sep then br.sep:SetColorTexture(sep[1], sep[2], sep[3], sep[4] or 0.08) end
			if br.nameFs and pal.text then br.nameFs:SetTextColor(pal.text[1], pal.text[2], pal.text[3], 1) end
			if br.qtyFs then
				local mc = pal.textTertiary or pal.textMuted
				if mc then br.qtyFs:SetTextColor(mc[1], mc[2], mc[3], mc[4] or 1) end
			end
			if br.costFs and pal.text then br.costFs:SetTextColor(pal.text[1], pal.text[2], pal.text[3], 1) end
		end
		if btSep then btSep:SetColorTexture(sep[1], sep[2], sep[3], sep[4] or 0.08) end
		if bfSep then bfSep:SetColorTexture(sep[1], sep[2], sep[3], sep[4] or 0.08) end
		if basketTotalLbl and pal.text then basketTotalLbl:SetTextColor(pal.text[1], pal.text[2], pal.text[3], 1) end
		if basketTotalFs and pal.text then basketTotalFs:SetTextColor(pal.text[1], pal.text[2], pal.text[3], 1) end
		if basketHintFs then
			local mc = pal.textTertiary or pal.textMuted
			if mc then basketHintFs:SetTextColor(mc[1], mc[2], mc[3], mc[4] or 1) end
		end
		if basketEmptyFs then
			local mc = pal.textTertiary or pal.textMuted
			if mc then basketEmptyFs:SetTextColor(mc[1], mc[2], mc[3], mc[4] or 1) end
		end
		if dashShopBtn then
			local fs = dashShopBtn._mmLabel or (dashShopBtn.GetFontString and dashShopBtn:GetFontString())
			local sc = pal.textSecondary or pal.textMuted
			if fs and fs.SetTextColor and sc then fs:SetTextColor(sc[1], sc[2], sc[3], sc[4] or 0.72) end
		end
	end)
