	ns.Theme.RegisterWidget(spreadCard, function()
		local pal = getPal()
		if spreadCard.surface and spreadCard.surface.UpdateTheme then spreadCard.surface:UpdateTheme(pal.cardBg, false) end
		if spreadSep then
			local sc = pal.glassSep or pal.separator or { 1, 1, 1, 0.08 }
			spreadSep:SetColorTexture(sc[1], sc[2], sc[3], sc[4] or 0.08)
		end
		if spreadSummaryFs and pal.text then spreadSummaryFs:SetTextColor(pal.text[1], pal.text[2], pal.text[3], 1) end
	end)

	local PROFIT_SPREAD_COLS = {
		{ key = "name",                label = "Guaranteed Seller", width = 154, minWidth = 148, align = "LEFT", hint = "High-turnover craftable item (* marks items in your diversified Daily Spread Plan)" },
		{ key = "canCraftSort",        label = "Able / How",        width = 96,  minWidth = 86, align = "LEFT", defaultAsc = false, hint = "Able to Craft status or recipe source + vendor cost (click [WH] to open Wowhead Forever recipe link)" },
		{ key = "repSort",             label = "Rep",               width = 42,  minWidth = 38, align = "LEFT", defaultAsc = true, hint = "Required faction reputation (green = met, red = required, - = none)" },
		{ key = "goodScore",           label = "Why It Sells",      width = 88,  minWidth = 78, grow = 240, align = "LEFT", defaultAsc = false, hint = "Best in Class, Writ Turn-In, Crate Mat, or high daily buyer volume" },
		{ key = "listedSort",          label = "AH",                width = 36,  minWidth = 34, align = "RIGHT", defaultAsc = true, hint = "Current quantity listed on the Auction House" },
		{ key = "dailySold",           label = "Sales/d",           width = 60,  minWidth = 56, align = "RIGHT", defaultAsc = false, hint = "Average daily units sold (Local Velocity / Region)" },
		{ key = "demandSort",          label = "Hot / Cold",        width = 72,  minWidth = 68, align = "LEFT", defaultAsc = false, hint = "Hot / Cold demand tier & Sales Ratio (Sales/Day / Current AH Qty)" },
		{ key = "craftCost",           label = "Craft",             width = 68,  minWidth = 66, align = "RIGHT", hint = "Smart per-item crafting cost ((Sub) indicates cheaper sub-craft)" },
		{ key = "ahPrice",             label = "AH Ea",             width = 64,  minWidth = 64, align = "RIGHT", defaultAsc = false, hint = "Current Auction House unit price" },
		{ key = "realizedProfit",      label = "Profit",            width = 68,  minWidth = 66, align = "RIGHT", defaultAsc = false, hint = "Realistic net profit per item after 5% AH cut & deposit risk" },
		{ key = "recDailyQty",         label = "Batch",             width = 50,  minWidth = 48, align = "RIGHT", defaultAsc = false, hint = "Recommended daily batch quantity to capture turnover without flooding" },
		{ key = "expectedDailyProfit", label = "Est./Day",          width = 72,  minWidth = 70, align = "RIGHT", defaultAsc = false, hint = "Expected daily gold profit from this craft" },
		{ key = "queuedQty",           label = "Queue",             width = 48,  minWidth = 46, align = "CENTER", defaultAsc = false, hint = "Left-Click: add batch to Spread Shopping List / Right-Click: remove" },
		{ key = "bisSort",             label = "Best",              width = 46,  minWidth = 44, align = "RIGHT", defaultAsc = false },
	}
	local function showSpreadTooltip(owner, row)
		GameTooltip:SetOwner(owner, "ANCHOR_RIGHT")
		if row.itemID and GameTooltip.SetItemByID then
			GameTooltip:SetItemByID(row.itemID)
		elseif row.itemID then
			GameTooltip:SetHyperlink("item:" .. row.itemID)
		else
			GameTooltip:AddLine(row.name or "Item", 1, 1, 1)
		end
		GameTooltip:AddLine(" ")
		GameTooltip:AddLine("Profit Spread Breakdown (" .. ns.CurrentEconomyInfo().label .. ")", 1, 0.82, 0)
		if row.inSpreadPlan then
			GameTooltip:AddLine(string.format("* Included in Top %d Daily Spread Plan (#%d)", MerchantMasterDB and MerchantMasterDB.spreadCount or 8, row.spreadRank or 1), 0.25, 1, 0.45)
		end
		GameTooltip:AddDoubleLine("Why Buyers Need It:", row.goodFull or row.goodShort or "Active Turnover", 0.85, 0.85, 0.85, 1, 1, 1)
		addRecipeRepTooltipLine(row)
		if row.craftAbility then
			GameTooltip:AddDoubleLine("Able to Craft / Source:", row.craftAbility.ableToCraft and "Yes (Learned)" or (row.craftAbility.howDetail or row.craftAbility.howShort or "—"), 0.85, 0.85, 0.85, row.craftAbility.ableToCraft and 0.25 or 1, row.craftAbility.ableToCraft and 1 or 0.82, row.craftAbility.ableToCraft and 0.35 or 0.35)
		end
		if row.cdInfo then
			local cd = row.cdInfo
			local cdScope = cd.isShared and "(Shared Alchemy Transmute CD)" or "(Independent CD)"
			if cd.onCooldown then
				GameTooltip:AddDoubleLine("Craft Cooldown:", string.format("CD: No (%s · 1/%s) %s", cd.remainingLabel or cd.windowLabel, cd.windowLabel, cdScope), 0.85, 0.85, 0.85, 1.0, 0.35, 0.35)
			elseif cd.available == true then
				GameTooltip:AddDoubleLine("Craft Cooldown:", string.format("CD: Yes (1/%s) %s", cd.windowLabel, cdScope), 0.85, 0.85, 0.85, 0.25, 1.0, 0.45)
			else
				GameTooltip:AddDoubleLine("Craft Cooldown:", string.format("1/%s Cooldown %s", cd.windowLabel, cdScope), 0.85, 0.85, 0.85, 0.72, 0.72, 0.76)
			end
		end
		GameTooltip:AddDoubleLine("Smart Unit Craft Cost:", ns.FormatMoneyCompact(row.craftCost), 0.85, 0.85, 0.85, 1, 1, 1)
		for _, rg in ipairs(row.craftBreakdown or {}) do
			local tag = rg.isVendor and "Vendor" or (rg.source or "AH")
			GameTooltip:AddDoubleLine(string.format("   · %dx %s (%s)", rg.qty, rg.name, tag), ns.FormatMoneyCompact(rg.lineCost), 0.68, 0.68, 0.68, 0.85, 0.85, 0.85)
		end
		GameTooltip:AddDoubleLine("AH Unit Price:", ns.FormatMoneyCompact(row.ahPrice), 0.85, 0.85, 0.85, 1, 1, 1)
		GameTooltip:AddDoubleLine("Realized Net Profit / Unit:", ns.FormatMoneyCompact(row.realizedProfit, true), 0.85, 0.85, 0.85, 1, 1, 1)
		GameTooltip:AddDoubleLine("AH Qty · Sales / Day:", string.format("%s listed  ·  %.1f / day", row.listed ~= nil and tostring(row.listed) or "—", row.dailySold or 0), 0.85, 0.85, 0.85, 0.5, 0.9, 1)
		if row.demand then
			GameTooltip:AddDoubleLine("Hot / Cold Demand:", row.demand.stateLabel or row.demand.heatBadge, 0.85, 0.85, 0.85, 1, 1, 1)
		end
		GameTooltip:AddDoubleLine("Recommended Daily Batch:", string.format("%dx / day -> %s / day", row.recDailyQty or 1, ns.FormatMoneyCompact(row.expectedDailyProfit, true)), 1, 0.82, 0, 0.3, 1, 0.45)
		GameTooltip:AddLine(" ")
		GameTooltip:AddLine("Left-click for Quick Look · Shift-click to search the AH", 0.65, 0.85, 1)
		if row.craftAbility and not row.craftAbility.ableToCraft and row.craftAbility.wowheadURL then
			GameTooltip:AddLine("Click [WH] on Able / How: open Wowhead Forever recipe link", 1, 0.82, 0.35)
		end
		GameTooltip:Show()
	end

	local function adjustSpreadQueue(row, mouseBtn)
		if not (MerchantMasterDB and row and row.itemID) then return end
		MerchantMasterDB.spreadQueue = MerchantMasterDB.spreadQueue or {}
		local queueKey = row.spreadQueueKey or row.itemID
		local isLongCD = row.cdInfo and (row.cdInfo.nominalSeconds or 0) >= 82800
		local step = isLongCD and 1 or math.max(1, row.recDailyQty or row.numMade or 1)
		local cur = tonumber(MerchantMasterDB.spreadQueue[queueKey]) or 0
		if mouseBtn == "RightButton" then
			local nxt = cur - step
			MerchantMasterDB.spreadQueue[queueKey] = (nxt > 0) and nxt or nil
		else
			local grp = (row.cdInfo and row.cdInfo.sharedGroup) or (ns.GetRecipeCooldownGroup and row.recipe and ns.GetRecipeCooldownGroup(row.recipe))
			if grp and ns.GetRecipeCooldownGroup then
				for otherKey, qQty in pairs(MerchantMasterDB.spreadQueue) do
					if otherKey ~= queueKey and (tonumber(qQty) or 0) > 0 then
						local otherRec = ns.ResolveSpreadQueueRecipe(otherKey)
						if otherRec and ns.GetRecipeCooldownGroup(otherRec) == grp then
							if app.ui and app.ui.toast and app.ui.toast.ShowToast then
								app.ui.toast:ShowToast("Shared Transmute cooldown already queued (" .. tostring(otherRec.name or "another Transmute") .. ")", "info")
							end
							return
						end
					end
				end
			end
			MerchantMasterDB.spreadQueue[queueKey] = isLongCD and 1 or (cur + step)
		end
		app.selectedSpreadItemID = row.itemID
		app.refresh()
	end

	app.ui.profitSpreadTable = createSortableTable(spreadCard, -44, "profit_spread", PROFIT_SPREAD_COLS, function(r, data, tbl)
		if not r.cells then
			applyRowHighlight(r)
			r.cells = {}
			for i, col in ipairs(tbl.columns) do
				if i == 1 then
					local btn = CreateFrame("Button", nil, r)
					btn:SetSize(col.width, ROW_H)
					btn:SetPoint("LEFT", r, "LEFT", tbl.colX[i], 0)
					btn.icon = btn:CreateTexture(nil, "ARTWORK")
					btn.icon:SetSize(16, 16)
					btn.icon:SetPoint("LEFT", 0, 0)
					btn.fs = btn:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
					btn.fs:SetPoint("LEFT", btn.icon, "RIGHT", 4, 0)
					btn.fs:SetPoint("RIGHT", 0, 0)
					btn.fs:SetJustifyH("LEFT")
					btn.fs:SetWordWrap(false)
					btn:SetScript("OnEnter", function(self) if self:GetParent().data then showSpreadTooltip(self, self:GetParent().data) end end)
					btn:SetScript("OnLeave", GameTooltip_Hide)
					btn:SetScript("OnClick", forwardRowClick)
					r.cells[i] = btn
				elseif i == 2 then
					r.cells[i] = createAbleCell(r, col.width, tbl.colX[i], nil, function(d)
						if d and d.itemID then app.searchAH(d.name, 1, d.itemID) end
					end)
				elseif i == 13 then
					local qBtn = CreateFrame("Button", nil, r)
					qBtn:SetSize(col.width, ROW_H - 2)
					qBtn:SetPoint("LEFT", r, "LEFT", tbl.colX[i], 0)
					qBtn:RegisterForClicks("LeftButtonUp", "RightButtonUp")
					qBtn.bg = qBtn:CreateTexture(nil, "BACKGROUND")
					qBtn.bg:SetAllPoints()
					qBtn.fs = qBtn:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
					qBtn.fs:SetAllPoints()
					qBtn.fs:SetJustifyH("CENTER")
					qBtn:SetScript("OnClick", function(self, mouseBtn) adjustSpreadQueue(self:GetParent().data, mouseBtn) end)
					r.cells[i] = qBtn
				else
					local fs = r:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
					fs:SetSize(col.width, ROW_H)
					fs:SetPoint("LEFT", r, "LEFT", tbl.colX[i], 0)
					fs:SetJustifyH(col.align)
					fs:SetWordWrap(false)
					r.cells[i] = fs
				end
			end
			r:SetScript("OnClick", app.clickRecipeQuickLook)
		end

		r.data = data
		local p = getPal()
		r.stripe:SetColorTexture(0, 0, 0, 0)

		local rankPrefix = data.inSpreadPlan and (palHex("hexMuted", "98989d") .. string.format("#%d |r", data.spreadRank or 1)) or ""
		r.cells[1].icon:SetTexture(data.icon)
		r.cells[1].fs:SetText(rankPrefix .. palHex("hexText", "ffffff") .. data.name .. "|r")
		local abilityText = data.craftAbility and data.craftAbility.cellText or (palHex("hexMuted", "98989d") .. "—|r")
		if data.cdInfo then
			if data.cdInfo.onCooldown then
				abilityText = "|cffff4245CD: No (" .. tostring(data.cdInfo.remainingLabel or data.cdInfo.windowLabel) .. ")|r"
			elseif data.cdInfo.available == true then
				abilityText = "|cff30d158CD: Yes (1/" .. tostring(data.cdInfo.windowLabel) .. ")|r"
			end
		end
		bindAbleCell(r.cells[2], data.craftAbility, abilityText)
		r.cells[3]:SetText(formatRepColumnCell(data))
		r.cells[4]:SetText(themeText(data.goodShort or (palHex("hexMuted", "98989d") .. "-|r")))
		r.cells[5]:SetText(data.listed ~= nil and (data.listed == 0 and (palHex("hexWarning", "ff9230") .. "0|r") or (palHex("hexText", "ffffff") .. tostring(data.listed) .. "|r")) or (palHex("hexMuted", "98989d") .. "-|r"))
		r.cells[6]:SetText(themeText(ns.Theme.FormatSalesPerDay(data.dailySold)))
		r.cells[7]:SetText(themeText(data.demand and data.demand.heatBadge or (palHex("hexMuted", "98989d") .. "-|r")))
		local subBadge = data.usedSubCraft and (" " .. palHex("hexPositive", "30d158") .. "(Sub)|r") or ""
		r.cells[8]:SetText(moneyText(data.craftCost) .. subBadge)
		r.cells[9]:SetText(moneyText(data.ahPrice))
		r.cells[10]:SetText(moneyText(data.realizedProfit, true))
		local isLongCD = data.cdInfo and (data.cdInfo.nominalSeconds or 0) >= 82800
		local batchLabel = isLongCD and ("1/" .. tostring(data.cdInfo.windowLabel or "24h")) or (tostring(data.recDailyQty or 1) .. "x")
		r.cells[11]:SetText(palHex("hexSecondary", "ebebf5") .. batchLabel .. "|r")
		r.cells[12]:SetText(moneyText(data.expectedDailyProfit, true))

		r.cells[14]:SetText(themeText(data.bisInfo and data.bisInfo.hasEval and data.bisInfo.cellText or "-"))

		local qBg = (p and p.glassFill) or { 1, 1, 1, 0.06 }
		if data.queuedQty and data.queuedQty > 0 then
			r.cells[13].bg:SetColorTexture(qBg[1], qBg[2], qBg[3], qBg[4] or 0.08)
			r.cells[13].fs:SetText(palHex("hexPositive", "30d158") .. "[" .. tostring(data.queuedQty) .. "x]|r")
		else
			r.cells[13].bg:SetColorTexture(qBg[1], qBg[2], qBg[3], (qBg[4] or 0.06) * 0.7)
			r.cells[13].fs:SetText(palHex("hexMuted", "98989d") .. "[+" .. tostring(data.recDailyQty or 1) .. "]|r")
		end
	end, nil, { transparentInset = true, bottomPad = 10 })
end

