	local function applyCustomOutlierPrice(copperVal)
		local id = app.selectedOutlierItemID
		if not (MerchantMasterDB and id) then return end
		MerchantMasterDB.outlierPrices = MerchantMasterDB.outlierPrices or {}
		if copperVal and copperVal > 0 then
			MerchantMasterDB.outlierPrices[id] = math.floor(copperVal + 0.5)
			priceEdit:SetText(ns.FormatMoneyEdit(MerchantMasterDB.outlierPrices[id]))
		else
			MerchantMasterDB.outlierPrices[id] = nil
		end
		app.refresh()
	end

