		end
		GameTooltip:AddLine(" ")
		GameTooltip:AddLine("Outlier Monopoly & Custom Pricing (" .. ns.CurrentEconomyInfo().label .. ")", 1, 0.82, 0)
		addRecipeRepTooltipLine(row)
		local cd = row.cdInfo
		if cd then
			local status = cd.remainingLabel and (cd.remainingLabel .. " remaining") or cd.rateLabel
			GameTooltip:AddDoubleLine(cd.sharedLabel or "Craft Cooldown", status, 0.85, 0.85, 0.85, 1, 1, 1)
		end
		GameTooltip:AddDoubleLine("Product Quality:", row.goodFull or row.goodShort or "Niche", 0.85, 0.85, 0.85, 1, 1, 1)
		if row.craftAbility then
			GameTooltip:AddDoubleLine("Able / Recipe Source:", row.craftAbility.ableToCraft and "Yes (Learned)" or (row.craftAbility.howDetail or row.craftAbility.howShort or "—"), 0.85, 0.85, 0.85, row.craftAbility.ableToCraft and 0.25 or 1, row.craftAbility.ableToCraft and 1 or 0.82, 0.35)
		end
		local outlierSalesHdr = (ns.HasSnapshots and ns.HasSnapshots()) and "AH Qty · Snapshot Sales/Day:" or "AH Qty · Est. Sales/Day:"
		GameTooltip:AddDoubleLine(outlierSalesHdr, string.format("%s  ·  %s / day", (row.listed == 0) and "UNLISTED (0)" or (tostring(row.listed or "0") .. " listed"), row.dailySold and string.format("%.2f", row.dailySold) or "—"), 0.85, 0.85, 0.85, 1, 1, 1)
		if row.demand then
			GameTooltip:AddDoubleLine("Hot / Cold Demand:", row.demand.stateLabel or row.demand.heatBadge, 0.85, 0.85, 0.85, 1, 1, 1)
		end
		GameTooltip:AddDoubleLine("Smart Unit Craft Cost:", ns.FormatMoneyCompact(row.craftCost), 0.85, 0.85, 0.85, 1, 1, 1)
		if row.lastKnownPrice then
			GameTooltip:AddDoubleLine("Last Known AH Price (" .. (row.lastKnownSource or "History") .. "):", ns.FormatMoneyCompact(row.lastKnownPrice), 0.85, 0.85, 0.85, 1, 1, 1)
		else
			GameTooltip:AddDoubleLine("Last Known AH Price:", "None recorded", 0.85, 0.85, 0.85, 0.65, 0.65, 0.65)
		end
		GameTooltip:AddDoubleLine("Suggested Monopoly Price:", ns.FormatMoneyCompact(row.suggestedPrice), 0.85, 0.85, 0.85, 0.7, 0.9, 1)
		GameTooltip:AddDoubleLine(row.isCustomPrice and "Your Custom Price (Active):" or "Target Sale Price:", ns.FormatMoneyCompact(row.targetPrice), 1, 0.82, 0, 1, 0.9, 0.4)
		GameTooltip:AddDoubleLine("Net Profit / Unit:", ns.FormatMoneyCompact(row.profit, true), 1, 0.82, 0, 1, 1, 1)
		GameTooltip:AddLine(" ")
		GameTooltip:AddLine("Left-click for Quick Look and custom pricing · Shift-click to search the AH", 0.65, 0.85, 1)
		if row.craftAbility and not row.craftAbility.ableToCraft and row.craftAbility.wowheadURL then
			GameTooltip:AddLine("Click [WH] on Able / How: open Wowhead Forever recipe link", 1, 0.82, 0.35)
		end
		GameTooltip:Show()
	end

	local function paintOutlierSelection(frame)
		local hover = getPal().glassHover
		if hover and frame.data.itemID == app.selectedOutlierItemID then
			frame.stripe:SetColorTexture(hover[1], hover[2], hover[3], hover[4] or 0.08)
		else
			frame.stripe:SetColorTexture(0, 0, 0, 0)
		end
	end

	function app.refreshOutlierSelection(row)
		local changed = row and row.itemID ~= app.selectedOutlierItemID
		app.selectedOutlierRow = row
		if row then
			app.selectedOutlierItemID = row.itemID
			selIcon:SetTexture(row.icon)
			local lastTag = row.lastKnownPrice and (" · Last AH " .. ns.FormatMoneyCompact(row.lastKnownPrice)) or ""
			selLabelFs:SetText(string.format("%s%s|r %s(Cost %s%s)|r", palHex("hexText", "ffffff"), row.name, palHex("hexMuted", "98989d"), ns.FormatMoneyCompact(row.craftCost), lastTag))
			lastAHBtn:SetEnabled(row.lastKnownPrice ~= nil and row.lastKnownPrice > 0)
			if changed or not (priceEdit.HasFocus and priceEdit:HasFocus()) then
				priceEdit:SetText(ns.FormatMoneyEdit(row.targetPrice))
			end
		else
			selIcon:SetTexture(ns.QUESTION_ICON)
			selLabelFs:SetText(palHex("hexMuted", "98989d") .. "Click any Outlier row below to set your price|r")
			lastAHBtn:SetEnabled(false)
		end
		if changed then
			app.ui.outliersTable.scrollBox:ForEachFrame(function(frame)
				if frame.data then paintOutlierSelection(frame) end
			end)
		end
	end

	app.ui.outliersTable = createSortableTable(outliersView, -42, "outliers", OUTLIER_COLS, function(r, data, tbl)
		if not r.cells then
			applyRowHighlight(r)
			r.cells = {}
			for i, col in ipairs(tbl.columns) do
				if i == 1 then
					local btn = CreateFrame("Button", nil, r)
					btn:SetSize(col.width, ROW_H)
					btn:SetPoint("LEFT", r, "LEFT", tbl.colX[i], 0)
					btn.icon = btn:CreateTexture(nil, "ARTWORK")
					btn.icon:SetSize(16, 16)
					btn.icon:SetPoint("LEFT", 0, 0)
					btn.fs = btn:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
					btn.fs:SetPoint("LEFT", btn.icon, "RIGHT", 4, 0)
					btn.fs:SetPoint("RIGHT", 0, 0)
					btn.fs:SetJustifyH("LEFT")
					btn.fs:SetWordWrap(false)
					btn:SetScript("OnEnter", function(self) if self:GetParent().data then showOutlierTooltip(self, self:GetParent().data) end end)
					btn:SetScript("OnLeave", GameTooltip_Hide)
					btn:SetScript("OnClick", forwardRowClick)
					r.cells[i] = btn
				elseif i == 2 then
					r.cells[i] = createAbleCell(r, col.width, tbl.colX[i], nil, app.refreshOutlierSelection)
				else
					local fs = r:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
					fs:SetSize(col.width, ROW_H)
					fs:SetPoint("LEFT", r, "LEFT", tbl.colX[i], 0)
					fs:SetJustifyH(col.align)
					fs:SetWordWrap(false)
					r.cells[i] = fs
				end
			end
			r:SetScript("OnClick", function(self, mouseBtn)
				local d = self.data
				if not d or (mouseBtn and mouseBtn ~= "LeftButton") then return end
				if IsShiftKeyDown and IsShiftKeyDown() and d.itemID then
					app.searchAH(d.name, 1, d.itemID)
					return
				end
				app.refreshOutlierSelection(d)
				app.openQuickLook("recipe", app.buildRecipeQuickLookRow(d), { owner = self })
			end)
		end

		r.data = data
		paintOutlierSelection(r)

		local isUnl = (data.isUnlisted == true) or (data.listed == 0)
		r.cells[1].icon:SetTexture(data.icon)
		r.cells[1].fs:SetText(palHex("hexText", "ffffff") .. data.name .. "|r")
		local abilityText = data.craftAbility and data.craftAbility.cellText or (palHex("hexMuted", "98989d") .. "—|r")
		local cd = data.cdInfo
		if cd and (cd.onCooldown or cd.available) then
			local ink = cd.onCooldown and palHex("hexDanger", "ff4245") or palHex("hexPositive", "30d158")
			abilityText = ink .. (cd.isShared and "Shared CD: " or "CD: ") .. (cd.remainingLabel or cd.windowLabel) .. "|r"
		end
		bindAbleCell(r.cells[2], data.craftAbility, abilityText)
		r.cells[3]:SetText(formatRepColumnCell(data))
		r.cells[4]:SetText(themeText(data.goodShort or (palHex("hexMuted", "98989d") .. "—|r")))
		r.cells[5]:SetText(isUnl and (palHex("hexWarning", "ff9230") .. "UNLISTED|r") or (palHex("hexText", "ffffff") .. tostring(data.listed or "—") .. "|r"))
		setCellBold(r.cells[5], isUnl)
		r.cells[6]:SetText(themeText(ns.Theme.FormatSalesPerDay(data.dailySold)))
		r.cells[7]:SetText(themeText(data.demand and data.demand.heatBadge or (palHex("hexMuted", "98989d") .. "—|r")))
		setCellBold(r.cells[7], isUnl)
		local subBadge = data.usedSubCraft and (" " .. palHex("hexPositive", "30d158") .. "(Sub)|r") or ""
		r.cells[8]:SetText(moneyText(data.craftCost) .. subBadge)
		r.cells[9]:SetText(data.lastKnownPrice and moneyText(data.lastKnownPrice) or "")
		local pPrefix = data.isCustomPrice and (palHex("hexWarning", "ff9230") .. "[Own] ") or ""
		local pSuffix = data.isCustomPrice and "|r" or ""
		r.cells[10]:SetText(pPrefix .. moneyText(data.targetPrice) .. pSuffix)
		r.cells[11]:SetText(moneyText(data.profit, true))
		r.cells[12]:SetText(data.expectedDailyProfit and moneyText(data.expectedDailyProfit, true) or (palHex("hexMuted", "98989d") .. "—|r"))
	end)
end

