	local function showCrateTooltip(owner, row, focus)
		GameTooltip:SetOwner(owner, "ANCHOR_RIGHT")
		local itemID = (focus == "crate") and row.crateID or (focus == "reagent" and row.reagentID or nil)
		suppressCratePostCall = true
		if itemID and GameTooltip.SetItemByID then
			GameTooltip:SetItemByID(itemID)
		elseif itemID then
			GameTooltip:SetHyperlink("item:" .. itemID)
		else
			GameTooltip:AddLine(row.crateFullName, row.crateQuality == 2 and 0.12 or 1, 1, row.crateQuality == 2 and 0 or 1)
		end
		suppressCratePostCall = false
		local crateInfo = (ns.IsCrateTooltipEnabled() and row.crateID) and buildCrateTooltipInfo(row.crateID) or nil
		GameTooltip:AddLine(" ")
		GameTooltip:AddLine("Waylaid Crate Breakdown (" .. ns.CurrentEconomyInfo().label .. ")", 1, 0.82, 0)
		GameTooltip:AddDoubleLine("Crate (" .. (row.crateSource or "unlisted") .. ")", crateMoneyText(row.cratePrice), 0.85, 0.85, 0.85, 1, 1, 1)
		if crateInfo and crateInfo.bundles and #crateInfo.bundles > 0 then
			appendCrateBundleLines(GameTooltip, crateInfo, true)
			if row.hasCraft and row.craftOpt then
				GameTooltip:AddDoubleLine(string.format("Option — Craft %dx (%s)", row.reagentQty, row.craftOpt.profLabel),
					row.craftEach and (crateMoneyText(row.craftEach) .. "/ea · " .. crateMoneyText(row.craftTotal)) or crateMoneyText(row.craftTotal),
					0.85, 0.85, 0.85, 0.4, 0.95, 1)
				local batches = math.ceil(row.reagentQty / math.max(1, row.craftOpt.numMade or 1))
				for _, rg in ipairs(row.craftOpt.breakdown or {}) do
					local tag = rg.isVendor and "Vendor" or (rg.source or "unlisted")
					GameTooltip:AddDoubleLine(string.format("   · %dx %s (%s)", rg.qty * batches, rg.name, tag), crateMoneyText(rg.lineCost and (rg.lineCost * batches) or nil), 0.68, 0.68, 0.68, 0.85, 0.85, 0.85)
				end
			end
		else
			GameTooltip:AddDoubleLine(string.format("Option 1 — Buy %dx %s (%s)", row.reagentQty, row.reagentName, row.buySource or "unlisted"),
				row.buyEach and (crateMoneyText(row.buyEach) .. "/ea · " .. crateMoneyText(row.buyTotal)) or crateMoneyText(row.buyTotal),
				0.85, 0.85, 0.85, 1, 1, 1)
			if row.hasCraft and row.craftOpt then
				GameTooltip:AddDoubleLine(string.format("Option 2 — Craft %dx (%s)", row.reagentQty, row.craftOpt.profLabel),
					row.craftEach and (crateMoneyText(row.craftEach) .. "/ea · " .. crateMoneyText(row.craftTotal)) or crateMoneyText(row.craftTotal),
					0.85, 0.85, 0.85, 0.4, 0.95, 1)
				local batches = math.ceil(row.reagentQty / math.max(1, row.craftOpt.numMade or 1))
				for _, rg in ipairs(row.craftOpt.breakdown or {}) do
					local tag = rg.isVendor and "Vendor" or (rg.source or "unlisted")
					GameTooltip:AddDoubleLine(string.format("   · %dx %s (%s)", rg.qty * batches, rg.name, tag), crateMoneyText(rg.lineCost and (rg.lineCost * batches) or nil), 0.68, 0.68, 0.68, 0.85, 0.85, 0.85)
				end
			end
		end
		GameTooltip:AddDoubleLine("Selected Mode:", row.mode or "Buy", 0.85, 0.85, 0.85, row.mode == "Craft" and 0.3 or 1, 0.95, row.mode == "Craft" and 1 or 0.4)
		if row.grossTotal then
			GameTooltip:AddDoubleLine("Gross Cost", crateMoneyText(row.grossTotal), 0.75, 0.75, 0.75, 0.9, 0.9, 0.9)
		end
		local rw = (row.reward and row.reward > 0) and ("-" .. crateMoneyText(row.reward)) or crateMoneyText(0)
		GameTooltip:AddDoubleLine("Quest Turn-In Reward (Cashback)", rw, 0.75, 0.95, 0.75, 0.4, 1, 0.4)
		GameTooltip:AddDoubleLine("Net Price Total", crateMoneyText(row.totalPrice), 1, 0.82, 0, 1, 1, 1)
		GameTooltip:AddDoubleLine(string.format("Merchant's Favor (%d tokens)", row.tokens), row.pricePerToken and (crateRateText(row.pricePerToken) .. "/token") or crateMoneyText(nil), 1, 0.82, 0, 0.2, 1, 0.2)
		if crateInfo then
			appendCrateRepLines(GameTooltip, crateInfo)
		end
		GameTooltip:AddDoubleLine("Sales / Day (Crate · Reagent):",
			string.format("%s / day  ·  %s / day",
				row.crateDailySold ~= nil and string.format("%.2f", row.crateDailySold) or "—",
				row.reagentDailySold ~= nil and string.format("%.1f", row.reagentDailySold) or "—"),
			0.85, 0.85, 0.85, 0.5, 0.88, 1)
		if row.profLabel ~= "" then
			GameTooltip:AddDoubleLine("Profession / Skill:", string.format("%s (%d)", row.profLabel, row.skill or 1), 0.75, 0.75, 0.75, 0.9, 0.9, 0.9)
		end
		if row.reagentOwned > 0 then
			GameTooltip:AddLine(string.format("Owned: %d/%d %s", row.reagentOwned, row.reagentQty, row.reagentName), 0.4, 0.9, 1)
		end
		GameTooltip:AddLine(" ")
		GameTooltip:AddLine(focus == "crate" and "Click: search Crate on AH" or string.format("Click: search %dx %s on AH", row.reagentQty, row.reagentName), 0.65, 0.85, 1)
		if row.hasCraft then
			GameTooltip:AddLine("Click [Mode]: toggle Craft vs Buy AH", 0.4, 1, 0.6)
		end
		GameTooltip:AddLine("Shift-Click: buy Crate + Reagents on AH", 0.65, 0.85, 1)
		if ns.Theme and ns.Theme.LiftTooltip then ns.Theme.LiftTooltip(GameTooltip) end
		GameTooltip:Show()
	end

	local function appendLeafBuyerRows(rows, breakdown, batches)
		if type(breakdown) ~= "table" or #breakdown == 0 then return end
		batches = math.max(1, tonumber(batches) or 1)
		local metaByID = {}
		local hasAllIDs = true
		local function scanMeta(list, mult)
			for _, rg in ipairs(list or {}) do
				local need = (tonumber(rg.qty) or 0) * mult
				if need > 0 then
					if rg.makeMyself and rg.craftOpt and type(rg.craftOpt.breakdown) == "table" and #rg.craftOpt.breakdown > 0 then
						local subBatches = math.ceil(need / math.max(1, tonumber(rg.craftOpt.numMade) or 1))
						scanMeta(rg.craftOpt.breakdown, subBatches)
					else
						if not rg.itemID then hasAllIDs = false end
						local rid = rg.itemID or (app.lookupID and app.lookupID(rg.name)) or (ns.ITEM_IDS_BY_NAME and ns.ITEM_IDS_BY_NAME[rg.name])
						if rid and rid > 0 then
							local m = metaByID[rid]
							if not m then
								metaByID[rid] = {
									name = rg.name or (ns.ItemName and ns.ItemName(rid)) or ("Item #" .. tostring(rid)),
									isVendor = rg.isVendor == true,
									ahUnitPrice = rg.ahUnitCost or rg.unitCost,
								}
							elseif rg.isVendor then
								m.isVendor = true
							end
						end
					end
				end
			end
		end
		scanMeta(breakdown, batches)
		if hasAllIDs and ns.CollectLeafReagents then
			local leafMap = ns.CollectLeafReagents(breakdown, batches, {})
			local ids = {}
			for id in pairs(leafMap) do ids[#ids + 1] = id end
			table.sort(ids)
			for _, id in ipairs(ids) do
				local qty = leafMap[id]
				local m = metaByID[id]
				if qty and qty > 0 and not (m and m.isVendor) then
					rows[#rows + 1] = {
						name = (m and m.name) or (ns.ItemName and ns.ItemName(id)) or ("Item #" .. tostring(id)),
						itemID = id,
						qty = qty,
						ahUnitPrice = m and m.ahUnitPrice or nil,
					}
				end
			end
			return
		end
		local byID = {}
		local order = {}
		local function collectFlat(list, mult)
			for _, rg in ipairs(list or {}) do
				local need = (tonumber(rg.qty) or 0) * mult
				if need > 0 then
					if rg.makeMyself and rg.craftOpt and type(rg.craftOpt.breakdown) == "table" and #rg.craftOpt.breakdown > 0 then
						local subBatches = math.ceil(need / math.max(1, tonumber(rg.craftOpt.numMade) or 1))
						collectFlat(rg.craftOpt.breakdown, subBatches)
					elseif not rg.isVendor then
						local rid = rg.itemID or (app.lookupID and app.lookupID(rg.name)) or (ns.ITEM_IDS_BY_NAME and ns.ITEM_IDS_BY_NAME[rg.name])
						if rid and rid > 0 then
							if not byID[rid] then
								byID[rid] = {
									name = rg.name or (ns.ItemName and ns.ItemName(rid)) or ("Item #" .. tostring(rid)),
									itemID = rid,
									qty = need,
									ahUnitPrice = rg.ahUnitCost or rg.unitCost,
								}
								order[#order + 1] = rid
							else
								byID[rid].qty = byID[rid].qty + need
							end
						elseif rg.name then
							rows[#rows + 1] = { name = rg.name, qty = need, ahUnitPrice = rg.ahUnitCost or rg.unitCost }
						end
					end
				end
			end
		end
		collectFlat(breakdown, batches)
		for _, rid in ipairs(order) do
			rows[#rows + 1] = byID[rid]
		end
	end
	app._appendLeafBuyerRows = appendLeafBuyerRows

	local function searchCratePair(row)
		local rows = {
			{
				name = ns.ItemName(row.crateID, row.crateFullName),
				itemID = row.crateID or (app.lookupID and app.lookupID(row.crateFullName)) or (ns.ITEM_IDS_BY_NAME and ns.ITEM_IDS_BY_NAME[row.crateFullName]),
				qty = 1,
				ahUnitPrice = row.cratePrice,
			},
		}
		if row.mode == "Craft" and row.craftOpt and row.craftOpt.breakdown and #row.craftOpt.breakdown > 0 then
			local batches = math.ceil(row.reagentQty / math.max(1, row.craftOpt.numMade or 1))
			appendLeafBuyerRows(rows, row.craftOpt.breakdown, batches)
		else
			local rgName = ns.ItemName(row.reagentID, row.reagentName)
			rows[#rows + 1] = {
				name = rgName,
				itemID = row.reagentID or (app.lookupID and app.lookupID(rgName)) or (ns.ITEM_IDS_BY_NAME and ns.ITEM_IDS_BY_NAME[rgName]),
				qty = row.reagentQty,
				ahUnitPrice = row.buyEach,
			}
		end
		return app.sendShoppingRowsToBuyer(rows, row.crateFullName or "Waylaid Crate")
	end

	app.ui.cratesTable = createSortableTable(cratesCard, -46, "crates", CRATE_COLS, function(r, data, tbl)
		if not r.cells then
			applyRowHighlight(r)
			r.cells = {}
			for i, col in ipairs(tbl.columns) do
				if i == 1 or i == 2 then
					local btn = CreateFrame("Button", nil, r)
					btn:SetSize(col.width, ROW_H)
					btn:SetPoint("LEFT", r, "LEFT", tbl.colX[i], 0)
					btn.icon = btn:CreateTexture(nil, "ARTWORK")
					btn.icon:SetSize(16, 16)
					btn.icon:SetPoint("LEFT", 0, 0)
					btn.fs = btn:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
					btn.fs:SetPoint("LEFT", btn.icon, "RIGHT", 4, 0)
					btn.fs:SetPoint("RIGHT", 0, 0)
					btn.fs:SetJustifyH("LEFT")
					btn.fs:SetWordWrap(false)
					local focus = (i == 1) and "crate" or "reagent"
					btn:SetScript("OnEnter", function(self)
						if self:GetParent().data then showCrateTooltip(self, self:GetParent().data, focus) end
					end)
					btn:SetScript("OnLeave", GameTooltip_Hide)
					btn:SetScript("OnClick", function(self, mouseBtn)
						local row = self:GetParent().data
						if not row then return end
						local shiftHeld = IsShiftKeyDown and IsShiftKeyDown()
						if shiftHeld then
							local id = focus == "crate" and row.crateID or row.reagentID
							if app.tryQuickLookChatLink(id) or searchCratePair(row) then return end
						end
						if focus == "crate" and mouseBtn == "LeftButton" and not shiftHeld
							and not (IsModifierKeyDown and IsModifierKeyDown()) then
							local hud = app.openQuickLook("crate", row, { owner = self:GetParent() })
							if hud then
								app.searchAH(row.crateFullName, 1, row.crateID, { silentNoAH = true, coalesce = true })
							end
							return
						elseif focus == "crate" then
							app.searchAH(row.crateFullName, 1, row.crateID)
						else
							app.searchAH(row.reagentName, row.reagentQty, row.reagentID)
						end
					end)
					r.cells[i] = btn
				elseif i == 3 then
					local mBtn = CreateFrame("Button", nil, r)
					mBtn:SetSize(col.width, ROW_H)
					mBtn:SetPoint("LEFT", r, "LEFT", tbl.colX[i], 0)
					mBtn:RegisterForClicks("LeftButtonUp", "RightButtonUp")
					mBtn.fs = mBtn:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
					mBtn.fs:SetAllPoints()
					mBtn.fs:SetJustifyH("CENTER")
					mBtn:SetScript("OnClick", function(self, mouseBtn)
						local row = self:GetParent().data
						if row and row.hasCraft then
							toggleSubCraftOverride(row.reagentID, row.mode == "Craft", mouseBtn)
						end
					end)
					r.cells[i] = mBtn
				else
					local fs = r:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
					fs:SetSize(col.width, ROW_H)
					fs:SetPoint("LEFT", r, "LEFT", tbl.colX[i], 0)
					fs:SetJustifyH(col.align)
					fs:SetWordWrap(false)
					r.cells[i] = fs
				end
			end
			r:SetScript("OnClick", function(self, mouseBtn)
				local row = self.data
				if not row then return end
				if IsShiftKeyDown and IsShiftKeyDown() then
					if app.tryQuickLookChatLink(row.crateID) or searchCratePair(row) then return end
				end
				if mouseBtn == "LeftButton" and not (IsShiftKeyDown and IsShiftKeyDown()) then
					app.openQuickLook("crate", row, { owner = self })
					return
				end
				app.searchAH(row.reagentName, row.reagentQty, row.reagentID)
			end)
		end

		r.data = data
		r.stripe:SetColorTexture(0, 0, 0, 0)

		local cCol = (data.crateQuality == 2) and palHex("hexPositive", "30d158") or palHex("hexText", "ffffff")
		r.cells[1].icon:SetTexture(data.crateIcon)
		r.cells[1].fs:SetText(cCol .. data.crateName .. "|r")

		local badge = ""
		if data.reagentOwned >= data.reagentQty then
			badge = " " .. palHex("hexPositive", "30d158") .. "(Ready)|r"
		elseif data.reagentOwned > 0 then
			badge = " " .. palHex("hexMuted", "98989d") .. string.format("(%d)|r", data.reagentOwned)
		end
		r.cells[2].icon:SetTexture(data.reagentIcon)
		r.cells[2].fs:SetText(palHex("hexText", "ffffff") .. data.reagentName .. "|r" .. badge)

		local modeTxt = (data.mode == "Craft") and (palHex("hexBlue", "0091ff") .. "Craft|r")
			or ((data.mode == "Buy") and (data.hasCraft and (palHex("hexWarning", "ff9230") .. "Buy*|r") or (palHex("hexWarning", "ff9230") .. "Buy|r")) or (palHex("hexMuted", "98989d") .. "—|r"))
		r.cells[3].fs:SetText(modeTxt)

		local fIcon = favorIconMarkup()
		r.cells[4]:SetText(tostring(data.tokens) .. (data.unconfirmed and (palHex("hexMuted", "98989d") .. "*|r") or "") .. (fIcon ~= "" and (" " .. fIcon) or ""))
		r.cells[5]:SetText(moneyText(data.cratePrice))
		r.cells[6]:SetText(moneyText(data.reagentEach))
		r.cells[7]:SetText(palHex("hexText", "ffffff") .. tostring(data.reagentQty) .. "|r")
		r.cells[8]:SetText(moneyText(data.reagentTotal))
		if data.reward and data.reward > 0 then
			r.cells[9]:SetText(moneyText(data.reward))
		else
			r.cells[9]:SetText(zeroMoney("c"))
		end
		r.cells[10]:SetText(moneyText(data.totalPrice))
		r.cells[11]:SetText(themeText(ns.Theme.FormatSalesPerDay(data.dailySold)))
		if data.pricePerToken ~= nil then
			local ppt = moneyText(data.pricePerToken)
			r.cells[12]:SetText(ppt)
		else
			r.cells[12]:SetText(palHex("hexMuted", "98989d") .. "—|r")
		end
	end, nil, { transparentInset = true, bottomPad = 10 })
end

