	local function createFilterButton(anchor, options, field, width, prefix)
		local btn = CreateFrame("Button", nil, forgedBar, "UIPanelButtonTemplate")
		btn:SetSize(width, 26)
		btn:SetPoint("LEFT", anchor, "RIGHT", 8, 0)
		btn:RegisterForClicks("LeftButtonUp", "RightButtonUp")
		ns.Theme.SkinButton(btn, { dropdown = true, pill = true, fontSize = 11 })
		local function selectFilter(key)
			MerchantMasterDB[field] = key
			app.refresh()
		end
		btn:SetScript("OnClick", function(self, mouseBtn)
			local db = MerchantMasterDB
			if not db then return end
			if mouseBtn == "RightButton" then
				selectFilter("all")
			else
				ns.Theme.OpenDropDown(self, options, db[field] or "all", selectFilter, width)
			end
		end)
		function btn:Sync(key)
			for _, opt in ipairs(options) do
				if key == opt.key then
					self:SetText(prefix .. opt.label)
					self:SetActive(key ~= "all")
					return
				end
			end
			self:SetText(prefix .. options[1].label)
			self:SetActive(false)
		end
		return btn
	end

