	function app.syncForgedFilters()
		local db = MerchantMasterDB or {}
		mode:SetActive(db.forgedMode or "self_funded", true)
		human:SetActive(app.isForgedHuman())
		tier:Sync(db.forgedTierFilter or "all")
		quality:Sync(tonumber(db.forgedQualityFilter) or "all")
		available:SetActive(db.forgedAvailFilter == "available")
	end

	function app.clickForgedRow(row, mouseBtn, owner)
		if not row then return end
		local crateID = row.crateID
		if mouseBtn == "RightButton" then
			return app.searchAH(ns.ItemName(crateID, row.crateFullName or row.name), 1, crateID)
		end
		if mouseBtn and mouseBtn ~= "LeftButton" then return end
		if IsShiftKeyDown and IsShiftKeyDown() then
			if app.tryQuickLookChatLink(crateID) then return end
			return app.searchAH(ns.ItemName(crateID, row.crateFullName or row.name), 1, crateID)
		end
		if (IsModifierKeyDown and IsModifierKeyDown()) or (IsControlKeyDown and IsControlKeyDown())
			or (IsAltKeyDown and IsAltKeyDown()) then return end
		return app.openQuickLook("forged", row, { owner = owner })
	end

	-- The base widths and the table's padding and gaps use 1,032px.
	local FORGED_COLS = {
		{ key = "name",        label = "Empty Crate", width = 170, minWidth = 132, align = "LEFT" },
		{ key = "tier",        label = "Tier",        width = 86,  align = "LEFT" },
		{ key = "quality",     label = "Q",           width = 32,  align = "CENTER" },
		{ key = "emptyPrice",  label = "Empty AH",    width = 84,  align = "RIGHT" },
