		{ key = "favorCost",   label = "15F Feed",    width = 81,  align = "RIGHT", hint = "Net Favor sourcing cost after feeder cashback" },
		{ key = "totalRefund", label = "Refund",      width = 81,  align = "RIGHT", defaultAsc = false, hint = "Combined feeder and Crate Return cashback" },
		{ key = "netCost",     label = "Net Cost",    width = 86,  align = "RIGHT", hint = "Empty crate plus net Favor sourcing, minus Crate Return cashback" },
		{ key = "rep",         label = "Rep",         width = 44,  align = "RIGHT", defaultAsc = false },
		{ key = "costPerRep",  label = "Cost/Rep",     width = 83,  align = "RIGHT" },
		{ key = "source",      label = "Mode",        width = 90,  align = "CENTER" },
		{ key = "queuedCount", label = "Action",      width = 76,  align = "CENTER", defaultAsc = false, hint = "Left-click to queue one turn-in. Right-click to remove one." },
	}

	local function forgedMoney(copper, signed)
		return copper ~= nil and moneyText(copper, signed) or (palHex("hexMuted") .. "—|r")
	end

	app.ui.forgedTable = createSortableTable(forgedCard, -82, "forged", FORGED_COLS, function(r, data, tbl)
		if not r.cells then
			applyRowHighlight(r)
			r.cells = {}
			for i, col in ipairs(tbl.columns) do
				if i == 1 or i == 12 then
					local btn = CreateFrame("Button", nil, r)
					btn:SetSize(col.width, ROW_H)
					btn:SetPoint("LEFT", r, "LEFT", tbl.colX[i], 0)
					btn:RegisterForClicks("LeftButtonUp", "RightButtonUp")
					btn.fs = btn:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
					btn.fs:SetJustifyH(col.align)
					btn.fs:SetWordWrap(false)
					if i == 1 then
						btn.icon = btn:CreateTexture(nil, "ARTWORK")
						btn.icon:SetSize(16, 16)
						btn.icon:SetPoint("LEFT", 0, 0)
						btn.fs:SetPoint("LEFT", btn.icon, "RIGHT", 4, 0)
						btn.fs:SetPoint("RIGHT", 0, 0)
						btn:SetScript("OnClick", forwardRowClick)
						btn:SetScript("OnEnter", function(self)
							local row = self:GetParent().data
							if not (row and row.crateID) then return end
							GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
							suppressCratePostCall = true
							if GameTooltip.SetItemByID then GameTooltip:SetItemByID(row.crateID)
							else GameTooltip:SetHyperlink("item:" .. row.crateID) end
							suppressCratePostCall = false
							if ns.AppendCrateTooltip then ns.AppendCrateTooltip(GameTooltip, row.crateID) end
							GameTooltip:Show()
						end)
						btn:SetScript("OnLeave", GameTooltip_Hide)
					else
						btn.fs:SetAllPoints()
						btn:SetScript("OnClick", function(self, mouseBtn)
							app.adjustForgedTurnInQueue(self:GetParent().data, mouseBtn == "RightButton" and -1 or 1)
						end)
					end
					r.cells[i] = btn
				else
					local fs = r:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
					fs:SetSize(col.width, ROW_H)
					fs:SetPoint("LEFT", r, "LEFT", tbl.colX[i], 0)
					fs:SetJustifyH(col.align)
					fs:SetWordWrap(false)
					r.cells[i] = fs
				end
			end
			r:RegisterForClicks("LeftButtonUp", "RightButtonUp")
			r:SetScript("OnClick", function(self, mouseBtn) app.clickForgedRow(self.data, mouseBtn, self) end)
		end

		r.data = data
		setRowStripe(r, "zebra", data.rowIndex)
		local dash = palHex("hexMuted") .. "—|r"
		r.cells[1].icon:SetTexture(data.icon or data.crateIcon or ns.CRATE_ICON)
		r.cells[1].fs:SetText(data.shortName or data.crateName or data.name or "Empty Crate")
		r.cells[2]:SetText(data.tier or dash)
		r.cells[3]:SetText(data.quality and ("Q" .. data.quality) or dash)
		r.cells[4]:SetText(forgedMoney(data.emptyPrice))
		r.cells[5]:SetText(data.emptyAhQty ~= nil and formatComma(data.emptyAhQty) or dash)
		r.cells[6]:SetText(forgedMoney(data.forgedMode == "banked" and 0 or data.favorCost, "cost"))
		r.cells[7]:SetText(forgedMoney(data.totalRefund))
		r.cells[8]:SetText(forgedMoney(data.netCost, "cost"))
		r.cells[9]:SetText(data.rep and (palHex("hexBlue") .. "+" .. formatComma(data.rep) .. "|r") or dash)
		r.cells[10]:SetText(forgedMoney(data.costPerRep, "cost"))
		r.cells[11]:SetText(data.source or dash)
		local queued = data.queuedCount or 0
		r.cells[12].fs:SetText(palHex(queued > 0 and "hexPositive" or "hexBlue")
			.. (queued > 0 and string.format("[%dx]", queued) or "+ Queue") .. "|r")
	end, nil, { transparentInset = true, bottomPad = 10 })

	function app.refreshForgedView(opts, scanBanner)
		app.syncForgedFilters()
		local result = ns.BuildForgedDeliveryRows and ns.BuildForgedDeliveryRows(opts) or {}
		local rows = result.rows or {}
		local rowsByID = {}
		for _, row in ipairs(rows) do
			row.queuedCount = app.getForgedQueuedCount(row)
			if row.crateID then rowsByID[row.crateID] = row end
		end
		local st = app.sortState.forged
		ns.SortRows(rows, st.col, st.asc, "costPerRep", { name = true, tier = true, source = true })
		app.ui.forgedTable.updateHeaders()
		app.ui.forgedTable.setRows(rows)
		app.quickLookRows = app.quickLookRows or {}
		app.quickLookRows.forged = rows

		local receipt = ns.FORGED_RECEIPT or {}
		local favorRequired = result.favorRequired or receipt.favorCost or 15
		local refund = result.forgedRefund or receipt.refundCopper or 100
		local baseRep = result.baseRep or receipt.baseRep or 50
		local repMult = result.repMult or (ns.GetRacialRepMultiplier and ns.GetRacialRepMultiplier(app.isForgedHuman())) or 1.0
		local effectiveRep = result.effectiveRep or math.floor(baseRep * repMult + 0.5)
		local bestSelfRow, bestFavor, bestBankedRow = result.bestSelfFunded, result.bestFavorCrate, result.bestBanked
		forgedKpi1:SetData({
			value = forgedMoney(bestSelfRow and bestSelfRow.selfFundedCostPerRep, "cost"), unit = "/ rep",
			sub = bestSelfRow and ((bestSelfRow.shortName or bestSelfRow.crateName or bestSelfRow.name or "Crate")
				.. " · " .. forgedMoney(bestSelfRow.selfFundedNetCost, "cost") .. " / turn-in") or "No priced self-funded crates",
			valueColor = false,
		})
		local feederRate = bestFavor and (bestFavor.pricePerToken or bestFavor.costPerFavor)
		local tokens = bestFavor and bestFavor.tokens
		local reward = bestFavor and bestFavor.reward
		local feederCashback = tokens and tokens > 0 and reward and (favorRequired * (reward / tokens)) or 0
		forgedKpi2:SetData({
			value = forgedMoney(feederRate, "cost"), unit = "/ F",
			sub = feederRate and string.format("%s · %dF %s · +%s back",
				bestFavor.crateName or bestFavor.name or "Crate", favorRequired,
				forgedMoney(favorRequired * feederRate, "cost"), moneyText(feederCashback)) or "No priced Favor feeder",
			valueColor = false,
		})
		forgedKpi3:SetData({
			value = forgedMoney(bestBankedRow and bestBankedRow.bankedCostPerRep, "cost"), unit = "/ rep",
			sub = bestBankedRow and string.format("%s · %s - %s = %s",
				bestBankedRow.shortName or bestBankedRow.crateName or bestBankedRow.name or "Crate",
				forgedMoney(bestBankedRow.emptyPrice), moneyText(refund), forgedMoney(bestBankedRow.bankedNetCost, "cost")) or "No priced empty crates",
			valueColor = false,
		})

		local queued = app.getForgedQueuedCount()
		summary:SetText(string.format("Friendly+ · %dF -> +%d Rep + %s Cashback%s", favorRequired, effectiveRep,
			moneyText(refund), queued > 0 and (" · " .. formatComma(queued) .. " queued") or ""))
		app.ui.statusText:SetText(scanBanner or (ns.BuildForgedDeliveryRows
			and string.format("%d crates · %d priced", #rows, result.meta and result.meta.availableCount or 0)
			or "Forged delivery pricing is unavailable"))
		return rowsByID
	end
end

---------------------------------------------------------------------------------------------------
-- Reputation Sub-View 1: Craftsman's Writs (~40s Writ Pouch Refund + Turn-In Area Filtering & Multi-Buy)

do
	local writsView = CreateFrame("Frame", nil, mainArea)
	writsView:SetPoint("TOPLEFT", 0, 0)
	writsView:SetPoint("BOTTOMRIGHT", 0, 0)
	writsView:Hide()
	app.ui.writsView = writsView

	-- Top 32px Area & Pouch Summary Bar + [Queue Area Writs] + [Shopping List]
	local writAreaBar = CreateFrame("Frame", nil, writsView)
	writAreaBar:SetPoint("TOPLEFT", 0, 0)
	writAreaBar:SetPoint("TOPRIGHT", 0, 0)
	writAreaBar:SetHeight(36)
	writAreaBar.surface = ns.Theme.NineApple(writAreaBar, "glass_r10", getPal().cardBg, false, { noSpecular = true })

	local writsShopBtn = ns.Theme.CreatePlateButton(writAreaBar, "Shopping List", 118, 24, { variant = "secondary", pill = true, fontSize = 11 })
	writsShopBtn:SetPoint("RIGHT", -8, 0)
	writsShopBtn:SetScript("OnClick", function()
		if app.toggleShoppingWindow then app.toggleShoppingWindow(true) end
	end)
	app.ui.writsShopBtn = writsShopBtn

	local queueAreaWritsBtn = ns.Theme.CreatePlateButton(writAreaBar, "Queue Area Writs", 142, 24, { variant = "secondary", pill = true, fontSize = 11 })
	queueAreaWritsBtn:SetPoint("RIGHT", writsShopBtn, "LEFT", -6, 0)
	queueAreaWritsBtn:SetScript("OnClick", function()
		if not MerchantMasterDB then return end
		local zf = MerchantMasterDB.writZoneFilter or "all"
		if zf == "all" or zf == "mapped" or zf == "unmapped" then
			say("Pick a Turn-In Area first (Left Sidebar 'Area' dropdown or click any Turn-In Area cell) to queue that zone's Writs.")
			return
		end
		MerchantMasterDB.writTurnInQueue = MerchantMasterDB.writTurnInQueue or {}
		local queuedAny = false
		for _, r in ipairs(app.lastVisibleWritRows or {}) do
			if r.writID and r.totalPrice ~= nil then
				MerchantMasterDB.writTurnInQueue[r.writID] = math.max(1, tonumber(MerchantMasterDB.writTurnInQueue[r.writID]) or 1)
				queuedAny = true
			end
		end
		if not queuedAny then
			say("No priced Craftsman's Writs found in " .. tostring(zf) .. ".")
			return
		end
		app.refresh()
		if app.toggleShoppingWindow then app.toggleShoppingWindow(true) end
	end)
	queueAreaWritsBtn:SetScript("OnEnter", function(self)
		GameTooltip:SetOwner(self, "ANCHOR_TOP")
		GameTooltip:AddLine("Queue All Visible / Area Writs for Multi-Buy", 1, 0.82, 0)
		GameTooltip:AddLine("Adds all priced Craftsman's Writs in your currently selected Turn-In Area (e.g. Alterac Mountains, Ashenvale, Hillsbrad Foothills, Duskwood, etc.) into the Shopping List so you can buy every Writ + Turn-In Item in one AH trip and turn them all in together!", 1, 1, 1, true)
		GameTooltip:Show()
	end)
	queueAreaWritsBtn:SetScript("OnLeave", GameTooltip_Hide)
	app.ui.queueAreaWritsBtn = queueAreaWritsBtn
	local writsResetBtn = app.createResetFiltersButton(writAreaBar, "writsResetBtn", "resetWritsFilters")
	writsResetBtn:SetPoint("RIGHT", queueAreaWritsBtn, "LEFT", -6, 0)
	local writsFiltersBtn = app.createFiltersButton(writAreaBar, "writsFiltersBtn", writsResetBtn)

	local writsSummaryFs = writAreaBar:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
	writsSummaryFs:SetPoint("LEFT", 16, 0)
	writsSummaryFs:SetPoint("RIGHT", writsFiltersBtn, "LEFT", -8, 0)
	writsSummaryFs:SetJustifyH("LEFT")
	writsSummaryFs:SetWordWrap(false)
	applySafeFont(writsSummaryFs, 12, "regular")
	ns.Theme.AutoThemeText(writsSummaryFs)
	app.ui.writsSummaryFs = writsSummaryFs
	ns.Theme.RegisterWidget(writAreaBar, function()
		local pal = getPal()
		if writAreaBar.surface and writAreaBar.surface.UpdateTheme then writAreaBar.surface:UpdateTheme(pal.cardBg, false) end
		if writsSummaryFs and pal.text then writsSummaryFs:SetTextColor(pal.text[1], pal.text[2], pal.text[3], 1) end
	end)

	-- 13 cols: 4 + (126+126+104+36+80+36+66+82+66+54+72+72+54) + 12*5 = 1038 <= 1048
	local WRIT_COLS = {
		{ key = "writName",      label = "Writ Name",    width = 126, align = "LEFT",   hint = "Craftsman's Writ quest item (Click to search Writ on AH)" },
		{ key = "reqItemName",   label = "Turn-In Item", width = 126, align = "LEFT",   hint = "Crafted/bought item required to complete the Writ (Click to search on AH)" },
		{ key = "zone",          label = "Turn-In Area", width = 104, align = "LEFT",   hint = "Turn-In Zone & NPC (Left-Click cell to filter to this Area · Right-Click to reset to All Zones)" },
		{ key = "cdSort",        label = "CD",           width = 36,  align = "CENTER", defaultAsc = true, hint = "Daily repeatable quest cooldown. R = Ready today · <H>h or <M>m = time until daily quest reset." },
		{ key = "profSkillSort", label = "Prof / Skill", width = 80,  align = "LEFT",   hint = "Profession & skill rank needed to craft the turn-in item yourself" },
		{ key = "rep",           label = "Rep",          width = 36,  align = "RIGHT",  defaultAsc = false, hint = "Reputation earned (+75 / +125 / +200)" },
		{ key = "writPrice",     label = "Writ AH",      width = 66, minWidth = 92,  align = "RIGHT",  hint = "AH price of the Craftsman's Writ scroll" },
		{ key = "mode",          label = "Item Cost",    width = 82, minWidth = 92,  align = "RIGHT",  hint = "Cheaper fulfillment method (Craft vs Buy) & item cost" },
		{ key = "grossTotal",    label = "Gross",        width = 66, minWidth = 92,  align = "RIGHT",  hint = "Upfront AH spend (Writ Scroll + Turn-In Item/Mats) before opening Coin Pouch" },
		{ key = "pouchRefund",   label = "Pouch",        width = 54, minWidth = 92,  align = "RIGHT",  defaultAsc = false, hint = "Tiered Coin Pouch cashback on turn-in (Journeyman +75: 35s 36c · Expert +125 / Artisan +200: 74s 80c)" },
		{ key = "totalPrice",    label = "Net Total",    width = 72, minWidth = 92,  align = "RIGHT",  hint = "Net Cost = Gross - Coin Pouch (<= 0 means Free or Net-Profitable Reputation!)" },
		{ key = "pricePerRep",   label = "Net / Rep",    width = 72, minWidth = 92,  align = "RIGHT",  hint = "Net Total divided by Reputation gained" },
		{ key = "queuedCount",   label = "[+ Buy]",      width = 54,  align = "CENTER", defaultAsc = false, hint = "Left-Click: add Writ + Turn-In Item to Area Shopping List · Right-Click: remove" },
	}

	local function showWritTooltip(owner, row, focus)
		GameTooltip:SetOwner(owner, "ANCHOR_RIGHT")
		local itemID = (focus == "writ") and row.writID or (focus == "item" and row.reqItemID or nil)
		if itemID and GameTooltip.SetItemByID then
			GameTooltip:SetItemByID(itemID)
		elseif itemID then
			GameTooltip:SetHyperlink("item:" .. itemID)
		else
			GameTooltip:AddLine(row.writFullName, 0.12, 1, 0)
		end
		GameTooltip:AddLine(" ")
		GameTooltip:AddLine("Craftsman's Writ Breakdown (" .. ns.CurrentEconomyInfo().label .. ")", 1, 0.82, 0)
		if row.zoneHint then
			GameTooltip:AddDoubleLine("Turn-In Area:", row.zoneHint .. " (likely)", 0.85, 0.85, 0.85, 0.68, 0.68, 0.68)
		else
			GameTooltip:AddDoubleLine("Turn-In Area:", row.zone or "Unmapped", 0.85, 0.85, 0.85, 0.55, 0.88, 1)
		end
		if row.npc then
			local locStr = row.coordText and string.format("%s (%s)", row.npc, row.coordText) or row.npc
			GameTooltip:AddDoubleLine("Turn-In NPC:", locStr, 0.85, 0.85, 0.85, 1, 0.9, 0.55)
		end
		if row.cdAvailable then
			GameTooltip:AddDoubleLine("Daily Quest Cooldown:", "Ready today (resets daily)", 0.85, 0.85, 0.85, 0.2, 1, 0.3)
		elseif row.onCooldown then
			GameTooltip:AddDoubleLine("Daily Quest Cooldown:", string.format("On Cooldown (%s until daily reset)", row.cdText or "24h"), 0.85, 0.85, 0.85, 1, 0.25, 0.28)
		end
		GameTooltip:AddDoubleLine("Writ Scroll (" .. (row.writSource or "unlisted") .. ")", ns.FormatMoneyCompact(row.writPrice), 0.85, 0.85, 0.85, 1, 1, 1)
		GameTooltip:AddDoubleLine(string.format("Option 1 — Buy %dx %s (%s)", row.reqQty, row.reqItemName, row.buySource or "unlisted"), ns.FormatMoneyCompact(row.buyCost), 0.85, 0.85, 0.85, 1, 1, 1)
		GameTooltip:AddDoubleLine(string.format("Option 2 — Craft (%s)", row.profSkillLabel), ns.FormatMoneyCompact(row.craftCost), 0.85, 0.85, 0.85, 1, 1, 1)
		if row.craftAbility then
			GameTooltip:AddDoubleLine("Able to Craft / Recipe Source:", row.craftAbility.ableToCraft and "Yes (Learned)" or ("No · " .. row.craftAbility.howDetail), 0.85, 0.85, 0.85, row.craftAbility.ableToCraft and 0.2 or 1, row.craftAbility.ableToCraft and 1 or 0.82, row.craftAbility.ableToCraft and 0.2 or 0.35)
		end
		if row.craftBreakdown and #row.craftBreakdown > 0 then
			for _, rg in ipairs(row.craftBreakdown) do
				local tag = rg.isVendor and "Vendor" or (rg.source or "unlisted")
				GameTooltip:AddDoubleLine(string.format("   · %dx %s (%s)", rg.qty * row.reqQty, rg.name, tag), ns.FormatMoneyCompact(rg.lineCost and (rg.lineCost * row.reqQty) or nil), 0.68, 0.68, 0.68, 0.85, 0.85, 0.85)
			end
		end
		GameTooltip:AddDoubleLine("Selected Fulfillment Mode:", row.mode, 0.85, 0.85, 0.85, 0.4, 0.9, 1)
		GameTooltip:AddDoubleLine("Gross Upfront Spend:", ns.FormatMoneyCompact(row.grossTotal), 0.85, 0.85, 0.85, 1, 1, 1)
		local pRef = (row.pouchRefund and row.pouchRefund > 0) and ("-" .. ns.FormatMoneyCompact(row.pouchRefund)) or ns.FormatMoneyCompact(0)
		local pTier = row.pouchTier and (" (" .. row.pouchTier .. ")") or ""
		GameTooltip:AddDoubleLine("Coin Pouch Refund" .. pTier .. ":", pRef, 0.75, 0.95, 0.75, 0.35, 1, 0.45)
		GameTooltip:AddDoubleLine("Net Turn-In Cost:", ns.FormatMoneyCompact(row.totalPrice), 1, 0.82, 0, (row.totalPrice and row.totalPrice <= 0) and 0.25 or 1, 1, (row.totalPrice and row.totalPrice <= 0) and 0.35 or 1)
		GameTooltip:AddDoubleLine(string.format("Reputation Gained (+%d Rep):", row.rep), row.pricePerRep ~= nil and (ns.FormatMoneyCompact(row.pricePerRep) .. " / rep") or "—", 1, 0.82, 0, 0.2, 1, 0.2)
		GameTooltip:AddDoubleLine("Sales / Day (Writ · Turn-In):",
			string.format("%s / day  ·  %s / day",
				row.writDailySold ~= nil and string.format("%.2f", row.writDailySold) or "—",
				row.reqDailySold ~= nil and string.format("%.2f", row.reqDailySold) or "—"),
			0.85, 0.85, 0.85, 0.5, 0.88, 1)
		GameTooltip:AddLine(" ")
		GameTooltip:AddLine("Click [Turn-In Area]: filter to this Zone  ·  Right-Click: All Zones", 0.55, 0.9, 1)
		GameTooltip:AddLine("Click [+ Buy]: add Writ + Item to Shopping List  ·  Shift-Click: buy on AH", 0.65, 0.85, 1)
		GameTooltip:Show()
	end

	local function shiftSearchWrit(row)
		local rows = {
			{
				name = ns.ItemName(row.writID, row.writFullName),
				itemID = row.writID or (app.lookupID and app.lookupID(row.writFullName)) or (ns.ITEM_IDS_BY_NAME and ns.ITEM_IDS_BY_NAME[row.writFullName]),
				qty = 1,
				ahUnitPrice = row.writPrice,
			},
		}
		if row.mode == "Craft" and row.craftBreakdown and #row.craftBreakdown > 0 then
			if app._appendLeafBuyerRows then
				app._appendLeafBuyerRows(rows, row.craftBreakdown, row.reqQty)
			else
				for _, rg in ipairs(row.craftBreakdown) do
					if not rg.isVendor then
						local rid = rg.itemID or (app.lookupID and app.lookupID(rg.name)) or (ns.ITEM_IDS_BY_NAME and ns.ITEM_IDS_BY_NAME[rg.name])
						rows[#rows + 1] = { name = rg.name, itemID = rid, qty = rg.qty * row.reqQty, ahUnitPrice = rg.ahUnitCost or rg.unitCost }
					end
				end
			end
		else
			local reqID = row.reqItemID or (app.lookupID and app.lookupID(row.reqItemName)) or (ns.ITEM_IDS_BY_NAME and ns.ITEM_IDS_BY_NAME[row.reqItemName])
			local reqUnit = (row.buyCost and row.reqQty and row.reqQty > 0) and math.floor(row.buyCost / row.reqQty + 0.5) or nil
			rows[#rows + 1] = {
				name = row.reqItemName,
				itemID = reqID,
				qty = row.reqQty,
				ahUnitPrice = reqUnit,
			}
		end
		return app.sendShoppingRowsToBuyer(rows, row.writFullName or "Craftsman's Writ")
	end

	local function adjustWritTurnInQueue(row, mouseBtn)
		if not (MerchantMasterDB and row and row.writID) then return end
		MerchantMasterDB.writTurnInQueue = MerchantMasterDB.writTurnInQueue or {}
		local cur = tonumber(MerchantMasterDB.writTurnInQueue[row.writID]) or 0
		if mouseBtn == "RightButton" then
			local nxt = cur - 1
			MerchantMasterDB.writTurnInQueue[row.writID] = (nxt > 0) and nxt or nil
		else
			MerchantMasterDB.writTurnInQueue[row.writID] = cur + 1
		end
		app.refresh()
	end

	app.ui.writsTable = createSortableTable(writsView, -38, "writs", WRIT_COLS, function(r, data, tbl)
		if not r.cells then
			applyRowHighlight(r)
			r.cells = {}
			for i, col in ipairs(tbl.columns) do
				if i == 1 or i == 2 then
					local btn = CreateFrame("Button", nil, r)
					btn:SetSize(col.width, ROW_H)
					btn:SetPoint("LEFT", r, "LEFT", tbl.colX[i], 0)
					btn.icon = btn:CreateTexture(nil, "ARTWORK")
					btn.icon:SetSize(16, 16)
					btn.icon:SetPoint("LEFT", 0, 0)
					btn.fs = btn:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
					btn.fs:SetPoint("LEFT", btn.icon, "RIGHT", 4, 0)
					btn.fs:SetPoint("RIGHT", 0, 0)
					btn.fs:SetJustifyH("LEFT")
					btn.fs:SetWordWrap(false)
					local focus = (i == 1) and "writ" or "item"
					btn:SetScript("OnEnter", function(self)
						if self:GetParent().data then showWritTooltip(self, self:GetParent().data, focus) end
					end)
					btn:SetScript("OnLeave", GameTooltip_Hide)
					btn:SetScript("OnClick", function(self, mouseBtn)
						local row = self:GetParent().data
						if not row then return end
						local shiftHeld = IsShiftKeyDown and IsShiftKeyDown()
						if shiftHeld then
							local id = focus == "writ" and row.writID or row.reqItemID
							if app.tryQuickLookChatLink(id) or shiftSearchWrit(row) then return end
						end
						if focus == "writ" and mouseBtn == "LeftButton" and not shiftHeld
							and not (IsModifierKeyDown and IsModifierKeyDown()) then
							local hud = app.openQuickLook("writ", row, { owner = self:GetParent() })
							if hud then
								app.searchAH(row.writFullName, 1, row.writID, { silentNoAH = true, coalesce = true })
							end
							return
						elseif focus == "writ" then
							app.searchAH(row.writFullName, 1, row.writID)
						else
							app.searchAH(row.reqItemName, row.reqQty, row.reqItemID)
						end
					end)
					r.cells[i] = btn
				elseif i == 3 then
					local zBtn = CreateFrame("Button", nil, r)
					zBtn:SetSize(col.width, ROW_H)
					zBtn:SetPoint("LEFT", r, "LEFT", tbl.colX[i], 0)
					zBtn:RegisterForClicks("LeftButtonUp", "RightButtonUp")
					zBtn.fs = zBtn:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
					zBtn.fs:SetAllPoints()
					zBtn.fs:SetJustifyH("LEFT")
					zBtn.fs:SetWordWrap(false)
					zBtn:SetScript("OnClick", function(self, mouseBtn)
						if not MerchantMasterDB then return end
						local row = self:GetParent().data
						if mouseBtn == "RightButton" or not row or not row.zone then
							MerchantMasterDB.writZoneFilter = "all"
						elseif row.zone == "Unmapped" then
							MerchantMasterDB.writZoneFilter = (MerchantMasterDB.writZoneFilter == "unmapped") and "all" or "unmapped"
						else
							MerchantMasterDB.writZoneFilter = (MerchantMasterDB.writZoneFilter == row.zone) and "all" or row.zone
						end
						app.refresh()
					end)
					r.cells[i] = zBtn
				elseif i == 13 then
					local qBtn = CreateFrame("Button", nil, r)
					qBtn:SetSize(col.width, ROW_H - 2)
					qBtn:SetPoint("LEFT", r, "LEFT", tbl.colX[i], 0)
					qBtn:RegisterForClicks("LeftButtonUp", "RightButtonUp")
					qBtn.bg = qBtn:CreateTexture(nil, "BACKGROUND")
					qBtn.bg:SetAllPoints()
					qBtn.fs = qBtn:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
					qBtn.fs:SetAllPoints()
					qBtn.fs:SetJustifyH("CENTER")
					qBtn:SetScript("OnClick", function(self, mouseBtn)
						adjustWritTurnInQueue(self:GetParent().data, mouseBtn)
					end)
					r.cells[i] = qBtn
				else
					local fs = r:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
					fs:SetSize(col.width, ROW_H)
					fs:SetPoint("LEFT", r, "LEFT", tbl.colX[i], 0)
					fs:SetJustifyH(col.align)
					fs:SetWordWrap(false)
					r.cells[i] = fs
				end
			end
			r:SetScript("OnClick", function(self, mouseBtn)
				local row = self.data
				if not row then return end
				if IsShiftKeyDown and IsShiftKeyDown() then
					if app.tryQuickLookChatLink(row.writID) or shiftSearchWrit(row) then return end
				end
				if mouseBtn == "LeftButton" and not (IsShiftKeyDown and IsShiftKeyDown()) then
					app.openQuickLook("writ", row, { owner = self })
					return
				end
				app.searchAH(row.writFullName, 1, row.writID)
			end)
		end

		r.data = data
		local p = getPal()
		local isBest = data.pricePerRep ~= nil and app.bestWritPPR ~= nil and math.abs(data.pricePerRep - app.bestWritPPR) < 0.001
		local isFree = data.totalPrice ~= nil and data.totalPrice <= 0
		if (isBest or isFree) and p and p.glassHover then
			local hc = p.glassHover
			r.stripe:SetColorTexture(hc[1], hc[2], hc[3], (hc[4] or 0.05) * 0.7)
		else
			r.stripe:SetColorTexture(0, 0, 0, 0)
		end

		r.cells[1].icon:SetTexture(data.writIcon)
		r.cells[1].fs:SetText(palHex("hexPositive", "30d158") .. data.writName .. "|r")

		local qtyPrefix = (data.reqQty > 1) and (tostring(data.reqQty) .. "x ") or ""
		local ownTag = (data.reqOwned >= data.reqQty) and (" " .. palHex("hexPositive", "30d158") .. "(Own)|r") or ""
		r.cells[2].icon:SetTexture(data.reqItemIcon)
		r.cells[2].fs:SetText(palHex("hexText", "ffffff") .. qtyPrefix .. data.reqItemName .. "|r" .. ownTag)

		r.cells[3].fs:SetText(themeText(data.areaDisplay or (palHex("hexMuted", "98989d") .. "Unmapped|r")))

		if data.cdAvailable then
			r.cells[4]:SetText(palHex("hexPositive", "30d158") .. "R|r")
		elseif data.onCooldown then
			r.cells[4]:SetText(palHex("hexDanger", "ff4245") .. tostring(data.cdText or "24h") .. "|r")
		else
			r.cells[4]:SetText(palHex("hexText", "ffffff") .. "-|r")
		end
		local pCol = (data.unlock.known or data.unlock.meetsSkill) and palHex("hexPositive", "30d158") or palHex("hexSecondary", "ebebf5")
		r.cells[5]:SetText(pCol .. data.profSkillLabel .. "|r")
		r.cells[6]:SetText(palHex("hexBlue", "0091ff") .. "+" .. tostring(data.rep) .. "|r")
		r.cells[7]:SetText(ns.FormatMoneyCompact(data.writPrice))

		local chosenItemCost = (data.mode == "Craft") and data.craftCost or data.buyCost
		local mPrefix = (data.mode == "Craft") and (palHex("hexBlue", "0091ff") .. "C:|r") or ((data.mode == "Buy") and (palHex("hexWarning", "ff9230") .. "B:|r") or "")
		r.cells[8]:SetText((chosenItemCost ~= nil) and (mPrefix .. ns.FormatMoneyCompact(chosenItemCost)) or (palHex("hexMuted", "98989d") .. "—|r"))

		r.cells[9]:SetText(ns.FormatMoneyCompact(data.grossTotal))
		if data.pouchRefund and data.pouchRefund > 0 then
			r.cells[10]:SetText(palHex("hexPositive", "30d158") .. "-" .. ns.FormatMoneyCompact(data.pouchRefund) .. "|r")
		else
			r.cells[10]:SetText(zeroMoney("c"))
		end

		if data.totalPrice ~= nil then
			local netStr = ns.FormatMoneyCompact(data.totalPrice)
			r.cells[11]:SetText((data.totalPrice <= 0) and (palHex("hexPositive", "30d158") .. netStr .. "|r") or netStr)
		else
			r.cells[11]:SetText(palHex("hexMuted", "98989d") .. "—|r")
		end

		if data.pricePerRep ~= nil then
			local ppr = ns.FormatMoneyCompact(data.pricePerRep)
			r.cells[12]:SetText((isBest or isFree) and (palHex("hexPositive", "30d158") .. ppr .. "|r") or ppr)
		else
			r.cells[12]:SetText(palHex("hexMuted", "98989d") .. "—|r")
		end

		local qBg = (p and p.glassFill) or { 1, 1, 1, 0.06 }
		if data.queuedCount and data.queuedCount > 0 then
			r.cells[13].bg:SetColorTexture(qBg[1], qBg[2], qBg[3], qBg[4] or 0.08)
			r.cells[13].fs:SetText(palHex("hexPositive", "30d158") .. "[" .. tostring(data.queuedCount) .. "x]|r")
		else
			r.cells[13].bg:SetColorTexture(qBg[1], qBg[2], qBg[3], (qBg[4] or 0.06) * 0.7)
			r.cells[13].fs:SetText(palHex("hexMuted", "98989d") .. "[+ Buy]|r")
		end
	end)
end

