-- Profit Sub-View 3: recipes provider context (registered after the host).
local function recipeContextSnapshot(value, previous)
	if issecretvalue and issecretvalue(value) then return nil end
	if type(value) ~= "table" then return value end
	local copy, same = {}, type(previous) == "table"
	for key, item in pairs(value) do
		if not (issecretvalue and issecretvalue(key)) then
			copy[key] = recipeContextSnapshot(item, same and previous[key] or nil)
			if same and copy[key] ~= previous[key] then same = false end
		end
	end
	if same then for key in pairs(previous) do if copy[key] == nil then same = false; break end end end
	return same and previous or copy
end

function app.getRecipeStatsContext(inputs)
	inputs = inputs or {}
	local db, previous = MerchantMasterDB or {}, app.recipeStatsContext
	local profDB = ns.GetProfessorDB and ns.GetProfessorDB() or {}
	local knownOnly = (inputs.knownRecipesOnly == true) or (db.knownRecipesOnly == true) or (db.unlockFilter == "known")
	local craftAll = ns.IsAllCharsCraftableActive and ns.IsAllCharsCraftableActive({
		knownRecipesOnly = knownOnly,
		unlockFilter = inputs.unlockFilter or db.unlockFilter,
		craftableAllChars = inputs.craftableAllChars,
	}) or false
	local candidate = {
		ownedCounts = inputs.counts or ownedCounts(), profMap = inputs.profMap or ns.GetPlayerProfessions(),
		repState = inputs.repState or ns.GetMerchantReputation(), trainerCosts = profDB.trainerCosts,
		economy = (inputs.econInfo or ns.CurrentEconomyInfo()).effectiveKey, charKey = app.charKey,
		applyAHCut = db.applyAHCut ~= false, subCraftMode = db.subCraftMode or "smart",
		subCraftOverrides = db.subCraftOverrides, outlierPrices = db.outlierPrices,
		sourceKey = db.priceSource, hostRevision = app.recipeStatsRevision,
		craftableAllChars = craftAll,
	}
	local same = previous ~= nil
	for key, value in pairs(candidate) do
		candidate[key] = recipeContextSnapshot(value, previous and previous[key])
		if not previous or candidate[key] ~= previous[key] then same = false end
	end
	if same then
		for key in pairs(previous) do if key ~= "revision" and candidate[key] == nil then same = false; break end end
	end
	if same then return previous end
	candidate.revision = (previous and previous.revision or 0) + 1
	app.recipeStatsContext = candidate
	return candidate
end

function app.buildSuperListContext(opts)
	opts = opts or {}
	local db = MerchantMasterDB or {}
	local counts = opts.counts or ownedCounts()
	local profMap = opts.profMap or (ns.GetPlayerProfessions and ns.GetPlayerProfessions() or {})
	if not app._lastSkillEventProfs then app._lastSkillEventProfs = profMap end
	local repState = opts.repState or (ns.GetMerchantReputation and ns.GetMerchantReputation() or {})
	local econInfo = opts.econInfo or (ns.CurrentEconomyInfo and ns.CurrentEconomyInfo() or {})
	local knownRecipesOnly = (db.knownRecipesOnly == true) or (db.unlockFilter == "known")
	local unlockFilter = knownRecipesOnly and "known" or (db.unlockFilter or "all")
	local subCraftMode = db.subCraftMode or "smart"
	local subCraftOverrides = db.subCraftOverrides
	local search = opts.search
	if search == nil then
		search = (app.ui and app.ui.searchBox and app.ui.searchBox.GetText and app.ui.searchBox:GetText()) or ""
	end
	local profFilter = opts.profFilter or db.profFilter or "all"
	local craftAll = ns.IsAllCharsCraftableActive and ns.IsAllCharsCraftableActive({
		knownRecipesOnly = knownRecipesOnly,
		unlockFilter = unlockFilter,
	}) or false
	return {
		hostManaged = true,
		db = db, search = search, profFilter = profFilter, unlockFilter = unlockFilter,
		knownRecipesOnly = knownRecipesOnly, craftableAllChars = craftAll, subCraftMode = subCraftMode,
		subCraftOverrides = subCraftOverrides, counts = counts, profMap = profMap,
		repState = repState, scanBanner = opts.scanBanner, econInfo = econInfo,
		revision = app.recipeStatsRevision, charKey = app.charKey,
		statsContext = app.getRecipeStatsContext({
			counts = counts, profMap = profMap, repState = repState, econInfo = econInfo,
			knownRecipesOnly = knownRecipesOnly, unlockFilter = unlockFilter, craftableAllChars = craftAll,
		}),
	}
end

