local function findDirectShoppingEntry(list, itemID)
	local key = "item:" .. tostring(itemID)
	for i = 1, #(list or {}) do
		local entry = list[i]
		if type(entry) == "table" and entry.key == key then
			return entry, i
		end
	end
end

function app.getItemShoppingQty(rowOrID)
	local itemID = type(rowOrID) == "table" and tonumber(rowOrID.itemID or rowOrID.outputItemID) or tonumber(rowOrID)
	if not (itemID and itemID > 0 and MerchantMasterDB and type(MerchantMasterDB.shoppingList) == "table") then return 0 end
	local entry = findDirectShoppingEntry(MerchantMasterDB.shoppingList, itemID)
	return entry and math.max(0, math.floor((tonumber(entry.qty) or 0) + 0.5)) or 0
end

local itemQtySyncPending
function app.adjustItemShoppingQty(rowOrID, delta)
	if not MerchantMasterDB then return 0 end
	local itemID = type(rowOrID) == "table" and tonumber(rowOrID.itemID or rowOrID.outputItemID) or tonumber(rowOrID)
	if not (itemID and itemID > 0) then return 0 end
	MerchantMasterDB.shoppingList = MerchantMasterDB.shoppingList or {}
	local list = MerchantMasterDB.shoppingList
	local numDelta = tonumber(delta) or 0
	local d = numDelta >= 0 and math.floor(numDelta + 0.5) or -math.floor(-numDelta + 0.5)
	local entry, idx = findDirectShoppingEntry(list, itemID)
	local cur = entry and math.max(0, math.floor((tonumber(entry.qty) or 0) + 0.5)) or 0
	if d == 0 then return cur end
	local nextQty = math.max(0, cur + d)
	if nextQty == 0 then
		if idx then table.remove(list, idx) end
	elseif entry then
		entry.qty = nextQty
	else
		local name = (type(rowOrID) == "table" and rowOrID.name) or (ns.ItemName and ns.ItemName(itemID)) or ("Item #" .. tostring(itemID))
		list[#list + 1] = {
			key = "item:" .. tostring(itemID),
			name = name,
			itemID = itemID,
			qty = nextQty,
			sourceLabel = "All Items",
		}
	end
	if not app.hasUnifiedShoppingItems() then
		app._profPreviewCleared = true
		if app.setActiveShoppingList then
			app.setActiveShoppingList({}, themeText(EMPTY_SHOPPING_SUMMARY), "Shopping List", app.activeTab)
		end
	else
		app._profPreviewCleared = nil
		if app.syncUnifiedShoppingList and not itemQtySyncPending then
			itemQtySyncPending = true
			C_Timer.After(0, function()
				itemQtySyncPending = false
				if app.hasUnifiedShoppingItems() then app.syncUnifiedShoppingList() end
			end)
		end
	end
	if app.allItemsProvider and app.allItemsProvider.RepaintShoppingQty then
		app.allItemsProvider.RepaintShoppingQty()
	end
	if app.watchlistProvider and app.watchlistProvider.RepaintShoppingQty then
		app.watchlistProvider.RepaintShoppingQty()
	end
	return nextQty
end

