	if not (app.allItemsProvider and app.allItemsProvider.WarmInBackground) then return end
	if panel and panel:IsShown() and app.activeTab == "all_items" then return end
	if app.allItemsProvider.IsWarming and app.allItemsProvider.IsWarming() then return end
	app.warmAllItemsCache(0.05)
end

function app.warmDisenchantCrafterCache(delay)
	if not (app.disenchantCrafterProvider and app.disenchantCrafterProvider.WarmInBackground) then return end
	if panel and panel:IsShown() and app.activeTab == "disenchant_crafter" then return end
	local seq = (app._warmDCTimerSeq or 0) + 1
	app._warmDCTimerSeq = seq
	local function run()
		if seq ~= app._warmDCTimerSeq then return end
		if panel and panel:IsShown() and app.activeTab == "disenchant_crafter" then return end
		if not MerchantMasterDB then return end
		local started = app.disenchantCrafterProvider.WarmInBackground(app.buildDisenchantCrafterContext())
		if started == false then
			app._dcWarmUnsupported = app.disenchantCrafterProvider
		elseif app._dcWarmUnsupported == app.disenchantCrafterProvider then
			app._dcWarmUnsupported = nil
		end
		if started ~= false and app.disenchantCrafterProvider.HasWarmData and app.disenchantCrafterProvider.HasWarmData()
			and not (app.disenchantCrafterProvider.IsWarming and app.disenchantCrafterProvider.IsWarming())
			and app.onDisenchantCrafterWarmComplete then
			app.onDisenchantCrafterWarmComplete()
		end
	end
	if delay and delay > 0 and C_Timer and C_Timer.After then
		C_Timer.After(delay, run)
	else
		run()
	end
end

function app.onVendorCrafterWarmComplete()
	if app.disenchantCrafterProvider and app.disenchantCrafterProvider.WarmInBackground then
		if panel and panel:IsShown() and app.activeTab == "disenchant_crafter" then
