	if delay and delay > 0 and C_Timer and C_Timer.After then
		C_Timer.After(delay, run)
	else
		run()
	end
end

---------------------------------------------------------------------------------------------------
-- Recipe quantities shared by All Recipes and the shopping basket.
do
	local function sameQueuedRecipe(entry, rec)
		if not entry or not rec then return false end
		local eSpell = tonumber(entry.spellID) or 0
		local rSpell = tonumber(rec.spellID) or 0
		if eSpell > 0 or rSpell > 0 then
			return eSpell > 0 and eSpell == rSpell and (not entry.prof or not rec.prof or entry.prof == rec.prof)
		end
		if entry.idx and rec.idx and entry.idx == rec.idx and entry.outputItemID == rec.outputItemID then
			return true
		end
		if entry.outputItemID and rec.outputItemID and entry.outputItemID > 0 and entry.outputItemID == rec.outputItemID and entry.prof == rec.prof then
			return true
		end
		return false
	end

	local function resolveQueueRecipe(rowOrRecipe)
		if not rowOrRecipe then return nil end
		if type(rowOrRecipe) == "table" and type(rowOrRecipe.recipe) == "table" then
			return rowOrRecipe.recipe
		end
		local rec = ns.ResolveCraftingOrderRecipe(rowOrRecipe, ns.GetPlayerProfessions(), false)
		if rec then return rec end
		if type(rowOrRecipe) == "table" and (rowOrRecipe.spellID or rowOrRecipe.outputItemID or rowOrRecipe.idx) then
			return rowOrRecipe
		end
		return nil
	end

	function app.getRecipeShoppingQty(rowOrRecipe)
		local queue = MerchantMasterDB and MerchantMasterDB.craftOrderQueue
		if type(queue) ~= "table" or #queue == 0 then return 0 end
		local rec = resolveQueueRecipe(rowOrRecipe)
		if not rec then return 0 end
		local total = 0
		for _, entry in ipairs(queue) do
			if sameQueuedRecipe(entry, rec) then
				total = total + math.max(0, math.floor((tonumber(entry.qty) or 0) + 0.5))
			end
		end
		return total
	end

	local function applyQueueEntryMeta(entry, meta, nextQty)
		if not (entry and type(meta) == "table") then return end
		if type(meta.reagents) == "table" and #meta.reagents > 0 then
			local cloned = {}
			for i, pair in ipairs(meta.reagents) do
				if type(pair) == "table" and pair[1] and pair[2] and pair[2] > 0 then
					cloned[#cloned + 1] = { pair[1], pair[2] }
				end
			end
			if #cloned > 0 then entry.reagentOverride = cloned end
		end
		if meta.reusedQty ~= nil then
			local rq = math.max(0, math.floor((tonumber(meta.reusedQty) or 0) + 0.5))
			if meta.setReusedQty then
				entry.reusedQty = rq > 0 and math.min(nextQty, rq) or nil
			elseif rq > 0 then
				local prev = math.max(0, math.floor((tonumber(entry.reusedQty) or 0) + 0.5))
				entry.reusedQty = math.min(nextQty, math.max(prev, rq))
			end
		end
		if type(meta.buyCaps) == "table" then
			local caps = {}
			for itemID, c in pairs(meta.buyCaps) do
				local id = tonumber(itemID)
				if id and type(c) == "table" then
					caps[id] = {
						maxBuyUnit = tonumber(c.maxBuyUnit),
						breakEvenUnit = tonumber(c.breakEvenUnit),
						wallUnit = tonumber(c.wallUnit),
						avgBuyUnit = tonumber(c.avgBuyUnit),
						source = c.source,
					}
				end
			end
			if next(caps) then
				entry.buyCaps = caps
			end
		end
	end

	local shoppingQtySyncPending
	function app.adjustRecipeShoppingQty(rowOrRecipe, delta, meta)
		if not MerchantMasterDB then return 0 end
		local rec = resolveQueueRecipe(rowOrRecipe)
		if not rec then return 0 end
		MerchantMasterDB.craftOrderQueue = MerchantMasterDB.craftOrderQueue or {}
		local queue = MerchantMasterDB.craftOrderQueue
		local numDelta = tonumber(delta) or 0
		local d = numDelta >= 0 and math.floor(numDelta + 0.5) or -math.floor(-numDelta + 0.5)

		local matchIdx
		for i = 1, #queue do
			if sameQueuedRecipe(queue[i], rec) then
				matchIdx = i
				break
			end
		end
		if d == 0 then
			if matchIdx and type(meta) == "table" then
				local cur = math.max(0, math.floor((tonumber(queue[matchIdx].qty) or 0) + 0.5))
				applyQueueEntryMeta(queue[matchIdx], meta, cur)
			end
			return app.getRecipeShoppingQty(rec)
		end

		local cdInfo = (d > 0 and ns.GetRecipeCooldownInfo) and ns.GetRecipeCooldownInfo(rec) or nil
		if d > 0 and cdInfo and cdInfo.sharedGroup and ns.GetRecipeCooldownGroup then
			for i = 1, #queue do
				local entry = queue[i]
				if (tonumber(entry.qty) or 0) > 0 and not sameQueuedRecipe(entry, rec) then
					local otherRec = resolveQueueRecipe(entry)
					if otherRec and ns.GetRecipeCooldownGroup(otherRec) == cdInfo.sharedGroup then
						if app.ui and app.ui.toast and app.ui.toast.ShowToast then
							app.ui.toast:ShowToast("Shared Transmute cooldown already queued (" .. tostring(otherRec.name or "another Transmute") .. ")", "info")
						end
						return 0
					end
				end
			end
		end
		local isLongCD = cdInfo and (cdInfo.nominalSeconds or 0) >= 82800
		local curQty = matchIdx and math.max(0, math.floor((tonumber(queue[matchIdx].qty) or 0) + 0.5)) or 0
		if isLongCD and d > 0 and (curQty + d) > 1 then
			d = (curQty >= 1) and 0 or (1 - curQty)
			if app.ui and app.ui.toast and app.ui.toast.ShowToast then
				app.ui.toast:ShowToast(string.format("%s: max 1 craft per %s", rec.name or "Recipe", cdInfo.windowLabel), "info")
			end
			if d == 0 then
				return curQty
			end
		end

		local nextQty = 0
		if matchIdx then
			local entry = queue[matchIdx]
			local cur = math.max(0, math.floor((tonumber(entry.qty) or 0) + 0.5))
			nextQty = cur + d
			if nextQty <= 0 then
				table.remove(queue, matchIdx)
				nextQty = 0
			else
				entry.qty = nextQty
				entry.idx = rec.idx or entry.idx
				entry.spellID = rec.spellID or entry.spellID
				entry.outputItemID = rec.outputItemID or entry.outputItemID
				entry.prof = rec.prof or entry.prof
				if entry.reusedQty and entry.reusedQty > nextQty then
					entry.reusedQty = nextQty
				end
				applyQueueEntryMeta(entry, meta, nextQty)
			end
		elseif d > 0 then
			nextQty = d
			local newEntry = {
				idx = rec.idx,
				spellID = rec.spellID,
				outputItemID = rec.outputItemID,
				prof = rec.prof,
				qty = nextQty,
			}
			applyQueueEntryMeta(newEntry, meta, nextQty)
			queue[#queue + 1] = newEntry
		end

		if not app.hasUnifiedShoppingItems() then

			app._profPreviewCleared = true

			if app.setActiveShoppingList then
				app.setActiveShoppingList({}, themeText(EMPTY_SHOPPING_SUMMARY), "Shopping List", app.activeTab)
			end
		else
			app._profPreviewCleared = nil
			if not shoppingQtySyncPending then
				-- Rebuild the basket once for the settled quantities.
				shoppingQtySyncPending = true
				C_Timer.After(0, function()
					shoppingQtySyncPending = false
					if app.hasUnifiedShoppingItems() then app.syncUnifiedShoppingList() end
				end)
			end
		end
		if app.superListProvider and app.superListProvider.RepaintShoppingQty then
			app.superListProvider.RepaintShoppingQty()
		end
		if app.vendorCrafterProvider and app.vendorCrafterProvider.RepaintShoppingQty then
			app.vendorCrafterProvider.RepaintShoppingQty()
		end
		if app.disenchantCrafterProvider and app.disenchantCrafterProvider.RepaintShoppingQty then
			app.disenchantCrafterProvider.RepaintShoppingQty()
		end
		if app.allItemsProvider and app.allItemsProvider.RepaintShoppingQty then
			app.allItemsProvider.RepaintShoppingQty()
		end
		if app.professorProvider and app.professorProvider.repaintShoppingQty then
			app.professorProvider.repaintShoppingQty()
		end
		return nextQty
	end

	function app.clearCraftingOrderQueue()
		if MerchantMasterDB and type(MerchantMasterDB.craftOrderQueue) == "table" then
			wipe(MerchantMasterDB.craftOrderQueue)
		end


		if app.superListProvider and app.superListProvider.RepaintVisible then
			app.superListProvider.RepaintVisible()
		end
		if app.vendorCrafterProvider and app.vendorCrafterProvider.RepaintVisible then
			app.vendorCrafterProvider.RepaintVisible()
		end
		if app.disenchantCrafterProvider and app.disenchantCrafterProvider.RepaintVisible then
			app.disenchantCrafterProvider.RepaintVisible()
		end
		if app.allItemsProvider and app.allItemsProvider.RepaintVisible then
			app.allItemsProvider.RepaintVisible()
		end
		app.refresh()
	end


	function app.openCraftingOrder(rowOrRecipe, qty)
		local rec = ns.ResolveCraftingOrderRecipe(rowOrRecipe, ns.GetPlayerProfessions(), rowOrRecipe == nil)
		if not rec then return false end
		app.selectedRecipeItemID = rec.outputItemID
		if not panel:IsShown() then app.togglePanel("recipes") else app.setTab("recipes") end
		if ns.SuperList and type(ns.SuperList.OpenQuickLook) == "function" then
			pcall(ns.SuperList.OpenQuickLook, rec.outputItemID or rowOrRecipe, true, rec)
		end
		return true
	end
end

