function app.queueVendorCrafterPlan(entries, opts)
	if type(entries) ~= "table" then return 0, 0 end
	local replace = (opts and opts.replace) and true or false
	if replace and MerchantMasterDB and type(MerchantMasterDB.craftOrderQueue) == "table" then
		wipe(MerchantMasterDB.craftOrderQueue)
	end
	local recipesQueued, craftsQueued = 0, 0
	for _, entry in ipairs(entries) do
		local row = type(entry) == "table" and entry.row or nil
		local desired = math.floor(tonumber(type(entry) == "table" and entry.crafts or 0) or 0)
		if row and desired >= 1 then
			local cur = (app.getRecipeShoppingQty and app.getRecipeShoppingQty(row)) or 0
			local delta = desired - cur
			local finalQty = cur
			local caps = (type(entry) == "table" and entry.reagentBuyCaps) or row.reagentBuyCaps or nil
			local meta = (type(caps) == "table") and { buyCaps = caps } or nil
			if (delta ~= 0 or meta) and app.adjustRecipeShoppingQty then
				finalQty = app.adjustRecipeShoppingQty(row, delta, meta) or 0
			end
			if finalQty > 0 then
				recipesQueued = recipesQueued + 1
				craftsQueued = craftsQueued + finalQty
			end
		end
	end
	if recipesQueued > 0 then
		if app.syncUnifiedShoppingList and app.hasUnifiedShoppingItems and app.hasUnifiedShoppingItems() then
			app.syncUnifiedShoppingList()
		end
		if not (opts and opts.silent) and app.toggleShoppingWindow then
			app.toggleShoppingWindow(true)
		end
	elseif replace then
		if app.superListProvider and app.superListProvider.RepaintVisible then
			app.superListProvider.RepaintVisible()
		end
		if app.vendorCrafterProvider and app.vendorCrafterProvider.RepaintVisible then
			app.vendorCrafterProvider.RepaintVisible()
		end
		if app.disenchantCrafterProvider and app.disenchantCrafterProvider.RepaintVisible then
			app.disenchantCrafterProvider.RepaintVisible()
		end
		if app.allItemsProvider and app.allItemsProvider.RepaintVisible then
			app.allItemsProvider.RepaintVisible()
		end
	end
	return recipesQueued, craftsQueued
end

app.queueDisenchantCrafterPlan = app.queueVendorCrafterPlan

function app.tryQuickLookChatLink(itemID)
	if not itemID then return false end
	local modified = false
	if type(_G.IsModifiedClick) == "function" then
		local ok, value = pcall(_G.IsModifiedClick, "CHATLINK")
		modified = ok and value == true
	end
	local searchBox = app.ui and app.ui.searchBox
	local searchFocused = false
	if searchBox and searchBox.HasFocus then
		local ok, value = pcall(searchBox.HasFocus, searchBox)
		searchFocused = ok and value == true
	end
	if not modified and not searchFocused then return false end
	local function itemLinkFrom(getItemInfo)
		if type(getItemInfo) ~= "function" then return nil end
		local ok, _, link = pcall(getItemInfo, itemID)
		if not ok then return nil end
		if type(_G.issecretvalue) == "function" then
			local secretOk, secret = pcall(_G.issecretvalue, link)
			if not secretOk or secret then return nil end
		end
		if type(link) ~= "string" or link == "" then return nil end
		return link
	end
	local primary = C_Item and C_Item.GetItemInfo
	local link = itemLinkFrom(primary)
	if not link and _G.GetItemInfo ~= primary then
		link = itemLinkFrom(_G.GetItemInfo)
	end
	if not link then return false end
	if modified and type(_G.ChatEdit_InsertLink) == "function" then
		local inserted, accepted = pcall(_G.ChatEdit_InsertLink, link)
		if inserted and accepted == true then return true end
	end
	if searchFocused and type(ns.AllowItemInsert) == "function" then
		local inserted, accepted = pcall(ns.AllowItemInsert, link)
		return inserted and accepted == true
	end
	return false
end

local function isSameQuickLookTarget(kind, prevRow, nextRow)
	if not (prevRow and nextRow) then return false end
	if prevRow == nextRow then return true end
	if kind == "writ" then
		return prevRow.writID and prevRow.writID == nextRow.writID
	elseif kind == "forged" then
		return prevRow.crateID and prevRow.crateID == nextRow.crateID
	elseif kind == "crate" then
		return prevRow.crateID and prevRow.crateID == nextRow.crateID and prevRow.reagentID == nextRow.reagentID
	elseif kind == "item" then
		local pid = tonumber(prevRow.itemID or prevRow.outputItemID)
		local nid = tonumber(nextRow.itemID or nextRow.outputItemID)
		return pid ~= nil and pid > 0 and pid == nid
	elseif kind == "recipe" then
		if prevRow.recipe and prevRow.recipe == nextRow.recipe then return true end
		local prevSpell = tonumber(prevRow.spellID or (prevRow.recipe and prevRow.recipe.spellID))
		local nextSpell = tonumber(nextRow.spellID or (nextRow.recipe and nextRow.recipe.spellID))
		local prevProf = prevRow.prof or (prevRow.recipe and prevRow.recipe.prof)
		local nextProf = nextRow.prof or (nextRow.recipe and nextRow.recipe.prof)
		if prevProf and nextProf and prevProf ~= nextProf then return false end
		if prevSpell and nextSpell and prevSpell > 0 and nextSpell > 0 then
			return prevSpell == nextSpell
		end
		local prevOutID = prevRow.outputItemID or prevRow.itemID
		local nextOutID = nextRow.outputItemID or nextRow.itemID
		if not (prevOutID and nextOutID and prevOutID > 0 and nextOutID > 0) then return false end
		if prevRow.key ~= nil and nextRow.key ~= nil then return prevRow.key == nextRow.key end
		return prevOutID == nextOutID
	end
	return false
end

function app.buildRecipeQuickLookRow(d)
	if not d then return end
	d = d._orig or d
	if d.isMilestone or d.srcType == "gather" then return end
	local rawOutID = tonumber(d.outputItemID or d.itemID)
	local outputItemID = (rawOutID and rawOutID > 0) and rawOutID or nil
	local profMap = ns.GetPlayerProfessions()
	local profHint = d.prof or (d.rec and d.rec.prof) or (ns.MP and ns.MP.GetDB and ns.MP.GetDB().selectedProf)
	local recipe = d.recipe
	if not recipe and ns.ResolveCraftingOrderRecipe and ((d.spellID and d.spellID > 0) or outputItemID) then
		recipe = ns.ResolveCraftingOrderRecipe({
			spellID = d.spellID,
			outputItemID = outputItemID,
			prof = profHint,
		}, profMap, false)
	end
	if not recipe and outputItemID then
		if ns.SelectBestRecipeForItem then
			recipe = ns.SelectBestRecipeForItem(outputItemID, profHint, profMap)
		end
		if not recipe then
			local recipes = ns.RECIPES_BY_OUTPUT and ns.RECIPES_BY_OUTPUT[outputItemID]
			recipe = recipes and recipes[1]
		end
	end
	if not recipe then return end

	local statsRow = (ns.RecipeStats and ns.RecipeStats.Get and app.getRecipeStatsContext)
		and ns.RecipeStats.Get(recipe, app.getRecipeStatsContext()) or nil

	-- Professor rows (d.ev ~= nil) store per-craft grossPerCraft & profitCraft, so copy into a clean
	-- Quick Look row without mutating Browse/Path rows; all other rows preserve source table identity.
	local ql = d
	if d.ev then
		ql = {}
		for k, v in pairs(d) do ql[k] = v end
		ql._orig = d
	end
	ql.recipe = recipe
	ql.spellID = ql.spellID or recipe.spellID
	ql.outputItemID = outputItemID or recipe.outputItemID
	ql.name = ql.rawRecipeName or ql.name or (ql.outputItemID and ns.ItemName(ql.outputItemID, recipe.name)) or recipe.name
	local profInfo = ns.MP and ns.MP.PROFESSIONS and ns.MP.PROFESSIONS[recipe.prof or profHint or ""]
	ql.icon = ql.icon or (ql.outputItemID and ns.ItemIcon(ql.outputItemID)) or (statsRow and statsRow.icon) or (profInfo and profInfo.icon)
	ql.prof = ql.prof or recipe.prof or profHint
	ql.requiredSkill = ql.requiredSkill or ql.reqSkill or ql.req or recipe.skill
	local made = math.max(1, tonumber(ql.numMade or recipe.numMade) or 1)
	ql.numMade = made
	ql.craftAbility = ql.craftAbility or (statsRow and statsRow.craftAbility)
	ql.sourceLabel = ql.sourceLabel or (statsRow and statsRow.sourceLabel)
	ql.listed = (ql.listed ~= nil) and ql.listed or (statsRow and statsRow.listed)
	ql.unitAH = ql.unitAH or ql.ahPrice or ql.targetPrice or (d.ev and d.ev.ahGrossUnit) or (statsRow and statsRow.unitAH)
	if d.ev then
		-- RecipeStats.BuildQuickLook expects per-unit craftCost & profit (then multiplies by `made`).
		local evUnitCraft = (type(d.ev.grossPerCraft) == "number") and (d.ev.grossPerCraft / made) or nil
		local evUnitProfit = (type(d.profitCraft) == "number") and (d.profitCraft / made) or nil
		ql.craftCost = (statsRow and statsRow.craftCost) or evUnitCraft
		ql.profit = (statsRow and statsRow.profit ~= nil and statsRow.profit) or evUnitProfit
	else
		ql.craftCost = ql.craftCost or (statsRow and statsRow.craftCost)
		ql.profit = (ql.profit ~= nil and ql.profit) or ql.realizedProfit or (statsRow and statsRow.profit)
	end
	ql.salesPerDay = ql.salesPerDay or ql.dailySold or (statsRow and statsRow.salesPerDay)
	return ql
end

local function findQuickLookRow(kind, previous, rows)
	local match
	for _, row in ipairs(rows or {}) do
		if isSameQuickLookTarget(kind, previous, row) then
			if kind ~= "recipe" or row == previous or (previous.recipe and previous.recipe == row.recipe) then
				return row
			end
			match = match or row
		end
	end
	return match
end

local function resolveQuickLookRow(kind, previous)
	if not previous then return end
	local tab = app.activeTab
	if kind == "forged" then
		return findQuickLookRow(kind, previous, app.quickLookRows and app.quickLookRows.forged)
	end
	if kind == "item" then
		return findQuickLookRow(kind, previous, app.allItemsProvider and app.allItemsProvider.GetRows and app.allItemsProvider.GetRows())
	end
	if kind ~= "recipe" then
		if tab == "dashboard" then
			for _, frame in ipairs(app.ui.dashTurninRows) do
				if frame.rowKind == kind and isSameQuickLookTarget(kind, previous, frame.rowData) then return frame.rowData end
			end
			return
		end
		return findQuickLookRow(kind, previous, app.quickLookRows and app.quickLookRows[kind])
	end

	local row
	if tab == "profit_spread" then
		row = findQuickLookRow(kind, previous, app.lastSpreadRows)
	elseif tab == "outliers" then
		row = findQuickLookRow(kind, previous, app.lastOutlierRows)
	elseif tab == "prof_path" and ns.MP and ns.MP.app then
		row = findQuickLookRow(kind, previous, ns.MP.app.lastVisiblePathSteps)
	elseif tab == "prof_browse" and ns.MP and ns.MP.app then
		row = findQuickLookRow(kind, previous, ns.MP.app.lastBrowseRows)
	elseif tab == "dashboard" and app.lastDashInsights then
		row = findQuickLookRow(kind, previous, app.lastDashInsights.topCrafts)
			or findQuickLookRow(kind, previous, app.lastDashInsights.topOutliers)
	end
	local quickLookRow = app.buildRecipeQuickLookRow(row)
	if quickLookRow then return quickLookRow end
	if previous.recipe then return ns.RecipeStats.Get(previous.recipe, app.getRecipeStatsContext()) end
end

function app.openQuickLook(kind, row, opts)
	local anchor
	if type(kind) == "table" then
		local rawRow, anchorOrOpts = kind, row
		if type(anchorOrOpts) == "table" and not anchorOrOpts.GetObjectType then
			opts = opts or anchorOrOpts
		else
			anchor = anchorOrOpts
		end
		row = rawRow
		kind = rawRow.forged and "forged" or (opts and opts.kind)
			or (rawRow.writ and "writ") or (rawRow.crate and "crate") or "recipe"
	end
	local provider = app.superListProvider
	if not (provider and provider.OpenQuickLook and row) then return end
	if kind == "forged" and not (ns.RecipeStats and ns.RecipeStats.BuildForgedQuickLook) then return end
	opts = opts or {}
	local hud = provider.GetQuickLookFrame and provider.GetQuickLookFrame()
	if opts.toggle ~= false and hud and hud:IsShown() and hud.data and hud.data.kind == kind
		and isSameQuickLookTarget(kind, hud.row, row) then
		provider.CloseQuickLook()
		return
	end
	if (kind == "recipe" or kind == "item") and ns.WarmLiveVendorPrices then
		local outID = tonumber(row.outputItemID or row.itemID)
		if outID and outID > 0 then
			ns.WarmLiveVendorPrices({ outID })
		end
	end
	return provider.OpenQuickLook(row, true, nil, { kind = kind, owner = opts.owner or anchor })
end

function app.refreshQuickLook()
	local provider = app.superListProvider
	if not (provider and provider.RefreshQuickLook) then return end
	local hud = provider.GetQuickLookFrame and provider.GetQuickLookFrame()
	if hud and hud:IsShown() and hud.data and hud.data.kind == "recipe" and hud.openedTab ~= "recipes" then
		hud.row = resolveQuickLookRow("recipe", hud.row) or hud.row
	end
	return provider.RefreshQuickLook()
end

function app.addQuickLookItem(kind, row)
	if kind == "forged" then return app.adjustForgedTurnInQueue(row, 1) end
	if kind == "item" then
		local itemID = tonumber(row and (row.itemID or row.outputItemID))
		if not (MerchantMasterDB and itemID and itemID > 0) then return false end
		local before = app.getItemShoppingQty(row)
		local after = app.adjustItemShoppingQty(row, 1)
		if after > before and app.syncUnifiedShoppingList then
			app.syncUnifiedShoppingList()
		end
		return after > before
	end
	if kind == "writ" then
		if not (MerchantMasterDB and row.writID) then return false end
		MerchantMasterDB.writTurnInQueue = MerchantMasterDB.writTurnInQueue or {}
		local queue = MerchantMasterDB.writTurnInQueue
		queue[row.writID] = (tonumber(queue[row.writID]) or 0) + 1
		app.refresh()
		return true
	end
	if kind ~= "crate" or not row.crateID then return false end
	local demand = {
		{ itemID = row.crateID, qty = 1, role = "Crate", parentProf = row.prof },
		{ itemID = row.reagentID, qty = row.reagentQty or 1, role = "Reagent", parentProf = row.prof },
	}
	return app.addUnifiedShoppingItem({ key = "crate:" .. row.crateID .. ":" .. tostring(row.reagentID),
		name = row.crateFullName or row.crateName, itemID = row.crateID, qty = 1,
		demandList = demand, sourceLabel = "Waylaid Crate" })
end

local function normalizeDeepAnalysisSpec(targetSpec)
	if type(targetSpec) == "number" then
		return { kind = "item", itemID = targetSpec }
	end
	if type(targetSpec) ~= "table" then return nil end
	local spec
	if targetSpec.row ~= nil or targetSpec.kind ~= nil
		or (targetSpec.itemID ~= nil and targetSpec.recipe == nil and targetSpec.writ == nil and targetSpec.crate == nil and not targetSpec.forged) then
		spec = {
			kind = targetSpec.kind,
			row = targetSpec.row,
			itemID = tonumber(targetSpec.itemID),
			recipe = targetSpec.recipe,
			context = targetSpec.context,
			window = targetSpec.window,
			name = targetSpec.name,
			icon = targetSpec.icon,
		}
	else
		spec = { row = targetSpec }
	end
	if not spec.kind then
		local r = spec.row
		if type(r) == "table" then
			if r.forged then spec.kind = "forged"
			elseif r.writ or r.writID then spec.kind = "writ"
			elseif r.crate or r.crateID then spec.kind = "crate"
			elseif r.recipe or r.outputItemID then spec.kind = "recipe"
			else spec.kind = "item" end
		elseif spec.recipe then
			spec.kind = "recipe"
		else
			spec.kind = "item"
		end
	end
	if spec.kind == "recipe" then
		local ctx = spec.context or (app.getRecipeStatsContext and app.getRecipeStatsContext()) or {}
		if spec.row and not spec.row.recipe and app.buildRecipeQuickLookRow then
			local built = app.buildRecipeQuickLookRow(spec.row)
			if built then spec.row = built end
		end
		if not spec.row and spec.recipe and ns.RecipeStats and ns.RecipeStats.Get then
			spec.row = ns.RecipeStats.Get(spec.recipe, ctx)
		end
		if not spec.row and spec.itemID and ns.RecipeStats and ns.RecipeStats.GetCatalog then
			for _, entry in ipairs(ns.RecipeStats.GetCatalog()) do
				if entry.recipe and entry.recipe.outputItemID == spec.itemID then
					spec.row = ns.RecipeStats.Get(entry.recipe, ctx)
					break
				end
			end
		end
		if spec.row and spec.row.recipe then
			spec.recipe = spec.recipe or spec.row.recipe
		end
	end
	if not spec.itemID then
		local r = spec.row
		spec.itemID = tonumber((r and (r.outputItemID or r.writID or r.crateID or r.itemID))
			or (spec.recipe and spec.recipe.outputItemID))
	end
	if not spec.window then
		spec.window = (MerchantMasterDB and MerchantMasterDB.quickLookWindow) or "7d"
	end
	return spec
end

function app.openDeepAnalysis(targetSpec, returnContext)
	local spec = normalizeDeepAnalysisSpec(targetSpec)
	if not spec then return false end
	local provider = app.superListProvider
	if not spec.context then
		local ctx = {}
		if app.getRecipeStatsContext then
			for k, v in pairs(app.getRecipeStatsContext()) do ctx[k] = v end
		end
		local db = MerchantMasterDB or {}
		ctx.writMode = db.writMode
		ctx.crateMode = db.crateMode
		ctx.forgedMode = db.forgedMode or "self_funded"
		ctx.forgedHumanDiplomacy = db.forgedHumanDiplomacy
		ctx.humanDiplomacy = db.forgedHumanDiplomacy
		ctx.window = spec.window
		ctx.kind = spec.kind
		spec.context = ctx
	else
		spec.context.window = spec.context.window or spec.window
		spec.context.kind = spec.context.kind or spec.kind
	end

	if app.activeTab == "deep_analysis" and app._deepAnalysisTarget then
		app._deepAnalysisStack = app._deepAnalysisStack or {}
		app._deepAnalysisStack[#app._deepAnalysisStack + 1] = app._deepAnalysisTarget
	else
		app._deepAnalysisStack = {}
		local ret = {}
		if type(returnContext) == "table" then
			for k, v in pairs(returnContext) do ret[k] = v end
		end
		if not ret.tab or ret.tab == "deep_analysis" then
			local curTab = app.activeTab
			if curTab == "deep_analysis" and app._deepAnalysisReturn and app._deepAnalysisReturn.tab then
				curTab = app._deepAnalysisReturn.tab
			end
			ret.tab = (curTab and curTab ~= "deep_analysis") and curTab or "recipes"
		end
		local hud = provider and provider.GetQuickLookFrame and provider.GetQuickLookFrame()
		if ret.wasQuickLookOpen == nil then
			ret.wasQuickLookOpen = (hud and hud:IsShown()) and true or false
		end
		if ret.wasQuickLookOpen then
			ret.quickLookKind = ret.quickLookKind or (hud and (hud.kind or (hud.data and hud.data.kind))) or spec.kind
			ret.quickLookRow = ret.quickLookRow or (hud and hud.row) or spec.row
			ret.quickLookWindow = ret.quickLookWindow or (hud and hud.window) or spec.window
		end
		if ret.superListScrollPct == nil and (ret.tab == "recipes" or ret.tab == "all_items" or ret.tab == "vendor_crafter" or ret.tab == "disenchant_crafter") then
			local tbl = (ret.tab == "vendor_crafter") and (app.ui and app.ui.vendorCrafterTable)
				or (ret.tab == "disenchant_crafter") and (app.ui and app.ui.disenchantCrafterTable)
				or (ret.tab == "all_items") and (app.ui and app.ui.allItemsTable)
				or (app.ui and app.ui.recipesTable)
			local sb = tbl and tbl.scrollBox
			if sb and sb.GetScrollPercentage then
				ret.superListScrollPct = sb:GetScrollPercentage()
			end
		end
		if ret.analyticsDetailKey == nil and ret.tab == "an_items" then
			local anUI = ns.Analytics and ns.Analytics.UI
			local det = anUI and anUI.views and anUI.views.an_items and anUI.views.an_items.detail
			if det and det:IsShown() and anUI.detailKey ~= nil then
				ret.analyticsDetailKey = anUI.detailKey
			end
		end
		app._deepAnalysisReturn = ret
	end

	if provider and provider.CloseQuickLook then provider.CloseQuickLook() end
	if provider and provider.CloseHeatPopover then provider.CloseHeatPopover() end
	if app.vendorCrafterProvider and app.vendorCrafterProvider.CloseHeatPopover then app.vendorCrafterProvider.CloseHeatPopover() end
	if app.disenchantCrafterProvider and app.disenchantCrafterProvider.CloseHeatPopover then app.disenchantCrafterProvider.CloseHeatPopover() end
	if app.allItemsProvider and app.allItemsProvider.CloseHeatPopover then app.allItemsProvider.CloseHeatPopover() end
	local anDet = ns.Analytics and ns.Analytics.UI and ns.Analytics.UI.views
		and ns.Analytics.UI.views.an_items and ns.Analytics.UI.views.an_items.detail
	if anDet and anDet:IsShown() then anDet:Hide() end

	app._deepAnalysisTarget = spec
	app._deepAnalysisKeepingStack = true
	app._openingDeepAnalysis = true
	local ok, err = pcall(function()
		if not panel:IsShown() then
			app.setTab("deep_analysis")
			panel:Show()
		else
			app.setTab("deep_analysis")
		end
	end)
	app._openingDeepAnalysis = false
	app._deepAnalysisKeepingStack = false
	if not ok then error(err, 0) end
	if ns.DeepAnalysis and ns.DeepAnalysis.ShowTarget then
		ns.DeepAnalysis.ShowTarget(spec)
	end
	return true
end

function app.returnFromDeepAnalysis()
	local stack = app._deepAnalysisStack
	if stack and #stack > 0 then
		local prev = table.remove(stack)
		app._deepAnalysisTarget = prev
		app._deepAnalysisKeepingStack = true
		if app.activeTab ~= "deep_analysis" then
			app.setTab("deep_analysis")
		end
		app._deepAnalysisKeepingStack = false
		if ns.DeepAnalysis and ns.DeepAnalysis.ShowTarget then
			ns.DeepAnalysis.ShowTarget(prev)
		end
		return true
	end
	local ctx = app._deepAnalysisReturn or { tab = "recipes" }
	local targetTab = (ctx.tab and ctx.tab ~= "deep_analysis") and ctx.tab or "recipes"
	app._deepAnalysisTarget = nil
	app._deepAnalysisStack = nil
	app._deepAnalysisReturn = nil
	app.setTab(targetTab)
	if (targetTab == "recipes" or targetTab == "all_items" or targetTab == "vendor_crafter" or targetTab == "disenchant_crafter") and ctx.superListScrollPct ~= nil then
		local tbl = (targetTab == "vendor_crafter") and (app.ui and app.ui.vendorCrafterTable)
			or (targetTab == "disenchant_crafter") and (app.ui and app.ui.disenchantCrafterTable)
			or (targetTab == "all_items") and (app.ui and app.ui.allItemsTable)
			or (app.ui and app.ui.recipesTable)
		local sb = tbl and tbl.scrollBox
		if sb and sb.SetScrollPercentage then
			sb:SetScrollPercentage(ctx.superListScrollPct)
		end
	end
	if targetTab == "an_items" and ctx.analyticsDetailKey ~= nil then
		local anUI = ns.Analytics and ns.Analytics.UI
		if anUI and anUI.ShowItemDetail then
			anUI.ShowItemDetail(ctx.analyticsDetailKey)
		end
	end
	if ctx.wasQuickLookOpen then
		if ctx.quickLookWindow and MerchantMasterDB then
			MerchantMasterDB.quickLookWindow = ctx.quickLookWindow
		end
		local kind = ctx.quickLookKind or "recipe"
		local resolved = (resolveQuickLookRow and resolveQuickLookRow(kind, ctx.quickLookRow)) or ctx.quickLookRow
		if (targetTab == "recipes" or targetTab == "all_items" or targetTab == "vendor_crafter" or targetTab == "disenchant_crafter") and app.superListProvider and app.superListProvider.OpenQuickLook and resolved then
			app.superListProvider.OpenQuickLook(resolved, true, resolved.recipe, { kind = kind })
		elseif app.openQuickLook and resolved then
			app.openQuickLook(kind, resolved, { toggle = false })
		end
	end
	return true
end

local function isVisibleAndHovered(frame)
	if not (frame and frame.IsMouseOver) then return false end
	if frame.IsVisible and not frame:IsVisible() then return false end
	if frame.IsShown and not frame:IsShown() then return false end
	local ok, over = pcall(frame.IsMouseOver, frame)
	return ok and not (issecretvalue and issecretvalue(over)) and over == true
end

local superListContext = {
	theme = ns.Theme, parent = mainArea,
	setMinimumWidth = function(width) winChrome.window:SetMinimumWidth(width) end,
	-- Main area insets (216+12+12), plus scroll viewport insets.
	windowPadding = 268,
	sidebarParent = app.ui.sidebarOptionsHost,
	isActive = function() return panel:IsShown() and app.activeTab == "recipes" end,
	atAH = atAH,
	isAppearanceHovered = function()
		local hovered = isVisibleAndHovered
		local wowheadModal = app.ui.wowheadModal
		if hovered(app.ui.appearanceSwitch) or hovered(app.ui.optionsFrame)
			or hovered(app.ui.priceFmtBtn) or hovered(app.ui.optPriceFmtBtn)
		or hovered(app.ui.uiSkinBtn) or hovered(app.ui.optUiSkinBtn) or hovered(app.ui.tableStyleBtn) or hovered(app.ui.optTableStyleBtn) or hovered(wowheadModal)
			or (wowheadModal and wowheadModal:IsShown() and hovered(wowheadModal.urlBox)) then return true end
		local profUI = ns.MP and ns.MP.app and ns.MP.app.ui
		if hovered(app.ui.forgedModeSeg.frame) or hovered(app.ui.forgedHumanBtn)
			or (profUI and profUI.goalSeg and hovered(profUI.goalSeg.frame))
			or (profUI and profUI.browseGoalSeg and hovered(profUI.browseGoalSeg.frame))
			or (app.ui.charScopeSeg and hovered(app.ui.charScopeSeg.frame))
			or hovered(app.ui.knownAllCharsCheck) then return true end
		local menu = ns.Theme and ns.Theme.GetDropDownMenu and ns.Theme.GetDropDownMenu()
		if menu and menu:IsShown() then
			if hovered(menu) or hovered(menu._appleBg) then return true end
			for _, row in ipairs(menu.rows or {}) do
				if hovered(row) then return true end
			end
		end
		return hovered(_G.DropDownList1) or hovered(_G.DropDownList2)
	end,
	openWowheadPopup = function(...) return app.openWowheadPopup(...) end,
	openCraftingOrder = function(...) return app.openCraftingOrder(...) end,
	getRecipeShoppingQty = function(...) return app.getRecipeShoppingQty and app.getRecipeShoppingQty(...) or 0 end,
	adjustRecipeShoppingQty = function(...) return app.adjustRecipeShoppingQty and app.adjustRecipeShoppingQty(...) end,
	hasUnifiedShoppingItems = function() return app.hasUnifiedShoppingItems and app.hasUnifiedShoppingItems() end,
	addUnifiedShoppingItem = function(...) return app.addUnifiedShoppingItem and app.addUnifiedShoppingItem(...) end,
	createSortableTable = createSortableTable, applyRowHighlight = applyRowHighlight,
	createAbleCell = createAbleCell, bindAbleCell = bindAbleCell, setCellBold = setCellBold,
	rowHeight = ROW_H, getOwnedCounts = ownedCounts, getActiveEconomy = ns.CurrentEconomyInfo,
	refresh = function() return app.refresh() end,
	getActiveTab = function() return app.activeTab end,
	getQuickLookContext = function()
		local context = {}
		for key, value in pairs(app.getRecipeStatsContext()) do context[key] = value end
		local db = MerchantMasterDB or {}
		context.writMode = db.writMode
		context.crateMode = db.crateMode
		context.forgedMode = db.forgedMode or "self_funded"
		context.forgedHumanDiplomacy = db.forgedHumanDiplomacy
		context.humanDiplomacy = db.forgedHumanDiplomacy
		return context
	end,
	addQuickLookItem = function(...) return app.addQuickLookItem(...) end,
	openDeepAnalysis = function(spec, ret) return app.openDeepAnalysis(spec, ret) end,
	resolveQuickLookRow = resolveQuickLookRow,
	isQuickLookRowHovered = function()
		for _, key in ipairs({ "cratesTable", "writsTable", "forgedTable", "profitSpreadTable", "outliersTable", "allItemsTable", "vendorCrafterTable" }) do
			local tableView = app.ui[key]
			if tableView and tableView.scrollBox and tableView.scrollBox.ForEachFrame then
				local hovered = false
				tableView.scrollBox:ForEachFrame(function(frame)
					if hovered or not frame.data then return end
					hovered = isVisibleAndHovered(frame) or isVisibleAndHovered(frame.cells and frame.cells[1])
						or isVisibleAndHovered(frame.cells and frame.cells[2])
						or (key == "forgedTable" and isVisibleAndHovered(frame.cells and frame.cells[12]))
				end)
				if hovered then return true end
			end
		end
		local profUI = ns.MP and ns.MP.app and ns.MP.app.ui
		if profUI then
			for _, tableView in ipairs({ profUI.pathTable, profUI.browseTable }) do
				if tableView and tableView.forEachRow then
					local hovered = false
					tableView.forEachRow(function(frame)
						if hovered or not frame.data then return end
						hovered = isVisibleAndHovered(frame) or isVisibleAndHovered(frame.cells and frame.cells[1])
							or isVisibleAndHovered(frame.cells and frame.cells[3])
							or isVisibleAndHovered(frame.cells and frame.cells[13])
							or isVisibleAndHovered(frame.shiftStepper)
					end)
					if hovered then return true end
				end
			end
		end
		for _, key in ipairs({ "dashCraftRows", "dashOutlierRows", "dashTurninRows" }) do
			for _, row in ipairs(app.ui[key] or {}) do
				if isVisibleAndHovered(row) or isVisibleAndHovered(row.nameHover) then return true end
			end
		end
		return false
	end,
	tryQuickLookChatLink = function(...) return app.tryQuickLookChatLink(...) end,
	resetSuperListFilters = function() return app.resetSuperListFilters() end,
	toggleScreenFilters = function(anchor) return app.toggleScreenFilters and app.toggleScreenFilters(anchor) end,
	getSort = function() return app.sortState.recipes end,
	selectRecipe = function(itemID) app.selectedRecipeItemID = itemID end,
	toggleShoppingWindow = function(force) return app.toggleShoppingWindow(force) end,
	searchAH = function(...) return app.searchAH(...) end,
	multiSearchBuyer = function(...) return app.multiSearchBuyer(...) end,
	showSingleCraftShoppingPreview = function(...) return app.showSingleCraftShoppingPreview(...) end,
	sellableFilters = SELLABLE_FILTERS, sourceFilters = SOURCE_FILTERS,
	statusText = app.ui.statusText,
	sidebar = {
		sellBtn = app.ui.sellBtn, originBtn = app.ui.originBtn, merchantOnlyCheck = app.ui.merchantOnlyCheck,
		recipeSourcesBtn = app.ui.recipeSourcesBtn, recCraftFilterBtn = app.ui.recCraftFilterBtn,
		recDemandFilterBtn = app.ui.recDemandFilterBtn, bisOnlyCheck = app.ui.bisOnlyCheck,
		subCraftBtn = app.ui.subCraftBtn,
	},
}

