		{ rank = 6, label = "Honored (99)" },
		{ rank = 7, label = "Revered (1)" },
		{ rank = 8, label = "Exalted (2)" },
	}
	app.ui.rankBtns = {}
	do
		local rx = 0
		for _, rd in ipairs(rankFilterDefs) do
			local b = CreateFrame("Button", nil, repView, "UIPanelButtonTemplate")
			b:SetSize(112, 24)
			b:SetPoint("TOPLEFT", rx, -180)
			b:SetText(rd.label)
			ns.Theme.SkinButton(b, { variant = "secondary", pill = true, fontSize = 11 })
			local targetRank = rd.rank
			b:SetScript("OnClick", function()
				if MerchantMasterDB then MerchantMasterDB.repRankFilter = targetRank end
				app.refresh()
			end)
			app.ui.rankBtns[rd.rank] = b
			rx = rx + 116
		end
		local repResetBtn = app.createResetFiltersButton(repView, "repResetBtn", "resetRepViewFilters")
		repResetBtn:SetPoint("TOPLEFT", rx, -180)
		local repFiltersBtn = app.createFiltersButton(repView, "repFiltersBtn", repResetBtn, true)
		app.ui.repHintFs = repView:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
		app.ui.repHintFs:SetPoint("LEFT", repFiltersBtn, "RIGHT", 8, 0)
		app.ui.repHintFs:SetPoint("RIGHT", repView, "TOPRIGHT", -4, -192)
		app.ui.repHintFs:SetJustifyH("RIGHT")
		app.ui.repHintFs:SetWordWrap(false)
		applySafeFont(app.ui.repHintFs, 11, "regular")
	end

	ns.Theme.RegisterWidget(repView, function()
		local pal = getPal()
		local sep = pal.glassSep or pal.separator or { 1, 1, 1, 0.08 }
		if summaryBox.surface and summaryBox.surface.UpdateTheme then summaryBox.surface:UpdateTheme(pal.cardBg, false) end
		if repTitleFs and pal.text then repTitleFs:SetTextColor(pal.text[1], pal.text[2], pal.text[3], 1) end
		if repSubFactionFs and pal.textSecondary then repSubFactionFs:SetTextColor(pal.textSecondary[1], pal.textSecondary[2], pal.textSecondary[3], 1) end
		if repNumFs and pal.textSecondary then repNumFs:SetTextColor(pal.textSecondary[1], pal.textSecondary[2], pal.textSecondary[3], 1) end
		if repTierLeftFs then
			local mc = pal.textTertiary or pal.textMuted
			if mc then repTierLeftFs:SetTextColor(mc[1], mc[2], mc[3], mc[4] or 1) end
		end
		if repTierRightFs then
			local mc = pal.textTertiary or pal.textMuted
			if mc then repTierRightFs:SetTextColor(mc[1], mc[2], mc[3], mc[4] or 1) end
		end
		for _, tile in ipairs({ repFavorTile, repUnlocksTile }) do
			if tile.surface and tile.surface.UpdateTheme then tile.surface:UpdateTheme(pal.cardAltBg, false) end
			local mc = pal.textTertiary or pal.textMuted
			if mc then tile.lblFs:SetTextColor(mc[1], mc[2], mc[3], mc[4] or 1) end
			if pal.text then tile.valFs:SetTextColor(pal.text[1], pal.text[2], pal.text[3], 1) end
		end
		if repVDiv then repVDiv:SetColorTexture(sep[1], sep[2], sep[3], sep[4] or 0.08) end
		if repRightSep then repRightSep:SetColorTexture(sep[1], sep[2], sep[3], sep[4] or 0.08) end
		for _, hfs in ipairs(milestoneHdrs) do
			local mc = pal.textTertiary or pal.textMuted
			if mc then hfs:SetTextColor(mc[1], mc[2], mc[3], mc[4] or 1) end
		end
		for _, mb in ipairs(app.ui.milestoneRows or {}) do
			if mb.sep then mb.sep:SetColorTexture(sep[1], sep[2], sep[3], sep[4] or 0.08) end
			if mb.cells then
				for ci, cfs in ipairs(mb.cells) do
					local tc = (ci == 6 and pal.textSecondary) or pal.text
					if tc and cfs.SetTextColor then cfs:SetTextColor(tc[1], tc[2], tc[3], tc[4] or 1) end
				end
			end
		end
		if app.ui.repHintFs and pal.textSecondary then
			app.ui.repHintFs:SetTextColor(pal.textSecondary[1], pal.textSecondary[2], pal.textSecondary[3], 1)
		end
	end)

	-- 10 Columns: 4 + (214+98+76+46+56+72+90+90+68+142) + 9*5 = 1001px <= 1048px
	local UNLOCK_COLS = {
		{ key = "name",          label = "Unlocked Reward / Recipe", width = 214, align = "LEFT",   hint = "Camp vendor recipe, mount, pet, toy or tabard" },
		{ key = "category",      label = "Type / Prof",              width = 98,  align = "LEFT",   hint = "Profession or reward category" },
		{ key = "repSort",       label = "Rep Rank",                 width = 76,  align = "LEFT",   hint = "Required Merchant Reputation standing" },
		{ key = "skill",         label = "Skill",                    width = 46,  align = "RIGHT",  hint = "Required Profession Skill rank" },
		{ key = "sellableSort",  label = "Sellable",                 width = 56,  align = "CENTER", defaultAsc = false, hint = "Whether crafted output can be sold on AH" },
		{ key = "favorCost",     label = "Favor Cost",               width = 72,  align = "RIGHT",  hint = "Merchant's Favor currency needed to buy from camp vendor" },
		{ key = "favorGoldCost", label = "Est. Favor Gold",          width = 90, minWidth = 92,  align = "RIGHT",  hint = "Estimated gold cost of those Favor tokens using #1 Waylaid Crate" },
		{ key = "craftProfit",   label = "Craft Profit",             width = 90, minWidth = 98,  align = "RIGHT",  defaultAsc = false, hint = "Per-craft net AH profit once learned (for sellable recipes)" },
		{ key = "dailySold",     label = "Sales / Day",              width = 68,  align = "RIGHT",  defaultAsc = false, hint = "Average daily sales of crafted output" },
		{ key = "statusSort",    label = "Status",                   width = 142, align = "LEFT",   hint = "Current unlock state on your character" },
	}

	app.ui.repTable = createSortableTable(repView, -210, "rep", UNLOCK_COLS, function(r, data, tbl)
		if not r.cells then
			applyRowHighlight(r)
			r.cells = {}
			for i, col in ipairs(tbl.columns) do
				if i == 1 then
					local btn = CreateFrame("Button", nil, r)
					btn:SetSize(col.width, ROW_H)
					btn:SetPoint("LEFT", r, "LEFT", tbl.colX[i], 0)
					btn.icon = btn:CreateTexture(nil, "ARTWORK")
					btn.icon:SetSize(16, 16)
					btn.icon:SetPoint("LEFT", 0, 0)
					btn.fs = btn:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
					btn.fs:SetPoint("LEFT", btn.icon, "RIGHT", 4, 0)
					btn.fs:SetPoint("RIGHT", 0, 0)
					btn.fs:SetJustifyH("LEFT")
					btn.fs:SetWordWrap(false)
					btn:SetScript("OnEnter", function(self)
						local d = self:GetParent().data
						if not d then return end
						GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
						if d.itemID and GameTooltip.SetItemByID then
							GameTooltip:SetItemByID(d.itemID)
						elseif d.itemID then
							GameTooltip:SetHyperlink("item:" .. d.itemID)
						else
							GameTooltip:AddLine(d.name, 1, 0.82, 0)
						end
						if d.note then
							GameTooltip:AddLine(" ")
							GameTooltip:AddLine(d.note, 0.8, 0.9, 1, true)
						end
						if d.recipe and d.recipe.effectText and d.recipe.effectText ~= "" then
							GameTooltip:AddLine(" ")
							GameTooltip:AddLine("Forever Effect: " .. d.recipe.effectText, 0.45, 1, 0.65, true)
						end
						if d.bisInfo and d.bisInfo.hasEval then
							GameTooltip:AddDoubleLine("Best in Class (" .. (d.bisInfo.classLabel or "") .. "):",
								d.bisInfo.isBiS and ("* YES (#1 of " .. tostring(d.bisInfo.total) .. ")") or string.format("#%d of %d (Best: %s)", d.bisInfo.rank, d.bisInfo.total, d.bisInfo.bestName or "#1"),
								0.85, 0.85, 0.85, d.bisInfo.isBiS and 1 or 0.8, d.bisInfo.isBiS and 0.84 or 0.85, d.bisInfo.isBiS and 0 or 0.85)
						end
						GameTooltip:Show()
					end)
					btn:SetScript("OnLeave", GameTooltip_Hide)
					btn:SetScript("OnClick", function(self)
						local d = self:GetParent().data
						if d and d.sellable and d.itemID then app.searchAH(d.name, 1, d.itemID) end
					end)
					r.cells[i] = btn
				else
					local fs = r:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
					fs:SetSize(col.width, ROW_H)
					fs:SetPoint("LEFT", r, "LEFT", tbl.colX[i], 0)
					fs:SetJustifyH(col.align)
					fs:SetWordWrap(false)
					r.cells[i] = fs
				end
			end
		end

		r.data = data
		r.stripe:SetColorTexture(0, 0, 0, 0)

		local nCol = data.isSpecial and palHex("hexBlue", "0091ff") or palHex("hexPositive", "30d158")
		r.cells[1].icon:SetTexture(data.icon)
		r.cells[1].fs:SetText(nCol .. data.name .. "|r")
		r.cells[2]:SetText(palHex("hexSecondary", "ebebf5") .. data.category .. "|r")
		local rColors = {
			[4] = palHex("hexText", "ffffff"),
			[5] = palHex("hexPositive", "30d158"),
			[6] = palHex("hexBlue", "0091ff"),
			[7] = palHex("hexPurple", "bf5af2"),
			[8] = palHex("hexWarning", "ff9230"),
		}
		r.cells[3]:SetText((rColors[data.rep] or palHex("hexText", "ffffff")) .. data.repName .. "|r")
		r.cells[4]:SetText(data.skill and tostring(data.skill) or (palHex("hexMuted", "98989d") .. "—|r"))
		r.cells[5]:SetText(data.sellable and (palHex("hexPositive", "30d158") .. "Yes|r") or (palHex("hexMuted", "98989d") .. "No|r"))
		local fIcon = favorIconMarkup()
		r.cells[6]:SetText((data.favorCost and data.favorCost > 0) and (tostring(data.favorCost) .. (fIcon ~= "" and (" " .. fIcon) or " F")) or (palHex("hexPositive", "30d158") .. "Free|r"))
		r.cells[7]:SetText(data.favorGoldCost ~= nil and ns.FormatMoneyCompact(data.favorGoldCost) or (palHex("hexMuted", "98989d") .. "—|r"))
		r.cells[8]:SetText(data.craftProfit ~= nil and ns.FormatMoneyCompact(data.craftProfit, true) or (palHex("hexMuted", "98989d") .. "—|r"))
		r.cells[9]:SetText(themeText(ns.Theme.FormatSalesPerDay(data.dailySold)))
		r.cells[10]:SetText(themeText(data.statusText or ""))
	end)
end

---------------------------------------------------------------------------------------------------
-- Calculators View (Calc 1: Favor Tokens & Calc 2: Reputation Target + Stock-Aware Shopping Lists)

do
	local calcView = CreateFrame("Frame", nil, mainArea)
	calcView:SetPoint("TOPLEFT", 0, -30)
	calcView:SetPoint("BOTTOMRIGHT", 0, 0)
	calcView:Hide()
	app.ui.calcView = calcView

	-- 2-Row Calculator Mode Switcher, Input Controls & Summary Banner (top 58px of calcView)
	local banner = CreateFrame("Frame", nil, calcView, "InsetFrameTemplate")
	banner:SetPoint("TOPLEFT", 0, -1)
	banner:SetPoint("TOPRIGHT", 0, -1)
	banner:SetHeight(58)
	applyListBackground(banner)

	-- Row 1: Segmented Sub-Tabs (Calculator 1: Favor Tokens | Calculator 2: Reputation Target | Shopping List) + Live Summary
	local calcSubFavorBtn = ns.Theme.CreatePlateButton(banner, "Calculator 1: Favor Tokens", 190, 22)
	calcSubFavorBtn:SetPoint("TOPLEFT", 8, -6)
	calcSubFavorBtn:SetScript("OnClick", function()
		if MerchantMasterDB then MerchantMasterDB.calcMode = "favor" end
		app.lastSubTab.token = "calc_favor"
		app.setTab("calc_favor")
	end)
	app.ui.calcSubFavorBtn = calcSubFavorBtn

	local calcSubRepBtn = ns.Theme.CreatePlateButton(banner, "Calculator 2: Reputation Target", 206, 22)
	calcSubRepBtn:SetPoint("LEFT", calcSubFavorBtn, "RIGHT", 6, 0)
	calcSubRepBtn:SetScript("OnClick", function()
		if MerchantMasterDB then MerchantMasterDB.calcMode = "rep" end
		app.lastSubTab.reputation = "calc_rep"
		app.setTab("calc_rep")
	end)
	app.ui.calcSubRepBtn = calcSubRepBtn

	local calcOpenShopBtn = ns.Theme.CreatePlateButton(banner, "Shopping List", 112, 22)
	calcOpenShopBtn:SetPoint("LEFT", calcSubRepBtn, "RIGHT", 6, 0)
	calcOpenShopBtn:SetScript("OnClick", function() app.toggleShoppingWindow(true) end)
	app.ui.calcOpenShopBtn = calcOpenShopBtn

	local function appendCalculatorDemand(demand, rows)
		for _, row in ipairs(rows or {}) do
			if not row.isSubRow and row.itemID and (row.qty or 0) > 0 then
				demand[#demand + 1] = { itemID = row.itemID, qty = row.qty, role = row.role or "Calc",
					forceMakeMyself = row.makeMyself or nil }
			end
		end
	end

	local calcAddShopBtn = ns.Theme.CreatePlateButton(banner, "+ Add to List", 104, 22, { primary = true })
	calcAddShopBtn:SetPoint("LEFT", calcOpenShopBtn, "RIGHT", 6, 0)
	calcAddShopBtn:SetScript("OnClick", function()
		local res = app.lastCalcResult
		if not (res and app.addUnifiedShoppingItem) then return end
		local db = MerchantMasterDB or {}
		local isRep = app.activeTab == "calc_rep" or (app.activeTab == "calc" and db.calcMode == "rep")
		local demand = {}
		appendCalculatorDemand(demand, res.shoppingList)
		if (not res.shoppingList or #res.shoppingList == 0) and isRep and db.repSourceMode == "forged_only" then
			for _, row in ipairs(res.forgedRows or {}) do
				local id, count = row.crateID or row.itemID, row.count or row.receiptCount or 1
				if id and count > 0 then
					local before = #demand
					if ns.BuildForgedTurnInShoppingList then
						local plan = ns.BuildForgedTurnInShoppingList(row, count, {
							forgedMode = row.forgedMode or res.forgedMode or db.forgedMode,
							humanDiplomacy = db.forgedHumanDiplomacy,
							bestFavorCrate = row.bestFavorCrate or row.feederCrate,
							subCraftMode = db.subCraftMode, subCraftOverrides = db.subCraftOverrides,
						})
						appendCalculatorDemand(demand, plan and plan.shoppingList)
					end
					if #demand == before then
						demand[#demand + 1] = { itemID = id, qty = count, role = "Crate" }
					end
				end
			end
		end
		if #demand == 0 then return end
		local label = isRep
			and ("Rep Plan -> " .. tostring(res.targetName or "Target"))
			or ("Favor Plan (" .. tostring(res.netTargetTokens or 0) .. " tokens)")
		app.addUnifiedShoppingItem({
			key = "calc:" .. tostring(app.activeTab or "plan"),
			name = label,
			qty = 1,
			isBundle = true,
			sourceLabel = isRep and "Rep Calc" or "Favor Calc",
			demandList = demand,
		})
	end)
	app.ui.calcAddShopBtn = calcAddShopBtn

	local favorResetBtn = app.createResetFiltersButton(banner, "favorResetBtn", "resetFavorCalcFilters")
	favorResetBtn:SetPoint("TOPRIGHT", -8, -5)
	local repCalcResetBtn = app.createResetFiltersButton(banner, "repCalcResetBtn", "resetRepCalcFilters")
	repCalcResetBtn:SetPoint("TOPRIGHT", -8, -5)
	repCalcResetBtn:Hide()

	local favorSummaryFs = banner:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
	favorSummaryFs:SetPoint("LEFT", calcAddShopBtn, "RIGHT", 10, 0)
	favorSummaryFs:SetPoint("RIGHT", favorResetBtn, "LEFT", -10, 0)
	favorSummaryFs:SetJustifyH("RIGHT")
	favorSummaryFs:SetWordWrap(false)
	themeLabel(favorSummaryFs, 12)
	app.ui.favorSummaryFs = favorSummaryFs

	local repSummaryFs = banner:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
	repSummaryFs:SetPoint("LEFT", calcAddShopBtn, "RIGHT", 10, 0)
	repSummaryFs:SetPoint("RIGHT", repCalcResetBtn, "LEFT", -10, 0)
	repSummaryFs:SetJustifyH("RIGHT")
	repSummaryFs:SetWordWrap(false)
	if repSummaryFs.SetMaxLines then repSummaryFs:SetMaxLines(2) end
	themeLabel(repSummaryFs, 11)
	repSummaryFs:Hide()
	app.ui.repSummaryFs = repSummaryFs

	local rowSep = banner:CreateTexture(nil, "BORDER")
	rowSep:SetPoint("TOPLEFT", 8, -31)
	rowSep:SetPoint("TOPRIGHT", -8, -31)
	rowSep:SetHeight(1)
	themeSeparator(rowSep)

	-- Row 2 Mode A: Favor Token Calculator Controls
	local favorCtrl = CreateFrame("Frame", nil, banner)
	favorCtrl:SetPoint("TOPLEFT", 0, -31)
	favorCtrl:SetPoint("BOTTOMRIGHT", 0, 0)
	app.ui.favorCtrl = favorCtrl

	local fLbl = favorCtrl:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
	fLbl:SetPoint("LEFT", 10, 0)
	fLbl:SetText("Target Favor:")
	themeLabel(fLbl, 11, "semibold", "textSecondary")

	local favorInput = CreateFrame("EditBox", nil, favorCtrl, "InputBoxTemplate")
	favorInput:SetSize(74, 21)
	favorInput:SetPoint("LEFT", fLbl, "RIGHT", 6, 0)
	favorInput:SetAutoFocus(false)
	favorInput:SetMaxLetters(7)
	ns.Theme.StyleEditBox(favorInput)

	local function commitFavorTarget(rawText, forceDefault)
		if not MerchantMasterDB then return end
		local digits = tostring(rawText or ""):gsub("%D", "")
		local v = tonumber(digits)
		if v and v > 0 then
			MerchantMasterDB.calcFavorTarget = v
		elseif forceDefault then
			MerchantMasterDB.calcFavorTarget = math.max(1, tonumber(MerchantMasterDB.calcFavorTarget) or 150)
			favorInput:SetText(tostring(MerchantMasterDB.calcFavorTarget))
		elseif digits == "0" then
			MerchantMasterDB.calcFavorTarget = 0
		end
		app.refresh()
	end

	favorInput:SetScript("OnEscapePressed", function(self) self:ClearFocus() end)
	favorInput:SetScript("OnEnterPressed", function(self)
		self:ClearFocus()
		commitFavorTarget(self:GetText(), true)
	end)
	favorInput:SetScript("OnTextChanged", function(self, userInput)
		if not userInput then return end
		local cur = self:GetText() or ""
		local clean = cur:gsub("%D", "")
		if clean ~= cur then
			self:SetText(clean)
			return
		end
		local v = tonumber(clean)
		if v and v >= 0 and MerchantMasterDB then
			MerchantMasterDB.calcFavorTarget = v
			app.refresh()
		end
	end)
	app.ui.favorInput = favorInput

	local calcRunBtn = ns.Theme.CreatePlateButton(favorCtrl, "Calculate", 78, 21, { primary = true })
	calcRunBtn:SetPoint("LEFT", favorInput, "RIGHT", 6, 0)
	calcRunBtn:SetScript("OnClick", function()
		if favorInput.ClearFocus then favorInput:ClearFocus() end
		commitFavorTarget(favorInput:GetText(), true)
	end)
	app.ui.calcRunBtn = calcRunBtn

	local prevPreset = calcRunBtn
	app.ui.favorPresetBtns = {}
	for _, preset in ipairs({ 50, 150, 500, 1200, 6000 }) do
		local pb = CreateFrame("Button", nil, favorCtrl, "UIPanelButtonTemplate")
		pb:SetSize(46, 21)
		pb:SetPoint("LEFT", prevPreset, "RIGHT", 4, 0)
		pb:SetText(tostring(preset))
		ns.Theme.SkinButton(pb)
		local val = preset
		pb:SetScript("OnClick", function()
			if favorInput.ClearFocus then favorInput:ClearFocus() end
			if MerchantMasterDB then MerchantMasterDB.calcFavorTarget = val end
			favorInput:SetText(tostring(val))
			app.refresh()
		end)
		app.ui.favorPresetBtns[preset] = pb
		prevPreset = pb
	end

	local deductCheck = CreateFrame("CheckButton", nil, favorCtrl, "UICheckButtonTemplate")
	deductCheck:SetSize(22, 22)
	deductCheck:SetPoint("LEFT", prevPreset, "RIGHT", 8, 0)
	deductCheck.label = deductCheck:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
	deductCheck.label:SetPoint("LEFT", deductCheck, "RIGHT", 3, 0)
	deductCheck.label:SetText("Deduct My Favor")
	ns.Theme.SkinCheckButton(deductCheck)
	deductCheck:SetScript("OnClick", function(self)
		if MerchantMasterDB then MerchantMasterDB.calcDeductFavor = self:GetChecked() and true or false end
		app.refresh()
	end)
	app.ui.deductCheck = deductCheck

	local calcCrateModeBtn = CreateFrame("Button", nil, favorCtrl, "UIPanelButtonTemplate")
	calcCrateModeBtn:SetSize(164, 21)
	calcCrateModeBtn:SetPoint("LEFT", deductCheck.label, "RIGHT", 10, 0)
	calcCrateModeBtn:RegisterForClicks("LeftButtonUp", "RightButtonUp")
	ns.Theme.SkinButton(calcCrateModeBtn, { dropdown = true })
	calcCrateModeBtn:SetScript("OnClick", function(self, mouseBtn)
		if not MerchantMasterDB then return end
		if mouseBtn == "RightButton" then
			MerchantMasterDB.crateMode = "cheapest"
			app.refresh()
		else
			ns.Theme.OpenDropDown(self, CRATE_MODES, MerchantMasterDB.crateMode or "cheapest", function(k)
				MerchantMasterDB.crateMode = k
				app.refresh()
			end, 186)
		end
	end)
	app.ui.calcCrateModeBtn = calcCrateModeBtn

	local calcUseOwnedCheck = CreateFrame("CheckButton", nil, favorCtrl, "UICheckButtonTemplate")
	calcUseOwnedCheck:SetSize(22, 22)
	calcUseOwnedCheck:SetPoint("LEFT", calcCrateModeBtn, "RIGHT", 8, 0)
	calcUseOwnedCheck.label = calcUseOwnedCheck:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
	calcUseOwnedCheck.label:SetPoint("LEFT", calcUseOwnedCheck, "RIGHT", 3, 0)
	calcUseOwnedCheck.label:SetText("Use Owned")
	ns.Theme.SkinCheckButton(calcUseOwnedCheck)
	calcUseOwnedCheck:SetScript("OnClick", function(self)
		if MerchantMasterDB then MerchantMasterDB.calcUseOwned = self:GetChecked() and true or false end
		app.refresh()
	end)
	app.ui.calcUseOwnedCheck = calcUseOwnedCheck

	-- Row 2 Mode B: Reputation Target Calculator Controls
	local repCtrl = CreateFrame("Frame", nil, banner)
	repCtrl:SetPoint("TOPLEFT", 0, -31)
	repCtrl:SetPoint("BOTTOMRIGHT", 0, 0)
	repCtrl:Hide()
	app.ui.repCtrl = repCtrl

	local calcSimBtn = CreateFrame("Button", nil, repCtrl, "UIPanelButtonTemplate")
	calcSimBtn:SetSize(144, 21)
	calcSimBtn:SetPoint("LEFT", 8, 0)
	calcSimBtn:RegisterForClicks("LeftButtonUp", "RightButtonUp")
	ns.Theme.SkinButton(calcSimBtn, { dropdown = true })
	calcSimBtn:SetScript("OnClick", function(self, mouseBtn)
		if mouseBtn == "RightButton" then
			app.simStartIdx = 1
			app.refresh()
		else
			local simMenu = {}
			for idx, s in ipairs(SIM_START_OPTIONS) do
				simMenu[#simMenu + 1] = { key = idx, label = s.label }
			end
			ns.Theme.OpenDropDown(self, simMenu, app.simStartIdx or 1, function(pickedIdx)
				app.simStartIdx = pickedIdx
				app.refresh()
			end, 186)
		end
	end)
	app.ui.calcSimBtn = calcSimBtn

	local tLbl = repCtrl:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
	tLbl:SetPoint("LEFT", calcSimBtn, "RIGHT", 8, 0)
	tLbl:SetText("To:")
	themeLabel(tLbl, 11, "semibold", "textSecondary")

	app.ui.calcRepTargetBtns = {}
	local prevStage = tLbl
	for _, stg in ipairs({
		{ standing = 5, label = "Friendly" },
		{ standing = 6, label = "Honored" },
		{ standing = 7, label = "Revered" },
		{ standing = 8, label = "Exalted" },
	}) do
		local sb = CreateFrame("Button", nil, repCtrl, "UIPanelButtonTemplate")
		sb:SetSize(66, 21)
		sb:SetPoint("LEFT", prevStage, "RIGHT", 4, 0)
