		r.cells[2].fs:SetText(palHex(data.forged and "hexText" or "hexPositive") .. data.writName .. "|r")
		r.cells[3].fs:SetText(string.format("%dx %s", data.reqQtyEach, data.reqItemName))
		local zCol = palHex((data.zone and data.zone ~= "Unmapped") and "hexBlue" or "hexMuted")
		local zoneText = zCol .. tostring(data.zone or "Unmapped") .. "|r"
		if (not data.zone or data.zone == "Unmapped") and data.writ then
			local iz, zs = ns.GetWritZoneInfo(data.writ)
			if zs == "hint" then zoneText = palHex("hexMuted") .. iz .. " (likely)|r" end
