		r.cells[6]:SetText(palHex(modeInk) .. data.mode .. "|r")
		r.cells[7]:SetText(palHex("hexBlue") .. "+" .. formatComma(data.repTotal) .. "|r")
		r.cells[8]:SetText(ns.FormatMoneyCompact(data.grossCost or data.totalCost))
		-- Cost-mode money colours itself: a refund / net-profit (negative cost) renders "-" in positive green
		r.cells[9]:SetText((data.pouchRefund and data.pouchRefund > 0) and ns.FormatMoneyCompact(-data.pouchRefund) or zeroMoney("c"))
		r.cells[10]:SetText(ns.FormatMoneyCompact(data.totalCost))
		r.cells[11]:SetText(ns.FormatMoneyCompact(data.pricePerRep))
	end)

	function app.renderRepPlan(res, sourceMode)
		local rows = {}
		local hasForged = sourceMode == "forged_only"
		local function appendForged(row)
			hasForged = true
			local count = row.count or row.receiptCount or 1
			local repTotal = row.repTotal or (row.repEach or row.rep or res.effectiveRep or 50) * count
			local totalCost = row.totalCost or row.netCost
			local forgedMode = row.forgedMode or res.forgedMode or (MerchantMasterDB and MerchantMasterDB.forgedMode)
			local crateName = (row.shortName or row.crateName or row.name or row.writName or "Empty Crate"):gsub("^Waylaid Crate:%s*", "")
			local turnInItem = row.reqItemName
			if not turnInItem or turnInItem == row.name or turnInItem == row.crateName then
				turnInItem = (ns.FORGED_RECEIPT and ns.FORGED_RECEIPT.receiptName) or "Forged Delivery Receipt"
			end
			rows[#rows + 1] = {
				forged = true, crateID = row.crateID or row.itemID, crateFullName = row.crateFullName or row.name,
				count = count, writName = crateName, reqItemName = turnInItem, reqQtyEach = row.reqQtyEach or 1,
				zone = row.zone or "Crate Return", profSkillLabel = row.profSkillLabel or row.tier or "—",
				mode = forgedMode == "banked" and "Banked" or "Self-Funded",
				repTotal = repTotal, grossCost = row.grossCost or row.grossEmptyCost,
				pouchRefund = row.pouchRefund or row.totalRefund or ((row.forgedRefund or 0) + (row.favorRefund or 0)),
				totalCost = totalCost,
				pricePerRep = row.pricePerRep or row.costPerRep or (totalCost and repTotal > 0 and totalCost / repTotal) or nil,
			}
		end
		if res.repPlan then
			for _, row in ipairs(res.repPlan) do
				if row.forged or (row.crateID and not row.writID) then appendForged(row)
				else rows[#rows + 1] = row end
			end
		else
			for _, row in ipairs(res.writPlan or {}) do rows[#rows + 1] = row end
			for _, row in ipairs(res.forgedRows or {}) do appendForged(row) end
		end
		local tbl = app.ui.repPlanTable
		tbl.columns[1].label = hasForged and "# Turn-Ins" or "# Writs"
		tbl.columns[2].label = hasForged and "Writ / Empty Crate" or "Craftsman's Writ"
		tbl.columns[9].label = hasForged and "Refund" or "Pouch"
		local st = app.sortState.calc_rep
		ns.SortRows(rows, st.col, st.asc, "pricePerRep", { writName = true, reqItemName = true, zone = true, profSkillLabel = true, mode = true })
		tbl.updateHeaders()
		tbl.setRows(rows)
	end

	app.ui.calcShop = app.ui.shopPanel

	function app.runCalculatorDeepScan()
		local db = MerchantMasterDB or {}
		local ids, seen = {}, {}
		local function addID(id)
			if id and id > 0 and not seen[id] and not (ns.VENDOR_REAGENTS and ns.VENDOR_REAGENTS[id]) then
				seen[id] = true
				ids[#ids + 1] = id
			end
		end
		-- First add every item currently in the Calculator Shopping List
		if app.lastCalcResult and app.lastCalcResult.shoppingList then
			for _, srow in ipairs(app.lastCalcResult.shoppingList) do
				addID(srow.itemID)
			end
		end
		-- Then add top 12 cheapest candidate Crates/Writs + Reagents so runner-up combos also have exact multi-price ladders!
		if (db.calcMode or "favor") == "favor" then
			local rows = ns.BuildCrateRows({ crateMode = db.crateMode or "cheapest", profFilter = db.profFilter, unlockFilter = db.unlockFilter })
			ns.SortRows(rows, "pricePerToken", true, "pricePerToken")
			for i = 1, math.min(12, #rows) do
				addID(rows[i].crateID)
				addID(rows[i].reagentID)
			end
		elseif db.repSourceMode ~= "forged_only" then
			local rows = ns.BuildWritRows({ writMode = db.writMode or "cheapest", profFilter = db.profFilter, unlockFilter = db.unlockFilter })
			ns.SortRows(rows, "pricePerRep", true, "pricePerRep")
			for i = 1, math.min(12, #rows) do
				addID(rows[i].writID)
				addID(rows[i].reqItemID)
				for _, rg in ipairs(rows[i].craftBreakdown or {}) do
					addID(rg.itemID)
				end
			end
		end
		if db.calcMode == "rep" and (db.repSourceMode or "hybrid") ~= "writs_only" then
			for _, crate in ipairs(ns.CRATES or {}) do addID(crate.itemID or crate.crateID) end
		end
		app.scanOrderBookItems(ids, 500)
	end
end

