	local BAG_ROW, BAG_GAP = 18, 8
	local function initBagRow(r, data)
		if not r.text then
			r.icon = r:CreateTexture(nil, "ARTWORK")
			r.icon:SetSize(16, 16)
			r.text = r:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
			r.text:SetJustifyH("LEFT")
			r.text:SetWordWrap(false)
			themeLabel(r.text, 11)
			r.right = r:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
			r.right:SetJustifyH("RIGHT")
			themeLabel(r.right, 11)
			r.selected = r:CreateTexture(nil, "BACKGROUND")
			r.selected:SetAllPoints()
			if C_Texture and C_Texture.GetAtlasInfo and C_Texture.GetAtlasInfo("auctionhouse-ui-row-select") then
				r.selected:SetAtlas("auctionhouse-ui-row-select")
				r:SetHighlightAtlas("auctionhouse-ui-row-highlight", "ADD")
			else
				r.selected:SetTexture("Interface\\QuestFrame\\UI-QuestLogTitleHighlight")
				r.selected:SetVertexColor(1, 0.82, 0, 0.5)
				r:SetHighlightTexture("Interface\\QuestFrame\\UI-QuestTitleHighlight", "ADD")
			end
			r:SetScript("OnClick", function(self)
				if self.data.search then
					app.searchAH(self.data.search, self.data.qty, lookupID(self.data.search))
				elseif self.data.toggle then
					app.folded[self.data.toggle] = not app.folded[self.data.toggle] or nil
					app.refresh()
				end
			end)
			r.linkHit = CreateFrame("Button", nil, r)
			r.linkHit:SetHeight(BAG_ROW)
			r.linkHit:SetScript("OnEnter", function(self)
				local link = self:GetParent().data.link
				if link then
					GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
					suppressCratePostCall = true
					GameTooltip:SetHyperlink(link)
					suppressCratePostCall = false
					local id = tonumber(link:match("item:(%d+)"))
					if ns.AppendCrateTooltip then ns.AppendCrateTooltip(GameTooltip, id) end
					GameTooltip:Show()
				end
			end)
			r.linkHit:SetScript("OnLeave", GameTooltip_Hide)
			r.linkHit:SetScript("OnClick", forwardRowClick)
			r.scan = CreateFrame("Button", nil, r, "UIPanelButtonTemplate")
			r.scan:SetSize(56, 18)
			ns.Theme.SkinButton(r.scan, { readableDisabled = true })
			r.scan:SetScript("OnClick", function(self)
				ns.MarketScan.ScanBagCrates({ self:GetParent().data.crate })
			end)
		end
		r.data = data
		local top = data.gap and -BAG_GAP or 0
		r.icon:ClearAllPoints()
		r.text:ClearAllPoints()
		if data.icon then
			r.icon:SetTexture(data.icon)
			r.icon:SetPoint("TOPLEFT", 0, top - 1)
			r.icon:Show()
			r.text:SetPoint("LEFT", r.icon, "RIGHT", 4, 0)
		else
			r.icon:Hide()
			r.text:SetPoint("TOPLEFT", data.indent or 0, top - 3)
		end
		r.right:ClearAllPoints()
		if data.crate then
			r.scan:ClearAllPoints()
			r.scan:SetPoint("TOPRIGHT", -2, top)
			r.scan:SetText(data.scanning and "..." or "Scan")
			r.scan:SetEnabled(not data.scanning and data.atAH)
			r.scan:Show()
			r.right:SetPoint("RIGHT", r.scan, "LEFT", -6, 0)
		else
			r.scan:Hide()
			r.right:SetPoint("TOPRIGHT", -2, top - 3)
		end
		r.text:SetPoint("RIGHT", r.right, "LEFT", -6, 0)
		r.text:SetText(data.text)
		r.right:SetText(data.right or "")
		if data.link then
			r.linkHit:ClearAllPoints()
			r.linkHit:SetPoint("TOPLEFT", data.icon and r.icon or r.text, "TOPLEFT", 0, data.icon and 1 or 3)
			local nameWidth, columnWidth = r.text:GetStringWidth(), r.text:GetWidth()
			if columnWidth > 0 then nameWidth = math.min(nameWidth, columnWidth) end
			local iconWidth = data.icon and (r.icon:GetWidth() + 4) or 0
			r.linkHit:SetWidth(iconWidth + math.max(1, nameWidth))
		end
		r.linkHit:SetShown(data.link ~= nil)
		local hlTex = r.GetHighlightTexture and r:GetHighlightTexture()
		if hlTex then hlTex:SetShown(data.search ~= nil or data.toggle ~= nil) end
		r.selected:SetShown(data.search ~= nil and app.wanted ~= nil and data.search == app.wanted.name)
	end

	local bagLinearView = CreateScrollBoxListLinearView()
	bagLinearView:SetElementExtentCalculator(function(_, data)
		return data.gap and (BAG_ROW + BAG_GAP) or BAG_ROW
	end)
	bagLinearView:SetElementInitializer("Button", initBagRow)
	ScrollUtil.InitScrollBoxListWithScrollBar(box, bar, bagLinearView)

	local lastChk
	local function addBagCheck(label, onClick, readableDisabled)
		local chk = CreateFrame("CheckButton", nil, bagView, "UICheckButtonTemplate")
		chk:SetSize(24, 22)
		if lastChk then chk:SetPoint("BOTTOMLEFT", lastChk, "TOPLEFT", 0, 2) else chk:SetPoint("BOTTOMLEFT", 4, 4) end
		chk.label = chk:CreateFontString(nil, "OVERLAY", "GameFontNormalSmall")
		chk.label:SetPoint("LEFT", chk, "RIGHT", 3, 0)
		chk.label:SetText(label)
		ns.Theme.SkinCheckButton(chk, { readableDisabled = readableDisabled })
		chk:SetScript("OnClick", onClick)
		lastChk = chk
		return chk
	end

	app.ui.includeMail = addBagCheck("Include items in mail", function(self)
		MerchantMasterDB.includeMail = self:GetChecked() and true or false
		if ns.MapPins and ns.MapPins.OnEvent then ns.MapPins.OnEvent("HOST_CONTEXT_CHANGED") end
		app.invalidateRecipeStats("ownership")
		app.refresh()
	end)
	app.ui.includeBank = addBagCheck("Include items in bank", function(self)
		MerchantMasterDB.includeBank = self:GetChecked() and true or false
		if ns.MapPins and ns.MapPins.OnEvent then ns.MapPins.OnEvent("HOST_CONTEXT_CHANGED") end
		app.invalidateRecipeStats("ownership")
		app.refresh()
	end)
	app.ui.includeAlts = addBagCheck("Include items on alts", function(self)
		MerchantMasterDB.includeAlts = self:GetChecked() and true or false
		if ns.MapPins and ns.MapPins.OnEvent then ns.MapPins.OnEvent("HOST_CONTEXT_CHANGED") end
		app.invalidateRecipeStats("ownership")
		app.refresh()
	end)
	app.ui.hideWithAH = addBagCheck("Don't open automatically with the Auction House", function(self)
		local off = self:GetChecked() and true or false
		setAutoOpenAtAHDisabled(off)
		app.tellHowToUndo = off
	end, true)

	local nextBtn = CreateFrame("Button", nil, bagView, "UIPanelButtonTemplate")
	nextBtn:SetSize(104, 22)
	nextBtn:SetPoint("BOTTOMRIGHT", -2, 4)
	nextBtn:SetText("Next")
	ns.Theme.SkinButton(nextBtn, { primary = true, readableDisabled = true })
	nextBtn:SetScript("OnClick", function()
		if #app.queue == 0 then say("Nothing is missing."); return end
		local current = 0
		for i, name in ipairs(app.queue) do
			if app.wanted and app.wanted.name == name then current = i end
		end
		local targetName = app.queue[current % #app.queue + 1]
		app.searchAH(targetName, nil, lookupID(targetName))
	end)
	app.ui.nextBtn = nextBtn
	local bagsResetBtn = app.createResetFiltersButton(bagView, "bagsResetBtn", "resetBagsFilters")
	bagsResetBtn:SetPoint("BOTTOMRIGHT", nextBtn, "TOPRIGHT", 0, 4)
end

