-- Master Layout, Refresh & Tab Controller

local function bagPriceText(b)
	local p = b.price
	if not p then
		local id = lookupID(b.name)
		local mkt = id and ns.GetItemMarketPrice(id)
		if mkt then return moneyText(mkt * b.missing) end
		return "|cffff5555" .. string.format("Missing %d", b.missing) .. "|r"
	end
	if p.failed then return "|cffffd200No answer from Auction House, scan again.|r" end
	if not p.cost then return "|cffff5555Not listed|r" end
	if p.short then return "|cffff5555" .. string.format("%d short", p.short) .. "|r " .. moneyText(p.cost) end
	return moneyText(p.cost)
end

local function resolveMenuForTab(t, calcMode)
	if t == "deep_analysis" then return "deep_analysis" end
	if t == "console" or (type(t) == "string" and t:sub(1, 8) == "console_") then return "console" end
	if t == "sniper" or t == "sniper_gap" or t == "sniper_vendor" then return "sniper" end
	if t == "analytics" or (type(t) == "string" and t:sub(1, 3) == "an_") then return "analytics" end
	if t == "professor" or (type(t) == "string" and t:sub(1, 5) == "prof_") then return "professor" end
	if t == "dashboard" then return "dashboard" end
	if t == "profit_spread" or t == "outliers" or t == "recipes" or t == "all_items" or t == "vendor_crafter" or t == "disenchant_crafter" or t == "profit" then
		return "profit"
	end
	if t == "crates" or t == "calc_favor" or t == "token" or (t == "calc" and calcMode ~= "rep") then
		return "token"
	end
	if t == "writs" or t == "forged" or t == "rep" or t == "calc_rep" or t == "reputation" or (t == "calc" and calcMode == "rep") then
		return "reputation"
	end
	return "dashboard"
end

local VIEW_TITLES = {
	dashboard     = "Today's Overview",
	watchlist     = "Watchlist",
	profit_spread = "Market & Crafts",
	outliers      = "Market & Crafts",
	recipes       = "Market & Crafts",
	all_items     = "All Items",
	vendor_crafter = "Vendor Crafter",
	disenchant_crafter = "Disenchantment Crafter",
	crates        = "Crates & Writs",
	writs         = "Crates & Writs",
	forged        = "Forged delivery (rep)",
	rep           = "Crates & Writs",
	calc          = "Crates & Writs",
	calc_favor    = "Crates & Writs",
	calc_rep      = "Crates & Writs",
	an_overview   = "Ledger",
	an_ledger     = "Ledger",
	an_items      = "Ledger",
	an_portfolio  = "Ledger",
	an_invest     = "Ledger",
	an_writs      = "Ledger",
	prof_path     = "Leveling",
	prof_shop     = "Leveling",
	prof_browse   = "Leveling",
	sniper_gap    = "Gap Sniper",
	sniper_vendor = "Vendor Sniper",
	console_overview = "Console - Overview",
	console_database = "Console - Database",
	console_perf     = "Console - Performance & Debug",
	console_setup    = "Console - Snapshot Settings",
	console_settings = "Console - Settings",
	console_mail     = "Console - Mail",
	console_ui       = "Console - Addon UI",
	console_data     = "Console - Data & Maintenance",
	deep_analysis = "Deep Analysis",
}

app._minimized = false

local function applyPanelLayout()
	local t = app.activeTab
	local db = MerchantMasterDB or {}
	local calcMode = db.calcMode or "favor"
	if app._lastLayoutTab ~= t then
		ns.Theme.CloseDropDown()
		app._lastLayoutTab = t
	end

	if app._minimized and t ~= "bags" then
		if winChrome and winChrome.window and winChrome.window.SetCompact then
			winChrome.window:SetCompact(true)
		end
		panel._mmCompactBackdrop = false
		if winChrome and winChrome.outerGlass then winChrome.outerGlass:SetAlpha(0) end
		app.ui.bagHeaderTab:Hide()
		app.ui.backFullBtn:Hide()
		app.ui.openShopBtn:Hide()
		app.ui.topAuctionatorBtn:Hide()
		if winChrome.kpiPill then winChrome.kpiPill:Hide() end
		if winChrome.resizeGrip then winChrome.resizeGrip:Hide() end
		if winChrome.heightGrip then winChrome.heightGrip:Hide() end
		for _, md in ipairs(app.ui.menuDefs) do
			app.ui.menuBtns[md.key]:Hide()
		end
		app.ui.tabLine:Hide()
		app.ui.headerInfo:SetShown(false)
		app.ui.bagView:SetShown(false)
		app.ui.sidebar:SetShown(true)
		if app.ui.rightPane then app.ui.rightPane:SetShown(true) end
		if app.ui.toolbar then app.ui.toolbar:SetShown(true) end
		if app.ui.appearanceSwitch and app.ui.appearanceSwitch.frame then app.ui.appearanceSwitch.frame:SetShown(true) end
		if app.ui.topCartBtn then app.ui.topCartBtn:SetShown(true) end
		if app.ui.topTaskListBtn then app.ui.topTaskListBtn:SetShown(true) end
		if app.ui.topSendAuctionatorBtn then app.ui.topSendAuctionatorBtn:SetShown(true) end
		if app.ui.topDisenchantBtn then app.ui.topDisenchantBtn:SetShown(true) end
		if winChrome and winChrome.ahRefresh and winChrome.ahRefresh.button then
			winChrome.ahRefresh.button:SetShown(true)
		end
		if app.ui.mainArea then app.ui.mainArea:SetShown(false) end
		if app.sniperProvider and app.sniperProvider.Hide then app.sniperProvider.Hide() end
		if app.consoleProvider and app.consoleProvider.Hide then app.consoleProvider.Hide() end
		if app.ui.subStrip then app.ui.subStrip:SetShown(false) end
		if app.ui.viewTitleFs then
			app.ui.viewTitleFs:SetText(VIEW_TITLES[t] or "MerchantMaster")
		end
		if app.ui._updateTopCartButton then app.ui._updateTopCartButton() end
		if app.refreshSkinLayout then app.refreshSkinLayout() end
		return
	end

	if t ~= "bags" then
		winChrome.window:SetCompact(false)
		if t ~= "recipes" and t ~= "all_items" and t ~= "watchlist" and t ~= "vendor_crafter" and t ~= "disenchant_crafter" and winChrome.window.SetMinimumWidth then winChrome.window:SetMinimumWidth(1320) end
		winChrome.window:ApplyFull()
		app.ui.bagHeaderTab:Hide()
		app.ui.backFullBtn:Hide()
		app.ui.openShopBtn:Hide()
		app.ui.topAuctionatorBtn:Hide()
		if winChrome.kpiPill then winChrome.kpiPill:Hide() end
		if winChrome.resizeGrip then winChrome.resizeGrip:Show() end
		if winChrome.heightGrip then winChrome.heightGrip:Show() end
		for _, md in ipairs(app.ui.menuDefs) do
			app.ui.menuBtns[md.key]:Hide()
		end
	else
		winChrome.window:SetCompact(true)
		panel:SetScale(1)
		local ah = (AuctionHouseFrame and AuctionHouseFrame:IsShown() and AuctionHouseFrame)
			or (AuctionFrame and AuctionFrame:IsShown() and AuctionFrame)
		panel:SetSize(BAGS_W, ah and math.max(460, ah:GetHeight()) or BAGS_H)
		for _, md in ipairs(app.ui.menuDefs) do
			app.ui.menuBtns[md.key]:Hide()
		end
		app.ui.bagHeaderTab:ClearAllPoints()
		app.ui.bagHeaderTab:SetPoint("TOPLEFT", 14, -14)
		app.ui.bagHeaderTab:SetActive(true)
		app.ui.bagHeaderTab:Show()
		app.ui.backFullBtn:Show()
		app.ui.openShopBtn:Hide()
		app.ui.topAuctionatorBtn:Hide()
		if winChrome.kpiPill then winChrome.kpiPill:Hide() end
		if winChrome.resizeGrip then winChrome.resizeGrip:Hide() end
		if winChrome.heightGrip then winChrome.heightGrip:Hide() end
		if app.ui.sidebarOptionsHost then app.ui.sidebarOptionsHost:Hide() end
	end

	app.ui.tabLine:Hide()
	-- Compact bags layout hides both glass panes: give it the opaque window backdrop instead of see-through chrome
	panel._mmCompactBackdrop = (t == "bags")
	if winChrome and winChrome.outerGlass then winChrome.outerGlass:SetAlpha(t == "bags" and 1 or 0) end
	app.ui.sidebar:SetShown(t ~= "bags")
	if app.ui.rightPane then app.ui.rightPane:SetShown(t ~= "bags") end
	if app.ui.toolbar then app.ui.toolbar:SetShown(t ~= "bags") end
	if app.ui.appearanceSwitch and app.ui.appearanceSwitch.frame then app.ui.appearanceSwitch.frame:SetShown(t ~= "bags") end
	if app.ui.topCartBtn then app.ui.topCartBtn:SetShown(t ~= "bags") end
	if app.ui.topTaskListBtn then app.ui.topTaskListBtn:SetShown(t ~= "bags") end
	if app.ui.topSendAuctionatorBtn then app.ui.topSendAuctionatorBtn:SetShown(t ~= "bags") end
	if app.ui.topDisenchantBtn then app.ui.topDisenchantBtn:SetShown(t ~= "bags") end
	if winChrome and winChrome.ahRefresh and winChrome.ahRefresh.button then
		winChrome.ahRefresh.button:SetShown(t ~= "bags")
	end
	app.ui.mainArea:SetShown(t ~= "bags")
	app.ui.headerInfo:SetShown(false)
	app.ui.bagView:SetShown(t == "bags")

	if t == "bags" then
		if app.sniperProvider and app.sniperProvider.Hide then app.sniperProvider.Hide() end
		if app.consoleProvider and app.consoleProvider.Hide then app.consoleProvider.Hide() end
		if app.refreshSkinLayout then app.refreshSkinLayout() end
		return
	end

	if app.ui.viewTitleFs then
		app.ui.viewTitleFs:SetText(VIEW_TITLES[t] or "MerchantMaster")
	end

	local activeMenu = resolveMenuForTab(t, calcMode)
	for mkey, btn in pairs(app.ui.menuBtns) do
		btn:SetActive(mkey == activeMenu)
	end

	-- Update 10-item Fable Sidebar Nav active state
	local navTab = (t == "deep_analysis" and app._deepAnalysisReturn and app._deepAnalysisReturn.tab) or t
	local activeNav = "dashboard"
	if navTab == "dashboard" then
		activeNav = "dashboard"
	elseif navTab == "watchlist" then
		activeNav = "watchlist"
	elseif navTab == "profit_spread" then
		activeNav = "profit_spread"
	elseif navTab == "outliers" then
		activeNav = "outliers"
	elseif navTab == "recipes" then
		activeNav = "recipes"
	elseif navTab == "all_items" then
		activeNav = "all_items"
	elseif navTab == "vendor_crafter" then
		activeNav = "vendor_crafter"
	elseif navTab == "disenchant_crafter" then
		activeNav = "disenchant_crafter"
	elseif navTab == "crates" or navTab == "calc_favor" or (navTab == "calc" and calcMode ~= "rep") then
		activeNav = "crates"
	elseif navTab == "writs" then
		activeNav = "writs"
	elseif navTab == "forged" then
		activeNav = "forged"
	elseif navTab == "rep" or navTab == "calc_rep" or (navTab == "calc" and calcMode == "rep") then
		activeNav = "reputation"
	elseif type(navTab) == "string" and navTab:sub(1, 5) == "prof_" then
		activeNav = "prof_path"
	elseif type(navTab) == "string" and navTab:sub(1, 3) == "an_" then
		activeNav = "an_overview"
	elseif navTab == "sniper_gap" then
		activeNav = "sniper_gap"
	elseif navTab == "sniper_vendor" then
		activeNav = "sniper_vendor"
	elseif type(navTab) == "string" and navTab:sub(1, 8) == "console_" then
		activeNav = "console"
	end
	app.ui._activeNavKey = activeNav
	local pal = getPal()
	for _, nb in ipairs(app.ui.navOrder or {}) do
		local isAct = (nb.key == activeNav)
		if nb.activeBg and nb.activeBg.SetShown then nb.activeBg:SetShown(isAct) end
		if nb.labelFs and pal then
			applySafeFont(nb.labelFs, 13, isAct and "semibold" or "regular")
			local tc = isAct and pal.text or pal.textSecondary
			if tc then nb.labelFs:SetTextColor(tc[1], tc[2], tc[3], 1) end
		end
		if nb.iconTex and pal then
			local ic = isAct and pal.text or pal.textSecondary
			if ic then nb.iconTex:SetVertexColor(ic[1], ic[2], ic[3], 1) end
		end
	end

	local isCalcView = (t == "calc" or t == "calc_favor" or t == "calc_rep")
	local showSubStrip = (activeMenu == "analytics" or activeMenu == "professor" or isCalcView)
	if app.ui.subStrip then app.ui.subStrip:SetShown(showSubStrip) end

	app.ui.dashSubHdr:SetShown(false)
	app.ui.tokenSubBar:SetShown(showSubStrip and activeMenu == "token")
	app.ui.repSubBar:SetShown(showSubStrip and activeMenu == "reputation")
	if app.ui.analyticsSubBar then app.ui.analyticsSubBar:SetShown(activeMenu == "analytics") end
	if activeMenu == "analytics" and app.ui.analyticsSubBar then app.ui.analyticsSubBar:SetActiveKey(t) end
	if app.ui.analyticsView then app.ui.analyticsView:SetShown(activeMenu == "analytics") end
	if app.ui.profSubBar then app.ui.profSubBar:SetShown(activeMenu == "professor") end
	if activeMenu == "professor" and app.ui.profSubBar then app.ui.profSubBar:SetActiveKey(t) end
	if app.ui.professorView then app.ui.professorView:SetShown(activeMenu == "professor") end

	if activeMenu == "token" then
		app.ui.tokenSubBar:SetActiveKey((t == "calc" or t == "calc_favor") and "calc_favor" or t)
	elseif activeMenu == "reputation" then
		app.ui.repSubBar:SetActiveKey((t == "calc" or t == "calc_rep") and "calc_rep" or t)
	end

	app.ui.dashboardView:SetShown(t == "dashboard")
	if t == "dashboard" and app.syncDashboardMode then app.syncDashboardMode() end
	local showWatchlist = (t == "watchlist")
	if app.ui.watchlistView and app.ui.watchlistView:IsShown() ~= showWatchlist then
		app.ui.watchlistView:SetShown(showWatchlist)
	end
	if app.watchlistProvider then app.watchlistProvider.Layout(mainArea:GetWidth(), mainArea:GetHeight()) end
	app.ui.profitSpreadView:SetShown(t == "profit_spread")
	app.ui.outliersView:SetShown(t == "outliers")
	app.ui.cratesView:SetShown(t == "crates")
	app.ui.writsView:SetShown(t == "writs")
	app.ui.forgedView:SetShown(t == "forged")
	local showRecipes = (t == "recipes")
	if app.ui.recipesView and app.ui.recipesView:IsShown() ~= showRecipes then
		app.ui.recipesView:SetShown(showRecipes)
	end
	if app.superListProvider then app.superListProvider.Layout(mainArea:GetWidth(), mainArea:GetHeight()) end
	local showAllItems = (t == "all_items")
	if app.ui.allItemsView and app.ui.allItemsView:IsShown() ~= showAllItems then
		app.ui.allItemsView:SetShown(showAllItems)
	end
	if app.allItemsProvider then app.allItemsProvider.Layout(mainArea:GetWidth(), mainArea:GetHeight()) end
	local showVendorCrafter = (t == "vendor_crafter")
	if app.ui.vendorCrafterView and app.ui.vendorCrafterView:IsShown() ~= showVendorCrafter then
		app.ui.vendorCrafterView:SetShown(showVendorCrafter)
	end
	if app.vendorCrafterProvider then app.vendorCrafterProvider.Layout(mainArea:GetWidth(), mainArea:GetHeight()) end
	local showDisenchantCrafter = (t == "disenchant_crafter")
	if app.ui.disenchantCrafterView and app.ui.disenchantCrafterView:IsShown() ~= showDisenchantCrafter then
		app.ui.disenchantCrafterView:SetShown(showDisenchantCrafter)
	end
	if app.disenchantCrafterProvider then app.disenchantCrafterProvider.Layout(mainArea:GetWidth(), mainArea:GetHeight()) end
	app.ui.repView:SetShown(t == "rep")
	app.ui.calcView:SetShown(isCalcView)
	if app.ui.deepAnalysisView then app.ui.deepAnalysisView:SetShown(t == "deep_analysis") end
	local showSniper = (t == "sniper_gap" or t == "sniper_vendor")
	if app.sniperProvider then
		if showSniper then
			app.sniperProvider.Show(t)
		else
			app.sniperProvider.Hide()
		end
	elseif app.ui.sniperView then
		app.ui.sniperView:SetShown(showSniper)
	end
	local showConsole = (type(t) == "string" and t:sub(1, 8) == "console_")
	if app.consoleProvider then
		if showConsole then
			app.consoleProvider.Show(t)
		else
			app.consoleProvider.Hide()
		end
	elseif app.ui.consoleView then
		app.ui.consoleView:SetShown(showConsole)
	end
	if panel:IsShown() and app.layoutWindow then app.layoutWindow() end

	-- Contextual Left Sidebar Panel Options
	if activeMenu == "professor" then
		if app.professorProvider and app.professorProvider.sidebarControls then
			local ok, ctrls = pcall(app.professorProvider.sidebarControls, t)
			if ok and type(ctrls) == "table" then
				app.layoutSidebarOptions(ctrls)
			else
				app.layoutSidebarOptions({})
			end
		else
			app.layoutSidebarOptions({})
		end
	elseif activeMenu == "analytics" then
		if app.analyticsProvider and app.analyticsProvider.sidebarControls then
			local ok, ctrls = pcall(app.analyticsProvider.sidebarControls, t)
			if ok and type(ctrls) == "table" then
				app.layoutSidebarOptions(ctrls)
			else
				if not app._anErrLogged then
					app._anErrLogged = true
					say("Analytics UI error: " .. tostring(ok and "sidebarControls must return a table" or ctrls))
				end
				app.analyticsProvider = nil
				app.layoutSidebarOptions({})
			end
		else
			app.layoutSidebarOptions({})
		end
	elseif t == "dashboard" then
		app.layoutSidebarOptions({ app.ui.dashResetFiltersBtn, app.ui.dashScopeBtn, app.ui.recipeSourcesBtn, app.ui.crateTooltipCheck })
	elseif t == "watchlist" then
		app.layoutSidebarOptions(app.watchlistProvider and app.watchlistProvider.GetSidebarControls() or {})
	elseif t == "profit_spread" then
		app.layoutSidebarOptions({ app.ui.spreadResetFiltersBtn, app.ui.spreadCountBtn, app.ui.diversifyCheck, app.ui.recipeSourcesBtn, app.ui.recCraftFilterBtn, app.ui.recDemandFilterBtn, app.ui.subCraftBtn, app.ui.clearSpreadQueueBtn })
	elseif t == "outliers" then
		app.layoutSidebarOptions({ app.ui.outliersResetFiltersBtn, app.ui.outlierScopeBtn, app.ui.outlierQualityBtn, app.ui.recipeSourcesBtn, app.ui.recCraftFilterBtn, app.ui.subCraftBtn, app.ui.resetOutlierPricesBtn })
	elseif t == "recipes" then
		app.layoutSidebarOptions(app.superListProvider and app.superListProvider.GetSidebarControls() or {})
	elseif t == "all_items" then
		app.layoutSidebarOptions(app.allItemsProvider and app.allItemsProvider.GetSidebarControls() or {})
	elseif t == "vendor_crafter" then
		app.layoutSidebarOptions(app.vendorCrafterProvider and app.vendorCrafterProvider.GetSidebarControls() or {})
	elseif t == "disenchant_crafter" then
		app.layoutSidebarOptions(app.disenchantCrafterProvider and app.disenchantCrafterProvider.GetSidebarControls() or {})
	elseif t == "crates" then
		app.layoutSidebarOptions({ app.ui.cratesResetFiltersBtn, app.ui.crateModeBtn, app.ui.bestOnlyCheck, app.ui.crateTooltipCheck, app.ui.subCraftBtn })
	elseif t == "writs" then
		app.layoutSidebarOptions({ app.ui.writsResetFiltersBtn, app.ui.writModeBtn, app.ui.writZoneBtn, app.ui.writPouchCheck, app.ui.subCraftBtn, app.ui.clearWritRouteBtn })
	elseif t == "forged" then
		app.layoutSidebarOptions({ app.ui.forgedResetFiltersBtn, app.ui.subCraftBtn, app.ui.crateTooltipCheck })
	elseif t == "rep" then
		app.layoutSidebarOptions({ app.ui.repResetFiltersBtn, app.ui.simStartBtn, app.ui.shippingCheck, app.ui.writPouchCheck, app.ui.crateTooltipCheck })
	elseif isCalcView then
		if calcMode == "rep" or t == "calc_rep" then
			app.layoutSidebarOptions({ app.ui.repCalcResetFiltersBtn, app.ui.calcModeBtn, app.ui.writZoneBtn, app.ui.writPouchCheck, app.ui.respectStockCheck, app.ui.crateTooltipCheck, app.ui.subCraftBtn, app.ui.deepScanBtn })
		else
			app.layoutSidebarOptions({ app.ui.favorResetFiltersBtn, app.ui.calcModeBtn, app.ui.respectStockCheck, app.ui.crateTooltipCheck, app.ui.subCraftBtn, app.ui.deepScanBtn })
		end
	else
		app.layoutSidebarOptions({})
	end
	local openDD = ns.Theme.GetDropDownMenu and ns.Theme.GetDropDownMenu()
	if openDD and openDD:IsShown() and openDD.owner and not openDD.owner:IsShown() then
		ns.Theme.CloseDropDown()
	end
	if app.refreshSkinLayout then app.refreshSkinLayout() end
end
app.applyPanelLayout = applyPanelLayout

