function app.setMinimized(minState, skipRefresh)
	local want = (minState == true)
	panel._mmMinimized = want and app.activeTab ~= "bags"
	if want then
		if app.activeTab == "bags" then return end
		if not app._minimized then
			app._savedPreMinHeight = (MerchantMasterDB and MerchantMasterDB.window and tonumber(MerchantMasterDB.window.height))
				or math.max(730, math.floor((panel:GetHeight() or 730) + 0.5))
		end
		app._minimized = true
		ns.Theme.CloseDropDown()
		if app.ui.sidebarOptionsHost then app.ui.sidebarOptionsHost:Hide() end
		if winChrome and winChrome.window and winChrome.window.SetCompact then
			winChrome.window:SetCompact(true)
		end
		panel:SetSize(panel:GetWidth() or PANEL_W, 72)

		if app.ui.trafficLights and app.ui.trafficLights.frame then
			app.ui.trafficLights.frame:ClearAllPoints()
			app.ui.trafficLights.frame:SetPoint("LEFT", app.ui.sidebar, "LEFT", 16, 0)
		end
		if app.ui.brandLogoTex then app.ui.brandLogoTex:Hide() end
		if app.ui.brandTitleFs then
			app.ui.brandTitleFs:ClearAllPoints()
			app.ui.brandTitleFs:SetPoint("LEFT", app.ui.trafficLights.frame, "RIGHT", 10, 0)
			app.ui.brandTitleFs:SetPoint("RIGHT", app.ui.sidebar, "RIGHT", -10, 0)
			applySafeFont(app.ui.brandTitleFs, 14, "semibold")
		end
		if app.ui.brandSubFs then app.ui.brandSubFs:Hide() end
		if app.ui.searchWrap then app.ui.searchWrap:Hide() end
		for _, sec in ipairs(app.ui.sidebarSections or {}) do sec:Hide() end
		for _, nb in ipairs(app.ui.navOrder or {}) do nb:Hide() end
		if app.ui.walletCard then app.ui.walletCard:Hide() end

		if app.ui.toolbar then app.ui.toolbar:Show() end
		if app.ui.appearanceSwitch and app.ui.appearanceSwitch.frame then app.ui.appearanceSwitch.frame:Show() end
		if app.ui.topCartBtn then app.ui.topCartBtn:Show() end
		if app.ui.topTaskListBtn then app.ui.topTaskListBtn:Show() end
		if app.ui.topSendAuctionatorBtn then app.ui.topSendAuctionatorBtn:Show() end
		if winChrome and winChrome.ahRefresh and winChrome.ahRefresh.button then
			winChrome.ahRefresh.button:Show()
		end
		if app.ui.mainArea then app.ui.mainArea:Hide() end
		if app.ui.subStrip then app.ui.subStrip:Hide() end
		if winChrome.resizeGrip then winChrome.resizeGrip:Hide() end
		if winChrome.heightGrip then winChrome.heightGrip:Hide() end
		applyPanelLayout()
	else
		app._minimized = false
		if app.ui.trafficLights and app.ui.trafficLights.frame then
			app.ui.trafficLights.frame:ClearAllPoints()
			app.ui.trafficLights.frame:SetPoint("TOPLEFT", 16, -14)
		end
		local customSkin = ns.Theme and ns.Theme.IsCustomSkin and ns.Theme.IsCustomSkin() or false
		if app.ui.brandLogoTex then app.ui.brandLogoTex:SetShown(not customSkin) end
		if app.ui.brandTitleFs then
			app.ui.brandTitleFs:ClearAllPoints()
			app.ui.brandTitleFs:SetPoint("TOPLEFT", 50, -36)
			app.ui.brandTitleFs:SetPoint("TOPRIGHT", -12, -36)
			applySafeFont(app.ui.brandTitleFs, 16, "semibold")
		end
		if app.ui.brandSubFs then app.ui.brandSubFs:Show() end
		if app.ui.searchWrap then app.ui.searchWrap:Show() end
		for _, sec in ipairs(app.ui.sidebarSections or {}) do sec:Show() end
		for _, nb in ipairs(app.ui.navOrder or {}) do nb:Show() end
		if app.ui.walletCard then app.ui.walletCard:Show() end

		if MerchantMasterDB then
			MerchantMasterDB.window = MerchantMasterDB.window or {}
			MerchantMasterDB.window.height = app._savedPreMinHeight or 730
		end
		if winChrome and winChrome.window and winChrome.window.SetCompact then
			winChrome.window:SetCompact(false)
		end
		if not skipRefresh then
			applyPanelLayout()
			if panel:IsShown() and app.refresh then app.refresh() end
		end
	end
end

-- Skin geometry is kept in one reversible pass; Standard uses its original anchors.
do
	local T = ns.Theme
	local headerFrame = CreateFrame("Frame", nil, panel)
	headerFrame:Hide()
	app.ui.skinHeader = headerFrame
	local originalScopeWidth = scopeSeg.frame:GetWidth()
	local originalScopeHeight = scopeSeg.frame:GetHeight()
	local basketNav = CreateFrame("Button", nil, sidebar)
	basketNav:SetSize(196, 26)
	basketNav:SetPoint("TOPLEFT", sidebar, "TOPLEFT", 12, -116)
	basketNav:Hide()
	basketNav:SetScript("OnClick", function() app.toggleShoppingWindow() end)
	local basketNavLabel = basketNav:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
	basketNavLabel:SetPoint("LEFT", basketNav, "LEFT", 12, 0)
	basketNavLabel:SetPoint("RIGHT", basketNav, "RIGHT", -36, 0)
	basketNavLabel:SetJustifyH("LEFT")
	basketNavLabel:SetText("Shopping Basket")
	applySafeFont(basketNavLabel, 13, "semibold")
	local basketNavCount = T.CreateBadgePill(basketNav, "0", "neutral", { height = 20, fontSize = 11, minWidth = 22, padX = 14 })
	basketNavCount.frame:SetPoint("RIGHT", basketNav, "RIGHT", -8, 0)
	app.ui.skinBasketNav = basketNav
	app.ui._syncSkinBasketCount = function()
		basketNavCount:SetVariant("neutral", tostring((app.ui._basketSummary or {}).count or 0))
	end
	local originalNavPoints, originalScopeButtons = {}, {}
	for _, nb in ipairs(app.ui.navOrder) do originalNavPoints[nb] = { nb:GetPoint(1) } end
	for _, key in ipairs({ "known", "mine", "all" }) do
		local b = scopeSeg.buttons[key]
		originalScopeButtons[key] = { width = b:GetWidth(), height = b:GetHeight(), point = { b:GetPoint(1) } }
	end
	local originalSearchPoints = {}
	if app.ui.searchWrap then
		for i = 1, app.ui.searchWrap:GetNumPoints() do
			originalSearchPoints[i] = { app.ui.searchWrap:GetPoint(i) }
		end
	end
	local originalSearchHeight = app.ui.searchWrap and app.ui.searchWrap:GetHeight() or 30
	local originalSectionPoints = {}
	for i, sec in ipairs(app.ui.sidebarSections or {}) do
		local pts = {}
		for p = 1, sec:GetNumPoints() do pts[p] = { sec:GetPoint(p) } end
		originalSectionPoints[i] = pts
	end
	local tiledPlates = {}
	local function plate(owner, key, layer, sub)
		if not owner[key] then
			owner[key] = owner:CreateTexture(nil, layer or "BACKGROUND", nil, sub or 2)
			owner[key]:SetAllPoints(owner)
			owner[key]:Hide()
		elseif layer and owner[key].SetDrawLayer then
			owner[key]:SetDrawLayer(layer, sub or 2)
		end
		return owner[key]
	end
	local function syncOneTiledPlate(entry)
		local owner, tex, asset = entry.owner, entry.tex, entry.asset
		if not (owner and tex and tex:IsShown()) then return end
		local w = (owner.GetWidth and owner:GetWidth()) or 0
		local h = (owner.GetHeight and owner:GetHeight()) or 0
		if w <= 1 then w = (panel.GetWidth and panel:GetWidth()) or 1320 end
		if h <= 1 then h = (panel.GetHeight and panel:GetHeight()) or 730 end
		if w <= 1 then w = 1320 end
		if h <= 1 then h = 730 end
		if tex.SetHorizTile then tex:SetHorizTile(false) end
		if tex.SetVertTile then tex:SetVertTile(false) end
		if asset == "sidebar_bg" or asset == "header_tile" then
			tex:SetTexCoord(0, w / 210, 0, h / 210)
		else
			tex:SetTexCoord(0, 1, 0, 1)
		end
	end
	function app.syncSkinTiledCoords()
		if not (T.IsCustomSkin and T.IsCustomSkin()) then return end
		for _, entry in ipairs(tiledPlates) do syncOneTiledPlate(entry) end
		for _, list in ipairs({ app.ui.dashKpis, app.ui.spreadKpis, app.ui.cratesKpis, app.ui.forgedKpis }) do
			for _, kpi in ipairs(list or {}) do
				if kpi.syncSkinTile then kpi.syncSkinTile() end
			end
		end
	end
	local function trackTiled(owner, tex, asset)
		for _, entry in ipairs(tiledPlates) do
			if entry.tex == tex then
				entry.owner, entry.asset = owner, asset
				return entry
			end
		end
		local entry = { owner = owner, tex = tex, asset = asset }
		tiledPlates[#tiledPlates + 1] = entry
		return entry
	end
	local function material(owner, key, asset, on, color, layer, sub)
		if not owner then return end
		local tex = plate(owner, key, layer, sub)
		if on then
			if asset then
				local path = T.GetSkinAsset(T.GetSkin(), asset)
				if asset == "header_tile" or asset == "sidebar_bg" then
					tex:SetTexture(path, "REPEAT", "REPEAT")
					tex:SetVertexColor(1, 1, 1, 1)
					tex:SetShown(true)
					syncOneTiledPlate(trackTiled(owner, tex, asset))
					return
				elseif asset == "surface" then
					tex:SetTexture(path, "CLAMP", "CLAMP")
					tex:SetVertexColor(1, 1, 1, 1)
					tex:SetShown(true)
					syncOneTiledPlate(trackTiled(owner, tex, asset))
					return
				else
					tex:SetTexture(path)
					tex:SetVertexColor(1, 1, 1, 1)
					if tex.SetTexCoord then tex:SetTexCoord(0, 1, 0, 1) end
				end
			else
				tex:SetColorTexture(color[1], color[2], color[3], color[4] or 1)
			end
		end
		tex:SetShown(on)
	end
	local function perimeter(owner, on, color)
		if not owner.skinEdges then
			owner.skinEdges = {}
			for _, side in ipairs({ "TOP", "BOTTOM", "LEFT", "RIGHT" }) do
				local edge = owner:CreateTexture(nil, "BORDER", nil, 3)
				if side == "TOP" or side == "BOTTOM" then
					edge:SetPoint(side .. "LEFT", owner, side .. "LEFT", 0, 0)
					edge:SetPoint(side .. "RIGHT", owner, side .. "RIGHT", 0, 0)
					edge:SetHeight(1)
				else
					edge:SetPoint("TOP" .. side, owner, "TOP" .. side, 0, 0)
					edge:SetPoint("BOTTOM" .. side, owner, "BOTTOM" .. side, 0, 0)
					edge:SetWidth(1)
				end
				owner.skinEdges[#owner.skinEdges + 1] = edge
			end
		end
		for _, edge in ipairs(owner.skinEdges) do
			if on then edge:SetColorTexture(color[1], color[2], color[3], color[4] or 1) end
			edge:SetShown(on)
		end
	end
	local function displayTitle(fs, on, size)
		if on then
			if not fs._skinDisplayFont then fs._skinDisplayFont = { fs:GetFont() } end
			local text = fs:GetText() or ""
			if not fs._skinDisplayText or text ~= string.upper(fs._skinDisplayText) then fs._skinDisplayText = text end
			fs:SetFont("Fonts\\FRIZQT__.TTF", size, "")
			fs:SetText(string.upper(fs._skinDisplayText))
		elseif fs._skinDisplayFont then
			fs:SetFont(unpack(fs._skinDisplayFont))
			fs:SetText(fs._skinDisplayText)
			fs._skinDisplayFont, fs._skinDisplayText = nil, nil
		end
	end
	function app.refreshDashKpiLayout()
		local on = T.IsCustomSkin()
		local groups = {
			{ list = app.ui.dashKpis, compact = true },
			{ list = app.ui.spreadKpis, compact = false },
			{ list = app.ui.cratesKpis, compact = false },
			{ list = app.ui.forgedKpis, compact = false },
		}
		for _, grp in ipairs(groups) do
			for _, kpi in ipairs(grp.list or {}) do
				if grp.compact then kpi.frame:SetHeight(on and 68 or 104) end
				if kpi.iconTex then kpi.iconTex:SetShown(not on) end
				local fields = { kpi.titleFs, kpi.valueFs, kpi.unitFs, kpi.subFs }
				if on and not kpi._skinStandard then
					kpi._skinStandard = {}
					kpi._skinTagPoints = {}
					kpi._skinStandardValueJustify = kpi._alignValue
						or (kpi.valueFs.GetJustifyH and kpi.valueFs:GetJustifyH())
						or "RIGHT"
					for i = 1, kpi.tagPill.frame:GetNumPoints() do kpi._skinTagPoints[i] = { kpi.tagPill.frame:GetPoint(i) } end
					for _, fs in ipairs(fields) do
						local saved = { font = { fs:GetFont() }, width = fs:GetWidth(), points = {} }
						for i = 1, fs:GetNumPoints() do saved.points[i] = { fs:GetPoint(i) } end
						kpi._skinStandard[fs] = saved
					end
				end
				if on then
					local title = kpi.titleFs:GetText() or ""
					if not kpi._skinTitle or title ~= string.upper(kpi._skinTitle) then kpi._skinTitle = title end
					kpi.titleFs:SetText(string.upper(kpi._skinTitle))
					for _, fs in ipairs(fields) do fs:ClearAllPoints() end
					applySafeFont(kpi.titleFs, 10.5, "semibold")
					kpi.titleFs:SetPoint("TOPLEFT", kpi.frame, "TOPLEFT", 14, -12)
					kpi.titleFs:SetPoint("TOPRIGHT", kpi.frame, "TOPRIGHT", -14, -12)
					kpi.valueFs:SetJustifyH("LEFT")
					kpi.valueFs:SetWidth(0)
					if grp.compact then
						applySafeFont(kpi.valueFs, 16, "semibold")
						applySafeFont(kpi.unitFs, 11, "regular")
						applySafeFont(kpi.subFs, 11, "regular")
						kpi.valueFs:SetWidth(0)
						kpi.unitFs:SetWidth(0)
						local cardW = (kpi.frame.GetWidth and kpi.frame:GetWidth()) or 320
						if cardW < 180 then cardW = 320 end
						local valW = (kpi.valueFs.GetStringWidth and kpi.valueFs:GetStringWidth()) or 0
						if valW < 1 then
							local vtxt = (kpi.valueFs.GetText and kpi.valueFs:GetText()) or ""
							vtxt = vtxt:gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", ""):gsub("|T.-|t", "  ")
							valW = math.ceil(#vtxt * 9.5)
						end
						valW = math.ceil(valW)
						local unitShown = kpi.unitFs and kpi.unitFs:IsShown() and ((kpi.unitFs.GetText and kpi.unitFs:GetText()) or "") ~= ""
						local unitW = 0
						if unitShown then
							unitW = (kpi.unitFs.GetStringWidth and kpi.unitFs:GetStringWidth()) or 0
							if unitW < 1 then
								unitW = math.ceil(#(kpi.unitFs:GetText() or "") * 6.5)
							end
							unitW = math.ceil(unitW)
						end
						local leftPad, rightPad, unitGap, minSubGap = 14, 14, 6, 8
						local maxValRight = cardW - rightPad - (unitShown and (unitW + unitGap) or 0) - 48
						local clampedValW = math.max(40, math.min(valW + 2, maxValRight - leftPad))
						kpi.valueFs:SetPoint("TOPLEFT", kpi.frame, "TOPLEFT", leftPad, -33)
						kpi.valueFs:SetWidth(clampedValW)
						local unitX = leftPad + clampedValW + unitGap
						kpi.unitFs:SetPoint("TOPLEFT", kpi.frame, "TOPLEFT", unitX, -37)
						local leftEndX = unitShown and (unitX + unitW) or (leftPad + clampedValW)
						if kpi.tagPill.frame:IsShown() then
							kpi.tagPill.frame:ClearAllPoints()
							kpi.tagPill.frame:SetPoint("LEFT", kpi.frame, "TOPLEFT", leftEndX + 8, -42)
							local pillW = (kpi.tagPill.frame.GetWidth and kpi.tagPill.frame:GetWidth()) or 56
							leftEndX = leftEndX + 8 + pillW
						end
						local availSubW = math.max(40, math.floor(cardW - rightPad - leftEndX - minSubGap))
						kpi.subFs:SetPoint("TOPRIGHT", kpi.frame, "TOPRIGHT", -rightPad, -36)
						kpi.subFs:SetJustifyH("RIGHT")
						kpi.subFs:SetWidth(availSubW)
					else
						applySafeFont(kpi.valueFs, 22, "semibold")
						applySafeFont(kpi.unitFs, 12, "regular")
						applySafeFont(kpi.subFs, 12, "regular")
						kpi.valueFs:SetPoint("TOPLEFT", kpi.frame, "TOPLEFT", 14, -36)
						kpi.unitFs:SetPoint("BOTTOMLEFT", kpi.valueFs, "BOTTOMRIGHT", 8, 2)
						if kpi.tagPill.frame:IsShown() then
							kpi.tagPill.frame:ClearAllPoints()
							kpi.tagPill.frame:SetPoint("LEFT", kpi.unitFs:IsShown() and kpi.unitFs or kpi.valueFs, "RIGHT", 8, 0)
						end
						kpi.subFs:SetPoint("BOTTOMLEFT", kpi.frame, "BOTTOMLEFT", 14, 14)
						kpi.subFs:SetPoint("BOTTOMRIGHT", kpi.frame, "BOTTOMRIGHT", -14, 14)
						kpi.subFs:SetJustifyH("LEFT")
						kpi.subFs:SetWidth(0)
					end
				elseif kpi._skinStandard then
					for _, fs in ipairs(fields) do
						local saved = kpi._skinStandard[fs]
						fs:ClearAllPoints()
						for _, point in ipairs(saved.points) do fs:SetPoint(unpack(point)) end
						fs:SetWidth(saved.width)
						fs:SetFont(unpack(saved.font))
					end
					kpi.valueFs:SetJustifyH(kpi._skinStandardValueJustify or "RIGHT")
					kpi.subFs:SetJustifyH("LEFT")
					kpi.titleFs:SetText(kpi._skinTitle)
					kpi.tagPill.frame:ClearAllPoints()
					for _, point in ipairs(kpi._skinTagPoints) do kpi.tagPill.frame:SetPoint(unpack(point)) end
					kpi._skinTagPoints = nil
					kpi._skinStandardValueJustify = nil
					kpi._skinTitle, kpi._skinStandard = nil, nil
					if kpi.syncInlineLayout then kpi.syncInlineLayout() end
				end
			end
		end
	end
	local controls = CreateFrame("Frame", nil, rightPane)
	controls:SetSize(80, 48)
	controls:SetPoint("TOPRIGHT", headerFrame, "TOPRIGHT", -42, -3)
	controls:Hide()
	app.ui.skinControls = controls
	for i, spec in ipairs({
		{ key = "minimize", text = "-", click = function() app.setMinimized(not app._minimized) end },
		{ key = "maximize", text = "[]", click = function()
			if app._minimized then app.setMinimized(false, true) end
			if winChrome.window and winChrome.window.ToggleZoom then winChrome.window:ToggleZoom() end
			if app.applyPanelLayout then app.applyPanelLayout() end
			if app.refresh then app.refresh() end
		end },
		{ key = "close", text = "x", click = function() panel:Hide() end },
	}) do
		local b = CreateFrame("Button", nil, controls)
		b:SetSize(24, 24)
		b:SetPoint("LEFT", controls, "LEFT", (i - 1) * 28, 0)
		b.skinBg = b:CreateTexture(nil, "BACKGROUND", nil, 0)
		b.skinBg:SetPoint("TOPLEFT", b, "TOPLEFT", 1, -1)
		b.skinBg:SetPoint("BOTTOMRIGHT", b, "BOTTOMRIGHT", -1, 1)
		b.skinBg:SetColorTexture(0.24, 0.04, 0.08, 0.94)
		b.skinHover = b:CreateTexture(nil, "HIGHLIGHT")
		b.skinHover:SetPoint("TOPLEFT", b, "TOPLEFT", 1, -1)
		b.skinHover:SetPoint("BOTTOMRIGHT", b, "BOTTOMRIGHT", -1, 1)
		b.skinHover:SetColorTexture(1, 0.94, 0.78, 0.14)
		perimeter(b, false)
		b.fs = b:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
		b.fs:SetPoint("CENTER", b, "CENTER", 0, 0)
		b.fs:SetJustifyH("CENTER")
		b.fs:SetJustifyV("MIDDLE")
		b.fs:SetWordWrap(false)
		applySafeFont(b.fs, 13, "semibold")
		b.fs:SetText(spec.text)
		if b.SetFontString then b:SetFontString(b.fs) end
		b:SetText(spec.text)
		b:SetScript("OnClick", spec.click)
		controls[spec.key] = b
	end
	local portrait = sidebar:CreateTexture(nil, "ARTWORK", nil, 3)
	portrait:SetSize(34, 34)
	portrait:SetPoint("TOPLEFT", sidebar, "TOPLEFT", 16, -12)
	portrait:Hide()
	app.ui.skinPortrait = portrait
	local walletPortrait = app.ui.walletCard:CreateTexture(nil, "ARTWORK", nil, 3)
	walletPortrait:SetSize(34, 34)
	walletPortrait:SetPoint("BOTTOMLEFT", app.ui.walletCard, "BOTTOMLEFT", 12, 12)
	walletPortrait:Hide()
	app.ui.skinWalletPortrait = walletPortrait
	local header = plate(sidebar, "skinHeader")
	header:ClearAllPoints()
	header:SetPoint("TOPLEFT", sidebar, "TOPLEFT", 0, 0)
	header:SetPoint("TOPRIGHT", sidebar, "TOPRIGHT", 0, 0)
	header:SetHeight(64)

	function app.refreshSkinLayout()
		local on = T.IsCustomSkin and T.IsCustomSkin() or false
		local pal = getPal()
		local l, top, r, bottom = T.GetSkinInset()
		local compact = app._minimized and app.activeTab ~= "bags"
		panel._mmMinimized = compact and true or false
		-- Minimized chrome needs a usable title strip inside its short shell.
		if compact and on then top, bottom = 8, 8 end
		sidebar:ClearAllPoints()
		sidebar:SetPoint("TOPLEFT", panel, "TOPLEFT", l, -top - (on and 54 or 0))
		sidebar:SetPoint("BOTTOMLEFT", panel, "BOTTOMLEFT", l, bottom)
		sidebar:SetWidth(on and 220 or 216)
		rightPane:ClearAllPoints()
		rightPane:SetPoint("TOPLEFT", sidebar, "TOPRIGHT", 0, 0)
		rightPane:SetPoint("BOTTOMRIGHT", panel, "BOTTOMRIGHT", -r, bottom)
		if sidebar.surface then sidebar.surface:SetShown(not on) end
		if rightPane.surface then rightPane.surface:SetShown(not on) end
		for _, slices in ipairs({ sidebar.refractWash, sidebar.refractLens }) do
			for _, piece in ipairs(slices.pieces) do piece:SetShown(not on) end
		end
		sidebar.refractGlow:SetShown(not on)
		material(sidebar, "skinBackground", "sidebar_bg", on)
		material(rightPane, "skinBackground", "surface", on)
		material(mainArea, "skinBackground", "surface", on)
		headerFrame:ClearAllPoints()
		headerFrame:SetPoint("TOPLEFT", panel, "TOPLEFT", l, -top)
		headerFrame:SetPoint("TOPRIGHT", panel, "TOPRIGHT", -r, -top)
		headerFrame:SetHeight(54)
		if panel.GetFrameLevel and headerFrame.SetFrameLevel then
			headerFrame:SetFrameLevel(panel:GetFrameLevel() + 4)
