function app.setTab(tab)
	tab = LEGACY_TAB_ROUTES[tab] or tab
	local db = MerchantMasterDB
	if tab == "path" then tab = "prof_path"
	elseif tab == "browse" then tab = "prof_browse" end
	if tab == "professor" then
		tab = app.lastSubTab.professor or "prof_path"
	elseif type(tab) == "string" and tab:sub(1, 5) == "prof_" then
		app.lastSubTab.professor = tab
	end
	if tab == "analytics" then
		tab = app.lastSubTab.analytics or "an_overview"
	elseif type(tab) == "string" and tab:sub(1, 3) == "an_" then
		app.lastSubTab.analytics = tab
	end
	if tab == "sniper" then
		tab = app.lastSubTab.sniper or "sniper_gap"
	elseif tab == "sniper_gap" or tab == "sniper_vendor" then
		app.lastSubTab.sniper = tab
	end
	if tab == "console" then
		tab = app.lastSubTab.console or "console_overview"
	elseif type(tab) == "string" and tab:sub(1, 8) == "console_" then
		app.lastSubTab.console = tab
	end
	if tab == "profit" or tab == "token" or tab == "reputation" then
		tab = app.lastSubTab[tab] or (tab == "profit" and "profit_spread" or (tab == "token" and "crates" or "writs"))
	end
	tab = LEGACY_TAB_ROUTES[tab] or tab
	if tab == "calc_favor" then
		if db then db.calcMode = "favor" end
		app.lastSubTab.token = "calc_favor"
	elseif tab == "calc_rep" then
		if db then db.calcMode = "rep" end
		app.lastSubTab.reputation = "calc_rep"
	elseif tab == "calc" then
		local cm = (db and db.calcMode) or "favor"
		if cm == "rep" then
			app.lastSubTab.reputation = "calc_rep"
		else
			app.lastSubTab.token = "calc_favor"
		end
	elseif tab == "profit_spread" or tab == "outliers" or tab == "recipes" or tab == "all_items" or tab == "vendor_crafter" or tab == "disenchant_crafter" then
		app.lastSubTab.profit = tab
	elseif tab == "crates" then
		app.lastSubTab.token = "crates"
	elseif tab == "writs" or tab == "forged" or tab == "rep" then
		app.lastSubTab.reputation = tab
	end

	if not VALID_LEAF_TABS[tab] then tab = "dashboard" end
	if not app._warmedAllCatalogVendorSell and ns.WarmLiveVendorPrices
		and (tab == "recipes" or tab == "all_items" or tab == "vendor_crafter" or tab == "disenchant_crafter" or tab == "profit_spread" or tab == "outliers" or tab == "writs") then
		app._warmedAllCatalogVendorSell = true
		local warmIDs, warmSeen = {}, {}
		for _, rec in ipairs(ns.RECIPES or {}) do
			local oid = rec.outputItemID
			if oid and oid > 0 and not rec.isEnchant and not warmSeen[oid] then
				warmSeen[oid] = true
				warmIDs[#warmIDs + 1] = oid
			end
		end
		ns.WarmLiveVendorPrices(warmIDs)
	end
	local provider = app.superListProvider
	local quickLook = provider and provider.GetQuickLookFrame and provider.GetQuickLookFrame()
	if quickLook and quickLook:IsShown() and quickLook.openedTab ~= tab then provider.CloseQuickLook() end
	if provider and provider.CloseHeatPopover and tab ~= "recipes" then provider.CloseHeatPopover() end
	if app.vendorCrafterProvider and app.vendorCrafterProvider.CloseHeatPopover and tab ~= "vendor_crafter" then
		app.vendorCrafterProvider.CloseHeatPopover()
	end
	if app.disenchantCrafterProvider and app.disenchantCrafterProvider.CloseHeatPopover and tab ~= "disenchant_crafter" then
		app.disenchantCrafterProvider.CloseHeatPopover()
	end
	if app.allItemsProvider and app.allItemsProvider.CloseHeatPopover and tab ~= "all_items" then
		app.allItemsProvider.CloseHeatPopover()
	end
	if app.watchlistProvider and app.watchlistProvider.CloseHeatPopover and tab ~= "watchlist" then
		app.watchlistProvider.CloseHeatPopover()
	end
	if app._minimized and tab ~= "bags" and app.setMinimized then
		app.setMinimized(false, true)
	end
	if tab == "bags" and app.activeTab ~= "bags" and app.activeTab ~= "deep_analysis" and db then
		db.prevFullTab = app.activeTab
	end
	local popHost = app.ui and app.ui.sidebarOptionsHost
	if app.activeTab ~= tab and popHost and popHost:IsShown() and popHost._mode == "filters" then
		popHost:Hide()
	end
	if tab ~= "deep_analysis" and not app._deepAnalysisKeepingStack then
		app._deepAnalysisStack = nil
	end
	app.activeTab = tab
	if type(tab) == "string" and tab:sub(1, 5) == "prof_" then
		app._profPreviewCleared = false

	end
	if tab ~= "recipes" and tab ~= "all_items" and tab ~= "watchlist" and tab ~= "vendor_crafter" and tab ~= "disenchant_crafter" and tab ~= "bags" and winChrome.window and winChrome.window.SetMinimumWidth then
		winChrome.window:SetMinimumWidth(1320)
	end
	if db and tab ~= "deep_analysis" then db.activeTab = tab end
	if not panel:IsShown() then return end
	if app.ui and app.ui.searchBox then
		app.ui.searchBox._searchSeq = (app.ui.searchBox._searchSeq or 0) + 1
		app.ui.searchBox._lastSearchText = (app.ui.searchBox.GetText and app.ui.searchBox:GetText()) or ""
	end
	if app.refresh then app.refresh() end
end

local function findLabel(list, key)
	for _, it in ipairs(list) do
		if it.key == key then return it.label end
	end
	return list[1] and list[1].label or tostring(key or "")
end

local function formatWritZoneButtonLabel(zone)
	if not zone or zone == "" or zone == "all" then return "Area: All Zones" end
	if zone == "mapped" then return "Area: Known Areas" end
	if zone == "unmapped" then return "Area: Unmapped" end
	return "Area: " .. tostring(zone)
end

function app.resetSearchBox(box)
	if not box then return end
	box._searchSeq = (box._searchSeq or 0) + 1
	box._lastSearchText = ""
	if box:GetText() ~= "" then box:SetText("") end
	if box.placeholder then box.placeholder:Show() end
	if box._mmClearBtn then box._mmClearBtn:Hide() end
	if box.ClearFocus then box:ClearFocus() end
end

function app.resetSubCraftMode()
	if not MerchantMasterDB then return end
	MerchantMasterDB.subCraftMode = "smart"
	if app.ui.subCraftBtn then
		app.ui.subCraftBtn:SetText(findLabel(ns.SUBCRAFT_MODES, "smart"))
	end
end

function app.resetPageFilters(defaults)
	local db = MerchantMasterDB
	if not db then return end
	for key, value in pairs({ profFilter = "all", unlockFilter = "all", prevUnlockFilter = "all",
		sellableFilter = "all", knownRecipesOnly = false, bisOnly = false, merchantVendorOnly = false,
		sourceFilter = "all", craftableFilter = "all", demandFilter = "all" }) do db[key] = value end
	db.recipeSources = {}
	for key, value in pairs(defaults or {}) do db[key] = value end
	app.resetSearchBox(app.ui.searchBox)
	if app.ui.scopeSeg then app.ui.scopeSeg:SetActive("all", true) end
	for _, key in ipairs({ "knownRecipesCheck", "bisOnlyCheck", "merchantOnlyCheck" }) do
		if app.ui[key] then app.ui[key]:SetChecked(false) end
	end
	app.ui.unlockBtn:SetText(findLabel(UNLOCK_FILTERS, db.unlockFilter))
	app.ui.sellBtn:SetText(findLabel(SELLABLE_FILTERS, db.sellableFilter))
	app.ui.originBtn:SetText(findLabel(SOURCE_FILTERS, db.sourceFilter))
	app.ui.recipeSourcesBtn:SetText(ns.FormatRecipeSourcesLabel(db.recipeSources))
	app.ui.recCraftFilterBtn:SetText(findLabel(ns.CRAFTABLE_FILTERS, db.craftableFilter))
	app.ui.recDemandFilterBtn:SetText(findLabel(ns.DEMAND_FILTERS, db.demandFilter))
end

function app.resetCurrentViewFilters()
	local methods = { dashboard = "resetDashboardFilters", watchlist = "resetWatchlistFilters", profit_spread = "resetSpreadFilters",
		outliers = "resetOutliersFilters", all_items = "resetAllItemsFilters", vendor_crafter = "resetVendorCrafterFilters", disenchant_crafter = "resetDisenchantCrafterFilters", crates = "resetCratesFilters", writs = "resetWritsFilters", forged = "resetForgedFilters",
		rep = "resetRepViewFilters", calc_favor = "resetFavorCalcFilters", calc_rep = "resetRepCalcFilters" }
	local method = methods[app.activeTab]
	if method then return app[method]() end
end

