function app.resetBagsFilters()
	local db = MerchantMasterDB
	if not db then return end
	for key, value in pairs({ includeMail = true, includeBank = true, includeAlts = false }) do
		db[key] = value
		app.ui[key]:SetChecked(value)
	end
	wipe(app.folded)
	app.resetSearchBox(app.ui.searchBox)
	app.invalidateRecipeStats("ownership")
	if ns.MapPins and ns.MapPins.OnEvent then ns.MapPins.OnEvent("HOST_CONTEXT_CHANGED") end
	return app.refresh()
end

local refreshListeners = {}
local function notifyRefreshListeners()
	for i = 1, #refreshListeners do
		pcall(refreshListeners[i])
	end
end


function app.getUIPriceBank()
	local db = MerchantMasterDB or {}
	local econ = ns.CurrentEconomyInfo()
	local sig = table.concat({
		tostring(econ.selectedKey or "auto"),
		tostring(econ.effectiveKey or ""),
		tostring(db.priceSource or "auto"),
		tostring(db.lastRefreshAt or 0),
		tostring(ns.GetEffectivePriceVersion and ns.GetEffectivePriceVersion() or ns.priceCacheEpoch or 1),
	}, "|")
	local now = (GetTime and GetTime()) or 0
	local bank = app.uiPriceBank
	if not bank or bank.sig ~= sig then
		bank = {
			sig = sig,
			at = now,
			mktPrice = {},
			reagentCost = {},
			numListed = {},
			dailySold = {},
			vendorSell = {},
			lastKnownAH = {},
			craftOpt = {},
			smartCraft = {},
			candidates = {},
			itemNames = bank and bank.itemNames or {},
			itemIcons = bank and bank.itemIcons or {},
		}
		app.uiPriceBank = bank
	end
	return bank
end

local function getAnalyticsAverages()
	if app.analyticsProvider and app.analyticsProvider.getAverages then
		local ok, res = pcall(app.analyticsProvider.getAverages)
		if ok and type(res) == "table" then return res end
	end
	return nil
end

local function refreshPanelImpl()
	local db = MerchantMasterDB or {}
	local crates
	if not (type(app.activeTab) == "string" and (app.activeTab:sub(1, 3) == "an_" or app.activeTab:sub(1, 8) == "console_")) then
		crates = bagCrates()
		local bagLabel = string.format("Bag Crates (%d)", #crates)
		app.ui.bagHeaderTab:SetText(bagLabel)
		if app.ui.tokenSubBar and app.ui.tokenSubBar.buttons and app.ui.tokenSubBar.buttons.bags_open then
			app.ui.tokenSubBar.buttons.bags_open:SetText(bagLabel)
		end
	end

	applyPanelLayout()

	local unifiedSyncOpts = {}

	if app.activeTab == "bags" then
		local counts = ownedCounts()
		local rows, ready = {}, 0
		wipe(app.queue)
		if #crates == 0 then rows[1] = { text = "No Waylaid Crate in your bags." } end
		for c, crate in ipairs(crates) do
			local ranked = rankBundles(crate.bundles, counts, crate.name)
			local others = #ranked - 1
			local open = not app.folded[crate.name]
			rows[#rows + 1] = {
				text = crate.link, link = crate.link, icon = crate.icon, gap = c > 1,
				crate = crate, scanning = app.scanning[crate.name], atAH = atAH(),
				toggle = others > 0 and crate.name or nil,
				right = others > 0 and ("|cff9d9d9d" .. (open and "Fold" or string.format("+%d option(s)", others)) .. "|r") or nil,
			}
			if ranked[1] and ranked[1].missing == 0 then ready = ready + 1 end
			for i, b in ipairs(ranked) do
				if i == 1 or open then
					local text = bundleText(b)
					if i > 1 then text = "|cffb0b0b0or " .. text .. "|r" end
					if b.missing == 0 then
						rows[#rows + 1] = { text = "|cff33ff33" .. bundleText(b) .. "|r", right = "|cff33ff33Ready to fill|r", indent = 20 }
					else
						rows[#rows + 1] = { text = text, indent = 20, search = b.name, right = bagPriceText(b), qty = i > 1 and b.missing or nil }
						if i == 1 and not tContains(app.queue, b.name) then app.queue[#app.queue + 1] = b.name end
					end
				end
			end
		end
		app.ui.bagBox:SetDataProvider(CreateDataProvider(rows), ScrollBoxConstants and ScrollBoxConstants.RetainScrollPosition or true)
		local bagJob, bagQueueLength = ns.MarketScan.GetBagStatus()
		if bagJob then
			app.ui.bagView.summary:SetText(string.format("Pricing %s… (%d left)", bagJob.item, bagQueueLength))
		else
			app.ui.bagView.summary:SetText(string.format("%d crate(s), %d ready", #crates, ready))
		end
		local running = next(app.scanning) ~= nil
		app.ui.scanAllBtn:SetText(running and "..." or "Scan all")
		app.ui.scanAllBtn:SetEnabled(atAH() and not running and #crates > 0)
		app.ui.nextBtn:SetEnabled(atAH())
		app.ui.hideWithAH:SetEnabled(atAH())
		return
	end

	-- Shared Left Sidebar & Top Filter state
	local profFilter = db.profFilter or "all"
	local knownRecipesOnly = (db.knownRecipesOnly == true) or (db.unlockFilter == "known")
	local unlockFilter = knownRecipesOnly and "known" or (db.unlockFilter or "all")
	local subCraftMode = db.subCraftMode or "smart"
	local subCraftOverrides = db.subCraftOverrides
	local search = app.ui.searchBox:GetText() or ""
	local profMap = ns.GetPlayerProfessions()
	local repState = ns.GetMerchantReputation()
	local favorBal, favorIconID = ns.GetFavorBalance()
	local srcInfo = ns.CurrentSourceInfo()
	local econInfo = ns.CurrentEconomyInfo()
	local marketState = ns.MarketScan.GetState() -- read once per refresh: status capsule, Refresh button, scan banner

	-- Banner KPI Pill & Fable Sidebar / Floating Toolbar Live Sync
	local favStr = favorBal ~= nil and (tostring(favorBal) .. " " .. favorIconMarkup(favorIconID) .. " Favor") or ""
	app.ui.headerInfo:SetText(string.format("%s (%d/%d)%s",
		repState.standingName, repState.inTierCurrent, repState.inTierMax,
		favStr ~= "" and ("  ·  " .. favStr) or ""))

	if app.ui.appearanceSwitch and app.ui.appearanceSwitch.UpdateTheme then
		app.ui.appearanceSwitch:UpdateTheme()
	end
	if app.ui.scopeSeg and app.ui.scopeSeg.SetActive then
		local sk = knownRecipesOnly and "known" or ((unlockFilter == "mine_profs" or profFilter == "mine_profs") and "mine" or "all")
		app.ui.scopeSeg:SetActive(sk, true)
	end
	if app.syncToolbarCharScope then app.syncToolbarCharScope(true) end
	if app.ui.brandSubFs then
		local pNames = {}
		for _, pr in ipairs(ns.PROFESSIONS) do
			if pr.key ~= "all" and pr.key ~= "mine_profs" and profMap[pr.key] then
				local rank = tonumber(profMap[pr.key])
				if rank and rank > 1 then
					pNames[#pNames + 1] = string.format("%s %d", pr.full, math.floor(rank))
				else
					pNames[#pNames + 1] = pr.full
				end
			end
		end
		if ns.IsAllCharsCraftableActive and ns.IsAllCharsCraftableActive() and #pNames > 2 then
			local nChars = ns.GetEconomyCharacters and #ns.GetEconomyCharacters() or 1
			app.ui.brandSubFs:SetText(string.format("All Chars (%d) · %d Profs", nChars, #pNames))
		else
			app.ui.brandSubFs:SetText(#pNames > 0 and table.concat(pNames, " / ") or "All Professions")
		end
	end
	if app.ui.statusEconFs and app.ui.statusSyncFs then
		local faction = (type(_G.UnitFactionGroup) == "function" and _G.UnitFactionGroup("player")) or "Neutral"
		local rawEcon = tostring(econInfo.buttonLabel or econInfo.label or "Normal")
		local econMode = rawEcon:match("^(.-)%s*[-·]") or rawEcon
		econMode = econMode:gsub("%s+$", "")
		if econMode == "" then econMode = rawEcon end
		-- "Normal-Horde" -> "Normal · Horde": one clean middle-dot hierarchy, no clipped parentheses
		local econLabel = tostring(econInfo.label or (econMode .. " · " .. faction))
		econLabel = econLabel:gsub("%-(Horde)$", " · %1"):gsub("%-(Alliance)$", " · %1")
		local now = (type(_G.time) == "function") and _G.time() or nil
		local srcKey = (srcInfo and srcInfo.key) or (ns.GetEffectivePriceSource and ns.GetEffectivePriceSource()) or (db and db.priceSource) or "auto"
		local srcTag = "AH"
		local ageLbl = "Ready"
		local econKey = econInfo and econInfo.effectiveKey
		local snapMeta = (ns.Pricing and type(ns.Pricing.GetSnapshotMeta) == "function") and ns.Pricing.GetSnapshotMeta(econKey) or nil
		local snapAt = (type(snapMeta) == "table" and type(snapMeta.updatedAt) == "number" and snapMeta.updatedAt > 0 and (not now or snapMeta.updatedAt <= now))
			and snapMeta.updatedAt or nil
		local ahPool = db and db.ahPrices and econKey and db.ahPrices[econKey]
		local liveScanAt = (type(ahPool) == "table" and type(ahPool._scannedAt) == "number" and ahPool._scannedAt > 0 and (not now or ahPool._scannedAt <= now))
			and ahPool._scannedAt or nil
		local liveAt = liveScanAt
		if econInfo and econInfo.isActive and type(db.lastRefreshAt) == "number" and db.lastRefreshAt > 0 and (not now or db.lastRefreshAt <= now) then
			liveAt = (liveAt and math.max(liveAt, db.lastRefreshAt)) or db.lastRefreshAt
		end
		local ts = nil
		local useSnap = false
		if srcKey == "snapshot" then
			srcTag = "Snap"
			ts = snapAt
			if snapAt then useSnap = true end
		elseif srcKey == "live_ah" then
			srcTag = "AH"
			ts = liveAt
		elseif srcKey == "auto" then
			if snapAt and (not liveAt or snapAt >= liveAt) then
				useSnap = true
				srcTag = "Snap"
				ts = snapAt
			else
				srcTag = "AH"
				ts = liveAt
			end
		else
			srcTag = "AH"
			ts = liveAt
		end
		if useSnap then
			srcTag = "Snap"
			ts = snapAt
		end
		local fmtAge = app.ui._formatStatusAge
		if ts and now then
			ageLbl = (fmtAge and fmtAge(ts, now)) or "just now"
		end
		local econStr = (econInfo.selectedKey == "auto") and ("Auto \194\183 " .. econLabel) or econLabel
		local hasSnaps = (ns.HasSnapshots and ns.HasSnapshots()) and true or false
		local liveIsRecent = (liveAt ~= nil and now ~= nil and (now - liveAt) <= 1800) and true or false
		local tsmAvail = (econInfo and econInfo.isActive and ns.IsTSMAvailable and ns.IsTSMAvailable()) and true or false
		local usingTSM = tsmAvail and (srcKey == "tsm" or (srcKey == "auto" and not useSnap and not liveIsRecent))
		local tsmTs = nil
		if tsmAvail and type(ns.GetTSMLastUpdateTime) == "function" then
			local rawTsm = ns.GetTSMLastUpdateTime()
			if type(rawTsm) == "number" and rawTsm > 0 and (not now or rawTsm <= now) then
				tsmTs = rawTsm
			end
		end
		local noScanYet = (not usingTSM) and (ts == nil and liveAt == nil and not hasSnaps)
		local syncStr
		if usingTSM then
			local tsmAge = fmtAge and fmtAge(tsmTs, now) or nil
			syncStr = tsmAge and ("TSM " .. tsmAge) or "TSM Hourly"
		elseif noScanYet then
			syncStr = "No AH Scan Yet"
		else
			syncStr = string.format("%s %s", srcTag, ageLbl)
		end
		app.ui._statusUsingTSM = usingTSM
		app.ui._statusNoScanYet = noScanYet
		app.ui._statusSource = usingTSM and "tsm" or (useSnap and "snap" or (liveAt and "ah" or nil))
		app.ui._statusSnapAt = snapAt
		app.ui._statusLiveAt = liveAt
		app.ui._statusTsmAt = tsmTs
		app.ui._statusEconStr, app.ui._statusSyncStr = econStr, syncStr
		app.ui.statusEconFs:SetText(econStr)
		if app.updateScanChrome then
			app.updateScanChrome(marketState)
		else
			app.ui.statusSyncFs:SetText(syncStr)
			if app.ui.statusServerFs then
				app.ui.statusServerFs:SetText(string.format("%s  |  %s", econStr, syncStr))
			end
			if app.ui._updateStatusCapsuleWidth then
				app.ui._updateStatusCapsuleWidth(econStr, syncStr)
			end
		end
	elseif app.ui.statusServerFs then
		local faction = (type(_G.UnitFactionGroup) == "function" and _G.UnitFactionGroup("player")) or "Neutral"
		local fallbackSync = (getActiveLiveScanTs(db) == nil and not (ns.HasSnapshots and ns.HasSnapshots())) and "No AH Scan Yet" or "AH Ready"
		app.ui.statusServerFs:SetText("Normal · " .. faction .. "  |  " .. fallbackSync)
	end
	if app.ui.walletTierFs then
		local fname = tostring(repState.factionName or "")
		local shortName = fname:find("Azeroth") and "Azeroth Commerce" or "Durotar Supply"
		app.ui.walletTierFs:SetText(shortName)
	end
	if app.ui.walletStandFs then
		app.ui.walletStandFs:SetText(tostring(repState.standingName or "Neutral"))
	end
	if app.ui.walletGoldFs then
		local copper = 0
		if type(_G.GetMoney) == "function" then copper = _G.GetMoney() end
		app.ui.walletGoldFs:SetText(moneyText(copper))
	end
	do
		local maxTier = math.max(1, tonumber(repState.inTierMax) or 3000)
		local curTier = math.max(0, math.min(maxTier, tonumber(repState.inTierCurrent) or 0))
		if app.ui.walletProgressBar and app.ui.walletProgressBar.SetValue then
			app.ui.walletProgressBar:SetValue(curTier / maxTier)
		elseif app.ui.walletMeterFill and app.ui.walletMeterTrack then
			local tw = math.max(120, tonumber(app.ui.walletMeterTrack.GetWidth and app.ui.walletMeterTrack:GetWidth()) or 172)
			app.ui.walletMeterFill:SetWidth(math.max(4, math.floor(tw * (curTier / maxTier))))
		end
		if app.ui.walletRepSubFs then
			app.ui.walletRepSubFs:SetText(string.format("%s / %s", formatComma(curTier), formatComma(maxTier)))
		end
	end
	if app.ui.walletFavorFs then
		app.ui.walletFavorFs:SetText(favorBal ~= nil and formatComma(favorBal) or "0")
	end

	-- Profession Card highlights
	local pal = getPal()
	local isProfMenu = (type(app.activeTab) == "string" and app.activeTab:sub(1, 5) == "prof_")
	local activeProfHighlight = profFilter
	if isProfMenu and ns.GetProfessorDB then
		local pdb = ns.GetProfessorDB()
		activeProfHighlight = (pdb and pdb.selectedProf) or "alchemy"
	end
	for pkey, btn in pairs(app.ui.profBtns) do
		if pkey == activeProfHighlight then
			local ab = pal.accentBlue or { 0.04, 0.52, 1.0, 1 }
			btn.card:SetBorder(ab[1], ab[2], ab[3], 1)
			btn.card:SetFill(ab[1], ab[2], ab[3], 0.20)
			btn.fs:SetText(ns.PROF_BY_KEY[pkey].label)
			if pal.text then btn.fs:SetTextColor(pal.text[1], pal.text[2], pal.text[3], 1) end
		elseif profMap[pkey] then
			local ag = pal.accentGreen or { 0.19, 0.82, 0.35, 1 }
			btn.card:SetBorder(ag[1], ag[2], ag[3], 0.85)
			btn.card:SetFill(ag[1], ag[2], ag[3], 0.14)
			btn.fs:SetText(ns.PROF_BY_KEY[pkey].label)
			btn.fs:SetTextColor(ag[1], ag[2], ag[3], 1)
		else
			local bdr = pal.border or { 1, 1, 1, 0.12 }
			local bg = pal.inputBg or { 0.12, 0.12, 0.14, 0.90 }
			btn.card:SetBorder(bdr[1], bdr[2], bdr[3], bdr[4] or 0.12)
			btn.card:SetFill(bg[1], bg[2], bg[3], bg[4] or 0.90)
			btn.fs:SetText(ns.PROF_BY_KEY[pkey].label)
			if pal.textSecondary then btn.fs:SetTextColor(pal.textSecondary[1], pal.textSecondary[2], pal.textSecondary[3], 1) end
		end
	end

	app.ui.econBtn:SetText("Econ: " .. econInfo.buttonLabel)
	app.ui.sourceBtn:SetText("Src: " .. (srcInfo.short or srcInfo.label))
	app.ui.refreshBtn:SetText(marketState.active and "Stop Scan" or "Refresh AH")
	app.ui.unlockBtn:SetText(findLabel(UNLOCK_FILTERS, unlockFilter))
	app.ui.subCraftBtn:SetText(findLabel(ns.SUBCRAFT_MODES, subCraftMode))
	if app.ui.recipeSourcesBtn then app.ui.recipeSourcesBtn:SetText(ns.FormatRecipeSourcesLabel(db.recipeSources)) end
	app.ui.ahCutCheck:SetChecked(db.applyAHCut ~= false)
	if app.ui.knownRecipesCheck then app.ui.knownRecipesCheck:SetChecked(knownRecipesOnly) end
	if app.ui.knownAllCharsCheck then app.ui.knownAllCharsCheck:SetChecked(db.craftableAllChars == true) end
	app.ui.writPouchCheck:SetChecked(db.includeWritPouch ~= false)
	app.ui.bisOnlyCheck:SetChecked(db.bisOnly == true)
	if app.ui.crateTooltipCheck then app.ui.crateTooltipCheck:SetChecked(ns.IsCrateTooltipEnabled()) end
	app.ui.writZoneBtn:SetText(formatWritZoneButtonLabel(db.writZoneFilter or "all"))

	local scanBanner = nil
	if marketState.active then
		scanBanner = string.format("|cffffd200Scanning Live AH (%s)… %d items, page %d|r", ns.DetectActiveEconomy(), marketState.matchedCount, marketState.page)
	elseif app.lotScanTotal > 0 then
		scanBanner = string.format("|cffffd200Scanning AH Order-Book Lots (%d/%d)…|r", app.lotScanDone, app.lotScanTotal)
	end

	if type(app.activeTab) == "string" and app.activeTab:sub(1, 5) == "prof_" then
		if app.professorProvider and app.professorProvider.refresh then
			local ok, err = pcall(app.professorProvider.refresh, app.activeTab, app.ui.professorView, app.ui.statusText, scanBanner, search)
			if not ok then
				say("Professor UI error: " .. tostring(err))
			end
		end
		return
	end

	if type(app.activeTab) == "string" and app.activeTab:sub(1, 3) == "an_" then
		if app.analyticsProvider and app.analyticsProvider.refresh then
			if app.ui.analyticsView.emptyFs then app.ui.analyticsView.emptyFs:Hide() end
			local ok, err = pcall(app.analyticsProvider.refresh, app.activeTab, app.ui.analyticsView, app.ui.statusText)
			if not ok then
				if not app._anErrLogged then
					app._anErrLogged = true
					say("Analytics UI error: " .. tostring(err))
				end
				app.analyticsProvider = nil
				app.layoutSidebarOptions({})
				if app.ui.analyticsView.emptyFs then
					app.ui.analyticsView.emptyFs:SetText("|cffff5555Analytics error: " .. tostring(err) .. "|r")
					app.ui.analyticsView.emptyFs:Show()
				end
			end
		else
			if app.ui.analyticsView.emptyFs then
				app.ui.analyticsView.emptyFs:SetText("Analytics is unavailable. Check addon load errors and reload the UI.")
				app.ui.analyticsView.emptyFs:Show()
			end
			app.ui.statusText:SetText(scanBanner or "Analytics unavailable")
		end
		return
	end

	if type(app.activeTab) == "string" and app.activeTab:sub(1, 8) == "console_" then
		if (app.activeTab == "console_settings" or app.activeTab == "console_mail" or app.activeTab == "console_ui")
			and app.consoleProvider and app.consoleProvider.SyncSettings then
			app.consoleProvider.SyncSettings()
		end
		app.ui.statusText:SetText(scanBanner or "Console - Static snapshot (click Refresh to update)")
		return
	end

	local counts = ownedCounts()
	local t = app.activeTab
	local isCalcTab = (t == "calc" or t == "calc_favor" or t == "calc_rep")

	if t == "deep_analysis" then
		if ns.DeepAnalysis and ns.DeepAnalysis.Refresh then
			ns.DeepAnalysis.Refresh()
		end
		return
	end

	if t == "dashboard" then
		if app.ui.dashOnboardingCard then
			local showOnboard = app.shouldShowOnboarding()
			app.ui.dashOnboardingCard:SetShown(showOnboard)
			if showOnboard and app.ui.dashOnboardNoAutoOpenCheck then
				app.ui.dashOnboardNoAutoOpenCheck:SetChecked(isAutoOpenAtAHDisabled())
			end
		end
		local effDashScope = knownRecipesOnly and "known" or (db.dashboardScope or "smart")
		app.ui.dashScopeBtn:SetText(findLabel(ns.DASHBOARD_SCOPES, effDashScope))
		local ins = ns.BuildDashboardInsights({
			dashboardScope = db.dashboardScope or "smart",
			knownRecipesOnly = knownRecipesOnly,
			profFilter = profFilter,
			unlockFilter = unlockFilter,
			merchantVendorOnly = db.merchantVendorOnly,
			recipeSources = db.recipeSources,
			applyAHCut = (db.applyAHCut ~= false),
			subCraftMode = subCraftMode,
			subCraftOverrides = subCraftOverrides,
			outlierPrices = db.outlierPrices,
			ownedCounts = counts,
			profMap = profMap,
			repState = repState,
		})
		app.lastDashInsights = ins

		local function profGlyph(profKey)
			if profKey == "herbalism" then return "leaf"
			elseif profKey == "blacksmithing" or profKey == "mining" then return "bars"
			elseif profKey == "engineering" then return "gear"
			elseif profKey == "leatherworking" or profKey == "skinning" then return "crate"
			elseif profKey == "tailoring" or profKey == "inscription" then return "doc"
			elseif profKey == "enchanting" or profKey == "jewelcrafting" then return "crown"
			end
			return "flask"
		end

		local rightTag = ins.hasBestKnownFallback and "Best Options" or "Outliers"
		if app.ui.dashLeftHdrFs then
			app.ui.dashLeftHdrFs:SetText(ins.forceKnown
				and "KNOWN CRAFTS TODAY"
				or "Daily Velocity Crafts")
		end
		if app.ui.dashRightHdrFs then
			if ins.hasBestKnownFallback then
				app.ui.dashRightHdrFs:SetText("BEST KNOWN OPTIONS")
			elseif ins.forceKnown then
				app.ui.dashRightHdrFs:SetText("Monopoly Opportunities")
			else
				app.ui.dashRightHdrFs:SetText("Monopoly Opportunities")
			end
		end
		if app.ui.dashRightCard and app.ui.dashRightCard.seeAllBtn then
			local outN = #(ins.topOutliers or {})
			app.ui.dashRightCard.seeAllBtn:SetText(outN > 0
				and string.format("%d %s", outN, outN == 1 and "opportunity" or "opportunities")
				or "No opportunities")
		end

		local kpi1 = app.ui.dashKpis and app.ui.dashKpis[1]
		local kpi2 = app.ui.dashKpis and app.ui.dashKpis[2]
		local kpi3 = app.ui.dashKpis and app.ui.dashKpis[3]

		local craftCnt = #(ins.topCrafts or {})
		local outCnt = #(ins.topOutliers or {})
		local expNumStr = (ins.expectedProfitPerDay or 0) > 0
			and moneyText(ins.expectedProfitPerDay, true, { neutral = not ns.Theme.IsCustomSkin() })
			or zeroMoney("g")
		if kpi1 and kpi1.SetData then
			kpi1:SetData({
				title = "Expected Profit / Day",
				value = expNumStr,
				unit = "/ day",
				sub = string.format("%d daily seller%s + %d %s",
					craftCnt, craftCnt == 1 and "" or "s",
					outCnt, outCnt == 1 and "monopoly" or "monopolies"),
				valueColor = false,
			})
		else
			app.ui.dashExpectedDailyFs:SetText(expNumStr .. " / day")
			app.ui.dashBreakdownFs:SetText(string.format("%d daily sellers + %d monopolies", craftCnt, outCnt))
		end
		app.ui.dashRoiFs:SetText(string.format("Known (Can Do): %s/d · Potential: %s/d",
			moneyText(ins.knownProfitPerDay or 0, true), moneyText(ins.potentialProfitPerDay or 0, true)))

		if kpi2 and kpi2.SetData then
			local basketSum = app.ui._basketSummary or {}
			local bCnt = tonumber(basketSum.count) or 0
			local spendVal = moneyText(ins.totalMaterialCost or 0)
			local roiVal = tonumber(ins.roiPct) or 0
			kpi2:SetData({
				title = "Basket Spend & ROI",
				value = spendVal,
				unit = false,
				tag = roiVal > 0 and string.format("%.1f%% ROI", math.min(999.9, roiVal)) or false,
				tagVariant = "positive",
				sub = bCnt > 0
					and string.format("Daily spend · %d item%s", bCnt, bCnt == 1 and "" or "s")
					or string.format("Daily spend · %d recipe%s", craftCnt, craftCnt == 1 and "" or "s"),
				valueColor = false,
			})
		end

		if kpi3 and kpi3.SetData then
			local k3Val = "--"
			local k3Unit = false
			local k3Sub = "No Crate / Writ prices yet"
			if ins.bestCrate and ins.bestCrate.pricePerToken then
				k3Val = moneyText(ins.bestCrate.pricePerToken)
				k3Unit = "/ Favor"
				k3Sub = tostring(ins.bestCrate.crateName or "Crate")
			elseif ins.bestWrit and ins.bestWrit.pricePerRep then
				k3Val = moneyText(ins.bestWrit.pricePerRep)
				k3Unit = "/ Rep"
				k3Sub = tostring(ins.bestWrit.writName or "Writ")
			end
			kpi3:SetData({
				title = "Cheapest Turn-In",
				value = k3Val,
				unit = k3Unit,
				sub = k3Sub,
				valueColor = false,
			})
		end
		if app.refreshDashKpiLayout then app.refreshDashKpiLayout() end

		local maxTier = math.max(1, tonumber(repState.inTierMax) or 3000)
		local curTier = math.max(0, math.min(maxTier, tonumber(repState.inTierCurrent) or 0))
		if ins.bestCrate and ins.bestCrate.pricePerToken then
			app.ui.dashCratePulseFs:SetText(string.format("%s (%d/%d)  ·  Best Favor: %s (%s/tok)",
				repState.standingName or "Neutral", curTier, maxTier, ins.bestCrate.crateName, moneyText(ins.bestCrate.pricePerToken)))
		else
			app.ui.dashCratePulseFs:SetText(string.format("%s (%d/%d)  ·  Best Favor: --",
				repState.standingName or "Neutral", curTier, maxTier))
		end
		if ins.bestWrit and ins.bestWrit.pricePerRep then
			app.ui.dashWritPulseFs:SetText(string.format("Best Rep Writ: %s (%s/rep)", ins.bestWrit.writName, moneyText(ins.bestWrit.pricePerRep)))
		else
			app.ui.dashWritPulseFs:SetText("Best Rep Writ: --")
		end

		if app.ui.dashTurninRows then
			local c1 = (ins.topCrates and ins.topCrates[1]) or ins.bestCrate
			local c2 = ins.topCrates and ins.topCrates[2]
			local w1 = (ins.topWrits and ins.topWrits[1]) or ins.bestWrit
			local w2 = ins.topWrits and ins.topWrits[2]
			if not ins.topCrates or not ins.topWrits then
				local crateList = ns.BuildCrateRows({ bestOnly = true, crateMode = "cheapest", profMap = profMap, repState = repState }) or {}
				ns.SortRows(crateList, "pricePerToken", true, "pricePerToken", { crateName = true })
				local writList = ns.BuildWritRows({ writMode = "cheapest", includeWritPouch = true, profMap = profMap, repState = repState }) or {}
				ns.SortRows(writList, "pricePerRep", true, "pricePerRep", { writName = true })
				c1 = crateList[1] or ins.bestCrate
				c2 = crateList[2]
				w1 = writList[1] or ins.bestWrit
				w2 = writList[2]
			end

			local crateSlots = { c1, c2 }
			for idx = 1, 2 do
				local tr = app.ui.dashTurninRows[idx]
				local cr = crateSlots[idx]
				if tr and cr then
					tr.data, tr.rowData, tr.rowKind = cr, cr, "crate"
					tr.nameFs:SetText(cr.crateName or "Waylaid Crate")
					local matPart = cr.reagentName and string.format("%s %dx", cr.reagentName, cr.reagentQty or 1) or "Turn-in"
					local modePart
					if cr.mode == "Buy" or cr.mode == "Buy AH" then
						modePart = "Buy AH"
					elseif cr.mode == "Craft" then
						modePart = "Craft"
					else
						modePart = "Price unavailable"
					end
					tr.subFs:SetText(string.format("%s · %s", matPart, modePart))
					if tr.badge and tr.badge.SetVariant then
						tr.badge:SetVariant("plain", string.format("%s+%d|r %sFavor|r",
							palHex("hexText", "ffffff"), tonumber(cr.tokens) or 10, palHex("hexMuted", "98989d")))
					end
					if tr.valFs then
						tr.valFs:SetText(cr.pricePerToken and moneyText(cr.pricePerToken) or "--")
						if pal.text then tr.valFs:SetTextColor(pal.text[1], pal.text[2], pal.text[3], 1) end
					end
					tr:Show()
				elseif tr then
					tr.data, tr.rowData, tr.rowKind = nil, nil, nil
					tr:Hide()
				end
			end

			local writSlots = { w1, w2 }
			for idx = 1, 2 do
				local tr = app.ui.dashTurninRows[idx + 2]
				local wr = writSlots[idx]
				if tr and wr then
					tr.data, tr.rowData, tr.rowKind = wr, wr, "writ"
					tr.nameFs:SetText(wr.writName or "Craftsman's Writ")
					local zStr = (wr.zone and wr.zone ~= "Unmapped" and wr.zone ~= "") and wr.zone
						or (wr.zoneHint and wr.zoneHint ~= "" and wr.zoneHint)
						or (wr.profSkillLabel and wr.profSkillLabel ~= "" and wr.profSkillLabel)
						or "Turn-In Writ"
					if zStr == wr.writName then
						zStr = (wr.profSkillLabel and wr.profSkillLabel ~= "" and wr.profSkillLabel) or "Turn-In Writ"
					end
					tr.subFs:SetText(zStr)
					if tr.pouchFs then
						tr.pouchFs:SetText(wr.pouchRefund and moneyText(wr.pouchRefund) or "--")
					end
					if tr.badge and tr.badge.SetVariant then
						tr.badge:SetVariant("plain", string.format("%s+%d|r %sRep|r",
							palHex("hexText", "ffffff"), tonumber(wr.rep) or 125, palHex("hexMuted", "98989d")))
					end
					if tr.valFs then
						local net = (wr.totalPrice ~= nil) and (-wr.totalPrice) or nil
						tr.valFs:SetText(net ~= nil and moneyText(net, true) or "--")
						local vc = (net and net >= 0) and pal.accentGreen or pal.textSecondary
						if vc then tr.valFs:SetTextColor(vc[1], vc[2], vc[3], 1) end
					end
					tr:Show()
				elseif tr then
					tr.data, tr.rowData, tr.rowKind = nil, nil, nil
					tr:Hide()
				end
			end
		end

		local maxRow2 = (app.ui.dashLeftCard and app.ui.dashLeftCard.GetHeight and (app.ui.dashLeftCard:GetHeight() or 240) >= 280) and 5 or 4
		for i = 1, 5 do
			local cRow = app.ui.dashCraftRows[i]
			local d = ins.topCrafts[i]
			cRow.data = d
			if d then
				cRow:SetShown(i <= maxRow2)
				cRow.icon:SetTexture(d.icon)
				if cRow.glyphBadge and cRow.glyphBadge.SetIcon then
					cRow.glyphBadge:SetIcon(profGlyph(d.prof))
				end
				local cHeat = (d.demand and d.demand.heatBadge) or "Steady"
				local cQty = (d.listed ~= nil) and (tostring(d.listed) .. " AH") or "-- AH"
				local cSold = d.dailySold and (string.format("%.1f", d.dailySold) .. "/d") or "--/d"
				local showCWh = (i <= maxRow2 and d.craftAbility ~= nil and not d.craftAbility.ableToCraft and d.craftAbility.wowheadURL ~= nil)
				cRow.whBtn:SetShown(showCWh)
				cRow.nameFs:SetText(tostring(d.name or "Recipe"))
				local able = d.craftAbility and d.craftAbility.ableToCraft
				local profLbl = d.profSkillLabel or d.profLabel or ""
				local metaRight = able and "Learned" or ((d.craftAbility and (d.craftAbility.howShort or d.craftAbility.cellText)) or "Recipe")
				if able then
					cRow.metaFs:SetText(profLbl ~= "" and (profLbl .. " ·") or "")
					if cRow.metaRightFs then cRow.metaRightFs:SetText("Learned") end
					if cRow.setMetaCheck then cRow.setMetaCheck(true) end
				else
					if cRow.setMetaCheck then cRow.setMetaCheck(false) end
					cRow.metaFs:SetText(profLbl ~= "" and (profLbl .. " · " .. metaRight) or metaRight)
				end
				cRow.subFs:SetText(string.format("%s · %s · %s (%s · %s)",
					profLbl, d.adviceBadge or "", cHeat, cQty, cSold))
				cRow.callFs:SetText(string.format("Cost %s -> AH %s", moneyText(d.craftCost), moneyText(d.ahPrice)))
				if cRow.demandPill and cRow.demandPill.SetVariant then
					local lowH = tostring(cHeat):lower()
					local hv = (lowH:find("hot") or lowH:find("surge") or lowH:find("fast")) and "hot" or "neutral"
					-- The pill variant owns the ink: drop the data model's inline colour code
					cRow.demandPill:SetVariant(hv, (tostring(cHeat):gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", "")))
				end
				if cRow.velFs then
					cRow.velFs:SetText(d.dailySold and string.format("%.1f / day", d.dailySold) or "-- / day")
				end
				cRow.metricBig:SetText(moneyText(d.profit or d.expectedDailyProfit, true))
				if pal.accentGreen then cRow.metricBig:SetTextColor(pal.accentGreen[1], pal.accentGreen[2], pal.accentGreen[3], 1) end
				cRow.metricSub:SetText(moneyText(d.profit, true) .. " ea")
			else
				cRow.whBtn:Hide()
				cRow:Hide()
			end

			local oRow = app.ui.dashOutlierRows[i]
			local od = ins.topOutliers[i]
			oRow.data = od
			if od then
				oRow:SetShown(i <= maxRow2)
				oRow.icon:SetTexture(od.icon)
				if oRow.glyphBadge and oRow.glyphBadge.SetIcon then
					oRow.glyphBadge:SetIcon(i == 1 and "crown" or profGlyph(od.prof))
				end
				local oQty = (od.listed ~= nil) and (tostring(od.listed) .. " AH") or "0 AH"
				local oSold = od.dailySold and (string.format("%.1f", od.dailySold) .. "/d") or "0/d"
				local oAble = (od.canCraft and "Ready Now") or (od.craftAbility and od.craftAbility.cellText) or ""
				local showOWh = (i <= maxRow2 and od.craftAbility ~= nil and not od.craftAbility.ableToCraft and od.craftAbility.wowheadURL ~= nil)
				oRow.whBtn:SetShown(showOWh)
				oRow.nameFs:SetText(tostring(od.name or "Item"))
				local oProf = od.profSkillLabel or od.profLabel or ""
				local oLearned = od.canCraft or (od.craftAbility and od.craftAbility.ableToCraft)
				local oSrc = oLearned and "Learned" or ((od.craftAbility and (od.craftAbility.howShort or od.craftAbility.cellText)) or "Recipe")
				if oLearned then
					oRow.metaFs:SetText(oProf ~= "" and (oProf .. " ·") or "")
					if oRow.metaRightFs then oRow.metaRightFs:SetText("Learned") end
					if oRow.setMetaCheck then oRow.setMetaCheck(true) end
				else
					if oRow.setMetaCheck then oRow.setMetaCheck(false) end
					oRow.metaFs:SetText(oProf ~= "" and (oProf .. " · " .. oSrc) or oSrc)
				end
				oRow.subFs:SetText(string.format("%s · %s · %s · %s",
					oProf, oAble, oQty, oSold))
				local priceLabel = od.isBestKnownOption and "AH" or (od.isCustomPrice and "Custom" or "Suggested")
				oRow.callFs:SetText(string.format("Cost %s -> %s %s", moneyText(od.craftCost), priceLabel, moneyText(od.targetPrice)))
				oRow.actBtn:SetText(od.isBestKnownOption and "Buy Mats" or "Set Price")
				if oRow.demandPill and oRow.demandPill.SetVariant then
					local lNum = tonumber(od.listed) or 0
					local supLbl = tostring(lNum) .. " listed"
					oRow.demandPill:SetVariant(lNum == 0 and "strong" or "neutral", supLbl)
				end
				oRow.metricBig:SetText(moneyText(od.profit, true))
				if pal.accentGreen then oRow.metricBig:SetTextColor(pal.accentGreen[1], pal.accentGreen[2], pal.accentGreen[3], 1) end
				oRow.metricSub:SetText(moneyText(od.expectedDailyProfit, true) .. "/d")
			else
				oRow.whBtn:Hide()
				oRow:Hide()
			end
		end
		if app.syncDashboardBasketCard then
			app.syncDashboardBasketCard()
		end
		if app.syncDashboardMode then app.syncDashboardMode() end
		if app.ui.dashBriefView and app.ui.dashBriefView:IsShown() and app.ui.dashBriefView.Refresh then
			app.ui.dashBriefView:Refresh(false)
		end

		if panel:IsShown() and app.layoutWindow then
			app.layoutWindow()
		end

		app.ui.statusText:SetText(scanBanner or string.format("Expected Profit: %s / day (%d Guaranteed + %d %s · %s)",
			moneyText(ins.expectedProfitPerDay or 0, true), #ins.topCrafts, #ins.topOutliers, rightTag, econInfo.label))

	elseif t == "watchlist" then
		if app.watchlistProvider and app.watchlistProvider.Refresh then
			app.watchlistProvider.Refresh(app.buildWatchlistContext({
				counts = counts, profMap = profMap, repState = repState,
				econInfo = econInfo, scanBanner = scanBanner, search = search,
			}))
		end

	elseif t == "profit_spread" then
		local spreadCount = tonumber(db.spreadCount) or 8
		local diversify = (db.diversifyProfs ~= false)
		local craftFilter = db.craftableFilter or "all"
		local demandFilter = db.demandFilter or "all"
		app.ui.spreadCountBtn:SetText(findLabel(ns.SPREAD_COUNTS, spreadCount))
		app.ui.diversifyCheck:SetChecked(diversify)
		app.ui.recCraftFilterBtn:SetText(findLabel(ns.CRAFTABLE_FILTERS, craftFilter))
		app.ui.recDemandFilterBtn:SetText(findLabel(ns.DEMAND_FILTERS, demandFilter))

		local rows, summary = ns.BuildProfitSpreadRows({
			search = search,
			profFilter = profFilter,
			unlockFilter = unlockFilter,
			craftableFilter = craftFilter,
			demandFilter = demandFilter,
			recipeSources = db.recipeSources,
			applyAHCut = (db.applyAHCut ~= false),
			subCraftMode = subCraftMode,
			subCraftOverrides = subCraftOverrides,
			spreadCount = spreadCount,
			diversifyProfs = diversify,
			spreadQueue = db.spreadQueue,
			bisOnly = db.bisOnly == true,
			profMap = profMap,
			repState = repState,
		})
        if ns.Analytics and ns.Analytics.Tooltips then
            local ids={}; for _,row in ipairs(rows) do if row.itemID then ids[#ids+1]=row.itemID end end
            ns.Analytics.Tooltips.PrimeItems(ids)
        end
		app.lastSpreadSummary = summary
		app.lastSpreadRows = rows

		local st = app.sortState.profit_spread
		ns.SortRows(rows, st.col, st.asc, "expectedDailyProfit", { name = true })
		app.ui.profitSpreadTable.updateHeaders()
		app.ui.profitSpreadTable.setRows(rows)

		local spreadByID = {}
		for _, sr in ipairs(rows or {}) do
			local key = sr.spreadQueueKey or sr.itemID
			if key and not spreadByID[key] then spreadByID[key] = sr end
		end
		unifiedSyncOpts.spreadRowsByID = spreadByID
		local shopData = ns.BuildSpreadShoppingList(rows, summary, {
			spreadQueue = db.spreadQueue,
			profMap = profMap,
			subCraftMode = subCraftMode,
			subCraftOverrides = subCraftOverrides,
			ownedCounts = counts,
		})
		local planTag = shopData.hasCustomQueue and string.format("Custom Spread Queue (%d items)", #shopData.targets) or string.format("Top %d Daily Spread Plan", summary.planCount)
		if app.ui.spreadKpis then
			local sk1, sk2, sk3 = app.ui.spreadKpis[1], app.ui.spreadKpis[2], app.ui.spreadKpis[3]
			local expVal = summary.totalExpectedDailyProfit or 0
			if sk1 and sk1.SetData then
				sk1:SetData({
					title = "Expected Daily Profit",
					value = expVal > 0 and moneyText(expVal, true, { neutral = true }) or zeroMoney("g"),
					unit = "/ day",
					sub = planTag,
					valueColor = false,
				})
			end
			if sk2 and sk2.SetData then
				local roiV = tonumber(summary.roiPct) or 0
				sk2:SetData({
					title = "Daily Mat Spend",
					value = moneyText(summary.totalDailySpend or 0),
					unit = false,
					tag = roiV > 0 and string.format("%.0f%% ROI", math.min(999, roiV)) or false,
					tagVariant = "positive",
					sub = string.format("%d high-velocity crafts", summary.totalMatched or #rows),
					valueColor = false,
				})
			end
			if sk3 and sk3.SetData then
				sk3:SetData({
					title = "Best Daily Seller",
					value = summary.bestRow and moneyText(summary.bestRow.expectedDailyProfit, true, { neutral = true }) or "--",
					unit = summary.bestRow and "/ day" or false,
					sub = summary.bestRow and string.format("%s · %.1f / day", tostring(summary.bestRow.name or ""), summary.bestRow.dailySold or 0) or "No seller matched",
					valueColor = false,
				})
			end
		end
		app.ui.spreadSummaryFs:SetText(string.format(
			"%s%s:|r  Expected %s+%s / day|r  ·  Daily Spend: %s  ·  ROI: %s%+.0f%%|r  ·  %d crafts",
			palHex("hexText", "ffffff"), planTag, palHex("hexPositive", "30d158"),
			moneyText(summary.totalExpectedDailyProfit or 0), moneyText(summary.totalDailySpend or 0),
			palHex("hexPositive", "30d158"), math.min(9999, summary.roiPct or 0), summary.totalMatched or #rows))

		if scanBanner then
			app.ui.statusText:SetText(themeText(scanBanner))
		elseif summary.bestRow then
			app.ui.statusText:SetText(string.format("Top Daily Seller: %s%s|r (+%s/day · %.1f sold/d) · Spread: +%s/day",
				palHex("hexPositive", "30d158"), summary.bestRow.name, ns.FormatMoneyCompact(summary.bestRow.expectedDailyProfit), summary.bestRow.dailySold or 0, ns.FormatMoneyCompact(summary.totalExpectedDailyProfit or 0)))
		else
			app.ui.statusText:SetText("No high-velocity crafts matched in " .. econInfo.label)
		end

	elseif t == "outliers" then
		local oScope = db.outlierScope or "monopoly"
		local oQuality = db.outlierQuality or "good"
		local craftFilter = db.craftableFilter or "all"
		app.ui.outlierScopeBtn:SetText(findLabel(ns.OUTLIER_SCOPES, oScope))
		app.ui.outlierQualityBtn:SetText(findLabel(ns.OUTLIER_QUALITY_FILTERS, oQuality))
		app.ui.recCraftFilterBtn:SetText(findLabel(ns.CRAFTABLE_FILTERS, craftFilter))

		local rows, summary = ns.BuildOutlierRows({
			search = search,
			profFilter = profFilter,
			unlockFilter = unlockFilter,
			craftableFilter = craftFilter,
			recipeSources = db.recipeSources,
			outlierScope = oScope,
			outlierQuality = oQuality,
			outlierPrices = db.outlierPrices,
			applyAHCut = (db.applyAHCut ~= false),
			subCraftMode = subCraftMode,
			subCraftOverrides = subCraftOverrides,
			profMap = profMap,
			repState = repState,
		})
		app.lastOutlierSummary = summary
		app.lastOutlierRows = rows

		local st = app.sortState.outliers
		ns.SortRows(rows, st.col, st.asc, "outlierScore", { name = true })
		app.ui.outliersTable.updateHeaders()
		app.ui.outliersTable.setRows(rows)

		local byID = {}
		for _, r in ipairs(rows) do byID[r.itemID] = r end
		app.refreshOutlierSelection((app.selectedOutlierItemID and byID[app.selectedOutlierItemID]) or rows[1])

		app.ui.outlierSummaryFs:SetText(string.format(
			"%sUNLISTED: %d|r  ·  %sMonopoly (<=2): %d|r  ·  %s* BiS: %d|r  ·  %sCustom: %d|r",
			palHex("hexText", "ffffff"), summary.unlistedCount,
			palHex("hexWarning", "ff9230"), summary.monopolyCount,
			palHex("hexWarning", "ff9230"), summary.bisCount,
			palHex("hexBlue", "0091ff"), summary.customCount))

		if scanBanner then
			app.ui.statusText:SetText(themeText(scanBanner))
		elseif summary.bestRow then
			app.ui.statusText:SetText(string.format("Top Outlier: %s%s|r (%s profit @ %s) · %d outliers",
				palHex("hexWarning", "ff9230"), summary.bestRow.name, ns.FormatMoneyCompact(summary.bestRow.profit, true), ns.FormatMoneyCompact(summary.bestRow.targetPrice), summary.totalMatched))
		else
			app.ui.statusText:SetText("No outliers matched in " .. econInfo.label)
		end

	elseif t == "crates" then
		app.ui.crateModeBtn:SetText(findLabel(CRATE_MODES, db.crateMode or "cheapest"))
		app.ui.bestOnlyCheck:SetChecked(db.bestOnly and true or false)
		local rows, bestRow, pricedCount, totalCombos, profFallbackFrom = ns.BuildCrateRows({
			search = search,
			bestOnly = db.bestOnly,
			crateMode = db.crateMode or "cheapest",
			subCraftMode = subCraftMode,
			subCraftOverrides = subCraftOverrides,
			profFilter = profFilter,
			unlockFilter = unlockFilter,
			ownedCounts = counts,
			profMap = profMap,
			repState = repState,
		})
		app.bestCratePPT = bestRow and bestRow.pricePerToken or nil
		local st = app.sortState.crates
		ns.SortRows(rows, st.col, st.asc, "pricePerToken", { crateName = true, reagentName = true, mode = true })
		app.ui.cratesTable.updateHeaders()
		app.ui.cratesTable.setRows(rows)
		app.quickLookRows = app.quickLookRows or {}
		app.quickLookRows.crate = rows

		if app.ui.cratesKpis then
			local ck1, ck2, ck3 = app.ui.cratesKpis[1], app.ui.cratesKpis[2], app.ui.cratesKpis[3]
			if ck1 and ck1.SetData then
				ck1:SetData({
					title = "Cheapest Turn-In",
					value = (bestRow and bestRow.pricePerToken) and moneyText(bestRow.pricePerToken) or "--",
					unit = "/ Favor",
					sub = bestRow and tostring(bestRow.crateName or "Crate") or "No priced crates",
					valueColor = false,
				})
			end
			if ck2 and ck2.SetData then
				ck2:SetData({
					title = "Favor on Hand",
					value = favorBal ~= nil and formatComma(favorBal) or "0",
					unit = "Favor",
					sub = tostring(repState.factionName or "Durotar Supply & Logistics"),
					valueColor = false,
				})
			end
			if ck3 and ck3.SetData then
				ck3:SetData({
					title = "Priced Crates",
					value = string.format("%d / %d", pricedCount or 0, totalCombos or 0),
					unit = "options",
					sub = bestRow and string.format("%s: %s %dx", bestRow.mode or "Buy", bestRow.reagentName or "", bestRow.reagentQty or 1) or "Ready",
					valueColor = false,
				})
			end
		end

		local fbNote = profFallbackFrom and (" · " .. palHex("hexWarning", "ff9230") .. "All Crates shown|r") or ""
		if scanBanner then
			app.ui.statusText:SetText(themeText(scanBanner))
		elseif bestRow and bestRow.pricePerToken then
			app.ui.statusText:SetText(string.format("Best Favor: %s%s|r + %dx %s [%s] (%s/tok) · %d/%d%s",
				palHex("hexPositive", "30d158"), bestRow.crateName, bestRow.reagentQty, bestRow.reagentName, bestRow.mode or "Buy", ns.FormatMoneyCompact(bestRow.pricePerToken), pricedCount, totalCombos, fbNote))
		else
			app.ui.statusText:SetText(palHex("hexWarning", "ff9230") .. "No prices in " .. econInfo.label .. " (" .. srcInfo.label .. ")|r" .. fbNote)
		end

	elseif t == "forged" then
		local inlineSearch = app.ui.forgedSearchBox:GetText() or ""
		unifiedSyncOpts.forgedRowsByID = app.refreshForgedView({
			search = inlineSearch:match("%S") and inlineSearch or search,
			forgedMode = db.forgedMode or "self_funded",
			humanDiplomacy = db.forgedHumanDiplomacy,
			tierFilter = db.forgedTierFilter or "all",
			qualityFilter = db.forgedQualityFilter or "all",
			availableOnly = db.forgedAvailFilter == "available",
			forgedTurnInQueue = db.forgedTurnInQueue,
			crateMode = db.crateMode or "cheapest",
			profFilter = profFilter,
			unlockFilter = unlockFilter,
			subCraftMode = subCraftMode,
			subCraftOverrides = subCraftOverrides,
			ownedCounts = counts,
			profMap = profMap,
			repState = repState,
		}, scanBanner)

	elseif t == "writs" then
		local zoneFilter = db.writZoneFilter or "all"
		local includePouch = (db.includeWritPouch ~= false)
		app.ui.writModeBtn:SetText(findLabel(WRIT_MODES, db.writMode or "cheapest"))
		app.ui.writZoneBtn:SetText(formatWritZoneButtonLabel(zoneFilter))
		app.ui.writPouchCheck:SetChecked(includePouch)

		local rows, bestWrit, pricedCount, totalWrits, nearZeroCount = ns.BuildWritRows({
			search = search,
			writMode = db.writMode or "cheapest",
			zoneFilter = zoneFilter,
			includeWritPouch = includePouch,
			writTurnInQueue = db.writTurnInQueue,
			subCraftMode = subCraftMode,
			subCraftOverrides = subCraftOverrides,
			profFilter = profFilter,
			unlockFilter = unlockFilter,
			ownedCounts = counts,
			profMap = profMap,
			repState = repState,
		})
		app.lastWritRows = rows
		app.lastVisibleWritRows = rows
		app.bestWritPPR = bestWrit and bestWrit.pricePerRep or nil
		local st = app.sortState.writs
		ns.SortRows(rows, st.col, st.asc, "pricePerRep", { writName = true, reqItemName = true, zone = true, profSkillSort = true, mode = true })
		app.ui.writsTable.updateHeaders()
		app.ui.writsTable.setRows(rows)
		app.quickLookRows = app.quickLookRows or {}
		app.quickLookRows.writ = rows

		local writByID = {}
		for _, wr in ipairs(rows or {}) do
			if wr.writID and not writByID[wr.writID] then writByID[wr.writID] = wr end
		end
		unifiedSyncOpts.writRowsByID = writByID

		local shopData = ns.BuildWritTurnInShoppingList(rows, db.writTurnInQueue, {
			writMode = db.writMode or "cheapest",
			zoneFilter = zoneFilter,
			includeWritPouch = includePouch,
			profMap = profMap,
			subCraftMode = subCraftMode,
			subCraftOverrides = subCraftOverrides,
			ownedCounts = counts,
		})
		local pouchBadge = includePouch and (palHex("hexPositive", "30d158") .. "Coin Pouch ON (35s 36c / 74s 80c)|r") or (palHex("hexMuted", "98989d") .. "Coin Pouch OFF|r")
		local areaLbl = (zoneFilter == "all") and "All Zones" or ((zoneFilter == "mapped") and "Known Areas" or tostring(zoneFilter))
		local queueText = shopData.hasQueue
			and string.format("Queued: %s%d|r (+%d Rep, Net %s)", palHex("hexText", "ffffff"), shopData.writCount or 0, shopData.totalRep or 0, ns.FormatMoneyCompact(shopData.netCost))
			or ("Queued: " .. palHex("hexMuted", "98989d") .. "0|r")
		app.ui.writsSummaryFs:SetText(string.format(
			"%sArea:|r %s%s|r  ·  %s  ·  %sNear-Zero / Free Writs: %d|r  ·  %s",
			palHex("hexMuted", "98989d"), palHex("hexBlue", "0091ff"), areaLbl, pouchBadge,
			palHex("hexPositive", "30d158"), nearZeroCount or 0, queueText))

		if scanBanner then
			app.ui.statusText:SetText(themeText(scanBanner))
		elseif bestWrit and bestWrit.pricePerRep then
			local pCol = palHex("hexPositive", "30d158")
			app.ui.statusText:SetText(string.format("Best Rep: %s%s|r [%s, %s, +%d] (%s/rep) · %d near-free · %d/%d",
				pCol, bestWrit.writName, bestWrit.zone or "Unmapped", bestWrit.mode, bestWrit.rep,
				ns.FormatMoneyCompact(bestWrit.pricePerRep), nearZeroCount or 0, pricedCount, totalWrits))
		else
			app.ui.statusText:SetText("|cffff8844No Writ prices in " .. econInfo.label .. "|r")
		end

	elseif t == "recipes" then
		if app.cancelWarmSuperListCache then app.cancelWarmSuperListCache() end
		if app.superListProvider then
			app.bestRecipeProfit = app.superListProvider.Refresh(app.buildSuperListContext({
				counts = counts, profMap = profMap, repState = repState,
				econInfo = econInfo, scanBanner = scanBanner, search = search, profFilter = profFilter,
			}))
		end

	elseif t == "all_items" then
		if app.cancelWarmAllItemsCache then app.cancelWarmAllItemsCache() end
		if app.allItemsProvider then
			app.allItemsProvider.Refresh(app.buildAllItemsContext({
				counts = counts, profMap = profMap, repState = repState,
				econInfo = econInfo, scanBanner = scanBanner, search = search,
			}))
		end

	elseif t == "vendor_crafter" then
		if app.cancelWarmVendorCrafterCache then app.cancelWarmVendorCrafterCache() end
		if app.vendorCrafterProvider then
			app.bestVendorCrafterProfit = app.vendorCrafterProvider.Refresh(app.buildVendorCrafterContext({
				counts = counts, profMap = profMap, repState = repState,
				econInfo = econInfo, scanBanner = scanBanner, search = search, profFilter = profFilter,
			}))
		end

	elseif t == "disenchant_crafter" then
		if app.cancelWarmDisenchantCrafterCache then app.cancelWarmDisenchantCrafterCache() end
		if app.disenchantCrafterProvider then
			app.bestDisenchantCrafterProfit = app.disenchantCrafterProvider.Refresh(app.buildDisenchantCrafterContext({
				counts = counts, profMap = profMap, repState = repState,
				econInfo = econInfo, scanBanner = scanBanner, search = search, profFilter = profFilter,
			}))
		end

	elseif t == "sniper_gap" or t == "sniper_vendor" then
		if app.sniperProvider and app.sniperProvider.Refresh then
			app.sniperProvider.Refresh("app_refresh")
		end

	elseif t == "rep" then
		local simOpt = SIM_START_OPTIONS[app.simStartIdx] or SIM_START_OPTIONS[1]
		app.ui.simStartBtn:SetText(simOpt.label)
		app.ui.shippingCheck:SetChecked(db.includeShippingLabel and true or false)
		app.ui.writPouchCheck:SetChecked(db.includeWritPouch ~= false)
		local rankFilter = tonumber(db.repRankFilter) or 0

		local ov = ns.BuildReputationOverview({
			repState = repState,
			profMap = profMap,
			profFilter = profFilter,
			unlockFilter = unlockFilter,
			rankFilter = rankFilter,
			search = search,
			simStartRep = simOpt.val,
			includeShippingLabel = db.includeShippingLabel,
			includeWritPouch = (db.includeWritPouch ~= false),
			zoneFilter = db.writZoneFilter or "all",
		})

		if app.ui.repStandingPill and app.ui.repStandingPill.SetVariant then
			app.ui.repStandingPill:SetVariant("positive", tostring(repState.standingName or "Neutral"))
		end
		if app.ui.repSubFactionFs then
			app.ui.repSubFactionFs:SetText(tostring(repState.factionName or "Durotar Supply & Logistics"))
		end
		do
			local maxT = math.max(1, tonumber(repState.inTierMax) or 3000)
			local curT = math.max(0, math.min(maxT, tonumber(repState.inTierCurrent) or 0))
			if app.ui.repNumFs then
				app.ui.repNumFs:SetText(string.format("%s / %s", formatComma(curT), formatComma(maxT)))
			end
			if app.ui.repMeterBar and app.ui.repMeterBar.SetValue then
				app.ui.repMeterBar:SetValue(curT / maxT)
			end
			if app.ui.repTierLeftFs then
				app.ui.repTierLeftFs:SetText(tostring(repState.standingName or "Neutral"))
			end
			if app.ui.repTierRightFs then
				local nextNames = { [4] = "Friendly", [5] = "Honored", [6] = "Revered", [7] = "Exalted" }
				local nxt = nextNames[repState.standing or 4]
				if nxt then
					app.ui.repTierRightFs:SetText(string.format("%s to %s", formatComma(math.max(0, maxT - curT)), nxt))
				else
					app.ui.repTierRightFs:SetText("Exalted Max")
				end
			end
		end
		if app.ui.repFavorTileFs then
			app.ui.repFavorTileFs:SetText(favorBal ~= nil and formatComma(favorBal) or "0")
		end
		if app.ui.repUnlocksTileFs then
			app.ui.repUnlocksTileFs:SetText(string.format("%d rewards", #(ov.unlocks or {})))
		end

		local rColors = {
			[4] = palHex("hexText", "ffffff"),
			[5] = palHex("hexPositive", "30d158"),
			[6] = palHex("hexBlue", "0091ff"),
			[7] = palHex("hexPurple", "bf5af2"),
			[8] = palHex("hexWarning", "ff9230"),
		}
		for i, m in ipairs(ov.milestones) do
			local rowBtn = app.ui.milestoneRows[i]
			if rowBtn then
				rowBtn.standing = m.standing
				if rankFilter == m.standing then
					rowBtn.bg:SetColorTexture(0.04, 0.52, 1.0, 0.16)
				elseif m.reached then
					rowBtn.bg:SetColorTexture(0.19, 0.82, 0.35, 0.08)
				else
					rowBtn.bg:SetColorTexture(0, 0, 0, 0)
				end
				rowBtn.cells[1]:SetText((rColors[m.standing] or palHex("hexText", "ffffff")) .. m.rankName .. (m.reached and " · Reached" or "") .. "|r")
				rowBtn.cells[2]:SetText(formatComma(m.totalRep))
				rowBtn.cells[3]:SetText(m.repNeeded == 0 and (palHex("hexPositive", "30d158") .. "Done|r") or string.format("%s", formatComma(m.repNeeded)))
				if m.repNeeded == 0 then
					rowBtn.cells[4]:SetText("0 writs")
				else
					rowBtn.cells[4]:SetText(string.format("%d (%d/%d/%d)", m.writsBest, m.writs75, m.writs125, m.writs200))
				end
				if m.repNeeded == 0 then
					rowBtn.cells[5]:SetText("--")
				elseif m.estGoldCost ~= nil and m.estGoldCost <= 0 then
					rowBtn.cells[5]:SetText(palHex("hexPositive", "30d158") .. ns.FormatMoneyCompact(m.estGoldCost) .. "|r")
				else
					rowBtn.cells[5]:SetText(ns.FormatMoneyCompact(m.estGoldCost))
				end
				rowBtn.cells[6]:SetText(tostring(m.unlockSummary or ""))
			end
		end

		for rk, btn in pairs(app.ui.rankBtns) do
			btn:SetActive(rk == rankFilter)
		end

		local writInfo = ov.bestWrit and string.format("Cheapest Writ: %s (%s/rep)", ov.bestWrit.writName, ns.FormatMoneyCompact(ov.bestWrit.pricePerRep)) or "No Writ prices"
		local crateInfo = ov.bestCrate and string.format("Cheapest Favor: %s (%s/F)", ov.bestCrate.crateName, ns.FormatMoneyCompact(ov.bestCrate.pricePerToken)) or "No Crate prices"
		local avgs = getAnalyticsAverages()
		if avgs and avgs.perRep then writInfo = writInfo .. "  ·  My Avg: " .. ns.FormatMoneyCompact(avgs.perRep) .. "/rep" end
		if avgs and avgs.favorPrice then crateInfo = crateInfo .. "  ·  My Avg: " .. ns.FormatMoneyCompact(avgs.favorPrice) .. "/F" end
		app.ui.repHintFs:SetText(palHex("hexSecondary", "ebebf5") .. writInfo .. "  ·  " .. crateInfo .. "|r")
		app.ui.statusText:SetText(scanBanner or string.format("%s: %d / 42,000 Rep (%s)", ov.repState.factionName, ov.currentTotalRep, econInfo.label))

		local st = app.sortState.rep
		ns.SortRows(ov.unlocks, st.col, st.asc, "repSort", { name = true, category = true })
		app.ui.repTable.updateHeaders()
		app.ui.repTable.setRows(ov.unlocks)

	elseif isCalcTab then
		local calcMode = (t == "calc_rep" and "rep") or (t == "calc_favor" and "favor") or (db.calcMode or "favor")
		db.calcMode = calcMode
		app.ui.calcModeBtn:SetText(findLabel(CALC_MODES, calcMode))
		app.ui.respectStockCheck:SetChecked(db.calcRespectStock ~= false)
		if app.lotScanTotal > 0 then
			app.ui.deepScanBtn:SetText(string.format("Stop (%d/%d)", app.lotScanDone, app.lotScanTotal))
		else
			app.ui.deepScanBtn:SetText("Deep Scan AH Lots")
		end

		local isFavor = (calcMode ~= "rep")
		app.ui.calcSubFavorBtn:SetActive(isFavor)
		app.ui.calcSubRepBtn:SetActive(not isFavor)
		app.ui.favorSummaryFs:SetShown(isFavor)
		app.ui.repSummaryFs:SetShown(not isFavor)
		app.ui.favorCtrl:SetShown(isFavor)
		app.ui.favorResetBtn:SetShown(isFavor)
		app.ui.repCalcResetBtn:SetShown(not isFavor)
		app.ui.favorPlanTable.headerBar:SetShown(isFavor)
		app.ui.favorPlanTable.inset:SetShown(isFavor)
		app.ui.repCtrl:SetShown(not isFavor)
		app.ui.repPlanTable.headerBar:SetShown(not isFavor)
		app.ui.repPlanTable.inset:SetShown(not isFavor)

		if isFavor then
			local targetTok = math.max(0, math.floor(tonumber(db.calcFavorTarget) or 150))
			if not (app.ui.favorInput.HasFocus and app.ui.favorInput:HasFocus()) then
				if app.ui.favorInput:GetText() ~= tostring(targetTok) then
					app.ui.favorInput:SetText(tostring(targetTok))
				end
			end
			for pVal, pBtn in pairs(app.ui.favorPresetBtns or {}) do
				pBtn:SetActive(pVal == targetTok)
			end
			app.ui.deductCheck:SetChecked(db.calcDeductFavor and true or false)
			app.ui.calcCrateModeBtn:SetText(findLabel(CRATE_MODES, db.crateMode or "cheapest"))
			app.ui.calcUseOwnedCheck:SetChecked(db.calcUseOwned and true or false)

			local res = ns.SolveFavorShoppingList(targetTok, {
				deductBalance = db.calcDeductFavor,
				crateMode = db.crateMode or "cheapest",
				respectStock = (db.calcRespectStock ~= false),
				useOwned = db.calcUseOwned,
				ownedCounts = counts,
				profFilter = profFilter,
				unlockFilter = unlockFilter,
				subCraftMode = subCraftMode,
				subCraftOverrides = subCraftOverrides,
				profMap = profMap,
				repState = repState,
			})
			app.lastCalcResult = res

			local st = app.sortState.calc_favor
			ns.SortRows(res.comboPlan, st.col, st.asc, "pricePerToken", { crateName = true, reagentName = true, mode = true })
			app.ui.favorPlanTable.updateHeaders()
			app.ui.favorPlanTable.setRows(res.comboPlan)

			if res.netTargetTokens == 0 and res.deductBalance and res.currentFavor >= res.requestedTokens and res.requestedTokens > 0 then
				app.ui.favorSummaryFs:SetText(string.format(
					"|cff33ff33Target Met!|r Holding %d / %d Favor — toggle off 'Deduct My Favor' or raise Target",
					res.currentFavor, res.requestedTokens))
			elseif res.tokensFulfilled == 0 and res.netTargetTokens > 0 then
				app.ui.favorSummaryFs:SetText("|cffff7744No Waylaid Crate prices in " .. econInfo.label .. " — click Refresh AH or switch Econ|r")
			else
				local warn = res.shortfallTokens > 0 and string.format("  |cffff5555(AH Stock Short %d!)|r", res.shortfallTokens) or ""
				local fbTag = res.profFallbackFrom and "  |cffffcc55(All Crates)|r" or ""
				app.ui.favorSummaryFs:SetText(string.format(
					"|cff33ff33+%d Favor|r (%d Crates · %d Combo%s)  ·  Net: %s (%s/tok)%s%s",
					res.tokensFulfilled, res.cratesFilled, res.combosUsed, res.combosUsed == 1 and "" or "s",
					ns.FormatMoneyCompact(res.netCost),
					res.avgPricePerToken and ns.FormatMoneyCompact(res.avgPricePerToken) or "—",
					warn, fbTag))
				local avgs = getAnalyticsAverages()
				if avgs and avgs.favorPrice then
					app.ui.favorSummaryFs:SetText(app.ui.favorSummaryFs:GetText() .. "  ·  |cff88ddffMy Avg:|r " .. ns.FormatMoneyCompact(avgs.favorPrice) .. "|cff88ddff/tok|r")
				end
			end
			app.ui.statusText:SetText(scanBanner or string.format("Favor Calc: %d/%d tokens · %s net (%s)",
				res.tokensFulfilled, res.netTargetTokens, ns.FormatMoneyCompact(res.netCost), econInfo.label))
		else
			local simOpt = SIM_START_OPTIONS[app.simStartIdx] or SIM_START_OPTIONS[1]
			local sourceMode = db.repSourceMode or "hybrid"
			app.ui.repSourceSeg:SetActive(sourceMode, true)
			app.ui.calcSimBtn:SetText(simOpt.label)
			local targetSt = tonumber(db.calcRepTarget) or 8
			for stg, btn in pairs(app.ui.calcRepTargetBtns) do
				btn:SetActive(stg == targetSt)
			end
			app.ui.calcShipCheck:SetChecked(db.includeShippingLabel and true or false)
			app.ui.calcWritModeBtn:SetText(findLabel(WRIT_MODES, db.writMode or "cheapest"))
			app.ui.writZoneBtn:SetText(formatWritZoneButtonLabel(db.writZoneFilter or "all"))
			app.ui.writPouchCheck:SetChecked(db.includeWritPouch ~= false)

			local res = ns.SolveRepShoppingList({
				repState = repState,
				profMap = profMap,
				simStartRep = simOpt.val,
				targetStanding = targetSt,
				includeShippingLabel = db.includeShippingLabel,
				includeWritPouch = (db.includeWritPouch ~= false),
				zoneFilter = db.writZoneFilter or "all",
				writMode = db.writMode or "cheapest",
				repSourceMode = sourceMode,
				forgedMode = db.forgedMode or "self_funded",
				humanDiplomacy = db.forgedHumanDiplomacy,
				profFilter = profFilter,
				unlockFilter = unlockFilter,
				respectStock = (db.calcRespectStock ~= false),
				useOwned = db.calcUseOwned,
				ownedCounts = counts,
				subCraftMode = subCraftMode,
				subCraftOverrides = subCraftOverrides,
			})
			if sourceMode == "forged_only" and not (res.repPlan or res.forgedRows) then
				app.lastCalcResult = nil
				app.renderRepPlan({}, sourceMode)
				app.ui.repSummaryFs:SetText("Forged delivery planning is unavailable")
				app.ui.statusText:SetText(scanBanner or "Forged delivery planning is unavailable")
			else
				app.lastCalcResult = res
				app.renderRepPlan(res, sourceMode)
				local forgedCount, writCount = res.forgedCount or 0, res.writsCompleted or 0
				local net = ns.FormatMoneyCompact(res.totalCost)
				local rate = ns.FormatMoneyCompact(res.avgPricePerRep)
				local countsLabel = string.format("%d Writs", writCount)
				local costsLabel = string.format("Gross %s - Pouch %s = Net %s (%s/rep)",
					ns.FormatMoneyCompact(res.grossSpend or res.totalCost), ns.FormatMoneyCompact(res.pouchRefund or 0), net, rate)
				if forgedCount > 0 then
					local cashback = res.totalCashback or ((res.pouchRefund or 0) + (res.forgedRefund or 0) + (res.crateCashback or 0))
					countsLabel = countsLabel .. string.format(" + %d Forged", forgedCount)
					costsLabel = string.format("Net %s (%s/rep) · Cashback %s", net, rate, ns.FormatMoneyCompact(cashback))
				end
				local avgs = getAnalyticsAverages()
				if avgs and avgs.perRep then
					costsLabel = costsLabel .. " · " .. palHex("hexBlue") .. "My Avg:|r " .. ns.FormatMoneyCompact(avgs.perRep) .. "/rep"
				end
				app.ui.repSummaryFs:SetText(string.format("Need %s Rep -> %s+%s|r (%s)\n%s",
					formatComma(res.repNeeded), palHex("hexBlue"), formatComma(res.repFulfilled), countsLabel, costsLabel))
				local shortfall = (res.shortfallRep or 0) > 0 and string.format(" · %sAH stock short %s Rep|r",
					palHex("hexDanger"), formatComma(res.shortfallRep)) or ""
				app.ui.statusText:SetText(scanBanner or string.format("Rep Calc -> %s: +%s/%s Rep · Net %s (%s)%s",
					res.targetName, formatComma(res.repFulfilled), formatComma(res.repNeeded), net, econInfo.label, shortfall))
			end
		end
	end
	if not (type(t) == "string" and t:sub(1, 5) == "prof_") then
		if app.hasUnifiedShoppingItems and app.hasUnifiedShoppingItems() and app.ensureShoppingListSynced then
			unifiedSyncOpts.profMap = unifiedSyncOpts.profMap or ns.GetPlayerProfessions()
			unifiedSyncOpts.repState = unifiedSyncOpts.repState or ns.GetMerchantReputation()
			unifiedSyncOpts.ownedCounts = unifiedSyncOpts.ownedCounts or ownedCounts()
			app.ensureShoppingListSynced(unifiedSyncOpts)
		else
			app.syncUnifiedShoppingList(unifiedSyncOpts)
		end
	end
end

-- This path changes geometry only; it never calls refresh/evaluation providers.
function app.layoutWindow()
	if app.refreshSkinLayout then app.refreshSkinLayout() end
	if not panel:IsShown() or app.activeTab == "bags" or app._minimized then return end
	if app.syncToolbarCharScope then app.syncToolbarCharScope() end
	local width = mainArea:GetWidth()
	local height = mainArea:GetHeight()
	local custom = ns.Theme.IsCustomSkin and ns.Theme.IsCustomSkin()
	local kpiW = math.max(180, math.floor((width - 32) / 3))
	for _, kpiList in ipairs({ app.ui.dashKpis, app.ui.spreadKpis, app.ui.cratesKpis, app.ui.forgedKpis }) do
		if kpiList and #kpiList >= 2 then
			kpiList[1].frame:SetWidth(kpiW)
			kpiList[2].frame:SetWidth(kpiW)
		end
	end
	local dashHost = app.ui.dashClassicWrap or app.ui.dashboardView
	local dashKpis = app.ui.dashKpis
	local dashGap = custom and 10 or 16
	local dashKpiW = custom and math.floor((width - 20) / 3) or kpiW
	for i = 1, 2 do dashKpis[i].frame:SetWidth(dashKpiW) end
	dashKpis[2].frame:ClearAllPoints()
	dashKpis[2].frame:SetPoint("TOPLEFT", dashKpis[1].frame, "TOPRIGHT", dashGap, 0)
	dashKpis[3].frame:ClearAllPoints()
	dashKpis[3].frame:SetPoint("TOPLEFT", dashKpis[2].frame, "TOPRIGHT", dashGap, 0)
	dashKpis[3].frame:SetPoint("TOPRIGHT", dashHost, "TOPRIGHT", 0, 0)
	if app.ui.dashLeftCard then
		local gap, top = custom and 9 or 16, custom and 78 or 120
		local onboardShown = (app.ui.dashOnboardingCard and app.ui.dashOnboardingCard:IsShown()) and true or false
		local cardsTop = top
		if onboardShown then
			local obH = 82
			app.ui.dashOnboardingCard:ClearAllPoints()
			app.ui.dashOnboardingCard:SetPoint("TOPLEFT", dashHost, "TOPLEFT", 0, -top)
			app.ui.dashOnboardingCard:SetPoint("TOPRIGHT", dashHost, "TOPRIGHT", 0, -top)
			app.ui.dashOnboardingCard:SetHeight(obH)
			cardsTop = top + obH + gap
		end
		local halfW = math.max(240, math.floor((width - gap) / 2))
		local availH = math.max(360, (height or 642) - cardsTop)
		local row2H = math.max(onboardShown and 190 or 238, math.floor((availH - gap) * 0.474))
		if row2H > 286 then row2H = 286 end
		if custom then row2H = math.max(160, math.floor((height - cardsTop - gap) / 2)) end
		app.ui.dashLeftCard:ClearAllPoints()
		app.ui.dashLeftCard:SetPoint("TOPLEFT", dashHost, "TOPLEFT", 0, -cardsTop)
		app.ui.dashRightCard:ClearAllPoints()
		app.ui.dashRightCard:SetPoint("TOPRIGHT", dashHost, "TOPRIGHT", 0, -cardsTop)
		app.ui.dashLeftCard:SetSize(halfW, row2H)
		app.ui.dashRightCard:SetSize(halfW, row2H)
		if app.ui.dashTurninCard then
			app.ui.dashTurninCard:ClearAllPoints()
			app.ui.dashTurninCard:SetPoint("TOPLEFT", dashHost, "TOPLEFT", 0, -cardsTop - row2H - gap)
			app.ui.dashTurninCard:SetPoint("BOTTOMLEFT", dashHost, "BOTTOMLEFT", 0, 0)
			app.ui.dashTurninCard:SetWidth(halfW)
		end
		if app.ui.dashBasketCard then
			app.ui.dashBasketCard:ClearAllPoints()
			app.ui.dashBasketCard:SetPoint("TOPRIGHT", dashHost, "TOPRIGHT", 0, -cardsTop - row2H - gap)
			app.ui.dashBasketCard:SetPoint("BOTTOMRIGHT", dashHost, "BOTTOMRIGHT", 0, 0)
			app.ui.dashBasketCard:SetWidth(halfW)
		end
		local show5th = (row2H >= 280)
		if app.ui.dashCraftRows and app.ui.dashCraftRows[5] then
			app.ui.dashCraftRows[5]:SetShown(show5th and app.ui.dashCraftRows[5].data ~= nil)
		end
		if app.ui.dashOutlierRows and app.ui.dashOutlierRows[5] then
			app.ui.dashOutlierRows[5]:SetShown(show5th and app.ui.dashOutlierRows[5].data ~= nil)
		end
	end
	if app.ensureDashboardBrief then app.ensureDashboardBrief() end
	if app.ui.dashBriefView and app.ui.dashBriefView.Layout then
		app.ui.dashBriefView:Layout(width, height)
	end
	for _, tbl in ipairs(app.ui.resizeTables or {}) do
		if tbl ~= app.ui.recipesTable and tbl ~= app.ui.vendorCrafterTable and tbl ~= app.ui.disenchantCrafterTable and (not tbl.resizeParent.IsVisible or tbl.resizeParent:IsVisible()) then
			ns.Window.LayoutTable(tbl, tbl.headerBar:GetWidth(), tbl.professor and 0 or 1)
		end
	end
	if app.syncSkinTiledCoords then app.syncSkinTiledCoords() end
	if app.superListProvider then app.superListProvider.Layout(width, height) end
	if app.vendorCrafterProvider then app.vendorCrafterProvider.Layout(width, height) end
	if app.disenchantCrafterProvider then app.disenchantCrafterProvider.Layout(width, height) end
	if app.allItemsProvider then app.allItemsProvider.Layout(width, height) end
	if app.watchlistProvider then app.watchlistProvider.Layout(width, height) end
	if app.sniperProvider and app.sniperProvider.Layout then app.sniperProvider.Layout() end
	if app.consoleProvider and app.consoleProvider.Layout then app.consoleProvider.Layout() end
	ns.Window.LayoutAnalytics(ns.Analytics, width, height)
	if ns.DeepAnalysis and ns.DeepAnalysis.Layout then ns.DeepAnalysis.Layout(width, height) end
	if app.professorProvider and app.professorProvider.layout then app.professorProvider.layout() end
	if app.refreshDashKpiLayout then app.refreshDashKpiLayout() end
	if app.refreshDashRowIcons then app.refreshDashRowIcons() end
end

function app.refresh()
	if winChrome.ahRefresh then winChrome.ahRefresh:Update() end
	local panelShown = panel:IsShown()
	local shopShown = (app.ui.shopModal and app.ui.shopModal:IsShown()) and true or false
	if not panelShown and not shopShown then
		notifyRefreshListeners()
		return
	end
	ns.BeginEval(app.getUIPriceBank())
	local savedTab = app.activeTab
	local shopSource = LEGACY_TAB_ROUTES[app.activeShoppingSourceTab] or app.activeShoppingSourceTab
	local forceShopSource = (not panelShown and shopShown and shopSource and shopSource ~= savedTab)
	if forceShopSource then
		app.activeTab = shopSource
	end
	local perfT0 = (ns._consolePerfOn == true and _G.debugprofilestop) and _G.debugprofilestop() or nil
	local ok, err = pcall(function()
		refreshPanelImpl()
	end)
	if perfT0 and ns.ConsoleEngine and ns.ConsoleEngine.RecordUITiming then
		ns.ConsoleEngine.RecordUITiming(app.activeTab, _G.debugprofilestop() - perfT0)
	end
	if forceShopSource then
		app.activeTab = savedTab
	end
	if ok then
		ns.EndEval()
		if panelShown then
			app.layoutWindow()
			local superWarming = app.superListProvider and app.superListProvider.IsWarming and app.superListProvider.IsWarming()
			local superWarm = app.superListProvider and app.superListProvider.HasWarmData and app.superListProvider.HasWarmData()
			if app.activeTab ~= "recipes" and app.superListProvider then
				if superWarming and app.superListProvider.WarmInBackground then
					app.superListProvider.WarmInBackground(app.buildSuperListContext())
				elseif app.warmSuperListCache and not superWarm then
					app.warmSuperListCache(0.05)
				end
			end
			if app.activeTab ~= "vendor_crafter" and app.vendorCrafterProvider
				and app._vcWarmUnsupported ~= app.vendorCrafterProvider
				and superWarm and not superWarming then
				local vcWarming = app.vendorCrafterProvider.IsWarming and app.vendorCrafterProvider.IsWarming()
				local vcWarm = app.vendorCrafterProvider.HasWarmData and app.vendorCrafterProvider.HasWarmData()
				if vcWarming and app.vendorCrafterProvider.WarmInBackground then
					app.vendorCrafterProvider.WarmInBackground(app.buildVendorCrafterContext())
				elseif app.warmVendorCrafterCache and not vcWarm then
					app.warmVendorCrafterCache(0.05)
				end
			end
			local vcDone = (not app.vendorCrafterProvider)
				or (app.vendorCrafterProvider.HasWarmData and app.vendorCrafterProvider.HasWarmData()
					and not (app.vendorCrafterProvider.IsWarming and app.vendorCrafterProvider.IsWarming()))
			if app.activeTab ~= "disenchant_crafter" and app.disenchantCrafterProvider
				and app._dcWarmUnsupported ~= app.disenchantCrafterProvider
				and superWarm and not superWarming and vcDone then
				local dcWarming = app.disenchantCrafterProvider.IsWarming and app.disenchantCrafterProvider.IsWarming()
				local dcWarm = app.disenchantCrafterProvider.HasWarmData and app.disenchantCrafterProvider.HasWarmData()
				if dcWarming and app.disenchantCrafterProvider.WarmInBackground then
					app.disenchantCrafterProvider.WarmInBackground(app.buildDisenchantCrafterContext())
				elseif app.warmDisenchantCrafterCache and not dcWarm then
					app.warmDisenchantCrafterCache(0.05)
				end
			end
			local dcDone = (not app.disenchantCrafterProvider)
				or (app.disenchantCrafterProvider.HasWarmData and app.disenchantCrafterProvider.HasWarmData()
					and not (app.disenchantCrafterProvider.IsWarming and app.disenchantCrafterProvider.IsWarming()))
			if app.activeTab ~= "all_items" and app.allItemsProvider and vcDone and dcDone then
				local aiWarming = app.allItemsProvider.IsWarming and app.allItemsProvider.IsWarming()
				local aiWarm = app.allItemsProvider.HasWarmData and app.allItemsProvider.HasWarmData()
				if aiWarming and app.allItemsProvider.WarmInBackground then
					app.allItemsProvider.WarmInBackground(app.buildAllItemsContext())
				elseif app.warmAllItemsCache and not aiWarm then
					app.warmAllItemsCache(0.05)
				end
			end
		end
		notifyRefreshListeners()
		if app.refreshQuickLook then app.refreshQuickLook() end
	else
		ns.ResetEval()
		error(err)
	end
end

function app.markCurrent()
	if not panel:IsShown() or app.activeTab ~= "bags" then return end
	app.ui.bagBox:ForEachFrame(function(r)
		r.selected:SetShown(r.data.search ~= nil and app.wanted ~= nil and r.data.search == app.wanted.name)
	end)
end

local function anchorPanel()
	applyPanelLayout()
	if panel.userMoved then return end
	local ah = (AuctionHouseFrame and AuctionHouseFrame:IsShown() and AuctionHouseFrame)
		or (AuctionFrame and AuctionFrame:IsShown() and AuctionFrame)
	panel:ClearAllPoints()
	if ah and app.activeTab == "bags" then
		panel:SetPoint("TOPLEFT", ah, "TOPRIGHT", 12, 0)
	else
		panel:SetPoint("CENTER")
	end
end

function app.togglePanel(forceTab)
	if forceTab then
		local wasShown = panel:IsShown()
		app.openedByAH = false
		app.setTab(forceTab)
		anchorPanel()
		if not wasShown then
			panel:Show()
		end
		return
	end
	if panel:IsShown() then
		panel:Hide()
		return
	end
	app.openedByAH = false
	anchorPanel()
	panel:Show()
end

local cooldownRecipes, cooldownBySpell
local function getCooldownCatalog()
	if cooldownRecipes then return cooldownRecipes, cooldownBySpell end
	cooldownRecipes, cooldownBySpell = {}, {}
	for _, r in ipairs(ns.RECIPES or {}) do
		local cd = tonumber(r.cd)
		if cd and cd >= 60 and r.spellID and r.spellID > 0 then
			cooldownRecipes[#cooldownRecipes + 1] = r
			cooldownBySpell[r.spellID] = r
		end
	end
	return cooldownRecipes, cooldownBySpell
end

function app.scanPlayerCooldowns()
	local list = getCooldownCatalog()
	local sig = app._lastCooldownSig
	if not sig then
		sig = {}
		app._lastCooldownSig = sig
		for _, r in ipairs(list) do
			local info = ns.GetRecipeCooldownInfo and ns.GetRecipeCooldownInfo(r)
			if r.spellID then
				sig[r.spellID] = info and (info.onCooldown == true) or false
			end
		end
		return false
	end
	local changed = false
	local changedSpells = {}
	local changedGroups = nil
	for _, r in ipairs(list) do
		local info = ns.GetRecipeCooldownInfo and ns.GetRecipeCooldownInfo(r)
		local state = info and (info.onCooldown == true) or false
		if r.spellID and sig[r.spellID] ~= state then
			sig[r.spellID] = state
			changed = true
			changedSpells[r.spellID] = true
			local grp = ns.GetRecipeCooldownGroup and ns.GetRecipeCooldownGroup(r)
			if grp then
				changedGroups = changedGroups or {}
				changedGroups[grp] = true
			end
		end
	end
	if changedGroups and ns.GetRecipeCooldownGroup then
		for _, r in ipairs(list) do
			if r.spellID then
				local grp = ns.GetRecipeCooldownGroup(r)
				if grp and changedGroups[grp] then
					changedSpells[r.spellID] = true
				end
			end
		end
	end
	if changed then
		if ns.ResetEval then ns.ResetEval() end
		if app.invalidateRecipeStats then app.invalidateRecipeStats("cooldown", changedSpells) end
		if not app.recipeInvalidationBound then
			if ns.SuperList and ns.SuperList.Invalidate then
				ns.SuperList.Invalidate("cooldown", changedSpells)
			end
			if ns.RecipeStats and app.vendorCrafterProvider and app.vendorCrafterProvider.Invalidate then
				app.vendorCrafterProvider.Invalidate("cooldown", changedSpells)
			end
			if ns.RecipeStats and app.disenchantCrafterProvider and app.disenchantCrafterProvider.Invalidate then
				app.disenchantCrafterProvider.Invalidate("cooldown", changedSpells)
			end
			if ns.RecipeStats and app.allItemsProvider and app.allItemsProvider.Invalidate then
				app.allItemsProvider.Invalidate("cooldown", changedSpells)
			end
		end
		if panel:IsShown() and app.refresh then app.refresh() end
	end
	return changed
end

panel:HookScript("OnShow", function()
	if ns.Theme and ns.Theme.FlushPendingRepaint then ns.Theme.FlushPendingRepaint() end
	if ns.EnsureSnapshotsLoaded then ns.EnsureSnapshotsLoaded() end
	if app.refreshSkinLayout then app.refreshSkinLayout() end
	if app.scanPlayerCooldowns then app.scanPlayerCooldowns() end
	app.refresh()
	if app.layoutWindow then app.layoutWindow() end
end)

if ns.Theme and ns.Theme.OnModeChanged then
	local _refreshingMode = false
	ns.Theme.OnModeChanged(function(mode)
		-- Persist the player's own Dark/Light choice; a Warcraft skin reports an effective "dark" that must never overwrite it.
		if MerchantMasterDB then
			MerchantMasterDB.uiThemeMode = (ns.Theme.GetUserMode and ns.Theme.GetUserMode()) or mode
		end
		if _refreshingMode or app._skinSwitching then return end
		_refreshingMode = true
		if panel:IsShown() and app.refresh then
			app.refresh()
		elseif app.ui.appearanceSwitch and app.ui.appearanceSwitch.UpdateTheme then
			app.ui.appearanceSwitch:UpdateTheme()
		end
		_refreshingMode = false
	end)
end

