			app.disenchantCrafterProvider.CancelPresentation()
		elseif app.disenchantCrafterProvider.Cancel then
			app.disenchantCrafterProvider.Cancel()
		end
	end
	if app.allItemsProvider then
		if app.allItemsProvider.CancelPresentation then
			app.allItemsProvider.CancelPresentation()
		elseif app.allItemsProvider.Cancel then
			app.allItemsProvider.Cancel()
