local function addAHSearchBarButton()
	if InCombatLockdown and InCombatLockdown() then return end
	local barFrame = AuctionHouseFrame and AuctionHouseFrame.SearchBar
	if app.ui.ahBtn or not (barFrame and barFrame.FilterButton) then return end
	local btn = CreateFrame("Button", nil, barFrame)
	btn:SetSize(28, 28)
	btn:SetPoint("RIGHT", barFrame.FilterButton, "LEFT", -8, 0)
	if barFrame.SearchBox then
		barFrame.SearchBox:SetPoint("RIGHT", btn, "LEFT", -8, 0)
	end
	if btn.SetText then btn:SetText("") end
	if btn.RegisterForClicks then btn:RegisterForClicks("LeftButtonUp", "RightButtonUp") end
	local icon = btn:CreateTexture(nil, "ARTWORK")
	icon:SetAllPoints(btn)
	icon:SetTexture(ns.ADDON_ICON_SMALL)
	if icon.SetTexCoord then icon:SetTexCoord(0, 1, 0, 1) end
	btn.icon = icon
	local hl = btn:CreateTexture(nil, "HIGHLIGHT")
	hl:SetAllPoints(btn)
	hl:SetTexture(ns.ADDON_ICON_SMALL)
	if hl.SetTexCoord then hl:SetTexCoord(0, 1, 0, 1) end
	if hl.SetBlendMode then hl:SetBlendMode("ADD") end
	if hl.SetAlpha then hl:SetAlpha(0.28) end
	btn.highlight = hl
	btn:SetScript("OnMouseDown", function(self)
		self.icon:ClearAllPoints()
		self.icon:SetPoint("TOPLEFT", self, "TOPLEFT", 1, -1)
		self.icon:SetPoint("BOTTOMRIGHT", self, "BOTTOMRIGHT", 1, -1)
	end)
	btn:SetScript("OnMouseUp", function(self)
		self.icon:ClearAllPoints()
		self.icon:SetAllPoints(self)
	end)
	btn:SetScript("OnClick", function(_, mouseBtn)
		if mouseBtn == "RightButton" then
			if not panel:IsShown() then app.togglePanel() end
			app.refreshAllMarketValues()
		elseif IsShiftKeyDown and IsShiftKeyDown() and ns.AHSellTab and ns.AHSellTab.SelectTab then
			ns.AHSellTab.SelectTab()
		else
			app.togglePanel()
		end
	end)
	btn:SetScript("OnEnter", function(self)
		GameTooltip:SetOwner(self, "ANCHOR_TOP")
		GameTooltip:AddLine("MerchantMaster", 1, 0.82, 0)
		GameTooltip:AddLine("Left-Click: Open or close MerchantMaster", 0.9, 0.9, 0.92)
		GameTooltip:AddLine("Shift-Click: Open MM Sell tab", 0.72, 0.96, 0.78)
		GameTooltip:AddLine("Right-Click: Open and refresh Auction House market values", 0.72, 0.86, 1)
		GameTooltip:Show()
	end)
	btn:SetScript("OnLeave", GameTooltip_Hide)
	if hooksecurefunc and barFrame.SetSearchText then
		hooksecurefunc(barFrame, "SetSearchText", function()
			if type(resetModernFilters) == "function" then resetModernFilters(AuctionHouseFrame) end
		end)
	end
	app.ui.ahBtn = btn
end

