local LDB = LibStub("LibDataBroker-1.1")
local DBIcon = LibStub("LibDBIcon-1.0")

local function toggleMinimap()
	if not MerchantMasterDB then return end
	MerchantMasterDB.minimap = MerchantMasterDB.minimap or {}
	MerchantMasterDB.minimap.hide = not MerchantMasterDB.minimap.hide
	if MerchantMasterDB.minimap.hide then
		DBIcon:Hide(ADDON)
		say("Minimap button hidden. Type /mm minimap to show it again.")
	else
		DBIcon:Show(ADDON)
	end
	if app.consoleProvider and app.consoleProvider.SyncSettings then app.consoleProvider.SyncSettings() end
end

app.launcher = LDB:NewDataObject(ADDON, {
	type = "launcher",
	label = "MerchantMaster",
	icon = ns.ADDON_ICON_SMALL,
	iconCoords = { 0, 1, 0, 1 },
	OnClick = function(_, button)
		if button == "LeftButton" then
			app.togglePanel()
		elseif button == "RightButton" then
			if not panel:IsShown() then app.togglePanel() end
			app.refreshAllMarketValues()
		elseif button == "MiddleButton" then
			toggleMinimap()
		end
	end,
	OnTooltipShow = function(tooltip)
		ns.BeginEval(app.getUIPriceBank())
		local econ = ns.CurrentEconomyInfo()
		local db = MerchantMasterDB or {}
		tooltip:AddDoubleLine("MerchantMaster", econ.buttonLabel, 1, 0.82, 0, 0.5, 0.85, 1)
		local _, bestCrate = ns.BuildCrateRows({ bestOnly = false, crateMode = db.crateMode or "cheapest" })
		if bestCrate and bestCrate.pricePerToken then
			tooltip:AddDoubleLine("Best Favor Crate:", string.format("%s [%s] (%s/tok)", bestCrate.crateName, bestCrate.mode or "Buy", ns.FormatMoneyCompact(bestCrate.pricePerToken)), 0.85, 0.85, 0.85, 0.2, 1, 0.2)
		end
		local _, bestWrit = ns.BuildWritRows({ writMode = db.writMode or "cheapest", includeWritPouch = (db.includeWritPouch ~= false) })
		if bestWrit and bestWrit.pricePerRep then
			tooltip:AddDoubleLine("Best Rep Writ:", string.format("%s [%s] (%s/rep)", bestWrit.writName, bestWrit.mode, ns.FormatMoneyCompact(bestWrit.pricePerRep)), 0.85, 0.85, 0.85, 0.4, 0.9, 1)
		end
		ns.EndEval()
		tooltip:AddLine(" ")
		tooltip:AddLine("Left-Click: open/close  ·  Right-Click: refresh AH  ·  Middle-Click: hide icon", 0.65, 0.65, 0.65)
	end,
})

local function registerMinimap()
	MerchantMasterDB.minimap = MerchantMasterDB.minimap or {}
	bagCrates()
	app.launcher.icon = ns.ADDON_ICON_SMALL
	if DBIcon.IsRegistered and DBIcon:IsRegistered(ADDON) then return end
	DBIcon:Register(ADDON, app.launcher, MerchantMasterDB.minimap)
	local mmBtn = DBIcon.GetMinimapButton and DBIcon:GetMinimapButton(ADDON)
	if mmBtn then
		if DBIcon.RemoveButtonBorder then DBIcon:RemoveButtonBorder(ADDON) end
		if DBIcon.RemoveButtonBackground then DBIcon:RemoveButtonBackground(ADDON) end
		if DBIcon.SetButtonIcon then DBIcon:SetButtonIcon(ADDON, ns.ADDON_ICON_SMALL, 30, "CENTER", 0, 0) end
		if mmBtn.icon and mmBtn.icon.SetTexCoord then
			mmBtn.icon:SetTexCoord(0, 1, 0, 1)
			mmBtn.icon.UpdateCoord = function(self)
				if self.SetTexCoord then self:SetTexCoord(0, 1, 0, 1) end
			end
		end
	end
	if DBIcon.AddButtonToCompartment then DBIcon:AddButtonToCompartment(ADDON) end
end

