local function hasOpenTradeSkillRecipes()
	if C_TradeSkillUI and C_TradeSkillUI.GetAllRecipeIDs then
		local ok, ids = pcall(C_TradeSkillUI.GetAllRecipeIDs)
		if ok and type(ids) == "table" and #ids > 0 then return true end
	end
	if GetNumTradeSkills then
		local ok, n = pcall(GetNumTradeSkills)
		if ok and type(n) == "number" and n > 0 then return true end
	end
	if GetNumCrafts then
		local ok, n = pcall(GetNumCrafts)
		if ok and type(n) == "number" and n > 0 then return true end
	end
	return false
end

local function isPlayerCasting()
	if UnitCastingInfo and UnitCastingInfo("player") then return true end
	if UnitChannelInfo and UnitChannelInfo("player") then return true end
	return false
end

local function isRecentlyCrafting()
	if isPlayerCasting() then return true end
	local now = GetTime and GetTime() or 0
	local last = app._lastCraftEventTime or 0
	return last > 0 and now > 0 and (now - last) < 2.2
end

local function scheduleRefresh(reason)
	if reason == "items" and (app.superListProvider or app.vendorCrafterProvider or app.disenchantCrafterProvider or app.allItemsProvider) then return end
	if not panel:IsShown() then return end
	local isProfTab = type(app.activeTab) == "string" and app.activeTab:sub(1, 5) == "prof_"
	if isProfTab and (reason == "bags" or reason == "skills" or reason == "professor") then
		app._profRefreshSeq = (app._profRefreshSeq or 0) + 1
		local seq = app._profRefreshSeq
		local delay = isRecentlyCrafting() and 2.2 or 1.2
		local function runWhenIdle(attempts)
			if app._profRefreshSeq ~= seq or not panel:IsShown() then return end
			if isRecentlyCrafting() and (attempts or 0) < 30 then
				C_Timer.After(1.0, function() runWhenIdle((attempts or 0) + 1) end)
				return
			end
			app.refresh()
		end
		C_Timer.After(delay, function() runWhenIdle(0) end)
		return
	end
	if app.refreshScheduled then return end
	app.refreshScheduled = true
	C_Timer.After(0.15, function()
		app.refreshScheduled = false
		app.refresh()
	end)
end
app.scheduleRecipeRefresh = scheduleRefresh
app.scheduleRefresh = scheduleRefresh

local function scheduleItemInfoRefresh()
	if not panel:IsShown() then return end
	app.itemInfoRefreshSeq = (app.itemInfoRefreshSeq or 0) + 1
	local seq = app.itemInfoRefreshSeq
	C_Timer.After(0.50, function()
		if app.itemInfoRefreshSeq == seq and panel:IsShown() then
			if app.activeTab == "recipes" or app.activeTab == "all_items" or app.activeTab == "vendor_crafter" or app.activeTab == "disenchant_crafter" then return end
			if app.uiPriceBank and app.uiPriceBank.itemNames then
				wipe(app.uiPriceBank.itemNames)
			end
			if app.uiPriceBank and app.uiPriceBank.vendorSell then
				wipe(app.uiPriceBank.vendorSell)
			end
			if ns.MP and ns.MP.InvalidateSolveCache then
				ns.MP.InvalidateSolveCache()
			end
			app.refresh()
		end
	end)
end

local function isOrderFlowVisible()
	return (app._ahBuyingMode == true) or (app.ui.cartBuyerModal and app.ui.cartBuyerModal:IsShown())
end

local function hasPendingCraftTasks()
	if not (app.orderFlow and app.orderFlow.GetState) then return false end
	local ofSt = app.orderFlow.GetState()
	local tasks = ofSt and ofSt.stages and ofSt.stages.craft and ofSt.stages.craft.tasks
	if type(tasks) ~= "table" then return false end
	for _, t in ipairs(tasks) do
		if (t.remainingCrafts or 0) > 0 and t.status ~= "done" and t.status ~= "skipped" then
			return true
		end
	end
	return false
end

local function purgeStaleSingleWordSelfChars(activeEcon, realm, playerFaction, player, firstName, playerGuid, newKey)
	if not (player and firstName and player ~= firstName and MerchantMasterDB and MerchantMasterDB.chars) then
		return 0
	end
	local firstLow = firstName:lower()
	local staleKeys = {}
	for k, c in pairs(MerchantMasterDB.chars) do
		if k ~= newKey and type(c) == "table" and type(c.name) == "string" and c.name:lower() == firstLow then
			local sameScope = (c.economy == activeEcon) or (c.realm == realm and c.faction == playerFaction)
			if sameScope and (c.guid == nil or (playerGuid and c.guid == playerGuid)) then
				staleKeys[#staleKeys + 1] = k
			end
		end
	end
	if #staleKeys == 0 then return 0 end
	local targetChar = MerchantMasterDB.chars[newKey]
	if type(targetChar) ~= "table" then
		targetChar = {}
		MerchantMasterDB.chars[newKey] = targetChar
	end
	for _, oldKey in ipairs(staleKeys) do
		local oldChar = MerchantMasterDB.chars[oldKey]
		if type(oldChar) == "table" then
			-- Never carry stale bags/boundBags into the full-name character record
			for _, fld in ipairs({ "bank", "boundBank", "mail", "knownSpells", "knownOutputs", "knownNames", "scannedProfs", "cooldowns", "cooldownGroups", "writCooldowns" }) do
				if type(oldChar[fld]) == "table" then
					targetChar[fld] = targetChar[fld] or {}
					for k, v in pairs(oldChar[fld]) do
						if targetChar[fld][k] == nil then
							targetChar[fld][k] = v
						end
					end
				end
			end
		end
		MerchantMasterDB.chars[oldKey] = nil
	end
	return #staleKeys
end

local function flushBagResync(forceAll)
	app.bagsDirty = true
	app.bagCountsDirty = true
	if app.atBank then scanBank() end
	local oldBags = app.char and app.char.bags
	local oldByID = app._lastBagCountsByID or app.cachedBagCountsByID
	local counts = app.charKey and bagCounts()
	local newByID = app.cachedBagCountsByID
	if counts and (forceAll or not sameCounts(oldBags, counts) or (oldByID and not sameCounts(oldByID, newByID))) then
		local changedNames, changedIDs = {}, {}
		for k, v in pairs(oldBags or {}) do
			if (v or 0) ~= ((counts or {})[k] or 0) then changedNames[k] = true end
		end
		for k, v in pairs(counts or {}) do
			if (v or 0) ~= ((oldBags or {})[k] or 0) then changedNames[k] = true end
		end
		if oldByID then
			for k, v in pairs(oldByID) do
				if (v or 0) ~= ((newByID or {})[k] or 0) then changedIDs[k] = true end
			end
			for k, v in pairs(newByID or {}) do
				if (v or 0) ~= ((oldByID or {})[k] or 0) then changedIDs[k] = true end
			end
		else
			for name in pairs(changedNames) do
				local id = lookupID(name)
				if id and id > 0 then changedIDs[id] = true end
			end
		end
		local changedBag = { names = changedNames, ids = changedIDs }
		if app.char then app.char.bags = counts end
		app._lastBagCountsByID = copyCountsTable(newByID or {})
		app.invalidateRecipeStats("ownership", changedBag)
		if ns.MapPins and ns.MapPins.InvalidateOwnership then ns.MapPins.InvalidateOwnership() end
		local isProfTab = type(app.activeTab) == "string" and app.activeTab:sub(1, 5) == "prof_"
		local pdb = isProfTab and ns.GetProfessorDB and ns.GetProfessorDB() or nil
		if forceAll or not (isProfTab and pdb and pdb.useOwned == false) then
			scheduleRefresh("bags")
		end
		if isOrderFlowVisible() and app.syncOrderFlowDockAndRender then
			app.syncOrderFlowDockAndRender()
		end
	elseif counts and not app._lastBagCountsByID and newByID then
		app._lastBagCountsByID = copyCountsTable(newByID)
	end
	if app.orderFlow and app.orderFlow.OnBagUpdateDelayed and (forceAll or isOrderFlowVisible()) then
		app.orderFlow.OnBagUpdateDelayed()
	end
	return counts
end

local bagResyncQueued = false
local function scheduleBagResync()
	if bagResyncQueued then return end
	if C_Timer and C_Timer.After then
		bagResyncQueued = true
		C_Timer.After(0, function()
			bagResyncQueued = false
			flushBagResync(false)
		end)
	else
		flushBagResync(false)
	end
end

function app.resyncBags(verbose)
	local realm = (app.char and app.char.realm) or (GetRealmName and GetRealmName()) or "Forever"
	local player, firstName = getForeverPlayerName()
	local playerGuid = (app.char and app.char.guid) or (_G.UnitGUID and _G.UnitGUID("player")) or nil
	local playerFaction = (app.char and app.char.faction) or (UnitFactionGroup and UnitFactionGroup("player")) or "Horde"
	local activeEcon = (app.char and app.char.economy) or (ns.DetectActiveEconomy and ns.DetectActiveEconomy()) or "A"
	local curKey = app.charKey or (activeEcon .. "-" .. realm .. "-" .. player)
	if MerchantMasterDB and MerchantMasterDB.chars then
		local curRec = MerchantMasterDB.chars[curKey]
		if type(curRec) ~= "table" then
			curRec = app.char or {}
			MerchantMasterDB.chars[curKey] = curRec
		end
		curRec.name = player
		curRec.firstName = firstName
		if playerGuid then curRec.guid = playerGuid end
		curRec.realm = realm
		curRec.faction = playerFaction
		curRec.economy = activeEcon
	end
	local purged = 0
	if ns.Analytics and ns.Analytics.Store and ns.Analytics.Store.MigrateForeverSurnames then
		if ns.Analytics.Store.Init and not ns.Analytics.Store.initialized then ns.Analytics.Store.Init() end
		local migCount = ns.Analytics.Store.MigrateForeverSurnames(MerchantMasterDB and MerchantMasterDB.chars, curKey)
		purged = purged + (tonumber(migCount) or 0)
	end
	purged = purged + purgeStaleSingleWordSelfChars(activeEcon, realm, playerFaction, player, firstName, playerGuid, curKey)
	app.bagsDirty = true
	app.bagCountsDirty = true
	app.cachedBagCounts = nil
	app.cachedBagCountsByID = nil
	app._lastBagCountsByID = nil
	app._cachedOwnedCountsByID = nil
	app.ownershipRev = (app.ownershipRev or 0) + 1
	local counts = flushBagResync(true) or {}
	local bagTypes = 0
	for _ in pairs(counts) do bagTypes = bagTypes + 1 end
	local otherChars = {}
	if MerchantMasterDB and MerchantMasterDB.chars then
		for k, c in pairs(MerchantMasterDB.chars) do
			if k ~= app.charKey and type(c) == "table" then
				otherChars[#otherChars + 1] = tostring(c.name or k)
			end
		end
	end
	table.sort(otherChars)
	if verbose then
		local charNm = (app.char and app.char.name) or player
		local purgeNote = (purged > 0) and string.format(" (purged %d stale self record(s))", purged) or ""
		local otherStr = (#otherChars > 0) and table.concat(otherChars, ", ") or "none"
		say(string.format("Resynced %s: %d live bag item type(s)%s.", charNm, bagTypes, purgeNote))
		say("Other saved characters in MerchantMasterDB: " .. otherStr .. ".")
	end
	return {
		character = (app.char and app.char.name) or player,
		bagTypes = bagTypes,
		purged = purged,
		otherChars = otherChars,
	}
end

local function syncOrderFlowDockAndRender()
	if isOrderFlowVisible() and app.ui.cartBuyerModal and app.ui.cartBuyerModal:IsShown() then
		if app.dockCartBuyerModal then app.dockCartBuyerModal() end
		if app.ui.cartBuyerModal.Render then app.ui.cartBuyerModal.Render() end
	end
end
app.syncOrderFlowDockAndRender = syncOrderFlowDockAndRender

local function handleOrderFlowMerchantOpen(isShowEvent)
	if ns.CaptureMerchantVendorPrices then
		local prevEpoch = ns.priceCacheEpoch
		local okCap = pcall(ns.CaptureMerchantVendorPrices)
		if okCap and ns.priceCacheEpoch ~= prevEpoch then
			app.invalidateRecipeStats("prices")
			if panel:IsShown() then scheduleRefresh() end
		end
	end
	if isShowEvent and app.ensureMerchantFrameHooked then
		app.ensureMerchantFrameHooked()
	end
	if app.orderFlow then
		if isShowEvent and app.orderFlow.OnMerchantShow then
			app.orderFlow.OnMerchantShow()
			syncOrderFlowDockAndRender()
			if isOrderFlowVisible() and C_Timer and C_Timer.After then
				C_Timer.After(0, function()
					if app.orderFlow and app.orderFlow.OnMerchantUpdate and isOrderFlowVisible() then
						app.orderFlow.OnMerchantUpdate()
						syncOrderFlowDockAndRender()
					end
				end)
			end
		elseif (not isShowEvent) and app.orderFlow.OnMerchantUpdate then
			app.orderFlow.OnMerchantUpdate()
			syncOrderFlowDockAndRender()
		end
	end
end

local deCapture = {
	lastBagTarget = nil,
	pendingCast = nil,
	lootSession = nil,
}
;(function()
local DISENCHANT_SPELL_ID = 13262
local DE_LOOT_WINDOW_SEC = 4.0
local DE_LOOT_OPEN_TIMEOUT_SEC = 120.0
local DE_TARGET_WINDOW_SEC = 6.0
local hookedDEContainerFns = setmetatable({}, { __mode = "k" })

local function getBagSlotLinkAndID(bag, slot)
	if type(bag) ~= "number" or type(slot) ~= "number" then return nil, nil end
	local link
	if _G.C_Container and _G.C_Container.GetContainerItemLink then
		local ok, l = pcall(_G.C_Container.GetContainerItemLink, bag, slot)
		if ok and not isSecretVal(l) and type(l) == "string" and l ~= "" then link = l end
	elseif _G.GetContainerItemLink then
		local ok, l = pcall(_G.GetContainerItemLink, bag, slot)
		if ok and not isSecretVal(l) and type(l) == "string" and l ~= "" then link = l end
	end
	local id = link and tonumber(link:match("item:(%d+)")) or nil
	if (not id or not link) and _G.C_Container and _G.C_Container.GetContainerItemInfo then
		local ok, info = pcall(_G.C_Container.GetContainerItemInfo, bag, slot)
		if ok and type(info) == "table" and not isSecretTbl(info) then
			if not id and not isSecretVal(info.itemID) then id = tonumber(info.itemID) end
			if not link and not isSecretVal(info.hyperlink) and type(info.hyperlink) == "string" then link = info.hyperlink end
		end
	elseif (not id or not link) and _G.GetContainerItemInfo then
		local ok, _, _, _, _, _, _, l = pcall(_G.GetContainerItemInfo, bag, slot)
		if ok and not isSecretVal(l) and type(l) == "string" and l ~= "" then
			link = link or l
			id = id or tonumber(l:match("item:(%d+)"))
		end
	end
	return id, link
end

function ns.NotifyDisenchantTarget(bag, slot, itemID, itemLink, source, arcaneSalvager)
	local id = tonumber(itemID)
	local link = (type(itemLink) == "string" and itemLink ~= "") and itemLink or nil
	if (not id or id <= 0) and link then
		id = tonumber(link:match("item:(%d+)"))
	end
	if not id or id <= 0 then return false end
	local now = (GetTime and GetTime()) or 0
	deCapture.lastBagTarget = {
		bag = bag,
		slot = slot,
		itemID = id,
		itemLink = link,
		source = (source == "helper") and "helper" or "manual",
		arcaneSalvager = arcaneSalvager,
		at = now,
	}
	return true
end

local function onContainerUseHook(bag, slot)
	if isSecretVal(bag) or isSecretVal(slot) then return end
	if type(bag) ~= "number" or type(slot) ~= "number" then return end
	local now = (GetTime and GetTime()) or 0
	local prev = deCapture.lastBagTarget
	-- Preserve DisenchantHelper PreClick attribution when SecureActionButton executes /use bag slot
	if prev and prev.source == "helper" and prev.bag == bag and prev.slot == slot and (now - (prev.at or 0)) <= 1.0 then
		prev.at = now
		return
	end
	local id, link = getBagSlotLinkAndID(bag, slot)
	if not id or id <= 0 then return end
	if ns.IsItemDisenchantable and ns.IsItemDisenchantable(id, link) == false then
		return
	end
	ns.NotifyDisenchantTarget(bag, slot, id, link, "manual", nil)
end

local function onSpellTargetItemHook(targetArg)
	if isSecretVal(targetArg) or type(targetArg) ~= "string" or targetArg == "" then return end
	local id = tonumber(targetArg:match("item:(%d+)"))
	if not id or id <= 0 then return end
	if ns.IsItemDisenchantable and ns.IsItemDisenchantable(id, targetArg) == false then
		return
	end
	ns.NotifyDisenchantTarget(nil, nil, id, targetArg, "manual", nil)
end

function app.ensureDEContainerHooks()
	if not _G.hooksecurefunc then return end
	if _G.C_Container and type(_G.C_Container.UseContainerItem) == "function"
		and not hookedDEContainerFns[_G.C_Container.UseContainerItem] then
		local fn = _G.C_Container.UseContainerItem
		hookedDEContainerFns[fn] = true
		_G.hooksecurefunc(_G.C_Container, "UseContainerItem", onContainerUseHook)
		if type(_G.C_Container.UseContainerItem) == "function" then
			hookedDEContainerFns[_G.C_Container.UseContainerItem] = true
		end
	end
	if type(_G.UseContainerItem) == "function" and not hookedDEContainerFns[_G.UseContainerItem] then
		local fn = _G.UseContainerItem
		hookedDEContainerFns[fn] = true
		_G.hooksecurefunc("UseContainerItem", onContainerUseHook)
		if type(_G.UseContainerItem) == "function" then
			hookedDEContainerFns[_G.UseContainerItem] = true
		end
	end
	if type(_G.SpellTargetItem) == "function" and not hookedDEContainerFns[_G.SpellTargetItem] then
		local fn = _G.SpellTargetItem
		hookedDEContainerFns[fn] = true
		_G.hooksecurefunc("SpellTargetItem", onSpellTargetItemHook)
		if type(_G.SpellTargetItem) == "function" then
			hookedDEContainerFns[_G.SpellTargetItem] = true
		end
	end
end
app.ensureDEContainerHooks()

local function isDisenchantSpellID(spID)
	if type(spID) ~= "number" then return false end
	if spID == DISENCHANT_SPELL_ID then return true end
	if _G.GetSpellInfo then
		local ok, name = pcall(_G.GetSpellInfo, spID)
		if ok and not isSecretVal(name) and name == "Disenchant" then
			return true
		end
	end
	return false
end

local function getItemDisplayName(itemID, itemLink)
	if type(itemLink) == "string" and itemLink ~= "" then
		local bracketed = itemLink:match("%[(.-)%]")
		if bracketed and bracketed ~= "" then return bracketed end
	end
	local getInfo = (_G.C_Item and _G.C_Item.GetItemInfo) or _G.GetItemInfo
	if getInfo and (itemLink or itemID) then
		local ok, name = pcall(getInfo, itemLink or itemID)
		if ok and not isSecretVal(name) and type(name) == "string" and name ~= "" then
			return name
		end
	end
	if itemID and ns.ITEM_NAMES_BY_ID and ns.ITEM_NAMES_BY_ID[itemID] then
		return ns.ITEM_NAMES_BY_ID[itemID]
	end
	return nil
end

local function escapeLuaPattern(s)
	return (tostring(s):gsub("([%^%$%(%)%%%.%[%]%*%+%-%?])", "%%%1"))
end

local function wowFormatToPattern(fmt)
	if type(fmt) ~= "string" or fmt == "" then return nil end
	local pat = fmt:gsub("%%%d+%$([sd])", "%%%1")
	local tokens = {}
	pat = pat:gsub("%%([sd])", function(t)
		tokens[#tokens + 1] = t
		return "\001" .. tostring(#tokens) .. "\002"
	end)
	pat = escapeLuaPattern(pat)
	pat = pat:gsub("\001(%d+)\002", function(idx)
		local t = tokens[tonumber(idx)]
		return (t == "d") and "(%d+)" or "(.-)"
	end)
	return "^" .. pat .. "$"
end

local function isSelfDELootChatMessage(msg)
	if type(msg) ~= "string" or msg == "" then return false end
	local selfPat1 = wowFormatToPattern(_G.LOOT_ITEM_SELF_MULTIPLE)
	local selfPat2 = wowFormatToPattern(_G.LOOT_ITEM_SELF)
	if (selfPat1 and msg:match(selfPat1)) or (selfPat2 and msg:match(selfPat2)) then
		return true
	end
	local otherPat1 = wowFormatToPattern(_G.LOOT_ITEM_MULTIPLE)
	local otherPat2 = wowFormatToPattern(_G.LOOT_ITEM)
	if (otherPat1 and msg:match(otherPat1)) or (otherPat2 and msg:match(otherPat2)) then
		return false
	end
	if selfPat1 or selfPat2 then
		return msg:find("You receive loot:", 1, true) ~= nil
	end
	if msg:find("receives loot:", 1, true) then
		return false
	end
	return msg:find("item:%d+") ~= nil
end

local function findBagItemByName(targetName)
	if type(targetName) ~= "string" or targetName == "" then return nil, nil end
	local maxBags = (_G.NUM_BAG_SLOTS ~= nil) and tonumber(_G.NUM_BAG_SLOTS) or 4
	local getInfo = (_G.C_Item and _G.C_Item.GetItemInfo) or _G.GetItemInfo
	for bag = 0, maxBags do
		local slots = 0
		if _G.C_Container and _G.C_Container.GetContainerNumSlots then
			slots = tonumber(_G.C_Container.GetContainerNumSlots(bag)) or 0
		elseif _G.GetContainerNumSlots then
			slots = tonumber(_G.GetContainerNumSlots(bag)) or 0
		end
		for slot = 1, slots do
			local id, link = getBagSlotLinkAndID(bag, slot)
			if id and id > 0 then
				local itemName = (link and link:match("%[(.-)%]"))
					or (getInfo and select(1, getInfo(link or id)))
					or (ns.ITEM_NAMES_BY_ID and ns.ITEM_NAMES_BY_ID[id])
				if itemName == targetName and (not ns.IsItemDisenchantable or ns.IsItemDisenchantable(id, link) ~= false) then
					return id, link
				end
			end
		end
	end
	return nil, nil
end

local function resolveDisenchantTarget(targetName)
	local now = (GetTime and GetTime()) or 0
	local hasTargetName = (type(targetName) == "string" and targetName ~= "")
	local t = deCapture.lastBagTarget
	local bagTargetValid = t and (now - (t.at or 0)) <= DE_TARGET_WINDOW_SEC
	if bagTargetValid then
		local tName = getItemDisplayName(t.itemID, t.itemLink)
		if (not hasTargetName) or tName == targetName then
			return t.itemID, t.itemLink, t.source or "manual", t.arcaneSalvager
		end
	end
	if ns.DisenchantHelper and ns.DisenchantHelper.GetState and ns.DisenchantHelper.GetActiveTarget then
		local st = ns.DisenchantHelper.GetState()
		if st and st.shown then
			local _, _, id, link, asOn = ns.DisenchantHelper.GetActiveTarget()
			if id and id > 0 then
				local hName = getItemDisplayName(id, link)
				if (not hasTargetName) or hName == targetName then
					return id, link, "helper", asOn
				end
			end
		end
	end
	if hasTargetName then
		local id, link = findBagItemByName(targetName)
		if id then
			return id, link, "manual", nil
		end
	end
	if bagTargetValid and getItemDisplayName(t.itemID, t.itemLink) == nil then
		return t.itemID, t.itemLink, t.source or "manual", t.arcaneSalvager
	end
	return nil, nil, "manual", nil
end

local function clearDELiveCaptureState(clearLoot)
	deCapture.lastBagTarget = nil
	deCapture.pendingCast = nil
	if clearLoot then
		deCapture.lootSession = nil
	end
end

local function isDELootSessionExpired(s, now)
	if not s then return true end
	if s.lootOpened then
		return (now - (s.openedAt or s.succeededAt or 0)) > DE_LOOT_OPEN_TIMEOUT_SEC
	end
	return (now - (s.succeededAt or 0)) > DE_LOOT_WINDOW_SEC
end

local function commitDELootSession()
	local s = deCapture.lootSession
	deCapture.lootSession = nil
	if not s or s.committed then return false end
	s.committed = true
	local now = (GetTime and GetTime()) or 0
	if isDELootSessionExpired(s, now) then
		return false
	end
	local mats = (next(s.openMats) ~= nil) and s.openMats or s.chatMats
	if type(mats) ~= "table" or next(mats) == nil then
		return false
	end
	if not s.srcID or s.srcID <= 0 or not ns.RecordDEObservation then
		return false
	end
	local asActive = ns.IsArcaneSalvagerActive and ns.IsArcaneSalvagerActive(s.arcaneSalvager)
		or (s.arcaneSalvager == true)
	local ok = ns.RecordDEObservation(s.srcID, mats, {
		itemLink = s.srcLink,
		arcaneSalvager = asActive,
		source = s.source or "manual",
	})
	if ok then
		if app.disenchantCrafterProvider and app.disenchantCrafterProvider.Invalidate then
			app.disenchantCrafterProvider.Invalidate("de_obs")
		end
		if app.activeTab == "disenchant_crafter" and app.scheduleRecipeRefresh then
			app.scheduleRecipeRefresh("de_obs")
		end
		if ns.DeepAnalysis and ns.DeepAnalysis.Refresh and app.ui and app.ui.deepAnalysisFrame and app.ui.deepAnalysisFrame:IsShown() then
			pcall(ns.DeepAnalysis.Refresh)
		end
	end
	return ok == true
end

deCapture.isDisenchantSpellID = isDisenchantSpellID
deCapture.resolveDisenchantTarget = resolveDisenchantTarget
deCapture.clearState = clearDELiveCaptureState
deCapture.isLootSessionExpired = isDELootSessionExpired
deCapture.isSelfLootChatMessage = isSelfDELootChatMessage
deCapture.commitLootSession = commitDELootSession
end)()

events:SetScript("OnEvent", function(_, event, arg1, arg2, arg3, arg4)
	if ns.MarketScan.HandleEvent(event, arg1, arg2) then return end
	if event == "ADDON_LOADED" then
		if arg1 == ADDON then
			MerchantMasterDB = MerchantMasterDB or {}
			-- Migrate previous WaylaidCratesDB data once if present
			if not MerchantMasterDB.migratedFromWaylaid and type(_G.WaylaidCratesDB) == "table" then
				local old = _G.WaylaidCratesDB
				MerchantMasterDB.chars = MerchantMasterDB.chars or old.chars
				MerchantMasterDB.costs = MerchantMasterDB.costs or old.costs
				MerchantMasterDB.ahPrices = MerchantMasterDB.ahPrices or old.ahPrices
