	elseif event == "PLAYER_LOGIN" then
		app.ensureDEContainerHooks()
		local loginT0 = (ns._consolePerfOn == true and _G.debugprofilestop) and _G.debugprofilestop() or nil
		app.bindRecipeStatsInvalidation()
		if ns.TrainerStats then ns.TrainerStats.Initialize(app.getRecipeStatsContext) end
		local realm = GetRealmName and GetRealmName() or "Forever"
		local player, firstName = getForeverPlayerName()
		local playerGuid = (_G.UnitGUID and _G.UnitGUID("player")) or nil
		local playerFaction = UnitFactionGroup and UnitFactionGroup("player") or "Horde"
		local activeEcon = ns.DetectActiveEconomy()
		local newKey = activeEcon .. "-" .. realm .. "-" .. player
		local prevCharKey = app.charKey
		app.charKey = newKey
		app.char = MerchantMasterDB.chars[app.charKey] or ((prevCharKey == nil) and app.char or { mail = {}, bought = {}, bank = {}, bags = {} })
		MerchantMasterDB.chars[app.charKey] = app.char
		app.char.name = player
		app.char.firstName = firstName
		app.char.guid = playerGuid
		app.char.realm = realm
		app.char.faction = playerFaction
		app.char.economy = activeEcon
		if ns.Analytics and ns.Analytics.Store and ns.Analytics.Store.MigrateForeverSurnames then
			if ns.Analytics.Store.Init and not ns.Analytics.Store.initialized then ns.Analytics.Store.Init() end
			ns.Analytics.Store.MigrateForeverSurnames(MerchantMasterDB and MerchantMasterDB.chars, app.charKey)
		end
		purgeStaleSingleWordSelfChars(activeEcon, realm, playerFaction, player, firstName, playerGuid, newKey)
		app.char.knownSpells = app.char.knownSpells or {}
		app.char.knownOutputs = app.char.knownOutputs or {}
		app.char.knownNames = app.char.knownNames or {}
		app.char.scannedProfs = app.char.scannedProfs or {}
		app.char.cooldowns = app.char.cooldowns or {}
		app.char.cooldownGroups = app.char.cooldownGroups or {}
		app.char.writCooldowns = app.char.writCooldowns or {}
		-- Purge legacy phantom AH-purchase cache (real bags/bank/mail snapshots are authoritative).
		for _, c in pairs(MerchantMasterDB.chars or {}) do
			if type(c) == "table" and type(c.bought) == "table" and next(c.bought) ~= nil then
				c.bought = {}
			end
		end
		app.bagsDirty = true
		app.bagCountsDirty = true
		app.char.bags = bagCounts()
		scanGear()
		ns.activeChar = app.char
		syncActiveCharProfs()
		sanitizeKnownRecipes(app.char)
		scanTradeSkillWindow()
		if app.ensureMerchantFrameHooked then app.ensureMerchantFrameHooked() end
		if app.orderFlow and app.orderFlow.RestoreState then
			app.orderFlow.RestoreState()
		end
		if app.ui and app.ui._updateTopTaskListBadge then
			app.ui._updateTopTaskListBadge()
		end
		if app.scanPlayerCooldowns then app.scanPlayerCooldowns() end
		if ns.EnsureSnapshotsLoaded then ns.EnsureSnapshotsLoaded() end
		if app.mapPinsProvider and type(app.mapPinsProvider.Init) == "function" then
			app.mapPinsProvider.Init(_G.MerchantMasterAPI.GetMapPinsHostContext())
		elseif ns.MapPins and type(ns.MapPins.Init) == "function" then
			ns.MapPins.Init(_G.MerchantMasterAPI.GetMapPinsHostContext())
		end
		MerchantMasterDB.costs[activeEcon] = MerchantMasterDB.costs[activeEcon] or {}
		app.costs = MerchantMasterDB.costs[activeEcon]
		MerchantMasterDB.ahPrices[activeEcon] = MerchantMasterDB.ahPrices[activeEcon] or {}
		app.ahPrices = MerchantMasterDB.ahPrices[activeEcon]
		MerchantMasterDB.ahLots[activeEcon] = MerchantMasterDB.ahLots[activeEcon] or {}
		ns.ahPrices = app.ahPrices
		registerMinimap()
		C_Timer.After(2.0, function()
			if panel:IsShown() then app.refresh() end
			if app.warmSuperListCache and not (panel:IsShown() and app.activeTab == "recipes") then
				app.warmSuperListCache(0.25)
			end
		end)
		if loginT0 and ns.ConsoleEngine and ns.ConsoleEngine.RecordBootPhase then
			ns.ConsoleEngine.RecordBootPhase("PLAYER_LOGIN", _G.debugprofilestop() - loginT0)
		end
	elseif event == "GET_ITEM_INFO_RECEIVED" then
		local wasPending = arg1 and ns.pendingItemLoads and ns.pendingItemLoads[arg1] or false
		if wasPending then
			ns.pendingItemLoads[arg1] = nil
		end
		local isCatalogItem = arg1 and ns.ALL_CATALOG_IDS and ns.ALL_CATALOG_IDS[arg1] or false
		if arg2 == true and (wasPending or isCatalogItem) then
			local liveSell, vendorChanged = nil, false
			if ns.SyncLiveVendorSell then
				liveSell, vendorChanged = ns.SyncLiveVendorSell(arg1)
			end
			if app.uiPriceBank and app.uiPriceBank.vendorSell then
				local cachedV = app.uiPriceBank.vendorSell[arg1]
				if cachedV ~= nil and cachedV ~= liveSell then
					app.uiPriceBank.vendorSell[arg1] = nil
					vendorChanged = true
				end
			end
			if wasPending or vendorChanged then
				if app.singleCraftShoppingPreview then app._singleCraftPreviewDirty = true end
				app.loadedItemBatch = app.loadedItemBatch or {}
				app.loadedItemBatch[arg1] = true
				if vendorChanged then app.loadedItemVendorChanged = true end
				if not app.loadedItemBatchPending then
					app.loadedItemBatchPending = true
					C_Timer.After(1, function()
						local items = app.loadedItemBatch
						local vChanged = app.loadedItemVendorChanged
						app.loadedItemBatch = {}
						app.loadedItemBatchPending = nil
						app.loadedItemVendorChanged = nil
						if vChanged then
							if app.uiPriceBank and app.uiPriceBank.vendorSell then
								wipe(app.uiPriceBank.vendorSell)
							end
							if ns.MP and ns.MP.InvalidateSolveCache then
								ns.MP.InvalidateSolveCache()
							end
						end
						app.invalidateRecipeStats("items", items)
						if panel:IsShown() and app.activeTab ~= "recipes" and app.activeTab ~= "all_items" and app.activeTab ~= "vendor_crafter" and app.activeTab ~= "disenchant_crafter" then
							scheduleItemInfoRefresh()
						elseif app.ui.shopModal and app.ui.shopModal:IsShown() then
							app.refreshUnifiedShoppingDisplay()
						end
					end)
				end
			end
		end
	elseif event == "TRADE_SKILL_SHOW" or event == "TRADE_SKILL_UPDATE" or event == "TRADE_SKILL_LIST_UPDATE" or event == "TRADE_SKILL_DATA_SOURCE_CHANGED" or event == "NEW_RECIPE_LEARNED" or event == "CRAFT_SHOW" or event == "CRAFT_UPDATE" then
		if event == "TRADE_SKILL_DATA_SOURCE_CHANGED" then
			app._tsSessionScanned = false
		end
		if app.orderFlow then
			if event == "TRADE_SKILL_SHOW" and app.orderFlow.OnTradeSkillShow then
				app.orderFlow.OnTradeSkillShow()
				syncOrderFlowDockAndRender()
			elseif event == "CRAFT_SHOW" and app.orderFlow.OnCraftShow then
				app.orderFlow.OnCraftShow()
				syncOrderFlowDockAndRender()
			elseif isOrderFlowVisible() and (event == "TRADE_SKILL_UPDATE" or event == "TRADE_SKILL_LIST_UPDATE" or event == "TRADE_SKILL_DATA_SOURCE_CHANGED" or event == "CRAFT_UPDATE") and app.orderFlow.OnTradeSkillUpdate then
				app.orderFlow.OnTradeSkillUpdate()
			end
		end
		local isUpdateTick = (event == "TRADE_SKILL_UPDATE" or event == "TRADE_SKILL_LIST_UPDATE" or event == "CRAFT_UPDATE")
		local now = GetTime and GetTime() or 0
		if isUpdateTick then
			if isPlayerCasting() then return end
			if app._tsSessionScanned == true then return end
			if now > 0 and (now - (app._lastCraftEventTime or 0)) < 2.5 then return end
			if now > 0 and (now - (app._lastTradeSkillScanTime or 0)) < 3.0 then return end
		end
		if event == "NEW_RECIPE_LEARNED" then
			for _, rec in ipairs(ns.RECIPES or {}) do rec._reagentsChecked = nil end
		end
		app._lastTradeSkillScanTime = now
		local changed = scanTradeSkillWindow()
		if hasOpenTradeSkillRecipes() then
			app._tsSessionScanned = true
		end
		if changed or not isUpdateTick then
			if app.scanPlayerCooldowns then app.scanPlayerCooldowns() end
			scheduleRefresh("professor")
		end
	elseif event == "TRADE_SKILL_CLOSE" or event == "CRAFT_CLOSE" then
		app._tsSessionScanned = false
		if app.orderFlow and app.orderFlow.OnTradeSkillClosed then
			app.orderFlow.OnTradeSkillClosed()
			syncOrderFlowDockAndRender()
		end
	elseif event == "SKILL_LINES_CHANGED" then
		if ns.ResetEval then ns.ResetEval() end
		local sanitized = sanitizeKnownRecipes(app.char)
		local liveProfs = ns.GetLivePlayerProfessions and ns.GetLivePlayerProfessions() or nil
		local profMap = (liveProfs and next(liveProfs) ~= nil) and liveProfs
			or (ns.GetPlayerProfessions and ns.GetPlayerProfessions()) or {}
		local prev = app._lastSkillEventProfs or app._lastPlayerProfMap
		local keysChanged = (prev == nil and next(profMap) ~= nil)
			or (prev ~= nil and not sameProfKeys(prev, profMap))
		local ranksChanged = keysChanged or (prev ~= nil and not sameCounts(prev, profMap)) or sanitized
		if ranksChanged then
			app._lastPlayerProfMap = profMap
			app._lastSkillEventProfs = profMap
			syncActiveCharProfs()
			if ns.ResetEval then ns.ResetEval() end
			local invReason = keysChanged and "professions" or "skills"
			app.invalidateRecipeStats(invReason)
			if not app.recipeInvalidationBound then
				if app.superListProvider and app.superListProvider.Invalidate then
					app.superListProvider.Invalidate(invReason)
				end
				if app.vendorCrafterProvider and app.vendorCrafterProvider.Invalidate then
					app.vendorCrafterProvider.Invalidate(invReason)
				end
				if app.disenchantCrafterProvider and app.disenchantCrafterProvider.Invalidate then
					app.disenchantCrafterProvider.Invalidate(invReason)
				end
				if app.allItemsProvider and app.allItemsProvider.Invalidate then
					app.allItemsProvider.Invalidate(invReason)
				end
			end
			if keysChanged and app.warmSuperListCache and not (panel and panel:IsShown() and app.activeTab == "recipes") then
				app.warmSuperListCache(0.05)
			end
			scheduleRefresh("skills")
		end
	elseif event == "TRAIT_CONFIG_UPDATED" or event == "ACTIVE_TALENT_GROUP_CHANGED" then
		if ns.InvalidateVendorDiscountCache then ns.InvalidateVendorDiscountCache() end
		if ns.InvalidatePriceCache then ns.InvalidatePriceCache() end
		app.invalidateRecipeStats("prices")
		scheduleRefresh("prices")
	elseif event == "UPDATE_FACTION" or event == "CURRENCY_DISPLAY_UPDATE" then
		if event == "UPDATE_FACTION" then
			if ns.ResetEval then ns.ResetEval() end
			local rep = ns.GetMerchantReputation and ns.GetMerchantReputation()
			local function readable(v)
				return not ((_G.issecretvalue and _G.issecretvalue(v)) or (type(v) == "table" and _G.issecrettable and _G.issecrettable(v)))
			end
			if not readable(rep) or type(rep) ~= "table" or not readable(rep.standing) or not readable(rep.barValue) or not readable(rep.hasData) or not readable(rep.factionsDigest) then return end
			local prior = app._lastMerchantRepSig
			if prior and prior.standing == rep.standing and prior.barValue == rep.barValue and prior.hasData == rep.hasData and prior.factionsDigest == rep.factionsDigest then return end
			app._lastMerchantRepSig = { standing = rep.standing, barValue = rep.barValue, hasData = rep.hasData, factionsDigest = rep.factionsDigest }
			app.invalidateRecipeStats("rep")
			if not app.recipeInvalidationBound then
				if ns.SuperList and ns.SuperList.Invalidate then ns.SuperList.Invalidate("rep") end
				if app.vendorCrafterProvider and app.vendorCrafterProvider.Invalidate then app.vendorCrafterProvider.Invalidate("rep") end
				if app.disenchantCrafterProvider and app.disenchantCrafterProvider.Invalidate then app.disenchantCrafterProvider.Invalidate("rep") end
				if app.allItemsProvider and app.allItemsProvider.Invalidate then app.allItemsProvider.Invalidate("rep") end
			end
		end
		scheduleRefresh()
	elseif event == "MAIL_SHOW" then
        app.mailboxSession=(app.mailboxSession or 0)+1; app.mailboxScanPending=nil
        app.atMailbox=true; app.QueueMailboxScan("open")
		if app.orderFlow and app.orderFlow.OnMailShow then
			app.orderFlow.OnMailShow()
			syncOrderFlowDockAndRender()
		end
    elseif event == "MAIL_CLOSED" then
        local pending = app.mailboxScanPending
        if app.atMailbox and pending and pending.inboxReady then
            local capture = ns.Analytics and ns.Analytics.Capture
            local snapshot = capture and capture.ScanMailboxSnapshot and capture.ScanMailboxSnapshot(true)
            if type(snapshot) ~= "table" then
                snapshot = readMailboxOwnership(true)
            end
            if snapshot then
                app.CommitMailboxSnapshot(snapshot)
            end
        end
        app.atMailbox=false; app.mailboxSession=(app.mailboxSession or 0)+1; app.mailboxScanPending=nil
		if app.orderFlow and app.orderFlow.OnMailClosed then
			app.orderFlow.OnMailClosed()
			syncOrderFlowDockAndRender()
		end
    elseif event == "CLOSE_INBOX_ITEM" then
        if not (app.mailboxScanPending and app.mailboxScanPending.actionPending) then app.QueueMailboxScan("take") end
    elseif event == "MAIL_INBOX_UPDATE" then
        -- Only an outstanding open/action request can consume this readiness signal.
        if app.mailboxScanPending then
            app.mailboxScanPending.inboxReady=true; app.mailboxScanPending.attempt=0
            app.mailboxScanPending.schedule()
        end
		if app.orderFlow and isOrderFlowVisible() and app.orderFlow.OnMailInboxUpdate then
			app.orderFlow.OnMailInboxUpdate()
			syncOrderFlowDockAndRender()
		end
	elseif event == "BANKFRAME_OPENED" then
		app.atBank = true
		app.bagsDirty = true
		app.bagCountsDirty = true
		scanBank()
		local counts = app.charKey and bagCounts()
		if counts then app.char.bags = counts end
		app.invalidateRecipeStats("ownership")
		scheduleRefresh()
		if app.orderFlow and app.orderFlow.OnBankShow then
			app.orderFlow.OnBankShow()
			syncOrderFlowDockAndRender()
		end
	elseif event == "BANKFRAME_CLOSED" then
		local flushed = false
		if app.atBank then
			if scanBank() then flushed = true end
		end
		app.bagsDirty = true
		app.bagCountsDirty = true
		local counts = app.charKey and bagCounts()
		if counts and not sameCounts(app.char.bags, counts) then
			app.char.bags = counts
			app._lastBagCountsByID = copyCountsTable(app.cachedBagCountsByID or {})
			flushed = true
		end
		app.atBank = false
		if flushed then
			app.invalidateRecipeStats("ownership")
			if ns.MapPins and ns.MapPins.InvalidateOwnership then ns.MapPins.InvalidateOwnership() end
			scheduleRefresh("bags")
		end
		if app.orderFlow and app.orderFlow.OnBankClosed then
			app.orderFlow.OnBankClosed()
			syncOrderFlowDockAndRender()
		end
	elseif event == "PLAYERBANKSLOTS_CHANGED" then
		if app.atBank then
			app.bagsDirty = true
			app.bagCountsDirty = true
			scanBank()
			local counts = app.charKey and bagCounts()
			if counts then app.char.bags = counts end
			app.invalidateRecipeStats("ownership")
			scheduleRefresh()
		end
		if app.orderFlow and isOrderFlowVisible() and app.orderFlow.OnBankSlotsChanged then
			app.orderFlow.OnBankSlotsChanged()
			syncOrderFlowDockAndRender()
		end
	elseif event == "MERCHANT_SHOW" or event == "MERCHANT_UPDATE" then
		handleOrderFlowMerchantOpen(event == "MERCHANT_SHOW")
	elseif event == "MERCHANT_CLOSED" then
		if app.orderFlow and app.orderFlow.OnMerchantClosed then
			app.orderFlow.OnMerchantClosed()
			syncOrderFlowDockAndRender()
		end
	elseif event == "AUCTION_HOUSE_SHOW" then
		if ns.EnsureSnapshotsLoaded then ns.EnsureSnapshotsLoaded() end
		C_Timer.After(0, function()
			if winChrome and winChrome.ahRefresh then winChrome.ahRefresh:Update() end
		end)
		if app.ensureCartBuyerBidHook then app.ensureCartBuyerBidHook() end
		C_Timer.After(0, function()
			ns.MarketScan.HookBuyFrame()
			addAHSearchBarButton()
			if ns.AHSellTab and ns.AHSellTab.EnsureAttached then ns.AHSellTab.EnsureAttached() end
			if app._ahBuyingMode and app.ui.cartBuyerModal and app.ui.cartBuyerModal:IsShown() then
				if panel and panel:IsShown() then panel:Hide() end
				if app.dockCartBuyerModal then app.dockCartBuyerModal() end
				if app.cartBuyer and app.cartBuyer.OnAuctionHouseShow then
					app.cartBuyer.OnAuctionHouseShow()
				end
				if app.ui.cartBuyerModal.Render then app.ui.cartBuyerModal.Render() end
				return
			end
			local wasShown = panel:IsShown()
			if (not isAutoOpenAtAHDisabled()) or wasShown then
				if not wasShown then app.openedByAH = true end
				anchorPanel()
				if wasShown then
					app.refresh()
				else
					panel:Show()
				end
			end
		end)
	elseif event == "QUEST_TURNED_IN" then
		if (_G.issecretvalue and _G.issecretvalue(arg1)) or (type(arg1) == "table" and _G.issecrettable and _G.issecrettable(arg1)) then return end
		if type(arg1) ~= "number" and type(arg1) ~= "string" then return end
		local qid = tonumber(arg1)
		if not qid or qid <= 0 then return end
		if not writByQuestID then
			writByQuestID = {}
			for _, writ in ipairs(ns.WRITS or {}) do
				if type(writ) == "table" and not (_G.issecrettable and _G.issecrettable(writ))
					and not (_G.issecretvalue and _G.issecretvalue(writ.questID)) and tonumber(writ.questID) then
					writByQuestID[tonumber(writ.questID)] = true
				end
			end
		end
		if writByQuestID[qid] and ns.RecordWritTurnInCooldown and ns.RecordWritTurnInCooldown(qid) and panel:IsShown() then
			scheduleRefresh()
		end
	elseif event == "AUCTION_HOUSE_CLOSED" then
		app.cancelMarketScan(true)
		app.cancelOrderBookScan()
		if ns.AHSellTab and ns.AHSellTab.OnAuctionHouseClosed then ns.AHSellTab.OnAuctionHouseClosed() end
		if app._ahBuyingMode and app.ui.cartBuyerModal and app.ui.cartBuyerModal:IsShown() then
			if app.dockCartBuyerModal then app.dockCartBuyerModal() end
			if app.ui.cartBuyerModal.Render then app.ui.cartBuyerModal.Render() end
		end
		if app.openedByAH and not MerchantMasterDB.keepOpenAfterAH then
			panel:Hide()
		elseif panel:IsShown() then
			anchorPanel()
			app.refresh()
		end
	elseif event == "PLAYER_REGEN_DISABLED" then
		if ns.AHSellTab and ns.AHSellTab.SyncSpaceBinding then ns.AHSellTab.SyncSpaceBinding(true) end
	elseif event == "PLAYER_REGEN_ENABLED" then
		if ns.AHSellTab and ns.AHSellTab.IsSpacePendingSync and ns.AHSellTab.IsSpacePendingSync() then
			ns.AHSellTab.SyncSpaceBinding()
		end
	elseif event == "COMMODITY_PURCHASE_SUCCEEDED" then
		app.bagsDirty = true
		app.bagCountsDirty = true
		app.purchase = nil
		app.invalidateRecipeStats("ownership")
		scheduleRefresh()
	elseif event == "COMMODITY_PURCHASE_FAILED" then
		app.purchase = nil
	elseif event == "COMMODITY_PRICE_UPDATED" or event == "COMMODITY_PRICE_UNAVAILABLE" then
		if ns.SniperEngine and ns.SniperEngine.HandleEvent then
			ns.SniperEngine.HandleEvent(event, arg1, arg2)
		end
	elseif event == "AUCTION_HOUSE_PURCHASE_COMPLETED" then
		app.bagsDirty = true
		app.bagCountsDirty = true
		app.invalidateRecipeStats("ownership")
		if ns.SniperEngine and ns.SniperEngine.HandleEvent then
			ns.SniperEngine.HandleEvent(event, arg1, arg2)
		end
		scheduleRefresh()
	elseif event == "PLAYER_EQUIPMENT_CHANGED" then
		scanGear()
		scheduleRefresh()
	elseif event == "PLAYER_ENTERING_WORLD" then
		if app.scanPlayerCooldowns then app.scanPlayerCooldowns() end
		scheduleBagResync()
		if C_Timer and C_Timer.After then
			C_Timer.After(1.0, function() flushBagResync(false) end)
		end
	elseif event == "PLAYER_LOGOUT" then
		if app.orderFlow and app.orderFlow.SaveState then
			app.orderFlow.SaveState()
		end
		if ns.MarketScan and ns.MarketScan.PackHistoryForSave then
			ns.MarketScan.PackHistoryForSave(MerchantMasterDB)
		end
	elseif event == "SPELL_UPDATE_COOLDOWN" then
		if panel:IsShown() and app.scanPlayerCooldowns then
			app._cdScanSeq = (app._cdScanSeq or 0) + 1
			local seq = app._cdScanSeq
			C_Timer.After(0.25, function()
				if app._cdScanSeq == seq and panel:IsShown() then
					app.scanPlayerCooldowns()
				end
			end)
		end
	elseif event == "UNIT_SPELLCAST_SENT" then
		if _G.issecretvalue and (_G.issecretvalue(arg1) or _G.issecretvalue(arg2) or _G.issecretvalue(arg3) or _G.issecretvalue(arg4)) then return end
		if arg1 == "player" then
			local spID = (type(arg4) == "number" and arg4) or (type(arg3) == "number" and arg3) or nil
			if deCapture.isDisenchantSpellID(spID) then
				app.ensureDEContainerHooks()
				local srcID, srcLink, srcSource, asOn = deCapture.resolveDisenchantTarget(arg2)
				deCapture.pendingCast = {
					castGUID = arg3,
					spellID = spID,
					targetName = arg2,
					srcID = srcID,
					srcLink = srcLink,
					source = srcSource,
					arcaneSalvager = asOn,
					startedAt = GetTime and GetTime() or 0,
				}
			else
				deCapture.clearState(true)
			end
		end
	elseif event == "UNIT_SPELLCAST_START" then
		if _G.issecretvalue and (_G.issecretvalue(arg1) or _G.issecretvalue(arg3)) then return end
		if arg1 == "player" and type(arg3) == "number" and arg3 > 0 then
			app._lastCraftEventTime = GetTime and GetTime() or 0
			if not deCapture.isDisenchantSpellID(arg3) then
				deCapture.clearState(true)
			end
			if app.orderFlow and app.orderFlow.OnSpellcastStart and (isOrderFlowVisible() or hasPendingCraftTasks()) then
				app.orderFlow.OnSpellcastStart(arg1, arg3, arg2)
			end
		end
	elseif event == "UNIT_SPELLCAST_STOP" or event == "UNIT_SPELLCAST_INTERRUPTED" or event == "UNIT_SPELLCAST_FAILED" then
		if _G.issecretvalue and (_G.issecretvalue(arg1) or _G.issecretvalue(arg3)) then return end
		if arg1 == "player" then
			if event ~= "UNIT_SPELLCAST_STOP" then
				local spID = type(arg3) == "number" and arg3 or nil
				local pend = deCapture.pendingCast
				if event == "UNIT_SPELLCAST_FAILED" and pend and pend.castGUID ~= nil and arg2 ~= nil and pend.castGUID ~= arg2 then
					-- Rejected spam-click mid-cast carries a distinct castGUID; keep active DE capture intact
				elseif deCapture.isDisenchantSpellID(spID)
					or (pend and arg2 ~= nil and pend.castGUID == arg2)
					or (spID and not deCapture.isDisenchantSpellID(spID)) then
					deCapture.clearState(true)
				else
					deCapture.lastBagTarget = nil
				end
			end
			if app.orderFlow and app.orderFlow.OnSpellcastStop and (isOrderFlowVisible() or hasPendingCraftTasks()) then
				app.orderFlow.OnSpellcastStop(arg1, type(arg3) == "number" and arg3 or nil, event ~= "UNIT_SPELLCAST_STOP")
			end
		end
	elseif event == "UNIT_SPELLCAST_SUCCEEDED" then
		if _G.issecretvalue and (_G.issecretvalue(arg1) or _G.issecretvalue(arg3)) then return end
		if arg1 == "player" and type(arg3) == "number" and arg3 > 0 then
			app._lastCraftEventTime = GetTime and GetTime() or 0
			local spID = arg3
			if deCapture.isDisenchantSpellID(spID) then
				if deCapture.lootSession and not deCapture.lootSession.committed then
					deCapture.commitLootSession()
				end
				local pend = deCapture.pendingCast
				deCapture.pendingCast = nil
				local srcID, srcLink, srcSource, asOn
				if pend and (pend.castGUID == nil or arg2 == nil or pend.castGUID == arg2) and pend.srcID then
					srcID, srcLink, srcSource, asOn = pend.srcID, pend.srcLink, pend.source, pend.arcaneSalvager
				else
					srcID, srcLink, srcSource, asOn = deCapture.resolveDisenchantTarget(pend and pend.targetName)
				end
				deCapture.lastBagTarget = nil
				deCapture.lootSession = {
					srcID = srcID,
					srcLink = srcLink,
					source = srcSource or "manual",
					arcaneSalvager = asOn,
					succeededAt = GetTime and GetTime() or 0,
					lootOpened = false,
					openedAt = nil,
					openMats = {},
					chatMats = {},
					committed = false,
				}
			else
				deCapture.clearState(true)
			end
			if app.orderFlow and app.orderFlow.OnSpellcastSucceeded and (isOrderFlowVisible() or hasPendingCraftTasks()) then
				app.orderFlow.OnSpellcastSucceeded(arg1, spID)
			end
			local cdList, bySpell = getCooldownCatalog()
			local rec = bySpell[spID]
			if rec then
				app.char.cooldowns = app.char.cooldowns or {}
				app.char.cooldownGroups = app.char.cooldownGroups or {}
				local exp = (time and time() or 0) + (tonumber(rec.cd) or 60)
				app.char.cooldowns[spID] = exp
				local grp = ns.GetRecipeCooldownGroup and ns.GetRecipeCooldownGroup(rec)
				if grp then
					if grp == "alchemy_transmute" and ns.RebuildSharedTransmuteCooldownGroup then
						ns.RebuildSharedTransmuteCooldownGroup(app.char, time and time() or 0)
					else
						app.char.cooldownGroups[grp] = math.max(tonumber(app.char.cooldownGroups[grp]) or 0, exp)
					end
				end
				local changedSpells = { [spID] = true }
				if grp and ns.GetRecipeCooldownGroup then
					for _, r in ipairs(cdList) do
						if r.spellID and ns.GetRecipeCooldownGroup(r) == grp then
							changedSpells[r.spellID] = true
						end
					end
				end
				if app.invalidateRecipeStats then
					app.invalidateRecipeStats("cooldown", changedSpells)
				end
				if not app.recipeInvalidationBound then
					if ns.SuperList and ns.SuperList.Invalidate then
						ns.SuperList.Invalidate("cooldown", changedSpells)
					end
					if ns.RecipeStats and app.vendorCrafterProvider and app.vendorCrafterProvider.Invalidate then
						app.vendorCrafterProvider.Invalidate("cooldown", changedSpells)
					end
					if ns.RecipeStats and app.disenchantCrafterProvider and app.disenchantCrafterProvider.Invalidate then
						app.disenchantCrafterProvider.Invalidate("cooldown", changedSpells)
					end
					if ns.RecipeStats and app.allItemsProvider and app.allItemsProvider.Invalidate then
						app.allItemsProvider.Invalidate("cooldown", changedSpells)
					end
				end
				if C_Timer and C_Timer.After then
					C_Timer.After(0.25, function()
						if app.scanPlayerCooldowns then app.scanPlayerCooldowns() end
					end)
				elseif app.scanPlayerCooldowns then
					app.scanPlayerCooldowns()
				end
			end
		end
	elseif event == "PLAYER_INTERACTION_MANAGER_FRAME_SHOW" or event == "PLAYER_INTERACTION_MANAGER_FRAME_HIDE" then
		if _G.issecretvalue and _G.issecretvalue(arg1) then return end
		local pType = tonumber(arg1)
		local pit = _G.Enum and _G.Enum.PlayerInteractionType
		local isShow = (event == "PLAYER_INTERACTION_MANAGER_FRAME_SHOW")
		if pType and pit then
			if pType == pit.Merchant then
				if isShow then
					handleOrderFlowMerchantOpen(true)
				elseif app.orderFlow and app.orderFlow.OnMerchantClosed then
					app.orderFlow.OnMerchantClosed()
					syncOrderFlowDockAndRender()
				end
			elseif pType == pit.Banker or pType == pit.CharacterBanker then
				if isShow then
					app.atBank = true
					app.bagsDirty = true
					app.bagCountsDirty = true
					scanBank()
					local counts = app.charKey and bagCounts()
					if counts then app.char.bags = counts end
					app.invalidateRecipeStats("ownership")
					scheduleRefresh()
					if app.orderFlow and app.orderFlow.OnBankShow then
						app.orderFlow.OnBankShow()
						syncOrderFlowDockAndRender()
					end
				else
					local flushed = false
					if app.atBank then
						if scanBank() then flushed = true end
					end
					app.bagsDirty = true
					app.bagCountsDirty = true
					local counts = app.charKey and bagCounts()
					if counts and not sameCounts(app.char.bags, counts) then
						app.char.bags = counts
						app._lastBagCountsByID = copyCountsTable(app.cachedBagCountsByID or {})
						flushed = true
					end
					app.atBank = false
					if flushed then
						app.invalidateRecipeStats("ownership")
						if ns.MapPins and ns.MapPins.InvalidateOwnership then ns.MapPins.InvalidateOwnership() end
						scheduleRefresh("bags")
					end
					if app.orderFlow and app.orderFlow.OnBankClosed then
						app.orderFlow.OnBankClosed()
						syncOrderFlowDockAndRender()
					end
				end
			elseif pType == pit.MailInfo then
				if app.orderFlow then
					if isShow and app.orderFlow.OnMailShow then
						app.orderFlow.OnMailShow()
						syncOrderFlowDockAndRender()
					elseif (not isShow) and app.orderFlow.OnMailClosed then
						app.orderFlow.OnMailClosed()
						syncOrderFlowDockAndRender()
					end
				end
			end
		end
	elseif event == "LOOT_OPENED" then
		local s = deCapture.lootSession
		local now = GetTime and GetTime() or 0
		if s and not s.committed then
			if deCapture.isLootSessionExpired(s, now) then
				deCapture.lootSession = nil
			elseif _G.GetNumLootItems then
				local nLoot = tonumber(_G.GetNumLootItems()) or 0
				local openMats = {}
				for i = 1, nLoot do
					local link = _G.GetLootSlotLink and _G.GetLootSlotLink(i) or nil
					local matID = (not isSecretVal(link) and type(link) == "string") and tonumber(link:match("item:(%d+)")) or nil
					if matID and ns.IsDisenchantMaterial and ns.IsDisenchantMaterial(matID) then
						local qty = 1
						if _G.GetLootSlotInfo then
							local _, _, lQty = _G.GetLootSlotInfo(i)
							if not isSecretVal(lQty) and tonumber(lQty) and tonumber(lQty) > 0 then
								qty = math.floor(tonumber(lQty))
							end
						end
						openMats[matID] = (openMats[matID] or 0) + qty
					end
				end
				if next(openMats) ~= nil then
					s.openMats = openMats
					s.lootOpened = true
					s.openedAt = s.openedAt or now
				end
			end
		end
	elseif event == "CHAT_MSG_LOOT" then
		local s = deCapture.lootSession
		local now = GetTime and GetTime() or 0
		if s and not s.committed and type(arg1) == "string" and not isSecretVal(arg1) then
			if deCapture.isLootSessionExpired(s, now) then
				deCapture.lootSession = nil
			elseif next(s.openMats) == nil and deCapture.isSelfLootChatMessage(arg1) then
				local matID = tonumber(arg1:match("item:(%d+)"))
				if matID and ns.IsDisenchantMaterial and ns.IsDisenchantMaterial(matID) then
					local qty = tonumber(arg1:match("|h%[.-%]|h|r%s*x(%d+)"))
						or tonumber(arg1:match("|h%[.-%]|h%s*x(%d+)"))
						or 1
					s.chatMats[matID] = (s.chatMats[matID] or 0) + math.max(1, math.floor(qty))
				end
			end
		end
	elseif event == "LOOT_CLOSED" then
		deCapture.commitLootSession()
	elseif event == "BAG_UPDATE" then
		scheduleBagResync()
	elseif event == "BAG_UPDATE_DELAYED" then
		flushBagResync(false)
	end
end)

SLASH_MERCHANTMASTER1 = "/mm"
local UI_SKIN_ALIASES = {
	standard = "standard", apple = "standard", glass = "standard", modern = "standard", default = "goblin",
	human = "human", stormwind = "human", alliance = "human",
	night_elf = "night_elf", nightelf = "night_elf", ne = "night_elf", kaldorei = "night_elf",
	orc = "orc", orgrimmar = "orc", horde = "orc",
	undead = "undead", forsaken = "undead", ud = "undead",
	goblin = "goblin", baron = "goblin", trade = "goblin", tradebaron = "goblin", trade_baron = "goblin", bilgewater = "goblin",
}
SLASH_MERCHANTMASTER2 = "/merchantmaster"
SLASH_MERCHANTMASTER3 = "/crates"
SLASH_MERCHANTMASTER4 = "/waylaid"
SlashCmdList.MERCHANTMASTER = function(msg)
	local raw = (msg or ""):match("^%s*(.-)%s*$")
	msg = raw:lower()
	if msg == "" then
		app.togglePanel()
	elseif msg == "help" or msg == "?" then
		say("Available commands:")
		for _, entry in ipairs(app.PUBLIC_SLASH_COMMANDS or {}) do
			say("  " .. entry.cmd .. " - " .. entry.desc)
		end
	elseif msg == "minimap" then
		toggleMinimap()
	elseif msg == "resync" then
		app.resyncBags(true)
	elseif msg == "options" or msg == "config" or msg == "settings" then
		app.togglePanel("console_settings")
	elseif msg == "mail" or msg == "mailpresets" then
		app.togglePanel("console_mail")
	elseif msg == "blizzoptions" then
		openOptions()
	elseif msg == "console" or msg == "admin" or msg == "monitor" then
		app.togglePanel("console_overview")
	elseif msg == "db" or msg == "database" then
		app.togglePanel("console_database")
	elseif msg == "perf" or msg == "debug" or msg == "profiler" then
		app.togglePanel("console_perf")
	elseif msg == "setup" or msg == "snapshots" or msg == "snapshot" then
		app.togglePanel("console_setup")
	elseif msg == "ui" or msg == "appearance" then
		app.togglePanel("console_ui")
	elseif msg == "data" or msg == "maintenance" then
		app.togglePanel("console_data")
	elseif msg == "dashboard" or msg == "home" then
		app.togglePanel("dashboard")
	elseif msg == "prof" or msg == "professor" or msg == "leveling" or msg == "path" or msg == "prof_path" then
		app.togglePanel("prof_path")
	elseif msg == "profshop" or msg == "prof_shop" then
		app.togglePanel("prof_shop")
	elseif msg == "profbrowse" or msg == "prof_browse" then
		app.togglePanel("prof_browse")
	elseif msg == "analytics" or msg == "stats" then
		app.togglePanel("analytics")
	elseif msg == "ledger" or msg == "log" then
		app.togglePanel("an_ledger")
	elseif msg == "portfolio" or msg == "wealth" then
		app.togglePanel("an_portfolio")
	elseif msg == "investments" or msg == "invest" then
		app.togglePanel("an_invest")
	elseif msg == "spread" or msg == "profit_spread" or msg == "profitspread" then
		app.togglePanel("profit_spread")
	elseif msg == "outliers" or msg == "outlier" or msg == "monopoly" then
		app.togglePanel("outliers")
	elseif msg == "shop" or msg == "shopping" then
		if not panel:IsShown() then app.togglePanel() end
		app.toggleShoppingWindow()
	elseif msg:match("^area%s+") or msg:match("^zone%s+") then
		local q = raw:gsub("^[aA][rR][eE][aA]%s+", ""):gsub("^[zZ][oO][nN][eE]%s+", "")
		if MerchantMasterDB then
			if q:lower() == "all" then
				MerchantMasterDB.writZoneFilter = "all"
			elseif q:lower() == "mapped" or q:lower() == "known" then
				MerchantMasterDB.writZoneFilter = "mapped"
			elseif q:lower() == "unmapped" then
				MerchantMasterDB.writZoneFilter = "unmapped"
			else
				MerchantMasterDB.writZoneFilter = q
			end
			say("Writ Turn-In Area Filter: " .. tostring(MerchantMasterDB.writZoneFilter))
		end
		app.togglePanel("writs")
	elseif msg == "crates" or msg == "favor" or msg == "token" then
		app.togglePanel("crates")
	elseif msg == "cratemats" or msg == "crate_mats" or msg == "mats" or msg == "gather" then
		app.togglePanel("crates")
	elseif msg == "writs" or msg == "writ" then
		app.togglePanel("writs")
	elseif msg == "forged" or msg == "forgeddelivery" then
		app.togglePanel("forged")
	elseif msg == "writprofit" or msg == "writ_profit" or msg == "wprofit" then
		app.togglePanel("writs")
	elseif msg == "demand" or msg == "writdemand" or msg == "writ_demand" then
		app.togglePanel("writs")
	elseif msg == "known" or msg == "potential" then
		if MerchantMasterDB then
			local on = (msg == "known") and (not MerchantMasterDB.knownRecipesOnly) or false
			MerchantMasterDB.knownRecipesOnly = on
			MerchantMasterDB.unlockFilter = on and "known" or "all"
			if MerchantMasterDB.craftableAllChars then app.invalidateCraftableScope() end
			say(on and "Filter: Known Recipes Only (What I Can Do)." or "Filter: Full Potential (All Recipes).")
		end
		if not panel:IsShown() then app.togglePanel() else app.refresh() end
	elseif msg == "allchars" or msg == "craftableall" then
		if MerchantMasterDB then
			local nextOn = not (MerchantMasterDB.craftableAllChars == true)
			if nextOn and not MerchantMasterDB.knownRecipesOnly then
				MerchantMasterDB.knownRecipesOnly = true
				MerchantMasterDB.unlockFilter = "known"
			end
			app.setCraftableAllChars(nextOn)
			say(nextOn and "Craftable Now: All Characters in active economy." or "Craftable Now: Current Character only.")
		end
		if not panel:IsShown() then app.togglePanel() end
	elseif msg == "recipes" or msg == "recipe" then
		app.togglePanel("recipes")
	elseif msg == "items" or msg == "item" or msg == "allitems" or msg == "all_items" then
		app.togglePanel("all_items")
	elseif msg == "watchlist" or msg == "fav" or msg == "favorites" then
		app.togglePanel("watchlist")
	elseif msg == "vendor" or msg == "vc" or msg == "vendorcrafter" or msg == "vendor_crafter" then
		app.togglePanel("vendor_crafter")
	elseif msg == "decraft" or msg == "decrafter" or msg == "disenchant" or msg == "dc" then
		app.togglePanel("disenchant_crafter")
	elseif msg == "dehelper" or msg == "deh" then
		if ns.DisenchantHelper and ns.DisenchantHelper.Toggle then ns.DisenchantHelper.Toggle() end
	elseif msg == "sniper" or msg == "gap" or msg == "gapsniper" or msg == "sniper_gap" then
		app.togglePanel("sniper_gap")
	elseif msg == "vsniper" or msg == "vendorsniper" or msg == "sniper_vendor" or msg == "sniper vendor" or msg == "vsnipe" then
		app.togglePanel("sniper_vendor")
	elseif msg == "sell" or msg == "post" then
		if ns.AHSellTab and atAH() and ns.AHSellTab.SelectTab then
			ns.AHSellTab.SelectTab()
		else
			say("Open the Auction House to use the MM Sell tab.")
		end
	elseif msg == "crafting" or msg == "order" or msg == "orders" then
		app.togglePanel("recipes")
	elseif msg == "profit" then
		app.togglePanel("profit")
	elseif msg == "bis" or msg == "bestinclass" then
		if MerchantMasterDB then MerchantMasterDB.bisOnly = true end
		app.togglePanel("recipes")
	elseif msg == "rep" or msg == "reputation" or msg == "unlocks" then
		app.togglePanel("rep")
	elseif msg == "calc" or msg == "calculator" or msg == "calculators" then
		app.togglePanel("calc")
	elseif msg == "favorcalc" or msg == "calc_favor" then
		if MerchantMasterDB then MerchantMasterDB.calcMode = "favor" end
		app.togglePanel("calc_favor")
	elseif msg == "repcalc" or msg == "calc_rep" then
		if MerchantMasterDB then MerchantMasterDB.calcMode = "rep" end
		app.togglePanel("calc_rep")
	elseif msg == "bags" or msg == "bag" then
		app.togglePanel("bags")
	elseif msg:match("^econ") then
		app.cycleEconomy("LeftButton")
		say("Selected Economy: " .. ns.CurrentEconomyInfo().buttonLabel)
	elseif msg == "refresh" or msg == "scan" then
		if not panel:IsShown() then app.togglePanel() end
		app.refreshAllMarketValues()
	elseif msg == "clearah" then
		if app.clearSavedAHPrices then app.clearSavedAHPrices() end
	elseif msg == "theme" or msg == "skin" or msg:match("^theme%s") or msg:match("^skin%s") then
		local arg = msg:gsub("^%a+%s*", ""):gsub("[%s%-]+", "_")
		local T = ns.Theme
		if arg == "" then
			local names = {}
			for _, info in ipairs(T.UI_SKINS or {}) do names[#names + 1] = info.key end
			say("UI Theme: " .. T.GetSkin() .. "  (use /mm theme <" .. table.concat(names, " | ") .. ">)")
		else
			local key = UI_SKIN_ALIASES[arg] or (T.IsValidSkin(arg) and arg or nil)
			if key then
				key = app.applyUiSkin(key)
				say("UI Theme: " .. T.GetSkinInfo(key).label)
			else
				say("Unknown UI Theme '" .. arg .. "'. Valid: standard, human, night_elf, orc, undead, goblin.")
			end
		end
	elseif msg == "cratetooltips" or msg == "cratetooltip" then
		app.setCrateTooltips(not ns.IsCrateTooltipEnabled())
		say("Crate Tooltips: " .. (ns.IsCrateTooltipEnabled() and "ON" or "OFF"))
	elseif msg == "crafttooltips" or msg == "crafttooltip" then
		app.setTooltipCraftCost(not ns.IsTooltipCraftCostEnabled())
		say("Craft Cost Tooltips: " .. (ns.IsTooltipCraftCostEnabled() and "ON" or "OFF"))
	elseif msg == "detooltips" or msg == "detooltip" or msg == "detip" then
		app.setTooltipDEValue(not ns.IsTooltipDEValueEnabled())
		say("DE Value Tooltips: " .. (ns.IsTooltipDEValueEnabled() and "ON" or "OFF"))
	elseif msg == "debreakdown" or msg == "debreakdowns" then
		app.setTooltipDEBreakdown(not ns.IsTooltipDEBreakdownEnabled())
		say("DE Breakdown Tooltips: " .. (ns.IsTooltipDEBreakdownEnabled() and "ON" or "OFF"))
	else
		say("Unknown command '" .. raw .. "'. Type /mm help for available commands.")
	end
end

local function registerCrafterProvider(provider, cfg)
	if type(provider) ~= "table" then return false end
	for _, method in ipairs({ "Create", "Refresh", "Layout", "GetSidebarControls" }) do
		if type(provider[method]) ~= "function" then return false end
	end
	if app[cfg.providerKey] then return app[cfg.providerKey] == provider end
	local ctx = {}
	for k, v in pairs(superListContext) do ctx[k] = v end
	ctx.findLabel = findLabel
	ctx.isActive = function() return panel:IsShown() and app.activeTab == cfg.tabKey end
	ctx.getSort = function() return app.sortState[cfg.tabKey] end
	ctx[cfg.resetFn] = function() return app[cfg.resetFn]() end
	ctx[cfg.queueFn] = function(entries, opts) return app[cfg.queueFn](entries, opts) end
	ctx.selectRecipe = function(itemID) app[cfg.selectedKey] = itemID end
	ctx.openQuickLook = function(row, keepPinned, owner)
		return app.superListProvider and app.superListProvider.OpenQuickLook
			and app.superListProvider.OpenQuickLook(row, keepPinned, row and row.recipe, { kind = "recipe", owner = owner })
	end
	local view = provider.Create(mainArea, ctx)
	app.ui[cfg.viewKey] = view
	app.ui[cfg.tableKey], app.ui[cfg.summaryKey] = view.table, view.summary
	local seen = {}
	for _, w in ipairs(app.allDynamicSidebarControls) do seen[w] = true end
	local function addDynCtrl(w)
		if w and not seen[w] then
			seen[w] = true
			if w.Hide then w:Hide() end
			app.allDynamicSidebarControls[#app.allDynamicSidebarControls + 1] = w
		end
	end
	addDynCtrl(view.sourceButton)
	addDynCtrl(view.skillControl)
	addDynCtrl(view.resetFiltersButton)
	local okCtrls, extraCtrls = pcall(provider.GetSidebarControls)
	if okCtrls and type(extraCtrls) == "table" then
		for _, w in ipairs(extraCtrls) do addDynCtrl(w) end
	end
	app[cfg.providerKey] = provider
	if panel:IsShown() then
		applyPanelLayout()
		if app.activeTab == cfg.tabKey then app.refresh() end
	end
	return true
end

