					seen[w] = true
					w:Hide()
					app.allDynamicSidebarControls[#app.allDynamicSidebarControls + 1] = w
				end
			end
		end
		if panel:IsShown() and type(app.activeTab) == "string" and app.activeTab:sub(1, 5) == "prof_" then
			applyPanelLayout()
			app.refresh()
		end
		return true
	end,
}

-- Shared hooks for UI_Professor.lua
ns.matchProfKeyByName = matchProfKeyByName
app.sameProfKeys = sameProfKeys
app.sameCounts = sameCounts
app.registerConsole = _G.MerchantMasterAPI.RegisterConsole
